import { isCFeatureVariant, isOffByDefault } from './c-feature-variants';
import { isTestFile, isTestPath } from '../search/query-utils';
import { inBlock, isDeclarationFile, isMergedAmbientDeclaration, scanGlobalScope, type GlobalScopeScan } from './ambient-modules';
import { isMinifiedContent } from '../extraction/generated-detection';
import { getCargoWorkspaceCrateMap, parsePackageName, parseTargetPaths } from './frameworks/cargo-workspace';
import { blankRustCode, readRustScopes, rustBindingAt, rustInnerBlockAt, rustBoundsOf, rustFnAt, rustImplAt, splitRustTopLevel, type RustBinding, type RustPatternSite, type RustScopes } from './rust-scopes';
/**
 * Ceiling on how many same-named definitions a FUZZY name-match strategy will
 * score. A name defined more times than this is "ubiquitous" — a method/symbol
 * re-declared across a vendored theme or SDK (e.g. `init`/`update`/`render` on
 * every widget of a committed Metronic theme — #999). No directory-proximity or
 * receiver-word-overlap score can reliably pick THE one true target among
 * thousands, so the fuzzy strategies (matchByExactName's findBestMatch, and
 * matchMethodCall Strategy 3) decline above the ceiling instead of emitting a
 * low-confidence, almost-certainly-wrong edge. This also caps their per-ref cost
 * at O(ceiling): without it, K same-named refs each scored K candidates — the
 * O(K²) blow-up that pinned a core for 15-28 min at "Resolving refs … 94%" on a
 * repo vendoring a large JS/TS theme (#999). The PRECISE strategies are
 * unaffected: qualified-name, import-based, and class-name (Strategy 1/2)
 * resolution all still run and resolve a ubiquitous name when the context names
 * its exact target. Real repos top out near ~40 same-named methods, so a normal
 * codebase never reaches this; only bulk-vendored code does. Tune via
 * `CODEGRAPH_AMBIGUOUS_NAME_CEILING`.
 */
const DEFAULT_AMBIGUOUS_NAME_CEILING = 500;
function resolveAmbiguousNameCeiling(): number {
  const raw = process.env.CODEGRAPH_AMBIGUOUS_NAME_CEILING;
  if (!raw) return DEFAULT_AMBIGUOUS_NAME_CEILING;
  const parsed = Number.parseInt(raw, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_AMBIGUOUS_NAME_CEILING;
}
const AMBIGUOUS_NAME_CEILING = resolveAmbiguousNameCeiling();

/**
 * Try to resolve a path-like reference (e.g., "snippets/drawer-menu.liquid")
 * by matching the filename against file nodes.
 */
export function matchByFilePath(
  ref: UnresolvedRef,
  context: ResolutionContext
): ResolvedRef | null {
  // Path-like (`a/b.liquid`) OR a bare filename ending in a short extension
  // (`Foo.h` — an Objective-C `#import "Foo.h"`, resolved to the header by
  // basename). A bare ref WITHOUT an extension is a symbol name, not a file, so
  // leave it to the symbol-matching strategies.
  if (!ref.referenceName.includes('/') && !/\.[A-Za-z][A-Za-z0-9]{0,3}$/.test(ref.referenceName)) {
    return null;
  }

  // Extract the filename from the path
  const fileName = ref.referenceName.split('/').pop();
  if (!fileName) return null;

  // Search for file nodes with this name
  const candidates = context.getNodesByName(fileName);
  const fileNodes = candidates.filter(n => n.kind === 'file');

  if (fileNodes.length === 0) return null;

  // Prefer exact path match on qualified_name
  const exactMatch = fileNodes.find(n => n.qualifiedName === ref.referenceName || n.filePath === ref.referenceName);
  if (exactMatch) {
    return {
      original: ref,
      targetNodeId: exactMatch.id,
      confidence: 0.95,
      resolvedBy: 'file-path',
    };
  }

  // Fall back to suffix match (e.g., ref="snippets/foo.liquid" matches
  // "src/snippets/foo.liquid"). When several files share the basename — a
  // `#include "RNCAsyncStorage.h"` with a same-named header on another platform
  // (windows/code/ vs apple/) — prefer the one in the includer's own directory,
  // then by directory proximity / same language family. A C/C++ include (and any
  // bare-filename import) resolves relative to the including file, not to an
  // arbitrary same-named header elsewhere in the tree.
  const suffixMatches = fileNodes.filter(
    n => n.qualifiedName.endsWith(ref.referenceName) || n.filePath.endsWith(ref.referenceName)
  );
  if (suffixMatches.length > 0) {
    return {
      original: ref,
      targetNodeId: pickClosestFileNode(suffixMatches, ref).id,
      confidence: 0.85,
      resolvedBy: 'file-path',
    };
  }

  // If only one file node with this name, use it with lower confidence
  if (fileNodes.length === 1) {
    return {
      original: ref,
      targetNodeId: fileNodes[0]!.id,
      confidence: 0.7,
      resolvedBy: 'file-path',
    };
  }

  return null;
}

/**
 * Among several file nodes that all match a bare include/import by basename,
 * pick the one closest to the referencing file: same directory first, then by
 * directory-tree proximity, with the same language family as a tiebreak. A
 * C/C++ `#include "X.h"` (and any bare-filename import) resolves relative to the
 * including file — not to an arbitrary same-named header on another platform.
 */
function pickClosestFileNode(candidates: Node[], ref: UnresolvedRef): Node {
  const dirOf = (p: string): string => {
    const i = p.lastIndexOf('/');
    return i >= 0 ? p.slice(0, i) : '';
  };
  const refDir = dirOf(ref.filePath);
  const sameDir = candidates.filter((c) => dirOf(c.filePath) === refDir);
  const pool = sameDir.length > 0 ? sameDir : candidates;
  let best = pool[0]!;
  let bestScore = -Infinity;
  for (const c of pool) {
    const score =
      computePathProximity(ref.filePath, c.filePath) +
      (sameLanguageFamily(c.language, ref.language) ? 5 : 0);
    if (score > bestScore) {
      bestScore = score;
      best = c;
    }
  }
  return best;
}

/**
 * Language families that share a type system / runtime, so a same-language-only
 * reference may still resolve across them (a Kotlin `Foo.BAR` can name a Java
 * `Foo`). Anything not listed forms its own singleton family.
 */
const LANGUAGE_FAMILY: Record<string, string> = {
  java: 'jvm', kotlin: 'jvm', scala: 'jvm',
  swift: 'native', objc: 'native',
  // ArkTS is a TS superset — every HarmonyOS project mixes `.ets` UI with
  // `.ts` logic modules, so refs must cross freely between them.
  typescript: 'web', tsx: 'web', javascript: 'web', jsx: 'web', arkts: 'web',
  c: 'native', cpp: 'native',
  // Razor/Blazor markup names C# types — same family so `@model Foo` /
  // `<MyComponent/>` resolve to their `.cs` class through the cross-family gate.
  csharp: 'dotnet', razor: 'dotnet', vbnet: 'dotnet',
  svelte: 'web', vue: 'web', astro: 'web',
  cfml: 'cfml', cfscript: 'cfml',
};
export function sameLanguageFamily(a: string, b: string): boolean {
  if (a === b) return true;
  const fa = LANGUAGE_FAMILY[a];
  return fa !== undefined && fa === LANGUAGE_FAMILY[b];
}

/**
 * The languages whose files share one table of names: a C function is called
 * by its bare name from C++ and Objective-C alike, and a `.h` file is C, C++
 * or Objective-C only as far as sniffing its text can tell (Dear ImGui's
 * C++ `imgui.h` reads as C), so name matching ranks them as one language.
 * Other families keep the language itself: their files reach each other's
 * names through imports, and a name-only pick across TypeScript and TSX, or
 * Java and Kotlin, went to a same-named declaration in the next file more
 * often than to the one meant (#1662).
 */
const C_LINKED_LANGUAGES: ReadonlySet<string> = new Set(['c', 'cpp', 'objc']);
function sameRankingLanguage(a: string, b: string): boolean {
  return a === b || (C_LINKED_LANGUAGES.has(a) && C_LINKED_LANGUAGES.has(b));
}
/** Config/markup transitions stay open; every other code language has a family. */
const CODE_FAMILY: Record<string, string> = {
  ...LANGUAGE_FAMILY,
  python: 'python', go: 'go', rust: 'rust', php: 'php', ruby: 'ruby', dart: 'dart',
  lua: 'lua', luau: 'lua', r: 'r', erlang: 'erlang', pascal: 'pascal', solidity: 'solidity',
  nix: 'nix', cobol: 'cobol',
};

export function crossesCodeBoundary(a: string, b: string): boolean {
  return CODE_FAMILY[a] !== undefined && CODE_FAMILY[b] !== undefined &&
    CODE_FAMILY[a] !== CODE_FAMILY[b];
}

/**
 * Cross-family name matches need a framework export or an actual ABI boundary,
 * not merely a native caller. ABI evidence is scoped to the named free function.
 */
function hasBridgeEvidence(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.referenceKind !== 'calls') return false;
  // Expo's extractor creates explicit JS exports, resolved by the ordinary
  // name matcher rather than a framework resolve() branch.
  if (CODE_FAMILY[ref.language] === 'web' && candidate.id.startsWith('expo-module:') &&
      candidate.isExported && (candidate.language === 'swift' || candidate.language === 'kotlin')) return true;
  if (candidate.kind !== 'function') return false;
  const name = candidate.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  if (CODE_FAMILY[ref.language] === 'native') {
    const source = context.readFile(candidate.filePath);
    if (!source) return false;
    if (candidate.language === 'go') {
      const declaration = source.split('\n').slice(Math.max(0, candidate.startLine - 2), candidate.endLine).join('\n');
      return /\bimport\s+(?:\(\s*)?"C"/.test(stripCommentsForRegex(source, 'go')) &&
        new RegExp('^//export ' + name + '\\r?\\nfunc ' + name + '\\s*\\(', 'm').test(declaration);
    }
    if (candidate.language === 'rust') {
      const declaration = source.split('\n').slice(candidate.startLine - 1, candidate.endLine).join('\n');
      return new RegExp('\\bpub\\s+extern\\s+"C"\\s+fn\\s+' + name + '\\b')
        .test(stripCommentsForRegex(declaration, 'rust'));
    }
  }
  if (candidate.language === 'c' || candidate.language === 'cpp') {
    const source = context.readFile(ref.filePath);
    if (!source) return false;
    if (ref.language === 'go') {
      return /\bimport\s+(?:\(\s*)?"C"/.test(stripCommentsForRegex(source, 'go')) &&
        ref.referenceName === 'C.' + candidate.name;
    }
    if (ref.language === 'rust') {
      return new RegExp('extern\\s+"C"\\s*\\{[^}]*\\bfn\\s+' + name + '\\s*\\(')
        .test(stripCommentsForRegex(source, 'rust'));
    }
  }
  return false;
}

/**
 * Per-context memo: node id → its language, for gateLanguageMatch. Matches
 * land on ~5 refs per target on vscode, and each check otherwise fetched the
 * whole node (a point read + row decode past the query layer's small cache)
 * only to read one field. Nodes are fixed within a resolution pass; the memo
 * drops with clearNameMatcherMemos.
 */
const TARGET_LANGUAGE = new WeakMap<ResolutionContext, Map<string, string>>();

/** Reject the chosen result without shrinking a pool or trying a replacement. */
export function gateLanguageMatch(
  result: ResolvedRef | null,
  ref: UnresolvedRef,
  context: ResolutionContext
): ResolvedRef | null {
  if (!result) return result;
  // No code family on the reference's side: no target can cross a boundary.
  if (CODE_FAMILY[ref.language] === undefined) return result;
  if (context.getNodeById) {
    let languages = TARGET_LANGUAGE.get(context);
    if (!languages) {
      languages = new Map();
      TARGET_LANGUAGE.set(context, languages);
    }
    let language = languages.get(result.targetNodeId);
    if (language === undefined) {
      const node = context.getNodeById(result.targetNodeId);
      if (node) {
        language = node.language as string;
        if (languages.size >= 400_000) languages.clear();
        languages.set(result.targetNodeId, language);
      }
    }
    if (language !== undefined) {
      if (!crossesCodeBoundary(ref.language, language)) return result;
      const target = context.getNodeById(result.targetNodeId);
      return target && !hasBridgeEvidence(target, ref, context) ? null : result;
    }
  }
  const target = context.getNodeById?.(result.targetNodeId) ??
    context.getNodesByName(ref.referenceName).find((n) => n.id === result.targetNodeId);
  if (target && crossesCodeBoundary(ref.language, target.language) &&
      !hasBridgeEvidence(target, ref, context)) return null;
  return result;
}

/** Member values retain their receiver; never break ties by file order (#1820). */
function matchMemberFunctionRef(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  const dot = ref.referenceName.lastIndexOf('.');
  const receiver = ref.referenceName.slice(0, dot);
  const member = ref.referenceName.slice(dot + 1);
  const result = (nodes: Node[], confidence = 0.9): ResolvedRef | null => {
    const pool = nodes.filter(n => sameLanguageFamily(n.language, ref.language));
    const target = pool.length === 1 ? pool[0] : undefined;
    return target && (target.kind === 'function' || target.kind === 'method') &&
      target.id !== ref.fromNodeId && !isPythonProperty(target, context)
      ? { original: ref, targetNodeId: target.id, confidence, resolvedBy: 'function-ref' }
      : null;
  };
  const imports = context.getImportMappings(ref.filePath, ref.language);
  // An import is authoritative even when it points outside the project.
  if (imports.some(i => i.localName === receiver.split('.')[0])) {
    if (ref.language === 'python') {
      const cls = pythonRefClass(receiver, ref, context);
      if (cls) return result(pythonMembers(cls, member, ref, context));
      // `mod.global` / an imported `global` itself — never a deeper chain (`mod.global.field`).
      const segments = receiver.split('.');
      const hit = segments.length <= 2 ? context.resolveImport?.({ ...ref, referenceName: receiver, referenceKind: 'references' }) : null;
      const global = hit && context.getNodeById?.(hit.targetNodeId);
      // A local import of the root binds what the file imports, unless the file imports it from two places.
      if (global && global.name === segments[segments.length - 1] && isPythonModuleGlobal(global, context) &&
          pythonImportKeys(segments[0]!, ref.filePath, context).size === 1 &&
          !pythonGlobalBindings(segments[0]!, ref.filePath, context).some(b => b.kind !== 'import') &&
          !pythonBindsLocally(segments[0]!, ref, context, false)) {
        return result(pythonGlobalMembers(global, member, ref, context));
      }
    }
    const imported = context.resolveImport?.(ref);
    const node = imported && context.getNodeById?.(imported.targetNodeId);
    return node ? result(context.getNodesByQualifiedName(node.qualifiedName).filter(n => n.filePath === node.filePath)) : null;
  }
  if (ref.language === 'go') {
    if (receiver.includes('.')) return matchGoFieldChainCall(receiver, member, ref, context);
    const decl: GoReceiverDecl = {};
    const type = inferLocalReceiverType(receiver, ref, context, decl);
    if (decl.asserted !== undefined) {
      return decl.asserted && resolveMethodOnType(decl.asserted.name, member, ref, context, 0.9, 'function-ref', decl.asserted.dir);
    }
    // One declared as a type literal, a type from outside the project or an
    // alias of one holds no project method to take.
    if (decl.declared === null || (decl.declared !== undefined && goHasNoProjectMethods(decl.declared, ref, context))) return null;
    // Nor one a call or a conversion gives a value of such a type.
    if (decl.valued === null || (decl.valued && goValuedHasNoProjectMethods(decl.valued, context))) return null;
    if (type) {
      return resolveMethodOnType(type, member, ref, context, 0.9, 'function-ref',
        goDeclaredTypePackage(decl.raw, decl.file ?? ref.filePath, context));
    }
    const types = context.getNodesByName(receiver).filter(n => n.language === 'go' && (n.kind === 'struct' || n.kind === 'interface'));
    if (types.length) return types.length === 1 ? resolveMethodOnType(receiver, member, ref, context, 0.9, 'function-ref') : null;
  } else {
    const owner = context.getNodesInFile(ref.filePath).filter(n =>
      n.kind === 'class' && n.startLine <= ref.line && n.endLine >= ref.line)
      .sort((a, b) => b.startLine - a.startLine)[0];
    let type: string | null = null;
    if (receiver === 'self' || receiver === 'cls') {
      return owner ? result(pythonMembers(owner, member, ref, context)) : null;
    }
    if (/^(self|cls)\.\w+$/.test(receiver)) {
      if (!owner) return null;
      type = pythonFieldType(receiver, owner, ref, context);
    } else {
      type = pythonLocalType(receiver, ref, context);
      const viaGlobal = type === null ? pythonGlobalReceiverTarget(receiver, member, ref, context) : undefined;
      if (viaGlobal !== undefined) {
        return viaGlobal ? { original: ref, targetNodeId: viaGlobal.id, confidence: 0.9, resolvedBy: 'function-ref' } : null;
      }
    }
    // A type name used directly (`Store.fetch`) is scoped just like an annotation.
    if (!type && /^[A-Z]\w*$/.test(receiver)) type = receiver;
    if (type && type !== 'object' && type !== 'Any') {
      const cls = pythonRefClass(type, ref, context);
      if (!cls) return null;
      const members = pythonMembers(cls, member, ref, context);
      if (members.length) return result(members);
      // A base-typed field can hold a subclass-only method (the reported case).
      // Keep only descendants of THAT base; unrelated same-name methods cannot win.
      const candidates = context.getNodesByName(member).filter(n => n.kind === 'method' && n.language === 'python');
      const descendants = candidates.filter(n => {
        const parent = context.getNodesInFile(n.filePath).find(c =>
          c.kind === 'class' && n.qualifiedName === `${c.qualifiedName}::${member}`);
        return parent && pythonDerivesFrom(parent, cls, ref, context);
      });
      return result(descendants, 0.8);
    }
  }
  // Unknown receivers retain the old unique-or-drop discipline, across ALL
  // files. Tests and abstract-looking bodies are candidates too. A lone method
  // stands only when the receiver is named after its owner: netbox's
  // `device=self.parent.device` is a model field, not the project's one
  // `device` method (a GraphQL filter's). A veto, never a filter — filtering
  // first would promote some other lone match into a new guess.
  const unique = result(context.getNodesByName(member), 0.8);
  const target = unique ? context.getNodeById?.(unique.targetNodeId) : null;
  return target && target.kind === 'method' && !sharesReceiverWord(receiverLink(receiver), target) ? null : unique;
}

function pythonRefClass(name: string, ref: UnresolvedRef, context: ResolutionContext): Node | null {
  const imports = context.getImportMappings(ref.filePath, 'python');
  // `import pkg.mod` then `pkg.mod.Cls`: the mapping keys the module by its last segment.
  const module = imports.find(i => i.isNamespace && name.startsWith(`${i.source}.`) &&
    /^\w+$/.test(name.slice(i.source.length + 1)));
  if (module) {
    // Two modules with the same last segment (`import a.foo`, `import b.foo`) share the key: refuse.
    if (imports.filter(i => i.localName === module.localName).length !== 1) return null;
    name = `${module.localName}.${name.slice(module.source.length + 1)}`;
  }
  if (imports.some(i => i.localName === name.split('.')[0])) {
    const hit = context.resolveImport?.({ ...ref, referenceName: name, referenceKind: 'references' });
    const node = hit && context.getNodeById?.(hit.targetNodeId);
    return node?.kind === 'class' && context.getNodesByQualifiedName(node.qualifiedName)
      .filter(n => n.kind === 'class' && n.filePath === node.filePath).length === 1 ? node : null;
  }
  const classes = context.getNodesByName(name).filter(n => n.kind === 'class' && n.filePath === ref.filePath);
  return classes.length === 1 ? classes[0]! : null;
}

function pythonBases(cls: Node, ref: UnresolvedRef, context: ResolutionContext): Node[] {
  const line = context.getFileLines?.(cls.filePath)?.[cls.startLine - 1]
    ?? context.readFile(cls.filePath)?.split('\n')[cls.startLine - 1] ?? '';
  const bases = line.match(/^\s*class\s+\w+\s*\(([^)]*)\)/)?.[1];
  return (bases?.split(',') ?? []).flatMap(name => {
    const base = pythonRefClass(name.trim(), { ...ref, filePath: cls.filePath }, context);
    return base ? [base] : [];
  });
}

function pythonDerivesFrom(cls: Node, base: Node, ref: UnresolvedRef, context: ResolutionContext, seen = new Set<string>()): boolean {
  if (seen.has(cls.id) || seen.size >= 16) return false;
  seen.add(cls.id);
  return pythonBases(cls, ref, context).some(p => p.id === base.id || pythonDerivesFrom(p, base, ref, context, seen));
}

function pythonMembers(cls: Node, member: string, ref: UnresolvedRef, context: ResolutionContext, seen = new Set<string>()): Node[] {
  if (seen.has(cls.id) || seen.size >= 16) return [];
  seen.add(cls.id);
  // Instance assignments also shadow methods, even though they are not nodes.
  const body = pythonMemberLines(cls.filePath, context).slice(cls.startLine - 1, cls.endLine).join('\n');
  if (new RegExp(`^\\s*(?:(?:self|cls)\\.)?${escapeRegExp(member)}\\s*(?:=|:)`, 'm').test(body)) return [cls];
  const own = context.getNodesByQualifiedName(`${cls.qualifiedName}::${member}`).filter(n => n.filePath === cls.filePath);
  if (own.length) return own;
  return [...new Map(pythonBases(cls, ref, context).flatMap(p => pythonMembers(p, member, ref, context, seen)).map(n => [n.id, n])).values()];
}

function isPythonProperty(node: Node, context: ResolutionContext): boolean {
  if (node.language !== 'python' || node.kind !== 'method') return false;
  const lines = context.getFileLines?.(node.filePath) ?? context.readFile(node.filePath)?.split('\n') ?? [];
  for (let i = node.startLine - 2; i >= 0 && lines[i]!.trim().startsWith('@'); i--) {
    if (/^\s*@(?:property|(?:functools\.)?cached_property)\s*$/.test(lines[i]!)) return true;
  }
  return false;
}

const PYTHON_MEMBER_LINES = new WeakMap<ResolutionContext, Map<string, string[]>>();
function pythonMemberLines(filePath: string, context: ResolutionContext): string[] {
  let files = PYTHON_MEMBER_LINES.get(context);
  if (!files) { files = new Map(); PYTHON_MEMBER_LINES.set(context, files); }
  let lines = files.get(filePath);
  if (!lines) {
    lines = stripCommentsForRegex(context.readFile(filePath) ?? '', 'python').split('\n');
    files.set(filePath, lines);
  }
  return lines;
}

function pythonLocalType(receiver: string, ref: UnresolvedRef, context: ResolutionContext): string | null {
  if (!/^\w+$/.test(receiver)) return null;
  const caller = context.getNodeById?.(ref.fromNodeId);
  const lines = pythonMemberLines(ref.filePath, context);
  const declaration = new RegExp(`^\\s*${receiver}\\s*(?::\\s*["']?([\\w.]+)["']?)?\\s*=\\s*(.*)$`);
  const annotation = new RegExp(`^\\s*${receiver}\\s*:\\s*["']?([\\w.]+)`);
  for (let i = ref.line - 1; i >= (caller?.startLine ?? 1) - 1; i--) {
    const line = lines[i] ?? '';
    const assigned = line.match(declaration);
    if (assigned) return assigned[1] ?? assigned[2]!.match(/^([A-Z][\w.]*)\s*\(/)?.[1] ?? '<unknown>';
    const declared = line.match(annotation)?.[1];
    if (declared) return declared;
  }
  return caller?.signature?.match(new RegExp(`\\b${receiver}\\s*:\\s*["']?([\\w.]+)`))?.[1] ?? null;
}

/** A module-scope Python variable (not a class attribute or a function local). */
function isPythonModuleGlobal(node: Node, context: ResolutionContext): boolean {
  return node.language === 'python' && (node.kind === 'variable' || node.kind === 'constant') &&
    !context.getNodesInFile(node.filePath).some(n =>
      (n.kind === 'class' || n.kind === 'function' || n.kind === 'method') &&
      n.startLine <= node.startLine && n.endLine >= node.startLine);
}

/** How one line binds a name: `global`, a plain `name = value` / `name: T`, an import, or any other binding. */
type PythonBinding =
  | { kind: 'global' }
  | { kind: 'assign'; type: string | null; value: string; line: number }
  | { kind: 'import'; key: string }
  | { kind: 'other' };

const PYTHON_STATEMENT_STARTS = new WeakMap<ResolutionContext, Map<string, boolean[]>>();
/** Per line: does it start a statement (bracket depth 0, no `\` continuation)? String contents are skipped. */
function pythonStatementStarts(filePath: string, context: ResolutionContext): boolean[] {
  let files = PYTHON_STATEMENT_STARTS.get(context);
  if (!files) { files = new Map(); PYTHON_STATEMENT_STARTS.set(context, files); }
  let starts = files.get(filePath);
  if (starts) return starts;
  starts = [];
  let depth = 0;
  let continued = false;
  for (const line of pythonMemberLines(filePath, context)) {
    starts.push(depth === 0 && !continued);
    let quote = '';
    for (let i = 0; i < line.length; i++) {
      const c = line[i]!;
      if (quote) { if (c === '\\') i++; else if (c === quote) quote = ''; continue; }
      if (c === '"' || c === "'") quote = c;
      else if (c === '(' || c === '[' || c === '{') depth++;
      else if (c === ')' || c === ']' || c === '}') depth = Math.max(0, depth - 1);
    }
    continued = /\\\s*$/.test(line);
  }
  files.set(filePath, starts);
  return starts;
}

/** Line indexes that belong to `scope` itself (null: the module), not to a def or class nested in it. */
function pythonOwnLines(scope: Node | null, filePath: string, context: ResolutionContext): number[] {
  const count = pythonMemberLines(filePath, context).length;
  const from = scope ? scope.startLine : 1;
  const to = scope ? Math.min(scope.endLine, count) : count;
  const nested = new Uint8Array(to - from + 1);
  for (const n of context.getNodesInFile(filePath)) {
    if ((n.kind !== 'function' && n.kind !== 'method' && n.kind !== 'class') || n.id === scope?.id) continue;
    if (n.startLine < from || n.endLine > to || (scope && n.startLine <= scope.startLine)) continue;
    nested.fill(1, n.startLine - from, n.endLine - from + 1);
  }
  const own: number[] = [];
  for (let l = from; l <= to; l++) if (!nested[l - from]) own.push(l - 1);
  return own;
}

/** Split `a = b = value` at its top-level assignment operators; null when the line assigns nothing. */
function pythonAssignment(line: string): { targets: string[]; value: string; augmented: boolean } | null {
  const targets: string[] = [];
  let depth = 0;
  let quote = '';
  let start = 0;
  let augmented = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i]!;
    if (quote) { if (c === '\\') i++; else if (c === quote) quote = ''; continue; }
    if (c === '"' || c === "'") { quote = c; continue; }
    if (c === '(' || c === '[' || c === '{') { depth++; continue; }
    if (c === ')' || c === ']' || c === '}') { depth--; continue; }
    if (c !== '=' || depth !== 0) continue;
    const prev = line[i - 1] ?? '';
    if (line[i + 1] === '=') { i++; continue; } // ==
    if (prev === '!' || prev === ':') continue; // != and the walrus
    if ((prev === '<' || prev === '>') && line[i - 2] !== prev) continue; // <= >=
    const op = line.slice(start, i).match(/(?:\/\/|\*\*|>>|<<|[-+*/%&|^@])$/)?.[0];
    if (op) augmented = true;
    targets.push(line.slice(start, i - (op?.length ?? 0)));
    start = i + 1;
  }
  return targets.length ? { targets, value: line.slice(start), augmented } : null;
}

/**
 * Every way the statement starting at line `index` binds `name`, read across
 * its continuation lines. Only statement lines can assign or import; any line
 * can bind through `as`, a loop, a lambda or the walrus.
 */
function pythonLineBindings(lines: string[], index: number, statements: boolean[], name: string): PythonBinding[] {
  let line = lines[index]!;
  if (statements[index]) for (let j = index + 1; j < lines.length && !statements[j]; j++) line += '\n' + lines[j];
  const out: PythonBinding[] = [];
  // An import statement can name `name` on a continuation line: `from x import (\n    name,\n)`.
  const imported = statements[index] ? line.match(/^\s*(?:from\s+([\w.]+)\s+)?import\s+([\s\S]*)$/) : null;
  if (imported) {
    const names = imported[2]!;
    // `from x import *` can bind any name.
    if (imported[1] && names.trim() === '*') return [{ kind: 'other' }];
    if (!names.includes(name)) return out;
    for (const part of names.replace(/[()\\]/g, ' ').split(',')) {
      const m = part.trim().match(/^([\w.]+)(?:\s+as\s+(\w+))?$/);
      const local = m && (m[2] ?? (imported[1] ? m[1]! : m[1]!.split('.')[0]!));
      if (local !== name) continue;
      out.push({ kind: 'import', key: imported[1] ? `${imported[1]}:${m![1]}` : `${m![2] ? m![1] : local}:*` });
    }
    return out;
  }
  if (!line.includes(name)) return out;
  const word = new RegExp(`(?<![\\w.])${escapeRegExp(name)}\\b(?!\\s*[.\\[])`);
  if (!word.test(line)) return out;
  const declared = line.match(/^\s*(global|nonlocal)\s+([\w\s,]+)$/);
  if (declared) {
    return declared[2]!.split(',').some(s => s.trim() === name)
      ? [declared[1] === 'global' ? { kind: 'global' } : { kind: 'other' }] : [];
  }
  if (statements[index]) {
    // A `case` pattern binds its capture names (`case [name]:`, `case Cls(k=name):`, `case name:`).
    if (/^\s*case\b/.test(line)) return [{ kind: 'other' }];
    const assignment = pythonAssignment(line);
    if (assignment) {
      const target = assignment.targets.length === 1 && !assignment.augmented ? assignment.targets[0]!.trim() : '';
      const annotated = target.match(new RegExp(`^${escapeRegExp(name)}\\s*:\\s*["']?([\\w.]+)["']?$`));
      if (target === name || annotated) {
        out.push({ kind: 'assign', type: annotated?.[1] ?? null, value: assignment.value.trim(), line: index });
      } else if (assignment.targets.some(t => word.test(t))) {
        out.push({ kind: 'other' });
      }
    } else {
      const annotated = line.match(new RegExp(`^\\s*${escapeRegExp(name)}\\s*:\\s*["']?([\\w.]+)["']?\\s*$`));
      if (annotated) out.push({ kind: 'assign', type: annotated[1]!, value: '', line: index });
      else if (new RegExp(`^\\s*del\\b`).test(line)) out.push({ kind: 'other' });
    }
  }
  if (new RegExp(`\\b${escapeRegExp(name)}[ \\t]*:=|\\bas[ \\t]+${escapeRegExp(name)}\\b`).test(line)) out.push({ kind: 'other' });
  for (const loop of line.matchAll(/\bfor\s+([^:]+?)\s+in\b/g)) if (word.test(loop[1]!)) out.push({ kind: 'other' });
  for (const lambda of line.matchAll(/\blambda\b([^:]*):/g)) if (word.test(lambda[1]!)) out.push({ kind: 'other' });
  return out;
}

/**
 * Whether `name`, read at the ref, is bound by the calling function or one that
 * encloses it (parameter, assignment, loop, `as`, lambda, import) rather than
 * being the module global. With `importsBind` false, an import of the name is
 * not a shadow: it binds the same module the file imports.
 */
function pythonBindsLocally(name: string, ref: UnresolvedRef, context: ResolutionContext, importsBind: boolean): boolean {
  const lines = pythonMemberLines(ref.filePath, context);
  const statements = pythonStatementStarts(ref.filePath, context);
  const param = new RegExp(`[(,]\\s*\\*{0,2}${escapeRegExp(name)}\\s*[:=,)]`);
  const scopes = context.getNodesInFile(ref.filePath).filter(n =>
    (n.kind === 'function' || n.kind === 'method') && n.startLine <= ref.line && n.endLine >= ref.line)
    .sort((a, b) => b.startLine - a.startLine);
  for (const scope of scopes) {
    const own = pythonOwnLines(scope, ref.filePath, context);
    const bindings = own.flatMap(i => pythonLineBindings(lines, i, statements, name));
    if (bindings.some(b => b.kind === 'global')) return false;
    const def = own.find(i => /^\s*(?:async\s+)?def\b/.test(lines[i]!));
    let header = scope.signature ?? '';
    for (let j = def ?? lines.length; j < lines.length && (j === def || !statements[j]); j++) header += lines[j];
    if (param.test(header)) return true;
    if (bindings.some(b => b.kind !== 'global' && (b.kind !== 'import' || importsBind))) return true;
  }
  return false;
}

/**
 * The module `name` is bound to by an `import a.b as name` written in the
 * function around `ref` — the innermost one that binds `name` at all (#2600).
 * Import mappings are per file and read only module-level `import` lines, so
 * such a function-local alias has none. Null when that function binds `name`
 * any other way, binds it to several modules, or imports an undotted module
 * (an optional dependency's name can match any project file's basename).
 */
export function pythonFunctionModuleAlias(name: string, ref: UnresolvedRef, context: ResolutionContext): string | null {
  if (ref.language !== 'python' || !/^\w+$/.test(name)) return null;
  const lines = pythonMemberLines(ref.filePath, context);
  const statements = pythonStatementStarts(ref.filePath, context);
  const scopes = context.getNodesInFile(ref.filePath).filter(n =>
    (n.kind === 'function' || n.kind === 'method') && n.startLine <= ref.line && n.endLine >= ref.line)
    .sort((a, b) => b.startLine - a.startLine);
  for (const scope of scopes) {
    const bindings = pythonOwnLines(scope, ref.filePath, context).flatMap(i => pythonLineBindings(lines, i, statements, name));
    if (bindings.length === 0) continue;
    const modules = new Set(bindings.map(b => b.kind === 'import' && b.key.endsWith(':*') ? b.key.slice(0, -2) : ''));
    const [module] = modules;
    return modules.size === 1 && module && module.includes('.') && !pythonBindsLocally(name, ref, context, false) ? module : null;
  }
  return null;
}

/**
 * How the code around a Python reference binds `name`, the receiver of a
 * dotted reference whose file imports that name:
 * - `'module'`: nothing nearer does (or the function declares it `global`),
 *   so the file's own import is what the reference reads;
 * - `'local'`: the calling function, a function enclosing it, or the
 *   reference's own statement binds it otherwise — a parameter, an
 *   assignment (annotated and augmented ones too), a `for` / `with … as` /
 *   `except … as` target, a walrus, `del`, a nested `def` or `class`, a
 *   `case` capture, an `import` statement, or a lambda parameter or a
 *   comprehension variable the reference sits inside;
 * - `{ source, exportedName }`: a function-local `from source import
 *   exportedName as name`, the one import that binds it there;
 * - `{ module }`: a function-local `import module as name`, or `import name`
 *   / `import name.sub` (which bind the top-level `name`).
 * A keyword argument, an attribute or subscript store, a comparison, text in
 * a string or a comment, and a nested function's own body bind nothing.
 * `def by_param(other): other.update(…)` and `with open(p) as other:` read
 * no module the file imports as `other`.
 */
export type PythonReceiverBinding =
  | 'module'
  | 'local'
  | { source: string; exportedName: string }
  | { module: string };

export function pythonReceiverBinding(name: string, ref: UnresolvedRef, context: ResolutionContext): PythonReceiverBinding {
  if (ref.language !== 'python' || !/^[A-Za-z_]\w*$/.test(name)) return 'module';
  if (pythonStatementBindsAt(name, ref, context)) return 'local';
  // Innermost first: a closure reads the binding of the function nearest it.
  const { functions, innermost, parent } = pythonFunctionIndex(ref.filePath, context);
  for (let i = innermost[ref.line] ?? -1; i >= 0; i = parent[i]!) {
    const scope = functions[i]!;
    const binding = pythonNameScan(context, `binding\0${scope.id}\0${name}`, () => pythonScopeBinding(scope, name, context));
    if (binding !== null) return binding;
  }
  return 'module';
}

/**
 * A file's functions and methods, the innermost one around each line (-1 for
 * none) and the one around each function's own `def` line, built once per file.
 */
function pythonFunctionIndex(filePath: string, context: ResolutionContext): { functions: Node[]; innermost: Int32Array; parent: Int32Array } {
  return pythonNameScan(context, `functions\0${filePath}`, () => {
    // Outer before inner: by start, the longer first.
    const functions = context.getNodesInFile(filePath)
      .filter((n) => n.kind === 'function' || n.kind === 'method')
      .sort((a, b) => a.startLine - b.startLine || b.endLine - a.endLine);
    const innermost = new Int32Array(functions.reduce((m, f) => Math.max(m, f.endLine), 0) + 2).fill(-1);
    const parent = new Int32Array(functions.length).fill(-1);
    functions.forEach((f, i) => {
      parent[i] = innermost[f.startLine]!;
      innermost.fill(i, f.startLine, f.endLine + 1);
    });
    return { functions, innermost, parent };
  });
}

/** How the function `scope` itself binds `name`; null when it doesn't, and an enclosing scope decides. */
function pythonScopeBinding(scope: Node, name: string, context: ResolutionContext): PythonReceiverBinding | null {
  const { params, statements, nested } = pythonScopeText(scope, context);
  if (statements.some((st) => pythonDeclaresGlobal(st, name))) return 'module';
  if (params.includes(name) || nested.includes(name)) return 'local';
  let imported: Exclude<PythonReceiverBinding, string> | null = null;
  for (const st of statements) {
    const binding = pythonImportBinds(st, name);
    if (binding === undefined) {
      if (pythonStatementBinds(st, name)) return 'local';
    } else if (binding) {
      // Two imports binding the name differently: which one a reference reads
      // depends on the path the function took.
      if (imported && JSON.stringify(imported) !== JSON.stringify(binding)) return 'local';
      imported = binding;
    }
  }
  return imported;
}

/**
 * The parameter names of the function `scope`, the statements of its own
 * body (continuation lines joined, strings blanked, split on `;`), and the
 * names its nested `def`s and `class`es bind, whose bodies are not its own.
 */
function pythonScopeText(scope: Node, context: ResolutionContext): { params: string[]; statements: string[]; nested: string[] } {
  return pythonNameScan(context, `scope\0${scope.id}`, () => {
    const lines = pythonMemberLines(scope.filePath, context);
    const last = Math.min(scope.endLine, lines.length);
    const indent = (l: string) => l.length - l.trimStart().length;
    const statements: string[] = [];
    const nested: string[] = [];
    let header: string | null = null;
    let current: string | null = null;
    let depth = 0;
    let continued = false;
    let nestedIndent = -1;
    const flush = () => {
      if (current === null) return;
      if (header === null) header = current;
      else statements.push(...current.split(';').map((s) => s.trim()).filter(Boolean));
      current = null;
    };
    for (let k = scope.startLine; k <= last; k++) {
      const raw = lines[k - 1] ?? '';
      const blanked = pythonBlankStrings(raw);
      const inside = depth > 0 || continued;
      for (const c of blanked) {
        if (c === '(' || c === '[' || c === '{') depth++;
        else if (c === ')' || c === ']' || c === '}') depth = Math.max(0, depth - 1);
      }
      continued = /\\\s*$/.test(blanked);
      if (inside) {
        if (current !== null) current += ' ' + blanked.trim().replace(/\\$/, '');
        continue;
      }
      if (!blanked.trim()) continue;
      flush();
      if (nestedIndent >= 0) {
        if (indent(raw) > nestedIndent) continue;
        nestedIndent = -1;
      }
      const text = blanked.trim().replace(/\\$/, '');
      // The scope's first line is its own `def` header.
      const def = k === scope.startLine ? null : /^(?:async\s+)?(?:def|class)\s+(\w+)/.exec(text);
      if (def) {
        nested.push(def[1]!);
        nestedIndent = indent(raw);
        continue;
      }
      current = text;
    }
    flush();
    // `def name[T](a, *b, c: int = 1, **d)`: the names between the brackets.
    const head = header ?? '';
    const open = /\bdef\s+\w+\s*(?:\[[^\]]*\]\s*)?\(/.exec(head);
    const params = open ? pythonParamNames(head.slice(open.index + open[0].length, pythonClosingParen(head, open.index + open[0].length - 1))) : [];
    return { params, statements, nested };
  });
}

/** The index of the bracket closing the one at `open`, or the text's end. */
function pythonClosingParen(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    const c = text[i]!;
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return text.length;
}

/** `text` split at its top-level commas (none inside brackets). */
function pythonTopLevelParts(text: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let from = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i]!;
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth = Math.max(0, depth - 1);
    else if (c === ',' && depth === 0) {
      parts.push(text.slice(from, i));
      from = i + 1;
    }
  }
  parts.push(text.slice(from));
  return parts;
}

/** The names a parameter list binds: `a`, `*b`, `c: int = 1`, `**d`; never the bare `*` or `/` markers. */
function pythonParamNames(list: string): string[] {
  return pythonTopLevelParts(list)
    .map((p) => /^\s*\*{0,2}\s*([A-Za-z_]\w*)/.exec(p)?.[1])
    .filter((p): p is string => p !== undefined);
}

/** `global name` (or a list naming it). */
function pythonDeclaresGlobal(statement: string, name: string): boolean {
  const m = /^global\s+(.+)$/.exec(statement);
  return !!m && m[1]!.split(',').some((n) => n.trim() === name);
}

/**
 * What an import statement binds `name` to: the module of `import a.b as
 * name`, or the top-level `name` of `import name` / `import name.sub`; the
 * source and name of `from a import b as name`; null for an import that
 * doesn't bind it, undefined for any other statement.
 */
function pythonImportBinds(statement: string, name: string): Exclude<PythonReceiverBinding, string> | null | undefined {
  const plain = /^import\s+([\s\S]+)$/.exec(statement);
  if (plain) {
    for (const part of plain[1]!.replace(/[()]/g, ' ').split(',')) {
      const m = /^([\w.]+)(?:\s+as\s+(\w+))?$/.exec(part.trim());
      if (!m) continue;
      if (m[2] === name) return { module: m[1]! };
      if (!m[2] && m[1]!.split('.')[0] === name) return { module: name };
    }
    return null;
  }
  const from = /^from\s+(\.*[\w.]*)\s+import\s+([\s\S]+)$/.exec(statement);
  if (!from) return undefined;
  for (const part of from[2]!.replace(/[()]/g, ' ').split(',')) {
    const m = /^(\w+)(?:\s+as\s+(\w+))?$/.exec(part.trim());
    if (m && (m[2] ?? m[1]) === name) return { source: from[1]!, exportedName: m[1]! };
  }
  return null;
}

/** Whether one statement (strings blanked) binds `name` other than by an import. */
function pythonStatementBinds(statement: string, name: string): boolean {
  const n = escapeRegExp(name);
  if (pythonAssignTargets(statement).some((t) => pythonTargetBinds(t, name))) return true;
  // `name: T` declares a local without assigning it.
  if (new RegExp(`^${n}\\s*:(?!=)`).test(statement)) return true;
  const loop = /^(?:async\s+)?for\s+([\s\S]+?)\s+in\b/.exec(statement);
  if (loop && pythonTargetBinds(loop[1]!, name)) return true;
  // `with … as name`, `except … as name`, `case … as name`, `as (a, name)`.
  for (const m of statement.matchAll(/\bas\s+(\([^)]*\)|[\w.]+)/g)) if (pythonTargetBinds(m[1]!, name)) return true;
  if (new RegExp(`(?<![.\\w])${n}\\s*:=`).test(statement)) return true;
  const del = /^del\s+([\s\S]+)$/.exec(statement);
  if (del && pythonTopLevelParts(del[1]!).some((t) => pythonTargetBinds(t, name))) return true;
  return pythonCaseCaptures(statement, name);
}

/**
 * Whether a `case` clause's pattern captures `name`: written bare, not as a
 * value pattern's dotted part (`other.MODE`), a class pattern's class
 * (`other(…)`) or a keyword pattern's attribute (`Point(other=1)`). `case = 1`
 * assigns a variable named `case`.
 */
function pythonCaseCaptures(statement: string, name: string): boolean {
  const m = /^case\b([\s\S]*)$/.exec(statement);
  if (!m || pythonAssignTargets(statement).length > 0) return false;
  let depth = 0;
  let end = -1;
  for (let i = 0; i < m[1]!.length && end < 0; i++) {
    const c = m[1]![i]!;
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth = Math.max(0, depth - 1);
    else if (c === ':' && depth === 0) end = i;
  }
  if (end < 0) return false;
  const pattern = m[1]!.slice(0, end).replace(/\bif\b[\s\S]*$/, '');
  for (const hit of pattern.matchAll(new RegExp(`(?<![.\\w])${escapeRegExp(name)}\\b`, 'g'))) {
    const after = pattern.slice(hit.index! + name.length).trimStart();
    if (after.startsWith('.') || after.startsWith('(') || (after.startsWith('=') && !after.startsWith('=='))) continue;
    return true;
  }
  return false;
}

/**
 * Whether the reference sits inside a lambda whose parameters, or a
 * comprehension whose `for` targets, bind `name` on its own statement:
 * `lambda other: other.update(1)`, `[other.get() for other in items]`. Those
 * bind only there, so the rest of the function still reads the module.
 */
function pythonStatementBindsAt(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const lines = pythonMemberLines(ref.filePath, context);
  const starts = pythonStatementStarts(ref.filePath, context);
  const at = ref.line - 1;
  if (at < 0 || at >= lines.length) return false;
  let first = at;
  while (first > 0 && !starts[first]) first--;
  let end = at;
  while (end + 1 < lines.length && !starts[end + 1]) end++;
  let text = '';
  let offset = 0;
  for (let i = first; i <= end; i++) {
    if (i === at) offset = text.length + Math.max(0, ref.column ?? 0);
    text += pythonBlankStrings(lines[i]!) + '\n';
  }
  if (!/\b(?:lambda|for)\b/.test(text)) return false;
  // A lambda's body runs from its `:` to the first comma or closing bracket of
  // its own level.
  for (const m of text.matchAll(/\blambda\b/g)) {
    const from = m.index! + 6;
    let depth = 0;
    let colon = -1;
    for (let i = from; i < text.length && colon < 0; i++) {
      const c = text[i]!;
      if (c === '(' || c === '[' || c === '{') depth++;
      else if (c === ')' || c === ']' || c === '}') { if (depth === 0) break; depth--; }
      else if (c === ':' && depth === 0) colon = i;
    }
    if (colon < 0 || offset <= colon || !pythonParamNames(text.slice(from, colon)).includes(name)) continue;
    let stop = text.length;
    depth = 0;
    for (let i = colon + 1; i < text.length; i++) {
      const c = text[i]!;
      if (c === '(' || c === '[' || c === '{') depth++;
      else if (c === ')' || c === ']' || c === '}') { if (depth === 0) { stop = i; break; } depth--; }
      else if (c === ',' && depth === 0) { stop = i; break; }
    }
    if (offset < stop) return true;
  }
  // A comprehension's `for` sits inside the brackets it binds in.
  const opens: number[] = [];
  const pairs: Array<[number, number]> = [];
  for (let i = 0; i < text.length; i++) {
    const c = text[i]!;
    if (c === '(' || c === '[' || c === '{') opens.push(i);
    else if ((c === ')' || c === ']' || c === '}') && opens.length) pairs.push([opens.pop()!, i]);
  }
  for (const o of opens) pairs.push([o, text.length]);
  for (const m of text.matchAll(/\bfor\b/g)) {
    const around = pairs.filter(([o, c]) => o < m.index! && c > m.index!).sort((a, b) => b[0] - a[0])[0];
    if (!around || offset <= around[0] || offset >= around[1]) continue;
    const targets = /^\s*([\s\S]+?)\s+in\b/.exec(text.slice(m.index! + 3, around[1]));
    if (targets && pythonTargetBinds(targets[1]!, name)) return true;
  }
  return false;
}

/**
 * The imports binding `name` at module scope, or in a function declaring it
 * `global`, keyed as pythonLineBindings keys them: `from a import x as name`
 * → `a:x`, `import a.b as name` → `a.b:*`.
 */
export function pythonModuleImportKeys(name: string, filePath: string, context: ResolutionContext): Set<string> {
  return new Set(pythonGlobalBindings(name, filePath, context).flatMap((b) => (b.kind === 'import' ? [b.key] : [])));
}

/** Distinct sources a file imports `name` from, at any scope (`from a import x` → `a:x`). */
function pythonImportKeys(name: string, filePath: string, context: ResolutionContext): Set<string> {
  return pythonNameScan(context, `imports\0${filePath}\0${name}`, () => scanPythonImportKeys(name, filePath, context));
}

const PYTHON_NAME_SCANS = new WeakMap<ResolutionContext, Map<string, unknown>>();
/** Per-file, per-name scans are shared by every ref in the file; cleared with the other memos on sync. */
function pythonNameScan<T>(context: ResolutionContext, key: string, scan: () => T): T {
  let memo = PYTHON_NAME_SCANS.get(context);
  if (!memo) { memo = new Map(); PYTHON_NAME_SCANS.set(context, memo); }
  if (!memo.has(key)) memo.set(key, scan());
  return memo.get(key) as T;
}

function scanPythonImportKeys(name: string, filePath: string, context: ResolutionContext): Set<string> {
  const lines = pythonMemberLines(filePath, context);
  const statements = pythonStatementStarts(filePath, context);
  const keys = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    if (!statements[i] || !/\bimport\b/.test(lines[i]!)) continue;
    for (const b of pythonLineBindings(lines, i, statements, name)) if (b.kind === 'import') keys.add(b.key);
  }
  return keys;
}

/** Every binding of module global `name` in `filePath`: at module scope, and in each function that declares it `global`. */
function pythonGlobalBindings(name: string, filePath: string, context: ResolutionContext): PythonBinding[] {
  return pythonNameScan(context, `globals\0${filePath}\0${name}`, () => scanPythonGlobalBindings(name, filePath, context));
}

function scanPythonGlobalBindings(name: string, filePath: string, context: ResolutionContext): PythonBinding[] {
  const lines = pythonMemberLines(filePath, context);
  const statements = pythonStatementStarts(filePath, context);
  const scopes = context.getNodesInFile(filePath).filter(n => n.kind === 'class' || n.kind === 'function' || n.kind === 'method');
  const regions = [pythonOwnLines(null, filePath, context)];
  for (let i = 0; i < lines.length; i++) {
    if (!/^\s*global\b/.test(lines[i]!) || !pythonLineBindings(lines, i, statements, name).length) continue;
    const scope = scopes.filter(n => n.startLine <= i + 1 && n.endLine >= i + 1).sort((a, b) => b.startLine - a.startLine)[0];
    if (scope && scope.kind !== 'class') regions.push(pythonOwnLines(scope, filePath, context));
  }
  const script = pythonMainBlockLines(filePath, context);
  return regions.flatMap(region => region.filter(i => !script.has(i)).flatMap(i => pythonLineBindings(lines, i, statements, name)))
    .filter(b => b.kind !== 'global');
}

const PYTHON_GLOBAL_CLASSES = new WeakMap<ResolutionContext, Map<string, Node[] | null>>();
/**
 * The classes a module global can hold. It has no static type (`conn = None`,
 * rebound by `global conn; conn = Backend()`), so its type is the set of
 * classes its module assigns to it: at module scope, or in a function that
 * declares it `global`. Any other binding of it there (an opaque value, a
 * tuple target, `for`/`with`/import, a star import, a `globals()` write)
 * makes the type unknown (null). Production writes from other modules
 * (`settings.conn = X`) join the set; see pythonExternalWrites.
 */
function pythonGlobalClasses(global: Node, ref: UnresolvedRef, context: ResolutionContext): Node[] | null {
  let memo = PYTHON_GLOBAL_CLASSES.get(context);
  if (!memo) { memo = new Map(); PYTHON_GLOBAL_CLASSES.set(context, memo); }
  if (memo.has(global.id)) return memo.get(global.id)!;
  const own = pythonOwnGlobalWrites(global, context);
  const external = own && pythonExternalWrites(global, context);
  // Each type is resolved in the file that wrote it (its imports name the class).
  const writes = external && !external.unknown ? [...external.writes, ...own!] : null;
  let classes: Node[] | null = writes && [];
  const seen = new Set<string>();
  for (const write of writes ?? []) {
    const cls = pythonRefClass(write.type, { ...ref, filePath: write.file }, context);
    if (!cls) { classes = null; break; }
    if (!seen.has(cls.id)) { seen.add(cls.id); classes!.push(cls); }
  }
  memo.set(global.id, classes);
  return classes;
}

/**
 * The types the global's own module writes to it, or null when a binding
 * there leaves its type unknown — whatever other modules write, so they are
 * not read (#2332).
 */
function pythonOwnGlobalWrites(global: Node, context: ResolutionContext): Array<{ type: string; file: string }> | null {
  return pythonNameScan(context, `own\0${global.id}`, () => {
    const file = global.filePath;
    if (pythonDynamicGlobalWrite(global.name, file, context)) return null;
    const writes: Array<{ type: string; file: string }> = [];
    for (const b of pythonGlobalBindings(global.name, file, context)) {
      if (b.kind !== 'assign') return null;
      const constructor = b.value && b.value !== 'None' ? pythonConstructorCall(b.value) : null;
      if (b.type) {
        // `conn: Base = make()` trusts the annotation; `conn: A = B()` contradicts it.
        if (constructor && constructor.split('.').pop() !== b.type.split('.').pop()) return null;
        writes.push({ type: b.type, file });
        continue;
      }
      if (b.value === 'None') continue;
      if (!constructor) return null;
      writes.push({ type: constructor, file });
    }
    return writes;
  });
}

/**
 * The repo files a Python module path can name from `fromFile`. Relative
 * paths (`..settings`) resolve exactly; absolute ones match a file path
 * suffix, so a source root (`src/`) still resolves — and two files sharing
 * the tail (`x/settings.py`, `y/settings.py`) both come back.
 */
function pythonModuleFiles(dotted: string, fromFile: string, context: ResolutionContext): string[] {
  const dots = dotted.match(/^\.+/)?.[0].length ?? 0;
  const parts = dotted.slice(dots).split('.').filter(Boolean);
  if (!parts.length) return [];
  let dir = '';
  if (dots) {
    dir = path.posix.dirname(fromFile.replace(/\\/g, '/'));
    for (let i = 1; i < dots; i++) dir = path.posix.dirname(dir);
    if (dir === '.') dir = '';
  }
  const rel = [dir, ...parts].filter(Boolean).join('/');
  const matches = (file: string, want: string) => dots ? file === want : file === want || file.endsWith(`/${want}`);
  const last = parts[parts.length - 1]!;
  return [
    ...context.getNodesByName(`${last}.py`), ...context.getNodesByName(`${last}.pyi`), ...context.getNodesByName('__init__.py'),
  ].filter(n => n.kind === 'file' && (matches(n.filePath, `${rel}.py`) || matches(n.filePath, `${rel}.pyi`) || matches(n.filePath, `${rel}/__init__.py`)))
    .map(n => n.filePath);
}

/**
 * How `filePath` spells the module `moduleFile`: `aliases` import exactly that
 * file; `ambiguous` could also be another file sharing its dotted tail.
 * `import a.b` binds `a`, so that module is spelled `a.b` (the mapping's
 * last-segment `localName` is not a binding); `import a.b as c` binds `c`.
 */
function pythonModuleAliases(filePath: string, moduleFile: string, context: ResolutionContext): { aliases: string[]; ambiguous: string[] } {
  const aliases = new Set<string>();
  const ambiguous = new Set<string>();
  for (const m of context.getImportMappings(filePath, 'python')) {
    const files = pythonImportedFiles(m, filePath, context);
    if (!files.includes(moduleFile)) continue;
    // The mapping cannot tell `import a.b` from `import a.b as b`; the source line can.
    // Exactly this module (not `other.a.b`), outside string literals.
    const explicit = new RegExp(`\\bimport\\s[^\\n]*(?<![\\w.])${escapeRegExp(m.source)}\\s+as\\s+${escapeRegExp(m.localName)}\\b`);
    const plainDotted = m.isNamespace && m.source.includes('.') && m.localName === m.source.split('.').pop() &&
      !pythonMemberLines(filePath, context).some(line => explicit.test(blankPythonStrings(line)));
    (files.length === 1 ? aliases : ambiguous).add(plainDotted ? m.source : m.localName);
  }
  return { aliases: [...aliases], ambiguous: [...ambiguous] };
}

const PYTHON_IMPORTED_FILES = new WeakMap<ResolutionContext, WeakMap<ImportMapping, string[]>>();
/**
 * The repo files an import of `filePath` can name. Every global's write scan
 * asks again of the same files (#2332); kept for as long as the resolver keeps
 * the mapping itself, so the memo never outlives its import cache.
 */
function pythonImportedFiles(m: ImportMapping, filePath: string, context: ResolutionContext): string[] {
  let memo = PYTHON_IMPORTED_FILES.get(context);
  if (!memo) PYTHON_IMPORTED_FILES.set(context, (memo = new WeakMap()));
  let files = memo.get(m);
  if (!files) {
    const dotted = m.isNamespace ? m.source
      : /^\.+$/.test(m.source) ? `${m.source}${m.exportedName}` : `${m.source}.${m.exportedName}`;
    memo.set(m, (files = pythonModuleFiles(dotted, filePath, context)));
  }
  return files;
}

const PYTHON_MAIN_GUARD = /^if\s+(?:__name__\s*==\s*(['"])__main__\1|(['"])__main__\2\s*==\s*__name__)\s*:/;
/** Line indexes inside a top-level `if __name__ == "__main__":` block — script code, not module state. */
function pythonMainBlockLines(filePath: string, context: ResolutionContext): Set<number> {
  return pythonNameScan(context, `main\0${filePath}`, () => {
    const lines = pythonMemberLines(filePath, context);
    const inside = new Set<number>();
    for (let i = 0; i < lines.length; i++) {
      const guard = lines[i]!.match(PYTHON_MAIN_GUARD);
      if (!guard) continue;
      if (lines[i]!.slice(guard[0].length).trim()) inside.add(i); // `if __name__ == "__main__": stmt`
      for (let j = i + 1; j < lines.length && !/^\S/.test(lines[j]!); j++) inside.add(j);
    }
    return inside;
  });
}

/** Blank single-line string contents (triple-quoted strings are already blanked by the comment stripper). */
function blankPythonStrings(text: string): string {
  return text.replace(/(['"])(?:\\.|(?!\1)[^\\\n])*\1/g, m => m[0] + ' '.repeat(m.length - 2) + m[0]);
}

/** Test code installs doubles: the narrow test-suite set, plus pytest's `conftest.py` wherever it sits. */
function isPythonTestFile(filePath: string): boolean {
  return isTestPath(filePath) || /(?:^|\/)conftest\.py$/.test(filePath.replace(/\\/g, '/'));
}

/**
 * Writes to module global `global` from OTHER files. A production write
 * `<module>.<name> = Cls(...)` adds a type; any other production write
 * (another value, a tuple target, `setattr`) makes the type unknown. Test
 * files install doubles (`settings.conn = MagicMock()`, `monkeypatch.setattr`)
 * that do not define the production type; they are recorded as `writers`, and
 * a ref inside a writer resolves nothing through the global.
 */
function pythonExternalWrites(global: Node, context: ResolutionContext): { writes: Array<{ type: string; file: string }>; unknown: boolean; writers: Set<string> } {
  return pythonNameScan(context, `external\0${global.id}`, () => {
    const out = { writes: [] as Array<{ type: string; file: string }>, unknown: false, writers: new Set<string>() };
    const name = global.name;
    const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    for (const file of pythonWriteCandidates(name, context)) {
      if (file === global.filePath) continue;
      const test = isPythonTestFile(file);
      const { aliases, ambiguous } = pythonModuleAliases(file, global.filePath, context);
      if (!test && !aliases.length && !ambiguous.length) continue;
      const spell = (names: string[]) => `(?:${names.map(escape).join('|')})`;
      // Test files: any receiver (the double may sit on any spelling of the module).
      const receiver = test ? '[\\w.]+' : spell([...aliases, ...ambiguous]);
      const target = new RegExp(`(?<![\\w.])${receiver}\\.${escapeRegExp(name)}\\b(?!\\s*[.\\[(])`);
      const exact = new RegExp(`^${test ? receiver : spell(aliases.length ? aliases : ['\\0'])}\\.${escapeRegExp(name)}(?:\\s*:[^=]*)?$`);
      const dynamic = new RegExp(`\\b(?:setattr|patch\\.object)\\s*\\(\\s*${receiver}\\s*,\\s*['"]${escapeRegExp(name)}['"]` +
        `|(?<![\\w.])${receiver}\\.__dict__\\s*(?:\\[|\\.\\s*update\\s*\\()`);
      const lines = pythonMemberLines(file, context);
      const statements = pythonStatementStarts(file, context);
      const script = pythonMainBlockLines(file, context);
      for (let i = 0; i < lines.length; i++) {
        if (!statements[i] || script.has(i)) continue;
        let statement = lines[i]!;
        for (let j = i + 1; j < lines.length && !statements[j]; j++) statement += '\n' + lines[j];
        if (!statement.includes(name)) continue;
        const assignment = pythonAssignment(statement);
        const assigned = assignment?.targets.some(t => target.test(t.trim())) ?? false;
        if (!assigned && !dynamic.test(statement)) continue;
        if (test) { out.writers.add(file); continue; }
        // A write through an ambiguous spelling may land on another module: unknown.
        const single = assignment && assignment.targets.length === 1 && !assignment.augmented && exact.test(assignment.targets[0]!.trim());
        const value = single ? assignment!.value.trim() : '';
        if (value === 'None') continue;
        const constructor = value ? pythonConstructorCall(value) : null;
        if (!constructor) { out.unknown = true; return out; }
        out.writes.push({ type: constructor, file });
      }
    }
    return out;
  });
}

/**
 * The Python files that can write a module global named `name`, in path
 * order: those that spell it after a dot (`settings.conn = X`) or a quote
 * (`setattr(settings, "conn", X)`), and those that write through `.__dict__`,
 * whose statement may spell it anywhere. Comment stripping only blanks text,
 * so whatever a stripped statement spells, the file's text spells too. The
 * files are indexed once per pass, instead of every global reading every
 * Python file (#2332).
 */
function pythonWriteCandidates(name: string, context: ResolutionContext): string[] {
  const index = pythonNameScan(context, 'write-candidates', () => {
    const files = context.getAllFiles().filter(f => /\.pyi?$/.test(f));
    const spelled = new Map<string, number[]>();
    const dict: Array<{ at: number; words: string }> = [];
    files.forEach((file, at) => {
      const source = context.readFile(file) ?? '';
      const names = new Set<string>();
      for (const m of source.matchAll(/[.'"](\w+)/g)) names.add(m[1]!);
      for (const n of names) {
        const list = spelled.get(n);
        // A capture is a sliced view that would pin the file's whole text: key a flat copy.
        if (list) list.push(at); else spelled.set(Buffer.from(n).toString(), [at]);
      }
      // A word-only name is in the text exactly when it is in one of its words.
      if (names.has('__dict__')) dict.push({ at, words: [...new Set(source.match(/\w+/g))].join('\n') });
    });
    return { files, spelled, dict };
  });
  // The index holds ASCII words; any other name is looked for in every file's text.
  if (!/^\w+$/.test(name)) return index.files.filter(f => context.readFile(f)?.includes(name));
  const hits = new Set(index.spelled.get(name));
  for (const { at, words } of index.dict) if (words.includes(name)) hits.add(at);
  return [...hits].sort((a, b) => a - b).map(at => index.files[at]!);
}

/**
 * Whether the global's own module can write it through its namespace dict:
 * `globals()` / `vars()` / `sys.modules[__name__]` used as anything but a
 * literal-key read or `.get`, or a literal-key write of this name. Read per
 * statement (continuations joined), with string contents ignored.
 */
function pythonDynamicGlobalWrite(name: string, filePath: string, context: ResolutionContext): boolean {
  const lines = pythonMemberLines(filePath, context);
  const statements = pythonStatementStarts(filePath, context);
  const script = pythonMainBlockLines(filePath, context);
  // `vars()` is the module dict only at module scope; inside a function it is the locals.
  const moduleLines = new Set(pythonOwnLines(null, filePath, context));
  for (let i = 0; i < lines.length; i++) {
    if (!statements[i] || script.has(i)) continue;
    let statement = lines[i]!;
    for (let j = i + 1; j < lines.length && !statements[j]; j++) statement += '\n' + lines[j];
    const code = blankPythonStrings(statement);
    const namespace = moduleLines.has(i)
      ? /\bglobals\(\s*\)|\bvars\(\s*\)|\bsys\.modules\s*\[\s*__name__\s*\]/g
      : /\bglobals\(\s*\)|\bsys\.modules\s*\[\s*__name__\s*\]/g;
    const uses = code.match(namespace)?.length ?? 0;
    if (!uses) continue;
    const targets = pythonAssignment(statement)?.targets ?? [];
    let safe = 0;
    for (const m of statement.matchAll(/\bglobals\(\s*\)\s*(?:\[\s*(['"])(\w+)\1\s*\]|\.\s*get\s*\()/g)) {
      const key = m[2];
      const written = key !== undefined && targets.some(t => t.includes(m[0]));
      if (written && key === name) return true;
      safe++;
    }
    if (uses > safe) return true;
  }
  return false;
}

/**
 * What `receiver.member` reaches through a module-level instance of this
 * file — `_svc = SceneService()` at module scope, then `_svc.delete` (#2074)
 * or `_svc.delete(obj)` (#2582). Undefined when `receiver` is not that global
 * where the ref is: a parameter, a local, or a `def`/`class` written directly
 * in an enclosing function shadows it. Otherwise the one method or function every class the global
 * may hold has or inherits — never a property, an attribute or the referring
 * node itself (allowed for a `call`: recursion) — or null when there is none.
 */
function pythonGlobalReceiverTarget(
  receiver: string, member: string, ref: UnresolvedRef, context: ResolutionContext, call = false,
): Node | null | undefined {
  const global = pythonNameScan(context, `global\0${ref.filePath}\0${receiver}`, () =>
    context.getNodesInFile(ref.filePath).find(n => n.name === receiver && isPythonModuleGlobal(n, context)) ?? null);
  if (!global || pythonBindsLocally(receiver, ref, context, true)) return undefined;
  // A `def _svc` / `class _svc` nested in an enclosing function binds the name there.
  const nodes = context.getNodesInFile(ref.filePath);
  const scopes = nodes.filter(n => (n.kind === 'function' || n.kind === 'method') && n.startLine <= ref.line && n.endLine >= ref.line);
  const innermost = (n: Node) => nodes
    .filter(c => c.id !== n.id && (c.kind === 'function' || c.kind === 'method' || c.kind === 'class') &&
      c.startLine < n.startLine && c.endLine >= n.startLine)
    .sort((a, b) => b.startLine - a.startLine)[0];
  if (nodes.some(n => n.name === receiver && (n.kind === 'class' || n.kind === 'function') &&
      scopes.some(f => f.id === innermost(n)?.id))) return undefined;
  if (!pythonOwnGlobalWrites(global, context) || pythonExternalWrites(global, context).writers.has(ref.filePath)) {
    return null;
  }
  const classes = pythonGlobalClasses(global, ref, context);
  if (!classes) return null;
  // A class without the member (a base from outside the project may supply it) leaves it unknown.
  if (classes.some(cls => pythonMembers(cls, member, ref, context).length === 0)) return null;
  const pool = pythonGlobalMembers(global, member, ref, context).filter(n => sameLanguageFamily(n.language, ref.language));
  const target = pool.length === 1 ? pool[0]! : undefined;
  // A method value naming its own method is no reference; a call through the global is recursion.
  return target && (target.kind === 'function' || target.kind === 'method') && (call || target.id !== ref.fromNodeId) &&
    !isPythonProperty(target, context) ? target : null;
}

/**
 * The method a module global's value can dispatch to: one class resolves to
 * its own method; several bind to the nearest declaration they all inherit,
 * as a base-typed receiver does. Otherwise, no edge.
 */
function pythonGlobalMembers(global: Node, member: string, ref: UnresolvedRef, context: ResolutionContext): Node[] {
  // Unknown from its own module alone: no edge, and no other module to read.
  if (!pythonOwnGlobalWrites(global, context)) return [];
  // A test that installs its own double sees the double, not the production type.
  if (pythonExternalWrites(global, context).writers.has(ref.filePath)) return [];
  const classes = pythonGlobalClasses(global, ref, context);
  if (!classes) return [];
  const targets = [...new Map(classes.flatMap(cls => pythonMembers(cls, member, ref, context)).map(n => [n.id, n])).values()];
  if (targets.length <= 1) return targets;
  // Several targets: the nearest declaration every candidate class inherits,
  // whether or not a candidate overrides it.
  const owner = (n: Node) => context.getNodesInFile(n.filePath).find(c =>
    c.kind === 'class' && n.qualifiedName === `${c.qualifiedName}::${member}`);
  const declarations = new Map<string, { decl: Node; cls: Node }>();
  const queue = [...targets];
  while (queue.length && declarations.size < 32) {
    const decl = queue.shift()!;
    const cls = decl && owner(decl);
    if (!cls || declarations.has(decl.id)) continue;
    declarations.set(decl.id, { decl, cls });
    queue.push(...pythonBases(cls, ref, context).flatMap(base => pythonMembers(base, member, ref, context)));
  }
  const inherits = (cls: Node, base: Node) => cls.id === base.id || pythonDerivesFrom(cls, base, ref, context);
  const shared = [...declarations.values()].filter(d => classes.every(c => inherits(c, d.cls)));
  const nearest = shared.filter(d => shared.every(o => inherits(d.cls, o.cls)));
  return nearest.length === 1 ? [nearest[0]!.decl] : targets;
}

/** `Cls(...)` / `pkg.mod.Cls(...)` as the WHOLE (possibly multi-line) value; else null (`Cls() if x else y`). */
function pythonConstructorCall(text: string): string | null {
  // `(Cls())` is the same value; peel parentheses that wrap the whole expression.
  for (let wrapped = text.trim(); wrapped.startsWith('('); ) {
    let depth = 0;
    let close = -1;
    for (let i = 0; i < wrapped.length && close < 0; i++) {
      if (wrapped[i] === '(') depth++;
      else if (wrapped[i] === ')' && --depth === 0) close = i;
    }
    if (close !== wrapped.length - 1) break;
    text = wrapped = wrapped.slice(1, -1).trim();
  }
  const callee = text.match(/^((?:[A-Za-z_]\w*\.)*[A-Z]\w*)\s*\(/);
  if (!callee) return null;
  let depth = 0;
  let quote = '';
  for (let i = callee[0].length - 1; i < text.length; i++) {
    const c = text[i]!;
    if (quote) { if (c === '\\') i++; else if (c === quote) quote = ''; continue; }
    if (c === '"' || c === "'") quote = c;
    else if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') {
      if (--depth === 0) return /^[\s\\]*$/.test(text.slice(i + 1)) ? callee[1]! : null;
    }
  }
  return null;
}

/** Read a field's own annotation/initializer, or a constructor parameter assigned to it. */
function pythonFieldType(receiver: string, owner: Node, ref: UnresolvedRef, context: ResolutionContext): string | null {
  const lines = pythonMemberLines(ref.filePath, context);
  const field = receiver.split('.')[1]!;
  const assignment = new RegExp(`^\\s*(?:self|cls)\\.${escapeRegExp(field)}\\s*(?::\\s*["']?([\\w.]+)["']?)?\\s*=\\s*(.*)$`);
  const annotation = new RegExp(`^\\s*(?:(?:self|cls)\\.)?${escapeRegExp(field)}\\s*:\\s*["']?([\\w.]+)`);
  const methods = context.getNodesInFile(ref.filePath).filter(n => n.kind === 'method' &&
    n.qualifiedName.startsWith(`${owner.qualifiedName}::`));
  const types = new Set<string>();
  for (let i = owner.startLine; i < owner.endLine; i++) {
    const method = methods.find(n => n.startLine <= i + 1 && n.endLine >= i + 1);
    if (method && method.name !== '__init__' && method.id !== ref.fromNodeId) continue;
    if (method?.id === ref.fromNodeId && i + 1 > ref.line) continue;
    const line = lines[i] ?? '';
    const declared = !method || /^\s*(?:self|cls)\./.test(line) ? line.match(annotation)?.[1] : undefined;
    if (declared) types.add(declared);
    const assigned = line.match(assignment);
    if (!assigned) continue;
    if (assigned[1]) { types.add(assigned[1]); continue; }
    const constructor = assigned[2]!.match(/^([A-Z][\w.]*)\s*\(/)?.[1];
    if (constructor) { types.add(constructor); continue; }
    const param = assigned[2]!.trim();
    if (method && /^\w+$/.test(param)) {
      const signature = method.signature ?? '';
      const type = signature.match(new RegExp(`\\b${param}\\s*:\\s*["']?([\\w.]+)`))?.[1];
      if (type) types.add(type);
    } else {
      types.add('<unknown>');
    }
  }
  // Conflicting assignments are known-but-ambiguous, never a name-only fallback.
  return types.size === 1 ? [...types][0]! : types.size > 1 ? '<ambiguous>' : null;
}

/**
 * Resolve a function-as-value reference (#756) — a function name used as a
 * callback/function-pointer value (`register(handler)`, `o->cb = handler`,
 * `{ .cb = handler }`, `signal(SIGINT, handler)`). The ONLY strategy allowed
 * for `function_ref` refs: exact name, function/method targets only, same
 * language family, same-file first for bare names, and unique-only cross-file.
 * Member values use receiver/type/import scope before a unique-name fallback.
 * A wrong callback edge is worse than none.
 */
export function matchFunctionRef(
  ref: UnresolvedRef,
  context: ResolutionContext
): ResolvedRef | null {
  // `this.<member>` refs are resolved ONLY by the class-scoped resolver in
  // resolveOne (resolveThisMemberFnRef) — never by name matching here.
  if (ref.referenceName.startsWith('this.')) return null;

  if ((ref.language === 'python' || ref.language === 'go') && ref.referenceName.includes('.')) {
    return matchMemberFunctionRef(ref, context);
  }

  // In JS/TS/Python a bare identifier can never be a method value (methods
  // are only reachable through a receiver — `this.m` / `self.m` /
  // `Cls.m`), so bare fn-refs match FUNCTIONS only. This also sidesteps the
  // pre-existing TS quirk of class fields extracting as method-kind nodes,
  // which otherwise soaked up local names passed as arguments (excalidraw
  // A/B finding; same pattern in vendored docopt.py). Python's `self.m`
  // form keeps method targets via its own capture shape. C++ likewise: a
  // bare identifier can only be a FREE function (member values need
  // `&Cls::method`). PHP string callables name global FUNCTIONS (methods
  // need the `[$obj, 'm']` array form, which carries its own shape). Other
  // languages keep method targets: C# method groups, Swift/Dart
  // implicit-self, Java/Kotlin method references.
  const bareFnOnly =
    ref.language === 'typescript' || ref.language === 'tsx' ||
    ref.language === 'javascript' || ref.language === 'jsx' ||
    ref.language === 'arkts' ||
    ref.language === 'cpp' || ref.language === 'python' ||
    ref.language === 'php';

  // Python additionally accepts CLASS targets for bare identifiers (#1478):
  // class-as-value is a core Python idiom (`return SomeSerializer`,
  // `Meta.model = Org`, registry dicts, `admin.site.register(Model, Admin)`)
  // and, unlike TS, Python has no type-annotation recovery path. The
  // false-positive mechanism behind the function-only rule was lowercase
  // locals colliding with same-named METHODS (docopt.py) — a candidate must
  // be an exact-name CLASS node here, and the extraction gate (same-file
  // class ∪ imports) plus unique-or-drop still apply. Methods stay excluded.
  const bareClassOk = ref.language === 'python';

  // Qualified member-pointer (`&Widget::on_click` → "Widget::on_click"):
  // resolve the member ON THAT SCOPE — exempt from bareFnOnly (the `&Cls::m`
  // shape is an explicit member reference). Unique-or-drop like everything else.
  if (ref.referenceName.includes('::')) {
    const memberName = ref.referenceName.slice(ref.referenceName.lastIndexOf('::') + 2);
    const scoped = context
      .getNodesByName(memberName)
      .filter(
        (n) =>
          (n.kind === 'function' || n.kind === 'method') &&
          sameLanguageFamily(n.language, ref.language) &&
          n.id !== ref.fromNodeId &&
          (n.qualifiedName === ref.referenceName ||
            n.qualifiedName.endsWith(`::${ref.referenceName}`))
      );
    if (scoped.length === 0) return null;
    const sameFileScoped = scoped.filter((n) => n.filePath === ref.filePath);
    const pool = sameFileScoped.length > 0 ? sameFileScoped : scoped;
    if (sameFileScoped.length === 0 && scoped.length > 1) return null;
    const target = pool.reduce((a, b) => (a.startLine <= b.startLine ? a : b));
    return {
      original: ref,
      targetNodeId: target.id,
      confidence: 0.9,
      resolvedBy: 'function-ref',
    };
  }

  const named = context
    .getNodesByName(ref.referenceName)
    .filter(
      (n) =>
        (n.kind === 'function' ||
          (!bareFnOnly && n.kind === 'method') ||
          (bareClassOk && n.kind === 'class')) &&
        sameLanguageFamily(n.language, ref.language) &&
        n.id !== ref.fromNodeId // a function registering itself is not a dependency edge
    );
  // A function declared inside another is in scope only in there: httpx's
  // `self._build_auth(auth)` passes its own parameter, not the `auth` a test
  // defines inside `test_custom_auth`. Those still count against a lone
  // cross-file guess below — a name several functions use for themselves is
  // as likely a local's.
  let candidates = named.filter((n) => isLexicallyReachable(n, ref, context) &&
    // A Dart constructor is torn off through its class, never by a bare name.
    !isDartConstructor(n, context));
  if (candidates.length === 0) return null;
  // A Python name the function around it binds — a parameter, an assignment —
  // is that local's value: httpx's `auth_flow(self, request)` handing `request`
  // on is not the package's `request()` function. A pytest fixture is what a
  // test's parameter of its name receives.
  if (ref.language === 'python' && !candidates.some((n) => isFixtureInReach(n, ref.filePath, context)) &&
      isPythonLocallyBound(ref.referenceName, ref, context)) return null;
  // Likewise a JS/TS parameter or local: lodash's `baseHas(object, key)` passes its own `object`.
  const jsLocal = jsFunctionLocalScope(ref.referenceName, ref, context);
  if (jsLocal) {
    candidates = candidates.filter((n) => n.filePath === ref.filePath && n.startLine >= jsLocal.start && n.startLine <= jsLocal.end);
    if (candidates.length === 0) return null;
  }

  // Swift implicit-self: a bare identifier can name a METHOD only of the
  // ENCLOSING type (`Button(action: handleTap)` written inside that type) —
  // a same-named method on any OTHER class is a parameter collision
  // (Alamofire: a `request` parameter resolving to EventMonitor::request).
  // Scope method candidates to the from-symbol's type; top-level code has no
  // implicit self, so method targets are excluded there entirely. Free
  // functions are unaffected.
  if (ref.language === 'swift' && candidates.some((n) => n.kind === 'method')) {
    const fromNode = context.getNodeById?.(ref.fromNodeId);
    const sep = fromNode ? fromNode.qualifiedName.lastIndexOf('::') : -1;
    const classPrefix = fromNode && sep > 0 ? fromNode.qualifiedName.slice(0, sep) : null;
    candidates = candidates.filter((n) => {
      if (n.kind !== 'method') return true;
      if (!classPrefix) return false;
      const mSep = n.qualifiedName.lastIndexOf('::');
      if (mSep <= 0) return false;
      const methodPrefix = n.qualifiedName.slice(0, mSep);
      // Accept exact-scope matches plus suffix relationships either way, so
      // extension-declared members (`Holder::m`) still match a nested
      // from-scope (`Module::Holder::wire`) and vice versa.
      return (
        methodPrefix === classPrefix ||
        methodPrefix.endsWith(`::${classPrefix}`) ||
        classPrefix.endsWith(`::${methodPrefix}`)
      );
    });
    if (candidates.length === 0) return null;
  }

  // Same-file definition wins — the extraction gate guarantees most survivors
  // have one, and it's the dominant C pattern (static callback registered in
  // a same-file ops struct).
  const sameFile = candidates.filter((n) => n.filePath === ref.filePath);
  if (sameFile.length > 0) {
    // Swift: several same-named METHODS in one file is an API overload family
    // (`Session.request(...)` × N), and a bare identifier hitting it is almost
    // always a same-named parameter, not a method value (Alamofire A/B
    // finding) — refuse rather than guess. A single method (SwiftUI's
    // `action: handleTap`) still resolves.
    if (
      ref.language === 'swift' &&
      sameFile.length > 1 &&
      sameFile.every((n) => n.kind === 'method')
    ) {
      return null;
    }
    // Same-name overloads in one file are the same conceptual symbol; pick
    // the first by position for determinism.
    const target = sameFile.reduce((a, b) => (a.startLine <= b.startLine ? a : b));
    return {
      original: ref,
      targetNodeId: target.id,
      confidence: sameFile.length === 1 ? 0.95 : 0.9,
      resolvedBy: 'function-ref',
    };
  }

  // Cross-file (imported names the import resolver didn't already claim):
  // only an unambiguous match resolves — or, in Python, the one in reach of
  // a name the file imports (netbox's `sender=CustomField` beside a test's
  // own nested `CustomField`). Never a name the file imports from a package
  // outside the repository, which no project function is: outline's
  // `styled(Link)`, with `Link` from react-router-dom, is not an email
  // template's `Link`, nor is cord-field's lodash `noop` a test's own stub.
  // Nor a name a project import binds to something else (importBindsOther).
  if (candidates.length === 1 && (named.length === 1 ||
      (ref.language === 'python' && pythonFromImports(ref.filePath, context).has(ref.referenceName))) &&
      !(JS_FAMILY.has(ref.language) && isOutOfRepoBinding(ref.referenceName, ref, context)) &&
      !(JS_FAMILY.has(ref.language) && importBindsOther(candidates[0]!, ref, context))) {
    return {
      original: ref,
      targetNodeId: candidates[0]!.id,
      confidence: 0.8,
      resolvedBy: 'function-ref',
    };
  }
  return null;
}

/** Languages with no nested named functions: nesting in the graph is never a scope. */
const NO_NESTED_FUNCTIONS = new Set<string>(['c', 'cpp']);
/** Types a function body can declare for itself. */
const LOCAL_TYPE_KINDS = new Set<string>(['class', 'struct', 'enum', 'interface', 'trait', 'type_alias']);

/**
 * A function nested inside another FUNCTION is only callable from within its
 * container — Python, JS/TS, and every closure language scope it lexically.
 * Resolving a bare name from elsewhere to a nested local fabricates an edge
 * scope already rules out: `join(...)` in one function must never bind to a
 * `join` defined inside a DIFFERENT function (#1230). A candidate whose
 * qualifiedName parent is a same-file function/method is kept only when the
 * ref originates inside that parent's line range. Class members are
 * unaffected (their parent resolves to a class-like node), as are top-level
 * symbols and C++ namespace-prefixed names (the prefix has no node).
 */
export function isLexicallyReachable(
  candidate: Node,
  ref: UnresolvedRef,
  context: ResolutionContext
): boolean {
  // An anonymous class's member — Java's `new Listener() { … }`, Kotlin's
  // `object : Listener { … }` — is named only inside the declaration holding
  // the class: a bare `block()` elsewhere is never the `override val block` of
  // an object a private property holds. Its overrides are reached through the
  // type it implements.
  const anon = candidate.qualifiedName.includes('$anon@') ? ANON_MEMBER_QN.exec(candidate.qualifiedName) : null;
  if (anon) {
    if (ref.filePath !== candidate.filePath) return false;
    // The holder is the declaration of that name around the class's own line
    // (overloads share the name).
    const at = Number(anon[2]);
    let holders = context.getNodesByQualifiedName(anon[1]!)
      .filter((n) => n.filePath === candidate.filePath && n.startLine <= at && (n.endLine ?? n.startLine) >= at);
    // A Kotlin extension function is named by its receiver (`Call::asObservable`),
    // not by the path its object's members carry (`pkg::asObservable`): then
    // the innermost declaration around the class's line holds it.
    if (holders.length === 0) {
      const around = context.getNodesInFile(candidate.filePath).filter((n) =>
        ANON_HOLDER_KINDS.has(n.kind) && n.startLine <= at && (n.endLine ?? n.startLine) >= at && !n.qualifiedName.includes('$anon@'));
      const innermost = around.sort((x, y) => y.startLine - x.startLine)[0];
      if (innermost) holders = [innermost];
    }
    return holders.length === 0 || holders.some((n) => ref.line >= n.startLine && ref.line <= (n.endLine ?? n.startLine));
  }
  // An object literal's member is reached through its object (#2300): a bare
  // `load()` or `setTimeout(load)` never means `App.load`, whatever shares
  // the name — see isObjectMemberReachableByName for the ways that do.
  if (candidate.kind === 'function' && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName) &&
      !isObjectMemberReachableByName(candidate, ref, context)) return false;
  // An object hung on a path (`App.utils = {…}`, `$.event.special.swipe =
  // {…}`) is a property, not a binding: no bare name reaches it — a
  // `this.swipe()` elsewhere is not that object. One hung on the global object
  // (`window.App = {…}`) is the global `App`.
  if (isPathHolder(candidate) && isObjectLiteralOwner(candidate) && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName) &&
      !HOST_GLOBAL_PREFIX.test(lastQualifiedSegment(candidate.qualifiedName))) return false;
  // A `val` / `const` declared in a function body is that body's alone —
  // okio's `(source as Source).buffer()` bound to a `val buffer = Buffer()`
  // inside another test file's `pipe()`.
  if (candidate.kind === 'variable' || candidate.kind === 'constant' || (candidate.kind === 'field' && candidate.language === 'scala')) {
    const scope = localDeclarationScope(candidate, context);
    return scope === null || (ref.filePath === candidate.filePath && ref.line >= scope.start && ref.line <= scope.end);
  }
  // A function — or a type (`case class B()` in a test method), or a method
  // of such a type — declared inside a function is only in scope in there.
  if (candidate.kind !== 'function' && candidate.kind !== 'method' && !LOCAL_TYPE_KINDS.has(candidate.kind)) return true;
  // C and C++ have no nested named functions, so a function the graph shows
  // inside another is an extraction artifact, not a scope: tree-sitter-c
  // cannot parse a macro call whose arguments are designated initializers
  // (betaflight's `RESET_CONFIG(pidProfile_t, pidProfile, .pid = {…})`), and
  // its error recovery runs the enclosing function_definition to the end of
  // the file, nesting every function after it. Trusting that nesting rejected
  // 117 real calls into pid.c on that tree; the functions are reachable.
  if (NO_NESTED_FUNCTIONS.has(candidate.language)) return true;
  const scope = lexicalScopeOf(candidate, context);
  return scope === null || (ref.filePath === candidate.filePath && ref.line >= scope.start && ref.line <= scope.end);
}

/** A qualified name through an anonymous class: the declaration holding it, then `::<T$anon@line>`. */
const ANON_MEMBER_QN = /^(.+?)::<[^<>:]*\$anon@(\d+)>(?:::|$)/;
/** Declarations an anonymous class can be written in. */
const ANON_HOLDER_KINDS = new Set<Node['kind']>(['function', 'method', 'constant', 'field', 'variable', 'property']);

/** An anonymous class — Java's `new T() { … }`, Kotlin's `object : T { … }` — named `<T$anon@line>`. */
function isAnonymousClass(n: Node): boolean {
  return n.name.startsWith('<') && n.name.includes('$anon@');
}

/** A member of an anonymous class: its qualified name passes through `<T$anon@line>`. */
function isAnonymousMember(n: Node): boolean {
  return n.qualifiedName.includes('$anon@') && ANON_MEMBER_QN.test(n.qualifiedName);
}

/** How many anonymous classes a qualified name passes through. */
function anonymousDepth(qualifiedName: string): number {
  let count = 0;
  for (let i = qualifiedName.indexOf('$anon@'); i >= 0; i = qualifiedName.indexOf('$anon@', i + 6)) count++;
  return count;
}

/** Per context: node id → the function body (or Scala block) a declaration is local to. */
const LOCAL_DECL_MEMO = new WeakMap<ResolutionContext, Map<string, { start: number; end: number } | null>>();

/**
 * The lines a variable declaration is in scope for when it is local: the
 * innermost function or method of its file whose lines hold it — or, for a
 * Scala `val` the graph files under its class but written inside a block of
 * the class body (cats' `test("…") { val f = … }`), that block. Null for a
 * declaration at file, class or object level. A Lua global assigned inside a
 * function is still global; C and C++ nesting is not trusted (see below).
 */
function localDeclarationScope(candidate: Node, context: ResolutionContext): { start: number; end: number } | null {
  if (NO_NESTED_FUNCTIONS.has(candidate.language)) return null;
  let memo = LOCAL_DECL_MEMO.get(context);
  if (!memo) LOCAL_DECL_MEMO.set(context, (memo = new Map()));
  const hit = memo.get(candidate.id);
  if (hit !== undefined) return hit;
  let scope: { start: number; end: number } | null = null;
  if (!((candidate.language === 'lua' || candidate.language === 'luau') && !isLuaLocal(candidate, context))) {
    for (const n of context.getNodesInFile(candidate.filePath)) {
      if ((n.kind !== 'function' && n.kind !== 'method') || n.id === candidate.id) continue;
      if (n.startLine > candidate.startLine || n.endLine < candidate.startLine || n.startLine === n.endLine) continue;
      if (n.startLine === candidate.startLine && (n.startColumn ?? 0) >= (candidate.startColumn ?? 0)) continue;
      if (!scope || n.endLine - n.startLine < scope.end - scope.start) scope = { start: n.startLine, end: n.endLine };
    }
    if (!scope && candidate.kind === 'field' && candidate.language === 'scala') scope = scalaBlockOf(candidate, context);
  }
  memo.set(candidate.id, scope);
  return scope;
}

/** The `{ … }` block, deeper than its class body, that a Scala `val` is written in; null for a member. */
function scalaBlockOf(candidate: Node, context: ResolutionContext): { start: number; end: number } | null {
  const owner = candidate.qualifiedName.includes('::') ? candidate.qualifiedName.slice(0, candidate.qualifiedName.lastIndexOf('::')) : '';
  const cls = context.getNodesInFile(candidate.filePath).find((n) =>
    n.qualifiedName === owner && (n.kind === 'class' || n.kind === 'trait' || n.kind === 'struct' || n.kind === 'module'));
  if (!cls || cls.startLine >= candidate.startLine) return null;
  const lines = context.getFileLines?.(candidate.filePath) ?? context.readFile(candidate.filePath)?.split(/\r?\n/) ?? [];
  const clean = (l: string) => l.replace(/"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)'/g, '""').replace(/\/\/.*$/, '');
  // Depth at the start of each line, counted from the class header; the body is depth 1.
  const opens: number[] = [];
  let depth = 0;
  for (let line = cls.startLine; line < candidate.startLine; line++) {
    for (const ch of clean(lines[line - 1] ?? '')) {
      if (ch === '{') { depth++; opens.push(line); }
      else if (ch === '}') { depth = Math.max(0, depth - 1); opens.pop(); }
    }
  }
  if (depth <= 1) return null;
  const start = opens[opens.length - 1]!;
  let d = depth;
  for (let line = candidate.startLine; line <= cls.endLine; line++) {
    for (const ch of clean(lines[line - 1] ?? '')) {
      if (ch === '{') d++;
      else if (ch === '}' && --d < depth) return { start, end: line };
    }
  }
  return { start, end: cls.endLine };
}

/** Per context: a candidate's scoping function body, or null when nothing scopes it. */
const LEXICAL_SCOPE_MEMO = new WeakMap<ResolutionContext, Map<string, { start: number; end: number } | null>>();

/**
 * The innermost function or method BODY that scopes a declaration, walking out
 * through its qualified name (`test_x::Request::User::has_perm` → `test_x`).
 * A method directly on a class is reachable through its instances, and an
 * object-literal method a function returns through the object — neither is
 * scoped by the function it sits in.
 */
function lexicalScopeOf(candidate: Node, context: ResolutionContext): { start: number; end: number } | null {
  let memo = LEXICAL_SCOPE_MEMO.get(context);
  if (!memo) {
    memo = new Map();
    LEXICAL_SCOPE_MEMO.set(context, memo);
  }
  const hit = memo.get(candidate.id);
  if (hit !== undefined) return hit;
  let scope: { start: number; end: number } | null = null;
  const own = candidate.qualifiedName ?? '';
  const parentQn = own.includes('::') ? own.slice(0, own.lastIndexOf('::')) : '';
  let qn = own;
  while (qn.includes('::')) {
    qn = qn.slice(0, qn.lastIndexOf('::'));
    const container = context
      .getNodesByQualifiedName(qn)
      .find(
        (p) =>
          p.filePath === candidate.filePath &&
          (p.kind === 'function' || p.kind === 'method') &&
          p.startLine <= candidate.startLine &&
          p.endLine >= candidate.endLine
      );
    if (!container) continue;
    if (candidate.kind === 'method' && qn === parentQn) break;
    scope = { start: container.startLine, end: container.endLine };
    break;
  }
  memo.set(candidate.id, scope);
  return scope;
}

/** Languages whose module boundary is `import`/`export` (or CommonJS). */
const ESM_FAMILY = new Set<string>(['typescript', 'tsx', 'javascript', 'jsx', 'arkts']);

/**
 * The ES-module family with single-file components' script blocks: a file
 * declaring the class an import names (tsImportedTypeFile) is the same
 * signal in each.
 */
const ES_IMPORT_LANGUAGES = new Set<string>([...ESM_FAMILY, 'vue', 'svelte', 'astro']);

/**
 * A line-initial `import` statement — the marker that a JS/TS file is a MODULE
 * rather than a classic script. Line-anchored and followed by a name, brace,
 * star or quote, so a dynamic `import(` and the word inside a comment or string
 * do not match.
 */
const HAS_IMPORT_STATEMENT = /^[ \t]*import[\s{*'"]/m;

/**
 * Anything the file could offer another file, in every form the extractor's own
 * `isExported` flag misses. `^export` covers the declaration and later forms
 * (`export const`, `export { x }`, `export default x`, `export *`); the
 * CommonJS shapes cover files that never use ESM syntax at all, in both the dot
 * and the bracket form; and `declare global` contributes names to every file
 * whether or not the module exports anything of its own. Kept as a source test
 * rather than a node scan precisely because `isExported` is set only where a
 * declaration is written (an `export_statement` around it, or a `declare
 * module` / `declare global` body), so `const x = …; export { x }` and
 * `module.exports = { x }` both read as unexported on the node.
 */
const HAS_ESM_EXPORT = /^[ \t]*export[\s{*]|^[ \t]*declare\s+global\b/m;
const HAS_CJS_EXPORT = /\bmodule\.exports\b|\bexports\s*[.[]/;

/**
 * Per-context memo of "this file is a module that exports nothing", asked once
 * per candidate FILE rather than once per reference. Derived from file source,
 * so it drops with the context's file caches — clearNameMatcherMemos deletes it
 * alongside INFER_SCAN_STATES.
 */
const SEALED_MODULES = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether `filePath` is a JS/TS module that exports NOTHING — an import
 * statement present, no export of any form. No reference from another file can
 * reach any binding in such a file, so every one of its symbols is a false
 * candidate for a cross-file name match.
 *
 * This is the general case behind a package name capturing a same-named local:
 * on `vitejs/vite`, 157 cross-file `imports` refs — every `import { defineConfig
 * } from 'vite'` in the playground and the create-vite templates — resolved onto
 * `playground/ssr-html/test-stacktrace.js::vite`, which is `const vite = await
 * createServer(…)` at module scope in a file with zero exports. The existing
 * guards cannot see it: `isLexicallyReachable` returns early for any candidate
 * that is not a `function`, and the bare-import guard correctly declines because
 * `vite` IS a workspace member, so the specifier really is project-local. What
 * is wrong is only which node the name lands on.
 *
 * Deliberately narrow on three axes, because each is a class this would
 * otherwise resolve wrongly in the opposite direction:
 *
 * - **A classic script is exempt.** Requiring an `import` statement means a
 *   non-module `.js` file — concatenated globals, a browser `<script>` — keeps
 *   its cross-file matches, where a top-level binding genuinely is reachable.
 * - **CommonJS is exempt.** `module.exports` and `exports.x` are matched as
 *   exports, so a CJS file is never sealed.
 * - **Other languages are exempt.** Go, Python, Java and the rest have no
 *   equivalent boundary, and several extractors hardcode `isExported`.
 */
function isSealedModule(filePath: string, context: ResolutionContext): boolean {
  let memo = SEALED_MODULES.get(context);
  if (!memo) {
    memo = new Map();
    SEALED_MODULES.set(context, memo);
  }
  const hit = memo.get(filePath);
  if (hit !== undefined) return hit;
  // CommonJS assignments can execute inside template interpolations, which the
  // masker blanks. Keep the conservative raw-source exemption for those forms.
  // Cheapest disqualifiers first: nearly every module exports a node (asked
  // without reading or decoding the file), and masking the source is only
  // needed to rule out the ones that don't. (The masker only blanks text, so
  // no `import` in the source means none in code.)
  const exportsNode = context.fileHasExportedNode
    ? context.fileHasExportedNode(filePath)
    : context.getNodesInFile(filePath).some((n) => n.isExported);
  const source = exportsNode ? null : context.readFile(filePath);
  const sealed =
    !exportsNode && source !== null && source.includes('import') &&
    !HAS_CJS_EXPORT.test(source) &&
    (() => {
      const code = blankStringContents(stripCommentsForRegex(source, 'typescript'));
      return HAS_IMPORT_STATEMENT.test(code) && !HAS_ESM_EXPORT.test(code);
    })();
  memo.set(filePath, sealed);
  return sealed;
}

/** A TypeScript or JavaScript source file, read as such (an SFC's markup is not). */
const TS_JS_FILE = /\.[cm]?[jt]sx?$/i;

/** Per-context memo: file → where it declares into the global scope (null when unreadable). */
const TS_GLOBAL_SCOPES = new WeakMap<ResolutionContext, Map<string, GlobalScopeScan | null>>();

/** scanGlobalScope of `file`, a CommonJS file's top level counting as its own. */
export function tsGlobalScope(file: string, context: ResolutionContext): GlobalScopeScan | null {
  let memo = TS_GLOBAL_SCOPES.get(context);
  if (!memo) TS_GLOBAL_SCOPES.set(context, (memo = new Map()));
  let scope = memo.get(file);
  if (scope === undefined) {
    const source = context.readFile(file);
    scope = source === null ? null : scanGlobalScope(source);
    if (scope?.script && HAS_CJS_EXPORT.test(source!)) scope = { ...scope, script: false, globalWords: new Set() };
    memo.set(file, scope);
  }
  return scope;
}

/**
 * Whether a type written as a bare name the file doesn't import, in an ES
 * module, may be `n`: a declaration of the file's own, or a global one — at a
 * script's top level (a file with no import or export, a script `.d.ts`) or
 * directly inside `declare global`. A module's own declaration, exported or
 * not, is reached only through an import, which the import resolver has
 * followed already, and a namespace's member is no global. So `extends
 * Omit<…>` and `options: Omit<IPickOptions, 'canPickMany'>` are TypeScript's
 * `Omit`, never vscode's `export type Omit` in quickInput.ts, and `extends
 * Function` never terminal-suggest's `Fig.Function`.
 *
 * The globals project code relies on come from declaration files and
 * `declare global` blocks. A script `.ts` is a sample or a fixture whose top
 * level is global only to its own program — vscode's colorize fixtures
 * declare `type T` and copilot's eslint fixtures `interface Node` — and a
 * test's or fixture's globals are its tests' only, as its `declare module`
 * blocks are (see ambient-modules.ts).
 */
function isTsTypeInScope(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (n.filePath === ref.filePath || !TS_JS_FILE.test(n.filePath)) return true;
  const scope = tsGlobalScope(n.filePath, context);
  if (!scope) return true;
  if ((scope.script && !isDeclarationFile(n.filePath)) || (isTestFile(n.filePath) && !isTestFile(ref.filePath))) return false;
  return scope.globalWords.has(`${n.startLine}:${n.startColumn}`);
}

/**
 * Whether `ref` names a type by a bare name its ES module doesn't import
 * (isTsTypeInScope): a supertype, or a type annotation's or type argument's
 * name, which TS and JS files record as `references` and nothing else does.
 * The last name of a qualified type, `vscode.TextDocument`, is no bare name,
 * and neither is a name inside a `declare module 'x'` block, which is module
 * `x`'s own: legend-state's augmentation of `'@legendapp/state/react'` writes
 * that module's `FCReactive` without importing it. An `import X = ns.X`
 * alias imports its name.
 */
function isTsBareTypeName(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const typeRef = ref.referenceKind === 'references';
  if (!(typeRef || isInheritanceRef(ref)) || !JS_FAMILY.has(ref.language) || !TS_JS_FILE.test(ref.filePath) ||
      !/^[A-Za-z_$][\w$]*$/.test(ref.referenceName) ||
      context.getImportMappings(ref.filePath, ref.language).some((m) => m.localName === ref.referenceName) ||
      (typeRef && isWrittenQualified(ref, context))) return false;
  const scope = tsGlobalScope(ref.filePath, context);
  const at = { startLine: ref.line, startColumn: ref.column };
  return scope?.script === false && !scope.importAliases.has(ref.referenceName) &&
    !scope.moduleBlocks.some((block) => inBlock(at, block));
}

/**
 * Whether a name recorded alone was written after a `.`, as the last name of
 * `ns.Type` or `import('x').Type` is. A column that doesn't find the name on
 * its line counts as written so, which leaves the reference as it was.
 */
function isWrittenQualified(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1] ?? '';
  if (!line.startsWith(ref.referenceName, ref.column)) return true;
  let i = ref.column - 1;
  while (i >= 0 && (line[i] === ' ' || line[i] === '\t')) i--;
  return line[i] === '.';
}

/**
 * Whether `candidate` can be named by a reference in `ref`'s file at all.
 * Both name-based strategies validate their chosen candidate. Removing an
 * unreachable candidate before ranking can promote an unrelated runner-up;
 * rejecting the chosen target must leave the reference unresolved instead.
 */
function isCrossFileReachable(
  candidate: Node,
  ref: UnresolvedRef,
  context: ResolutionContext
): boolean {
  if ((ref.language as string) !== 'markdown' && (candidate.language as string) === 'markdown') return false;
  if (ref.referenceKind === 'calls' && ESM_FAMILY.has(candidate.language) &&
    (candidate.kind === 'constant' || candidate.kind === 'variable') &&
    /^=\s*require\s*\(\s*(['"])[^'"]+\.json\1\s*\)\s*;?\s*$/.test(candidate.signature ?? '')) return false;
  return (
    candidate.filePath === ref.filePath ||
    !ESM_FAMILY.has(candidate.language) ||
    (!isSealedModule(candidate.filePath, context) && !isUnexportedModuleBinding(candidate, context))
  );
}

const ESM_BINDING_KINDS: ReadonlySet<string> = new Set(['function', 'variable', 'constant', 'class', 'interface', 'type_alias', 'enum', 'component']);
const ESM_EXPORT_LISTS = new WeakMap<ResolutionContext, Map<string, { module: boolean; names: Set<string> }>>();

/**
 * Whether `candidate` is a top-level binding of an ES module that the module
 * doesn't export — declared without `export` and absent from its `export { … }`
 * / `export default x` lists. No other file can name it. The sealed-module
 * rule above covers files that export nothing; this is the same boundary per
 * symbol: sveltekit's `generate_manifest.js` keeps an unexported `resolve`
 * that twenty other files' `resolve(…)` calls went to. Classic scripts,
 * CommonJS, `declare global` and `.d.ts` files, members of a class or
 * namespace (qualified names), names a default-exported or returned object
 * literal lists,
 * and anything not declared by a statement of its own (an object literal's
 * member, `proto.x = function x() {}`) are exempt.
 */
function isUnexportedModuleBinding(candidate: Node, context: ResolutionContext): boolean {
  if (candidate.isExported || !ESM_BINDING_KINDS.has(candidate.kind)) return false;
  if (candidate.qualifiedName.includes('::') || /\.d\.[cm]?ts$/.test(candidate.filePath)) return false;
  let memo = ESM_EXPORT_LISTS.get(context);
  if (!memo) ESM_EXPORT_LISTS.set(context, (memo = new Map()));
  let info = memo.get(candidate.filePath);
  if (!info) {
    const source = context.readFile(candidate.filePath) ?? '';
    const code = blankStringContents(stripCommentsForRegex(source, 'typescript'));
    const module = (HAS_IMPORT_STATEMENT.test(code) || HAS_ESM_EXPORT.test(code)) &&
      !HAS_CJS_EXPORT.test(source) && !/\bdeclare\s+global\b/.test(code);
    const names = new Set<string>();
    if (module) {
      for (const m of source.matchAll(/^[ \t]*export\s+(?:type\s+)?\{([^}]*)\}/gm)) {
        for (const item of m[1]!.split(',')) {
          const local = item.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0]!.trim();
          if (local) names.add(local);
        }
      }
      for (const m of source.matchAll(/^[ \t]*export\s+(?:default|=)\s+([A-Za-z_$][\w$]*)\s*;?\s*$/gm)) names.add(m[1]!);
      // `export default { getAdapter, adapters: known }` exposes its shorthand and
      // value names; so does a `return { getDefaultActivityRoute, … }` (a
      // composable hands the function out through its result).
      for (const m of code.matchAll(/^[ \t]*export\s+default\s+\{([^}]*)\}|\breturn\s*\{([^{}]*)\}/gm)) {
        for (const item of (m[1] ?? m[2])!.split(',')) {
          const value = item.includes(':') ? item.split(':').pop()! : item;
          const id = /^\s*([A-Za-z_$][\w$]*)\s*$/.exec(value)?.[1];
          if (id) names.add(id);
        }
      }
    }
    info = { module, names };
    memo.set(candidate.filePath, info);
  }
  if (!info.module || info.names.has(candidate.name)) return false;
  const line = (context.getFileLines?.(candidate.filePath) ?? context.readFile(candidate.filePath)?.split('\n'))?.[candidate.startLine - 1] ?? '';
  // Its own line says `export` (a node's flag can miss a form), or it is
  // `prototype.toString = function toString() {…}`, reached through instances.
  if (/^\s*export\b/.test(line)) return false;
  // Only a declaration statement is a module binding: an object literal's
  // member (a zustand store action `setZipUri: (v) => set(…)`) is reached
  // through the object, and so is `proto.x = function x() {}`.
  return /^\s*(?:declare\s+)?(?:async\s+)?(?:function\*?|const|let|var|(?:abstract\s+)?class|interface|type|enum)\s/.test(line);
}

const LUA_LOCALS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** Whether a Lua variable or function is declared `local` (`local x = …`, `local function f`, `local a, x = …`). */
function isLuaLocal(candidate: Node, context: ResolutionContext): boolean {
  if (candidate.kind !== 'variable' && candidate.kind !== 'constant' && candidate.kind !== 'function') return false;
  let memo = LUA_LOCALS.get(context);
  if (!memo) LUA_LOCALS.set(context, (memo = new Map()));
  const hit = memo.get(candidate.id);
  if (hit !== undefined) return hit;
  const line = (context.getFileLines?.(candidate.filePath) ?? context.readFile(candidate.filePath)?.split(/\r?\n/))?.[candidate.startLine - 1] ?? '';
  const local = /^\s*local\b/.test(line);
  memo.set(candidate.id, local);
  return local;
}

const JVM_CALLABLE_KINDS: ReadonlySet<string> = new Set(['method', 'function']);
const JVM_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'interface', 'enum', 'struct', 'trait', 'type_alias', 'annotation']);

/**
 * A test suite — a test source set, a `tests/` / `__tests__/` / `spec/` /
 * `unittests/` directory, a `FooTest.kt` / `test_foo.py` / `foo.test.ts` /
 * `foo_unittest.cc` file — as opposed to test-support code a project ships
 * (`testing/`, `fakes/`, a `*-test` module like kotlinx-coroutines-test), which
 * its own code may use. A `foo_unittest/` directory is a suite, as a
 * `foo_unittest.cc` file is: glog builds each one as a test program of its own.
 */
export function isTestSuitePath(filePath: string): boolean {
  if (!isTestPath(filePath)) return false;
  const lower = filePath.toLowerCase();
  const name = lower.slice(lower.lastIndexOf('/') + 1);
  const original = filePath.slice(filePath.lastIndexOf('/') + 1);
  // (`…Spec.java` alone is no test: halo's `IndexSpecs`, okhttp's `ConnectionSpec`.)
  if (name.startsWith('test_') || /[._-](?:test|tests|unittest|unittests)\.[a-z0-9]+$|[._](?:spec|specs)\.[a-z0-9]+$/.test(name) ||
      // CamelCase suffixes where the language names tests so: not `useTests.ts`, a React hook.
      /(?:Test|Tests|TestCase)\.(?:java|kt|kts|swift|cs|scala|groovy|m|mm|vb|fs)$/.test(original) || name === 'conftest.py') return true;
  return /(?:^|\/)(?:tests?|__tests__|specs?|e2e|unittests|[\w.]+[-_]unittests?)\//.test(lower) || /(?:^|\/)[A-Za-z0-9]*(?:Test|Tests|Spec)\//.test(filePath);
}

/** A Jest or Vitest manual mock: a file under a `__mocks__/` directory. */
export function isManualMockPath(filePath: string): boolean {
  return /(?:^|\/)__mocks__\//.test(filePath.replace(/\\/g, '/').toLowerCase());
}

/**
 * Whether a definition in `candidatePath` is a manual mock that a reference
 * from `fromPath`, which is no test code, cannot mean (#2455): the rule the
 * resolver's mock-free view applies to name matching, for the passes that
 * pick a component or a handler by name. A production `<Chart />` never
 * renders a mock's `Chart`.
 */
export function isManualMockHiddenFrom(candidatePath: string, fromPath: string): boolean {
  return isManualMockPath(candidatePath) && !isTestPath(fromPath);
}

const fileStem = (filePath: string): string => {
  const name = filePath.slice(filePath.lastIndexOf('/') + 1);
  const dot = name.lastIndexOf('.');
  return dot > 0 ? name.slice(0, dot) : name;
};

/**
 * Whether a C or C++ file named like a test suite is part of `ref`'s
 * translation unit after all. A file is in every translation unit that
 * includes it, whatever its name says: protobuf's conformance framework is
 * `conformance_test.h` (`ConformanceTestSuite`) and `test_runner.h`, which the
 * suites and runners include, so binary_json_conformance_suite.cc's
 * `suite_.ReportFailure(…)` is `ConformanceTestSuite::ReportFailure`. A
 * definition in a source file counts through the header it implements: the
 * one named like it that it includes (`conformance_test.cc` →
 * `conformance_test.h`), when that header is a test suite's too — jemalloc's
 * test `test/unit/hash.c` includes the library's `hash.h` to test it.
 */
function isIncludedCppTestSuite(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if ((candidate.language !== 'c' && candidate.language !== 'cpp') || (ref.language !== 'c' && ref.language !== 'cpp')) return false;
  if (cppIncluders(candidate.filePath, context).has(ref.filePath)) return true;
  return cppSameStemHeaders(candidate.filePath, context)
    .some((header) => isTestSuiteFile(header, context) && cppIncluders(header, context).has(ref.filePath));
}

const CPP_STEM_HEADERS = new WeakMap<ResolutionContext, Map<string, string[]>>();

/**
 * The headers a C or C++ file includes under its own name
 * (`conformance_test.cc` → `conformance_test.h`): the declarations its
 * definitions implement. One beside it, when it includes one, is the only
 * such header: protobuf's pyext/message.cc implements pyext/message.h, not
 * the google/protobuf/message.h it also includes; fmt's src/format.cc, with
 * none beside it, implements include/fmt/format.h. It may include that one
 * through other headers only: upb's reflection/field_def.c includes
 * reflection/internal/field_def.h, which reaches reflection/field_def.h
 * through def.h (cppIncludedHeadersBeside).
 */
function cppSameStemHeaders(filePath: string, context: ResolutionContext): string[] {
  let memo = CPP_STEM_HEADERS.get(context);
  if (!memo) CPP_STEM_HEADERS.set(context, (memo = new Map()));
  let headers = memo.get(filePath);
  if (!headers) {
    const found: string[] = [];
    const stem = fileStem(filePath);
    for (const include of context.getNodesInFile(filePath)) {
      if (include.kind !== 'import' || fileStem(include.name) !== stem) continue;
      const header = cppIncludedFile(include, context);
      if (header && header !== filePath && fileStem(header) === stem) found.push(header);
    }
    const dir = filePath.slice(0, filePath.lastIndexOf('/') + 1);
    let beside = found.filter((header) => header.slice(0, header.lastIndexOf('/') + 1) === dir);
    if (beside.length === 0) beside = cppIncludedHeadersBeside(filePath, context);
    headers = beside.length > 0 ? beside : found;
    memo.set(filePath, headers);
  }
  return headers;
}

const TEST_SUITE_FILES = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** isTestSuitePath, memoized: it is asked of every candidate of an ambiguous C or C++ name. */
function isTestSuiteFile(filePath: string, context: ResolutionContext): boolean {
  let memo = TEST_SUITE_FILES.get(context);
  if (!memo) TEST_SUITE_FILES.set(context, (memo = new Map()));
  let hit = memo.get(filePath);
  if (hit === undefined) memo.set(filePath, (hit = isTestSuitePath(filePath)));
  return hit;
}

/**
 * Whether a C or C++ definition is in `ref`'s translation unit, as its
 * includes show it: in the reference's own file, in a file the reference's
 * file includes, directly or through other includes, or in the source file
 * that implements such a header — the one named like it that includes it
 * (`googletest.cc` for `googletest.h`) — unless the source keeps it to
 * itself (a `static`, or what isCppTranslationUnitLocal finds). A test
 * suite's source implements only a test suite's header, as in
 * isIncludedCppTestSuite.
 */
function isInCppTranslationUnit(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (candidate.filePath === ref.filePath) return true;
  if (candidate.language !== 'c' && candidate.language !== 'cpp') return false;
  if (cppIncluders(candidate.filePath, context).has(ref.filePath)) return true;
  if (!C_SOURCE_EXT.test(candidate.filePath) || isCppTranslationUnitLocal(candidate, ref, context) ||
      ((candidate.kind === 'function' || candidate.kind === 'variable' || candidate.kind === 'constant') &&
        isStaticCFunction(candidate, context))) return false;
  const suite = isTestSuiteFile(candidate.filePath, context);
  // (The header may be the reference's own: json.h's inline overloads call
  // the ones json.cc defines.)
  return cppSameStemHeaders(candidate.filePath, context).some((header) => (!suite || isTestSuiteFile(header, context)) &&
    (header === ref.filePath || cppIncluders(header, context).has(ref.filePath)));
}

/**
 * What a C or C++ name written alone can mean outside a class, by its kind:
 * a call reaches a function, or a type and its constructor (`Foo(…)`); a
 * construction makes a type (`std::string buffer(n, c)` is no enum's
 * `string`); any other reference names anything but a member. Nothing a
 * class declares is in reach — its methods, its nested types, their
 * constructors: only an object, a qualified name or the class's own code
 * reaches them. gmock's `Value(result, …)` matcher is no
 * `RepeatedFieldAccessor::Value`, breakpad's `EXPECT_CALL(handler, Entry(…))`
 * no `CallFrameInfo::Entry` struct.
 */
function isCppNameAloneTarget(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const constructor = n.kind === 'method' && n.qualifiedName.endsWith(`${n.name}::${n.name}`);
  const fits = ref.referenceKind === 'calls' ? n.kind === 'function' || constructor || CPP_TYPE_KINDS.has(n.kind)
    : ref.referenceKind === 'instantiates' ? constructor || CPP_TYPE_KINDS.has(n.kind)
    : constructor || (n.kind !== 'method' && n.kind !== 'field' && n.kind !== 'property');
  if (!fits) return false;
  const scope = cppParentScope(constructor ? cppParentScope(n.qualifiedName) : n.qualifiedName);
  return !cppTypeDecls(scope, context).some((d) => CPP_CLASS_KINDS.has(d.kind));
}

/**
 * Same-named candidates for a C or C++ reference, narrowed to the ones its
 * translation unit declares, when there are any: the name a file uses is
 * one its includes declare. protobuf's csharp generator tests call the
 * `TestSourceDir()` googletest.h declares, not test_util2.h's
 * `TestUtil::TestSourceDir`, a test suite none of them includes; its Python
 * and Ruby extensions and upb's own code call `upb_Encode()` in
 * upb/wire/encode.c, not the copy php-upb.c bundles; rocksdb's stress tool
 * calls the `StringToHex()` its db_stress_common.h declares, not
 * `LDBCommand::StringToHex`. For a name the reference writes alone
 * (`byName`), only what the name alone can mean counts
 * (isCppNameAloneTarget), and a call the extractor recorded without the
 * receiver it is written on (`columns()[0].value()`) is left to the name
 * strategies. When the unit declares none of them — a file whose includes
 * don't resolve — the candidates stay as they are. Not for an `#include`,
 * which names a file.
 */
function withinCppTranslationUnit(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext, byName = false): Node[] {
  if (candidates.length < 2 || (ref.language !== 'c' && ref.language !== 'cpp') || ref.referenceKind === 'imports') return candidates;
  if (byName && ref.referenceKind === 'calls' && cppImplicitReceiver(ref, context) !== 'bare') return candidates;
  // A "call" outside any function is a macro, or a declaration read as a call
  // (rocksdb's c.h `extern … rocksdb_t*` above `rocksdb_open(…);`): no call.
  if (ref.referenceKind === 'calls' && context.getNodeById?.(ref.fromNodeId)?.kind === 'file') return candidates;
  const within = candidates.filter((n) => isInCppTranslationUnit(n, ref, context) &&
    (!byName || n.filePath === ref.filePath || isCppNameAloneTarget(n, ref, context)));
  if (within.length === 0 || within.length === candidates.length) return candidates;
  // Nor, for a C call, to definitions only a flag nothing sets compiles, past
  // one the build without it does: that is cppFunctionOverload's choice
  // (lua-cjson's fpconv.h defines `fpconv_init` under `#ifdef
  // USE_INTERNAL_FPCONV`; redis's build calls fpconv.c's).
  if (ref.language === 'c' && ref.referenceKind === 'calls' && within.every((n) => isCFeatureVariant(n, ref, context)) &&
      !isOffByDefault(ref.filePath, ref.line, context) &&
      candidates.some((n) => !within.includes(n) && n.kind === 'function' && !isStaticCFunction(n, context) &&
        !isCFeatureVariant(n, ref, context))) return candidates;
  // Nor to functions too few or too many arguments for the call, past one
  // that takes them: glog's `GetStackTrace(stack, ARRAYSIZE(stack), 1)` is
  // the one stacktrace.h declares, which the stacktrace_*-inl.h headers its
  // stacktrace.cc includes define, not utilities.h's `GetStackTrace()`.
  if (ref.referenceKind === 'calls') {
    const args = cppCallArguments(ref, within[0]!.name, context);
    if (args && within.every((n) => cppArgumentCountFits(n, n.name, args, context) === false) &&
        candidates.some((n) => !within.includes(n) && cppArgumentCountFits(n, n.name, args, context) === true)) return candidates;
  }
  return within;
}

const MINIFIED_SCRIPTS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** A minified / bundled script, by name (`jquery.min.js`) or by its text. */
function isMinifiedScript(filePath: string, context: ResolutionContext): boolean {
  if (!/\.(?:m?js|cjs)$/i.test(filePath)) return false;
  let memo = MINIFIED_SCRIPTS.get(context);
  if (!memo) MINIFIED_SCRIPTS.set(context, (memo = new Map()));
  let hit = memo.get(filePath);
  if (hit === undefined) {
    hit = /[.-]min\.m?js$/i.test(filePath) || isMinifiedContent(filePath, context.readFile(filePath) ?? '');
    memo.set(filePath, hit);
  }
  return hit;
}

/** Per context: every package the project's JVM sources declare. */
const JVM_PACKAGES = new WeakMap<ResolutionContext, Set<string>>();

/**
 * Whether a Java file binds `name` with a single-type (or static) import from
 * a package the project does not declare — `import java.lang.reflect.Field;`,
 * `import static org.junit.Assert.assertEquals;`. A nested class of a project
 * type (`import com.acme.Outer.Inner;`) is under a project package, so it is not.
 */
export function isJavaOutsideImport(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const binding = context.getImportMappings(ref.filePath, ref.language).find((m) => m.localName === name);
  if (!binding) return false;
  // A member the file declares itself is in scope before any import —
  // Exposed's `toLocalDateTime(value)` inside the column type that defines it —
  // in the same namespace only: gson's `new URI(…)` is `java.net.URI` beside
  // `TypeAdapters`' field `URI`, as a type always is beside a value.
  const call = ref.referenceKind === 'calls' && name === ref.referenceName;
  const kinds = call ? JVM_CALLABLE_KINDS : JVM_TYPE_KINDS;
  if ((context.getNodesInFileNamed?.(ref.filePath, name) ?? context.getNodesInFile(ref.filePath).filter((n) => n.name === name))
    .some((n) => kinds.has(n.kind))) return false;
  let packages = JVM_PACKAGES.get(context);
  if (!packages) {
    packages = new Set<string>();
    for (const n of context.getNodesByKind('namespace')) {
      if (n.language === 'java' || n.language === 'kotlin' || n.language === 'scala') packages.add(n.qualifiedName);
    }
    JVM_PACKAGES.set(context, packages);
  }
  const parts = binding.source.split('.');
  for (let i = 1; i < parts.length; i++) {
    if (packages.has(parts.slice(0, i).join('.'))) return false;
  }
  return true;
}

/**
 * `Modifier.pad()` after `import androidx.compose.ui.Modifier`: the type is
 * outside the project, but Kotlin lets the project extend it. The call reaches
 * a project extension on that type — `fun Modifier.pad()`, indexed as
 * `Modifier::pad` — that the call site can see (its file, its package, an
 * import of it by name or `.*`) and whose own file imports the same type.
 * Compose's own `Modifier.fillMaxSize()` matches none and stays unlinked.
 */
function kotlinExtensionOnImportedType(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  const call = /^(\w+)\.(\w+)$/.exec(ref.referenceName);
  if (!call || ref.referenceKind !== 'calls') return null;
  const binding = context.getImportMappings(ref.filePath, ref.language).find((m) => m.localName === call[1]);
  if (!binding) return null;
  const pkg = binding.source.slice(0, binding.source.lastIndexOf('.'));
  const extensions = context.getNodesByQualifiedName(`${binding.exportedName}::${call[2]}`).filter((n) => {
    if (n.kind !== 'method' || n.language !== 'kotlin' || !isKotlinTopLevelVisible(n, ref, context)) return false;
    const scope = kotlinFileScope(n.filePath, context);
    return scope.imports.has(binding.source) || scope.stars.has(pkg);
  });
  const chosen = extensions.length > 1 ? extensions.filter((n) => n.filePath === ref.filePath) : extensions;
  return chosen.length === 1 ? { original: ref, targetNodeId: chosen[0]!.id, confidence: 0.9, resolvedBy: 'qualified-name' } : null;
}

/** Lua's global functions, and the test runner's: `local type = type` is the standard library's `type`. */
const LUA_GLOBAL_FUNCTIONS: ReadonlySet<string> = new Set([
  'assert', 'error', 'ipairs', 'pairs', 'next', 'type', 'tostring', 'tonumber', 'setmetatable', 'getmetatable',
  'rawget', 'rawset', 'rawequal', 'rawlen', 'select', 'pcall', 'xpcall', 'unpack', 'print', 'load', 'loadstring',
  'loadfile', 'dofile', 'collectgarbage', 'require', 'setfenv', 'getfenv', 'newproxy', 'typeof', 'warn', 'tick', 'wait',
  'describe', 'it', 'before_each', 'after_each', 'setup', 'teardown', 'lazy_setup', 'lazy_teardown', 'pending', 'finally',
  'insulate', 'expose',
]);

/** `require "m"` (or a loader named for it — kong's `reload_module("spec.internal.misc")`), then any `.member`s. */
const LUA_REQUIRE_ALIAS = /^(?:require|[A-Za-z_]\w*(?:[Rr]equire|_module|[Ii]mport))\s*\(?\s*(["'])([^"']+)\1\s*\)?((?:\s*\.\s*[A-Za-z_]\w*)*)\s*$/;
const LUA_NAME_ALIAS = /^([A-Za-z_]\w*)((?:\s*\.\s*[A-Za-z_]\w*)*)\s*$/;

/**
 * A bare Lua call through a `local` alias, followed to what the alias names:
 *
 *   local splitn = require("kong.tools.string").splitn   → the module's `splitn`
 *   local select_listener = utils.select_listener        → through `local utils = require …`
 *   local fmt = string.format / local type = type        → the standard library's: no edge
 *
 * Kong localizes every global and module function it uses this way, so its
 * calls stopped at a same-file variable — 8,000 of them, most for the
 * standard library. `undefined` when the call is not through such an alias
 * (it resolves as before), null when the alias names nothing in the project.
 */
function luaAliasTarget(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const decl = luaLocalDecl(ref.referenceName, ref.filePath, ref.line, context);
  if (!decl) return undefined;
  const target = luaAliasOf(decl, context, 0);
  if (target === undefined) return undefined;
  if (target === null) return null;
  return { original: ref, targetNodeId: target.id, confidence: 0.9, resolvedBy: 'import' };
}

/** The `local name = …` in scope at `line` of `file`: the nearest one above it that no other function holds. */
function luaLocalDecl(name: string, file: string, line: number, context: ResolutionContext): Node | null {
  const nodes = context.getNodesInFile(file);
  const fns = nodes.filter((n) => n.kind === 'function' || n.kind === 'method');
  let best: Node | null = null;
  for (const n of nodes) {
    if (n.name !== name || n.kind !== 'variable' || n.startLine > line || !n.signature) continue;
    if (fns.some((f) => f.startLine <= n.startLine && n.startLine <= f.endLine && !(f.startLine <= line && line <= f.endLine))) continue;
    if (!isLuaLocal(n, context)) continue;
    if (!best || n.startLine > best.startLine) best = n;
  }
  // A function's own locals are not nodes: kong's `local clear_header =
  // kong.response.clear_header` inside an access handler. Read the nearest
  // one above the call within the innermost function around it.
  const fn = fns.filter((f) => f.startLine <= line && line <= f.endLine && f.startLine < line)
    .sort((a, b) => (a.endLine - a.startLine) - (b.endLine - b.startLine))[0];
  if (fn && (!best || best.startLine < fn.startLine)) {
    const lines = context.getFileLines?.(file) ?? context.readFile(file)?.split(/\r?\n/) ?? [];
    const decl = new RegExp(`^\\s*local\\s+${escapeRegExp(name)}\\s*=\\s*(.+?)\\s*$`);
    for (let at = line - 1; at > fn.startLine; at--) {
      const m = decl.exec(lines[at - 1] ?? '');
      if (!m) continue;
      const fileNode = nodes.find((n) => n.kind === 'file');
      if (!fileNode) break;
      return { ...fileNode, name, kind: 'variable', signature: `= ${m[1]}`, startLine: at, endLine: at };
    }
  }
  return best;
}

/** Where a Lua alias is written: its file, line and name, and a node there to resolve `require`s from. */
interface LuaSite { file: string; line: number; name: string; node: Node }

/**
 * What a Lua alias variable names: a project function (or the module's own
 * global), null for the standard library or an outside module, `undefined`
 * for an initializer that is not an alias.
 */
function luaAliasOf(decl: Node, context: ResolutionContext, depth: number): Node | null | undefined {
  const rhs = decl.signature!.replace(/^\s*=\s*/, '').trim();
  return luaAliasExpr(rhs, { file: decl.filePath, line: decl.startLine, name: decl.name, node: decl }, context, depth);
}

const luaMembers = (chain: string): string[] => chain.split('.').map((s) => s.trim()).filter(Boolean);

function luaAliasExpr(rhs: string, site: LuaSite, context: ResolutionContext, depth: number): Node | null | undefined {
  const req = LUA_REQUIRE_ALIAS.exec(rhs);
  if (req) return luaModuleMember(req[2]!, luaMembers(req[3]!), site.node, context, depth);
  const named = LUA_NAME_ALIAS.exec(rhs);
  if (!named) return undefined;
  const root = named[1]!;
  const path = luaMembers(named[2]!);
  const rootDecl = root === site.name ? null : luaLocalDecl(root, site.file, site.line - 1, context);
  if (rootDecl) {
    const module = LUA_REQUIRE_ALIAS.exec(rootDecl.signature!.replace(/^\s*=\s*/, '').trim());
    if (module && path.length > 0) return luaModuleMember(module[2]!, [...luaMembers(module[3]!), ...path], rootDecl, context, depth);
    return undefined;
  }
  if (path.length === 0) return LUA_GLOBAL_FUNCTIONS.has(root) ? null : undefined;
  if (!LUA_LIBRARY_TABLES.has(root)) {
    // A member of a global table the host provides — kong's `local clear_header =
    // kong.response.clear_header` — is the one method of a table named after its holder.
    const member = path[path.length - 1]!;
    const holder = path.length > 1 ? path[path.length - 2]! : root;
    const owned = context.getNodesByName(member).filter((n) =>
      (n.language === 'lua' || n.language === 'luau') && n.kind === 'method' && sharesReceiverWord(holder, n) &&
      !(isTestPath(n.filePath) && !isTestPath(site.file)));
    return owned.length === 1 ? owned[0]! : undefined;
  }
  if (path.length !== 1) return undefined;
  // A library function the project patches itself (kong's `ngx.sleep`) is the project's —
  // a test's stand-in (`function ngx.get_phase()` in a spec) only for that test.
  const patched = context.getNodesByName(path[0]!).filter((n) =>
    (n.kind === 'function' || n.kind === 'method') && n.qualifiedName.split(/::|\./)[0] === root &&
    (n.filePath === site.file || !isTestPath(n.filePath)));
  return patched.length === 1 ? patched[0]! : null;
}

/** Per-context memo: `file\0a.b` → what that module member is. */
const LUA_MEMBERS = new WeakMap<ResolutionContext, Map<string, Node | null | undefined>>();

/** `member` of the module `require(name)` returns, from `decl`'s file: its function of that name. */
function luaModuleMember(name: string, path: string[], decl: Node, context: ResolutionContext, depth: number): Node | null | undefined {
  const file = luaModuleFile(name, decl, context);
  if (!file) return null;
  // `require "kong.conf_loader"` called directly: the module's returned value.
  if (path.length === 0) return undefined;
  let memo = LUA_MEMBERS.get(context);
  if (!memo) LUA_MEMBERS.set(context, (memo = new Map()));
  const key = `${file}\0${path.join('.')}`;
  if (memo.has(key)) return memo.get(key);
  memo.set(key, null); // a cycle of re-exports names nothing
  const found = luaMemberIn(file, path, context, depth);
  memo.set(key, found);
  return found;
}

function luaMemberIn(file: string, path: string[], context: ResolutionContext, depth: number): Node | null | undefined {
  const member = path[path.length - 1]!;
  const nodes = context.getNodesInFile(file);
  const inFile = nodes.filter((n) => n.name === member);
  const fns = inFile.filter((n) => n.kind === 'function' || n.kind === 'method');
  if (fns.length > 0) {
    const owner = path.length > 1 ? path[path.length - 2]! : null;
    return fns.find((n) => owner !== null && n.qualifiedName.endsWith(`${owner}::${member}`)) ??
      fns.find((n) => n.kind === 'method') ?? fns[0]!;
  }
  if (depth >= 3) return null;
  // The module exports something under this name: `return { check = check_phase }`,
  // `_M.check = check_phase`, `kong_exec = cmd.kong_exec,` (spec helpers' table).
  const source = (context.readFile(file) ?? '')
    .replace(/--\[(=*)\[[\s\S]*?\]\1\]/g, (c) => c.replace(/[^\n]/g, ''))
    .replace(/--[^\n]*/g, '');
  const exported = new RegExp(`(?:^|[\\s{,.])${escapeRegExp(member)}\\s*=\\s*([A-Za-z_]\\w*(?:\\s*\\.\\s*[A-Za-z_]\\w*)*)\\s*(?:[,;}]|$)`, 'm').exec(source);
  if (exported && exported[1] !== member) {
    const rhs = exported[1]!;
    const line = source.slice(0, exported.index).split('\n').length + 1;
    if (/^[A-Za-z_]\w*$/.test(rhs)) {
      const fn = nodes.find((n) => n.name === rhs && (n.kind === 'function' || n.kind === 'method'));
      if (fn) return fn;
    }
    const at = nodes.find((n) => n.kind === 'file') ?? nodes[0];
    const next = at ? luaAliasExpr(rhs, { file, line, name: member, node: at }, context, depth + 1) : undefined;
    if (next !== undefined) return next;
  }
  // The module re-exports an alias of its own (`local splitn = require(…).splitn`).
  const alias = inFile.find((n) => n.kind === 'variable' && n.signature && isLuaLocal(n, context));
  if (alias) {
    const next = luaAliasOf(alias, context, depth + 1);
    if (next !== undefined) return next;
  }
  const global = inFile.find((n) => n.kind === 'variable' && !isLuaLocal(n, context));
  return global ?? null;
}

/** The project file `require(name)` loads from `decl`'s file, or null for a module outside it. */
function luaModuleFile(name: string, decl: Node, context: ResolutionContext): string | null {
  const resolved = context.resolveImport?.({
    fromNodeId: decl.id,
    referenceName: name,
    referenceKind: 'imports',
    line: decl.startLine,
    column: 0,
    filePath: decl.filePath,
    language: decl.language,
  });
  if (!resolved) return null;
  return context.getNodeById?.(resolved.targetNodeId)?.filePath ?? null;
}

/**
 * Languages in which `visibility: 'private'` on a definition means no other
 * FILE can name it: a Kotlin `private fun` is file- or class-local, and the
 * same holds for Java, C#, Swift, Scala and PHP members. (A Dart `_name` is
 * its library's, which can span several files: see isVisibleAcrossFiles.)
 */
const PRIVATE_IS_FILE_LOCAL = new Set<string>(['kotlin', 'java', 'csharp', 'swift', 'scala', 'php']);

/**
 * Whether a resolution lands on a Java record's implicit accessor from outside
 * the record. One is reached through what types its receiver (a typed
 * receiver, `Record::x`, `Record.x`) or from inside the record; a name-only
 * guess bound `result.content()` on a library type to any record with a
 * `content` component. Applied by ReferenceResolver to name-only results.
 */
export function isGuessedRecordAccessor(resolved: ResolvedRef, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const target = context.getNodeById?.(resolved.targetNodeId);
  if (!target || target.kind !== 'method' || target.docstring !== IMPLICIT_RECORD_ACCESSOR_DOC) return false;
  const record = target.qualifiedName.slice(0, target.qualifiedName.lastIndexOf('::'));
  return ref.filePath !== target.filePath || !context.getNodesInFile(target.filePath).some((n) =>
    n.kind === 'class' && n.qualifiedName === record && n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line);
}

/** Per-context memo: node id → "this C/C++ function is declared `static`". */
const C_STATIC_MEMO = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * A C/C++ file that IS a translation unit. A `static` defined here is local
 * to it. A `static` (typically `static inline`) in a header is a different
 * thing: the header is textually included, so the function exists in every
 * unit that includes it and is callable from each — MAVLink's generated
 * `mavlink_msg_*.h` are nothing but such functions, 4,306 real calls on one
 * betaflight tree.
 */
const C_SOURCE_EXT = /\.(c|cc|cpp|cxx|c\+\+|m|mm)$/i;

/**
 * What an Objective-C source file defines for itself, as C does: its C types
 * and its globals, as opposed to its classes and protocols.
 */
const OBJC_FILE_LOCAL_KINDS: ReadonlySet<string> = new Set(['struct', 'union', 'enum', 'type_alias', 'variable', 'constant']);

/**
 * Whether `n` is a C type or global that an Objective-C source file other
 * than `ref`'s defines, which no other file can name. It leaves the
 * candidates before one is picked, so a global's declaration in a header
 * (Hammerspoon's `extern NSString *MJConfigFile;` in variables.h) stands for
 * the definition in variables.m. isVisibleAcrossFiles applies the same rule
 * to the pipeline's pick.
 */
function isObjcFileLocalElsewhere(n: Node, ref: UnresolvedRef): boolean {
  return n.language === 'objc' && n.filePath !== ref.filePath && OBJC_FILE_LOCAL_KINDS.has(n.kind) && C_SOURCE_EXT.test(n.filePath);
}

/** Per context: a C/C++ type's qualified name → its declarations. */
const CPP_TYPE_DECLS = new WeakMap<ResolutionContext, Map<string, Node[]>>();
/** Per context: a C/C++ file → the line and resolved file of each `#include` it writes. */
const CPP_INCLUDE_LINES = new WeakMap<ResolutionContext, Map<string, Array<[number, string | null]>>>();
/** Per context: a C/C++ file → the line spans of its unnamed namespaces. */
const CPP_UNNAMED_NAMESPACES = new WeakMap<ResolutionContext, Map<string, Array<[number, number]>>>();

/**
 * Whether only another C or C++ translation unit can name `candidate`: a
 * type or alias a source file declares, a member of a class only source
 * files declare, or what a source file's unnamed namespace (`namespace { … }`)
 * declares. rocksdb's test fixture `ColumnFamilyTestBase` is declared in
 * column_family_test.cc, and other test files' bare `Put(…)` reached its `Put`
 * by name; inlineskiplist.h's `Node*` reached hash_linklist_rep.cc's own
 * `Node`. What a source file declares is seen by the file itself, by a
 * translation unit that includes it (a test that includes the source it
 * tests), and by a header it includes after the declaration: rocksdb's
 * version_set.cc includes version_set_sync_and_async.h below its
 * `FilePicker` classes.
 */
function isCppTranslationUnitLocal(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'c' && ref.language !== 'cpp') return false;
  const seenFrom = (decl: Node, file: string): boolean => !C_SOURCE_EXT.test(decl.filePath) || decl.filePath === file ||
    cppIncluders(decl.filePath, context).has(file) || cppIncludesAfter(decl.filePath, decl.startLine, file, context);
  const seen = (decl: Node): boolean => seenFrom(decl, ref.filePath);
  if (CPP_TYPE_KINDS.has(candidate.kind)) return !seen(candidate);
  // A member written in its class's declaration is that declaration's; one
  // defined out of line is the class's, wherever a declaration of it its own
  // file sees is (through an alias, the class may be declared anywhere). A
  // scope its file sees no type of may be a namespace: fmt's posix-mock-test.cc
  // defines `test::close` of posix-mock.h's `namespace test`, and
  // ostream-test.cc declares a `struct test` of its own.
  const enclosing = cppEnclosingClassDecl(candidate, context);
  if (enclosing) return !seen(enclosing);
  const decls = cppTypeDecls(cppParentScope(candidate.qualifiedName), context)
    .filter((d) => seenFrom(d, candidate.filePath));
  if (decls.some((d) => d.kind === 'type_alias')) return false;
  if (decls.length > 0) return !decls.some(seen);
  return !seen(candidate) &&
    cppUnnamedNamespaceSpans(candidate.filePath, context).some(([start, end]) => candidate.startLine >= start && candidate.startLine <= end);
}

/**
 * Of the methods a C or C++ type's name gives, those `ref`'s translation
 * unit can see (isCppTranslationUnitLocal), when there are any. Classes of
 * one qualified name can be declared apart: rocksdb's db_stress_shared_state.h
 * and two benchmark `.cc` files each declare a `SharedState`, and a call in
 * db_stress_common.cc is the header's. (Every candidate for any other ref.)
 */
function cppVisibleFirst(methods: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  if (methods.length < 2 || (ref.language !== 'c' && ref.language !== 'cpp')) return methods;
  const visible = methods.filter((m) => !isCppTranslationUnitLocal(m, ref, context));
  return visible.length > 0 ? visible : methods;
}

/** The declarations of the C or C++ type (or alias) named `qualifiedName`. */
function cppTypeDecls(qualifiedName: string, context: ResolutionContext): Node[] {
  if (!qualifiedName) return [];
  let memo = CPP_TYPE_DECLS.get(context);
  if (!memo) CPP_TYPE_DECLS.set(context, (memo = new Map()));
  let decls = memo.get(qualifiedName);
  if (!decls) {
    decls = context.getNodesByQualifiedName(qualifiedName)
      .filter((n) => CPP_TYPE_KINDS.has(n.kind) && (n.language === 'cpp' || n.language === 'c'));
    memo.set(qualifiedName, decls);
  }
  return decls;
}

/** The innermost C or C++ class, struct or union declaration of its file whose lines hold `member`. */
function cppEnclosingClassDecl(member: Node, context: ResolutionContext): Node | undefined {
  let innermost: Node | undefined;
  for (const cls of cppClassesIn(member.filePath, context)) {
    if (cls.id === member.id || member.startLine < cls.startLine || member.startLine > (cls.endLine ?? cls.startLine)) continue;
    if (!innermost || cls.startLine >= innermost.startLine) innermost = cls;
  }
  return innermost;
}

/** Whether the C or C++ file `source` `#include`s `header` below line `line`. */
function cppIncludesAfter(source: string, line: number, header: string, context: ResolutionContext): boolean {
  let memo = CPP_INCLUDE_LINES.get(context);
  if (!memo) CPP_INCLUDE_LINES.set(context, (memo = new Map()));
  let includes = memo.get(source);
  if (!includes) {
    includes = context.getNodesInFile(source)
      .filter((n) => n.kind === 'import')
      .map((n): [number, string | null] => [n.startLine, cppIncludedFile(n, context)]);
    memo.set(source, includes);
  }
  return includes.some(([at, file]) => at > line && file === header);
}

/**
 * The line spans of the unnamed namespaces (`namespace { … }`) a C or C++
 * file writes, the outermost of nested ones: what one declares has internal
 * linkage, so no other translation unit names it. Comments, preprocessor
 * lines and string, character and raw string literals are skipped.
 */
function cppUnnamedNamespaceSpans(file: string, context: ResolutionContext): Array<[number, number]> {
  let memo = CPP_UNNAMED_NAMESPACES.get(context);
  if (!memo) CPP_UNNAMED_NAMESPACES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const spans: Array<[number, number]> = [];
  const text = context.readFile(file) ?? '';
  if (/\bnamespace\s*\{/.test(text)) {
    const open: Array<{ line: number; unnamed: boolean }> = [];
    let line = 1;
    let lineStart = true;
    // The code since the last brace or `;`, without comments and literals.
    let code = '';
    let i = 0;
    while (i < text.length) {
      const c = text[i]!;
      if (c === '\n') {
        line++;
        lineStart = true;
        code += ' ';
        i++;
        continue;
      }
      if (lineStart && c === '#') {
        // A preprocessor line, continued by a trailing backslash (before a CRLF too).
        let end = i;
        while (end < text.length && (text[end] !== '\n' || text[end - 1] === '\\' || (text[end - 1] === '\r' && text[end - 2] === '\\'))) {
          if (text[end] === '\n') line++;
          end++;
        }
        i = end;
        continue;
      }
      if (!/\s/.test(c)) lineStart = false;
      if (c === '/' && text[i + 1] === '/') {
        const end = text.indexOf('\n', i);
        i = end < 0 ? text.length : end;
        continue;
      }
      if (c === '/' && text[i + 1] === '*') {
        const end = text.indexOf('*/', i + 2);
        const stop = end < 0 ? text.length : end + 2;
        for (let j = i; j < stop; j++) if (text.charCodeAt(j) === 10) line++;
        i = stop;
        continue;
      }
      if (c === '"' && /(?:^|[^\w$])(?:u8|[uUL])?R$/.test(text.slice(Math.max(0, i - 4), i))) {
        // `R"delim( … )delim"`.
        const paren = text.indexOf('(', i);
        const end = paren < 0 ? -1 : text.indexOf(`)${text.slice(i + 1, paren)}"`, paren);
        const stop = end < 0 ? text.length : end + paren - i + 1;
        for (let j = i; j < stop && j < text.length; j++) if (text.charCodeAt(j) === 10) line++;
        i = Math.min(stop, text.length);
        continue;
      }
      if (c === '"' || c === "'") {
        let j = i + 1;
        while (j < text.length && text[j] !== c && text[j] !== '\n') j += text[j] === '\\' ? 2 : 1;
        i = j + 1;
        continue;
      }
      if (c === '{') {
        open.push({ line, unnamed: /(?:^|[^\w$])namespace\s*$/.test(code) });
        code = '';
      } else if (c === '}') {
        const top = open.pop();
        if (top?.unnamed && !open.some((o) => o.unnamed)) spans.push([top.line, line]);
        code = '';
      } else if (c === ';') {
        code = '';
      } else {
        code += c;
        if (code.length > 200) code = code.slice(-100);
      }
      i++;
    }
  }
  memo.set(file, spans);
  return spans;
}

/**
 * Whether a C/C++ function definition carries the `static` storage class —
 * read from its first source line(s), since the extractor records no storage
 * class and the kernel arm would need the same field. `static` on the line
 * above the name (`static void\nfoo(void)`) is the common alternative layout.
 */
function isStaticCFunction(candidate: Node, context: ResolutionContext): boolean {
  let memo = C_STATIC_MEMO.get(context);
  if (!memo) {
    memo = new Map();
    C_STATIC_MEMO.set(context, memo);
  }
  const hit = memo.get(candidate.id);
  if (hit !== undefined) return hit;
  const lines = context.getFileLines?.(candidate.filePath) ?? context.readFile(candidate.filePath)?.split('\n') ?? [];
  const head = [lines[candidate.startLine - 2] ?? '', lines[candidate.startLine - 1] ?? ''].join('\n');
  const isStatic = /(^|[\s;}])static\s/.test(head);
  memo.set(candidate.id, isStatic);
  return isStatic;
}

/** Per-context memo: node id → "this Rust method implements a trait". */
const RUST_TRAIT_IMPL_MEMO = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether a Rust method sits in an `impl Trait for Type` block. Such a method
 * carries no `pub` — the trait decides its visibility — so the extractor
 * records it as private; it is reachable wherever the trait is. Read from the
 * nearest enclosing `impl` header above the method, memoised per node.
 */
function isRustTraitImplMethod(candidate: Node, context: ResolutionContext): boolean {
  if (candidate.kind !== 'method') return false;
  let memo = RUST_TRAIT_IMPL_MEMO.get(context);
  if (!memo) {
    memo = new Map();
    RUST_TRAIT_IMPL_MEMO.set(context, memo);
  }
  const hit = memo.get(candidate.id);
  if (hit !== undefined) return hit;
  const lines = context.getFileLines?.(candidate.filePath) ?? context.readFile(candidate.filePath)?.split('\n') ?? [];
  let isTrait = false;
  for (let i = candidate.startLine - 2; i >= 0; i--) {
    const line = lines[i] ?? '';
    if (/^\s*(pub(\([^)]*\))?\s+)?(unsafe\s+)?impl\b/.test(line)) {
      isTrait = /\sfor\s/.test(line.replace(/\/\/.*$/, ''));
      break;
    }
    // A top-level item above the method means it was not inside an impl.
    if (/^(pub(\([^)]*\))?\s+)?(fn|struct|enum|mod|trait|const|static|type)\b/.test(line)) break;
  }
  memo.set(candidate.id, isTrait);
  return isTrait;
}

/**
 * The directory a Rust file's private items are visible from: the file's own
 * module subtree. `src/net.rs` and `src/net/mod.rs` own `src/net/`; a crate
 * root (`lib.rs` / `main.rs`) owns its directory. A child module reaches its
 * ancestors' private items (`super::`), a sibling or another crate never does.
 */
function rustModuleDir(filePath: string): string {
  const base = path.posix.basename(filePath);
  const dir = path.posix.dirname(filePath);
  if (base === 'mod.rs' || base === 'lib.rs' || base === 'main.rs') return dir;
  return path.posix.join(dir, base.replace(/\.rs$/, ''));
}

/**
 * Whether a Rust file is inside the module whose file is `ownerFile` and whose
 * submodules live under `ownerDir`: below that directory, or loaded by a
 * `#[path]` declaration written inside it (fast-mlsirm's
 * `tests/unit/scaling_tests.rs` is `scaling.rs`'s `mod tests`, and sees its
 * private items).
 */
function rustFileUnder(file: string, ownerDir: string, ownerFile: string, context: ResolutionContext): boolean {
  let f = file;
  for (let i = 0; i < 8; i++) {
    if (f.startsWith(`${ownerDir}/`) || (i > 0 && f === ownerFile)) return true;
    const claim = rustPathClaim(f, context);
    if (!claim) return false;
    f = claim.file;
  }
  return false;
}

/**
 * Standard-library package names (and kubernetes' aliases of a few of its own
 * util packages). A dotted Go reference through one is taken for a call into
 * that package, unless the name is a parameter or local where the call is
 * written (isGoProjectLocalCall).
 */
export const GO_STDLIB_PACKAGES: ReadonlySet<string> = new Set([
  'fmt', 'os', 'io', 'net', 'http', 'log', 'math', 'sort', 'sync',
  'time', 'path', 'bytes', 'strings', 'strconv', 'errors', 'context',
  'json', 'xml', 'csv', 'html', 'template', 'regexp', 'reflect',
  'runtime', 'testing', 'flag', 'bufio', 'crypto', 'encoding',
  'filepath', 'hash', 'mime', 'rand', 'signal', 'sql', 'syscall',
  'unicode', 'unsafe', 'atomic', 'binary', 'debug', 'exec', 'heap',
  'ring', 'scanner', 'tar', 'zip', 'gzip', 'zlib', 'tls', 'url',
  'user', 'pprof', 'trace', 'ast', 'build', 'parser', 'printer',
  'token', 'types', 'cgo', 'plugin', 'race', 'ioutil',
  // Kubernetes-common stdlib aliases
  'utilruntime', 'utilwait', 'utilnet',
]);

export interface GoQualification {
  /** The package name written before the reference's name, as spelled. */
  written?: string;
  /** The file's import that name is. */
  imported?: ImportMapping;
  /**
   * For a call through a parameter or local that takes an import's name, the
   * import the type its declaration writes is written through — `clock` in a
   * parameter `clock clock.PassiveClock`, `atomic` in `cache :=
   * &atomic.Bool{}` — or its value comes from: `reflect` in `value :=
   * reflect.New(t)`.
   */
  typePackage?: ImportMapping;
}

const GO_QUALIFIERS = new WeakMap<ResolutionContext, Map<string, GoQualification>>();

/**
 * The package a Go reference is written through, read from its line (the
 * index keeps only the name): `io` in `io.Closer`, and the file's import of
 * it. Empty for a name written bare.
 */
export function goRefQualification(ref: UnresolvedRef, context: ResolutionContext): GoQualification {
  if (ref.referenceKind === 'imports') return {};
  const name = ref.referenceName.split('.').pop()!;
  if (!/^[A-Za-z_]\w*$/.test(name)) return {};
  let memo = GO_QUALIFIERS.get(context);
  if (!memo) GO_QUALIFIERS.set(context, (memo = new Map()));
  const key = `${ref.filePath}\0${ref.line}\0${ref.column}\0${ref.referenceName}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  let written: string | undefined;
  const dot = ref.referenceName.indexOf('.');
  if (dot >= 0) {
    // A dotted reference spells its receiver, and only the first segment can
    // be a package: `klog` in `klog.Infof`, `s` in `s.cache.Get`. Reading
    // the line for it found nothing where the name is spelled again —
    // harbor's `Digest:` key beside `digest.Digest(dig)` — and another
    // selector's where one comes first: `klog` for `err.Error` in
    // `klog.Error(err.Error())`.
    const head = ref.referenceName.slice(0, dot);
    if (/^[A-Za-z_]\w*$/.test(head)) written = head;
  } else {
    const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1] ?? '';
    const at = Math.max(0, ref.column);
    // The qualifier right before the name at the reference's column, or the
    // line's only spelling of the name. A variadic `...chunks.Meta` is written
    // through `chunks` too: the ellipsis is no receiver.
    written = line.startsWith(name, at) ? /(?:^|[^\w.]|\.{3})([A-Za-z_]\w*)\.$/.exec(line.slice(0, at))?.[1]
      : !new RegExp(`(?<![\\w.])${name}\\b`).test(line) ? new RegExp(`(?:^|[^\\w.]|\\.{3})([A-Za-z_]\\w*)\\.${name}\\b`).exec(line)?.[1] : undefined;
  }
  const imports = context.getImportMappings(ref.filePath, 'go');
  let imported = written ? imports.find((m) => m.localName === written) : undefined;
  let typePackage: ImportMapping | undefined;
  // A call through a parameter or local that takes the import's name is a
  // call on that variable: etcd's `jwt, err := newTokenProviderJWT(…)`, then
  // `jwt.assign(…)` beside `import "github.com/golang-jwt/jwt/v5"`; harbor's
  // testify suites' `func (suite *DaoTestSuite) …` beside testify's `suite`.
  // A type's qualifier is always a package, and a value read through one
  // (`quota.Name`) is no call.
  const local = imported && dot >= 0 && ref.referenceKind === 'calls' ? goLocalDecl(written!, ref, context) : undefined;
  if (local) {
    // A value a package outside the project hands out is of a type it
    // declares: kubernetes' `clock := clocktesting.NewFakePassiveClock(…)`
    // has no project method `Now`.
    const qualifier = /^[*&\s]*([A-Za-z_]\w*)\.[A-Za-z_]\w*$/.exec(local.type ?? '')?.[1] ?? local.from;
    typePackage = qualifier ? imports.find((m) => m.localName === qualifier) : undefined;
    written = undefined;
    imported = undefined;
  }
  const found = { written, imported, typePackage };
  memo.set(key, found);
  return found;
}

/**
 * The import a Go reference is written through — `context` in
 * `context.Context`, `store` in `store.Manager` — taken from a dotted
 * reference's receiver, else read from its line, since the index keeps only
 * the name. Undefined for a name written bare, or through anything that isn't
 * one of the file's imports there.
 */
export function goRefQualifier(ref: UnresolvedRef, context: ResolutionContext): ImportMapping | undefined {
  return goRefQualification(ref, context).imported;
}

/**
 * Whether a Go reference is written through a package that is none of its
 * file's imports as the index knows them: `clientv3` in `clientv3.KV` under an
 * unaliased `import "go.etcd.io/etcd/client/v3"`, a package named neither by
 * its path's last element (`v3`) nor by the name goimports assumes for it
 * (`client`). Which package that is cannot be told from here.
 */
export function isGoUnknownQualified(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const { written, imported } = goRefQualification(ref, context);
  return written !== undefined && imported === undefined;
}

/**
 * What a Go type position — a parameter or result type, a composite
 * literal's type — names: a type, which Go reads from one package. A method
 * or a function is never it; Go reaches those only through a value or a
 * package. Whichever strategy found a declaration of the name, the type is
 * the one of that name in the reference's own package for a bare name (or in
 * a package its file dot-imports, goBareTypeDir), or in the imported project
 * package for `pkg.T`. Without one there, a method or function of the name is
 * nothing the reference means, nor is any type a bare name only a package
 * from outside the project the file dot-imports can give it. etcd's
 * `func (ti *treeIndex) KeyIndex(keyi *keyIndex) *keyIndex` linked both
 * `keyIndex` types to the method `treeIndex.keyIndex` beside it,
 * prometheus's `(ec2Client, error)` result to the method the line declares,
 * and its `&config_util.URL{…}` (an outside package) to `Target.URL`. A bare
 * name that found another package's type means its own package's type of
 * that name when there is one: prometheus's `prompb` builds its own
 * `Histogram_CountInt`, not the `write/v2` one.
 */
export function goTypePositionTarget(result: ResolvedRef, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  const target = context.getNodeById?.(result.targetNodeId);
  if (!target || target.language !== 'go') return result;
  const isType = GO_TYPE_KINDS.has(target.kind);
  // A composite literal keeps its package in the name (`config_util.URL`);
  // a parameter type leaves it on the line.
  const dot = ref.referenceName.lastIndexOf('.');
  const name = ref.referenceName.slice(dot + 1);
  // The package's directory; null for a package outside the project,
  // undefined for a qualifier that is none of the file's imports as indexed.
  let pkgDir: string | null | undefined;
  let bare = false;
  if (dot >= 0) {
    pkgDir = goImportPackageDir(ref.referenceName.slice(0, dot), ref.filePath, context);
  } else {
    const { written, imported } = goRefQualification(ref, context);
    bare = written === undefined;
    if (bare) {
      pkgDir = goBareTypeDir(name, ref.filePath, context);
      if (pkgDir === null) return null;
    } else if (imported) pkgDir = context.getGoPackageDir?.(imported.source, ref.filePath) ?? null;
  }
  if (isType && (!bare || goPackageDir(target.filePath) === pkgDir)) return result;
  const types = pkgDir ? goPackageTypes(name, pkgDir, context) : [];
  if (types.length > 0) return { ...result, targetNodeId: preferCallSiteFile(types, ref.filePath)[0]!.id };
  return isType ? result : null;
}

/**
 * Whether a Go reference is written through an imported package from outside
 * the project's modules — `context.Context`, `fmt.Errorf`, a third-party
 * `gin.H` — or is a call on a variable declared as such a package's type:
 * kubernetes' `clock.Now()` on a parameter `clock clock.PassiveClock`.
 */
function isGoExternalQualified(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const { imported, typePackage } = goRefQualification(ref, context);
  const pkg = imported ?? typePackage;
  return !!pkg && isGoOutsideImport(pkg, ref.filePath, context);
}

/**
 * Whether a Go import is of a package from outside the project's modules. A
 * relative or `/internal/` path is the project's own, mapped or not: Go lets
 * only its own module tree import an internal package.
 */
function isGoOutsideImport(imp: ImportMapping, filePath: string, context: ResolutionContext): boolean {
  return !(imp.source.startsWith('.') || imp.source.includes('/internal/') ||
    context.getGoPackageDir?.(imp.source, filePath) != null);
}

/**
 * Whether a Go type as a declaration writes it — `sync.Mutex`, `*testing.T`
 * — comes through an import of a package from outside the project.
 */
function isGoOutsideType(written: string | undefined, filePath: string, context: ResolutionContext): boolean {
  const qualifier = written && /^[*&\s]*([A-Za-z_]\w*)\s*\./.exec(written)?.[1];
  return !!qualifier && isGoOutsidePackage(qualifier, filePath, context);
}

/**
 * Whether a Go named type a declaration at `ref` writes (`goNamedType`) has
 * none of the project's methods: a type from outside the project
 * (`http.ResponseWriter`), a predeclared one, or an alias of such a type
 * (`type Ctx = context.Context`). Not one written through a qualifier none
 * of the file's imports names as indexed, or an unmapped internal package,
 * which can't be told.
 */
function goHasNoProjectMethods(named: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (isGoOutsideType(named, ref.filePath, context)) return true;
  const dot = named.indexOf('.');
  if (dot >= 0 && !goImportPackageDir(named.slice(0, dot), ref.filePath, context)) return false;
  return goWrittenType(named, ref, context) === null;
}

/** Whether `name` is the file's import of a package from outside the project: `context` in `context.WithTimeout(…)`. */
function isGoOutsidePackage(name: string, filePath: string, context: ResolutionContext): boolean {
  const imp = context.getImportMappings(filePath, 'go').find((m) => m.localName === name);
  return !!imp && isGoOutsideImport(imp, filePath, context);
}

/**
 * The named type a Go declaration writes, as `T` or `pkg.T`, its pointer and
 * type arguments dropped: `types.ID` for `*types.ID`, `sets.Set` for
 * `sets.Set[string]`. Null for a type literal — a slice, map, channel,
 * function, struct or interface — or a variadic `...T`.
 */
function goNamedType(written: string): string | null {
  const m = /^\*?\s*([A-Za-z_]\w*)(?:\s*\.\s*([A-Za-z_]\w*))?\s*(?:\[.*\])?$/.exec(written.trim());
  if (!m || GO_TYPE_KEYWORDS.has(m[1]!)) return null;
  return m[2] ? `${m[1]}.${m[2]}` : m[1]!;
}

/**
 * Whether `candidate` lives in the project package a Go reference is written
 * through, when it is one: `store.Manager` names the `Manager` of the
 * directory the `store` import maps to, never a same-named symbol of another
 * package (#2322).
 */
function isInGoQualifierPackage(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  // A package never holds a method: a call or method value landing on one is
  // made through a variable that shadows the import — prometheus's
  // `labels := &maxHeap{}`, then `labels.get()`.
  if (candidate.kind === 'method' && (ref.referenceKind === 'calls' || ref.referenceKind === 'function_ref')) return true;
  const imported = goRefQualifier(ref, context);
  if (!imported) return true;
  const pkgDir = context.getGoPackageDir?.(imported.source, ref.filePath);
  return pkgDir == null || goPackageDir(candidate.filePath) === pkgDir;
}

/**
 * A Go file's blocks and the names its functions declare: the receivers,
 * parameters and results of every `func` with a body, and each name a `:=`,
 * `var` or `const` declares.
 */
interface GoScopeIndex {
  /** The source, comments and string contents blanked, offsets kept. */
  code: string;
  lineStarts: number[];
  /** Offsets of every `{` and `}`, with the innermost block open after each. */
  events: number[];
  open: number[];
  close: Map<number, number>;
  decls: Map<string, GoDecl[]>;
  /** Where each declared name is bound, read on demand: [start, end, declaration]. */
  scopes: Map<string, Array<[number, number, GoDecl]>>;
  /** Whether the file declares a generic function or method, read on demand. */
  generic?: boolean;
}

interface GoDecl {
  /** Offset of the declared name. */
  at: number;
  /**
   * A statement's local, an `if` / `for` / `switch` header's, a `select`
   * case's, or a parameter of the function whose body opens at `body`.
   */
  kind: 'local' | 'header' | 'case' | 'param';
  body?: number;
  /** The declared type as written, when the declaration writes one. */
  type?: string;
  /** The package a `:=` takes its value from: `clocktesting` in `clock := clocktesting.NewFakeClock(…)`. */
  from?: string;
  /** The function of the file's own package a `:=` takes its value from: `newStore` in `store := newStore(…)`. */
  callee?: string;
  /**
   * Where the values a `:=`, or a `var` that writes no type, gives its names
   * start (past the `:=` or `=`), and this name's place `k` among the `n` it
   * declares: `out` is 1 of 2 in `in, out := &in.Items, &out.Items`.
   */
  value?: { at: number; k: number; n: number };
}

const GO_SCOPE_INDEXES = new WeakMap<ResolutionContext, Map<string, GoScopeIndex | null>>();
const GO_TYPE_KEYWORDS: ReadonlySet<string> = new Set(['chan', 'func', 'interface', 'map', 'struct']);
/** What a `:=` can call that is no function of the file's package: a builtin, a conversion to a predeclared type, a literal. */
const GO_PREDECLARED_CALLS: ReadonlySet<string> = new Set([
  ...GO_TYPE_KEYWORDS, 'append', 'cap', 'clear', 'close', 'complex', 'copy', 'delete', 'imag', 'len', 'make', 'max', 'min',
  'new', 'panic', 'print', 'println', 'real', 'recover', 'any', 'bool', 'byte', 'complex64', 'complex128', 'error',
  'float32', 'float64', 'int', 'int8', 'int16', 'int32', 'int64', 'rune', 'string', 'uint', 'uint8', 'uint16',
  'uint32', 'uint64', 'uintptr',
]);

/**
 * The parameter or local of the Go function around `ref` that `name` is
 * there, if one is. Go gives an identifier the innermost block that declares
 * it, from the end of its declaration on: a header's names live in its
 * statement's blocks (`else` included), a `select` case's in its clause, a
 * parameter in its function's body.
 */
function goLocalDecl(name: string, ref: Pick<UnresolvedRef, 'filePath' | 'line' | 'column'>, context: ResolutionContext): GoDecl | undefined {
  const index = goScopeIndex(ref.filePath, context);
  if (!index?.decls.has(name)) return undefined;
  return goLocalDeclAt(index, name, (index.lineStarts[ref.line - 1] ?? index.code.length) + Math.max(0, ref.column));
}

/** {@link goLocalDecl}, at an offset of the file `index` reads. */
function goLocalDeclAt(index: GoScopeIndex, name: string, at: number): GoDecl | undefined {
  let found: [number, number, GoDecl] | undefined;
  for (const scope of goScopesOf(index, name)) {
    if (at > scope[0] && at < scope[1] && (!found || scope[0] > found[0])) found = scope;
  }
  return found?.[2];
}

/**
 * The declaration {@link goLocalDecl} reads for `name` at `at` (1-based line,
 * 0-based column): where the declared name is, and the type it is declared
 * with when the declaration writes one — `d *Discovery`, `var o refresh.Options`,
 * `x := &T{…}`. Undefined when the function around `at` declares no such name:
 * it is package-level, or an import.
 */
export function goLocalDeclarationAt(
  name: string,
  at: Pick<UnresolvedRef, 'filePath' | 'line' | 'column'>,
  context: ResolutionContext
): { line: number; column: number; type?: string } | undefined {
  const decl = goLocalDecl(name, at, context);
  if (!decl) return undefined;
  const { lineStarts } = goScopeIndex(at.filePath, context)!;
  let lo = 0;
  let hi = lineStarts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (lineStarts[mid]! <= decl.at) lo = mid;
    else hi = mid - 1;
  }
  return { line: lo + 1, column: decl.at - lineStarts[lo]!, type: decl.type };
}

/**
 * Whether a Go reference's name is a parameter or local of the function
 * around it, which shadows every declaration of its package: client-go's
 * `init := func(t *testing.T) {…}` then `init(t)`.
 */
export function isGoLocallyBound(ref: UnresolvedRef, context: ResolutionContext): boolean {
  return goLocalDecl(ref.referenceName, ref, context) !== undefined;
}

function goScopeIndex(filePath: string, context: ResolutionContext): GoScopeIndex | null {
  let memo = GO_SCOPE_INDEXES.get(context);
  if (!memo) GO_SCOPE_INDEXES.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit !== undefined) return hit;
  const lines = context.getFileLines?.(filePath) ?? context.readFile(filePath)?.split(/\r?\n/);
  const index = lines ? readGoScopes(blankGoCode(lines.join('\n'))) : null;
  // Refs arrive file by file; a few files' worth is all a pass revisits.
  if (memo.size >= 64) memo.delete(memo.keys().next().value!);
  memo.set(filePath, index);
  return index;
}

function isGoIdentChar(c: number): boolean {
  return (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c === 95;
}

function readGoScopes(code: string): GoScopeIndex {
  const lineStarts = [0];
  for (let i = code.indexOf('\n'); i >= 0; i = code.indexOf('\n', i + 1)) lineStarts.push(i + 1);
  const events: number[] = [];
  const open: number[] = [];
  const close = new Map<number, number>();
  const stack: number[] = [];
  const braces = /[{}]/g;
  for (let m = braces.exec(code); m; m = braces.exec(code)) {
    const i = m.index;
    if (code.charCodeAt(i) === 123) stack.push(i);
    else {
      const at = stack.pop();
      if (at !== undefined) close.set(at, i);
    }
    events.push(i);
    open.push(stack.length > 0 ? stack[stack.length - 1]! : -1);
  }
  const decls = new Map<string, GoDecl[]>();
  const add = (name: string, decl: GoDecl): void => {
    if (name === '_') return;
    const list = decls.get(name);
    if (list) list.push(decl);
    else decls.set(name, [decl]);
  };
  // `a, b := …`: the identifiers before each `:=`.
  for (let i = code.indexOf(':='); i >= 0; i = code.indexOf(':=', i + 2)) {
    const names: Array<[string, number]> = [];
    let p = i;
    for (;;) {
      while (p > 0 && (code[p - 1] === ' ' || code[p - 1] === '\t')) p--;
      let s = p;
      while (s > 0 && isGoIdentChar(code.charCodeAt(s - 1))) s--;
      if (s === p || /\d/.test(code[s]!) || code[s - 1] === '.') break;
      names.push([code.slice(s, p), s]);
      p = s;
      while (p > 0 && (code[p - 1] === ' ' || code[p - 1] === '\t')) p--;
      if (code[p - 1] !== ',') break;
      p--;
    }
    if (names.length === 0) continue;
    const first = names[names.length - 1]![1];
    const lead = code.slice(code.lastIndexOf('\n', first - 1) + 1, first);
    const kind = /^\s*(?:\}\s*else\s+)?(?:if|for|switch)\b/.test(lead) ? 'header' : /^\s*case\b/.test(lead) ? 'case' : 'local';
    // `x := &pkg.T{…}`, `x := T{…}` and `x := new(T)` write the type they
    // declare; `x := pkg.New(…)` the package its value comes from, `x :=
    // newStore(…)` the function of its own package.
    const rhs = code.slice(i + 2, i + 160);
    const literal = /^[ \t]*&?[ \t]*((?:[A-Za-z_]\w*\.)?[A-Za-z_]\w*)[ \t]*\{/.exec(rhs)?.[1] ??
      /^[ \t]*new\([ \t]*((?:[A-Za-z_]\w*\.)?[A-Za-z_]\w*)[ \t]*\)/.exec(rhs)?.[1];
    const type = names.length === 1 && literal && !GO_TYPE_KEYWORDS.has(literal) ? literal : undefined;
    const from = /^[ \t]*&?[ \t]*([A-Za-z_]\w*)\.[A-Za-z_]\w*[ \t]*[({]/.exec(rhs)?.[1];
    const call = from ? undefined : /^[ \t]*([A-Za-z_]\w*)[ \t]*(?:\[(?:[^[\]\n]|\[[^[\]\n]*\])*\][ \t]*)?\(/.exec(rhs)?.[1];
    const callee = call && !GO_PREDECLARED_CALLS.has(call) ? call : undefined;
    // The names were read backwards from the `:=`.
    names.forEach(([name, at], r) => add(name, { at, kind, type, from, callee, value: { at: i + 2, k: names.length - 1 - r, n: names.length } }));
  }
  // `var x T`, `var a, b = …`, `const (…)`: names before a type, an `=` or
  // the line's end — in a group, on lines outside the brackets of a value
  // spanning several (`http.MethodHead,` in a `[]string{…}` is no name).
  const spec = /[ \t]*([A-Za-z_]\w*(?:[ \t]*,[ \t]*[A-Za-z_]\w*)*)(?=[ \t]*(?:\n|$|=(?!=))|[ \t]+(?:[*[A-Za-z_(]|<-))/y;
  const addSpec = (at: number): void => {
    spec.lastIndex = at;
    const s = spec.exec(code);
    if (!s) return;
    const type = /^[ \t]+([^\s=;][^=;\n]*?)[ \t]*(?:[=;\n]|$)/.exec(code.slice(at + s[0].length, at + s[0].length + 160))?.[1];
    // `var a, b = x, y`: the values that type them.
    const eq = type === undefined ? /^[ \t]*=(?!=)/.exec(code.slice(at + s[0].length, at + s[0].length + 40)) : null;
    const parts = s[1]!.split(',');
    let p = at + s[0].length - s[1]!.length;
    parts.forEach((part, k) => {
      const name = part.trim();
      const value = eq ? { at: at + s[0].length + eq[0].length, k, n: parts.length } : undefined;
      add(name, { at: p + part.indexOf(name), kind: 'local', type, value });
      p += part.length + 1;
    });
  };
  for (const m of code.matchAll(/(?<![\w.])(?:var|const)\b[ \t]*/g)) {
    const start = m.index! + m[0].length;
    if (code[start] !== '(') { addSpec(start); continue; }
    const end = goClosing(code, start);
    addSpec(start + 1);
    let depth = 0;
    for (let i = start + 1; i < end; i++) {
      const c = code[i];
      if (c === '(' || c === '[' || c === '{') depth++;
      else if (c === ')' || c === ']' || c === '}') depth--;
      else if (c === '\n' && depth === 0) addSpec(i + 1);
    }
  }
  // Each `func`'s receiver, parameters and results, bound in its body. A
  // `[]func(…)` or `chan func(…)` is a type, whatever brace follows it, and
  // so is a `func(…)` result type after a signature's `)` (#2580).
  for (const m of code.matchAll(/(?<![\w.])func\b/g)) {
    if (/(?:[\]*)]|\bchan(?:[ \t]*<-)?)[ \t]*$/.test(code.slice(Math.max(0, m.index! - 8), m.index!))) continue;
    const sig = goSignature(code, m.index! + 4);
    if (!sig) continue;
    for (const [from, to] of sig.groups) {
      for (const [name, at, type] of goParamNames(code, from, to)) add(name, { at, kind: 'param', body: sig.body, type });
    }
  }
  return { code, lineStarts, events, open, close, decls, scopes: new Map() };
}

/** The offset of the bracket closing the one at `at`, or the end of `code`. */
function goClosing(code: string, at: number): number {
  let depth = 0;
  for (let i = at; i < code.length; i++) {
    const c = code[i];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if ((c === ')' || c === ']' || c === '}') && --depth === 0) return i;
  }
  return code.length;
}

/**
 * The parameter lists of the `func` whose keyword ends at `at` — receiver,
 * parameters, results — as the offsets inside their parentheses, and the
 * offset of its body's `{`. Null for a function type, which has no body.
 */
function goSignature(code: string, at: number): { groups: Array<[number, number]>; body: number } | null {
  const groups: Array<[number, number]> = [];
  let p = at;
  const skip = (): void => { while (code[p] === ' ' || code[p] === '\t') p++; };
  const group = (): boolean => {
    if (code[p] !== '(') return false;
    const end = goClosing(code, p);
    groups.push([p + 1, end]);
    p = end + 1;
    skip();
    return true;
  };
  // `func Name[T any](…)`, `func (r T) Name(…)`, or a literal / type `func(…)`.
  const name = (): boolean => {
    const m = /^[A-Za-z_]\w*/.exec(code.slice(p, p + 128));
    if (!m || GO_TYPE_KEYWORDS.has(m[0])) return false;
    let q = p + m[0].length;
    while (code[q] === ' ' || code[q] === '\t') q++;
    if (code[q] === '[') q = goClosing(code, q) + 1;
    while (code[q] === ' ' || code[q] === '\t') q++;
    if (code[q] !== '(') return false;
    p = q;
    return true;
  };
  skip();
  if (code[p] !== '(') {
    if (!name() || !group()) return null;
  } else {
    group();
    if (name() && !group()) return null;
  }
  if (code[p] === '(') group();
  // A result type up to the body; a function type ends at a `,`, `)`, `}`,
  // `=`, `;` or the line's end instead.
  let depth = 0;
  for (; p < code.length; p++) {
    const c = code[p];
    if (c === '(' || c === '[') depth++;
    else if (c === ')' || c === ']') { if (--depth < 0) return null; }
    else if (c === '{') {
      if (depth > 0) continue;
      // `struct{…}` / `interface{…}` is the result type's own brace.
      if (/(?:struct|interface)\s*$/.test(code.slice(Math.max(0, p - 12), p))) { p = goClosing(code, p); continue; }
      return { groups, body: p };
    } else if (depth === 0 && (c === '\n' || c === ',' || c === ';' || c === '=' || c === '}')) return null;
  }
  return null;
}

/**
 * The names a Go parameter list between `from` and `to` declares, with the
 * type each is declared as: `(a, b int, c string)` declares a and b as `int`
 * and c as `string`; `(int, pkg.T)` and `(*T, ...U)` declare none.
 */
function goParamNames(code: string, from: number, to: number): Array<[string, number, string]> {
  const parts: Array<[number, number]> = [];
  let depth = 0;
  let start = from;
  for (let i = from; i < to; i++) {
    const c = code[i];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth--;
    else if (c === ',' && depth === 0) { parts.push([start, i]); start = i + 1; }
  }
  parts.push([start, to]);
  const names: Array<[string, number, string]> = [];
  let grouped: Array<[string, number]> = [];
  for (const [s, e] of parts) {
    const text = code.slice(s, e);
    const m = /^\s*([A-Za-z_]\w*)/.exec(text);
    if (!m || GO_TYPE_KEYWORDS.has(m[1]!)) continue;
    const rest = text.slice(m[0].length);
    // `pkg.T` is a type; a variadic `args ...T` is a name.
    if (/^\s*\.(?!\.\.)/.test(rest)) continue;
    const at = s + m[0].length - m[1]!.length;
    if (/^\s*$/.test(rest)) { grouped.push([m[1]!, at]); continue; }
    // `a, b int`: the names before a typed one share its type.
    const type = rest.trim();
    for (const [name, nameAt] of grouped) names.push([name, nameAt, type]);
    grouped = [];
    names.push([m[1]!, at, type]);
  }
  // A list with no typed name names no parameters: its lone identifiers are types.
  return names;
}

/** The innermost `{…}` holding an offset, as [open, close] — null outside every block. */
function goBlockAt(index: GoScopeIndex, offset: number): [number, number] | null {
  let lo = 0;
  let hi = index.events.length - 1;
  let at = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (index.events[mid]! < offset) { at = mid; lo = mid + 1; } else hi = mid - 1;
  }
  const open = at < 0 ? -1 : index.open[at]!;
  return open < 0 ? null : [open, index.close.get(open) ?? index.code.length];
}

/** Where the statement declaring at `at` ends: its line's end, or a `;`, outside brackets. */
function goStatementEnd(code: string, at: number): number {
  let depth = 0;
  for (let i = at; i < code.length; i++) {
    const c = code[i];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') { if (--depth < 0) return i; }
    else if ((c === '\n' || c === ';') && depth === 0) return i;
  }
  return code.length;
}

/**
 * The blocks of the `if` / `for` / `switch` statement whose header declares
 * at `at`: gofmt ends a header's line with its block's `{` (a composite
 * literal's in the header has more on its line), and an `else` chain keeps
 * the header's names.
 */
function goHeaderBlocks(index: GoScopeIndex, at: number): Array<[number, number]> {
  const code = index.code;
  const blocks: Array<[number, number]> = [];
  let depth = 0;
  for (let i = at; i < code.length; i++) {
    const c = code[i];
    if (c === '(' || c === '[') depth++;
    else if (c === ')' || c === ']') depth--;
    else if (c === '}') break;
    else if (c === '{') {
      const end = index.close.get(i) ?? code.length;
      if (depth !== 0 || !/^[ \t]*(?:\n|$)/.test(code.slice(i + 1, i + 80))) { i = end; continue; }
      blocks.push([i, end]);
      const chained = /^[ \t]*else\b[ \t]*/.exec(code.slice(end + 1, end + 40));
      if (!chained) break;
      i = end + chained[0].length;
      depth = 0;
    }
  }
  return blocks;
}

function goScopesOf(index: GoScopeIndex, name: string): Array<[number, number, GoDecl]> {
  const hit = index.scopes.get(name);
  if (hit) return hit;
  const scopes: Array<[number, number, GoDecl]> = [];
  for (const d of index.decls.get(name) ?? []) {
    if (d.kind === 'param') {
      scopes.push([d.body!, index.close.get(d.body!) ?? index.code.length, d]);
      continue;
    }
    // Outside every block it is a package-level name, which no import shares.
    const block = goBlockAt(index, d.at);
    if (!block) continue;
    if (d.kind === 'header') {
      for (const [start, end] of goHeaderBlocks(index, d.at)) scopes.push([start, end, d]);
      continue;
    }
    const from = goStatementEnd(index.code, d.at);
    let to = block[1];
    // A `case` clause's names, header or body, end at the next clause.
    {
      const clause = /\n[ \t]*(?:case\b|default[ \t]*:)/g;
      clause.lastIndex = from;
      for (let m = clause.exec(index.code); m && m.index < to; m = clause.exec(index.code)) {
        if (goBlockAt(index, m.index + 1)?.[0] === block[0]) { to = m.index; break; }
      }
    }
    if (from < to) scopes.push([from, to, d]);
  }
  index.scopes.set(name, scopes);
  return scopes;
}

/**
 * Go source with its comments and the contents of its strings and runes
 * blanked: offsets and newlines stay, so a regex match still maps to its
 * line and column.
 */
export function blankGoCode(src: string): string {
  const parts: string[] = [];
  let last = 0;
  const blank = (from: number, to: number): void => {
    parts.push(src.slice(last, from));
    const newline = src.indexOf('\n', from);
    parts.push(newline < 0 || newline >= to ? ' '.repeat(to - from) : src.slice(from, to).replace(/[^\n]/g, ' '));
    last = to;
  };
  const special = /[/"'`]/g;
  for (let m = special.exec(src); m; m = special.exec(src)) {
    const i = m.index;
    const c = src.charCodeAt(i);
    if (c === 47) {
      const d = src.charCodeAt(i + 1);
      if (d === 47) { // `//`
        const end = src.indexOf('\n', i);
        blank(i, end < 0 ? src.length : end);
      } else if (d === 42) { // `/*`
        const end = src.indexOf('*/', i + 2);
        blank(i, end < 0 ? src.length : end + 2);
      } else continue;
      special.lastIndex = last;
    } else if (c === 96) { // a raw string
      const end = src.indexOf('`', i + 1);
      blank(i + 1, end < 0 ? src.length : end);
      special.lastIndex = last + 1;
    } else { // "…" or '…'
      let j = i + 1;
      while (j < src.length) {
        const d = src.charCodeAt(j);
        if (d === 92) { j += 2; continue; }
        if (d === c || d === 10) break;
        j++;
      }
      blank(i + 1, Math.min(j, src.length));
      special.lastIndex = last + 1;
    }
  }
  parts.push(src.slice(last));
  return parts.join('');
}

const PHP_CLASS_KINDS: ReadonlySet<string> = new Set(['class', 'interface', 'trait', 'enum']);
/**
 * Whether a bare PHP class name at `ref` can mean `candidate`. An unqualified
 * class name is the current namespace's class or the one a `use` imports —
 * PHP never falls back to another namespace for classes. koel's `extends
 * Request` (under `use Saloon\Http\Request;`, `use App\Http\Requests\API\Request;`,
 * or in `App\Http\Requests\API` itself) all went to the first `Request` indexed.
 */
function isPhpClassVisible(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'php' || candidate.language !== 'php' || !PHP_CLASS_KINDS.has(candidate.kind)) return true;
  const name = ref.referenceName;
  if (!/^[A-Za-z_]\w*$/.test(name) || /^(?:self|static|parent)$/i.test(name)) return true;
  const fqn = candidate.qualifiedName.replace(/::/g, '\\');
  const scope = phpFileScope(ref.filePath, context);
  const imported = scope.uses.get(name);
  if (imported !== undefined) return imported.toLowerCase() === fqn.toLowerCase();
  return fqn.toLowerCase() === (scope.namespace ? `${scope.namespace}\\${name}` : name).toLowerCase();
}

const JAVA_TYPE_KINDS_VISIBLE: ReadonlySet<string> = new Set(['class', 'interface', 'enum', 'record', 'annotation']);
const JAVA_FILE_SCOPES = new WeakMap<ResolutionContext, Map<string, { pkg: string; single: Set<string>; demand: Set<string> }>>();
const JAVA_ANCESTORS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/** A Java file's package, its single-type imports and its on-demand (`.*`) imports, static ones included. */
function javaFileScope(file: string, context: ResolutionContext): { pkg: string; single: Set<string>; demand: Set<string> } {
  let memo = JAVA_FILE_SCOPES.get(context);
  if (!memo) JAVA_FILE_SCOPES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const text = stripCommentsForRegex(context.readFile(file) ?? '', 'java');
  const pkg = /^\s*package\s+([\w.]+)\s*;/m.exec(text)?.[1] ?? '';
  const single = new Set<string>();
  const demand = new Set<string>();
  for (const m of text.matchAll(/^\s*import\s+(?:static\s+)?([\w.]+?)(\.\*)?\s*;/gm)) (m[2] ? demand : single).add(m[1]!);
  const scope = { pkg, single, demand };
  memo.set(file, scope);
  return scope;
}

/** The simple names of the Java types `qn` extends or implements, a few levels up. */
function javaAncestorNames(qn: string, context: ResolutionContext, depth = 0): Set<string> {
  let memo = JAVA_ANCESTORS.get(context);
  if (!memo) JAVA_ANCESTORS.set(context, (memo = new Map()));
  const hit = memo.get(qn);
  if (hit) return hit;
  const names = new Set<string>();
  memo.set(qn, names);
  for (const decl of context.getNodesByQualifiedName(qn)) {
    if (decl.language !== 'java' || !JAVA_TYPE_KINDS_VISIBLE.has(decl.kind)) continue;
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    let header = '';
    for (let i = decl.startLine - 1; i < Math.min(lines.length, decl.startLine + 6) && !header.includes('{'); i++) header += `${lines[i] ?? ''} `;
    const list = /\b(?:extends|implements)\b([^{]*)/.exec(header.split('{')[0]!)?.[1] ?? '';
    for (const m of list.replace(/<[^<>]*(?:<[^<>]*>[^<>]*)*>/g, '').matchAll(/([A-Za-z_]\w*)\s*(?=,|$|\bimplements\b|\s*$)/g)) {
      if (m[1] !== 'implements' && m[1] !== 'extends') names.add(m[1]!);
    }
  }
  if (depth < 4) {
    for (const base of [...names]) {
      for (const t of context.getNodesByName(base)) {
        if (t.language !== 'java' || !JAVA_TYPE_KINDS_VISIBLE.has(t.kind) || t.qualifiedName === qn) continue;
        for (const up of javaAncestorNames(t.qualifiedName, context, depth + 1)) names.add(up);
      }
    }
  }
  return names;
}

/**
 * Whether a bare Java type name at `ref` can mean `candidate`. A top-level type
 * is in reach from its own package and through a single-type or on-demand
 * import; a nested type from inside its owner (or a type deriving from it) or
 * through an import of it or of its owner's members. halo's `Context`,
 * retrofit's `Builder`, jsoup's `Attribute` (meant: `Evaluator.Attribute`)
 * reached a same-named type nothing imported.
 */
function isJavaTypeVisible(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'java' || candidate.language !== 'java') return true;
  if (!/^[A-Za-z_$][\w$]*$/.test(ref.referenceName)) return true;
  // A constructor is in reach where its type is: lombok's `@Builder` and
  // okhttp's `new OkHttpClient.Builder()` are no project `Builder`'s constructor.
  if (candidate.kind === 'method') {
    const segs = candidate.qualifiedName.split('::');
    if (segs.length < 2 || segs[segs.length - 2] !== candidate.name || ref.referenceKind === 'calls') return true;
    const owner = context.getNodesInFile(candidate.filePath).find((n) =>
      n.qualifiedName === segs.slice(0, -1).join('::') && JAVA_TYPE_KINDS_VISIBLE.has(n.kind));
    return !owner || isJavaTypeVisible(owner, ref, context);
  }
  // An enum constant by its bare name: inside its enum, a `case` label, a
  // static import, or written through its enum — never `java.lang.Character`'s
  // `Character.MIN_SUPPLEMENTARY_CODE_POINT` (jsoup's `TokenType.Character`).
  if (candidate.kind === 'enum_member') {
    if (candidate.filePath === ref.filePath) return true;
    const segs = candidate.qualifiedName.split('::');
    const enumName = segs[segs.length - 2] ?? '';
    const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1] ?? '';
    const name = escapeRegExp(ref.referenceName);
    if (new RegExp(`\\bcase\\b[^:;]*\\b${name}\\b`).test(line) || new RegExp(`\\b${escapeRegExp(enumName)}\\s*\\.\\s*${name}\\b`).test(line)) return true;
    const here = javaFileScope(ref.filePath, context);
    const enumFqn = [javaFileScope(candidate.filePath, context).pkg, ...segs.slice(1, -1)].filter((p) => p !== '').join('.');
    return here.single.has(`${enumFqn}.${ref.referenceName}`) || here.demand.has(enumFqn);
  }
  if (!JAVA_TYPE_KINDS_VISIBLE.has(candidate.kind)) return true;
  const segs = candidate.qualifiedName.split('::');
  const candidateScope = javaFileScope(candidate.filePath, context);
  // The QN leads with the package when there is one.
  const typePath = candidateScope.pkg && segs[0] === candidateScope.pkg ? segs.slice(1) : segs;
  const fqn = [candidateScope.pkg, ...typePath].filter((p) => p !== '').join('.');
  const here = javaFileScope(ref.filePath, context);
  // Written with a qualifier — `RequestFactory.Builder`, `java.util.Map`, an
  // inner class's `outer.new Inner()` — the qualifier says which: the owner
  // (or the package) of this candidate.
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1] ?? '';
  if (new RegExp(`\\.\\s*new\\s+${escapeRegExp(ref.referenceName)}\\b`).test(line)) return true;
  // (A type annotation may sit between them: jsoup's `Range.@Nullable Spans`.)
  const qualifiers = [...line.matchAll(new RegExp(`([A-Za-z_$][\\w$.]*)\\s*\\.\\s*(?:@[\\w.]+(?:\\([^)]*\\))?\\s+)*${escapeRegExp(ref.referenceName)}\\b`, 'g'))].map((m) => m[1]!);
  // Nested only inside a type the file declares; a class local to a method is
  // the lexical rule's to judge.
  const ownerQn = segs.slice(0, -1).join('::');
  const ownerNode = segs.length > 1
    ? context.getNodesInFile(candidate.filePath).find((n) => n.qualifiedName === ownerQn && n.kind !== 'namespace' && n.kind !== 'file')
    : undefined;
  if (ownerNode && !JAVA_TYPE_KINDS_VISIBLE.has(ownerNode.kind)) return true;
  const nested = ownerNode !== undefined;
  const ownerName = nested ? ownerNode.name : '';
  if (qualifiers.some((q) => (nested && (q === ownerName || q.endsWith(`.${ownerName}`))) || (!nested && q === candidateScope.pkg))) return true;
  if (!nested) {
    if (candidate.filePath === ref.filePath || candidateScope.pkg === here.pkg) return true;
    return here.single.has(fqn) || here.demand.has(candidateScope.pkg);
  }
  // Nested: inside its owner, a subtype of it, or imported.
  const enclosing = context.getNodesInFile(ref.filePath)
    .filter((p) => JAVA_TYPE_KINDS_VISIBLE.has(p.kind) && p.startLine <= ref.line && p.endLine >= ref.line);
  if (enclosing.some((p) => p.qualifiedName === ownerQn || p.qualifiedName.startsWith(`${ownerQn}::`))) return true;
  // An anonymous class (`new NodeFilter() { … }`, named `<NodeFilter$anon@N>`) derives from what it instantiates.
  const supertypesAround = (p: Node): string[] => {
    const anon = /<([A-Za-z_$][\w$]*)\$anon@\d+>$/.exec(p.name)?.[1] ?? /<([A-Za-z_$][\w$]*)\$anon@\d+>/.exec(p.qualifiedName.split('::').pop() ?? '')?.[1];
    if (!anon) return [...javaAncestorNames(p.qualifiedName, context)];
    const ups = [anon];
    for (const t of context.getNodesByName(anon)) if (t.language === 'java' && JAVA_TYPE_KINDS_VISIBLE.has(t.kind)) ups.push(...javaAncestorNames(t.qualifiedName, context));
    return ups;
  };
  if (enclosing.some((p) => supertypesAround(p).includes(ownerName))) return true;
  const ownerFqn = fqn.slice(0, fqn.lastIndexOf('.'));
  return here.single.has(fqn) || here.demand.has(ownerFqn);
}

const SCALA_OBJECT_PACKAGES = new WeakMap<ResolutionContext, Map<string, string | null>>();

/** The full package a Scala file's `package object X` opens (`algebra`, `cats.syntax`), or null for none. */
function scalaPackageObjectPackage(file: string, context: ResolutionContext): string | null {
  let memo = SCALA_OBJECT_PACKAGES.get(context);
  if (!memo) SCALA_OBJECT_PACKAGES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit !== undefined) return hit;
  const text = context.readFile(file) ?? '';
  const object = /^\s*package\s+object\s+([\w$]+)/m.exec(text)?.[1];
  const pkg = object ? [...scalaPackageClauses(text), object].join('.') : null;
  memo.set(file, pkg);
  return pkg;
}

/** A Scala file's package clauses, in order (`package cats` / `package laws` → cats, laws). */
function scalaPackageClauses(text: string): string[] {
  return [...text.matchAll(/^\s*package\s+(?!object\b)([\w.]+)\s*$/gm)].flatMap((m) => m[1]!.split('.'));
}

/**
 * Whether a member of a Scala package object is in scope at `ref`: from its
 * package and the packages under it, or from a file that imports something
 * through the package (`import algebra._`, `import algebra.Eq`).
 */
function isScalaPackageObjectMemberVisible(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const objectPkg = scalaPackageObjectPackage(candidate.filePath, context);
  if (objectPkg === null) return true;
  const text = context.readFile(ref.filePath) ?? '';
  const here = scalaPackageClauses(text).join('.');
  if (here === objectPkg || here.startsWith(`${objectPkg}.`)) return true;
  const last = objectPkg.split('.').pop()!;
  return new RegExp(`^\\s*import\\s+[^\\n]*\\b${escapeRegExp(last)}\\b`, 'm').test(text);
}

const SFC_SCRIPT_RANGES = new WeakMap<ResolutionContext, Map<string, Array<{ start: number; end: number; exported: boolean }>>>();

/**
 * Whether a declaration in a `.svelte` / `.vue` file is the component's own:
 * anything but the component itself, unless it sits in a block that can export
 * — Svelte's `<script module>` (`context="module"`), or a Vue `<script>` that
 * is not `setup` — or is a type a Vue `<script setup>` exports.
 */
function isSfcPrivate(n: Node, context: ResolutionContext): boolean {
  const svelte = n.filePath.endsWith('.svelte');
  if ((!svelte && !n.filePath.endsWith('.vue')) || n.kind === 'component' || n.kind === 'file') return false;
  let memo = SFC_SCRIPT_RANGES.get(context);
  if (!memo) SFC_SCRIPT_RANGES.set(context, (memo = new Map()));
  let ranges = memo.get(n.filePath);
  if (!ranges) {
    ranges = [];
    const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
    let open: { start: number; exported: boolean } | null = null;
    lines.forEach((text, i) => {
      const tag = /<script\b([^>]*)>/i.exec(text);
      if (tag && !open) {
        const attrs = tag[1] ?? '';
        open = { start: i + 1, exported: svelte ? /\bmodule\b|context\s*=\s*["']module["']/.test(attrs) : !/\bsetup\b/.test(attrs) };
      }
      if (open && /<\/script\s*>/i.test(text)) {
        ranges!.push({ ...open, end: i + 1 });
        open = null;
      }
    });
    memo.set(n.filePath, ranges);
  }
  const block = ranges.find((r) => n.startLine >= r.start && n.startLine <= r.end);
  if (block?.exported) return false;
  // Vue hoists the types `<script setup>` exports: mealie imports CrudTable.vue's `TableConfig`.
  if (!svelte && block) {
    const line = context.getFileLines?.(n.filePath)?.[n.startLine - 1] ?? context.readFile(n.filePath)?.split(/\r?\n/)[n.startLine - 1] ?? '';
    if (/^\s*export\s+(?:declare\s+)?(?:interface|type|enum)\b/.test(line)) return false;
  }
  return true;
}

/** Per-context memo: node id → "this member sits inside a `private` class/object". */
const PRIVATE_OWNER_MEMO = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** Kinds that own members and carry a visibility of their own. */
const OWNER_KINDS = new Set<string>(['class', 'interface', 'struct', 'enum', 'namespace']);

/**
 * Whether `candidate` is a member of a `private` type in its file — a Kotlin
 * test's `private class Clock { fun now() = value }`: the method is public,
 * the class is not, so nothing outside the file can name `now`. Found by
 * line range among the file's own nodes, memoised per node.
 */
function isInsidePrivateType(candidate: Node, context: ResolutionContext): boolean {
  let memo = PRIVATE_OWNER_MEMO.get(context);
  if (!memo) {
    memo = new Map();
    PRIVATE_OWNER_MEMO.set(context, memo);
  }
  const hit = memo.get(candidate.id);
  if (hit !== undefined) return hit;
  const inside = context.getNodesInFile(candidate.filePath).some(
    (n) =>
      n.id !== candidate.id &&
      OWNER_KINDS.has(n.kind) &&
      n.visibility === 'private' &&
      n.startLine <= candidate.startLine &&
      n.endLine >= candidate.endLine
  );
  memo.set(candidate.id, inside);
  return inside;
}

/**
 * Whether Go lets `ref`'s file name the Go declaration `candidate`: an
 * exported name from anywhere, an unexported one only inside its own package,
 * which is a directory. By the name's first letter, not the extractor's flag:
 * an index built before Go methods carried the flag has it unset on every one.
 *
 * A package's external tests (`package a_test` beside `package a`) share its
 * directory but are a package of their own: a name one of them declares at
 * the top level reaches the other only through an import, written `a.Real`,
 * or bare after `import . "…/a"`, and then only an exported one. A test
 * helper `corpus` in `package a_test` is not package `a`'s `corpus` (#2581).
 */
function isGoNameVisible(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const dir = goPackageDir(candidate.filePath);
  if (dir !== goPackageDir(ref.filePath)) return /^[A-Z]/.test(candidate.name);
  if (candidate.filePath === ref.filePath || TYPE_MEMBER_KINDS.has(candidate.kind) || ref.referenceName.includes('.')) return true;
  const own = goPackageClause(ref.filePath, context);
  const theirs = goPackageClause(candidate.filePath, context);
  if (own === null || theirs === null || own === theirs) return true;
  return /^[A-Z]/.test(candidate.name) && goDotImports(ref.filePath, context).dirs.includes(dir);
}

/**
 * Whether `candidate` can be NAMED from a reference in `ref`'s file at all,
 * given what its language says about the definition's visibility. A
 * definition the language makes file-local is not a candidate for a
 * cross-file name match, however well the names agree:
 *
 * - **C / C++**: a `static` function defined in a SOURCE file is local to
 *   that translation unit; one in a header is part of every unit that
 *   includes it and stays visible. On a 2,109-file betaflight tree 145
 *   cross-file calls resolved onto a `static` in another `.c` (#1730) —
 *   `usbd_get_descriptor` onto the `static get_device_descriptor` of
 *   whichever USB class file ranked first. So is what a source file's
 *   unnamed namespace declares, and a type only source files declare, with
 *   its members (isCppTranslationUnitLocal).
 * - **Objective-C**: a struct, union, enum, typedef or global a `.m` / `.mm`
 *   source file defines is local to that file, as in C; other files reach a
 *   global through its header's `extern` declaration. A class is not.
 * - **Kotlin, Java, C#, Swift, Scala, PHP**: `private` is class- or
 *   file-local. An Android `editor.apply()` resolved onto an unrelated class's
 *   `private fun apply`.
 * - **Dart**: a `_name` is private to its library — the library file and the
 *   files its `part` directives name — so another file of the library names
 *   it, and a file of another library never does (#2466).
 * - **Go**: an unexported (lowercase) identifier is package-local, and a
 *   package is a directory. Judged by the name's case, which an older index's
 *   Go methods don't carry in `isExported`.
 * - **Rust**: a non-`pub` item is visible to its module and that module's
 *   descendants, never to a sibling module or another crate — `.count()` on
 *   an iterator resolved onto a `fn count` in a different crate. A method in
 *   an `impl Trait for Type` block has the trait's visibility, not `private`.
 * - **JS / TS / ArkTS**: a binding in a module that exports nothing (an
 *   `import` present, no `export` / CommonJS / `declare global`) is sealed —
 *   the vite playground's `const vite = await createServer(…)` took 157
 *   `import { defineConfig } from 'vite'` edges (#1719). Classic scripts,
 *   CommonJS, later `export { … }`, and ambient globals stay visible.
 *
 * Same-file candidates are always visible. Applied by ReferenceResolver to
 * the target the whole name-matching pipeline settled on, so a rejection ends
 * the reference unresolved: declining inside matchByExactName instead let the
 * ref fall through to matchFuzzy, which then committed to a same-language
 * namesake the ranking had passed over — eight such edges on one tree, all
 * onto a local `const fail = …` arrow the graph does not hold. matchFuzzy
 * checks its own survivor as well, since nothing runs after it.
 */
export function isVisibleAcrossFiles(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  // Go's `context.Context`, `http.Handler`: written through a package from
  // outside the module, so nothing in it — not even the same file's method
  // `Stream.Context` (fiber's 85 `context.Context` parameters went there).
  // Through one of the project's packages, only that package's symbol: a
  // `job.OPCommand` result type is not the method `Context.OPCommand`.
  if (ref.language === 'go' && candidate.language === 'go' &&
      (isGoExternalQualified(ref, context) || !isInGoQualifierPackage(candidate, ref, context))) return false;
  if (candidate.filePath === ref.filePath) return true;
  // A vendored minified bundle's names are mangled: healthchecks' 369 `$(…)`
  // (jQuery, a global) went to a one-letter helper inside bootstrap-native.min.js.
  if (isMinifiedScript(candidate.filePath, context)) return false;
  // A test suite is not linked into the program: typeorm's `Record<K, V>` is
  // not a test entity `Record`, tokio's `Output` not a `runtime/tests` type.
  // A C or C++ file the reference's translation unit includes is, whatever
  // its name.
  if (isTestSuitePath(candidate.filePath) && !isTestPath(ref.filePath) && !isIncludedCppTestSuite(candidate, ref, context)) return false;
  // A Svelte component's instance script, or a Vue SFC's `<script setup>`, is
  // private to the component: shadcn-svelte's 838 `<Item.Root>` (a namespace
  // import) went to a `type Item` one example component declares for itself.
  if (isSfcPrivate(candidate, context)) return false;
  // A bare PHP class name is its namespace's class, or the one a `use` names.
  if (!isPhpClassVisible(candidate, ref, context)) return false;
  // A bare Java type name is its package's, an import's, or a nested type in reach.
  if (!isJavaTypeVisible(candidate, ref, context)) return false;
  // A Dart `extension on Token { … }` has no name: `Token` is analyzer's type,
  // not bloc_lint's extension block (84 refs went there).
  if (dartExtensionDecl(candidate, context)?.named === false) return false;
  // And it applies only in its own library: flutter_test's `find.text(…)` is
  // no other file's `extension on TaskStatus { String get text }`.
  if (isDartUnnamedExtensionMember(candidate, context) && !inSameDartLibrary(ref.filePath, candidate.filePath, context)) return false;
  // A Scala package object's member is in scope in its package and those under
  // it, or through an import: cats.laws' `Eq` is the `cats` package object's
  // alias, not the `algebra` one's (752 refs went there).
  if (candidate.language === 'scala' && ref.language === 'scala' && !isScalaPackageObjectMemberVisible(candidate, ref, context)) return false;
  if (candidate.language === 'csharp' && ref.language === 'csharp' && CSHARP_TYPE_KINDS.has(candidate.kind) &&
      /^[A-Za-z_]\w*$/.test(ref.referenceName) &&
      (!isCsharpTypeVisible(candidate, ref, context) || !isCsharpNestedTypeInScope(candidate, ref, context))) return false;
  const lang = candidate.language as string;
  if (lang === 'c' || lang === 'cpp') {
    // A source file's `static` function, only for that file and one that
    // `#include`s it: hiredis's async.c includes dict.c.
    if (candidate.kind === 'function' && C_SOURCE_EXT.test(candidate.filePath) && isStaticCFunction(candidate, context) &&
        !cppIncluders(candidate.filePath, context).has(ref.filePath)) return false;
    return !isCppTranslationUnitLocal(candidate, ref, context);
  }
  // An Objective-C source file is a translation unit too: a C type it defines
  // is its own. ObjFW's runtime keeps `static struct Lock { … } *locks;` in
  // synchronized.m, and the AmigaOS `Lock(path, mode)` calls in other files
  // make no such struct. So is a global it defines: another file reaches one
  // through the header that declares it (`extern OFStdIOStream *OFStdOut;`),
  // whose node stands for it there. React Native's
  // `completionHandler(nil, image)` calls a block parameter, not the
  // `completionHandler` another .mm file keeps, and `#include <vector>` names
  // no `.mm` file's `vector`. (A class is the runtime's, wherever it is
  // written.)
  if (isObjcFileLocalElsewhere(candidate, ref)) return false;
  if (lang === 'go') return isGoNameVisible(candidate, ref, context);
  if (lang === 'rust') {
    if (candidate.visibility !== 'private') return true;
    if (isRustTraitImplMethod(candidate, context)) return true;
    // A method a trait declares carries no `pub` of its own: it is the
    // trait's, reached through a value whose type the call's receiver
    // declares (matchRustTypedReceiverCall). A guess by its name alone stays out.
    if (candidate.kind === 'method' && RUST_TYPED_REFS.get(context)?.has(ref) && rustTraitOf(candidate, context)?.visibility !== 'private') return true;
    return rustFileUnder(ref.filePath, rustModuleDir(candidate.filePath), candidate.filePath, context);
  }
  // A Dart `_name` is its library's, which spans the library file and its
  // parts: riverpod_generator's `class Counter extends _$Counter` names the
  // class it wrote into `main.g.dart`, and protobuf.dart's GeneratedMessage
  // calls `_fieldSet._clear()` on the FieldSet another part declares.
  if (lang === 'dart') {
    return candidate.visibility !== 'private' || (ref.language === 'dart' && dartPrivateVisible(ref.filePath, candidate.filePath, context));
  }
  if (PRIVATE_IS_FILE_LOCAL.has(lang)) {
    // Only Kotlin's private type keeps its members in its file: a Scala
    // `private[pkg] class` (or one with a private constructor) is the package's,
    // and a C# private nested class serves every file of its partial class.
    return candidate.visibility !== 'private' && !(lang === 'kotlin' && isInsidePrivateType(candidate, context));
  }
  // An R test file runs in an environment of its own (testthat): its top-level
  // `c <- ggplot(…)` is not what the package's 2,843 `c(…)` calls mean. The
  // `helper-*.R` / `setup-*.R` files are sourced for every test, so theirs are shared.
  if (lang === 'r' && (candidate.kind === 'variable' || candidate.kind === 'constant') &&
      /(?:^|\/)tests?\//.test(candidate.filePath) && !/(?:^|\/)(?:helper|setup)[^/]*\.[rR]$/.test(candidate.filePath)) return false;
  // A Lua `local` belongs to its chunk: kong's spec helpers' `local it = it`
  // took busted's `it(…)` in every other spec file, 4,166 times. Its module
  // can still hand it out — `return { check = check_phase }` — to a file that
  // names it through a `require` alias.
  if ((lang === 'lua' || lang === 'luau') && isLuaLocal(candidate, context)) {
    return ref.referenceKind === 'calls' && /^[A-Za-z_]\w*$/.test(ref.referenceName) &&
      luaAliasTarget(ref, context)?.targetNodeId === candidate.id;
  }
  // JS/TS/ArkTS sealed modules + markdown/JSON call-target guards (#1719).
  // Same predicate matchByExactName / matchFuzzy apply to their survivors so a
  // rejection here cannot fall through to a promoted runner-up.
  return isCrossFileReachable(candidate, ref, context);
}

/**
 * Languages whose calls are JS/TS calls — Vue, Svelte and Astro components'
 * scripts and template expressions included: a bare `t('key')` in a `.vue`
 * file resolves lexically exactly as in a `.ts` one.
 */
const JS_FAMILY = new Set<string>(['typescript', 'tsx', 'javascript', 'jsx', 'vue', 'svelte', 'astro']);
const JS_TS = new Set<string>(['typescript', 'tsx', 'javascript', 'jsx']);

/** Languages whose identifiers resolve regardless of case. */
export const CASE_INSENSITIVE_LANGUAGES = new Set<string>(['php', 'pascal', 'cfml', 'cfscript', 'cfquery', 'cobol', 'vbnet']);

/**
 * Whether a JS/TS `calls` ref is a RECEIVER-LESS call — `serialize(x)`, not
 * `this.serialize(x)` / `obj.serialize(x)`. The extractor emits `this.m()`
 * and `super.m()` under the bare method name, so the receiver is read back
 * from the call site's own line: the text at the ref's column is the call
 * expression, and it starts with the name itself only when nothing precedes
 * it. In JS/TS a bare call can never bind to a class method (methods need a
 * receiver), so a `method` node is not a candidate for it (#1714) — the
 * enclosing method itself least of all, which the same-file proximity term
 * used to pick over the module-scope function the call actually means.
 */
/**
 * The receiver a call the extractor recorded by its bare name is written on,
 * read from the source: TS/JS keeps `this.container.classList.toggle()` and
 * `window.$events.listen()` bare, Scala `requestToArmeria(request).execute()`
 * and `_.get.whenRequestMatchesPartial(…)`. `'self'` for `this.m()` /
 * `self.m()` / `super.m()` / `super().m()` — in JS, `self.m()` only when the
 * file binds `self` (`globalThis.self` otherwise); null for a call written
 * bare (or not found). `links` are the member names between `this` and the
 * method.
 */
function bareCallReceiver(ref: UnresolvedRef, context: ResolutionContext): { receiver: string; links: string[] } | null {
  if (ref.referenceKind !== 'calls' || !/^[A-Za-z_$][\w$]*$/.test(ref.referenceName)) return null;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  if (!lines) return null;
  const name = ref.referenceName.replace(/\$/g, '\\$');
  const call = new RegExp(`(?<![\\w$])${name}\\s*(?:<[^<>()]*>|\\[(?:[^\\[\\]]|\\[[^\\[\\]]*\\])*\\])?\\s*[({]`);
  // Search the ref's own line first: a minified bundle is one line, and
  // joining it to the lines after it copied all of it for every call on it
  // (about 1 MB a call on go-ethereum's graphiql.min.js). Every match starts
  // with the name, so a match with no `name` before it on the line is where
  // the joined lines match first too. Otherwise (no match, as for a call that
  // continues on the next line, or the name earlier) the joined lines decide.
  const span = lines.slice(ref.line - 1, ref.line + 7);
  const from = Math.max(0, ref.column);
  let text = span[0]?.slice(from) ?? '';
  let at = call.exec(text);
  if (!at || text.indexOf(ref.referenceName) < at.index) {
    text = span.join('\n').slice(from);
    at = call.exec(text);
  }
  if (!at) return null;
  const before = text.slice(0, at.index).replace(/\s+$/, '');
  if (!/\??\.$/.test(before)) return null;
  const head = before.replace(/\??\.$/, '').replace(/\s+$/, '');
  // A JS `self` the file doesn't bind is the global object's own `self` — a
  // worker's scope, or the page's `window` — never `this`, and is read as the
  // path it is (`'self'` alone would read as `this`).
  if (isJsGlobalSelf(head, ref, context)) return { receiver: 'globalThis.self', links: [] };
  if (/(?:^|[^\w$.])(?:this|self|super|Self)$/.test(head) || /(?:^|[^\w$.])super\s*\([^()]*\)$/.test(head)) return { receiver: 'self', links: [] };
  const chain = /(?:^|[^\w$.#])((?:this|super)(?:\s*\??\.\s*#?[\w$]+)+)$/.exec(head);
  const links = chain ? chain[1]!.split('.').slice(1).map((l) => l.replace(/[\s?]/g, '')) : [];
  return { receiver: head.slice(-40), links };
}

/**
 * Whether a JS/TS name is one of the browser's own objects where the
 * reference is written (JS_BROWSER_HOST_GLOBALS: `window`, `self`,
 * `localStorage`, `history`, …) because the file uses the name only that way
 * (usesNameOnlyAsReceiver). A call on one is the browser's, never a project
 * method: `window.open()` is no `WindowService::open`, `history.back()` no
 * router's `back` (#2907). A file that binds the name — `const history =
 * createRouter()`, `var self = this`, a parameter, plain or destructured like
 * outline's `({ document }: Props)` — or imports it calls what that holds.
 */
function isBrowserHostGlobal(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return JS_FAMILY.has(ref.language) && JS_BROWSER_HOST_GLOBALS.has(name) &&
    usesNameOnlyAsReceiver(name, ref.filePath, context);
}

/** Per context, by `file\0name`: whether the file uses the name only as a receiver. */
const RECEIVER_ONLY_NAMES = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether a JS/TS file writes `name` only as a receiver — `document.x`,
 * `history.back()`, `self?.close()`, `localStorage['k']` — or after
 * `typeof`, which is how code uses one of the browser's own objects. Any
 * other mention may bind or hand over a value of the file's own: a parameter
 * (destructured ones included), a declaration, an import, an argument, an
 * object key. Read with comments and strings blanked; a property of the same
 * name (`x.document`) is no mention. An indexOf scan, not a look-behind
 * regex, so a minified line costs one pass.
 */
function usesNameOnlyAsReceiver(name: string, filePath: string, context: ResolutionContext): boolean {
  let memo = RECEIVER_ONLY_NAMES.get(context);
  if (!memo) RECEIVER_ONLY_NAMES.set(context, (memo = new Map()));
  const key = `${filePath}\0${name}`;
  const known = memo.get(key);
  if (known !== undefined) return known;
  const code = blankStringContents(stripCommentsForRegex(context.readFile(filePath) ?? '', 'typescript'));
  let only = true;
  for (let at = code.indexOf(name); at !== -1 && only; at = code.indexOf(name, at + 1)) {
    const end = at + name.length;
    if ((at > 0 && /[\w$.#]/.test(code[at - 1]!)) || /[\w$]/.test(code[end] ?? '')) continue;
    let next = end;
    while (next < code.length && /\s/.test(code[next]!)) next++;
    const receiver = (code[next] === '.' && code[next + 1] !== '.') || code[next] === '[' ||
      (code[next] === '?' && code[next + 1] === '.');
    if (!receiver && !/\btypeof\s+$/.test(code.slice(Math.max(0, at - 16), at))) only = false;
  }
  memo.set(key, only);
  return only;
}

/** Whether `head`, the code before a call's `.`, ends with a JS `self` that names the global object. */
function isJsGlobalSelf(head: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return /(?:^|[^\w$.])self$/.test(head) && isBrowserHostGlobal('self', ref, context);
}

/**
 * Whether a Python call recorded by its bare name was written on the instance,
 * `self.get_ip(request)`. The extractor drops the `self.`, so a same-named name
 * the file imports would otherwise claim the method call (#2074 follow-up).
 */
export function isPythonSelfCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  return ref.language === 'python' && bareCallReceiver(ref, context)?.receiver === 'self';
}

/** Whether a call recorded by its bare name is written on something other than the caller's own object. */
function isCollapsedNonRecursion(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const written = bareCallReceiver(ref, context);
  if (!written || written.receiver === 'self') return false;
  return !(JS_FAMILY.has(ref.language) && isCollapsedSelfRecursion({ root: 'this', links: written.links }, ref, context));
}

function isCollapsedSelfRecursion(chain: { root: string; links: string[] }, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (chain.root !== 'this' || chain.links.length !== 1 || chain.links[0]!.includes('(')) return false;
  const field = chain.links[0]!.replace(/^#/, '');
  const caller = context.getNodeById?.(ref.fromNodeId);
  const cut = caller ? caller.qualifiedName.lastIndexOf('::') : -1;
  if (!caller || cut <= 0) return false;
  const owner = caller.qualifiedName.slice(0, cut).split('::').pop()!;
  const cls = context.getNodesInFile(ref.filePath).find((n) =>
    n.kind === 'class' && n.name === owner && n.startLine <= ref.line && n.endLine >= ref.line);
  if (!cls) return false;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  const body = lines.slice(cls.startLine - 1, cls.endLine).join('\n');
  const f = escapeRegExp(field);
  const declared = new RegExp(`(?:^|[\\s(,])#?${f}\\s*[?!]?\\s*:\\s*([A-Za-z_$][\\w$]*)`, 'm').exec(body)?.[1] ??
    new RegExp(`\\bthis\\.${f}\\s*=\\s*new\\s+([A-Za-z_$][\\w$]*)`).exec(body)?.[1];
  return declared === owner;
}

function isBareJsCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  return JS_FAMILY.has(ref.language) && isReceiverLessCall(ref, context);
}

/**
 * Whether a Go `calls` ref is receiver-less — `relogin(ctx)`, not
 * `l.relogin(ctx)`. A Go method is only reachable through a value or a method
 * expression, so a bare call (a func parameter, a local func value, a
 * package-level function) is never a method, in its own package or in one the
 * file does not import (#1857). Read from the source line like the JS/TS
 * check, because `pkg.Factory().Method()` reaches the resolver as a bare
 * `Method` ref too.
 */
function isBareGoCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  return ref.language === 'go' && isReceiverLessCall(ref, context);
}

/**
 * Whether a Go reference's name is written bare, so that Go reads it from the
 * reference's own package: a type `Node` (variadic `...Node` too), a composite
 * literal `&Event{}`, a route's handler `Index`, a call `Walk(v, n)` or a
 * conversion `(*Block)(pb)`. Not `parser.Node` or `...chunks.Meta`, written
 * through an import, nor a name reached through a value: `err[i].Error()`, a
 * `.String()` chained onto the line above, a route's handler `h.Follow`.
 */
export function isGoBareName(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const name = ref.referenceName;
  if (ref.language !== 'go' || !/^[A-Za-z_]\w*$/.test(name)) return false;
  if (ref.referenceKind === 'calls' && isReceiverLessCall(ref, context)) return true;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1]
    ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1];
  if (line === undefined) return false;
  // A call's column is its expression's: only a conversion's parenthesized
  // type is still bare there.
  if (ref.referenceKind === 'calls') {
    return line[ref.column] === '(' && new RegExp(`^\\(\\s*\\*?\\s*${name}\\s*\\)\\s*\\(`).test(line.slice(ref.column));
  }
  if (line.startsWith(name, ref.column)) {
    let end = ref.column;
    while (end > 0 && WHITESPACE.test(line[end - 1]!)) end--;
    return line[end - 1] !== '.' || (end >= 3 && line.slice(end - 3, end) === '...');
  }
  // A route's handler is recorded at the start of its line: its spelling
  // there, outside the path string.
  const code = line.replace(/"(?:[^"\\]|\\.)*"|`[^`]*`/g, (s) => ' '.repeat(s.length));
  return new RegExp(`(?<![\\w.])${name}\\b`).test(code);
}

/**
 * Whether an R call is a plain function call — `range(x)`, `vars(a)` — not a
 * ggproto / R6 method through `obj$m(…)` or `self$m(…)`. A method is only
 * reached through its object: ggplot2's `range(data$x)` (base R's) went to a
 * Coord's `range` method.
 */
function isBareRCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'r' || ref.referenceKind !== 'calls' || !/^[A-Za-z_.][\w.]*$/.test(ref.referenceName)) return false;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (!line) return false;
  const m = new RegExp(`(?<![\\w.])${ref.referenceName.replace(/\./g, '\\.')}\\s*\\(`).exec(line);
  return !!m && !/(?:\$|@|::)\s*$/.test(line.slice(0, m.index));
}

/**
 * Whether a PHP `calls` ref is a bare function call — `redirect($url)`,
 * `view('books.show')` — rather than `$this->redirect()` / `$obj->view()` /
 * `Foo::view()`. PHP has no implicit `$this`: a call written without a
 * receiver can only be a function, so a method, field or property that shares
 * the name is never what it calls. Name-matching used to bind BookStack's
 * every `return redirect(…)` to ApiDocsController::redirect and every
 * `return view(…)` to a `$view` field.
 *
 * PHP refs record the column of the call EXPRESSION — `$this->setPageTitle(`
 * sits at `$this` — so a bare call is the one whose text at its column is the
 * name itself (a leading `\` for a fully qualified function is allowed).
 */
function isBarePhpCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'php' || ref.referenceKind !== 'calls') return false;
  if (!/^\w+$/.test(ref.referenceName)) return false;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1]
    ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return false;
  const at = line[ref.column] === '\\' ? ref.column + 1 : ref.column;
  if (!line.startsWith(ref.referenceName, at)) return false;
  CALL_OPENER.lastIndex = at + ref.referenceName.length;
  if (!CALL_OPENER.test(line)) return false;
  let end = at;
  while (end > 0 && WHITESPACE.test(line[end - 1]!)) end--;
  // `$obj->name(` / `Foo::name(` / `$obj?->name(`, should a column ever land on
  // the name — but not `'size' => filesize($zip)` or `$x ? a : name()`.
  return !(end > 1 && ((line[end - 1] === '>' && line[end - 2] === '-') || (line[end - 1] === ':' && line[end - 2] === ':')));
}

function isReceiverLessCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.referenceKind !== 'calls') return false;
  if (ref.referenceName.includes('.')) return false;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1]
    ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return false;
  // `^<name>\s*[(<]` at the call's column (or a JS/TS wrapper's tail after the
  // name), without compiling a pattern per call.
  if (!line.startsWith(ref.referenceName, ref.column)) return false;
  CALL_OPENER.lastIndex = ref.column + ref.referenceName.length;
  JS_PEELED_CALLEE_TAIL.lastIndex = CALL_OPENER.lastIndex;
  if (!CALL_OPENER.test(line) && !(JS_FAMILY.has(ref.language) && JS_PEELED_CALLEE_TAIL.test(line))) return false;
  // Nothing but whitespace, an operator or an opener may precede a bare call:
  // read the text before the column backwards, past trailing whitespace,
  // instead of end-anchoring a pattern that scans the prefix from its start.
  let end = Math.min(ref.column, line.length);
  while (end > 0 && WHITESPACE.test(line[end - 1]!)) end--;
  if (end === 0 || !RECEIVER_TAIL_CHAR.test(line[end - 1]!)) return true;
  // In JS/TS a receiver ends in `.` or `?.`, so a `)` right before the name
  // closes a statement header — `if (open) setOpen()`, `for (…) f()`, a header
  // that wraps lines or holds a `)` in a string — and the call is bare (#2585).
  if (line[end - 1] === ')' && JS_FAMILY.has(ref.language)) return true;
  let start = end;
  while (start > 0 && WORD_CHAR.test(line[start - 1]!)) start--;
  return BARE_CALL_KEYWORDS.has(line.slice(start, end));
}

/** `\s*[(<]` from a given index (sticky) — an optional call's `?.(` too. */
const CALL_OPENER = /\s*(?:\?\.\s*)?[(<]/y;
/**
 * What follows a JS/TS callee's name inside a wrapper the extractor sees
 * through — `fn!()`, `(fn)()`, `(fn as F)()`, `(fn satisfies F)()` — whose
 * reference sits at the name, as a plain call's does (sticky).
 */
const JS_PEELED_CALLEE_TAIL = /\s*[!)]|\s+(?:as|satisfies)(?![\w$])/y;
const WHITESPACE = /\s/;
const WORD_CHAR = /\w/;
/** A character that ends a receiver: `.`, a word character, `$`, `]` or `)`. */
const RECEIVER_TAIL_CHAR = /[.\w$\])]/;
/**
 * Keywords after which a name starts an expression, so the call has no
 * receiver — Go's `if Type(b) != Series`, `switch dirType(name)` included.
 */
const BARE_CALL_KEYWORDS: ReadonlySet<string> = new Set([
  'return', 'await', 'yield', 'typeof', 'void', 'new', 'else', 'case', 'throw', 'in', 'of', 'instanceof', 'go', 'defer',
  'if', 'switch', 'for', 'range', 'do',
]);

/**
 * A C# / VB.NET reference whose site is a TYPE position: `Type sourceType`,
 * `List<int>`, `new TypeMap()`, `Exception? e`, `Dictionary<string, Type>`,
 * VB's `As Type` / `New List(Of T)`. Read from the source at the reference's
 * column; anything else — a member read (`Builder.Services`), a method group
 * (`MapGet("/x", GetItems)`), a route's handler — keeps every candidate.
 */
function isDotNetTypeRef(ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'csharp' && ref.language !== 'vbnet') return false;
  if (ref.referenceKind !== 'references' && ref.referenceKind !== 'instantiates' &&
    ref.referenceKind !== 'type_of' && ref.referenceKind !== 'returns') return false;
  const name = ref.referenceName;
  if (!/^[A-Za-z_]\w*$/.test(name)) return false;
  // `new TypeMap()` constructs a type; the reference's column is the `new`.
  if (ref.referenceKind === 'instantiates') return true;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1]
    ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined || !line.startsWith(name, ref.column)) return false;
  const before = line.slice(0, ref.column);
  const after = line.slice(ref.column + name.length);
  if (ref.language === 'vbnet') return /\b(?:As|New|Of)\s+$/i.test(before);
  if (/\bnew\s+$/.test(before)) return true;
  // `Type name` — a declaration names its type first.
  if (/^\s+@?[A-Za-z_]/.test(after)) return !/^\s+(?:is|as|and|or|not|when|in|switch|with)\b/.test(after);
  // `List<int>`, `Type?`, `Type[]`, and the arguments of a generic.
  if (/^<|^\?(?![.?\[])|^\[\s*[,\]]/.test(after)) return true;
  return /^\s*[,>]/.test(after) && /<[^<>()]*$/.test(before);
}

/**
 * Whether a candidate can be what a .NET type position names. A property, a
 * method (a constructor is one) or an enum case shares the type's name, not
 * its meaning: AutoMapper's `Type sourceType` bound to an attribute's `Type`
 * property and `TypeMap typeMap` to a `TypeMap` property beside the `TypeMap`
 * class. A field never names a type either, nor does a constant — the kind a
 * C# `const` / `static readonly` field gets: jellyfin's `new Version(5, 18)`
 * bound to a claim-name `const string Version`, and serilog's `static
 * readonly Meter Meter = new(…)` to itself.
 */
function canNameInTypePosition(n: Node): boolean {
  return !(n.kind === 'property' || n.kind === 'method' || n.kind === 'enum_member' || n.kind === 'field' ||
    n.kind === 'constant');
}

/**
 * The shape of a Python call that reaches the resolver as a bare name — the
 * column is the call's start. `bare`: `get(1)`, which cannot mean a method
 * (Python has no implicit self). `chained`: a receiver the extractor could not
 * keep — `User.objects.get(…)`, `self.client.login(…)`, `request.POST.get(…)`
 * arrive as `get` / `login`, and can only mean a member of what the chain
 * names last (`POST`, `client`, `objects`). netbox bound 3,610 `.all()` calls
 * to one `UserConfig.all`, healthchecks 880 `objects.get` to a test case's
 * `get`. `self.x()` / `cls.x()`, and a chain split across lines, are null:
 * today's behavior.
 */
type PythonCallShape = { kind: 'bare' } | { kind: 'chained'; owner: string };

function pythonCallShape(ref: UnresolvedRef, context: ResolutionContext): PythonCallShape | null {
  if (ref.language !== 'python' || ref.referenceKind !== 'calls') return null;
  const name = ref.referenceName;
  if (!/^[A-Za-z_]\w*$/.test(name)) return null;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return null;
  const text = line.slice(ref.column);
  if (text.startsWith(name) && /^\s*\(/.test(text.slice(name.length))) return { kind: 'bare' };
  if (new RegExp(String.raw`^(?:self|cls)\s*\.\s*${name}\s*\(`).test(text)) return null;
  // The call starts at its receiver, so everything up to `.name(` is the receiver chain.
  const chain = new RegExp(String.raw`^(.*?)\.\s*${name}\s*\(`).exec(text);
  if (!chain) return null;
  const owner = /(\w+)\s*(?:\([^()]*\)|\[[^\[\]]*\])?\s*$/.exec(chain[1]!)?.[1];
  return owner ? { kind: 'chained', owner } : null;
}

/** Can a Python call of this shape mean the candidate? */
function fitsPythonCallShape(n: Node, shape: PythonCallShape, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (shape.kind === 'bare') {
    if (n.kind === 'method') return false;
    if (n.filePath === ref.filePath) return true;
    // `from django.shortcuts import render`: the call is the package's.
    if (isPythonNameImportedFromOutside(ref.referenceName, ref, context)) return false;
    // `view = UserView.as_view()` … `view(request)`: the file's own value —
    // unless it is a pytest fixture, which a test takes as a parameter of that name.
    return isFixtureInReach(n, ref.filePath, context) || !isPythonLocallyBound(ref.referenceName, ref, context);
  }
  // A member of what the chain names: a method of a class of that name, or a
  // function / class in a module of that name (`helpers.slugify()`).
  if (n.kind === 'method') {
    // `self.store.fetch()` on a `Store`, `self.user_service.find()` on a `UserService`.
    const cut = n.qualifiedName.lastIndexOf('::');
    const owner = cut >= 0 ? n.qualifiedName.slice(0, cut).split('::').pop()! : '';
    const plain = (s: string): string => s.replace(/_/g, '').toLowerCase();
    return owner !== '' && plain(owner) === plain(shape.owner);
  }
  const parts = n.filePath.split('/');
  const stem = parts[parts.length - 1]!.replace(/\.pyi?$/, '');
  return stem === shape.owner || (stem === '__init__' && parts[parts.length - 2] === shape.owner);
}

/**
 * A pytest fixture: `@pytest.fixture` / `@fixture`, or anything a `conftest.py`
 * defines. Python decorators are not kept on the node, so they are read from
 * the lines above its `def` (a decorator's arguments may span lines).
 */
function isPytestFixture(n: Node, context: ResolutionContext): boolean {
  if (/(?:^|\/)conftest\.py$/.test(n.filePath) || (n.decorators ?? []).some((d) => /(?:^|\.)fixture\b/.test(d))) return true;
  return isDecoratedFixture(n, context);
}

/**
 * A fixture a test at `filePath` can take by name: one its own module defines,
 * or one a `conftest.py` of its directory or a parent does. A test module's
 * fixture is that module's alone — pytest's `_run_both(func)` is handing on its
 * parameter, not a doc example's `func` fixture.
 */
function isFixtureInReach(n: Node, filePath: string, context: ResolutionContext): boolean {
  if (n.filePath === filePath) return isPytestFixture(n, context);
  const conftest = /^(.*?)(?:^|\/)conftest\.py$/.exec(n.filePath);
  if (conftest !== null) return conftest[1] === '' || filePath.startsWith(`${conftest[1]}/`);
  // A fixture module a `conftest.py` above the test pulls in — `from
  // tests.fixtures.cli import *`, or `pytest_plugins = ["tests.fixtures.cli"]`.
  if (!isPytestFixture(n, context)) return false;
  return pluggedFixtureModules(filePath, context).some((m) => n.filePath === m || n.filePath.endsWith(`/${m}`));
}

const PY_PLUGGED_MODULES = new WeakMap<ResolutionContext, Map<string, string[]>>();

/** The module files (`tests/fixtures/cli.py`) the `conftest.py` files above `filePath` star-import or list in `pytest_plugins`. */
function pluggedFixtureModules(filePath: string, context: ResolutionContext): string[] {
  let memo = PY_PLUGGED_MODULES.get(context);
  if (!memo) PY_PLUGGED_MODULES.set(context, (memo = new Map()));
  const dir = filePath.includes('/') ? filePath.slice(0, filePath.lastIndexOf('/')) : '';
  const hit = memo.get(dir);
  if (hit) return hit;
  const modules: string[] = [];
  for (let d = dir; ; d = d.includes('/') ? d.slice(0, d.lastIndexOf('/')) : '') {
    const text = context.readFile(d ? `${d}/conftest.py` : 'conftest.py');
    if (text) {
      for (const m of text.matchAll(/^\s*from\s+([\w.]+)\s+import\s+\*/gm)) modules.push(`${m[1]!.replace(/\./g, '/')}.py`);
      const plugins = /^\s*pytest_plugins\s*=\s*[[(]([^\])]*)[\])]/m.exec(text)?.[1] ?? '';
      for (const m of plugins.matchAll(/["']([\w.]+)["']/g)) modules.push(`${m[1]!.replace(/\./g, '/')}.py`);
    }
    if (!d) break;
  }
  memo.set(dir, modules);
  return modules;
}

const PY_FIXTURE_TYPES = new WeakMap<ResolutionContext, Map<string, string | null>>();

/**
 * The class a pytest fixture returns, for a test parameter of its name — the
 * fixture in reach (the test's module, else the nearest `conftest.py` above
 * it) whose body returns or yields `Cls(…)`, directly or through a local
 * assigned `Cls(…)`. Null for anything else (a parameter that is no fixture's,
 * a fixture returning a call of a function).
 */
function pythonFixtureReturnType(receiver: string, ref: UnresolvedRef, context: ResolutionContext): string | null {
  if (!/^[a-z_]\w*$/.test(receiver) || receiver === 'self' || receiver === 'cls') return null;
  let memo = PY_FIXTURE_TYPES.get(context);
  if (!memo) PY_FIXTURE_TYPES.set(context, (memo = new Map()));
  const key = `${ref.fromNodeId}\0${receiver}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  let type: string | null = null;
  const caller = context.getNodeById?.(ref.fromNodeId);
  const lines = caller ? context.getFileLines?.(caller.filePath) ?? context.readFile(caller.filePath)?.split(/\r?\n/) ?? [] : [];
  // The receiver must be the test's own parameter.
  const signature = caller && (caller.kind === 'function' || caller.kind === 'method')
    ? lines.slice(caller.startLine - 1, caller.startLine + 4).join(' ').split(/\)\s*(?:->[^:]*)?:/)[0] ?? '' : '';
  if (new RegExp(`[(,]\\s*${escapeRegExp(receiver)}\\s*(?:[:=,)]|$)`).test(signature)) {
    const fixtures = context.getNodesByName(receiver)
      .filter((n) => n.kind === 'function' && n.language === 'python' && isFixtureInReach(n, ref.filePath, context))
      .sort((a, b) => (a.filePath === ref.filePath ? -1 : 0) - (b.filePath === ref.filePath ? -1 : 0) || b.filePath.length - a.filePath.length);
    const fixture = fixtures[0];
    if (fixture) {
      const body = (context.getFileLines?.(fixture.filePath) ?? context.readFile(fixture.filePath)?.split(/\r?\n/) ?? [])
        .slice(fixture.startLine, fixture.endLine).join('\n');
      const returned = /^\s*(?:return|yield)\s+([A-Za-z_][\w.]*)\s*(\()?/m.exec(body);
      if (returned) {
        const direct = returned[2] ? returned[1]! : new RegExp(`^\\s*${returned[1]!.replace(/\./g, '\\.')}\\s*=\\s*([A-Za-z_][\\w.]*)\\s*\\(`, 'm').exec(body)?.[1];
        const cls = direct?.split('.').pop();
        if (cls && /^[A-Z]/.test(cls)) type = cls;
      }
    }
  }
  memo.set(key, type);
  return type;
}

function isDecoratedFixture(n: Node, context: ResolutionContext): boolean {
  if (n.language !== 'python' || n.kind !== 'function') return false;
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  // Upward through the decorator lines: each one starts with `@`, or sits inside one's parentheses.
  let open = 0;
  for (let i = n.startLine - 2; i >= 0 && i >= n.startLine - 16; i--) {
    const text = lines[i]?.trim() ?? '';
    open += (text.match(/\)/g)?.length ?? 0) - (text.match(/\(/g)?.length ?? 0);
    if (open > 0) continue;
    if (!text.startsWith('@')) return false;
    if (/^@(?:\w+\.)*fixture\b/.test(text)) return true;
  }
  return false;
}

const PY_LOCAL_BINDS = new WeakMap<ResolutionContext, Map<string, boolean>>();
/**
 * The file isPythonLocallyBound last read: its code lines, and per name
 * whether its module binds it. Refs arrive grouped by file, so one file per
 * context spares re-stripping the file for every function and name (#2332).
 */
const PY_LOCAL_FILE = new WeakMap<ResolutionContext, { filePath: string; lines: string[]; module: Map<string, boolean> }>();
/** The ref isPythonLocallyBound last answered, and the answer. */
const PY_LOCAL_LAST = new WeakMap<ResolutionContext, { ref: UnresolvedRef; name: string; bound: boolean }>();

/**
 * Whether the function around a Python call — or its module, at top level —
 * binds `name` itself: an assignment (`view = X.as_view()`, `a, view = …`,
 * `view: T = …`), a parameter, a `for` / `with … as` / `except … as` target.
 * DRF's tests write `view = SomeView.as_view()` then `view(request)`, and
 * every such call went to one test file's `def view`.
 */
function isPythonLocallyBound(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  // fitsPythonCallShape asks once per same-named candidate, and finding the
  // function around the call reads every node in the file: answer a ref once (#2332).
  const last = PY_LOCAL_LAST.get(context);
  if (last?.ref === ref && last.name === name) return last.bound;
  const bound = pythonLocalBinding(name, ref, context);
  PY_LOCAL_LAST.set(context, { ref, name, bound });
  return bound;
}

/** isPythonLocallyBound's answer, kept per calling function and name. */
function pythonLocalBinding(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const fn = context.getNodesInFile(ref.filePath)
    .filter((f) => (f.kind === 'function' || f.kind === 'method') && f.startLine <= ref.line && f.endLine >= ref.line)
    .sort((a, b) => (a.endLine - a.startLine) - (b.endLine - b.startLine))[0];
  let memo = PY_LOCAL_BINDS.get(context);
  if (!memo) PY_LOCAL_BINDS.set(context, (memo = new Map()));
  const key = `${ref.filePath}\0${fn?.id ?? ''}\0${name}\0${fn ? '' : ref.line}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  // An imported name is the import's (the import resolver's to follow).
  if (pythonFromImports(ref.filePath, context).has(name)) {
    memo.set(key, false);
    return false;
  }
  // Code only: `{% user_display user as user_display %}` in a docstring binds nothing.
  let file = PY_LOCAL_FILE.get(context);
  if (file?.filePath !== ref.filePath) {
    const lines = stripCommentsForRegex(context.readFile(ref.filePath) ?? '', 'python').split(/\r?\n/);
    PY_LOCAL_FILE.set(context, (file = { filePath: ref.filePath, lines, module: new Map() }));
  }
  const lines = file.lines;
  const n = escapeRegExp(name);
  const assigns = new RegExp(`^\\s*(?:[\\w\\s,*()\\[\\]]*,\\s*)?\\(?\\*?${n}\\)?\\s*(?:,[\\w\\s,*()\\[\\]]*)?(?::[^=]+)?=(?!=)`);
  const targets = new RegExp(`\\bfor\\s+[\\w\\s,()]*\\b${n}\\b[\\w\\s,()]*\\s+in\\b|\\bas\\s+${n}\\b`);
  const params = new RegExp(`[(,]\\s*\\*{0,2}${n}\\s*(?:[:=,)]|$)`);
  let bound = false;
  if (fn) {
    // The signature up to its `:` (it may span lines), then the body above the call.
    let i = fn.startLine - 1;
    let signature = '';
    for (; i < Math.min(lines.length, fn.startLine + 20); i++) {
      signature += lines[i] ?? '';
      if (/\)\s*(?:->[^:]*)?:\s*(?:#.*)?$/.test(lines[i] ?? '')) break;
    }
    bound = params.test(signature.replace(/^[^(]*/, ''));
    for (let line = i + 1; !bound && line < ref.line - 1; line++) {
      const text = lines[line] ?? '';
      bound = assigns.test(text) || targets.test(text);
    }
  }
  // A module-level binding (`view = api_view(['GET'])(handler)`).
  if (!bound) {
    let module = file.module.get(n);
    if (module === undefined) {
      const top = new RegExp(`^(?:[\\w,\\s]*,\\s*)?${n}\\s*(?:,[\\w\\s,]*)?(?::[^=]+)?=(?!=)`);
      module = lines.some(line => top.test(line));
      file.module.set(n, module);
    }
    bound = module;
  }
  memo.set(key, bound);
  return bound;
}

const PY_IMPORTS = new WeakMap<ResolutionContext, Map<string, Map<string, string>>>();
const PY_MODULE_LOCAL = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** `name` → the module a `from <module> import name` line takes it from, per file. */
function pythonFromImports(filePath: string, context: ResolutionContext): Map<string, string> {
  let memo = PY_IMPORTS.get(context);
  if (!memo) {
    memo = new Map();
    PY_IMPORTS.set(context, memo);
  }
  const hit = memo.get(filePath);
  if (hit) return hit;
  const names = new Map<string, string>();
  const text = context.readFile(filePath) ?? '';
  for (const m of text.matchAll(/^\s*from\s+([\w.]+)\s+import\s+(\([^)]*\)|[^\n#]+)/gm)) {
    const module = m[1]!;
    for (const item of m[2]!.replace(/[()]/g, '').split(',')) {
      const bound = /(\w+)\s*$/.exec(item.trim())?.[1];
      if (bound && bound !== '*') names.set(bound, module);
    }
  }
  memo.set(filePath, names);
  return names;
}

function isPythonNameImportedFromOutside(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const module = pythonFromImports(ref.filePath, context).get(name);
  if (!module || module.startsWith('.')) return false;
  return !isPythonProjectModule(module, ref.filePath, context);
}

/** Whether some project file is the module `a.b` as `fromFile` imports it (`a/b.py` or `a/b/__init__.py`). */
function isPythonProjectModule(module: string, fromFile: string, context: ResolutionContext): boolean {
  let memo = PY_MODULE_LOCAL.get(context);
  if (!memo) {
    memo = new Map();
    PY_MODULE_LOCAL.set(context, memo);
  }
  // The import resolver decides where a module lives (package roots), and the
  // answer can depend on the importer (a monorepo service's own root), so key
  // by both. A file that merely ENDS in `requests/__init__.py` — a copy nested
  // in a test fixture — is not the `requests` an import names.
  const key = `${fromFile}\0${module}`;
  let local = memo.get(key);
  if (local === undefined) {
    if (context.resolveModuleFile) {
      local = context.resolveModuleFile(module, fromFile, 'python') !== null;
    } else {
      const rel = module.replace(/\./g, '/');
      local = context.getAllFiles().some((f) =>
        f === `${rel}.py` || f.endsWith(`/${rel}.py`) || f === `${rel}/__init__.py` || f.endsWith(`/${rel}/__init__.py`));
    }
    memo.set(key, local);
  }
  return local;
}

/**
 * A receiver the file binds only by importing a module from outside the
 * project — `import subprocess`, `import numpy as np` — never rebinding it at
 * module scope (an assignment, a `for`/`with`/tuple target, a `global` write
 * in a function, a fallback `class`/`def` of that name) nor in the calling
 * function. A call on it is that module's function, never a project class's
 * method of the same name (#2599).
 */
export function isPythonOutsideModuleReceiver(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (ref.language !== 'python') return false;
  return isPythonOutsideModuleName(name, ref.filePath, context) && !pythonBindsLocally(name, ref, context, false);
}

/**
 * The module-scope half of isPythonOutsideModuleReceiver: `filePath` binds
 * `name` only by importing it from outside the project, and never rebinds it
 * at module scope.
 */
function isPythonOutsideModuleName(name: string, filePath: string, context: ResolutionContext): boolean {
  if (!/^\w+$/.test(name)) return false;
  return pythonNameScan(context, `outside\0${filePath}\0${name}`, () => {
    const keys = pythonImportKeys(name, filePath, context);
    if (keys.size === 0) return false;
    if (pythonGlobalBindings(name, filePath, context).some((b) => b.kind !== 'import')) return false;
    if (context.getNodesInFile(filePath).some((n) => n.name === name && (n.kind === 'class' || n.kind === 'function'))) return false;
    // `import a.b as x` keys as `a.b:*`; `from a import x` as `a:x`, where only
    // the module `a` tells that `x` comes from outside.
    return [...keys].every((key) => {
      const module = key.slice(0, key.indexOf(':'));
      return !module.startsWith('.') && !isPythonProjectModuleAnyRoot(module, filePath, context);
    });
  });
}

/**
 * Whether `a.b.c` is a project module from some import root: `a/b/c.py`, or —
 * with the package itself indexed as the root — `b/c.py` or `c.py`. Erring
 * toward "project" only leaves a call to the name strategies, as before.
 */
function isPythonProjectModuleAnyRoot(module: string, fromFile: string, context: ResolutionContext): boolean {
  const parts = module.split('.');
  return parts.some((_, i) => isPythonProjectModule(parts.slice(i).join('.'), fromFile, context));
}

const JAVA_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'interface', 'enum', 'struct', 'record', 'trait']);
const JAVA_SUPERS = new WeakMap<ResolutionContext, Map<string, string[]>>();
const JAVA_STATIC_IMPORTS = new WeakMap<ResolutionContext, Map<string, { owners: Set<string>; members: Set<string> }>>();

/**
 * A bare Java call — `verify(mock)`, `helper()`, `this.x()`, `super.x()` —
 * reaches a method of a class around it, of one of that class's supertypes, or
 * one the file imports statically. Not some other class's method of that name:
 * halo's tests' Mockito `verify(…)` and `eq(…)` bound 1,038 calls to an
 * `EmailVerificationService.verify` and 845 to a builder's `eq`. Supertypes are
 * read from the declarations — the resolved `extends` edges do not exist yet on
 * the first pass.
 */
function isJavaMethodInScope(method: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut < 0) return true;
  const owner = method.qualifiedName.slice(0, cut).split('::').pop()!;
  const imports = javaStaticImportsOf(ref.filePath, context);
  if (imports.owners.has(owner) || imports.members.has(`${owner}.${ref.referenceName}`)) return true;
  const around = context
    .getNodesInFile(ref.filePath)
    .filter((n) => JAVA_TYPE_KINDS.has(n.kind) && n.startLine <= ref.line && n.endLine >= ref.line);
  const seen = new Set<string>();
  const queue = around.map((n) => n.name);
  while (queue.length > 0 && seen.size < 40) {
    const name = queue.shift()!;
    if (seen.has(name)) continue;
    seen.add(name);
    if (name === owner) return true;
    queue.push(...javaSupertypesOf(name, context));
  }
  return false;
}

/** The simple names a Java type's declarations extend or implement. */
function javaSupertypesOf(typeName: string, context: ResolutionContext): string[] {
  let memo = JAVA_SUPERS.get(context);
  if (!memo) {
    memo = new Map();
    JAVA_SUPERS.set(context, memo);
  }
  const hit = memo.get(typeName);
  if (hit) return hit;
  const names: string[] = [];
  for (const decl of context.getNodesByName(typeName)) {
    if (decl.language !== 'java' || !JAVA_TYPE_KINDS.has(decl.kind)) continue;
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    const head = lines.slice(decl.startLine - 1, decl.startLine + 5).join(' ');
    const clause = /\b(?:extends|implements)\b([^{]*)\{/.exec(head)?.[1] ?? '';
    const flat = clause.replace(/<[^<>]*(?:<[^<>]*>[^<>]*)*>/g, '');
    for (const m of flat.matchAll(/([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)/g)) {
      const simple = m[1]!.split('.').pop()!;
      if (simple !== 'extends' && simple !== 'implements') names.push(simple);
    }
  }
  memo.set(typeName, names);
  return names;
}

/** A Java file's `import static a.b.Owner.member;` / `import static a.b.Owner.*;`. */
function javaStaticImportsOf(filePath: string, context: ResolutionContext): { owners: Set<string>; members: Set<string> } {
  let memo = JAVA_STATIC_IMPORTS.get(context);
  if (!memo) {
    memo = new Map();
    JAVA_STATIC_IMPORTS.set(context, memo);
  }
  const hit = memo.get(filePath);
  if (hit) return hit;
  const found = { owners: new Set<string>(), members: new Set<string>() };
  const text = context.readFile(filePath) ?? '';
  for (const m of text.matchAll(/^\s*import\s+static\s+([\w.$]+)\s*\.\s*(\*|[\w$]+)\s*;/gm)) {
    const owner = m[1]!.split('.').pop()!;
    if (m[2] === '*') found.owners.add(owner);
    else found.members.add(`${owner}.${m[2]}`);
  }
  memo.set(filePath, found);
  return found;
}

const DART_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'interface', 'enum', 'mixin', 'extension', 'struct', 'trait']);
const DART_SUPERS = new WeakMap<ResolutionContext, Map<string, string[]>>();

/**
 * Whether a bare Dart call can reach `method`: only a method of the class it
 * is written in, or of what that class extends, mixes in or implements (an
 * extension's `on` type included). riverpod's tests' `test(…)` — package:test's
 * function — went to `ProviderContainer.test` 2,360 times; shelf's `expect(…)`
 * to a test handler's `expect` method. Outside any class (`main`), no method.
 */
function isDartMethodInScope(method: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return dartMemberDepth(method, ref, context) < Infinity;
}

const DART_CONSTRUCTORS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether a Dart method is a named constructor — `Foo.named(…)`, `factory
 * Foo.of(…)`, `const Foo.value(…)`, `const factory Foo.x() = _X;` — read from
 * its declaration. Dart reaches one only through its class (`Foo.value(…)`,
 * the tear-off `Foo.value`), never by a bare name: a parameter `value` passed
 * on is not `const BlocProvider.value(…)`.
 */
function isDartConstructor(n: Node, context: ResolutionContext): boolean {
  if (n.language !== 'dart' || n.kind !== 'method') return false;
  let memo = DART_CONSTRUCTORS.get(context);
  if (!memo) DART_CONSTRUCTORS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  const cut = n.qualifiedName.lastIndexOf('::');
  const owner = cut > 0 ? n.qualifiedName.slice(0, cut).split('::').pop()! : '';
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  const head = (lines[n.startLine - 1] ?? '').slice(n.startColumn);
  const constructor = owner !== '' &&
    new RegExp(String.raw`^(?:(?:const|factory|external)\s+)*${escapeRegExp(owner)}\s*\.\s*${escapeRegExp(n.name)}(?![\w$])`).test(head);
  memo.set(n.id, constructor);
  return constructor;
}

/**
 * How many supertype steps separate the class a Dart call is written in from
 * `method`'s owner: 0 for its own member, Infinity when the owner is not in
 * its hierarchy at all. An extension's member is in scope when the extension
 * is `on` a type of that hierarchy — a bare `requireElement()` inside a
 * notifier is `this.requireElement()`, the `on AnyNotifier` extension's — and
 * ranks after every real member, as Dart resolves it.
 */
function dartMemberDepth(method: Node, ref: UnresolvedRef, context: ResolutionContext): number {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut < 0) return 0;
  const owner = method.qualifiedName.slice(0, cut).split('::').pop()!;
  const hierarchy = dartHierarchyAt(ref, context);
  const own = hierarchy.get(owner);
  if (own !== undefined) return own;
  const decl = context
    .getNodesInFile(method.filePath)
    .find((n) => n.name === owner && DART_TYPE_KINDS.has(n.kind) && n.startLine <= method.startLine && n.endLine >= method.endLine);
  if (!decl) return Infinity;
  const head = dartHeadOf(decl, context);
  if (!head.extension) return Infinity;
  const on = Math.min(...head.supers.map((t) => hierarchy.get(t) ?? Infinity));
  return on === Infinity ? Infinity : DART_EXTENSION_RANK + on;
}

/** Past any real member's depth: an extension member only applies when no instance member does. */
const DART_EXTENSION_RANK = 1000;
/** Past any lineage's depth (at most 40): an extension on a type parameter is the least specific. */
const DART_UNIVERSAL_RANK = 100;
const DART_HIERARCHIES = new WeakMap<ResolutionContext, WeakMap<UnresolvedRef, Map<string, number>>>();

/** Every type the classes around a Dart call site are, by supertype distance (at most 40). */
function dartHierarchyAt(ref: UnresolvedRef, context: ResolutionContext): Map<string, number> {
  let memo = DART_HIERARCHIES.get(context);
  if (!memo) {
    memo = new WeakMap();
    DART_HIERARCHIES.set(context, memo);
  }
  const hit = memo.get(ref);
  if (hit) return hit;
  const depths = new Map<string, number>();
  const queue: Array<[string, number]> = context
    .getNodesInFile(ref.filePath)
    .filter((n) => DART_TYPE_KINDS.has(n.kind) && n.startLine <= ref.line && n.endLine >= ref.line)
    .map((n) => [n.name, 0]);
  while (queue.length > 0 && depths.size < 40) {
    const [name, depth] = queue.shift()!;
    if (depths.has(name)) continue;
    depths.set(name, depth);
    for (const sup of dartSupertypesOf(name, context)) queue.push([sup, depth + 1]);
  }
  memo.set(ref, depths);
  return depths;
}

/**
 * Of the in-scope members a bare Dart call could mean, the nearest: a
 * subclass's override, or the class that implements what an interface only
 * declares. bloc's `emit(…)` in a `Cubit` is `BlocBase.emit`, not the
 * `Emittable` interface's.
 */
function nearestDartMembers(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  const members = candidates.filter(isDartMember);
  if (members.length < 2) return candidates;
  const depth = new Map(members.map((n) => [n.id, dartMemberDepth(n, ref, context)]));
  const nearest = Math.min(...depth.values());
  return candidates.filter((n) => !depth.has(n.id) || depth.get(n.id) === nearest);
}

/** A member of a Dart type — a method, or an abstract member written without a body (extracted as a `function` owned by the type). */
function isDartMember(n: Node): boolean {
  return n.kind === 'method' || (n.kind === 'function' && n.qualifiedName.includes('::'));
}

/**
 * A value a Dart type holds — an enum constant, a `static const` / `final` —
 * which a bare name reaches only from inside the type, like its methods:
 * bloc's brick hook calls `info(…)` on mason's `Logger`, and the call went to
 * bloc_lint's enum constant `LinterRuleState.info`.
 */
function isDartTypeValue(n: Node): boolean {
  return n.language === 'dart' && (n.kind === 'enum_member' || VALUE_KINDS.has(n.kind)) && n.qualifiedName.includes('::');
}

/** What a Dart library declares at its top level: a function, a type, a typedef, a top-level `final` / `const`. */
const DART_LIBRARY_DECL_KINDS: ReadonlySet<string> = new Set(['function', 'class', 'enum', 'type_alias', 'constant', 'variable', 'interface', 'struct', 'trait', 'mixin', 'extension']);

function isDartLibraryDecl(n: Node): boolean {
  return n.language === 'dart' && DART_LIBRARY_DECL_KINDS.has(n.kind) && !n.qualifiedName.includes('::');
}

/**
 * Whether a Dart name written without a receiver — a call, a type — can mean
 * `candidate` when it is declared at the top level of a library: the caller's
 * own library declares it, or a library the caller imports without a prefix
 * exports it, `show` / `hide` and `export` chains followed (see
 * ./dart-libraries). A name written through an import prefix (`p.Report`)
 * means only what the imports with that prefix export. riverpod's generated
 * `async.g.dart` (`part of 'async.dart'`) calls the `family(…)` async.dart
 * declares, and the call went to annotated.dart's `family` beside it; a test's
 * `fakeAsync(…)` from package:fake_async went to a vendored copy no file imports.
 */
function isDartTopLevelVisible(candidate: Node, ref: UnresolvedRef, context: ResolutionContext, prefix: string | null = null): boolean {
  if (!isDartLibraryDecl(candidate)) return true;
  return prefix === null
    ? dartLibrarySees(ref.filePath, candidate.filePath, candidate.name, context)
    : dartPrefixSees(ref.filePath, prefix, candidate.filePath, candidate.name, context);
}

/**
 * Whether `n` is a Dart `_name` that another library declares, which nothing
 * written in the reference's library can mean (#2466). It leaves the
 * candidates before one is picked, so the library's own declaration wins
 * where another library's namesake would have ranked first and then been
 * declined: the Dart SDK's wasm `_ImmutableLinkedHashMapMixin` calls the
 * `_createIndex` of the `_MapCreateIndexMixin` it is `on`, not the one the
 * VM's mixin of the same name declares. isVisibleAcrossFiles applies the
 * same rule to the pipeline's pick.
 */
function isDartPrivateOfAnotherLibrary(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return n.language === 'dart' && n.visibility === 'private' && n.filePath !== ref.filePath &&
    !dartPrivateVisible(ref.filePath, n.filePath, context);
}

/**
 * The import prefix a Dart type name is written through — the `p` of
 * `p.Report`, `p.Color.red` — or null. A type reference's column is the
 * name's start; on a line with non-ASCII text before it the nearest whole-word
 * occurrence stands in.
 */
function dartImportPrefixOf(ref: UnresolvedRef, context: ResolutionContext): string | null {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1];
  if (line === undefined) return null;
  const name = ref.referenceName;
  const isWord = (at: number) => line.startsWith(name, at) && !/[\w$]/.test(line[at - 1] ?? '') && !/[\w$]/.test(line[at + name.length] ?? '');
  let start = isWord(ref.column) ? ref.column : -1;
  for (let at = line.indexOf(name); start < 0 && at >= 0; at = line.indexOf(name, at + 1)) {
    if (isWord(at)) start = at;
  }
  if (start < 0) return null;
  return /([A-Za-z_$][\w$]*)\s*\.\s*$/.exec(line.slice(0, start))?.[1] ?? null;
}

/**
 * A library's own top-level declaration shadows every import of its name, so
 * when the caller's library declares one, the imported namesakes are no
 * candidates. (A function nested in another body is not the library's.)
 */
function preferOwnDartLibrary(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  if (candidates.filter(isDartLibraryDecl).length < 2) return candidates;
  const own = candidates.filter((n) =>
    isDartLibraryDecl(n) && inSameDartLibrary(ref.filePath, n.filePath, context) && isLexicallyReachable(n, ref, context));
  return own.length === 0 ? candidates : candidates.filter((n) => !isDartLibraryDecl(n) || own.includes(n));
}

/**
 * A Dart call through an import prefix — `http.get(…)` after `import
 * 'package:http/http.dart' as http;`, `fmt.describe(…)`, `kit.Widget()` —
 * calls a top-level declaration a library imported with that prefix exports,
 * `export` chains and `show` / `hide` followed, or nothing of the project:
 * never a member found by its name. riverpod's docs' 25 `http.get(…)` calls
 * went to a docs example's `Http::get`, by their receiver's capitalized name.
 * Undefined when the receiver is no import prefix there, or a parameter, local
 * or member of that name hides it.
 */
function matchDartPrefixedCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const parts = DART_MEMBER_READ.exec(ref.referenceName);
  if (!parts || !dartImportPrefixes(ref.filePath, context).has(parts[1]!)) return undefined;
  const prefix = parts[1]!;
  const name = parts[2]!;
  const at = dartPrefixedCallSite(ref, prefix, name, context);
  // `const p.Box.named()` reaches here as `p.named`: no call of a top-level `named`.
  if (at < 0) return null;
  if (isDartNameHidden(prefix, ref, at, context)) return undefined;
  const found = dartPrefixedDecls(prefix, name, ref, context);
  return found.length === 1 ? { original: ref, targetNodeId: found[0]!.id, confidence: 0.9, resolvedBy: 'import' } : null;
}

/** The top-level Dart declarations named `name` that the imports written with `prefix` bring into the reference's library. */
function dartPrefixedDecls(prefix: string, name: string, ref: UnresolvedRef, context: ResolutionContext): Node[] {
  return context.getNodesByName(name).filter((n) => isDartLibraryDecl(n) && dartPrefixSees(ref.filePath, prefix, n.filePath, name, context));
}

/**
 * Where `prefix` starts in the code of a Dart call written `prefix.name(…)`,
 * or -1 when the call is written otherwise: `const p.Box.named()` arrives as
 * `p.named`. (The reference's column sits just past `name`.)
 */
function dartPrefixedCallSite(ref: UnresolvedRef, prefix: string, name: string, context: ResolutionContext): number {
  const code = dartCodeOf(ref.filePath, context);
  const start = code ? dartNameStart({ ...ref, referenceName: name }, code) : -1;
  if (!code || start < 0) return -1;
  const text = code.text;
  let k = start - 1;
  while (k >= 0 && /\s/.test(text[k]!)) k--;
  if (text[k] !== '.' || text[k - 1] === '.' || text[k - 1] === '?') return -1;
  k--;
  while (k >= 0 && /\s/.test(text[k]!)) k--;
  const end = k + 1;
  while (k >= 0 && /[\w$]/.test(text[k]!)) k--;
  if (text.slice(k + 1, end) !== prefix) return -1;
  while (k >= 0 && /\s/.test(text[k]!)) k--;
  return text[k] === '.' ? -1 : end - prefix.length;
}

/**
 * Whether a parameter or local around offset `at`, or a member of the type the
 * reference is written in, is named `name`: it hides a library-level name
 * there — an import prefix among them — as Dart's scopes nest.
 */
function isDartNameHidden(name: string, ref: UnresolvedRef, at: number, context: ResolutionContext): boolean {
  if (isDartLocallyBound(ref.filePath, name, at, context)) return true;
  const own = dartEnclosingType(ref, context);
  return own !== null && (classMemberType(own, name, context) !== null ||
    context.getNodesByName(name).some((n) => n.filePath === own.filePath && n.qualifiedName === `${own.qualifiedName}::${name}`));
}

/**
 * The import prefix a Dart call through a type is written with — the `p` of
 * `p.Box<int>.named(…)`, which arrives as `Box.named` with its column on the
 * prefix — or null.
 */
function dartTypeCallPrefix(typeName: string, member: string, ref: UnresolvedRef, context: ResolutionContext): string | null {
  const prefixes = dartImportPrefixes(ref.filePath, context);
  if (prefixes.size === 0) return null;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split(/\r?\n/)[ref.line - 1];
  if (line === undefined) return null;
  const written = new RegExp(String.raw`(?<![\w$.])([A-Za-z_$][\w$]*)\s*\.\s*${escapeRegExp(typeName)}\s*` +
    String.raw`(?:<(?:[^<>]|<(?:[^<>]|<[^<>]*>)*>)*>)?\s*\.\s*${escapeRegExp(member)}(?![\w$])`, 'g');
  // The one at the reference's column, else the first: a column counted in bytes misses after non-ASCII text.
  const found = [...line.matchAll(written)].filter((m) => prefixes.has(m[1]!));
  return (found.find((m) => m.index === ref.column) ?? found[0])?.[1] ?? null;
}

/**
 * Whether a bare Dart reference really is receiver-less at its call site. The
 * extractor keeps one receiver level, so the later links of a chain —
 * `LoginState().withEmail(e).withPassword(p)` — arrive as bare names; their
 * line shows `.withPassword(` all the same. (A Dart ref's column sits just
 * past the name; the name's start is found either way.) A spread's
 * `...items()` is no receiver.
 */
function isReceiverLessDartCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return true;
  const name = ref.referenceName;
  let start = -1;
  if (line.startsWith(name, ref.column)) start = ref.column;
  else if (ref.column >= name.length && line.startsWith(name, ref.column - name.length)) start = ref.column - name.length;
  else start = line.indexOf(name);
  if (start < 0) return true;
  const before = line.slice(0, start);
  return !/\.\s*$/.test(before) || /(?:^|[^.])\.\.\.\s*$/.test(before);
}

/**
 * A later link of a Dart call chain — `Provider.autoDispose.family<…>(…)`,
 * `events.map(mapper).transform(…)`, `const LoginState().withEmail(e)` — which
 * the extractor records by its bare name, its receiver dropped.
 */
export function isDartChainLink(ref: UnresolvedRef, context: ResolutionContext): boolean {
  return ref.language === 'dart' && ref.referenceKind === 'calls' && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName) &&
    !isReceiverLessDartCall(ref, context);
}

/**
 * A Dart chain link calls a member of what the chain before it evaluates to,
 * typed from evidence alone: the chain's head (a type, a constructor call, a
 * string, `this` / `super`, a variable, field or getter with a declared type)
 * and each link's declared type (a method's or getter's return type, a
 * field's type, what a static constant is initialized with). Without that
 * evidence it links nothing — never a member found by its name: bloc's
 * `events.map(mapper).transform(…)` is a Stream's, not angular_bloc's
 * `BlocPipe.transform`, and riverpod's `FutureProvider.autoDispose.family(…)`
 * is the `family` getter of the builder `autoDispose` holds, not whichever
 * builder's `family` sat nearest (#750).
 */
export function matchDartChainLink(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  if (!context.getNodesByName(ref.referenceName).some((n) => n.language === 'dart')) return null;
  const code = dartCodeOf(ref.filePath, context);
  const start = code ? dartNameStart(ref, code) : -1;
  if (!code || start < 0) return null;
  // `x.name` / `x?.name`: the receiver ends before the dot. `..name` is a cascade's.
  let end = start - 1;
  while (end >= 0 && /\s/.test(code.text[end]!)) end--;
  if (code.text[end] !== '.' || code.text[end - 1] === '.') return null;
  end--;
  if (code.text[end] === '?') end--;
  while (end >= 0 && /\s/.test(code.text[end]!)) end--;
  const chain = readDartChain(code.text, end);
  const receiver = chain ? typeDartChain(chain, ref, context, 0) : null;
  if (!receiver) return null;
  // Static members are the type's own: `p.Provider.autoDispose(…)` calls the
  // constant, as `Provider.autoDispose(…)` does.
  if (receiver.static) {
    const member = dartStaticMember(receiver.type, ref.referenceName, ref, context, dartOwnerOf(receiver));
    return member && member.kind !== 'enum_member'
      ? { original: ref, targetNodeId: member.id, confidence: 0.85, resolvedBy: 'qualified-name' } : null;
  }
  const member = dartMemberOf(receiver.type, ref.referenceName, ref, context, (n) => !isDartSetter(n, context), receiver.viaSuper ? 1 : 0)?.node;
  return member ? { original: ref, targetNodeId: member.id, confidence: 0.85, resolvedBy: 'instance-method' } : null;
}

/**
 * Lookups that hand back an instance of the one type they are given:
 * provider's and flutter_bloc's `context.read<T>()` / `watch<T>()` /
 * `BlocProvider.of<T>(context)`, get_it's `get<T>()`, GetX's `find<T>()`, and
 * Flutter's `findAncestorStateOfType<T>()` family.
 */
const DART_TYPE_ARGUMENT_LOOKUPS: ReadonlySet<string> = new Set([
  'read', 'watch', 'get', 'find', 'of', 'maybeOf', 'call', 'dependOnInheritedWidgetOfExactType',
  'getInheritedWidgetOfExactType', 'findAncestorStateOfType', 'findAncestorWidgetOfExactType', 'findRootAncestorStateOfType',
]);

/** Words that can stand before a Dart name without being its declared type. */
const DART_NON_TYPE_WORDS: ReadonlySet<string> = new Set([
  'final', 'var', 'late', 'const', 'required', 'covariant', 'static', 'external', 'return', 'await', 'yield', 'throw',
  'new', 'in', 'is', 'as', 'case', 'else', 'if', 'for', 'while', 'do', 'switch', 'assert', 'this', 'super', 'get', 'set',
  'operator', 'async', 'sync', 'show', 'hide', 'typedef', 'extends', 'with', 'implements', 'on',
]);

/** A link of a Dart chain: `.name`, `.name<…>(…)` (`call`), or a subscript `[…]` (`index`). */
interface DartChainLink { name: string; typeArgs: string[]; call: boolean; index: boolean }

/**
 * What a Dart chain starts from: a name (`x`, `Foo`, `foo(…)`, `Foo<T>(…)`,
 * with the keyword written before it — `const`, `new`, `as`, `await` — and
 * where it starts), a string literal, or a parenthesized expression.
 */
type DartChainHead =
  | { kind: 'name'; name: string; typeArgs: string[]; call: boolean; keyword: string; at: number }
  | { kind: 'string' }
  | { kind: 'paren'; open: number; close: number };

interface DartChain { head: DartChainHead; links: DartChainLink[] }

/**
 * What a Dart chain evaluates to: an instance of `type`, or (`static`) the
 * type itself, before a static member — of the type `owner` declares, when
 * the chain says which file that is (`p.Box` names the one `p` brings in).
 */
interface DartValue { type: string; static: boolean; viaSuper?: boolean; owner?: string }

/**
 * A Dart file's code with comments and string contents blanked, where each
 * line starts, and the files of its library it names: its `part`s and the
 * file it is `part of`.
 */
interface DartCode { text: string; lineStarts: number[]; parts: string[]; partOf: string | null }

const DART_CODE = new WeakMap<ResolutionContext, Map<string, DartCode | null>>();

function dartCodeOf(filePath: string, context: ResolutionContext): DartCode | null {
  let memo = DART_CODE.get(context);
  if (!memo) DART_CODE.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit !== undefined) return hit;
  const source = context.readFile(filePath);
  let code: DartCode | null = null;
  if (source !== null) {
    const text = blankDartCode(source);
    const lineStarts = [0];
    for (let i = 0; i < text.length; i++) if (text[i] === '\n') lineStarts.push(i + 1);
    const sibling = (uri: string): string => path.posix.normalize(path.posix.join(path.posix.dirname(filePath), uri));
    const parts = [...source.matchAll(/^\s*part\s+['"]([^'"]+)['"]\s*;/gm)].map((m) => sibling(m[1]!));
    const partOf = /^\s*part\s+of\s+['"]([^'"]+)['"]\s*;/m.exec(source)?.[1];
    code = { text, lineStarts, parts, partOf: partOf ? sibling(partOf) : null };
  }
  // Refs arrive file by file, so a few files' worth is enough.
  if (memo.size >= 64) memo.delete(memo.keys().next().value!);
  memo.set(filePath, code);
  return code;
}

/**
 * Dart source with comments and string contents blanked, offsets kept: a
 * literal keeps its quotes, and an interpolation's code (`'${a.b()}'`) stays,
 * so a chain inside one reads like any other.
 */
function blankDartCode(source: string): string {
  const out = source.split('');
  const n = source.length;
  const blank = (from: number, to: number): void => {
    for (let k = from; k < to && k < n; k++) if (out[k] !== '\n' && out[k] !== '\r') out[k] = ' ';
  };
  type Literal = { quote: string; triple: boolean; raw: boolean };
  // The literals an open `${…}` returns to, with the brace depth around each.
  const outer: Array<{ literal: Literal; depth: number }> = [];
  let literal: Literal | null = null;
  let depth = 0;
  let i = 0;
  while (i < n) {
    const c = source[i]!;
    if (literal) {
      if (!literal.raw && c === '\\') {
        blank(i, i + 2);
        i += 2;
      } else if (!literal.raw && c === '$' && source[i + 1] === '{') {
        blank(i, i + 2);
        outer.push({ literal, depth });
        literal = null;
        depth = 0;
        i += 2;
      } else if (source.startsWith(literal.triple ? literal.quote.repeat(3) : literal.quote, i)) {
        i += literal.triple ? 3 : 1;
        literal = null;
      } else if (!literal.triple && c === '\n') {
        literal = null;
        i++;
      } else {
        blank(i, i + 1);
        i++;
      }
      continue;
    }
    if (c === '/' && source[i + 1] === '/') {
      const eol = source.indexOf('\n', i);
      const stop = eol < 0 ? n : eol;
      blank(i, stop);
      i = stop;
    } else if (c === '/' && source[i + 1] === '*') {
      let nest = 1;
      let j = i + 2;
      while (j < n && nest > 0) {
        if (source[j] === '/' && source[j + 1] === '*') { nest++; j += 2; }
        else if (source[j] === '*' && source[j + 1] === '/') { nest--; j += 2; }
        else j++;
      }
      blank(i, j);
      i = j;
    } else if (c === "'" || c === '"') {
      const triple = source.startsWith(c.repeat(3), i);
      literal = { quote: c, triple, raw: source[i - 1] === 'r' && !/[\w$]/.test(source[i - 2] ?? '') };
      i += triple ? 3 : 1;
    } else {
      if (outer.length > 0 && c === '{') depth++;
      else if (outer.length > 0 && c === '}') {
        if (depth === 0) {
          blank(i, i + 1);
          ({ literal, depth } = outer.pop()!);
          i++;
          continue;
        }
        depth--;
      }
      i++;
    }
  }
  return out.join('');
}

/** Where a Dart ref's name starts in its file's code. Its column sits just past the name (or on it). */
function dartNameStart(ref: UnresolvedRef, code: DartCode): number {
  const from = code.lineStarts[ref.line - 1];
  if (from === undefined) return -1;
  const line = code.text.slice(from, code.lineStarts[ref.line] ?? code.text.length);
  const name = ref.referenceName;
  let start = -1;
  if (line.startsWith(name, ref.column)) start = ref.column;
  else if (ref.column >= name.length && line.startsWith(name, ref.column - name.length)) start = ref.column - name.length;
  else start = line.indexOf(name);
  return start < 0 ? -1 : from + start;
}

/** The offset of the `open` bracket matching the `close` one at `at`, read backwards; -1 past `limit` characters. */
function dartOpening(text: string, at: number, open: string, close: string, limit = 20000): number {
  let depth = 0;
  for (let k = at; k >= 0 && at - k < limit; k--) {
    if (text[k] === close) depth++;
    else if (text[k] === open && --depth === 0) return k;
    else if (open === '<' && /[;{}=]/.test(text[k]!)) return -1;
  }
  return -1;
}

/** The simple name a Dart type is written as: `Foo` for `p.Foo<Bar>?`. */
function dartSimpleTypeName(text: string): string | null {
  const name = text.replace(/<[\s\S]*$/, '').replace(/\?/g, '').trim().split('.').pop()!.trim();
  return /^[A-Za-z_$][\w$]*$/.test(name) ? name : null;
}

/**
 * The links and head of the Dart expression whose last character is at
 * `end`, read backwards: `FutureProvider.autoDispose` → `FutureProvider`
 * then `.autoDispose`; `events.map(mapper)` → `events` then `.map(…)`. Null
 * for a shape the walk does not read — a cascade section, a number, a call
 * of an expression.
 */
function readDartChain(text: string, end: number): DartChain | null {
  const links: DartChainLink[] = [];
  let i = end;
  const skip = (): void => {
    while (i >= 0 && /\s/.test(text[i]!)) i--;
  };
  for (let step = 0; step < 32; step++) {
    skip();
    while (text[i] === '!') {
      i--;
      skip();
    }
    if (text[i] === ']') {
      const open = dartOpening(text, i, '[', ']');
      if (open < 0) return null;
      links.push({ name: '', typeArgs: [], call: false, index: true });
      i = open - 1;
      continue;
    }
    if (text[i] === "'" || text[i] === '"') return { head: { kind: 'string' }, links: links.reverse() };
    let call = false;
    let typeArgs: string[] = [];
    if (text[i] === ')') {
      const close = i;
      const open = dartOpening(text, i, '(', ')');
      if (open < 0) return null;
      i = open - 1;
      skip();
      if (text[i] === '>') {
        const lt = dartOpening(text, i, '<', '>', 400);
        if (lt < 0) return null;
        typeArgs = splitCppTopLevel(text.slice(lt + 1, i));
        i = lt - 1;
        skip();
      }
      if (!/[\w$]/.test(text[i] ?? '')) {
        // `(…)` with no name before it is the head — unless an expression is called: `f()(…)`.
        if (typeArgs.length > 0 || text[i] === ')' || text[i] === ']') return null;
        return { head: { kind: 'paren', open, close }, links: links.reverse() };
      }
      call = true;
    } else if (text[i] === '>') {
      // `BlocProvider<CounterCubit>.value(…)`: a type written with its arguments.
      const lt = dartOpening(text, i, '<', '>', 400);
      if (lt < 0) return null;
      typeArgs = splitCppTopLevel(text.slice(lt + 1, i));
      i = lt - 1;
      skip();
    }
    const nameEnd = i + 1;
    while (i >= 0 && /[\w$]/.test(text[i]!)) i--;
    const name = text.slice(i + 1, nameEnd);
    if (!/^[A-Za-z_$][\w$]*$/.test(name)) return null;
    let j = i;
    while (j >= 0 && /\s/.test(text[j]!)) j--;
    if (text[j] === '.') {
      // `obj..a().b()`: a cascade section's receiver is the cascade's target.
      if (text[j - 1] === '.') return null;
      links.push({ name, typeArgs, call, index: false });
      i = j - 1;
      if (text[i] === '?') i--;
      continue;
    }
    const keyword = /([A-Za-z_]\w*)$/.exec(text.slice(Math.max(0, j - 10), j + 1))?.[1] ?? '';
    return { head: { kind: 'name', name, typeArgs, call, keyword, at: i + 1 }, links: links.reverse() };
  }
  return null;
}

/** What a Dart chain evaluates to, link by link, or null where the evidence runs out. */
function typeDartChain(chain: DartChain, ref: UnresolvedRef, context: ResolutionContext, depth: number): DartValue | null {
  if (depth > 3) return null;
  const head = chain.head;
  let links = chain.links;
  let value: DartValue | null;
  if (head.kind === 'string') value = { type: 'String', static: false };
  else if (head.kind === 'paren') value = typeDartParen(head, ref, context, depth);
  else {
    // `p.Provider.autoDispose`: an import prefix names a library, so the chain
    // starts at the link after it, which names what that library exports.
    const first = links[0];
    if (!head.call && head.typeArgs.length === 0 && first && !first.index && dartImportPrefixes(ref.filePath, context).has(head.name) &&
        !isDartNameHidden(head.name, ref, head.at, context)) {
      value = typeDartPrefixedHead(head.name, first, ref, context, depth);
      links = links.slice(1);
    } else {
      // `const Foo.named(…)`: the named constructor is the head's own link.
      if ((head.keyword === 'const' || head.keyword === 'new') && !head.call && links[0]?.call) links = links.slice(1);
      value = typeDartHead(head, ref, context, depth);
    }
  }
  for (const link of links) {
    // Every Dart object's `toString()` returns a String, whatever it is.
    if (link.name === 'toString' && link.call && link.typeArgs.length === 0) {
      value = { type: 'String', static: false };
      continue;
    }
    const next = value ? typeDartLink(value, link, ref, context, depth) : null;
    // A lookup nothing declared answers for hands back the type it is given,
    // whatever it is called on: `context.read<LoginCubit>()` on Flutter's
    // BuildContext, or on an untyped `(context) =>` parameter.
    const given = !next && link.call && link.typeArgs.length === 1 && DART_TYPE_ARGUMENT_LOOKUPS.has(link.name) &&
      !(value && dartLinkDeclared(value, link, ref, context)) ? dartSimpleTypeName(link.typeArgs[0]!) : null;
    // An untyped value stays untyped until a link says what it makes.
    value = next ?? (given ? { type: given, static: false } : null);
  }
  return value;
}

/** Whether the type a Dart chain has reached declares the member a link names. */
function dartLinkDeclared(value: DartValue, link: DartChainLink, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return value.static
    ? dartStaticMember(value.type, link.name, ref, context, dartOwnerOf(value)) !== null
    : dartMemberOf(value.type, link.name, ref, context, (n) => !isDartSetter(n, context), value.viaSuper ? 1 : 0) !== null;
}

/** Which of the types named like a chain's value it is: the one its `owner` file declares, when the chain said. */
function dartOwnerOf(value: DartValue): ((type: Node) => boolean) | undefined {
  return value.owner === undefined ? undefined : (type) => type.filePath === value.owner;
}

/** `(x as Foo)` is a Foo; any other parenthesized expression is what its last operand is: `(a ?? Todo(…))`. */
function typeDartParen(head: { open: number; close: number }, ref: UnresolvedRef, context: ResolutionContext, depth: number): DartValue | null {
  const code = dartCodeOf(ref.filePath, context);
  if (!code) return null;
  const inner = code.text.slice(head.open + 1, head.close);
  const cast = /\bas\s+((?:[A-Za-z_$][\w$]*\.)?[A-Za-z_$][\w$]*)\s*(?:<[^()]*>)?\s*\??\s*$/.exec(inner);
  if (cast) {
    const type = dartSimpleTypeName(cast[1]!);
    return type ? { type, static: false } : null;
  }
  let end = head.close - 1;
  while (end > head.open && /\s/.test(code.text[end]!)) end--;
  return dartExpressionValue(code.text, end, ref, context, depth);
}

/** The value of the Dart expression ending at `end`: an instance, never a type, and never an awaited one. */
function dartExpressionValue(text: string, end: number, ref: UnresolvedRef, context: ResolutionContext, depth: number): DartValue | null {
  const chain = readDartChain(text, end);
  if (!chain || (chain.head.kind === 'name' && chain.head.keyword === 'await')) return null;
  const value = typeDartChain(chain, ref, context, depth + 1);
  return value && !value.static ? value : null;
}

/** What a Dart chain's head evaluates to. */
function typeDartHead(
  head: { name: string; typeArgs: string[]; call: boolean; keyword: string },
  ref: UnresolvedRef,
  context: ResolutionContext,
  depth: number,
): DartValue | null {
  const name = head.name;
  if (name === 'this' || name === 'super') {
    const own = dartEnclosingType(ref, context);
    return own ? { type: own.name, static: false, viaSuper: name === 'super' } : null;
  }
  if (head.keyword === 'const' || head.keyword === 'new' || head.keyword === 'as') return { type: name, static: false };
  if (head.keyword === 'is') return null;
  const isType = context.getNodesByName(name).some((n) => n.language === 'dart' && DART_TYPE_KINDS.has(n.kind));
  if (head.call) {
    // `Foo(…)` constructs a Foo; `foo(…)` is what the function says it returns,
    // or — a variable holding a callable, riverpod's `family(0)` — what its `call` does.
    if (isType) return { type: name, static: false };
    const fn = dartFunctionNamed(name, ref, context);
    if (fn) {
      const type = dartReturnType(fn, head.typeArgs, context);
      return type ? { type, static: false } : null;
    }
    const held = dartVariableType(name, ref, context, depth);
    return held ? dartCallResult(held, head.typeArgs, ref, context) : null;
  }
  // `Foo.` before a static member — a type outside the project included, whose members nothing reaches.
  if (isType || (/^[A-Z]/.test(name) && !context.getNodesByName(name).some((n) => n.language === 'dart' && (n.kind === 'constant' || n.kind === 'variable')))) {
    return { type: name, static: true };
  }
  const type = dartVariableType(name, ref, context, depth);
  return type ? { type, static: false } : null;
}

/**
 * What the first link after an import prefix evaluates to — `p.Provider`
 * before a static member, `p.Report(…)`, `p.make(…)`, `p.config` — read from
 * the top-level declarations the prefixed import brings in, and nothing when
 * it brings in none of that name: a package outside the repository, whatever
 * the project declares under the name elsewhere.
 */
function typeDartPrefixedHead(prefix: string, link: DartChainLink, ref: UnresolvedRef, context: ResolutionContext, depth: number): DartValue | null {
  const found = dartPrefixedDecls(prefix, link.name, ref, context);
  const types = found.filter((n) => DART_TYPE_KINDS.has(n.kind));
  if (types.length > 0) {
    return { type: link.name, static: !link.call, owner: types.length === 1 ? types[0]!.filePath : undefined };
  }
  if (found.length !== 1) return null;
  const decl = found[0]!;
  if (decl.kind === 'function') {
    const type = link.call ? dartReturnType(decl, link.typeArgs, context) : null;
    return type ? { type, static: false } : null;
  }
  if (decl.kind !== 'constant' && decl.kind !== 'variable') return null;
  const held = dartConstantType(decl, ref, context, depth);
  if (!held) return null;
  return link.call ? dartCallResult(held, link.typeArgs, ref, context) : { type: held, static: false };
}

/** What one link of a Dart chain makes of the value before it. */
function typeDartLink(value: DartValue, link: DartChainLink, ref: UnresolvedRef, context: ResolutionContext, depth: number): DartValue | null {
  if (link.index) return null;
  if (value.static) {
    const member = dartStaticMember(value.type, link.name, ref, context, dartOwnerOf(value));
    if (!member) {
      // `BlocProvider.value(…)`, `AsyncValue.data(…)`: a constructor the index holds no node for.
      return link.call && context.getNodesByName(value.type).some((n) => n.language === 'dart' && DART_TYPE_KINDS.has(n.kind))
        ? { type: value.type, static: false } : null;
    }
    if (member.kind === 'enum_member') return link.call ? null : { type: value.type, static: false };
    if (member.kind === 'constant') {
      // `FutureProvider.autoDispose`: the value the static constant holds.
      const held = dartConstantType(member, ref, context, depth);
      if (!held) return null;
      return link.call ? dartCallResult(held, link.typeArgs, ref, context) : { type: held, static: false };
    }
    return typeDartMemberUse(member, link, ref, context);
  }
  const member = dartMemberOf(value.type, link.name, ref, context, (n) => !isDartSetter(n, context), value.viaSuper ? 1 : 0)?.node;
  if (member) return typeDartMemberUse(member, link, ref, context);
  // A field mints no node: its declared type is read from its class.
  if (link.call) return null;
  const field = dartFieldType(value.type, link.name, ref, context, depth);
  return field ? { type: field, static: false } : null;
}

/** What using a member makes: a method's call or a getter's read is its declared return type; a getter called is its value called. */
function typeDartMemberUse(member: Node, link: DartChainLink, ref: UnresolvedRef, context: ResolutionContext): DartValue | null {
  const getter = isDartGetter(member, context);
  const type = dartReturnType(member, getter ? [] : link.typeArgs, context);
  if (!type) return null;
  if (getter) return link.call ? dartCallResult(type, link.typeArgs, ref, context) : { type, static: false };
  // A method named without a call is a tear-off: a function, not its result.
  return link.call ? { type, static: false } : null;
}

/** What calling a value of `type` returns — its `call` method's declared return type. */
function dartCallResult(type: string, typeArgs: string[], ref: UnresolvedRef, context: ResolutionContext): DartValue | null {
  const call = dartMemberOf(type, 'call', ref, context, (n) => !isDartGetter(n, context))?.node;
  const result = call ? dartReturnType(call, typeArgs, context) : null;
  return result ? { type: result, static: false } : null;
}

const DART_RETURN_TYPES = new WeakMap<ResolutionContext, Map<string, { type: string; own: string[] } | null>>();

/**
 * A Dart function's declared return type as a simple name, a type parameter
 * of its own replaced by the type argument the call gives (`T read<T>()`
 * called as `read<Foo>()` is a Foo); a type parameter of its class
 * (`State get state` in `BlocBase<State>`) says nothing without the
 * receiver's own arguments.
 */
function dartReturnType(fn: Node, typeArgs: string[], context: ResolutionContext): string | null {
  let memo = DART_RETURN_TYPES.get(context);
  if (!memo) DART_RETURN_TYPES.set(context, (memo = new Map()));
  let info = memo.get(fn.id);
  if (info === undefined) {
    info = null;
    const type = fn.returnType ? dartSimpleTypeName(fn.returnType) : null;
    if (type) {
      // `static T of<T …>(…)` in `BlocProvider<T …>`: the function's own parameter is the one meant.
      const own = declaredTypeParameters(fn, context);
      const cut = fn.qualifiedName.lastIndexOf('::');
      const owner = cut > 0 && !own.includes(type) ? context.getNodesInFile(fn.filePath).find((n) => DART_TYPE_KINDS.has(n.kind) &&
        n.qualifiedName === fn.qualifiedName.slice(0, cut) && n.startLine <= fn.startLine && n.endLine >= fn.endLine) : undefined;
      if (!owner || !declaredTypeParameters(owner, context).includes(type)) info = { type, own };
    }
    memo.set(fn.id, info);
  }
  if (!info) return null;
  const at = info.own.indexOf(info.type);
  if (at < 0) return info.type;
  return typeArgs[at] ? dartSimpleTypeName(typeArgs[at]!) : null;
}

/** The innermost Dart class, mixin, enum or extension a reference sits in. */
function dartEnclosingType(ref: UnresolvedRef, context: ResolutionContext): Node | null {
  let own: Node | null = null;
  for (const n of context.getNodesInFile(ref.filePath)) {
    if (DART_TYPE_KINDS.has(n.kind) && n.startLine <= ref.line && n.endLine >= ref.line && (!own || n.startLine >= own.startLine)) own = n;
  }
  return own;
}

/**
 * The static member `name` the Dart type `typeName` itself declares — a
 * static method or getter, a named constructor or factory, a static
 * constant, an enum value — preferring the call site's file, then the
 * nearest. Static members are not inherited. `isOwner` narrows the types of
 * that name to the one meant (the one an import prefix brings in).
 */
function dartStaticMember(
  typeName: string,
  name: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  isOwner: (type: Node) => boolean = () => true,
): Node | null {
  const owners = context.getNodesByName(typeName).filter((n) => n.language === 'dart' && DART_TYPE_KINDS.has(n.kind) && isOwner(n));
  if (owners.length === 0) return null;
  const found = context.getNodesByName(name).filter((m) => m.language === 'dart' &&
    (m.kind === 'method' || m.kind === 'function' || m.kind === 'constant' || m.kind === 'enum_member') &&
    owners.some((o) => o.filePath === m.filePath && m.qualifiedName === `${o.qualifiedName}::${name}`) &&
    !isDartSetter(m, context) && isDartStaticMember(m, context));
  if (found.length <= 1) return found[0] ?? null;
  return found.find((m) => m.filePath === ref.filePath) ??
    found.reduce((a, b) => (computePathProximity(ref.filePath, b.filePath) > computePathProximity(ref.filePath, a.filePath) ? b : a));
}

/**
 * Whether a member of a Dart type is reached through the type itself: a
 * static member, constant or enum value, or a named constructor or factory
 * (`factory ProviderContainer.test(…)`) — not an instance member sharing a
 * constructor's name (`AsyncValue`'s `error` getter beside its
 * `AsyncValue.error(…)` factory, even declared on the line above it).
 */
function isDartStaticMember(m: Node, context: ResolutionContext): boolean {
  return m.isStatic === true || m.kind === 'constant' || m.kind === 'enum_member' || isDartConstructor(m, context);
}

/**
 * The function a bare Dart call `name(…)` means: a member of the type around
 * it (an implicit `this.`), else a function of the file, else the one
 * function of that name the project declares.
 */
function dartFunctionNamed(name: string, ref: UnresolvedRef, context: ResolutionContext): Node | null {
  const own = dartEnclosingType(ref, context);
  const member = own ? dartMemberOf(own.name, name, ref, context, (n) => !isDartGetter(n, context) && !isDartSetter(n, context))?.node : undefined;
  if (member) return member;
  return dartLibraryPick(context.getNodesByName(name).filter((n) => n.language === 'dart' && n.kind === 'function' && !n.qualifiedName.includes('::')), ref, context);
}

/**
 * Of same-named top-level Dart declarations, the one the call's library
 * holds — its own file, then a `part` of it (riverpod_generator's
 * `depFamilyProvider` in `missing_dependencies.g.dart`) — else the only one.
 */
function dartLibraryPick(nodes: Node[], ref: UnresolvedRef, context: ResolutionContext): Node | null {
  const own = nodes.find((n) => n.filePath === ref.filePath);
  if (own) return own;
  const library = dartLibraryFiles(ref.filePath, context);
  const shared = nodes.filter((n) => library.has(n.filePath));
  if (shared.length === 1) return shared[0]!;
  return nodes.length === 1 ? nodes[0]! : null;
}

/** The files of a Dart file's library: itself, its `part`s, and the file it is `part of` with that file's parts. */
function dartLibraryFiles(filePath: string, context: ResolutionContext): Set<string> {
  const files = new Set([filePath]);
  const code = dartCodeOf(filePath, context);
  for (const part of code?.parts ?? []) files.add(part);
  if (code?.partOf) {
    files.add(code.partOf);
    for (const part of dartCodeOf(code.partOf, context)?.parts ?? []) files.add(part);
  }
  return files;
}

/**
 * The declared type of a Dart variable a chain starts from: a local or
 * parameter the code around the call declares (the nearest declaration wins,
 * and an untyped one ends the search), a field or getter of the class around
 * it, or a top-level variable.
 */
function dartVariableType(name: string, ref: UnresolvedRef, context: ResolutionContext, depth: number): string | null {
  const local = dartLocalType(name, ref, context, depth);
  if (local !== undefined) return local;
  const field = inferMemberReceiverType(name, ref, context);
  if (field) return dartSimpleTypeName(field);
  const own = dartEnclosingType(ref, context);
  const getter = own ? dartMemberOf(own.name, name, ref, context, (n) => isDartGetter(n, context))?.node : undefined;
  if (getter) return dartReturnType(getter, [], context);
  const top = dartLibraryPick(context.getNodesByName(name).filter((n) => n.language === 'dart' && n.kind === 'constant' && !n.qualifiedName.includes('::')), ref, context);
  return top ? dartConstantType(top, ref, context, depth) : null;
}

/**
 * The type of the nearest declaration of `name` before the call, within the
 * function around it: its declared type (`final Ticker _ticker`, `Foo? x`,
 * `(BuildContext context)`), else what its initializer evaluates to (`final
 * todo = Todo(…)`). Null for a declaration that says no type (a `for (final
 * x in …)` variable, an untyped closure parameter); undefined for none.
 */
function dartLocalType(name: string, ref: UnresolvedRef, context: ResolutionContext, depth: number): string | null | undefined {
  const code = dartCodeOf(ref.filePath, context);
  const at = code ? dartNameStart(ref, code) : -1;
  if (!code || at < 0) return undefined;
  const start = code.lineStarts[enclosingScopeStartLine(ref, context) - 1] ?? 0;
  const scope = code.text.slice(start, at);
  const uses = dartNameUses(code, ref.filePath, name, context);
  // The last use before the call: uses are in file order.
  let lo = 0;
  let hi = uses.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (uses[mid]! < at) lo = mid + 1;
    else hi = mid;
  }
  for (let u = lo - 1; u >= 0 && uses[u]! >= start; u--) {
    const pos = uses[u]! - start;
    const before = scope.slice(Math.max(0, pos - 120), pos);
    const after = scope.slice(pos + name.length);
    const declared = /([A-Za-z_$][\w$]*)\s*(<[^;{}()=]*>)?\s*\??\s+$/.exec(before);
    const typed = declared && !DART_NON_TYPE_WORDS.has(declared[1]!) && /^\s*(?:[=;,)}]|in\b)/.test(after) &&
      !/^\s*==/.test(after) ? declared[1]! : null;
    if (typed) return typed;
    // `final x = …`, `var x = …`: the initializer says the type.
    if (/(?:^|[^\w$])(?:final|var|late|const)\s+$/.test(before)) {
      const init = /^\s*=(?![=>])/.exec(after);
      return init ? dartInitializerType(code.text, start + pos + name.length + init[0].length, ref, context, depth) : null;
    }
    // A closure's untyped parameter — `(context, state) =>` — or a `catch (e)`;
    // not an argument of a call, `foo(x, (a) {…})`, nor an `if (x) {`.
    if (/^\s*[,)]/.test(after) && /[(,]\s*$/.test(before)) {
      const open = dartGroupOpen(code.text, start + pos);
      const close = open < 0 ? -1 : dartGroupClose(code.text, open);
      const callee = /([\w$]*)\s*(?:<[^;{}()]*>)?\s*$/.exec(code.text.slice(Math.max(0, open - 60), Math.max(0, open)))?.[1] ?? '';
      if (callee === 'catch') return null;
      if (close >= 0 && !/[\w$>)\]]\s*$/.test(code.text.slice(Math.max(0, open - 60), Math.max(0, open))) &&
          /^\)\s*(?:async\s*\*?|sync\s*\*)?\s*(?:=>|\{)/.test(code.text.slice(close, close + 30))) return null;
    }
  }
  return undefined;
}

/**
 * The `>` closing a Dart type argument list opened at `open` — one followed
 * by a call, a member or another `>`, which a comparison's `<` never is — or -1.
 */
function dartTypeArgumentsEnd(text: string, open: number): number {
  let depth = 0;
  for (let k = open; k < text.length && k - open < 400; k++) {
    const ch = text[k];
    if (ch === '<') depth++;
    else if (ch === '>' && --depth === 0) return /^\s*[(.>?]/.test(text.slice(k + 1, k + 4)) ? k : -1;
    else if (ch === ';' || ch === '{' || ch === '}' || ch === '=') return -1;
  }
  return -1;
}

/** The `(` of the parenthesized group around offset `at`, read backwards; -1 when there is none nearby. */
function dartGroupOpen(text: string, at: number): number {
  let parens = 0;
  let braces = 0;
  for (let k = at - 1; k >= 0 && at - k < 4000; k--) {
    const ch = text[k];
    if (ch === '}') braces++;
    else if (ch === '{') {
      if (braces-- === 0) return -1;
    } else if (braces > 0) continue;
    else if (ch === ')') parens++;
    else if (ch === '(') {
      if (parens-- === 0) return k;
    } else if (ch === ';') return -1;
  }
  return -1;
}

/** The `)` closing the `(` at `open`; -1 when it is not found nearby. */
function dartGroupClose(text: string, open: number): number {
  let depth = 0;
  for (let k = open; k < text.length && k - open < 8000; k++) {
    if (text[k] === '(') depth++;
    else if (text[k] === ')' && --depth === 0) return k;
  }
  return -1;
}

const DART_NAME_USES = new WeakMap<ResolutionContext, Map<string, number[]>>();

/** Where a name is written in a Dart file's code — not as a member (`.name`) — read once per file and name. */
function dartNameUses(code: DartCode, filePath: string, name: string, context: ResolutionContext): number[] {
  let memo = DART_NAME_USES.get(context);
  if (!memo) DART_NAME_USES.set(context, (memo = new Map()));
  const key = `${filePath}|${name}`;
  const hit = memo.get(key);
  if (hit) return hit;
  const uses = [...code.text.matchAll(new RegExp(`(?<![\\w$.])${escapeRegExp(name)}(?![\\w$])`, 'g'))].map((m) => m.index!);
  if (memo.size >= 4096) memo.delete(memo.keys().next().value!);
  memo.set(key, uses);
  return uses;
}

/** What the Dart expression starting at `from` evaluates to, read back from where its statement ends. */
function dartInitializerType(text: string, from: number, ref: UnresolvedRef, context: ResolutionContext, depth: number): string | null {
  let nest = 0;
  let k = from;
  for (; k < text.length && k - from < 4000; k++) {
    const ch = text[k]!;
    // `AsyncNotifierProvider.family<A, B, C>(…)`: a type argument list's commas end nothing.
    if (ch === '<' && /[\w$]/.test(text[k - 1] ?? '')) {
      const close = dartTypeArgumentsEnd(text, k);
      if (close > 0) {
        k = close;
        continue;
      }
    }
    if (ch === '(' || ch === '[' || ch === '{') nest++;
    else if (ch === ')' || ch === ']' || ch === '}') {
      if (nest === 0) break;
      nest--;
    } else if ((ch === ';' || ch === ',') && nest === 0) break;
  }
  let end = k - 1;
  while (end >= from && /\s/.test(text[end]!)) end--;
  if (end < from) return null;
  return dartExpressionValue(text, end, ref, context, depth)?.type ?? null;
}

/**
 * The type a Dart constant is declared with — `static const Foo x = …`,
 * `final Foo? x` — or, with none written, what its initializer evaluates to:
 * riverpod's `static const autoDispose = AutoDisposeFutureProviderBuilder();`.
 */
function dartConstantType(constant: Node, ref: UnresolvedRef, context: ResolutionContext, depth: number): string | null {
  const code = dartCodeOf(constant.filePath, context);
  const from = code?.lineStarts[constant.startLine - 1];
  if (!code || from === undefined) return null;
  const head = new RegExp(`\\b(?:const|final|var)\\s+(?:([A-Za-z_$][\\w$.]*)\\s*(?:<[^;=]*>)?\\s*\\??\\s+)?${escapeRegExp(constant.name)}\\s*=(?![=>])`)
    .exec(code.text.slice(from, from + 600));
  if (!head) return null;
  if (head[1] && !DART_NON_TYPE_WORDS.has(head[1])) return dartSimpleTypeName(head[1]);
  const site: UnresolvedRef = { ...ref, filePath: constant.filePath, line: constant.startLine, column: 0 };
  return dartInitializerType(code.text, from + head.index + head[0].length, site, context, depth + 1);
}

/**
 * The type a Dart class — or a type it extends, mixes in or implements —
 * declares a field `name` with (`final ProviderPointerManager _pointerManager`),
 * or what the field is initialized with (`final _cache = Cache()`).
 */
function dartFieldType(typeName: string, name: string, ref: UnresolvedRef, context: ResolutionContext, depth: number): string | null {
  const lineage = [...dartLineage(typeName, context)].sort((a, b) => a[1] - b[1]);
  for (const [owner] of lineage) {
    for (const decl of context.getNodesByName(owner)) {
      if (decl.language !== 'dart' || !DART_TYPE_KINDS.has(decl.kind)) continue;
      const declared = classMemberType(decl, name, context);
      if (declared) return dartSimpleTypeName(declared);
      // An abstract getter mints no node: `ProviderElement? get _listenedElement;`.
      const getter = new RegExp(String.raw`(?:^|[\s;{}])([A-Za-z_$][\w$]*)\s*(?:<[^;{}=]*>)?\s*\??\s+get\s+${escapeRegExp(name)}\s*;`);
      for (const { text } of classMemberLines(decl, context)) {
        const m = text.includes(name) ? getter.exec(text) : null;
        if (m && !DART_NON_TYPE_WORDS.has(m[1]!)) return dartSimpleTypeName(m[1]!);
      }
      const code = dartCodeOf(decl.filePath, context);
      const from = code?.lineStarts[decl.startLine - 1];
      const to = code?.lineStarts[decl.endLine];
      if (!code || from === undefined) continue;
      const init = new RegExp(`\\b(?:final|var|late)\\s+${escapeRegExp(name)}\\s*=(?![=>])`).exec(code.text.slice(from, to));
      if (init) {
        const site: UnresolvedRef = { ...ref, filePath: decl.filePath, line: decl.startLine, column: 0 };
        return dartInitializerType(code.text, from + init.index + init[0].length, site, context, depth + 1);
      }
    }
  }
  return null;
}

/** The simple names a Dart type's declarations extend, mix in, implement, or (an extension / mixin) sit `on`. */
function dartSupertypesOf(typeName: string, context: ResolutionContext): string[] {
  let memo = DART_SUPERS.get(context);
  if (!memo) {
    memo = new Map();
    DART_SUPERS.set(context, memo);
  }
  const hit = memo.get(typeName);
  if (hit) return hit;
  const names: string[] = [];
  for (const decl of context.getNodesByName(typeName)) {
    if (decl.language !== 'dart' || !DART_TYPE_KINDS.has(decl.kind)) continue;
    names.push(...dartHeadOf(decl, context).supers);
  }
  memo.set(typeName, names);
  return names;
}

const DART_HEAD_WORDS: ReadonlySet<string> = new Set(['extends', 'with', 'implements', 'on']);

/**
 * A Dart type declaration's head, read from source up to its body: the
 * supertypes it names, and whether it is an `extension` (whose one supertype
 * is the type it extends). Comments and type arguments are dropped first, so
 * riverpod's `class $NotifierProviderElement< // … NotifierT extends
 * $Notifier<ValueT>, ValueT > extends $ClassProviderElement<…> with
 * ElementWithFuture<…>` reads as `extends $ClassProviderElement with
 * ElementWithFuture`, and `class A = B with C;` as its mixin application.
 */
function dartHeadOf(decl: Node, context: ResolutionContext): { supers: string[]; extension: boolean } {
  const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
  const text = lines
    .slice(decl.startLine - 1, Math.min(decl.endLine, decl.startLine + 40))
    .join('\n')
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    .replace(/\/\/[^\n]*/g, ' ');
  let depth = 0;
  let flat = '';
  for (const ch of text) {
    if (ch === '<') depth++;
    else if (ch === '>') depth = Math.max(0, depth - 1);
    else if (depth === 0) {
      if (ch === '{' || ch === ';') break;
      flat += ch;
    }
  }
  const keyword = /\b(class|mixin|extension|enum)\b/.exec(flat);
  const head = keyword ? flat.slice(keyword.index) : flat;
  const clause = /(?:\b(?:extends|with|implements|on)\b|=)([\s\S]*)$/.exec(head)?.[1] ?? '';
  return {
    supers: [...clause.matchAll(/[A-Za-z_$][\w$]*/g)].map((m) => m[0]).filter((w) => !DART_HEAD_WORDS.has(w)),
    extension: keyword?.[1] === 'extension' && !/^extension\s+type\b/.test(head),
  };
}

const DART_LINEAGES = new WeakMap<ResolutionContext, Map<string, Map<string, number>>>();
const DART_EXTENSION_OWNERS = new WeakMap<ResolutionContext, Map<string, DartExtensionOwner | null>>();
const DART_GETTERS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** A Dart type and every type it extends, mixes in or implements, by supertype distance (at most 40). */
function dartLineage(typeName: string, context: ResolutionContext): Map<string, number> {
  let memo = DART_LINEAGES.get(context);
  if (!memo) DART_LINEAGES.set(context, (memo = new Map()));
  const hit = memo.get(typeName);
  if (hit) return hit;
  const depths = new Map<string, number>();
  const queue: Array<[string, number]> = [[typeName, 0]];
  while (queue.length > 0 && depths.size < 40) {
    const [name, depth] = queue.shift()!;
    if (depths.has(name)) continue;
    depths.set(name, depth);
    for (const sup of dartSupertypesOf(name, context)) queue.push([sup, depth + 1]);
  }
  memo.set(typeName, depths);
  return depths;
}

/**
 * The extension a Dart member is declared in — the types it is `on`, whether
 * it is named, and whether it is `on` a type parameter of its own (`extension
 * ObjectX<T> on T`, which every type has) — or null for a class's, mixin's or
 * enum's member.
 */
interface DartExtensionOwner { on: string[]; named: boolean; universal: boolean }

function dartExtensionOwner(member: Node, context: ResolutionContext): DartExtensionOwner | null {
  let memo = DART_EXTENSION_OWNERS.get(context);
  if (!memo) DART_EXTENSION_OWNERS.set(context, (memo = new Map()));
  const hit = memo.get(member.id);
  if (hit !== undefined) return hit;
  let found: DartExtensionOwner | null = null;
  const cut = member.qualifiedName.lastIndexOf('::');
  if (cut > 0) {
    const ownerQn = member.qualifiedName.slice(0, cut);
    const owner = context.getNodesInFile(member.filePath).find((n) => n.qualifiedName === ownerQn && n.kind === 'class' &&
      n.startLine <= member.startLine && n.endLine >= member.startLine);
    const decl = owner ? dartExtensionDecl(owner, context) : null;
    if (owner && decl) {
      const on = dartHeadOf(owner, context).supers;
      found = { on, named: decl.named, universal: on.length === 1 && declaredTypeParameters(owner, context).includes(on[0]!) };
    }
  }
  memo.set(member.id, found);
  return found;
}

/** Whether a Dart member is a getter — declared `get <name>`, a method its readers run. */
function isDartGetter(n: Node, context: ResolutionContext): boolean {
  if (n.language !== 'dart' || n.kind !== 'method') return false;
  let memo = DART_GETTERS.get(context);
  if (!memo) DART_GETTERS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  // The declaration from its start, and the next line for a return type that wraps.
  const head = `${(lines[n.startLine - 1] ?? '').slice(n.startColumn)} ${lines[n.startLine] ?? ''}`;
  const getter = new RegExp(String.raw`^[^={;]*?\bget\s+${escapeRegExp(n.name)}(?![\w$])`).test(head);
  memo.set(n.id, getter);
  return getter;
}

const DART_SETTERS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** Whether a Dart member is a setter — declared `set <name>(…)`, which no call or read runs. */
function isDartSetter(n: Node, context: ResolutionContext): boolean {
  if (n.language !== 'dart' || n.kind !== 'method') return false;
  let memo = DART_SETTERS.get(context);
  if (!memo) DART_SETTERS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  const line = (context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [])[n.startLine - 1] ?? '';
  const setter = new RegExp(String.raw`^[^={;]*?\bset\s+${escapeRegExp(n.name)}\s*\(`).test(line.slice(n.startColumn));
  memo.set(n.id, setter);
  return setter;
}

/**
 * The Dart member `name` a value of type `typeName` reaches, as Dart finds it:
 * the nearest one the type or a type it extends, mixes in or implements
 * declares, else one an extension on such a type adds — an extension applies
 * only where no instance member answers, and an unnamed one only in its own
 * library. `accept` narrows the candidates (a read wants a getter). Ties go to
 * the call site's own file, then the nearest directory — riverpod's translated
 * docs carry their own copy of each example's extension. `minDepth` 1 skips
 * the type's own members, as `super.` does.
 */
function dartMemberOf(
  typeName: string,
  name: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  accept: (n: Node) => boolean,
  minDepth = 0,
): { node: Node; viaExtension: boolean } | null {
  const lineage = dartLineage(typeName, context);
  const depthOf = (t: string): number => {
    const depth = lineage.get(t);
    return depth === undefined || depth < minDepth ? Infinity : depth;
  };
  let best: Node[] = [];
  let bestRank = Infinity;
  let isProjectType: boolean | undefined;
  for (const m of context.getNodesByName(name)) {
    if (m.language !== 'dart' || !isDartMember(m) || !accept(m)) continue;
    const extension = dartExtensionOwner(m, context);
    let rank: number;
    if (extension) {
      if (!extension.named && !inSameDartLibrary(ref.filePath, m.filePath, context)) continue;
      // `extension ObjectX<T> on T` reaches every type, after every extension
      // that names one of its lineage — when the type is the project's, so
      // what it declares is known: a List's own `cast` is not ObjectX's.
      const on = extension.universal
        ? (isProjectType ??= context.getNodesByName(typeName).some((n) => n.language === 'dart' && DART_TYPE_KINDS.has(n.kind)))
          ? DART_UNIVERSAL_RANK : Infinity
        : Math.min(...extension.on.map(depthOf));
      if (on === Infinity) continue;
      rank = DART_EXTENSION_RANK + on;
    } else {
      const owner = m.qualifiedName.slice(0, Math.max(0, m.qualifiedName.lastIndexOf('::'))).split('::').pop()!;
      const depth = depthOf(owner);
      if (depth === Infinity) continue;
      rank = depth;
    }
    if (rank < bestRank) {
      bestRank = rank;
      best = [m];
    } else if (rank === bestRank) {
      best.push(m);
    }
  }
  if (best.length === 0) return null;
  const node = best.find((n) => n.filePath === ref.filePath) ??
    best.reduce((a, b) => (computePathProximity(ref.filePath, b.filePath) > computePathProximity(ref.filePath, a.filePath) ? b : a));
  return { node, viaExtension: bestRank >= DART_EXTENSION_RANK };
}

/** `x.area` / `Config.instance`: the receiver and member of a Dart member read. */
const DART_MEMBER_READ = /^([A-Za-z_$][\w$]*)\.([A-Za-z_$][\w$]*)$/;

/**
 * Whether a ref is a Dart member read — `x.area`, which the extractor records
 * as a `references` ref named `<receiver>.<member>`. No other Dart reference
 * carries a dotted name: a type is one identifier, a static read names only
 * its type.
 */
export function isDartMemberRead(ref: UnresolvedRef): boolean {
  return ref.language === 'dart' && ref.referenceKind === 'references' && DART_MEMBER_READ.test(ref.referenceName);
}

/**
 * A Dart member read runs code only when the member is a getter, so it links
 * — as a call — the getter the receiver's type reaches: declared on the type, a
 * type it extends, mixes in or implements, or added by an extension on one of
 * them (`s.label` on an enum `Shape` through `extension ShapeInfo on Shape`),
 * or nothing: a field read, a getter of a type outside the project, a receiver
 * whose type is not written down. Never a same-named getter found by name alone
 * (#2338).
 */
export function matchDartMemberRead(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  const parts = DART_MEMBER_READ.exec(ref.referenceName);
  if (!parts) return null;
  const receiver = parts[1]!;
  const member = parts[2]!;
  // Most reads are of fields, which mint no nodes: check for a getter first.
  if (!context.getNodesByName(member).some((n) => isDartGetter(n, context))) return null;
  // A type named directly reads its static getter (`Config.instance`); a
  // variable is typed by its declaration — a parameter or local in scope, else
  // a field of the class the read is written in (`final Box box;`).
  const typeName = /^[A-Z]/.test(receiver) &&
    context.getNodesByName(receiver).some((n) => n.language === 'dart' && DART_TYPE_KINDS.has(n.kind))
    ? receiver
    : inferLocalReceiverType(receiver, ref, context) ?? inferMemberReceiverType(receiver, ref, context);
  if (!typeName) return null;
  const found = dartMemberOf(typeName, member, ref, context, (n) => isDartGetter(n, context));
  if (!found) return null;
  return { original: ref, targetNodeId: found.node.id, confidence: 0.9, resolvedBy: 'instance-method', edgeKind: 'calls' };
}

/**
 * Whether a ref is a Dart annotation — `@riverpod`, `@Riverpod(keepAlive:
 * true)`, `@meta.immutable` — which the extractor records by its last name, at
 * the `@`.
 */
export function isDartAnnotation(ref: UnresolvedRef): boolean {
  return ref.language === 'dart' && ref.referenceKind === 'decorates';
}

/**
 * A Dart annotation is a constant expression: a `const` variable, or a call of
 * a `const` constructor. So it links, as it is written, a constant or (called)
 * a class its library can see, through the import prefix it is written with;
 * a static constant, an enum value or (called) a named constructor of the
 * type it is written through (`@Foo.value`, `@Foo.named(…)`); or, on a
 * member, a static constant of the type around it. Never a method, a
 * getter or a function: riverpod's 506 `@riverpod` annotations went to
 * riverpod_analyzer_utils' extension getter `riverpod`, not riverpod_annotation's
 * `const riverpod = Riverpod();`.
 */
export function matchDartAnnotation(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  const name = ref.referenceName;
  if (!context.getNodesByName(name).some((n) => n.language === 'dart')) return null;
  const written = dartAnnotationAt(ref, context);
  if (!written) return null;
  const { names, call } = written;
  let pool: Node[];
  let resolvedBy: ResolvedRef['resolvedBy'] = 'exact-match';
  if (names.length === 1 || (names.length === 2 && dartImportPrefixes(ref.filePath, context).has(names[0]!))) {
    const prefix = names.length === 2 ? names[0]! : null;
    const own = prefix === null && !call ? dartEnclosingStatic(name, ref, context) : null;
    if (own) return { original: ref, targetNodeId: own.id, confidence: 0.9, resolvedBy };
    pool = context.getNodesByName(name).filter((n) => isDartLibraryDecl(n) &&
      (call ? isDartAnnotationClass(n, context) : n.kind === 'constant') && isDartTopLevelVisible(n, ref, context, prefix));
    if (prefix === null) pool = preferOwnDartLibrary(pool, ref, context);
  } else if (names.length === 2 || (names.length === 3 && dartImportPrefixes(ref.filePath, context).has(names[0]!))) {
    const prefix = names.length === 3 ? names[0]! : null;
    let owners = context.getNodesByName(names[names.length - 2]!).filter((n) =>
      isDartLibraryDecl(n) && DART_TYPE_KINDS.has(n.kind) && isDartTopLevelVisible(n, ref, context, prefix));
    if (prefix === null) owners = preferOwnDartLibrary(owners, ref, context);
    pool = context.getNodesByName(name).filter((m) => m.language === 'dart' &&
      owners.some((o) => o.filePath === m.filePath && m.qualifiedName === `${o.qualifiedName}::${name}`) &&
      (call ? isDartConstructor(m, context) : m.kind === 'constant' || m.kind === 'enum_member'));
    resolvedBy = 'qualified-name';
  } else {
    return null;
  }
  if (pool.length <= 1) return pool[0] ? { original: ref, targetNodeId: pool[0].id, confidence: 0.9, resolvedBy } : null;
  // Libraries this cannot establish see every file's declarations.
  const best = findBestMatch(ref, pool, context);
  return best
    ? { original: ref, targetNodeId: best.id, confidence: computePathProximity(ref.filePath, best.filePath) >= 30 ? 0.7 : 0.4, resolvedBy }
    : null;
}

/** A class a Dart annotation can call a constructor of: not an extension, which has none. */
function isDartAnnotationClass(n: Node, context: ResolutionContext): boolean {
  return n.kind === 'class' && dartExtensionDecl(n, context) === null;
}

/**
 * The static constant or enum value `name` of the type a Dart annotation is
 * written in, which a member's annotation names bare. A class's own
 * annotations stand outside its body.
 */
function dartEnclosingStatic(name: string, ref: UnresolvedRef, context: ResolutionContext): Node | null {
  let own: Node | null = null;
  for (const n of context.getNodesInFile(ref.filePath)) {
    if (DART_TYPE_KINDS.has(n.kind) && n.id !== ref.fromNodeId && n.startLine <= ref.line && n.endLine >= ref.line &&
        (!own || n.startLine >= own.startLine)) own = n;
  }
  if (!own) return null;
  const qualifiedName = `${own.qualifiedName}::${name}`;
  return context.getNodesByName(name).find((m) => m.language === 'dart' && m.filePath === ref.filePath &&
    m.qualifiedName === qualifiedName && (m.kind === 'constant' || m.kind === 'enum_member')) ?? null;
}

/**
 * How a Dart annotation is written — the names of `@p.Foo.named(…)` up to the
 * one its ref records, and whether it is called — read from its `@`. The
 * extractor records the last name, or the one a type argument list follows
 * (`@Foo<int>.named(…)` is `Foo`'s).
 */
function dartAnnotationAt(ref: UnresolvedRef, context: ResolutionContext): { names: string[]; call: boolean } | null {
  const code = dartCodeOf(ref.filePath, context);
  const from = code?.lineStarts[ref.line - 1];
  if (!code || from === undefined) return null;
  const to = code.lineStarts[ref.line] ?? code.text.length;
  // On a line with non-ASCII text before it, the `@` whose names fit stands in.
  const ats = [from + ref.column];
  for (let k = code.text.indexOf('@', from); k >= 0 && k < to; k = code.text.indexOf('@', k + 1)) {
    if (k !== from + ref.column) ats.push(k);
  }
  for (const at of ats) {
    const read = code.text[at] === '@' ? readDartAnnotation(code.text, at + 1) : null;
    const end = read ? (read.typeArgsAt >= 0 ? read.typeArgsAt : read.names.length - 1) : -1;
    if (read && read.names[end] === ref.referenceName) return { names: read.names.slice(0, end + 1), call: read.call };
  }
  return null;
}

/** A Dart annotation's dotted names, which of them a type argument list follows, and whether `(` comes next on its line. */
function readDartAnnotation(text: string, i: number): { names: string[]; typeArgsAt: number; call: boolean } | null {
  const names: string[] = [];
  let typeArgsAt = -1;
  const identifier = /[ \t]*([A-Za-z_$][\w$]*)[ \t]*/y;
  while (names.length < 8) {
    identifier.lastIndex = i;
    const m = identifier.exec(text);
    if (!m) return null;
    names.push(m[1]!);
    i = identifier.lastIndex;
    if (text[i] === '<' && typeArgsAt < 0) {
      const close = dartTypeArgumentsEnd(text, i);
      if (close < 0) return null;
      typeArgsAt = names.length - 1;
      for (i = close + 1; text[i] === ' ' || text[i] === '\t'; i++);
    }
    if (text[i] !== '.') break;
    i++;
  }
  return { names, typeArgsAt, call: text[i] === '(' };
}

/**
 * A member an extension adds to `typeName` — `s.shout()` on an enum `Shape`
 * through `extension ShapeInfo on Shape` — when the type itself declares none
 * (#2338). An inherited instance member is left to the strategies that
 * resolve it today.
 */
function dartExtensionMemberOf(typeName: string, name: string, ref: UnresolvedRef, context: ResolutionContext): Node | null {
  const found = dartMemberOf(typeName, name, ref, context, () => true);
  return found?.viaExtension ? found.node : null;
}

/**
 * A Dart call through a type's name — `BlocProvider.value(…)`, riverpod's
 * `FutureProvider.autoDispose(…)` — is to one of that type's own constructors
 * or static members, or to nothing the project declares. Dart inherits none
 * of them, so a guess past the type is always wrong: flutter_bloc's
 * `BlocProvider.value(…)` went to `RepositoryProvider`'s `value` 89 times,
 * riverpod's `Family2Family._()` to the `EmptyFamily2Family._` declared above
 * it, and the SDK's `Uri.parse(…)`, past bloc_lint's `extension on Uri`, to a
 * project `parse`. A static constant's callee is the value it holds (`static
 * const autoDispose = AutoDisposeFutureProviderBuilder();`). The member is
 * found as a chain's static link finds it (dartStaticMember). Written through
 * an import prefix (`p.Box<int>.named(…)`, which arrives as `Box.named`), the
 * type is the one that import brings in, if any. Undefined when the receiver
 * names no Dart type of the project.
 */
function matchDartTypeMemberCall(
  typeName: string,
  member: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null | undefined {
  const types = context.getNodesByName(typeName).filter((n) => n.language === 'dart' && DART_TYPE_KINDS.has(n.kind));
  const prefix = types.length > 0 || /^[_$]*[A-Z]/.test(typeName) ? dartTypeCallPrefix(typeName, member, ref, context) : null;
  const isOwner = (n: Node): boolean => prefix === null || dartPrefixSees(ref.filePath, prefix, n.filePath, typeName, context);
  if (!types.some(isOwner)) return prefix === null ? undefined : null;
  const own = dartStaticMember(typeName, member, ref, context, isOwner);
  return own && own.kind !== 'enum_member'
    ? { original: ref, targetNodeId: own.id, confidence: 0.85, resolvedBy: 'qualified-name' } : null;
}

/**
 * How a bare Rust or Go name is written at its call: `path` after `::` (left
 * to the path strategies), `chained` after a `.` — with the receiver it is
 * written on, call and type arguments dropped — or `bare`. The extractors
 * keep one receiver level, so `sym.filename().map(From::from)` and
 * `child.Flags().String("f", …)` arrive as bare `map` / `String`.
 */
function rustGoCallShape(ref: UnresolvedRef, context: ResolutionContext): { shape: 'path' } | { shape: 'bare' } | { shape: 'chained'; receiver: string } | null {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split('\n');
  let line = lines?.[ref.line - 1];
  if (line === undefined) return null;
  const name = ref.referenceName;
  const at = new RegExp(`(?<![\\w$])${escapeRegExp(name)}\\s*(?:\\(|::<|!)`);
  let start = line.startsWith(name, ref.column) ? ref.column : -1;
  if (start < 0) {
    const m = at.exec(line);
    start = m ? m.index : -1;
  }
  // A link further down a chain the call's line starts — `bat()\n  .arg(…)\n  .stdout(…)` —
  // is recorded at the chain's first line.
  for (let next = ref.line; start < 0 && lines && next < Math.min(lines.length, ref.line + 20); next++) {
    const m = /^\s*\./.test(lines[next]!) ? at.exec(lines[next]!) : null;
    if (m) {
      // Named after the chain's head: `Command::new("true")` for its `.stdout(…)`.
      if (/^\s*\.\s*$/.test(lines[next]!.slice(0, m.index))) {
        return { shape: 'chained', receiver: rustGoReceiverName(line.trimEnd().replace(/[?;]+$/, '')) };
      }
      line = lines[next]!;
      start = m.index;
    }
  }
  if (start < 0) return null;
  const before = line.slice(0, start);
  if (/::\s*$/.test(before)) return { shape: 'path' };
  if (!/\.\s*$/.test(before)) return { shape: 'bare' };
  const receiver = before.replace(/\?\s*\.\s*$/, '');
  return { shape: 'chained', receiver: isTupleReceiver(receiver) ? '()' : rustGoReceiverName(receiver) };
}

/**
 * Whether a receiver's text ends in a tuple, `(self.ip(), self.port()).`: a
 * parenthesized list with a comma of its own, no callee or macro before it.
 */
function isTupleReceiver(text: string): boolean {
  const src = text.replace(/\s*\.\s*$/, '');
  if (!src.endsWith(')')) return false;
  let depth = 0;
  let comma = false;
  let i = src.length - 1;
  for (; i >= 0; i--) {
    const ch = src[i]!;
    if (ch === ')' || ch === ']' || ch === '}') depth++;
    else if (ch === '(' || ch === '[' || ch === '{') {
      if (--depth === 0) break;
    } else if (ch === ',' && depth === 1) comma = true;
  }
  return i >= 0 && comma && !/[\w$>\])!?]\s*$/.test(src.slice(0, i));
}

/**
 * The receiver a Rust / Go `….name(` is written on, as its path and dotted
 * identifiers with arguments dropped — `Command::new("x").short_flag('f')` →
 * `Command::new.short_flag`, a macro `arg!(…)` → `arg`, a Go composite
 * literal `(JSON{data})` → `JSON`. Read backwards to the expression's start.
 */
function rustGoReceiverName(text: string): string {
  let out = '';
  let i = text.replace(/\s*\.\s*$/, '').length - 1;
  const src = text.replace(/\s*\.\s*$/, '');
  while (i >= 0) {
    const ch = src[i]!;
    if (ch === ')' || ch === ']' || ch === '}') {
      const open = ch === ')' ? '(' : ch === ']' ? '[' : '{';
      let depth = 0;
      let j = i;
      for (; j >= 0; j--) {
        if (src[j] === ch) depth++;
        else if (src[j] === open && --depth === 0) break;
      }
      if (j < 0) return '';
      // `(JSON{data})` — a parenthesized composite literal names its type.
      if (ch === ')' && out === '') {
        const literal = /^\(\s*&?\s*([A-Za-z_][\w.]*)\s*\{/.exec(src.slice(j, i + 1));
        if (literal) return literal[1]!;
      }
      i = j - 1;
    } else if (/[\w$.:!]/.test(ch)) {
      if (ch !== '!') out = ch + out;
      i--;
    } else break;
  }
  return out.replace(/^[.:]+|[.:]+$/g, '');
}

/**
 * Whether a Rust / Go call of that shape can mean `n`. A bare call never
 * reaches a method (Rust needs `self.` / `Type::`, Go a receiver): axum's
 * routing `get(handler)` went to a cookie jar's `get`. A chained call reaches
 * a method of what its receiver is named after (or of `self`), never a free
 * function: tokio's `sym.filename().map(…)` went to `MutexGuard::map` 156
 * times, cobra's `c.Flags().String(…)` to a test type's `String`.
 */
function isRustGoCallTarget(n: Node, shape: ReturnType<typeof rustGoCallShape>): boolean {
  if (!shape || shape.shape === 'path') return true;
  const member = n.kind === 'method';
  if (shape.shape === 'bare') return !member;
  // A tuple's method is no named type's: serde's `(self.ip(),
  // self.port()).serialize(s)` went to the `impl Serialize for Path` below it.
  if (shape.receiver === '()') return false;
  if (!member) return n.kind !== 'function';
  // A name the standard library's own types all carry (`unwrap`, `clone`,
  // `iter`, Go's `String` / `Get`) needs a receiver named after the owner; a
  // project-specific one keeps its match — clap's `flag("n").short('n')` is
  // `Arg::short`, cobra's `c.Root().Name()` `Command::Name`.
  // Go's `w.Header().Get(…)` / `r.Header.Set(…)`: net/http's Header map.
  if (n.language === 'go' && /(?:^|\.)Header$/.test(shape.receiver) && /^(?:Get|Set|Add|Del|Values|Clone|Write)$/.test(n.name)) return false;
  const std = (n.language === 'go' ? GO_STD_METHODS : RUST_STD_METHODS).has(n.name);
  return !std || /^(?:self|Self)$/.test(shape.receiver) || (shape.receiver !== '' && sharesReceiverWord(shape.receiver, n));
}

/**
 * Kotlin's scope functions and standard collection / string / conversion
 * methods: on an untyped chain link (`builder.apply { … }`, `list.map { … }`)
 * they are the standard library's, never a project type's same-named member.
 * Names project types commonly carry (`get`, `write`, `close`, `add`) are left
 * out — okio's `sink.write(…)` is its own Buffer's.
 */
const KOTLIN_STD_METHODS: ReadonlySet<string> = new Set([
  'apply', 'also', 'let', 'run', 'takeIf', 'takeUnless', 'toString', 'equals', 'hashCode', 'map', 'mapNotNull',
  'mapIndexed', 'filter', 'filterNot', 'filterIsInstance', 'forEach', 'forEachIndexed', 'first', 'firstOrNull',
  'last', 'lastOrNull', 'single', 'singleOrNull', 'isEmpty', 'isNotEmpty', 'isNullOrEmpty', 'isNullOrBlank',
  'isBlank', 'isNotBlank', 'orEmpty', 'joinToString', 'toList', 'toMutableList', 'toSet', 'toMutableSet', 'toMap',
  'toTypedArray', 'any', 'all', 'none', 'count', 'sumOf', 'maxOf', 'minOf', 'maxOrNull', 'minOrNull', 'sortedBy',
  'sortedByDescending', 'sorted', 'sortedWith', 'reversed', 'drop', 'dropLast', 'take', 'takeLast', 'zip',
  'flatMap', 'flatten', 'distinct', 'groupBy', 'associate', 'associateBy', 'associateWith', 'partition',
  'contains', 'containsKey', 'getOrElse', 'getOrNull', 'getOrPut', 'getOrDefault', 'trim', 'trimEnd', 'trimStart',
  'split', 'substring', 'startsWith', 'endsWith', 'replace', 'lowercase', 'uppercase', 'toInt', 'toLong',
  'toDouble', 'toFloat', 'toIntOrNull', 'toLongOrNull', 'encodeToByteArray', 'decodeToString',
  'copyOf', 'copyOfRange', 'indexOf', 'lastIndexOf', 'withIndex', 'asSequence', 'asList', 'ifEmpty', 'ifBlank',
  'padStart', 'padEnd', 'repeat', 'lines', 'toCharArray', 'coerceAtLeast', 'coerceAtMost', 'coerceIn',
]);

/**
 * Methods of .NET's base types, collections, streams, strings, LINQ and
 * reflection — names a project type overrides or wraps, which a call through
 * an untyped receiver means only when the receiver is named after the owner.
 * Newtonsoft's `reader.Value.ToString()` went to its JValue's `ToString`,
 * `table.Columns.Add(…)` to a name table's `Add`.
 */
const CSHARP_STD_METHODS: ReadonlySet<string> = new Set([
  'ToString', 'Equals', 'GetHashCode', 'GetType', 'CompareTo', 'Add', 'AddRange', 'Remove', 'RemoveAt', 'RemoveAll',
  'Contains', 'ContainsKey', 'ContainsValue', 'Clear', 'Insert', 'IndexOf', 'CopyTo', 'ToArray', 'ToList',
  'ToDictionary', 'GetEnumerator', 'MoveNext', 'Reset', 'TryGetValue', 'GetValueOrDefault', 'TryAdd', 'Write',
  'WriteLine', 'WriteAsync', 'WriteLineAsync', 'Read', 'ReadAsync', 'ReadLine', 'ReadToEnd', 'Flush', 'FlushAsync',
  'Close', 'Dispose', 'DisposeAsync', 'Parse', 'TryParse', 'Format', 'Join', 'Split', 'Replace', 'Substring', 'Trim',
  'TrimStart', 'TrimEnd', 'StartsWith', 'EndsWith', 'ToUpper', 'ToLower', 'ToUpperInvariant', 'ToLowerInvariant',
  'Select', 'Where', 'First', 'FirstOrDefault', 'Single', 'SingleOrDefault', 'Last', 'LastOrDefault', 'Any', 'All',
  'Count', 'Sum', 'Max', 'Min', 'OrderBy', 'OrderByDescending', 'GroupBy', 'Skip', 'Take', 'Distinct', 'Concat',
  'Cast', 'OfType', 'Aggregate', 'Invoke', 'DynamicInvoke', 'GetMethod', 'GetProperty', 'GetField', 'GetConstructor',
  'GetCustomAttributes', 'GetGenericArguments', 'MakeGenericType', 'IsAssignableFrom', 'ConfigureAwait', 'Wait',
  'ContinueWith', 'Append', 'AppendLine', 'Peek', 'Push', 'Pop', 'Enqueue', 'Dequeue', 'HasFlag', 'Find', 'FindAll',
  'ForEach', 'Sort', 'Reverse', 'Clone', 'Seek', 'SetLength',
]);

/** The same .NET names as VB.NET writes them — in any case. */
const VBNET_STD_METHODS: ReadonlySet<string> = new Set([...CSHARP_STD_METHODS].map((m) => m.toLowerCase()));

/**
 * Python's dict / list / set / str / file / `re` methods. On an untyped
 * receiver (`options.setdefault(…)`, `d.copy()`) they are the builtin
 * type's, never a same-named project method the call happens to share a
 * file with.
 */
const PYTHON_STD_METHODS: ReadonlySet<string> = new Set([
  'get', 'setdefault', 'pop', 'popitem', 'update', 'items', 'keys', 'values', 'copy', 'clear',
  'append', 'extend', 'insert', 'remove', 'index', 'count', 'sort', 'reverse', 'add', 'discard',
  'union', 'intersection', 'difference', 'split', 'rsplit', 'join', 'strip', 'lstrip', 'rstrip',
  'replace', 'startswith', 'endswith', 'lower', 'upper', 'format', 'encode', 'decode', 'find',
  'rfind', 'splitlines', 'read', 'readline', 'readlines', 'write', 'writelines', 'close', 'seek',
  'flush', 'group', 'groups', 'match', 'search', 'sub', 'findall', 'fullmatch',
]);

/**
 * Scala's collection / Option / Future methods and the `java.*` calls Scala
 * code makes. On Play, ~2,500 `map` / `get` / `foreach` calls on untyped
 * values landed on unrelated project methods.
 */
const SCALA_STD_METHODS: ReadonlySet<string> = new Set([
  'map', 'flatMap', 'filter', 'filterNot', 'foreach', 'fold', 'foldLeft', 'foldRight', 'reduce',
  'collect', 'collectFirst', 'find', 'exists', 'forall', 'count', 'get', 'getOrElse', 'orElse',
  'orNull', 'isEmpty', 'nonEmpty', 'isDefined', 'contains', 'headOption', 'head', 'tail', 'last',
  'lastOption', 'take', 'drop', 'groupBy', 'sortBy', 'sorted', 'mkString', 'toList', 'toSeq',
  'toSet', 'toMap', 'toVector', 'toArray', 'zip', 'zipWithIndex', 'size', 'length', 'update',
  'updated', 'recover', 'recoverWith', 'transform', 'andThen', 'compose', 'onComplete', 'asScala',
  'asJava', 'getOrElseUpdate', 'put', 'remove', 'add', 'append', 'replace', 'split', 'trim',
  'startsWith', 'endsWith', 'format', 'equals', 'hashCode', 'toString', 'set', 'build', 'execute',
  'of', 'encode', 'decode', 'max', 'min',
]);

/**
 * `java.lang` / `java.util` / streams and the Android framework calls Java
 * code makes on values whose type the resolver cannot see — a lambda
 * parameter, a `var`, a call result, an inherited field. On Play ~1,100
 * test-map `put` calls landed on a test class's `RejectingMap::put`. Names
 * Java projects commonly declare themselves (`post`, `of`, `apply`, `run`,
 * `start`, `getId`) stay out.
 */
const JAVA_STD_METHODS: ReadonlySet<string> = new Set([
  'equals', 'hashCode', 'toString', 'getClass', 'compareTo',
  'get', 'put', 'add', 'remove', 'contains', 'containsKey', 'containsValue', 'size', 'isEmpty',
  'clear', 'iterator', 'hasNext', 'next', 'stream', 'forEach', 'keySet', 'values', 'entrySet',
  'addAll', 'removeAll', 'putAll', 'putIfAbsent', 'getOrDefault', 'computeIfAbsent', 'indexOf',
  'toArray', 'subList',
  'length', 'charAt', 'substring', 'trim', 'split', 'startsWith', 'endsWith', 'equalsIgnoreCase',
  'toLowerCase', 'toUpperCase', 'replace', 'format', 'valueOf',
  'map', 'filter', 'orElse', 'orElseGet', 'orElseThrow', 'ifPresent', 'isPresent', 'collect',
  'findFirst', 'anyMatch', 'allMatch',
  'postDelayed', 'removeCallbacks', 'obtainMessage', 'getResources', 'getSystemService',
  'findViewById', 'setVisibility', 'startActivity',
]);

/**
 * A request handler the web framework dispatches to: a Django / DRF / Flask
 * view's `get` / `post` / …, a controller's `index` / `store` / `update` /
 * `destroy`. Nothing calls one through an instance by name, so a guess from
 * a Django test's `client.post(…)` (allauth: 425 times on a
 * ClientRegistrationView) or an Eloquent `$page->update(…)` is never one.
 */
const DISPATCHED_OWNER = /(?:View|ViewSet|APIView|Controller|Endpoint|ViewMixin)$/;
const DISPATCHED_ACTIONS: ReadonlySet<string> = new Set([
  'get', 'post', 'put', 'patch', 'delete', 'head', 'options', 'index', 'show', 'store', 'update', 'destroy',
  'create', 'edit', 'list', 'retrieve', 'partial_update',
]);

/** A test double's name: Fake…, Mock…, Stub…, Dummy…, Spy…, …Fake, …Mock, …Stub. */
const TEST_DOUBLE_OWNER = /\b(?:fake|mock|mocked|stub|dummy|spy)\b/i;

/** A method of a test double (`MockedResponse`, `_FakeHTTPResponse`) the receiver and the calling file never name. */
function isUnnamedTestDouble(method: Node, receiver: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut <= 0) return false;
  const owner = method.qualifiedName.slice(0, cut).split(/::|\./).pop()!;
  if (!TEST_DOUBLE_OWNER.test(splitCamelCase(owner).join(' '))) return false;
  if (splitCamelCase(receiverLink(receiver)).some((w) => TEST_DOUBLE_OWNER.test(w))) return false;
  return !(context.readFile(ref.filePath) ?? '').includes(owner);
}

/**
 * The link of a dotted receiver its value is named after: the last, or for a
 * constant (`InitializationPhase.CONTROLLERS`, `Foo.INSTANCE`) the type it
 * belongs to.
 */
function receiverLink(receiver: string): string {
  const links = receiver.split('.');
  const last = links[links.length - 1]!;
  return links.length > 1 && /^[A-Z][A-Z0-9_]+$/.test(last) ? links[links.length - 2]! : last;
}

/** The standard-library method names of a language whose receiver-less guesses need the receiver to name the owner. */
function stdMethodNames(language: string): ReadonlySet<string> | null {
  switch (language) {
    case 'go': return GO_STD_METHODS;
    case 'rust': return RUST_STD_METHODS;
    case 'kotlin': return KOTLIN_STD_METHODS;
    case 'csharp': return CSHARP_STD_METHODS;
    case 'vbnet': return VBNET_STD_METHODS;
    case 'dart': return DART_STD_METHODS;
    case 'python': return PYTHON_STD_METHODS;
    case 'scala': return SCALA_STD_METHODS;
    case 'java': return JAVA_STD_METHODS;
    default: return null;
  }
}

/** Whether `name` is one of `language`'s standard-library method names (VB.NET's in any case). */
export function isStdMethodName(language: string, name: string): boolean {
  return stdMethodNames(language)?.has(language === 'vbnet' ? name.toLowerCase() : name) ?? false;
}

/** Methods of Dart's String, List, Iterable, Map and Set — names a project type rarely carries itself. */
const DART_STD_METHODS: ReadonlySet<string> = new Set([
  'endsWith', 'startsWith', 'contains', 'split', 'substring', 'trim', 'trimLeft', 'trimRight', 'toLowerCase',
  'toUpperCase', 'replaceAll', 'replaceFirst', 'replaceRange', 'indexOf', 'lastIndexOf', 'padLeft', 'padRight',
  'codeUnitAt', 'allMatches', 'firstMatch', 'hasMatch', 'addAll', 'removeAt', 'removeWhere', 'removeLast',
  'retainWhere', 'insertAll', 'where', 'whereType', 'forEach', 'toList', 'toSet', 'join', 'reduce', 'fold',
  'any', 'every', 'firstWhere', 'lastWhere', 'singleWhere', 'containsKey', 'containsValue', 'putIfAbsent',
  'sublist', 'take', 'takeWhile', 'skip', 'skipWhile', 'expand', 'cast', 'compareTo', 'elementAt', 'followedBy',
  'asMap', 'getRange', 'setAll', 'fillRange', 'shuffle', 'sort', 'indexWhere', 'lastIndexWhere',
]);

/**
 * Whether a receiver is named after the owner of `method` — for a Dart
 * extension, after the type it is `on`: getx's `ext.endsWith(".avi")` on a
 * String shares a word with `RxStringExt`, none with its `Rx<String>`. A Go
 * receiver must name the owner type itself, case and a trailing number
 * aside (`id` an `ID`, `urlsMap` a `URLsMap`): a shared word is what every
 * `err` has with an `…Err` type, every `ctx` with a `valCtx`.
 */
function receiverNamesOwner(receiver: string, method: Node, context: ResolutionContext): boolean {
  if (method.language === 'go') return namesOwnerType(receiver, method);
  if (method.language === 'dart') {
    const cut = method.qualifiedName.lastIndexOf('::');
    const owner = cut > 0 ? method.qualifiedName.slice(0, cut).split('::').pop()! : '';
    const decl = owner ? context.getNodesByName(owner).find((n) => n.language === 'dart' && n.filePath === method.filePath) : undefined;
    const line = decl ? (context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [])[decl.startLine - 1] ?? '' : '';
    const on = /\bextension\s+\w*\s*(?:<[^>]*>)?\s*on\s+([\w<>, ?]+?)\s*\{/.exec(line)?.[1];
    if (on) return sharesReceiverWord(receiver, { ...method, qualifiedName: `${on.replace(/[<>, ?]+/g, '')}::${method.name}` });
  }
  return sharesReceiverWord(receiver, method);
}

/**
 * The Dart `extension` declaration a class node stands for, read from its
 * head past the annotations the node starts with (riverpod's `@internal
 * extension ContainerReadElement on ProviderContainer`): `named` false for
 * `extension on X`.
 */
function dartExtensionDecl(n: Node, context: ResolutionContext): { named: boolean } | null {
  if (n.language !== 'dart' || n.kind !== 'class') return null;
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  const head = lines.slice(n.startLine - 1, Math.min(n.endLine, n.startLine + 5)).join('\n')
    .replace(/^\s*(?:(?:@[\w$.]+(?:\s*\((?:[^()]|\([^()]*\))*\))?|\/\/[^\n]*)\s*)*/, '');
  if (!/^extension\b(?!\s+type\b)/.test(head)) return null;
  // A generic one has no name either: riverpod's `extension<PointerT extends
  // _PointerBase, ProviderT extends ProviderOrFamily> on Map<…>` took the
  // `Map` type references of riverpod's own library.
  return { named: !/^extension\s*(?:<(?:[^<>]|<(?:[^<>]|<[^<>]*>)*>)*>)?\s*on\b/.test(head) };
}

/** Whether a Dart method belongs to an unnamed `extension on X`, visible only in its own library. */
function isDartUnnamedExtensionMember(method: Node, context: ResolutionContext): boolean {
  if (method.language !== 'dart' || method.kind !== 'method') return false;
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut <= 0) return false;
  const ownerQn = method.qualifiedName.slice(0, cut);
  const owner = context.getNodesInFile(method.filePath).find((n) => n.qualifiedName === ownerQn && n.kind === 'class' &&
    n.startLine <= method.startLine && n.endLine >= method.startLine);
  return owner !== undefined && dartExtensionDecl(owner, context)?.named === false;
}

const CSHARP_ALIASES = new WeakMap<ResolutionContext, Map<string, Map<string, string>>>();

/**
 * The type a C# file's `using Name = Some.Namespace.Type;` (or `global using`)
 * aliases `name` to, as its simple name — or null.
 */
function csharpUsingAlias(name: string, ref: UnresolvedRef, context: ResolutionContext): string | null {
  if (!/^[A-Za-z_]\w*$/.test(name)) return null;
  let memo = CSHARP_ALIASES.get(context);
  if (!memo) {
    memo = new Map();
    CSHARP_ALIASES.set(context, memo);
  }
  let aliases = memo.get(ref.filePath);
  if (!aliases) {
    aliases = new Map();
    const source = context.readFile(ref.filePath) ?? '';
    for (const m of source.matchAll(/^\s*(?:global\s+)?using\s+([A-Za-z_]\w*)\s*=\s*(?:global::)?([\w.]+)\s*(?:<[^;>]*>)?\s*;/gm)) {
      aliases.set(m[1]!, m[2]!.split('.').pop()!);
    }
    memo.set(ref.filePath, aliases);
  }
  return aliases.get(name) ?? null;
}

/** The receiver a Kotlin chain link `….name(` / `?.name {` is written on, or null for a call with none. */
function kotlinChainReceiver(ref: UnresolvedRef, context: ResolutionContext): string | null {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return null;
  const name = ref.referenceName;
  let start = line.startsWith(name, ref.column) ? ref.column : -1;
  if (start < 0) {
    const m = new RegExp(`(?<![\\w$])${escapeRegExp(name)}\\s*[({]`).exec(line);
    start = m ? m.index : -1;
  }
  if (start < 0) {
    // An infix call on an expression — `alias(libs.x) apply false` — whose
    // receiver the extractor could not name.
    const infix = new RegExp(`(?<=[\\w)\\]"'}]\\s+)${escapeRegExp(name)}\\s+(?=[^\\s=])`).exec(line);
    return infix ? rustGoReceiverName(line.slice(0, infix.index).trimEnd()) : null;
  }
  const before = line.slice(0, start);
  if (!/\.\s*$/.test(before)) return null;
  return rustGoReceiverName(before.replace(/\?\s*\.\s*$/, '').replace(/!!\s*$/, ''));
}

const KOTLIN_BITWISE_INFIX: ReadonlySet<string> = new Set(['and', 'or', 'xor', 'shl', 'shr', 'ushr', 'inv']);
const KOTLIN_NUMBER_TYPES: ReadonlySet<string> = new Set(['Byte', 'Short', 'Int', 'Long', 'UByte', 'UShort', 'UInt', 'ULong', 'Char']);

/**
 * A project's bitwise extension on a number type — okio's `infix fun
 * Byte.and(mask: Int)` — is indistinguishable, without the operand's type,
 * from the standard library's own `Int.and` / `Long.shr` members every other
 * `x and 0xff` / `h shr 8` calls; neither is a safe edge.
 */
function isKotlinNumberBitwise(n: Node, ref: UnresolvedRef): boolean {
  if (ref.language !== 'kotlin' || !KOTLIN_BITWISE_INFIX.has(n.name)) return false;
  const cut = n.qualifiedName.lastIndexOf('::');
  return cut > 0 && KOTLIN_NUMBER_TYPES.has(n.qualifiedName.slice(0, cut).split(/::|\./).pop()!);
}

/** Whether a bare Kotlin name is written with no receiver at its call — not a later link of a chain (`….name(`). */
function isReceiverLessKotlinCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return false;
  const name = ref.referenceName;
  let start = line.startsWith(name, ref.column) && !/[\w$]/.test(line[ref.column - 1] ?? '') ? ref.column : -1;
  if (start < 0) {
    const m = new RegExp(`(?<![\\w$])${escapeRegExp(name)}\\s*[({<]`).exec(line);
    start = m ? m.index : -1;
  }
  return start >= 0 && !/[.:]\s*$/.test(line.slice(0, start));
}

/**
 * Whether a bare `require(…)` / `check(…)` / `assert(…)` is Kotlin's
 * precondition: its condition is a comparison or boolean expression, or a
 * lazy message follows it.
 */
function isKotlinPreconditionCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!/^(?:require|check|assert)$/.test(ref.referenceName)) return false;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  const at = line ? new RegExp(`(?<![\\w.])${ref.referenceName}\\s*\\(`).exec(line) : null;
  if (!line || !at) return false;
  let depth = 0;
  let args = '';
  let rest = '';
  for (let i = at.index + at[0].length; i < line.length; i++) {
    const ch = line[i]!;
    if (ch === '(') depth++;
    else if (ch === ')' && depth-- === 0) {
      rest = line.slice(i + 1);
      break;
    }
    args += ch;
  }
  return /[<>=!]=|&&|\|\||(?:^|[\s(])!|\s[<>]\s|\bis\b|\bin\b|\btrue\b|\bfalse\b/.test(args) || /^\s*\{/.test(rest);
}

const KOTLIN_RECEIVER_TYPES = new WeakMap<ResolutionContext, Set<string>>();

/**
 * Every type a Kotlin function type in the project takes as its receiver —
 * `Module` in `typealias ModuleDeclaration = Module.() -> Unit`, `Scope` in
 * `Scope.(ParametersHolder) -> T`, `JdbcTransaction` in `statement:
 * JdbcTransaction.(TestDB) -> Unit`. A lambda of such a type runs with that
 * receiver, so a bare call inside one reaches its members.
 */
function kotlinReceiverTypes(context: ResolutionContext): Set<string> {
  const hit = KOTLIN_RECEIVER_TYPES.get(context);
  if (hit) return hit;
  const types = new Set<string>();
  const outside = new Set<string>();
  for (const file of context.getAllFiles()) {
    if (!/\.kts?$/.test(file)) continue;
    const source = stripCommentsForRegex(context.readFile(file) ?? '', 'java');
    for (const m of source.matchAll(/\b([A-Z]\w*)(?:<[^<>()]*(?:<[^<>()]*>[^<>()]*)*>)?\s*\.\s*\(/g)) types.add(m[1]!);
    // An extension on a type from outside the project (`fun
    // MacrobenchmarkScope.waitForContent()`, `fun StringBuilder.padInt(…)`)
    // is written to be called inside that library's lambdas.
    for (const m of source.matchAll(/\bfun\s+(?:<[^>]*>\s*)?([A-Z]\w*(?:\.[A-Z]\w*)*)(?:<[^<>()]*(?:<[^<>()]*>[^<>()]*)*>)?\??\.[A-Za-z_`][\w`]*\s*\(/g)) {
      for (const part of m[1]!.split('.')) outside.add(part);
    }
  }
  for (const name of outside) {
    if (!context.getNodesByName(name).some((n) => MEMBER_CLASS_KINDS.has(n.kind) && (n.language === 'kotlin' || n.language === 'java'))) types.add(name);
  }
  // A receiver's members include those it inherits: Exposed's `mergeFrom`
  // body runs on a MergeTableStatement, whose `whenMatchedDelete` is
  // MergeStatement's.
  const queue = [...types];
  while (queue.length > 0 && types.size < 5000) {
    const name = queue.shift()!;
    for (const decl of context.getNodesByName(name)) {
      if (decl.language !== 'kotlin' || !MEMBER_CLASS_KINDS.has(decl.kind)) continue;
      for (const sup of classHeadSupertypes(decl, context)) {
        if (!types.has(sup)) {
          types.add(sup);
          queue.push(sup);
        }
      }
    }
  }
  KOTLIN_RECEIVER_TYPES.set(context, types);
  return types;
}

/**
 * What the Android framework and AndroidX classes a Kotlin class commonly
 * extends inherit, so an extension on `ComponentCallbacks` or
 * `ComponentActivity` is in reach of an `AppCompatActivity` subclass.
 */
const KOTLIN_PLATFORM_SUPERS: Readonly<Record<string, readonly string[]>> = {
  AppCompatActivity: ['FragmentActivity'], FragmentActivity: ['ComponentActivity'],
  ComponentActivity: ['Activity', 'LifecycleOwner', 'ViewModelStoreOwner', 'SavedStateRegistryOwner'],
  Activity: ['ContextThemeWrapper', 'ComponentCallbacks2'], ContextThemeWrapper: ['ContextWrapper'],
  ContextWrapper: ['Context'], Application: ['ContextWrapper', 'ComponentCallbacks2'],
  Service: ['ContextWrapper', 'ComponentCallbacks2'], ComponentCallbacks2: ['ComponentCallbacks'],
  Fragment: ['ComponentCallbacks', 'LifecycleOwner', 'ViewModelStoreOwner', 'SavedStateRegistryOwner'],
  DialogFragment: ['Fragment'], AppCompatDialogFragment: ['DialogFragment'],
  BottomSheetDialogFragment: ['AppCompatDialogFragment'], AndroidViewModel: ['ViewModel'],
};

const KOTLIN_HIERARCHIES = new WeakMap<ResolutionContext, WeakMap<UnresolvedRef, Set<string>>>();

/**
 * The Kotlin types a bare call is written inside — the classes and objects
 * around it and the receiver of the extension function it is in — and what
 * they inherit.
 */
function kotlinHierarchyAt(ref: UnresolvedRef, context: ResolutionContext): Set<string> {
  let memo = KOTLIN_HIERARCHIES.get(context);
  if (!memo) {
    memo = new WeakMap();
    KOTLIN_HIERARCHIES.set(context, memo);
  }
  const hit = memo.get(ref);
  if (hit) return hit;
  const queue: string[] = [];
  for (const n of context.getNodesInFile(ref.filePath)) {
    if (n.startLine > ref.line || n.endLine < ref.line) continue;
    if (MEMBER_CLASS_KINDS.has(n.kind)) queue.push(n.name);
    // `fun Foo.bar() { baz() }`: Foo is the implicit receiver.
    else if ((n.kind === 'method' || n.kind === 'function') && n.qualifiedName.includes('::')) {
      queue.push(n.qualifiedName.slice(0, n.qualifiedName.lastIndexOf('::')).split(/::|\./).pop()!);
    }
  }
  // A Gradle build script runs on the Project (a settings script on Settings).
  if (ref.filePath.endsWith('.gradle.kts')) queue.push(/(?:^|\/)settings\.gradle\.kts$/.test(ref.filePath) ? 'Settings' : 'Project');
  // The same read from the source's braces, which also sees an anonymous
  // `object : Table("t") { … }` and survives a class the parser lost.
  for (const frame of kotlinBraceFrames(ref.filePath, context)) {
    if (frame.start <= ref.line && frame.end >= ref.line) queue.push(...frame.names);
  }
  const names = new Set<string>();
  while (queue.length > 0 && names.size < 60) {
    const name = queue.shift()!;
    if (names.has(name)) continue;
    names.add(name);
    queue.push(...(KOTLIN_PLATFORM_SUPERS[name] ?? []));
    for (const decl of context.getNodesByName(name)) {
      if (decl.language === 'kotlin' && MEMBER_CLASS_KINDS.has(decl.kind)) queue.push(...classHeadSupertypes(decl, context));
    }
  }
  memo.set(ref, names);
  return names;
}

const KOTLIN_FRAMES = new WeakMap<ResolutionContext, Map<string, Array<{ start: number; end: number; names: string[] }>>>();

/**
 * The type bodies of a Kotlin file by line range, read from its braces: each
 * `class` / `object` / `interface` body with its name and supertypes, an
 * anonymous `object : Base(…)` with its base, and an extension function's
 * body with its receiver type.
 */
function kotlinBraceFrames(file: string, context: ResolutionContext): Array<{ start: number; end: number; names: string[] }> {
  let memo = KOTLIN_FRAMES.get(context);
  if (!memo) {
    memo = new Map();
    KOTLIN_FRAMES.set(context, memo);
  }
  const hit = memo.get(file);
  if (hit) return hit;
  const frames: Array<{ start: number; end: number; names: string[] }> = [];
  const source = blankStringContents(stripCommentsForRegex(context.readFile(file) ?? '', 'java'));
  const stack: Array<{ start: number; names: string[] | null }> = [];
  let line = 1;
  let pending = '';
  for (const ch of source) {
    if (ch === '\n') line++;
    if (ch === '{') {
      // `with(x) {`, `x.apply {`, `x.run {`: a receiver of whatever type x is.
      const scoped = /(?:\bwith\s*\([^{}]*\)|\.\s*(?:apply|run)(?:\s*<[^<>]*>)?)\s*$/.test(pending);
      let names = scoped ? ['*'] : kotlinHeadNames(pending);
      // `single { get() }`: a lambda runs on the receiver its function's parameter type names.
      if (!scoped && (!names || names.length === 0)) {
        const call = /(?:^|[^\w$])([a-z_]\w*)\s*(?:<[^<>{}]*>)?\s*(?:\([^(){}]*\))?\s*$/.exec(pending)?.[1];
        const receiver = call && !KOTLIN_BLOCK_WORDS.has(call) ? kotlinLambdaReceiver(call, context) : null;
        if (receiver) names = [receiver];
      }
      stack.push({ start: line, names });
      pending = '';
    } else if (ch === '}') {
      const open = stack.pop();
      if (open?.names && open.names.length > 0) frames.push({ start: open.start, end: line, names: open.names });
      pending = '';
    } else if (ch === ';') pending = '';
    else if (pending.length < 600) pending += ch;
    else pending = pending.slice(300) + ch;
  }
  memo.set(file, frames);
  return frames;
}

/** Words before a `{` that open a block, not a lambda argument. */
const KOTLIN_BLOCK_WORDS: ReadonlySet<string> = new Set([
  'if', 'else', 'for', 'while', 'do', 'when', 'try', 'catch', 'finally', 'init', 'get', 'set', 'constructor',
  'fun', 'class', 'object', 'interface', 'return', 'by', 'lazy', 'apply', 'run', 'also', 'let', 'with', 'use',
]);

const KOTLIN_LAMBDA_RECEIVERS = new WeakMap<ResolutionContext, Map<string, string | null>>();

/**
 * The receiver a lambda passed to the project's `name` runs with: the type
 * before `.(` in its last parameter's function type, directly or through a
 * typealias — koin's `single(…, definition: Definition<T>)` with `typealias
 * Definition<T> = Scope.(ParametersHolder) -> T` runs its lambda on a Scope.
 * Null unless every `name` agrees.
 */
function kotlinLambdaReceiver(name: string, context: ResolutionContext): string | null {
  let memo = KOTLIN_LAMBDA_RECEIVERS.get(context);
  if (!memo) KOTLIN_LAMBDA_RECEIVERS.set(context, (memo = new Map()));
  if (memo.has(name)) return memo.get(name)!;
  const receiverOf = (type: string, depth: number): string | null => {
    const direct = /^\s*(?:suspend\s+)?([A-Z]\w*)(?:<[^<>]*(?:<[^<>]*>[^<>]*)*>)?\s*\.\s*\(/.exec(type);
    if (direct) return direct[1]!;
    const alias = /^\s*([A-Z]\w*)\b/.exec(type)?.[1];
    if (!alias || depth > 2) return null;
    for (const decl of context.getNodesByName(alias)) {
      if (decl.language !== 'kotlin' || decl.kind !== 'type_alias') continue;
      const text = (context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [])[decl.startLine - 1] ?? '';
      const rhs = /=\s*(.+)$/.exec(text)?.[1];
      if (rhs) return receiverOf(rhs, depth + 1);
    }
    return null;
  };
  const found = new Set<string>();
  for (const fn of context.getNodesByName(name)) {
    if (fn.language !== 'kotlin' || (fn.kind !== 'function' && fn.kind !== 'method')) continue;
    const lines = context.getFileLines?.(fn.filePath) ?? context.readFile(fn.filePath)?.split(/\r?\n/) ?? [];
    const head = lines.slice(fn.startLine - 1, fn.startLine + 11).join(' ');
    const open = head.search(new RegExp(`\\b${name}\\s*\\(`));
    if (open < 0) continue;
    let depth = 0;
    let end = -1;
    for (let i = head.indexOf('(', open); i < head.length; i++) {
      if (head[i] === '(') depth++;
      else if (head[i] === ')' && --depth === 0) { end = i; break; }
    }
    if (end < 0) continue;
    const params = splitCppTopLevel(head.slice(head.indexOf('(', open) + 1, end));
    const last = params[params.length - 1];
    const type = last ? /:\s*([\s\S]+?)(?:\s*=\s*[^=>][\s\S]*)?$/.exec(last.replace(/^\s*(?:noinline|crossinline)\s+/, ''))?.[1] : undefined;
    const receiver = type ? receiverOf(type, 0) : null;
    if (receiver) found.add(receiver);
  }
  const result = found.size === 1 ? [...found][0]! : null;
  memo.set(name, result);
  return result;
}

/** The type names a Kotlin block head introduces: a type declaration's name and supertypes, or an extension function's receiver. */
function kotlinHeadNames(head: string): string[] | null {
  let depth = 0;
  let flat = '';
  for (const ch of head) {
    if (ch === '<' || ch === '(') depth++;
    else if (ch === '>' || ch === ')') depth = Math.max(0, depth - 1);
    else if (depth === 0) flat += ch;
  }
  const decl = /\b(?:class|interface|object)\b(?:\s+([A-Za-z_]\w*))?([^=]*)$/.exec(flat);
  if (decl) {
    const supers = /:\s*([\s\S]*)$/.exec(decl[2] ?? '')?.[1] ?? '';
    const names = [...supers.replace(/\bwhere\b[\s\S]*$/, '').matchAll(/([A-Z]\w*)\s*(?=,|$|\bby\b)/g)].map((m) => m[1]!);
    return decl[1] ? [decl[1], ...names] : names;
  }
  const receiver = /\bfun\s+(?:<[^>]*>\s*)?([A-Z]\w*)(?:<[^>]*>)?\??\.[A-Za-z_]\w*\s*\(/.exec(head)?.[1];
  return receiver ? [receiver] : null;
}

/**
 * Whether a bare Kotlin call can reach method `n`: a member of a type around
 * the call or of what it inherits, or of a type the project's function types
 * take as a lambda receiver (a DSL). koin's `error("…")` — Kotlin's — went to
 * a Logger's `error`, and `module { … }` in one test to another test class's
 * private `module`.
 */
function isKotlinMemberReachable(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  // A Gradle script's bare calls — `plugins { }`, `dependencies { }`,
  // `api(projects.core)` — run on the build tool's own types: never a member
  // of a class the project declares (nowinandroid's `Graph.plugins()`, a lint
  // registry's `api` property). Build logic's extensions on Gradle's types
  // (`NamedDomainObjectContainer.createSourceSet(…)`) stay.
  if (ref.filePath.endsWith('.kts')) {
    if (n.kind !== 'method' && n.kind !== 'field' && n.kind !== 'property') return true;
    const cut = n.qualifiedName.lastIndexOf('::');
    const owner = cut > 0 ? n.qualifiedName.slice(0, cut).split(/::|\./).pop()! : '';
    return owner !== '' && !context.getNodesByName(owner).some((c) => isMethodOwnerKind(c) || c.kind === 'module');
  }
  // A Java class's method, too: Kotlin calls it bare only from a subclass or through a static import.
  if (n.kind !== 'method' || (n.language !== 'kotlin' && n.language !== 'java')) return true;
  // `require(n >= 0) { … }`, `check(!closed)`: Kotlin's preconditions, not a
  // member `require(byteCount: Long)` of the type around the call.
  if (isKotlinPreconditionCall(ref, context)) return false;
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut <= 0) return true;
  const path = n.qualifiedName.slice(0, cut).split(/::|\./);
  let owner = path.pop()!;
  const companion = owner === 'Companion' && path.length > 0;
  if (companion) owner = path.pop()!;
  // A (Java) constructor is the type's, called by its name.
  if (n.name === owner) return true;
  const hierarchy = kotlinHierarchyAt(ref, context);
  if (hierarchy.has('*') || kotlinReceiverTypes(context).has(owner) || hierarchy.has(owner)) return true;
  // `import okio.TestUtil.deepCopy` / `import okio.TestUtil.*` names an object's members.
  const pkg = kotlinFileScope(n.filePath, context).pkg;
  const objectPath = (pkg ? `${pkg}.${owner}` : owner) + (companion ? '.Companion' : '');
  const here = kotlinFileScope(ref.filePath, context);
  return here.imports.has(`${objectPath}.${n.name}`) || here.stars.has(objectPath);
}

/**
 * Of the members a bare Kotlin call can reach, the ones the code around it
 * reaches — its class, an extension's receiver, the lambda it is in — before
 * those only a lambda type somewhere in the project could: koin's `get()` in
 * `Scope.new(…)` is Scope's, not Koin's.
 */
function lexicalKotlinMembers(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  if (candidates.length < 2) return candidates;
  const hierarchy = kotlinHierarchyAt(ref, context);
  if (hierarchy.has('*')) return candidates;
  const lexical = candidates.filter((n) => {
    if (n.kind !== 'method') return false;
    // An object expression's override is not what a call of its own name in
    // it means — `original!!.contentLength()` in `override fun
    // contentLength()`, `this@Outer.onScroll(…)`, an extension receiver's
    // `onDataChanged(…)` — as when its overrides were local functions: the
    // scopes around it decide.
    if (n.id === ref.fromNodeId && isAnonymousMember(n)) return false;
    const path = n.qualifiedName.slice(0, Math.max(0, n.qualifiedName.lastIndexOf('::'))).split(/::|\./);
    let owner = path.pop() ?? '';
    if (owner === 'Companion') owner = path.pop() ?? '';
    return hierarchy.has(owner);
  });
  return lexical.length > 0 ? lexical : candidates;
}

/** Whether a standard-named Kotlin chain link can mean `n`: only through a receiver named after its owner. */
function isKotlinStdChainTarget(n: Node, receiver: string): boolean {
  if (n.kind !== 'method' && n.kind !== 'function') return true;
  return receiver === 'this' || (receiver !== '' && sharesReceiverWord(receiver, n));
}

/**
 * How a Swift call is written: `bare` (implicit self, or a free function),
 * through `self.` / `super.`, or `chained` on some other receiver. The
 * extractor keeps one receiver level, so `super.init(…)`,
 * `axis.entries.removeAll()` and `min(a, b)` all arrive as bare names.
 */
interface SwiftCallShape {
  shape: 'bare' | 'self' | 'super' | 'chained';
  /** A chained call's receiver, calls and subscripts dropped. */
  receiver: string;
  /** The first argument's label, if any. */
  label: string;
  /** `name[…]`: a subscript of a value, not a call. */
  subscript: boolean;
  /** `URLEncodedFormDecoder().decode(…)`: the type the link before the call constructs. */
  constructed?: string;
}

function swiftCallShape(ref: UnresolvedRef, context: ResolutionContext): SwiftCallShape | null {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return null;
  const name = ref.referenceName;
  let start = line.startsWith(name, ref.column) && !/[\w$]/.test(line[ref.column - 1] ?? '') ? ref.column : -1;
  if (start < 0) {
    const m = new RegExp(`(?<![\\w$])${escapeRegExp(name)}\\s*[({<[]`).exec(line);
    start = m ? m.index : -1;
  }
  if (start < 0) return null;
  const before = line.slice(0, start);
  const after = line.slice(start + name.length);
  const base = { receiver: '', label: '', subscript: /^\s*\[/.test(after) };
  if (!/\.\s*$/.test(before)) return { ...base, shape: 'bare' };
  // `self.m(` — not `self[i].m(` or `self.items.m(`, which are chains.
  const plain = /(?:^|[^\w$.)\]])(self|Self|super)\s*[?!]?\s*\.\s*$/.exec(before)?.[1];
  if (plain) return { ...base, shape: plain === 'super' ? 'super' : 'self' };
  return {
    ...base,
    shape: 'chained',
    receiver: rustGoReceiverName(before.replace(/[?!]\s*\./g, '.')),
    label: /^\s*\(\s*([A-Za-z_]\w*)\s*:(?!:)/.exec(after)?.[1] ?? '',
    constructed: /(?<![\w$.])([A-Z][\w$]*)\s*(?:<[^<>()]*>)?\s*\([^()]*\)\s*[?!]?\s*\.\s*$/.exec(before)?.[1],
  };
}

/** Argument labels the standard library's collection and string methods take. */
const SWIFT_STD_LABELS: ReadonlySet<string> = new Set([
  'contentsOf', 'where', 'by', 'at', 'keepingCapacity', 'separator', 'forKey', 'of', 'into', 'in', 'options',
  'maxSplits', 'omittingEmptySubsequences', 'with', 'after', 'before', 'upTo', 'through', 'offsetBy', 'default',
]);

/**
 * Whether a Swift method's declaration takes the argument label a call gives
 * first (`func contains(jpeg marker: JPEGMarker)` for `data.kf.contains(jpeg:
 * .SOF2)`). Labels are part of a Swift method's name, so one the standard
 * library's namesakes never take identifies the project's.
 */
function swiftDeclaresLabel(n: Node, label: string, context: ResolutionContext): boolean {
  if (label === '' || SWIFT_STD_LABELS.has(label)) return false;
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  const head = lines.slice(n.startLine - 1, n.startLine + 3).join(' ');
  return new RegExp(`\\bfunc\\s+${escapeRegExp(n.name)}\\s*(?:<[^>]*>)?\\s*\\(\\s*${escapeRegExp(label)}\\b`).test(head);
}

/**
 * What the standard library's collection types and protocols refine, so a
 * project extension of `Collection` is in reach of a type that conforms to
 * `RandomAccessCollection`. UIKit / AppKit ancestry comes from the
 * Objective-C table.
 */
const SWIFT_STD_SUPERS: Readonly<Record<string, readonly string[]>> = {
  RandomAccessCollection: ['BidirectionalCollection'], BidirectionalCollection: ['Collection'],
  MutableCollection: ['Collection'], RangeReplaceableCollection: ['Collection'], Collection: ['Sequence'],
  LazySequenceProtocol: ['Sequence'], LazyCollectionProtocol: ['Collection', 'LazySequenceProtocol'],
  StringProtocol: ['BidirectionalCollection'],
  Array: ['RandomAccessCollection', 'MutableCollection', 'RangeReplaceableCollection'],
  ArraySlice: ['RandomAccessCollection', 'MutableCollection', 'RangeReplaceableCollection'],
  ContiguousArray: ['RandomAccessCollection', 'MutableCollection', 'RangeReplaceableCollection'],
  String: ['StringProtocol', 'RangeReplaceableCollection'], Substring: ['StringProtocol', 'RangeReplaceableCollection'],
  Dictionary: ['Collection'], Set: ['Collection', 'SetAlgebra'], Range: ['RandomAccessCollection'],
  ClosedRange: ['RandomAccessCollection'],
};

/** Swift declarations a member hangs off: types, protocols, and extensions (extracted as classes). */
const SWIFT_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'struct', 'enum', 'interface']);
const SWIFT_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'property', 'field', 'enum_member']);
const SWIFT_DECLS = new WeakMap<ResolutionContext, Map<string, { supers: string[]; projectType: boolean }>>();
const SWIFT_HIERARCHIES = new WeakMap<ResolutionContext, WeakMap<UnresolvedRef, Map<string, number>>>();

/**
 * What the project declares a Swift type as: the supertypes and protocols
 * every declaration and extension of it names, and whether any of them is
 * the type itself rather than an extension of an outside one
 * (`extension Sequence`).
 */
function swiftDeclOf(typeName: string, context: ResolutionContext): { supers: string[]; projectType: boolean } {
  let memo = SWIFT_DECLS.get(context);
  if (!memo) {
    memo = new Map();
    SWIFT_DECLS.set(context, memo);
  }
  const hit = memo.get(typeName);
  if (hit) return hit;
  const system = OBJC_SYSTEM_SUPERS[typeName];
  const info = { supers: [...(SWIFT_STD_SUPERS[typeName] ?? (system ? [system] : []))], projectType: false };
  for (const decl of context.getNodesByName(typeName)) {
    if (decl.language !== 'swift' || !SWIFT_TYPE_KINDS.has(decl.kind)) continue;
    const head = swiftHeadOf(decl, context);
    info.supers.push(...head.supers);
    if (!head.extension) info.projectType = true;
  }
  memo.set(typeName, info);
  return info;
}

/**
 * A Swift declaration's head, read up to its body with comments, attribute
 * arguments and generic parameters dropped: `@objc(ChartViewBase) open class
 * ChartViewBase<T>: NSUIView, ChartDataProvider where T: Equatable {` →
 * NSUIView, ChartDataProvider.
 */
function swiftHeadOf(decl: Node, context: ResolutionContext): { supers: string[]; extension: boolean } {
  const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
  const text = lines
    .slice(decl.startLine - 1, Math.min(decl.endLine, decl.startLine + 20))
    .join('\n')
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    .replace(/\/\/[^\n]*/g, ' ');
  let depth = 0;
  let flat = '';
  for (const ch of text) {
    if (ch === '<' || ch === '(') depth++;
    else if (ch === '>' || ch === ')') depth = Math.max(0, depth - 1);
    else if (depth === 0) {
      if (ch === '{') break;
      flat += ch;
    }
  }
  const head = /\b(class|struct|enum|protocol|extension|actor)\s+[\w.]+\s*([\s\S]*)$/.exec(flat);
  if (!head) return { supers: [], extension: false };
  const clause = /^:([\s\S]*?)(?:\bwhere\b|$)/.exec(head[2]!.trim())?.[1] ?? '';
  return {
    supers: clause.split(',').map((item) => /([A-Za-z_]\w*)\s*$/.exec(item.trim())?.[1]).filter((w): w is string => !!w),
    extension: head[1] === 'extension',
  };
}

/** The Swift types around a call (depth 0) and what they inherit or conform to, by distance. */
function swiftHierarchyAt(ref: UnresolvedRef, context: ResolutionContext): Map<string, number> {
  let memo = SWIFT_HIERARCHIES.get(context);
  if (!memo) {
    memo = new WeakMap();
    SWIFT_HIERARCHIES.set(context, memo);
  }
  const hit = memo.get(ref);
  if (hit) return hit;
  const depths = new Map<string, number>();
  const queue: Array<[string, number]> = context
    .getNodesInFile(ref.filePath)
    .filter((n) => SWIFT_TYPE_KINDS.has(n.kind) && n.startLine <= ref.line && n.endLine >= ref.line)
    .map((n) => [n.name.split('.').pop()!, 0]);
  while (queue.length > 0 && depths.size < 40) {
    const [name, depth] = queue.shift()!;
    if (depths.has(name)) continue;
    depths.set(name, depth);
    for (const sup of swiftDeclOf(name, context).supers) queue.push([sup, depth + 1]);
  }
  memo.set(ref, depths);
  return depths;
}

/** A Swift type and every supertype and protocol the project says it has. */
function swiftTypeClosure(typeName: string, context: ResolutionContext): Set<string> {
  const seen = new Set<string>();
  const queue = [typeName];
  while (queue.length > 0 && seen.size < 40) {
    const name = queue.shift()!;
    if (seen.has(name)) continue;
    seen.add(name);
    queue.push(...swiftDeclOf(name, context).supers);
  }
  return seen;
}

/**
 * Of the in-scope members a bare / `self.` / `super.` Swift call could mean,
 * the nearest: the type's own, else its superclass's — Alamofire's
 * `self.cancel()` in a DownloadRequest extension is DownloadRequest's
 * override, not Request's.
 */
function nearestSwiftMembers(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  const hierarchy = swiftHierarchyAt(ref, context);
  const depthOf = (n: Node): number | undefined => {
    if (!SWIFT_MEMBER_KINDS.has(n.kind) && n.kind !== 'constant' && n.kind !== 'variable') return undefined;
    const cut = n.qualifiedName.lastIndexOf('::');
    return cut > 0 ? hierarchy.get(n.qualifiedName.slice(0, cut).split(/::|\./).pop()!) : undefined;
  };
  const depths = candidates.map(depthOf).filter((d): d is number => d !== undefined);
  if (depths.length < 2) return candidates;
  const nearest = Math.min(...depths);
  return candidates.filter((n) => {
    const d = depthOf(n);
    return d === undefined || d === nearest;
  });
}

/**
 * Methods of Swift's standard collections, strings and optionals and of
 * Foundation / UIKit views — names a project type rarely carries itself.
 * Ones it often does (`cancel`, `resume`, `store`, `validate`, `load`) are
 * left out: Alamofire's `request.resume()`, Kingfisher's `cache.store(…)`.
 */
const SWIFT_STD_METHODS: ReadonlySet<string> = new Set([
  'append', 'insert', 'remove', 'removeAll', 'removeFirst', 'removeLast', 'removeValue', 'contains', 'map',
  'compactMap', 'flatMap', 'filter', 'reduce', 'forEach', 'sorted', 'sort', 'first', 'last', 'min', 'max',
  'firstIndex', 'lastIndex', 'index', 'enumerated', 'reversed', 'joined', 'split', 'prefix', 'suffix',
  'dropFirst', 'dropLast', 'allSatisfy', 'randomElement', 'shuffled', 'popLast', 'replaceSubrange',
  'replacingOccurrences', 'components', 'trimmingCharacters', 'hasPrefix', 'hasSuffix', 'lowercased',
  'uppercased', 'appending', 'updateValue', 'merge', 'merging', 'union', 'intersection', 'subtracting',
  'formUnion', 'isEqual', 'addSubview', 'removeFromSuperview', 'setNeedsDisplay', 'setNeedsLayout',
  'layoutIfNeeded', 'addGestureRecognizer', 'addTarget', 'addObserver', 'removeObserver', 'eraseToAnyPublisher',
]);

/**
 * Whether a Swift file's declarations are visible from another file as far as
 * separate modules go: one under a `…Tests` directory (SwiftPM's
 * `Tests/VaporTests`, Xcode's `KingfisherTests`) or in a playground only from
 * inside it.
 */
function isSwiftTargetVisible(declFile: string, fromFile: string): boolean {
  const segments = declFile.split('/').slice(0, -1);
  const target = segments.findIndex((seg) => /Tests$|\.playground$/.test(seg));
  if (target < 0) return true;
  const prefix = segments.slice(0, target + 1).join('/') + '/';
  return fromFile.startsWith(prefix);
}

/**
 * Whether a Swift call of that shape can mean `n`. A member reached with no
 * receiver or through `self.` belongs to a type around the call or to what
 * it inherits or conforms to — `super.` to the latter only; top-level code
 * has no implicit self. Charts' `min(a, b)` went to a range type's `min`
 * field, `super.init(…)` to an Objective-C demo's `init` 170 times. A member
 * reached down a longer chain keeps its match unless its name is one the
 * standard types all carry: `axis.entries.removeAll()` is the array's, not
 * a chart data class's (unless the receiver names the owner, or the owner
 * is an outside type the project only extends).
 */
function isSwiftCallTarget(n: Node, shape: SwiftCallShape | null, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!shape) return true;
  // A global `let` / `var` from another file is subscripted, not called —
  // Charts' `min(a, b)` went to a playground page's `let min = 20.0`.
  if ((n.kind === 'constant' || n.kind === 'variable') && n.filePath !== ref.filePath && !shape.subscript) return false;
  // A test target imports the module it tests, never the reverse.
  if (!isSwiftTargetVisible(n.filePath, ref.filePath)) return false;
  const cut = n.qualifiedName.lastIndexOf('::');
  const owner = cut > 0 ? n.qualifiedName.slice(0, cut).split(/::|\./).pop()! : null;
  if (!SWIFT_MEMBER_KINDS.has(n.kind) && !(owner !== null && (n.kind === 'constant' || n.kind === 'variable'))) {
    if (n.kind !== 'function') return true;
    return shape.shape === 'bare' || owner !== null || (shape.shape === 'chained' && /^[A-Z]/.test(shape.receiver));
  }
  if (owner === null) return true;
  if (shape.shape === 'chained') {
    // A member of what the link before constructs, or of what that inherits:
    // vapor's `URLEncodedFormDecoder().decode(…)` is not a request's private
    // `_URLQueryContainer.decode`, `JSONDecoder().decode(…)` no project type's.
    // (A capitalized C function — realm's `RLMObjectBaseObjectSchema(obj)!` — constructs nothing.)
    if (shape.constructed && !context.getNodesByName(shape.constructed).some((f) => f.kind === 'function')) {
      return swiftTypeClosure(shape.constructed, context).has(owner);
    }
    // A property the type around the call declares with a type — Kingfisher's
    // `var cache: ImageCache!` — is that type: `cache.imageCachedType(…)` is
    // ImageCache's, not a test subclass's override.
    const typed = /^(?:self\.)?[A-Za-z_]\w*$/.test(shape.receiver) ? inferMemberReceiverType(shape.receiver, ref, context) : null;
    if (typed && /^[A-Z]/.test(typed)) return swiftTypeClosure(typed, context).has(owner);
    if (shape.receiver === '' || !SWIFT_STD_METHODS.has(n.name)) return true;
    return sharesReceiverWord(shape.receiver.split('.').pop()!, n) || !swiftDeclOf(owner, context).projectType ||
      swiftDeclaresLabel(n, shape.label, context);
  }
  const depth = swiftHierarchyAt(ref, context).get(owner);
  return depth !== undefined && (shape.shape !== 'super' || depth > 0);
}

/**
 * Methods of Rust's Option / Result / iterators / collections / strings /
 * smart pointers — names a project type rarely carries itself. Ones it often
 * does (`get`, `set`, `insert`, `next`, `call`, `read`) are left out: serde's
 * `Attr::set`, clap's own `get`.
 */
const RUST_STD_METHODS: ReadonlySet<string> = new Set([
  'unwrap', 'unwrap_or', 'unwrap_or_else', 'unwrap_or_default', 'unwrap_err', 'unwrap_unchecked', 'expect',
  'expect_err', 'ok', 'err', 'map', 'map_err', 'map_or', 'map_or_else', 'and_then', 'or_else', 'ok_or',
  'ok_or_else', 'is_some', 'is_none', 'is_ok', 'is_err', 'is_some_and', 'as_ref', 'as_mut', 'as_deref', 'clone',
  'cloned', 'copied', 'iter', 'iter_mut', 'into_iter', 'collect', 'enumerate', 'zip', 'rev', 'chain', 'skip',
  'step_by', 'peekable', 'flat_map', 'filter_map', 'flatten', 'any', 'all', 'len', 'is_empty', 'push', 'push_str',
  'pop', 'extend', 'drain', 'clear', 'retain', 'truncate', 'reserve', 'with_capacity', 'capacity', 'sort',
  'sort_by', 'sort_by_key', 'dedup', 'split_off', 'contains_key', 'to_string', 'to_owned', 'to_vec', 'as_str',
  'as_bytes', 'as_slice', 'as_ptr', 'into', 'try_into', 'borrow', 'borrow_mut', 'deref', 'deref_mut', 'chars',
  'bytes', 'lines', 'starts_with', 'ends_with', 'trim', 'to_lowercase', 'to_uppercase', 'windows', 'chunks',
  'then', 'then_some', 'eq', 'cmp', 'partial_cmp', 'read_to_end', 'read_to_string', 'fetch_add', 'fetch_sub',
  // std::process::Command's pipes and the assert_cmd assertions tests chain
  // onto it (not `arg` / `env`, which clap's own builders carry)
  'current_dir', 'stdout', 'stderr', 'stdin', 'success', 'failure',
]);

/**
 * Methods of Go's standard types and interfaces — `fmt.Stringer`, `error`,
 * `http.ResponseWriter`, `sync` locks, `reflect`, `time`. Ones a project type
 * often carries itself (`Get`, `Set`, `Close`, `Value`, `Next`) are left out:
 * gin's `c.Set(…)` is its Context's.
 */
const GO_STD_METHODS: ReadonlySet<string> = new Set([
  'String', 'Error', 'Unwrap', 'Is', 'As', 'Header', 'WriteHeader', 'WriteString', 'Lock', 'Unlock', 'RLock',
  'RUnlock', 'Err', 'Deadline', 'Int', 'Bool', 'Float64', 'Int64', 'Uint64', 'Bytes', 'Len', 'Cap', 'Seconds',
  'Unix', 'Before', 'After', 'Equal', 'IsNil', 'IsValid', 'Elem', 'NumField', 'Interface', 'Kind',
]);

const SCALA_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'trait', 'interface', 'enum', 'struct', 'module', 'namespace']);
const SCALA_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'field', 'property', 'variable', 'constant']);
const SCALA_SUPERS = new WeakMap<ResolutionContext, Map<string, string[]>>();
const SCALA_IMPORTS = new WeakMap<ResolutionContext, Map<string, { owners: Set<string>; members: Set<string>; values: Set<string> }>>();

/**
 * Whether a bare Scala name can mean the member `n`, read at its site. Three
 * shapes:
 * - a later link of a chain (`fa.iterator.map(f)` — the extractor keeps one
 *   receiver level, the line still shows the dot): the receiver must be named
 *   after `n`'s owner (`Foo.bar` on object Foo). cats's chained `.map(…)` went
 *   to a lazy-list ops class's `map` 186 times;
 * - a name the enclosing definition binds — a parameter `f: A => B`, a
 *   `val` — is that local: `f(true)` is not a case class's field `f` (396);
 * - otherwise a member of the types around it or their `extends` / `with`
 *   supertypes, of a companion, of the same file, or of an object the file
 *   imports (`import Foo._`, `import Foo.{bar}`).
 */
function isScalaMemberInScope(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return true;
  const name = ref.referenceName;
  const at = new RegExp(`(?<![\\w$])${escapeRegExp(name)}\\b`).exec(line);
  if (!at) return true;
  const before = line.slice(0, at.index);
  if (/\.\s*$/.test(before)) {
    // A later link of a chain: a member of what the receiver is named after,
    // never a package object's function — unless it is an `extension` method.
    if (n.filePath === ref.filePath) return true;
    // A type or object as a chain link (`pkg.Obj(…)`) is named by what holds it:
    // cats' `arbitrary[Int].map { … }` is no call of alleycats' `object map`.
    if (SCALA_TYPE_KINDS.has(n.kind)) {
      // Scala qualified names leave the package out: a top-level type's holder is its file's package.
      const outer = n.qualifiedName.split('::').slice(-2, -1)[0];
      const holder = outer !== undefined ? outer.split('.').pop()!
        : [...(context.readFile(n.filePath) ?? '').matchAll(/^\s*package\s+([\w.]+)\s*$/gm)].pop()?.[1]?.split('.').pop() ?? '';
      return holder !== '' && scalaReceiverName(before).split('.').pop() === holder;
    }
    if (!SCALA_MEMBER_KINDS.has(n.kind)) return n.kind !== 'function' || isScalaExtensionMethod(n, context);
    const receiver = scalaReceiverName(before);
    return receiver !== '' && sharesReceiverWord(receiver, n);
  }
  const local = scalaLocalBinder(name, ref, context);
  if (local) return n.filePath === ref.filePath && n.startLine >= local.startLine && n.endLine <= local.endLine;
  if (!SCALA_MEMBER_KINDS.has(n.kind)) return true;
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut < 0 || n.filePath === ref.filePath) return true;
  const owner = n.qualifiedName.slice(0, cut).split('::').pop()!;
  const imports = scalaImportsOf(ref.filePath, context);
  if (imports.owners.has(owner) || imports.members.has(`${owner}.${name}`)) return true;
  // `import builder._` brings in a VALUE's members, of a type the file doesn't say.
  if (imports.values.size > 0) return true;
  // An imported object's inherited members: `import sttp.client4._` is
  // `package object client4 extends SttpApi`, so `multipart(…)` is SttpApi's.
  if (scalaImportedSupertypes(ref.filePath, imports, context).has(owner)) return true;
  const around = context
    .getNodesInFile(ref.filePath)
    .filter((t) => SCALA_TYPE_KINDS.has(t.kind) && t.startLine <= ref.line && t.endLine >= ref.line);
  if (around.length === 0) return true;
  const seen = new Set<string>();
  const queue = [...around.map((t) => t.name), ...scalaAnonymousBases(ref, context)];
  while (queue.length > 0 && seen.size < 60) {
    const typeName = queue.shift()!;
    if (seen.has(typeName)) continue;
    seen.add(typeName);
    if (typeName === owner) return true;
    queue.push(...scalaSupertypesOf(typeName, context));
  }
  return false;
}

/**
 * The types an anonymous class around a Scala site instantiates — `new
 * scopt.OptionParser[Config]("scopt") { head("scopt") }` puts OptionParser's
 * members in scope. Read backwards over the open braces above the site.
 */
function scalaAnonymousBases(ref: UnresolvedRef, context: ResolutionContext): string[] {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split('\n') ?? [];
  const bases: string[] = [];
  let depth = 0;
  for (let i = ref.line - 1; i >= 0 && i >= ref.line - 400; i--) {
    const text = lines[i]!;
    for (let c = text.length - 1; c >= 0; c--) {
      if (text[c] === '}') depth++;
      else if (text[c] === '{') {
        if (depth > 0) { depth--; continue; }
        const head = /\bnew\s+([\w.]+(?:\s*\[[^\]]*\])?(?:\s*\([^)]*\))?(?:\s+with\s+[\w.]+(?:\s*\[[^\]]*\])?)*)\s*$/.exec(text.slice(0, c));
        if (head) for (const m of head[1]!.replace(/\[[^\]]*\]|\([^)]*\)/g, '').split(/\s+with\s+/)) bases.push(m.trim().split('.').pop()!);
      }
    }
  }
  return bases;
}

/**
 * The receiver a Scala `….name` is written on, as its dotted identifiers with
 * call and type arguments dropped: `proc("bash").call()` → `proc`,
 * `Alternative[List].unite` → `Alternative`, `checker.value.onWrite` →
 * `checker.value`. Read backwards to the expression's start.
 */
function scalaReceiverName(before: string): string {
  const text = before.replace(/\s*\.\s*$/, '');
  let out = '';
  let i = text.length - 1;
  while (i >= 0) {
    const ch = text[i]!;
    if (ch === ')' || ch === ']') {
      const open = ch === ')' ? '(' : '[';
      let depth = 0;
      for (; i >= 0; i--) {
        if (text[i] === ch) depth++;
        else if (text[i] === open && --depth === 0) break;
      }
      if (i < 0) return '';
      i--;
    } else if (/[\w$.]/.test(ch)) {
      out = ch + out;
      i--;
    } else break;
  }
  return out.replace(/^\.+|\.+$/g, '');
}

/** Whether a Scala function is declared in an `extension (…)` block. */
function isScalaExtensionMethod(n: Node, context: ResolutionContext): boolean {
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split('\n') ?? [];
  return lines.slice(Math.max(0, n.startLine - 4), n.startLine).some((l) => /^\s*extension\b/.test(l));
}

/**
 * The definition around a Scala site that binds `name` itself — a parameter, a
 * `val` / `var` / `def`, a lambda or `for` parameter — or null.
 */
function scalaLocalBinder(name: string, ref: UnresolvedRef, context: ResolutionContext): Node | null {
  const nodes = context.getNodesInFile(ref.filePath);
  const innermost = (kinds: ReadonlySet<string>) => nodes
    .filter((f) => kinds.has(f.kind) && f.startLine <= ref.line && f.endLine >= ref.line)
    .sort((a, b) => (a.endLine - a.startLine) - (b.endLine - b.startLine))[0];
  const fn = innermost(SCALA_FUNCTION_KINDS);
  // A test suite's body runs in its class: `test("…") { forAll { (e: E, f: A => B) => f(1) } }`.
  const scope = fn ?? innermost(SCALA_TYPE_KINDS);
  if (!scope) return null;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split('\n') ?? [];
  const text = lines.slice(scope.startLine - 1, ref.line).join('\n');
  const n = escapeRegExp(name);
  const binder = new RegExp(`(?:[(,\\[]\\s*(?:implicit\\s+|using\\s+)?${n}\\s*:)|(?:\\b(?:val|var|def|lazy\\s+val)\\s+${n}\\b)|(?:(?<![\\w$.])${n}\\s*(?:=>|<-))|(?:\\(\\s*${n}\\s*(?:,[^)]*)?\\)\\s*=>)`, 'g');
  if (fn) return binder.test(text) ? fn : null;
  // In a class body, a binder counts only inside a block still open at the site —
  // not a sibling test's `val f`, not the class's own members at its body's depth.
  const blockAt: number[] = new Array(text.length);
  const open: number[] = [];
  let next = 0;
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '{') { open.push(++next); depth++; }
    else if (ch === '}') { open.pop(); depth--; }
    blockAt[i] = open.length > 1 ? open[open.length - 1]! : 0;
  }
  const live = new Set(open.slice(1));
  for (const m of text.matchAll(binder)) {
    const block = blockAt[m.index!] ?? 0;
    if (block !== 0 && live.has(block)) return scope;
  }
  return null;
}

const SCALA_FUNCTION_KINDS: ReadonlySet<string> = new Set(['method', 'function']);

/** The simple names a Scala type's declarations extend or mix in. */
function scalaSupertypesOf(typeName: string, context: ResolutionContext): string[] {
  let memo = SCALA_SUPERS.get(context);
  if (!memo) SCALA_SUPERS.set(context, (memo = new Map()));
  const hit = memo.get(typeName);
  if (hit) return hit;
  const names: string[] = [typeName];
  for (const decl of context.getNodesByName(typeName)) {
    if (decl.language !== 'scala' || !SCALA_TYPE_KINDS.has(decl.kind)) continue;
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    const text = lines.slice(decl.startLine - 1, decl.startLine + 12).join(' ');
    let depth = 0;
    let flat = '';
    for (const ch of text) {
      if (ch === '[' || ch === '(') depth++;
      else if (ch === ']' || ch === ')') depth = Math.max(0, depth - 1);
      else if (depth === 0) {
        if (ch === '{' || ch === '=') break;
        flat += ch;
      }
    }
    const clause = /\bextends\b(.*)$/.exec(flat)?.[1] ?? '';
    for (const m of clause.matchAll(/([A-Za-z_][\w.]*)/g)) {
      const simple = m[1]!.split('.').pop()!;
      if (simple !== 'with' && simple !== 'derives' && simple !== typeName) names.push(simple);
    }
  }
  memo.set(typeName, names.slice(1));
  return names.slice(1);
}

const SCALA_IMPORTED_SUPERS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();
const SCALA_PACKAGE_OBJECTS = new WeakMap<ResolutionContext, Map<string, string[]>>();

/** `package object client4 extends SttpApi with …` — the graph holds no node for one. */
function scalaPackageObjects(context: ResolutionContext): Map<string, string[]> {
  const hit = SCALA_PACKAGE_OBJECTS.get(context);
  if (hit) return hit;
  const out = new Map<string, string[]>();
  for (const file of context.getAllFiles()) {
    if (!file.endsWith('.scala') || (context.fileContains && !context.fileContains(file, 'package object'))) continue;
    const source = context.readFile(file) ?? '';
    for (const m of source.matchAll(/\bpackage\s+object\s+([\w$]+)\s+extends\s+([^{\n]+)/g)) {
      const names = m[2]!.replace(/\[[^\]]*\]/g, '').split(/\bwith\b/).map((t) => t.trim().split('.').pop()!.replace(/\(.*$/, '').trim()).filter(Boolean);
      out.set(m[1]!, [...(out.get(m[1]!) ?? []), ...names]);
    }
  }
  SCALA_PACKAGE_OBJECTS.set(context, out);
  return out;
}

/** Every supertype of the objects a Scala file imports wholesale (`import Obj._`). */
function scalaImportedSupertypes(file: string, imports: { owners: Set<string> }, context: ResolutionContext): Set<string> {
  let memo = SCALA_IMPORTED_SUPERS.get(context);
  if (!memo) SCALA_IMPORTED_SUPERS.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const seen = new Set<string>();
  // Code in `package sttp.client4` (or under it) sees `package object client4`'s members unimported.
  const packages = [...(context.readFile(file) ?? '').matchAll(/^\s*package\s+([\w.]+)\s*$/gm)].flatMap((m) => m[1]!.split('.'));
  const queue = [...imports.owners, ...packages];
  const packageObjects = scalaPackageObjects(context);
  while (queue.length > 0 && seen.size < 120) {
    const typeName = queue.shift()!;
    for (const sup of [...scalaSupertypesOf(typeName, context), ...(packageObjects.get(typeName) ?? [])]) {
      if (!seen.has(sup)) { seen.add(sup); queue.push(sup); }
    }
  }
  memo.set(file, seen);
  return seen;
}

/** A Scala file's `import a.b.Obj._` / `import a.b.Obj.*` owners and `import a.b.Obj.{x, y}` / `Obj.x` members. */
function scalaImportsOf(file: string, context: ResolutionContext): { owners: Set<string>; members: Set<string>; values: Set<string> } {
  let memo = SCALA_IMPORTS.get(context);
  if (!memo) SCALA_IMPORTS.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const found = { owners: new Set<string>(), members: new Set<string>(), values: new Set<string>() };
  const source = context.readFile(file) ?? '';
  for (const m of source.matchAll(/^\s*import\s+([\w.]+?)\.(?:(_|\*)|\{([^}]*)\}|([\w$]+))\s*$/gm)) {
    const owner = m[1]!.split('.').pop()!;
    // `import builder._` — rooted at a value the file declares, whose type it doesn't say.
    const root = m[1]!.split('.')[0]!;
    if (/^[a-z]/.test(root) && (root === m[1] || new RegExp(`\\b(?:val|var|lazy\\s+val)\\s+${root}\\b|[(,]\\s*${root}\\s*:`).test(source))) {
      found.values.add(owner);
    }
    if (m[2]) found.owners.add(owner);
    else for (const member of (m[3] ?? m[4] ?? '').split(',')) {
      const id = member.trim().split(/\s*=>\s*/)[0]!;
      if (id === '_' || id === '*') found.owners.add(owner);
      else if (id) found.members.add(`${owner}.${id}`);
    }
  }
  memo.set(file, found);
  return found;
}

const CSHARP_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'interface', 'enum', 'struct', 'record']);
const CSHARP_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'property', 'field', 'enum_member', 'constant', 'event']);
const CSHARP_SUPERS = new WeakMap<ResolutionContext, Map<string, string[]>>();
const CSHARP_STATIC_USINGS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/**
 * Whether a bare C# name — `TestContext`, `Easing`, `Helper()` — can mean the
 * member `n`: C# reads a bare name as a member of the types around it (outer
 * classes included) or of their base types, or of a `using static` type.
 * Never some unrelated class's: eShop's `TestContext.CancellationToken` in
 * one test class went to another test class's `TestContext` property, MAUI's
 * `Easing.Linear` to an animation class's `Easing`. Chain links the line
 * shows a receiver for are not judged.
 */
function isCsharpMemberInScope(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!CSHARP_MEMBER_KINDS.has(n.kind)) return true;
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut < 0 || !hasNoReceiverOnLine(ref, context)) return true;
  const owner = n.qualifiedName.slice(0, cut).split(/::|\./).pop()!;
  if (csharpStaticUsings(ref.filePath, context).has(owner)) return true;
  const around = context
    .getNodesInFile(ref.filePath)
    .filter((t) => CSHARP_TYPE_KINDS.has(t.kind) && t.startLine <= ref.line && t.endLine >= ref.line);
  // No type around the name: the declaration wasn't recovered — nothing to judge by.
  if (around.length === 0) return true;
  const seen = new Set<string>();
  const queue = around.map((t) => t.name);
  while (queue.length > 0 && seen.size < 40) {
    const name = queue.shift()!;
    if (seen.has(name)) continue;
    seen.add(name);
    if (name === owner) return true;
    queue.push(...csharpSupertypesOf(name, context));
  }
  return false;
}

/** The simple names a C# type's declarations (every `partial` one) derive from. */
function csharpSupertypesOf(typeName: string, context: ResolutionContext): string[] {
  let memo = CSHARP_SUPERS.get(context);
  if (!memo) CSHARP_SUPERS.set(context, (memo = new Map()));
  const hit = memo.get(typeName);
  if (hit) return hit;
  const names: string[] = [];
  for (const decl of context.getNodesByName(typeName)) {
    if (decl.language !== 'csharp' || !CSHARP_TYPE_KINDS.has(decl.kind)) continue;
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    let head = lines.slice(decl.startLine - 1, decl.startLine + 8).join(' ');
    head = head.slice(0, (head.indexOf('{') + 1 || head.length + 1) - 1);
    let depth = 0;
    let flat = '';
    for (const ch of head) {
      if (ch === '<' || ch === '(') depth++;
      else if (ch === '>' || ch === ')') depth = Math.max(0, depth - 1);
      else if (depth === 0) flat += ch;
    }
    const bases = new RegExp(`\\b${escapeRegExp(typeName)}\\s*:\\s*(.*?)(?:\\bwhere\\b|$)`).exec(flat)?.[1] ?? '';
    for (const m of bases.matchAll(/([A-Za-z_][\w.]*)/g)) names.push(m[1]!.split('.').pop()!);
  }
  memo.set(typeName, names);
  return names;
}

/**
 * The types a C# file sees through static usings: its own `using static
 * A.B.Type;`, any file's `global using static`, and `<Using Include="A.B.Type"
 * Static="true"/>` in the `.csproj` / `Directory.Build.props` files above it
 * (AutoMapper imports its ExpressionBuilder helpers project-wide that way).
 */
function csharpStaticUsings(file: string, context: ResolutionContext): Set<string> {
  let memo = CSHARP_STATIC_USINGS.get(context);
  if (!memo) CSHARP_STATIC_USINGS.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const owners = new Set<string>(csharpProjectStaticUsings(path.posix.dirname(file), context, memo));
  for (const m of (context.readFile(file) ?? '').matchAll(/^\s*(?:global\s+)?using\s+static\s+([\w.]+)\s*;/gm)) owners.add(m[1]!.split('.').pop()!);
  memo.set(file, owners);
  return owners;
}

/** Static usings that apply to every file under `dir`: project files on the way up, and every `global using static`. */
function csharpProjectStaticUsings(dir: string, context: ResolutionContext, memo: Map<string, Set<string>>): Set<string> {
  const key = `dir:${dir}`;
  const hit = memo.get(key);
  if (hit) return hit;
  let owners: Set<string>;
  if (dir === '.' || dir === '' || dir === '/') {
    owners = new Set();
    for (const f of context.getAllFiles()) {
      if (!f.endsWith('.cs')) continue;
      const text = context.readFile(f) ?? '';
      if (!text.includes('global using static')) continue;
      for (const m of text.matchAll(/^\s*global\s+using\s+static\s+([\w.]+)\s*;/gm)) owners.add(m[1]!.split('.').pop()!);
    }
  } else {
    owners = new Set(csharpProjectStaticUsings(path.posix.dirname(dir), context, memo));
  }
  let entries: string[] = [];
  try {
    entries = fs.readdirSync(path.join(context.getProjectRoot(), dir === '.' ? '' : dir));
  } catch {
    entries = [];
  }
  for (const entry of entries) {
    if (!/\.(?:csproj|props)$/i.test(entry)) continue;
    let text = '';
    try {
      text = fs.readFileSync(path.join(context.getProjectRoot(), dir === '.' ? '' : dir, entry), 'utf8');
    } catch {
      continue;
    }
    for (const m of text.matchAll(/<Using\s+Include\s*=\s*"([\w.]+)"[^>]*\bStatic\s*=\s*"true"/gi)) owners.add(m[1]!.split('.').pop()!);
  }
  memo.set(key, owners);
  return owners;
}

const CSHARP_NAMESPACE_SCOPES = new WeakMap<ResolutionContext, Map<string, { namespaces: string[]; usings: Set<string>; aliases: Map<string, string> }>>();
const CSHARP_PROJECT_USINGS = new WeakMap<ResolutionContext, Map<string, { usings: Set<string>; project: boolean }>>();

/**
 * The namespaces a C# file's code runs in and the ones it imports: its
 * `namespace` declarations, its `using X;`, the `global using X;` of its
 * project's files (every file's, outside any project) and the
 * `<Using Include="X" />` of the project files above it.
 */
function csharpNamespaceScope(file: string, context: ResolutionContext): { namespaces: string[]; usings: Set<string>; aliases: Map<string, string> } {
  let memo = CSHARP_NAMESPACE_SCOPES.get(context);
  if (!memo) CSHARP_NAMESPACE_SCOPES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const text = stripCommentsForRegex(context.readFile(file) ?? '', 'java');
  const namespaces = [...text.matchAll(/^\s*namespace\s+([\w.]+)/gm)].map((m) => m[1]!);
  let projectMemo = CSHARP_PROJECT_USINGS.get(context);
  if (!projectMemo) CSHARP_PROJECT_USINGS.set(context, (projectMemo = new Map()));
  const project = csharpProjectUsings(path.posix.dirname(file), context, projectMemo);
  const usings = new Set<string>(project.usings);
  if (!project.project) for (const u of csharpGlobalUsings('.', context)) usings.add(u);
  const aliases = new Map<string, string>();
  for (const m of text.matchAll(/^\s*(?:global\s+)?using\s+(?!static\b)(?:([A-Za-z_]\w*)\s*=\s*)?([\w.]+)\s*;/gm)) {
    if (m[1]) aliases.set(m[1], m[2]!);
    else usings.add(m[2]!);
  }
  const scope = { namespaces, usings, aliases };
  memo.set(file, scope);
  return scope;
}

/**
 * The `<Using Include="X" />` of the project files from `dir` up, and the
 * `global using X;` of each project's own files — a global using is its
 * project's alone: serilog's Serilog.Tests and Serilog.PerformanceTests each
 * `global using` their own `Support` namespace, and both define `Some`.
 * `project` says whether a `.csproj` sits at `dir` or above it.
 */
function csharpProjectUsings(dir: string, context: ResolutionContext, memo: Map<string, { usings: Set<string>; project: boolean }>): { usings: Set<string>; project: boolean } {
  const key = dir;
  const hit = memo.get(key);
  if (hit) return hit;
  const root = dir === '.' || dir === '' || dir === '/';
  const parent = root ? null : csharpProjectUsings(path.posix.dirname(dir), context, memo);
  const usings = new Set<string>(parent?.usings ?? []);
  let project = parent?.project ?? false;
  let entries: string[] = [];
  try {
    entries = fs.readdirSync(path.join(context.getProjectRoot(), root ? '' : dir));
  } catch {
    entries = [];
  }
  for (const entry of entries) {
    if (!/\.(?:csproj|props)$/i.test(entry)) continue;
    let text = '';
    try {
      text = fs.readFileSync(path.join(context.getProjectRoot(), root ? '' : dir, entry), 'utf8');
    } catch {
      continue;
    }
    if (/\.csproj$/i.test(entry) && !project) {
      project = true;
      for (const u of csharpGlobalUsings(root ? '.' : dir, context)) usings.add(u);
    }
    for (const m of text.matchAll(/<Using\s+Include\s*=\s*"([\w.]+)"(?![^>]*\bStatic\s*=\s*"true")[^>]*>/gi)) usings.add(m[1]!);
    // The SDK's implicit usings (serilog's own `System.TimeProvider` polyfill is seen through them).
    if (/<ImplicitUsings>\s*(?:enable|true)\s*<\/ImplicitUsings>/i.test(text)) {
      for (const ns of CSHARP_IMPLICIT_USINGS) usings.add(ns);
    }
  }
  const result = { usings, project };
  memo.set(key, result);
  return result;
}

const CSHARP_GLOBAL_USINGS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/** The `global using X;` of the `.cs` files under `dir` (`.` = the whole repository). */
function csharpGlobalUsings(dir: string, context: ResolutionContext): Set<string> {
  let memo = CSHARP_GLOBAL_USINGS.get(context);
  if (!memo) CSHARP_GLOBAL_USINGS.set(context, (memo = new Map()));
  const hit = memo.get(dir);
  if (hit) return hit;
  const usings = new Set<string>();
  const prefix = dir === '.' ? '' : `${dir}/`;
  for (const f of context.getAllFiles()) {
    if (!f.endsWith('.cs') || !f.startsWith(prefix) || (context.fileContains && !context.fileContains(f, 'global using'))) continue;
    for (const m of (context.readFile(f) ?? '').matchAll(/^\s*global\s+using\s+(?!static\b)([\w.]+)\s*;/gm)) usings.add(m[1]!);
  }
  memo.set(dir, usings);
  return usings;
}

/** The namespaces `<ImplicitUsings>enable</ImplicitUsings>` imports into every file (Microsoft.NET.Sdk). */
const CSHARP_IMPLICIT_USINGS: readonly string[] = [
  'System', 'System.Collections.Generic', 'System.IO', 'System.Linq', 'System.Net.Http', 'System.Threading', 'System.Threading.Tasks',
];

/**
 * Whether a bare C# type name can mean `n` — a type in namespace `N` is seen
 * from `N` and the namespaces inside it, and through a `using N;` —
 * Newtonsoft's `async Task` tests (`using System.Threading.Tasks;`) bound
 * `Task` to a test class of that name in `Newtonsoft.Json.Tests.Schema`, 433
 * times. A type in the global namespace is seen everywhere.
 */
function isCsharpTypeVisible(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const cut = n.qualifiedName.indexOf('::');
  if (cut < 0) return true;
  const ns = n.qualifiedName.slice(0, cut);
  // A nested type (`Outer::Inner`) is judged by its outermost type's namespace.
  const scope = csharpNamespaceScope(ref.filePath, context);
  // `using License = AutoMapper.Licensing.License;` names that type, whatever the file's usings.
  const aliased = scope.aliases.get(ref.referenceName);
  if (aliased !== undefined) return aliased === `${ns}.${n.qualifiedName.slice(cut + 2).replace(/::/g, '.')}`;
  if (scope.namespaces.some((own) => own === ns || own.startsWith(ns + '.'))) return true;
  return scope.usings.has(ns);
}

/**
 * Whether a bare C# name can reach `n` as a nested type: only from inside the
 * type that declares it (any partial part, any depth) or a class deriving from
 * it. AutoMapper's tests each declare their own nested `Source`, and a
 * same-file `new Source()` went to whichever test class came first.
 */
function isCsharpNestedTypeInScope(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut < 0) return true;
  const owner = n.qualifiedName.slice(0, cut);
  const ownerType = context.getNodesInFile(n.filePath).find((p) => CSHARP_TYPE_KINDS.has(p.kind) && p.qualifiedName === owner);
  // Declared in a namespace, not a type.
  if (!ownerType) return true;
  const enclosing = context.getNodesInFile(ref.filePath)
    .filter((p) => CSHARP_TYPE_KINDS.has(p.kind) && p.startLine <= ref.line && p.endLine >= ref.line);
  if (enclosing.some((p) => p.qualifiedName === owner || p.qualifiedName.startsWith(`${owner}::`))) return true;
  // Inherited: a type around the ref derives from the owner (`class SourceA :
  // Source`), through any partial part — Newtonsoft's JsonTextReader.Async.cs
  // is `partial class JsonTextReader` with no base list, reading JsonReader's `State`.
  return enclosing.some((p) => csharpAncestorNames(p.qualifiedName, context).has(ownerType.name));
}

const CSHARP_ANCESTORS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/** The simple names of the C# types `qn` derives from, through every partial part and base, a few levels up. */
function csharpAncestorNames(qn: string, context: ResolutionContext, depth = 0): Set<string> {
  let memo = CSHARP_ANCESTORS.get(context);
  if (!memo) CSHARP_ANCESTORS.set(context, (memo = new Map()));
  const hit = memo.get(qn);
  if (hit) return hit;
  const names = new Set<string>();
  memo.set(qn, names); // a cycle reads what is gathered so far
  for (const decl of context.getNodesByQualifiedName(qn)) {
    if (decl.language !== 'csharp' || !CSHARP_TYPE_KINDS.has(decl.kind)) continue;
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    let header = '';
    for (let i = decl.startLine - 1; i < Math.min(lines.length, decl.startLine + 6) && !header.includes('{'); i++) header += `${lines[i] ?? ''} `;
    const list = /:\s*([^{;]*)/.exec(header.split('{')[0]!.replace(/\bwhere\b[\s\S]*$/, ''))?.[1] ?? '';
    for (const base of splitCppTopLevel(list)) {
      const name = /([A-Za-z_]\w*)\s*(?:<.*)?$/.exec(base.trim())?.[1];
      if (name) names.add(name);
    }
  }
  if (depth < 4) {
    for (const base of [...names]) {
      for (const t of context.getNodesByName(base)) {
        if (t.language !== 'csharp' || !CSHARP_TYPE_KINDS.has(t.kind) || t.qualifiedName === qn) continue;
        for (const up of csharpAncestorNames(t.qualifiedName, context, depth + 1)) names.add(up);
      }
    }
  }
  return names;
}

const OBJC_SUPERS = new WeakMap<ResolutionContext, Map<string, string[]>>();
const OBJC_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'property', 'field']);

/**
 * How a bare Objective-C name is written at its site: `c-call` for C call
 * syntax (`completionBlock()` — a function, a block or a function pointer,
 * never a method), `self-send` for a message to `self` / `super` /
 * `[self class]`, whose receiver the extractor drops; null otherwise.
 */
function objcCallShape(ref: UnresolvedRef, context: ResolutionContext): 'c-call' | 'self-send' | 'super-send' | null {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return null;
  const name = ref.referenceName.split(':')[0]!;
  if (!name) return null;
  const at = new RegExp(`(?<![\\w.])${escapeRegExp(name)}\\b`, 'g');
  let m: RegExpExecArray | null;
  let shape: 'c-call' | 'self-send' | 'super-send' | null = null;
  while ((m = at.exec(line))) {
    const before = line.slice(0, m.index);
    const after = line.slice(m.index + name.length);
    if (/^\s*\(/.test(after) && !/\[\s*[\w.]+\s+$/.test(before)) shape ??= 'c-call';
    else if (/\[\s*super\s+$/.test(before)) return 'super-send';
    else if (/\[\s*(?:self|\[\s*self\s+class\s*\])\s+$/.test(before)) return 'self-send';
  }
  return shape;
}

/**
 * The classes a message to `self` / `super` can reach: the class it is
 * written in and every class that one inherits from (read from its
 * `@interface Name : Super` declarations; category methods are indexed under
 * the class they extend). Null outside any class.
 */
function objcHierarchyAt(ref: UnresolvedRef, context: ResolutionContext): Set<string> | null {
  const inFile = context.getNodesInFile(ref.filePath);
  let here = inFile
    .filter((c) => c.kind === 'class' && c.startLine <= ref.line && c.endLine >= ref.line)
    .sort((a, b) => (a.endLine - a.startLine) - (b.endLine - b.startLine))[0]?.name;
  // An `@implementation` whose range the index lost still names its class in
  // its methods: `SDWebImageDownloaderDecryptor::initWithBlock:`.
  if (!here) {
    const method = inFile.find((c) => c.kind === 'method' && c.startLine <= ref.line && c.endLine >= ref.line && c.qualifiedName.includes('::'));
    here = method?.qualifiedName.slice(0, method.qualifiedName.lastIndexOf('::'));
  }
  if (!here) return null;
  const seen = new Set<string>();
  const queue = [here];
  while (queue.length > 0 && seen.size < 30) {
    const name = queue.shift()!;
    if (seen.has(name)) continue;
    seen.add(name);
    queue.push(...objcSupertypesOf(name, context));
  }
  return seen;
}

/**
 * Whether a message to `self` / `super` can mean `n`: a method of a class in
 * the sender's hierarchy — SDWebImage's `[self class]` went to SDWeakProxy's
 * `class` 71 times. When tree-sitter-objc loses an `@implementation`
 * (AFNetworking's AFURLSessionManager) its methods are indexed as functions:
 * one in the sender's own file, or in the file named after a class of its
 * hierarchy, still counts (as does any, when the sender's own class was lost
 * too). A function elsewhere is never what `[super init]` sends to.
 */
function isObjcSelfSendTarget(n: Node, ref: UnresolvedRef, context: ResolutionContext, toSuper = false): boolean {
  const hierarchy = objcHierarchyAt(ref, context);
  if (OBJC_MEMBER_KINDS.has(n.kind)) {
    const cut = n.qualifiedName.lastIndexOf('::');
    if (cut < 0 || hierarchy === null) return true;
    const owner = n.qualifiedName.slice(0, cut);
    // `[super init]` goes past the class it is written in.
    return hierarchy.has(owner) && !(toSuper && owner === [...hierarchy][0]);
  }
  if (n.filePath === ref.filePath) return !toSuper;
  if (hierarchy === null) return true;
  const base = n.filePath.slice(n.filePath.lastIndexOf('/') + 1).replace(/\.\w+$/, '');
  return hierarchy.has(base) && !(toSuper && base === [...hierarchy][0]);
}

/**
 * UIKit / AppKit superclasses, for a category on a system class: an
 * `UIImageView (WebCache)` method sending `[self sd_internalSetImageWithURL:…]`
 * reaches the `UIView (WebCache)` category.
 */
const OBJC_SYSTEM_SUPERS: Readonly<Record<string, string>> = {
  UIResponder: 'NSObject', UIView: 'UIResponder', UIViewController: 'UIResponder', UIWindow: 'UIView',
  UIControl: 'UIView', UIButton: 'UIControl', UITextField: 'UIControl', UISwitch: 'UIControl', UISlider: 'UIControl',
  UISegmentedControl: 'UIControl', UIStepper: 'UIControl', UIPageControl: 'UIControl', UIDatePicker: 'UIControl',
  UIRefreshControl: 'UIControl', UIStackView: 'UIView', UINavigationBar: 'UIView', UIToolbar: 'UIView',
  UITabBar: 'UIView', UISearchBar: 'UIView', UIVisualEffectView: 'UIView', UIActivityIndicatorView: 'UIView',
  UIProgressView: 'UIView', UIPickerView: 'UIView', UITableViewHeaderFooterView: 'UIView',
  UITableViewController: 'UIViewController', UICollectionViewController: 'UIViewController',
  UINavigationController: 'UIViewController', UITabBarController: 'UIViewController',
  UIPageViewController: 'UIViewController', UISplitViewController: 'UIViewController',
  UIAlertController: 'UIViewController', UIHostingController: 'UIViewController',
  UIImageView: 'UIView', UILabel: 'UIView', UIScrollView: 'UIView', UITableView: 'UIScrollView',
  UICollectionView: 'UIScrollView', UITextView: 'UIScrollView', UITableViewCell: 'UIView',
  UICollectionReusableView: 'UIView', UICollectionViewCell: 'UICollectionReusableView',
  MKAnnotationView: 'UIView', MKMapView: 'UIView',
  NSResponder: 'NSObject', NSView: 'NSResponder', NSViewController: 'NSResponder', NSWindow: 'NSResponder',
  NSControl: 'NSView', NSImageView: 'NSControl', NSButton: 'NSControl', NSTextField: 'NSControl', NSTableView: 'NSControl',
};

/**
 * Whether an Objective-C receiver's type owns `method`, in its hierarchy: the
 * receiver names a class (`[AllTypesObject objectsInRealm:…]` — a class
 * method inherited from RLMObject), or is a property one of whose
 * `@property … Type *name` declarations gives such a type
 * (`managed.anyDataObj` → RLMSet, for `containsObject:`).
 */
function objcReceiverReaches(receiver: string, method: Node, context: ResolutionContext): boolean {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut < 0) return false;
  const owner = method.qualifiedName.slice(0, cut);
  let types: string[] = [];
  if (/^[A-Z]\w*$/.test(receiver)) {
    if (context.getNodesByName(receiver).some((n) => n.kind === 'class' && n.language === 'objc')) types = [receiver];
  } else if (receiver.includes('.')) types = objcPropertyTypes(receiver.split('.').pop()!, context);
  const seen = new Set<string>();
  const queue = [...types];
  while (queue.length > 0 && seen.size < 40) {
    const name = queue.shift()!;
    if (seen.has(name)) continue;
    seen.add(name);
    if (name === owner) return true;
    queue.push(...objcSupertypesOf(name, context));
  }
  return false;
}

/** The classes the `@property … Type *name` declarations of `name` give. */
function objcPropertyTypes(name: string, context: ResolutionContext): string[] {
  const types = new Set<string>();
  const decl = new RegExp(`@property\\s*(?:\\([^)]*\\)\\s*)?([A-Z]\\w*)\\s*(?:<[^;]*>\\s*)?\\*\\s*(?:_Nullable\\s+|_Nonnull\\s+)?${escapeRegExp(name)}\\b`);
  for (const n of context.getNodesByName(name)) {
    if (n.kind !== 'property' || n.language !== 'objc') continue;
    const line = context.getFileLines?.(n.filePath)?.[n.startLine - 1] ?? context.readFile(n.filePath)?.split('\n')[n.startLine - 1] ?? '';
    const t = decl.exec(line)?.[1];
    if (t) types.add(t);
  }
  return [...types];
}

/**
 * What one file declares of an Objective-C class: instance variables (an
 * `@interface`'s ivar block, which subclasses see, or a class extension's or
 * an `@implementation`'s, which they don't), properties (a category's can't
 * be synthesized), and the ivar each `@synthesize` names for a property.
 */
interface ObjcClassMembers {
  ivars: Map<string, string>;
  ownIvars: Map<string, string>;
  properties: Map<string, { type: string; category: boolean }>;
  synthesized: Map<string, string>;
}

/** Per context: an Objective-C file → each class it declares → what it declares of it. */
const OBJC_MEMBER_TABLES = new WeakMap<ResolutionContext, Map<string, Map<string, ObjcClassMembers>>>();
/** Per context: class name + the calling file's directory → the files declaring that class. */
const OBJC_CLASS_FILES = new WeakMap<ResolutionContext, Map<string, string[]>>();

// A declared class as a member declaration writes it, past qualifiers, with
// its type arguments, protocol list or ObjFW's `OF_GENERIC(…)` after it, up to
// the `*`: `OFObject <OFHTTPClientDelegate> *`, `OFArray OF_GENERIC(OFString *) *`,
// `IBOutlet UIImageView *`.
const OBJC_MEMBER_TYPE = String.raw`(?:(?:__strong|__weak|__unsafe_unretained|__block|const|volatile|IBOutlet|IBInspectable)\s+)*([A-Z]\w*)\s*(?:<[^;{}]*?>\s*|[A-Z][A-Z0-9_]*\s*\([^;{}]*?\)\s*)?\*`;
// An instance variable, alone or listed: `OFDictionary *_headers;`, `OFString *_host, *_path;`.
const OBJC_IVAR_RE = new RegExp(String.raw`^\s*${OBJC_MEMBER_TYPE}\s*((?:(?:_Nullable|_Nonnull|const)\s+)*\w+(?:\s*,\s*\*\s*(?:(?:_Nullable|_Nonnull|const)\s+)*\w+)*)\s*;`);
// A property, past attribute macros and its attribute list:
// `@property OF_NULLABLE_PROPERTY (readonly, nonatomic) OFString *host;`.
const OBJC_PROPERTY_RE = new RegExp(String.raw`^\s*@property\b\s*(?:[A-Z][A-Z0-9_]+\s*)*(?:\([^)]*\)\s*)?(?:(?:nullable|nonnull|null_unspecified|__kindof)\s+)*${OBJC_MEMBER_TYPE}\s*(?:(?:_Nullable|_Nonnull|const)\s+)*(\w+)`);

/**
 * What each Objective-C class `filePath` declares has, by name, with the
 * class each is declared as (ObjcClassMembers): read from `@interface`s (a
 * header's, a class extension's or a category's: the ivar block right after
 * the head, then `@property` declarations, which may run over several lines)
 * and from an `@implementation`'s ivar block and `@synthesize` lines, never a
 * method body.
 */
function objcFileMembers(filePath: string, context: ResolutionContext): Map<string, ObjcClassMembers> {
  let memo = OBJC_MEMBER_TABLES.get(context);
  if (!memo) OBJC_MEMBER_TABLES.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit) return hit;
  const tables = new Map<string, ObjcClassMembers>();
  memo.set(filePath, tables);
  const lines = context.getFileLines?.(filePath) ?? context.readFile(filePath)?.split(/\r?\n/) ?? [];
  const count = (text: string, re: RegExp): number => (text.match(re) ?? []).length;
  let members: ObjcClassMembers | null = null;
  let inInterface = false;
  // `@interface Name (Category)`, or a class extension `@interface Name ()`.
  let category: string | null = null;
  // A class declares ivars only in a block that is the first code after its
  // head: 'head' until that code (`open` counts the head's unclosed `<` and
  // `(`, as in a protocol list over several lines), 'ivars' inside the block
  // (`depth` braces deep), 'body' past it.
  let state: 'head' | 'ivars' | 'body' = 'body';
  let open = 0;
  let depth = 0;
  // A `@property` declaration read so far, until its `;`.
  let property: string | null = null;
  for (const raw of lines) {
    let line = raw.replace(/\/\/.*$/, '');
    const head = /^\s*(?:[A-Z][A-Z0-9_]*(?:\([^)]*\))?\s+)*@(interface|implementation)\s+(\w+)\s*(?:<[^>]*>\s*|[A-Z][A-Z0-9_]*\([^)]*\)\s*)?(?:\(\s*(\w*)\s*\))?/.exec(line);
    if (head) {
      const cls = head[2]!;
      members = tables.get(cls) ?? { ivars: new Map(), ownIvars: new Map(), properties: new Map(), synthesized: new Map() };
      tables.set(cls, members);
      inInterface = head[1] === 'interface';
      category = head[3] ?? null;
      state = 'head';
      open = 0;
      property = null;
      line = line.slice(head.index + head[0].length);
    } else if (/^\s*@end\b/.test(line)) {
      members = null;
      continue;
    }
    if (!members) continue;
    if (state === 'head') {
      // The head may go on with its superclass or protocol list on the next
      // lines: ObjFW's `@interface OFKernelEventObserverTests: OTTestCase`
      // over `    <OFKernelEventObserverDelegate>`.
      const inHead = head !== null || open > 0 || /^\s*[<:]/.test(line);
      open += count(line, /[<(]/g) - count(line, /[>)]/g);
      const brace = line.indexOf('{');
      if (brace >= 0) {
        state = 'ivars';
        depth = 0;
        line = line.slice(brace);
      } else if (inHead || open > 0 || /^\s*(?:$|\/\*|\*|#)/.test(line)) {
        continue;
      } else {
        state = 'body';
      }
    }
    if (state === 'ivars') {
      depth += count(line, /\{/g) - count(line, /\}/g);
      if (depth <= 0) state = 'body';
      const ivar = OBJC_IVAR_RE.exec(line.replace(/^[^{]*\{/, '').replace(/\}.*$/, ''));
      const ivars = inInterface && category === null ? members.ivars : members.ownIvars;
      for (const name of ivar?.[2]!.split(',') ?? []) {
        const bare = name.replace(/\*|_Nullable|_Nonnull|\bconst\b/g, '').trim();
        if (/^\w+$/.test(bare) && !ivars.has(bare)) ivars.set(bare, ivar![1]!);
      }
      continue;
    }
    if (!inInterface) {
      const synthesize = /^\s*@synthesize\s+([^;]+);/.exec(line);
      for (const item of synthesize?.[1]!.split(',') ?? []) {
        const [name, ivar] = item.split('=').map((s) => s.trim());
        if (name && /^\w+$/.test(ivar ?? name)) members.synthesized.set(ivar ?? name, name);
      }
      continue;
    }
    if (property === null && !/^\s*@property\b/.test(line)) continue;
    property = property === null ? line : `${property} ${line}`;
    if (!property.includes(';') && property.length < 400) continue;
    const declared = OBJC_PROPERTY_RE.exec(property);
    property = null;
    if (declared && !members.properties.has(declared[2]!)) {
      members.properties.set(declared[2]!, { type: declared[1]!, category: !!category });
    }
  }
  return tables;
}

/**
 * The files declaring the Objective-C class `name`, the calling file first.
 * When more than one file declares the class itself (`@interface Name`, not a
 * category or an extension), they are namesakes in separate targets, like
 * each SDWebImage demo app's `ViewController`, and only the declarations in
 * the calling file's directory are the one the call means.
 */
function objcClassFiles(name: string, ref: UnresolvedRef, context: ResolutionContext): string[] {
  const dir = ref.filePath.slice(0, ref.filePath.lastIndexOf('/') + 1);
  let memo = OBJC_CLASS_FILES.get(context);
  if (!memo) OBJC_CLASS_FILES.set(context, (memo = new Map()));
  const key = `${name}\u0000${dir}`;
  const hit = memo.get(key);
  if (hit) return hit;
  const decls = context.getNodesByName(name).filter((n) => n.kind === 'class' && n.language === 'objc');
  const primary = new Set<string>();
  const own = new RegExp(`@interface\\s+${escapeRegExp(name)}\\b(?!\\s*\\()`);
  for (const decl of decls) {
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    if (lines.slice(decl.startLine - 1, decl.endLine).some((l) => own.test(l))) primary.add(decl.filePath);
  }
  const inDir = (file: string) => file.startsWith(dir) && !file.includes('/', dir.length);
  const files = [...new Set(decls.map((n) => n.filePath))]
    .filter((file) => primary.size < 2 || inDir(file))
    .sort((a, b) => Number(b === ref.filePath) - Number(a === ref.filePath));
  memo.set(key, files);
  return files;
}

/**
 * The class an Objective-C receiver is declared as when it is an instance
 * variable of the class around the call, or a property read through `self.`:
 * ObjFW's `[_headers mutableCopy]` on an `OFMutableDictionary *_headers;`
 * ivar, the ivar a property synthesizes (`_name`, or the one `@synthesize`
 * names), or `[self.weakCache objectForKey:]` on an `NSMapTable` property. A
 * class it inherits from lends the ivars its `@interface` declares and its
 * properties. A local or a parameter, which the shared inferrer reads first,
 * shadows an ivar, and a bare name is never a property's: `arcs` in
 * `initWithArcs:` is the parameter. Null when nothing declares it.
 */
function objcMemberReceiverType(receiver: string, ref: UnresolvedRef, context: ResolutionContext): string | null {
  const viaSelf = receiver.startsWith('self.');
  const name = viaSelf ? receiver.slice(5) : receiver;
  if (!/^[A-Za-z_]\w*$/.test(name) || name === 'self' || name === 'super') return null;
  // A capitalized name is a class (`[OFString stringWithFormat:]`), not an
  // ivar, and `self.name` needs a property of that name.
  if (viaSelf ? !context.getNodesByName(name).some((n) => n.kind === 'property' && n.language === 'objc') : /^[A-Z]/.test(name)) {
    return null;
  }
  const hierarchy = objcHierarchyAt(ref, context);
  if (!hierarchy) return null;
  // What each class of the hierarchy declares, the calling one first.
  const levels = [...hierarchy].map((cls) => objcClassFiles(cls, ref, context)
    .map((file) => objcFileMembers(file, context).get(cls))
    .filter((t): t is ObjcClassMembers => t !== undefined));
  // A property's type, from the calling class up; `own`: only one the calling
  // class declares and may synthesize, never a category's.
  const propertyType = (key: string, own: boolean): string | undefined => {
    for (const level of own ? levels.slice(0, 1) : levels) {
      for (const t of level) {
        const p = t.properties.get(key);
        if (p && !(own && p.category)) return p.type;
      }
    }
    return undefined;
  };
  if (viaSelf) return propertyType(name, false) ?? null;
  for (const [i, level] of levels.entries()) {
    for (const t of level) {
      const type = t.ivars.get(name) ?? (i === 0 ? t.ownIvars.get(name) : undefined);
      if (type) return type;
    }
    if (i > 0) continue;
    const synthesized = level.map((t) => t.synthesized.get(name)).find((p) => p !== undefined);
    const type = synthesized !== undefined ? propertyType(synthesized, false)
      : name.startsWith('_') ? propertyType(name.slice(1), true) : undefined;
    if (type) return type;
  }
  return null;
}

/** The superclasses an Objective-C class's `@interface` declarations name. */
function objcSupertypesOf(name: string, context: ResolutionContext): string[] {
  let memo = OBJC_SUPERS.get(context);
  if (!memo) OBJC_SUPERS.set(context, (memo = new Map()));
  const hit = memo.get(name);
  if (hit) return hit;
  const supers: string[] = [];
  for (const decl of context.getNodesByName(name)) {
    if (decl.kind !== 'class' || decl.language !== 'objc') continue;
    // The class may open with an attribute macro on a line of its own, like
    // `NS_SWIFT_NAME(CrashInstallationStandard)` above KSCrash's
    // `@interface KSCrashInstallationStandard : KSCrashInstallation`.
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split('\n') ?? [];
    const line = lines.slice(decl.startLine - 1, decl.endLine).find((l) => l.includes('@interface')) ?? '';
    const sup = /@interface\s+\w+\s*:\s*(\w+)/.exec(line)?.[1];
    if (sup && !supers.includes(sup)) supers.push(sup);
  }
  const system = OBJC_SYSTEM_SUPERS[name];
  if (supers.length === 0 && system) supers.push(system);
  memo.set(name, supers);
  return supers;
}

const VB_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'property', 'field', 'enum_member', 'constant', 'variable']);

/**
 * What a VB.NET member access is written on, read at the call site: the
 * extractor keeps a call's last name only, so `Me.CMB.Buttons.Add(x)` and
 * `New System.Drawing.Size(1, 2)` arrive as bare `Add` / `Size`. Returns null
 * for a genuinely bare name, `''` for a `With` block's `.Name`, else the
 * text before the dot (`Me.CMB.Buttons`, `System.Drawing`).
 */
function vbReceiverOf(ref: UnresolvedRef, context: ResolutionContext): string | null {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return null;
  const lower = line.toLowerCase();
  const name = ref.referenceName.toLowerCase();
  let start = lower.startsWith(name, ref.column) ? ref.column : -1;
  if (start < 0) {
    // The reference starts at its receiver or its `New`, so the name is the
    // first one there or after: `st.Language = New Language(…)` constructs
    // a Language through no receiver, and `Me.Size = New System.Drawing.Size(…)`
    // through `System.Drawing`, not `Me`.
    const at = new RegExp(`(?<![\\w])${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w])`, 'g');
    at.lastIndex = Math.max(0, ref.column);
    const m = at.exec(lower) ?? (at.lastIndex = 0, at.exec(lower));
    start = m ? m.index : -1;
  }
  if (start < 0) return null;
  const before = line.slice(0, start);
  const dot = /([\w.()]*?)\s*\.\s*$/.exec(before);
  if (!dot) return null;
  // `GetService(Of TrayNotifierService).Notify()` — the type argument names the receiver.
  const typeArg = /\(\s*Of\s+([\w.]+)\s*\)\s*\.\s*$/i.exec(before);
  if (typeArg) return typeArg[1]!;
  return dot[1]!.replace(/\([^()]*\)/g, '');
}

/**
 * Whether a VB.NET member access can mean `n`: through `Me` / `MyBase` /
 * `MyClass`, or through a name that is `n`'s own type or module
 * (`Module1.Log()`, `Colors.Red`). Any other receiver has a type nothing here
 * names — SCrawler's `New System.Drawing.Size(…)` went to a nested enum's
 * `Size` case 713 times, its designer's `Controls.Add(…)` to a collection
 * class's `Add` 547.
 */
function isVbMemberReachable(n: Node, receiver: string): boolean {
  if (!VB_MEMBER_KINDS.has(n.kind)) return true;
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut < 0) return true;
  const last = receiver.split('.').pop()!.toLowerCase();
  if (/^(?:me|mybase|myclass)$/.test(last) && !receiver.includes('.')) return true;
  const owner = n.qualifiedName.slice(0, cut).split(/::|\./).pop()!.toLowerCase();
  return last !== '' && last === owner;
}

/**
 * Whether a VB.NET call has no receiver, or one the extractor drops (`Me`,
 * `MyClass`, `MyBase`) — a call isVbMemberInScope judges. A name its line
 * doesn't show (a link of a chain continued from the line above) is not.
 */
function isVbScopedCall(ref: UnresolvedRef, receiver: string | null, context: ResolutionContext): boolean {
  if (ref.language !== 'vbnet' || ref.referenceKind !== 'calls' || !/^\w+$/.test(ref.referenceName)) return false;
  return receiver === null ? hasNoReceiverOnLine(ref, context) : /^(?:me|mybase|myclass)$/i.test(receiver);
}

/** Whether a VB.NET call or construction names its target with nothing before it (`New Point(4, 285)`). */
function isVbUnqualifiedName(ref: UnresolvedRef, receiver: string | null, context: ResolutionContext): boolean {
  if (ref.language !== 'vbnet' || (ref.referenceKind !== 'calls' && ref.referenceKind !== 'instantiates')) return false;
  return receiver === null && /^\w+$/.test(ref.referenceName) && hasNoReceiverOnLine(ref, context);
}

const CFML_CHAINS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/**
 * Whether a bare CFML call written in a component can mean `method`: its own
 * component's, or one of the components it `extends` (read from source — a
 * dotted path matched against the indexed files by its longest suffix). A
 * call in a `.cfm` template is not judged: a ColdBox view runs inside the
 * renderer's scope. coldbox's `now()` — the built-in — went to a date
 * helper's `now` 228 times; chained `.then()` calls arrive bare too, and keep
 * their method.
 */
function isCfmlMethodInScope(method: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!/\.cfc$/i.test(ref.filePath) || !hasNoReceiverOnLine(ref, context)) return true;
  return cfmlChain(ref.filePath, context).has(method.filePath);
}

/** A component file and every component file it extends. */
function cfmlChain(file: string, context: ResolutionContext): Set<string> {
  let memo = CFML_CHAINS.get(context);
  if (!memo) CFML_CHAINS.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const chain = new Set<string>();
  const queue = [file];
  while (queue.length > 0 && chain.size < 30) {
    const f = queue.shift()!;
    if (chain.has(f)) continue;
    chain.add(f);
    const text = context.readFile(f) ?? '';
    const head = text.slice(0, text.search(/\bfunction\b|<cffunction/i) >>> 0 || text.length);
    const ext = /\bextends\s*=\s*["']?([\w.\/:-]+)["']?/i.exec(head)?.[1];
    if (ext) queue.push(...cfmlComponentFiles(ext, f, context));
  }
  memo.set(file, chain);
  return chain;
}

/** The indexed `.cfc` files a component path names: the same directory first, else the longest path suffix. */
function cfmlComponentFiles(dotted: string, from: string, context: ResolutionContext): string[] {
  const segments = dotted.replace(/\//g, '.').split('.').filter(Boolean);
  const name = segments[segments.length - 1]!.toLowerCase();
  const files = [...new Set(context.getNodesByLowerName(name)
    .filter((n) => n.kind === 'class' && /\.cfc$/i.test(n.filePath))
    .map((n) => n.filePath))];
  if (files.length === 0) return [];
  const dir = from.slice(0, from.lastIndexOf('/') + 1);
  if (segments.length === 1) {
    const local = files.filter((f) => f.slice(0, f.lastIndexOf('/') + 1) === dir);
    return local.length > 0 ? local : files;
  }
  for (let take = segments.length; take >= 1; take--) {
    const suffix = '/' + segments.slice(-take).join('/').toLowerCase() + '.cfc';
    const hits = files.filter((f) => ('/' + f.toLowerCase()).endsWith(suffix));
    if (hits.length > 0) return hits;
  }
  return files;
}

const NO_RECEIVER_LINES = new WeakMap<ResolutionContext, WeakMap<UnresolvedRef, boolean>>();

/**
 * Whether a bare reference is receiver-less at its call site, name case
 * aside: the name is not preceded by a `.` on its line (true when the line
 * can't tell). An extractor that keeps one receiver level hands the later
 * links of a chain (`newFuture(f).then(g)`) over bare.
 */
function hasNoReceiverOnLine(ref: UnresolvedRef, context: ResolutionContext): boolean {
  // Asked once per CANDIDATE by the per-language scope filters, though only
  // the ref decides it — a bare `init()` in a CFML codebase has hundreds of
  // same-named methods, each re-reading the line (#2091).
  let memo = NO_RECEIVER_LINES.get(context);
  if (!memo) NO_RECEIVER_LINES.set(context, (memo = new WeakMap()));
  let answer = memo.get(ref);
  if (answer === undefined) memo.set(ref, (answer = readNoReceiverOnLine(ref, context)));
  return answer;
}

function readNoReceiverOnLine(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return true;
  const lower = line.toLowerCase();
  const name = ref.referenceName.toLowerCase();
  let start = -1;
  if (lower.startsWith(name, ref.column)) start = ref.column;
  else if (ref.column >= name.length && lower.startsWith(name, ref.column - name.length)) start = ref.column - name.length;
  else start = lower.search(new RegExp(`(?<![\\w$])${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\(`));
  // Not on its line at all: a link of a chain written across lines.
  if (start < 0) return false;
  return !/\.\s*$/.test(line.slice(0, start));
}

const RUBY_ANCESTRY = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/**
 * Whether a bare Ruby call written inside a class body can mean `method`: a
 * receiver-less call is a call on `self`, so it reaches the class's own
 * methods, its superclasses', and those of the modules any of them
 * `include`s, `extend`s or `prepend`s — read from source, resolved against
 * the lexical nesting (`class Foo < Base` inside `module RuboCop::Cop` is
 * `RuboCop::Cop::Base`). A call in a module body, a block at the top of a
 * file (a spec, a DSL) or a script is not judged: a module's methods run on
 * whatever includes it, and a block may be evaluated on anything. rubocop's
 * `format(…)` — Kernel's — went to the LSP runtime's `format` 411 times.
 */
function isRubyMethodInScope(method: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut < 0) return true;
  const here = context
    .getNodesInFile(ref.filePath)
    .filter((n) => (n.kind === 'class' || n.kind === 'module') && n.startLine <= ref.line && n.endLine >= ref.line)
    .sort((a, b) => (a.endLine - a.startLine) - (b.endLine - b.startLine))[0];
  if (!here || here.kind !== 'class') return true;
  return rubyAncestry(here.qualifiedName, context).has(method.qualifiedName.slice(0, cut));
}

/**
 * Of a Ruby class's two methods of one name, `def build` and `def self.build`
 * (both `Widget::build`), the one a bare call means: a bare call is a call on
 * `self`, so in an instance method it is the instance method, and in a class
 * method (`def self.x`, `class << self`) the class method. Widget's `run`
 * calling `build` reaches `def build`, and its `def self.go` calling `build`
 * reaches `def self.build`. Only such pairs are split: inside a block that
 * runs on another object (`Module.new do … end`, a test's `it do … end`) the
 * caller's kind says nothing of `self`, and any other candidate stays as it
 * was. A call written anywhere but in a method splits nothing.
 */
function rubyMethodsOfCallerKind(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  if (candidates.length < 2) return candidates;
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller || caller.kind !== 'method' || caller.language !== 'ruby') return candidates;
  const wantClass = caller.isStatic === true;
  const isRubyMethod = (n: Node): boolean => n.kind === 'method' && n.language === 'ruby';
  // Per qualified name, which kinds the candidates declare: 1 class, 2 instance.
  const kinds = new Map<string, number>();
  for (const n of candidates) {
    if (isRubyMethod(n)) kinds.set(n.qualifiedName, (kinds.get(n.qualifiedName) ?? 0) | (n.isStatic === true ? 1 : 2));
  }
  const twinOfOtherKind = (n: Node): boolean =>
    isRubyMethod(n) && kinds.get(n.qualifiedName) === 3 && (n.isStatic === true) !== wantClass;
  return candidates.some(twinOfOtherKind) ? candidates.filter((n) => !twinOfOtherKind(n)) : candidates;
}

/** A Ruby class's qualified name, those of its superclasses, and of every module mixed into any of them. */
export function rubyAncestry(qn: string, context: ResolutionContext): Set<string> {
  let memo = RUBY_ANCESTRY.get(context);
  if (!memo) RUBY_ANCESTRY.set(context, (memo = new Map()));
  const hit = memo.get(qn);
  if (hit) return hit;
  const seen = new Set<string>();
  const queue = [qn];
  while (queue.length > 0 && seen.size < 60) {
    const q = queue.shift()!;
    if (seen.has(q)) continue;
    seen.add(q);
    for (const decl of context.getNodesByQualifiedName(q)) {
      if (decl.language !== 'ruby' || (decl.kind !== 'class' && decl.kind !== 'module')) continue;
      const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
      const outer = q.includes('::') ? q.slice(0, q.lastIndexOf('::')) : '';
      const sup = /^\s*class\s+[\w:]+\s*<\s*(::)?([A-Z][\w:]*)/.exec(lines[decl.startLine - 1] ?? '');
      if (sup) queue.push(rubyConstantQn(sup[2]!, sup[1] ? '' : outer, context));
      for (const line of lines.slice(decl.startLine, decl.endLine)) {
        // A module a call returns (`include RouteSet.new.tap { … }.url_helpers`,
        // actionpack's tests) is no mixin of the constant the call starts at.
        const mix = /^\s*(?:include|extend|prepend)\s+([A-Z:][\w:]*(?:\s*,\s*[A-Z:][\w:]*)*)(?![\w:]|\s*[.(])/.exec(line);
        if (!mix) continue;
        for (const name of mix[1]!.split(/\s*,\s*/)) {
          queue.push(name.startsWith('::') ? rubyConstantQn(name.slice(2), '', context) : rubyConstantQn(name, q, context));
        }
      }
    }
  }
  memo.set(qn, seen);
  return seen;
}

/** The class or module a constant written inside `scope` names: the nearest enclosing namespace that has it, else the name itself. */
function rubyConstantQn(name: string, scope: string, context: ResolutionContext): string {
  for (let prefix = scope; ; prefix = prefix.includes('::') ? prefix.slice(0, prefix.lastIndexOf('::')) : '') {
    const qn = prefix ? `${prefix}::${name}` : name;
    if (context.getNodesByQualifiedName(qn).some((n) => n.language === 'ruby' && (n.kind === 'class' || n.kind === 'module'))) return qn;
    if (!prefix) return name;
  }
}

const KOTLIN_FILE_SCOPES = new WeakMap<ResolutionContext, Map<string, { pkg: string; imports: Set<string>; stars: Set<string> }>>();
/** Packages every Kotlin file imports without writing it. */
const KOTLIN_DEFAULT_IMPORTS: ReadonlySet<string> = new Set([
  'kotlin', 'kotlin.annotation', 'kotlin.collections', 'kotlin.comparisons', 'kotlin.io', 'kotlin.ranges',
  'kotlin.sequences', 'kotlin.text', 'kotlin.jvm', 'java.lang', 'kotlin.js',
]);
const KOTLIN_ENCLOSING_KINDS: ReadonlySet<string> = new Set([
  'class', 'interface', 'enum', 'struct', 'trait', 'protocol', 'module', 'namespace', 'function', 'method',
]);

/** A Kotlin file's `package` and the names and packages its `import`s bring in. */
function kotlinFileScope(file: string, context: ResolutionContext): { pkg: string; imports: Set<string>; stars: Set<string> } {
  let memo = KOTLIN_FILE_SCOPES.get(context);
  if (!memo) KOTLIN_FILE_SCOPES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const text = (context.readFile(file) ?? '').replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/`/g, '');
  const pkg = /^\s*package\s+([\w.]+)/m.exec(text)?.[1] ?? '';
  const imports = new Set<string>();
  const stars = new Set<string>();
  for (const m of text.matchAll(/^\s*import\s+([\w.]+?)(\.\*)?(?:\s+as\s+\w+)?\s*;?\s*(?:\/\/.*)?$/gm)) {
    if (m[2]) stars.add(m[1]!);
    else imports.add(m[1]!);
  }
  const scope = { pkg, imports, stars };
  memo.set(file, scope);
  return scope;
}

/**
 * Whether a top-level Kotlin declaration — a function, an extension function
 * (indexed under its receiver type, `JdbcTransaction::assertEquals`), a
 * property — can be named from the file a call is written in: its own
 * package, an `import` of it, or a star import of its package. A member of a
 * class is not judged here; a lambda's receiver can put any type's members in
 * scope. Exposed's tests call `assertEquals(…)` from kotlin.test and JUnit, or
 * import the JDBC suite's extension; the calls went to the R2DBC suite's
 * extension 3,075 times.
 */
function isKotlinTopLevelVisible(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (n.language !== 'kotlin' || n.filePath === ref.filePath) return true;
  const enclosed = context
    .getNodesInFile(n.filePath)
    .some((o) => o.id !== n.id && KOTLIN_ENCLOSING_KINDS.has(o.kind) && o.startLine <= n.startLine && o.endLine >= n.endLine &&
      (o.startLine < n.startLine || o.endLine > n.endLine));
  if (enclosed) return true;
  const pkg = kotlinFileScope(n.filePath, context).pkg;
  const here = kotlinFileScope(ref.filePath, context);
  return pkg === here.pkg || here.stars.has(pkg) || here.imports.has(pkg ? `${pkg}.${n.name}` : n.name) || KOTLIN_DEFAULT_IMPORTS.has(pkg);
}

/**
 * Whether a Kotlin method found by its type's name can be called from the
 * reference's file. A member of a class in its file's package (`p::Modes::x`)
 * can; an extension, `fun Modes.hidden()` indexed as `Modes::hidden`, is
 * top-level, so only from its own package or through an import of it or its
 * package (isKotlinTopLevelVisible).
 */
export function isKotlinExtensionInScope(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (n.language !== 'kotlin' || n.kind !== 'method' || n.filePath === ref.filePath) return true;
  const pkg = kotlinFileScope(n.filePath, context).pkg;
  if (pkg && n.qualifiedName.startsWith(`${pkg}::`)) return true;
  return isKotlinTopLevelVisible(n, ref, context);
}

const PHP_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'trait', 'interface', 'enum']);
const PHP_SUPERS = new WeakMap<ResolutionContext, Map<string, string[]>>();

/**
 * How a bare PHP method name was written at its call site: `$this->m()` /
 * `self::m()` / `static::m()` are the enclosing class's own (or inherited)
 * methods, `parent::m()` an ancestor's; null for anything else.
 */
function phpSelfReceiver(ref: UnresolvedRef, context: ResolutionContext): 'self' | 'parent' | null {
  if (ref.language !== 'php' || ref.referenceKind !== 'calls' || !/^\w+$/.test(ref.referenceName)) return null;
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (!line) return null;
  const name = ref.referenceName;
  if (new RegExp(String.raw`\$this\s*\??->\s*${name}\s*\(|\b(?:self|static)\s*::\s*${name}\s*\(`).test(line)) return 'self';
  if (new RegExp(String.raw`\bparent\s*::\s*${name}\s*\(`).test(line)) return 'parent';
  return null;
}

/**
 * Whether `method` belongs to the class the call is written in, one it
 * extends, or a trait any of them uses — read from source, since the
 * resolver's supertype edges don't exist yet on the first pass, and resolved
 * the way PHP resolves a class name: through the file's `namespace` and `use`
 * imports (aliases included) to one fully qualified class. A parent outside
 * the repository (PHPUnit's TestCase, Orchestra's) ends the chain. Drupal's
 * `$this->assertEquals()` is PHPUnit's; it went to the one in-repo
 * `assertEquals`, a comparator's, 8,832 times.
 */
function isPhpMethodInScope(method: Node, ref: UnresolvedRef, via: 'self' | 'parent', context: ResolutionContext): boolean {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut < 0) return true;
  const ownerQn = method.qualifiedName.slice(0, cut);
  const enclosing = context
    .getNodesInFile(ref.filePath)
    .filter((n) => PHP_TYPE_KINDS.has(n.kind) && n.startLine <= ref.line && n.endLine >= ref.line)
    .sort((a, b) => b.startLine - a.startLine)[0];
  // Inside a trait, `$this` is whichever class uses it: Laravel's
  // ValidatesAttributes calls the Validator's `getValue()`.
  if (!enclosing || enclosing.kind === 'trait') return true;
  const up = phpAncestry(via === 'parent' ? phpSupertypeQns(enclosing, context) : [enclosing.qualifiedName], context);
  if (up.qns.has(ownerQn)) return true;
  // A base class may call what a subclass defines (BookStack's Entity calls
  // `$this->chapter()`, a Page method): the owner descends from the caller.
  if (via === 'self' && phpAncestry([ownerQn], context).qns.has(enclosing.qualifiedName)) return true;
  // Past an ancestor outside the repository (Orchestra's TestCase) that
  // ancestor's members are unseen — the repository's traits it uses among
  // them. A trait's method may still be the one meant; an unrelated class's
  // (Drupal's comparator `assertEquals`) never is.
  return up.leavesRepo && context.getNodesByQualifiedName(ownerQn).some((d) => d.kind === 'trait');
}

/**
 * Whether a PHP receiver is named after a class that has `method` in its
 * ancestry: `$page->save()` → Page, which extends Entity; `$newRole->users()`
 * → Role. BookStack's `$role->save()` is not Entity's (Role is a Model).
 */
function phpReceiverReaches(receiver: string, method: Node, context: ResolutionContext): boolean {
  const cut = method.qualifiedName.lastIndexOf('::');
  if (cut < 0) return false;
  const owner = method.qualifiedName.slice(0, cut);
  const last = receiver.split('.').pop()!.replace(/^\$/, '');
  if (!last) return false;
  const words = splitCamelCase(last);
  const names = new Set([last, words[words.length - 1] ?? last].map((w) => w.charAt(0).toUpperCase() + w.slice(1)));
  for (const name of names) {
    for (const decl of context.getNodesByName(name)) {
      if (decl.language !== 'php' || !PHP_TYPE_KINDS.has(decl.kind)) continue;
      if (phpAncestry([decl.qualifiedName], context).qns.has(owner)) return true;
    }
  }
  return false;
}

/** Every type `start` reaches through `extends` and trait `use`, and whether it left the repository on the way. */
function phpAncestry(start: readonly string[], context: ResolutionContext): { qns: Set<string>; leavesRepo: boolean } {
  const qns = new Set<string>();
  const queue = [...start];
  let leavesRepo = false;
  while (queue.length > 0 && qns.size < 80) {
    const qn = queue.shift()!;
    if (qns.has(qn)) continue;
    qns.add(qn);
    const decls = context.getNodesByQualifiedName(qn).filter((d) => d.language === 'php' && PHP_TYPE_KINDS.has(d.kind));
    if (decls.length === 0) leavesRepo = true;
    for (const decl of decls) queue.push(...phpSupertypeQns(decl, context));
  }
  return { qns, leavesRepo };
}

const PHP_FILE_SCOPES = new WeakMap<ResolutionContext, Map<string, { namespace: string; uses: Map<string, string> }>>();

/** A PHP file's `namespace` and its `use A\B\C [as D];` imports, alias → fully qualified name. */
function phpFileScope(file: string, context: ResolutionContext): { namespace: string; uses: Map<string, string> } {
  let memo = PHP_FILE_SCOPES.get(context);
  if (!memo) PHP_FILE_SCOPES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const text = context.readFile(file) ?? '';
  const namespace = /^\s*namespace\s+([\w\\]+)\s*[;{]/m.exec(text)?.[1] ?? '';
  const uses = new Map<string, string>();
  // File-level imports sit before the first type; a trait `use` inside a class body is not one.
  const header = text.slice(0, text.search(/^\s*(?:(?:abstract|final|readonly)\s+)*(?:class|trait|interface|enum)\s/m) >>> 0 || text.length);
  for (const m of header.matchAll(/^\s*use\s+(?:function\s+|const\s+)?([\w\\]+)(?:\s+as\s+(\w+))?\s*;/gm)) {
    const fqn = m[1]!.replace(/^\\/, '');
    uses.set(m[2] ?? fqn.split('\\').pop()!, fqn);
  }
  const scope = { namespace, uses };
  memo.set(file, scope);
  return scope;
}

/** The qualified name (`A\B::C`) a PHP class name written in `file` refers to. */
function phpTypeQn(name: string, file: string, context: ResolutionContext): string {
  let fqn: string;
  if (name.startsWith('\\')) fqn = name.slice(1);
  else {
    const { namespace, uses } = phpFileScope(file, context);
    const [head, ...rest] = name.split('\\');
    const imported = uses.get(head!);
    fqn = imported ? [imported, ...rest].join('\\') : namespace ? `${namespace}\\${name}` : name;
  }
  const at = fqn.lastIndexOf('\\');
  return at < 0 ? fqn : `${fqn.slice(0, at)}::${fqn.slice(at + 1)}`;
}

/** The qualified names a PHP class or trait extends and the traits it uses. */
function phpSupertypeQns(decl: Node, context: ResolutionContext): string[] {
  let memo = PHP_SUPERS.get(context);
  if (!memo) {
    memo = new Map();
    PHP_SUPERS.set(context, memo);
  }
  const hit = memo.get(decl.id);
  if (hit) return hit;
  const names: string[] = [];
  const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
  const head = lines.slice(decl.startLine - 1, decl.startLine + 4).join(' ');
  const extended = /\bextends\s+([^{]*?)(?:\bimplements\b|\{)/.exec(head)?.[1] ?? '';
  for (const m of extended.matchAll(/(\\?[A-Za-z_][\w\\]*)/g)) names.push(m[1]!);
  // `use StringTranslationTrait, MessengerTrait;` at the top of the body —
  // one per line or one list across several (Laravel's Command, Model).
  const bodyLines = lines.slice(decl.startLine, Math.min(decl.endLine, decl.startLine + 80));
  const firstFunction = bodyLines.findIndex((l) => /\bfunction\b/.test(l));
  const body = bodyLines.slice(0, firstFunction < 0 ? bodyLines.length : firstFunction).join('\n');
  for (const used of body.matchAll(/^\s*use\s+([\w\\,\s]+?)\s*[;{]/gm)) {
    for (const t of used[1]!.split(',')) if (t.trim()) names.push(t.trim());
  }
  const qns = names.map((n) => phpTypeQn(n, decl.filePath, context));
  memo.set(decl.id, qns);
  return qns;
}

/** Names the Rust prelude puts in every module; a project item of the same name needs a `use` to shadow one. */
const RUST_PRELUDE = new Set([
  'Ok', 'Err', 'Some', 'None', 'Result', 'Option', 'Box', 'Vec', 'String', 'Default', 'Drop', 'Iterator',
  'IntoIterator', 'From', 'Into', 'Clone', 'Copy', 'Send', 'Sync', 'Sized', 'ToString', 'ToOwned', 'PartialEq',
  'Eq', 'PartialOrd', 'Ord', 'AsRef', 'AsMut', 'Fn', 'FnMut', 'FnOnce', 'Extend', 'drop',
]);

interface RustUses {
  /** Every identifier in the file's project `use` trees — not `std::` / `core::` / `alloc::` ones. */
  names: Set<string>;
  /** `X` of each `use …::X::*` (`super` for `use super::*`). */
  globs: Set<string>;
  /** Names the file imports from outside the project — `use std::task::{Context, Poll}`, `use futures::Stream`. */
  external: Set<string>;
  /** The items the file's project `use`s bind — their leaves, not the paths they walk. */
  bound: Set<string>;
  /** Each bound item → the first segment of every path that binds it (`crate`, `super`, `tokio_test`). */
  boundFrom: Map<string, Set<string>>;
  /** Each name a project `use` binds → the paths that bind it (`Receiver` → `crate::sync::watch::Receiver`). */
  paths: Map<string, RustUsePath[]>;
  /** Each name a `use` from the standard library binds → those paths (`fs` → `std::fs`). */
  stdPaths: Map<string, RustUsePath[]>;
  /** The modules its project `use … ::*` globs bring in, as paths. */
  globPaths: RustUsePath[];
  /** The modules the file declares inline (`mod tests { … }`), in source order. */
  blocks: RustModBlock[];
  /** Modules it declares with a `#[path = "…"]` of their own (often one per cfg), whose file can't be told from their name. */
  pathMods: Set<string>;
  /** Modules it declares out of line with no `#[path]` (`mod name;`): the files the regular rules name. */
  mods: Set<string>;
  /** Whether it starts a binary of its own: a top-level `fn main` or `#![no_main]` (a trybuild case, a fuzz target). */
  main: boolean;
  /** Whether every brace closes, so `blocks` can be trusted to say what is inside them. */
  balanced: boolean;
  /** The offset each line starts at. */
  lineStarts: number[];
}

interface RustUsePath {
  /** The path as written, less any `as` alias: `['crate', 'sync', 'watch', 'Receiver']`. */
  segs: string[];
  /** The offset of its `use` in the file, which decides the module the path starts from. */
  at: number;
  /** A `pub use` (of any reach), which a glob over its module passes on. */
  pub: boolean;
  /**
   * The braces of the block it is written in — a function's body, a block in
   * one — where alone it binds its name, rather than in its module. Undefined
   * for a `use` of the module itself: at a file's top level, in an inline
   * `mod … { }`, or in a macro's braces there (`cfg_rt! { use …; }`).
   */
  scope?: RustUseScope;
}

/** A block a `use` is written in, by the offsets of its braces. */
interface RustUseScope {
  open: number;
  close: number;
}

/** An inline `mod name { … }`, by the offsets of its braces. */
interface RustModBlock {
  name: string;
  open: number;
  close: number;
  /** The inline module it is declared in, or null for the file's own top level. */
  parent: RustModBlock | null;
}

const RUST_CRATES = new WeakMap<ResolutionContext, Set<string>>();
const RUST_DEPENDENCIES = new WeakMap<ResolutionContext, Set<string>>();

interface RustManifestDependency {
  /** The name code writes for it (`futures_util`). */
  key: string;
  /** The package it is: its key, unless `package = "…"` renames it. */
  pkg: string;
  /** Its `path = "…"`, from the manifest's directory. */
  path?: string;
  /** `workspace = true`: the workspace's `[workspace.dependencies]` declares it. */
  workspace: boolean;
  /** `[dependencies]` (per-target ones included), dev, build, or `[workspace.dependencies]`. */
  kind: 'normal' | 'dev' | 'build' | 'workspace';
}

/**
 * A Cargo manifest's dependencies, however each is written: `foo = "1"`, an
 * inline table, dotted keys (`foo.workspace = true`) or a `[dependencies.foo]`
 * table of its own.
 */
function rustManifestDependencies(text: string): RustManifestDependency[] {
  const deps = new Map<string, RustManifestDependency>();
  const entry = (kind: RustManifestDependency['kind'], name: string): RustManifestDependency => {
    const key = name.replace(/-/g, '_');
    let dep = deps.get(`${kind} ${key}`);
    if (!dep) deps.set(`${kind} ${key}`, (dep = { key, pkg: key, workspace: false, kind }));
    return dep;
  };
  const read = (dep: RustManifestDependency, fields: string): void => {
    const pkg = /\bpackage\s*=\s*"([^"]+)"/.exec(fields)?.[1];
    if (pkg) dep.pkg = pkg.replace(/-/g, '_');
    const at = /\bpath\s*=\s*"([^"]+)"/.exec(fields)?.[1];
    if (at) dep.path = at.replace(/\\/g, '/');
    if (/\bworkspace\s*=\s*true\b/.test(fields)) dep.workspace = true;
  };
  let kind: RustManifestDependency['kind'] | null = null;
  let table: RustManifestDependency | null = null;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*$/, '').trim();
    const header = /^\[([^\]]+)\]$/.exec(line);
    if (header) {
      const m = /^(?:(workspace)\.|target\..+\.)?(dev-|build-)?dependencies(?:\.([A-Za-z0-9_-]+))?$/.exec(header[1]!.trim());
      const of = !m ? null : m[1] ? 'workspace' : m[2] === 'dev-' ? 'dev' : m[2] === 'build-' ? 'build' : 'normal';
      kind = of !== null && !m![3] ? of : null;
      table = of !== null && m![3] ? entry(of, m![3]) : null;
      continue;
    }
    if (table) {
      read(table, line);
      continue;
    }
    const dep = kind === null ? null : /^"?([A-Za-z0-9_-]+)"?\s*(?:\.\s*([A-Za-z_-]+)\s*)?=\s*(.*)$/.exec(line);
    if (dep) read(entry(kind!, dep[1]!), dep[2] ? `${dep[2]} = ${dep[3]}` : dep[3]!);
  }
  return [...deps.values()];
}

/** The crates the project's manifests depend on, by the name code writes them (`futures_util`), less the project's own. */
function rustDependencyCrates(context: ResolutionContext): Set<string> {
  const hit = RUST_DEPENDENCIES.get(context);
  if (hit) return hit;
  const deps = new Set<string>();
  const manifests = ['Cargo.toml', ...[...getCargoWorkspaceCrateMap(context).values()].map((dir) => `${dir}/Cargo.toml`)];
  for (const manifest of new Set(manifests)) {
    for (const { key } of rustManifestDependencies(context.readFile(manifest) ?? '')) deps.add(key);
  }
  for (const own of rustProjectCrates(context)) deps.delete(own);
  RUST_DEPENDENCIES.set(context, deps);
  return deps;
}

interface RustCrate {
  /** Its package name as code writes it (`tokio_test`). */
  name: string;
  /** Each dependency of any kind that is a project crate: the name code writes → that crate's directory. */
  keys: Map<string, string>;
  /** The project crates its `[dependencies]` name, by directory: the ones it can re-export from. */
  deps: Set<string>;
  /** The library root its manifest gives a `path` of its own (`[lib] path = …`), as a project file. */
  lib?: string;
  /** The binaries' roots its manifest gives a `path` (ripgrep's `crates/core/main.rs`), as project files. */
  bins: string[];
  /** The examples', tests' and benches' roots its manifest gives a `path`, as project files: each its own crate. */
  others: string[];
}

interface RustCrateGraph {
  /** The project's crates by directory: the root package's is ''. */
  crates: Map<string, RustCrate>;
  /** A crate's directory → itself and every project crate it depends on, transitively. */
  reach: Map<string, Set<string>>;
  /** A file → the directory of the crate it is in, or null for none the manifests name. */
  fileCrate: Map<string, string | null>;
}

const RUST_CRATE_GRAPHS = new WeakMap<ResolutionContext, RustCrateGraph>();

/**
 * The project's crates — the root package, the workspace's members and the
 * path dependencies they name — and which of them each depends on. A
 * dependency is found by its `path` (its own or, for `workspace = true`, the
 * workspace's), so a renamed key or a crate outside the members still lands;
 * without one, by its package name.
 */
function rustCrateGraph(context: ResolutionContext): RustCrateGraph {
  const hit = RUST_CRATE_GRAPHS.get(context);
  if (hit) return hit;
  const crates = new Map<string, RustCrate>();
  const manifests = new Map<string, string>();
  const byName = new Map<string, string>();
  // A path a manifest in `dir` writes, as a project path; null when it leaves
  // the project, which nothing here reads or names.
  const join = (dir: string, rel: string): string | null => {
    const joined = path.posix.normalize(dir === '' ? rel : `${dir}/${rel}`).replace(/\/+$/, '');
    return joined === '.' ? '' : escapesRoot(joined) ? null : joined;
  };
  const add = (dir: string): boolean => {
    if (crates.has(dir)) return true;
    const text = context.readFile(dir === '' ? 'Cargo.toml' : `${dir}/Cargo.toml`);
    // By its section: axum-core's manifest writes `categories = [ … ]` above its `name`.
    const name = text ? parsePackageName(text)?.replace(/-/g, '_') : undefined;
    if (!name) return false;
    const targets = parseTargetPaths(text!);
    const lib = targets.lib === undefined ? null : join(dir, targets.lib);
    const files = (rels: string[]): string[] => rels.map((rel) => join(dir, rel)).filter((file): file is string => file !== null);
    crates.set(dir, { name, keys: new Map(), deps: new Set(), lib: lib ?? undefined, bins: files(targets.bins), others: files(targets.others) });
    manifests.set(dir, text!);
    if (!byName.has(name)) byName.set(name, dir);
    return true;
  };
  add('');
  for (const member of getCargoWorkspaceCrateMap(context).values()) {
    const dir = join('', member);
    if (dir !== null) add(dir);
  }
  const inherited = new Map(rustManifestDependencies(context.readFile('Cargo.toml') ?? '')
    .filter((dep) => dep.kind === 'workspace').map((dep) => [dep.key, dep]));
  const queue = [...crates.keys()];
  for (let i = 0; i < queue.length; i++) {
    const dir = queue[i]!;
    const crate = crates.get(dir)!;
    for (const dep of rustManifestDependencies(manifests.get(dir)!)) {
      if (dep.kind === 'workspace') continue;
      const shared = dep.workspace ? inherited.get(dep.key) : undefined;
      const at = shared ? (shared.path === undefined ? null : join('', shared.path)) : dep.path === undefined ? null : join(dir, dep.path);
      let to: string | undefined;
      if (at !== null && !crates.has(at) && add(at)) queue.push(at);
      if (at !== null && crates.has(at)) to = at;
      else to = byName.get(shared?.pkg ?? dep.pkg);
      if (to === undefined || to === dir) continue;
      crate.keys.set(dep.key, to);
      if (dep.kind === 'normal') crate.deps.add(to);
    }
  }
  const reach = new Map<string, Set<string>>();
  for (const dir of crates.keys()) {
    const seen = new Set([dir]);
    const pending = [dir];
    for (let next = pending.pop(); next !== undefined; next = pending.pop()) {
      for (const to of crates.get(next)!.deps) {
        if (seen.has(to)) continue;
        seen.add(to);
        pending.push(to);
      }
    }
    reach.set(dir, seen);
  }
  const graph = { crates, reach, fileCrate: new Map<string, string | null>() };
  RUST_CRATE_GRAPHS.set(context, graph);
  return graph;
}

/** The directory of the crate `filePath` is in: the deepest one that holds it, the root package's (''), or null. */
function rustCrateDirOf(filePath: string, graph: RustCrateGraph): string | null {
  const hit = graph.fileCrate.get(filePath);
  if (hit !== undefined) return hit;
  let best: string | null = graph.crates.has('') ? '' : null;
  for (const dir of graph.crates.keys()) {
    if (dir !== '' && filePath.startsWith(`${dir}/`) && (best === null || dir.length > best.length)) best = dir;
  }
  graph.fileCrate.set(filePath, best);
  return best;
}

/**
 * Whether a `use` path from one of `roots` can name this candidate, by its
 * crate. A path from a crate the file's own manifest depends on (`use
 * tokio_test::task::spawn`), or from its own crate's name, names that crate's
 * item or one it re-exports from a crate its `[dependencies]` name, in turn
 * (`clap::Command` is clap_builder's); `crate::`, `self::` and `super::` start
 * from the file's own crate. tokio's tests' 133 `spawn(…)` calls are
 * tokio-test's, never the examples crate's `pub fn spawn`, which nothing
 * depends on. Any other path — through a module, a crate from outside the
 * project — and a file in no crate the manifests name say nothing.
 */
function rustUseCanReach(roots: Set<string>, candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const graph = rustCrateGraph(context);
  const at = rustCrateDirOf(candidate.filePath, graph);
  const own = rustCrateDirOf(ref.filePath, graph);
  if (at === null || own === null) return true;
  const crate = graph.crates.get(own)!;
  for (const root of roots) {
    const from = root === 'crate' || root === 'self' || root === 'super' || root === crate.name ? own : crate.keys.get(root);
    if (from === undefined || graph.reach.get(from)!.has(at)) return true;
  }
  return false;
}

/** The project's own crate names (`tokio`, `tokio_util`), from its Cargo.toml files. */
function rustProjectCrates(context: ResolutionContext): Set<string> {
  const hit = RUST_CRATES.get(context);
  if (hit) return hit;
  const crates = new Set<string>();
  // The manifests are not indexed files: the root's package, and the workspace's members.
  const root = parsePackageName(context.readFile('Cargo.toml') ?? '');
  if (root) crates.add(root.replace(/-/g, '_'));
  for (const name of getCargoWorkspaceCrateMap(context).keys()) crates.add(name.replace(/-/g, '_'));
  RUST_CRATES.set(context, crates);
  return crates;
}
const RUST_USES = new WeakMap<ResolutionContext, Map<string, RustUses>>();

function rustUsesOf(filePath: string, context: ResolutionContext): RustUses {
  let memo = RUST_USES.get(context);
  if (!memo) {
    memo = new Map();
    RUST_USES.set(context, memo);
  }
  const hit = memo.get(filePath);
  if (hit) return hit;
  const uses: RustUses = {
    names: new Set(), globs: new Set(), external: new Set(), bound: new Set(), boundFrom: new Map(),
    paths: new Map(), stdPaths: new Map(), globPaths: [], blocks: [], pathMods: new Set(), mods: new Set(), main: false, balanced: true, lineStarts: [],
  };
  const leaves = (tree: string): string[] => [
    ...[...tree.matchAll(/([A-Za-z_]\w*)\s*(?=[,}]|$|\s+as\b)|\bas\s+([A-Za-z_]\w*)/g)]
      .map((leaf) => leaf[2] ?? leaf[1]!).filter((id) => id !== 'self' && id !== 'as'),
    // `use std::io::{self, Read}` binds `io` too.
    ...[...tree.matchAll(/([A-Za-z_]\w*)\s*::\s*\{[^{}]*\bself\b/g)].map((m) => m[1]!),
  ];
  const bind = (map: Map<string, RustUsePath[]>, local: string, path: RustUsePath): void => {
    const list = map.get(local);
    if (list) list.push(path);
    else map.set(local, [path]);
  };
  // Comments and strings blanked first: a doc comment's prose ("…use the
  // Option…"), a string's `"use crate::x;"` is no `use`.
  const text = blankRustCode(context.readFile(filePath) ?? '');
  const dependencies = rustDependencyCrates(context);
  const matches = [...text.matchAll(/(?:^|[;{}\s])use\s+([^;]{1,2000});/g)];
  const kws = matches.map((m) => m.index! + m[0].indexOf('use'));
  // The braces are read for inline modules, and for the block a `use` is in
  // when one may be in a block: indented, or after a brace on its line.
  let braces: number[] | undefined;
  const codeBraces = (): number[] => (braces ??= rustCodeBraces(text));
  const layout = rustModBlocks(text, codeBraces);
  uses.blocks = layout.blocks;
  uses.balanced = layout.balanced;
  // (Braces that don't pair say nothing: every `use` then counts for its module.)
  const nested = kws.some((kw) => /^\s|[{}]/.test(text.slice(text.lastIndexOf('\n', kw - 1) + 1, kw)));
  const scopes = nested ? rustUseScopes(text, kws, codeBraces(), new Set(layout.blocks.map((b) => b.open))) : null;
  matches.forEach((m, i) => {
    const tree = m[1]!;
    const root = /^\s*(?:::)?([A-Za-z_]\w*)/.exec(tree)?.[1] ?? '';
    // Outside: the standard library or a crate the manifests depend on — not a
    // module of the project's (`mod support { … }` inline in a test).
    const outside = root === 'std' || root === 'core' || root === 'alloc' || (root !== '' && dependencies.has(root));
    // Every path, outside ones too: walked, a path dependency on a crate the
    // workspace doesn't list is the project's (a facade's `pub use shared::Thing`).
    const kw = kws[i]!;
    const pub = /\bpub(?:\s*\([^()]*\))?\s*$/.test(text.slice(Math.max(0, kw - 48), kw));
    const scope = scopes?.[i];
    for (const { segs, local } of rustUseTreeBindings(tree)) {
      // A macro's own `use $crate::…` names no module of this file's.
      if (segs.length === 0 || segs[0]!.startsWith('$')) continue;
      const path: RustUsePath = scope ? { segs, at: m.index!, pub, scope } : { segs, at: m.index!, pub };
      // The standard library's: what its name means where the `use` reaches.
      if (RUST_STD_ROOTS.has(segs[0]!)) {
        if (local !== null) bind(uses.stdPaths, local, path);
        continue;
      }
      if (local === null) uses.globPaths.push(path);
      else bind(uses.paths, local, path);
    }
    // The items it binds: each leaf (`as` aliases by their alias), never the path it walks.
    if (outside) {
      for (const id of leaves(tree)) uses.external.add(id);
      return;
    }
    for (const id of leaves(tree)) {
      uses.bound.add(id);
      const from = uses.boundFrom.get(id);
      if (from) from.add(root);
      else uses.boundFrom.set(id, new Set([root]));
    }
    for (const id of tree.matchAll(/[A-Za-z_]\w*/g)) uses.names.add(id[0]);
    for (const g of tree.matchAll(/(\w+)\s*::\s*(?:\{[^}]*)?\*/g)) uses.globs.add(g[1]!);
  });
  // `#[path = "atomic_u64_native.rs"] mod imp;`, `#[cfg_attr(docsrs, path = "…")] pub mod de;`
  const pathModAt = new Set<number>();
  for (const m of text.matchAll(/#\[\s*(?:cfg_attr\s*\([^\]]*\bpath|path)\s*=[^\]]*\]\s*(?:#!?\[[^\]]*\]\s*)*(?:pub(?:\([^)]*\))?\s+)?mod\s+(?:r#)?([A-Za-z_]\w*)/g)) {
    uses.pathMods.add(m[1]!);
    pathModAt.add(m.index! + m[0].search(/\bmod\s+(?:r#)?[A-Za-z_]\w*$/));
  }
  // `mod name;` with no `#[path]` of its own.
  for (const m of text.matchAll(/\bmod\s+(?:r#)?([A-Za-z_]\w*)\s*;/g)) {
    if (!pathModAt.has(m.index!)) uses.mods.add(m[1]!);
  }
  uses.main = /^(?:pub\s+)?(?:async\s+)?fn\s+main\s*\(|^[ \t]*#!\[\s*no_main\s*\]/m.test(text);
  for (let at = 0; at !== -1; at = text.indexOf('\n', at) + 1 || -1) uses.lineStarts.push(at);
  memo.set(filePath, uses);
  return uses;
}

/** Roots that name a crate of the standard library. */
const RUST_STD_ROOTS: ReadonlySet<string> = new Set(['std', 'core', 'alloc', 'proc_macro']);

/**
 * What one `use` tree binds, by the path each binding names: `crate::sync::{
 * watch::{self, Receiver as Rx}, *}` binds `watch` to `crate::sync::watch` and
 * `Rx` to `crate::sync::watch::Receiver`, and globs `crate::sync` (local null).
 */
function rustUseTreeBindings(tree: string): Array<{ segs: string[]; local: string | null }> {
  const tokens = tree.match(/(?:r#)?\$?[A-Za-z_]\w*|::|[{},*]/g) ?? [];
  const out: Array<{ segs: string[]; local: string | null }> = [];
  let i = 0;
  // One tree under `prefix`: a path, then a `{ … }` group, a `*`, or an `as` alias.
  const read = (prefix: string[]): void => {
    const segs = [...prefix];
    while (i < tokens.length) {
      const t = tokens[i]!;
      if (t === '::') {
        i++;
        continue;
      }
      if (t === '*') {
        i++;
        out.push({ segs, local: null });
        return;
      }
      if (t === '{') {
        i++;
        while (i < tokens.length && tokens[i] !== '}') {
          const before = i;
          read(segs);
          if (tokens[i] === ',' || i === before) i++;
        }
        i++;
        return;
      }
      if (t === ',' || t === '}' || (t === 'as' && segs.length > prefix.length)) break;
      segs.push(t.startsWith('r#') ? t.slice(2) : t);
      i++;
      if (tokens[i] !== '::') break;
    }
    if (segs.length === prefix.length) return;
    let local: string | undefined;
    if (tokens[i] === 'as') {
      local = tokens[i + 1];
      i += 2;
    }
    // `watch::{self, …}` binds the module itself.
    if (segs[segs.length - 1] === 'self') segs.pop();
    local ??= segs[segs.length - 1];
    if (segs.length > 0 && local !== undefined && local !== '_' && /^[A-Za-z_]\w*$/.test(local)) out.push({ segs, local });
  };
  while (i < tokens.length) {
    const before = i;
    read([]);
    if (i === before) i++;
  }
  return out;
}

/** The offsets of the braces in `text` (comments already blanked) that are code: none in a string or char literal. */
function rustCodeBraces(text: string): number[] {
  const braces: number[] = [];
  const scan = /[{}]|\b(?:b?r(#*)")|"|'/g;
  for (let m = scan.exec(text); m; m = scan.exec(text)) {
    const at = m.index;
    const c = m[0];
    if (c === '{' || c === '}') {
      braces.push(at);
    } else if (c === "'") {
      // A char literal (`'{'`, `'\''`, `'\u{7f}'`) — any other quote starts a lifetime or a label.
      const lit = /^'(?:\\(?:u\{[0-9A-Fa-f]{1,6}\}|x[0-9A-Fa-f]{2}|.)|[^\\'\n])'/.exec(text.slice(at, at + 12));
      if (lit) scan.lastIndex = at + lit[0].length;
    } else if (c === '"') {
      // The next quote no odd run of backslashes escapes.
      let end = at;
      for (;;) {
        end = text.indexOf('"', end + 1);
        let slashes = 0;
        while (end > 0 && text[end - 1 - slashes] === '\\') slashes++;
        if (end < 0 || slashes % 2 === 0) break;
      }
      scan.lastIndex = end < 0 ? text.length : end + 1;
    } else {
      // A raw string: `r#"…"#` closes only at a quote followed by as many `#`s.
      const close = text.indexOf(`"${m[1]}`, at + c.length);
      scan.lastIndex = close < 0 ? text.length : close + 1 + m[1]!.length;
    }
  }
  return braces;
}

/** The inline `mod name { … }` blocks of a file's text (comments already blanked), in source order. */
function rustModBlocks(text: string, codeBraces: () => readonly number[] = () => rustCodeBraces(text)): { blocks: RustModBlock[]; balanced: boolean } {
  const heads = new Map<number, string>();
  for (const m of text.matchAll(/\bmod\s+(?:r#)?([A-Za-z_]\w*)\s*\{/g)) heads.set(m.index! + m[0].length - 1, m[1]!);
  const blocks: RustModBlock[] = [];
  if (heads.size === 0) return { blocks, balanced: true };
  const open: Array<RustModBlock | null> = [];
  let inner: RustModBlock | null = null;
  let balanced = true;
  // A head whose `{` is in a string is never among the braces.
  for (const at of codeBraces()) {
    if (text[at] === '{') {
      const name = heads.get(at);
      const block: RustModBlock | null = name === undefined ? null : { name, open: at, close: text.length, parent: inner };
      if (block) {
        blocks.push(block);
        inner = block;
      }
      open.push(block);
      continue;
    }
    if (open.length === 0) {
      balanced = false;
      continue;
    }
    const closed = open.pop();
    if (closed) {
      closed.close = at;
      inner = closed.parent;
    }
  }
  return { blocks, balanced: balanced && open.length === 0 };
}

/**
 * The block each `use` at `kws` (ascending offsets) is written in, read from
 * the file's code braces: the innermost one around it — a function's body, a
 * block in one — that is no module's own. An inline `mod … {` is the module's,
 * and a macro's braces (`cfg_rt! {`, `macro_rules! m {`), with every brace in
 * them, are the scope around them: tokio's `cfg_sync! { pub use … }` and a
 * `cfg_if! { if #[cfg(unix)] { pub use … } }` are the module's own `use`s.
 * Undefined for a `use` of its module; null when the braces don't pair.
 */
function rustUseScopes(text: string, kws: readonly number[], braces: readonly number[], modOpens: ReadonlySet<number>): Array<RustUseScope | undefined> | null {
  const out: Array<RustUseScope | undefined> = [];
  const open: Array<RustUseScope | 'module' | 'macro'> = [];
  const innermost = (): RustUseScope | undefined => {
    for (let i = open.length - 1; i >= 0; i--) {
      const e = open[i]!;
      if (e !== 'macro') return e === 'module' ? undefined : e;
    }
    return undefined;
  };
  let k = 0;
  for (const at of braces) {
    while (k < kws.length && kws[k]! < at) out[k++] = innermost();
    if (text.charCodeAt(at) === 123) {
      open.push(modOpens.has(at) ? 'module'
        : open[open.length - 1] === 'macro' || isRustMacroBrace(text, at) ? 'macro' : { open: at, close: text.length });
      continue;
    }
    const closed = open.pop();
    if (closed === undefined) return null;
    if (typeof closed === 'object') closed.close = at;
  }
  if (open.length > 0) return null;
  while (k < kws.length) out[k++] = innermost();
  return out;
}

/** Whether the `{` at `at` opens a macro's input: `name! {`, `path::name! {`, `macro_rules! name {`. */
function isRustMacroBrace(text: string, at: number): boolean {
  let p = at - 1;
  while (p >= 0 && /\s/.test(text[p]!)) p--;
  if (text[p] === '!') return true;
  // `macro_rules! name {`: the name, then the `!` before it.
  let q = p;
  while (q >= 0 && /\w/.test(text[q]!)) q--;
  if (q === p) return false;
  while (q >= 0 && /\s/.test(text[q]!)) q--;
  return text[q] === '!' && /\bmacro_rules\s*$/.test(text.slice(Math.max(0, q - 24), q));
}

/** The innermost inline module whose braces hold `offset`, or null for the file's top level. */
function rustBlockAt(blocks: readonly RustModBlock[], offset: number): RustModBlock | null {
  let at: RustModBlock | null = null;
  for (const b of blocks) {
    if (b.open > offset) break;
    if (offset < b.close) at = b;
  }
  return at;
}

/** A Rust module, by where its items are written. */
interface RustModule {
  /** The file its items are written in. */
  file: string;
  /** Where the files of the modules it declares live: `src/sync` for `src/sync/mod.rs` and `src/sync.rs` alike. */
  dir: string;
  /** Its block, for a module declared inline (`mod futures { … }`); null for the file's own. */
  block: RustModBlock | null;
  /** A crate's root — `lib.rs`, `main.rs`, a test target's file — which nothing is above. */
  root: boolean;
  /** The package's other root, which holds crate-root items too: the `main.rs` beside its `lib.rs`. */
  alt?: string;
}

const rustJoin = (dir: string, name: string): string => (dir === '' ? name : `${dir}/${name}`);
const rustParentDir = (p: string): string => p.slice(0, Math.max(0, p.lastIndexOf('/')));

/** Whether a Rust file is a Cargo target's root: `src/lib.rs`, `src/main.rs`, `src/bin/x.rs`, `tests/x.rs`, `build.rs`, … */
function isRustTargetRoot(filePath: string, context: ResolutionContext): boolean {
  const graph = rustCrateGraph(context);
  const dir = rustCrateDirOf(filePath, graph);
  if (dir === null) return /(?:^|\/)(?:lib|main)\.rs$/.test(filePath);
  const crate = graph.crates.get(dir);
  if (crate && (crate.lib === filePath || crate.bins.includes(filePath) || crate.others.includes(filePath))) return true;
  const rel = dir === '' ? filePath : filePath.slice(dir.length + 1);
  return /^(?:src\/(?:lib|main)\.rs|src\/bin\/[^/]+(?:\.rs|\/main\.rs)|(?:tests|examples|benches)\/[^/]+(?:\.rs|\/main\.rs)|build\.rs)$/.test(rel);
}

/** A `#[path = "…"] mod name;` declaration. */
interface RustPathDecl {
  /** The file it is written in, and the offset of its `mod`: the module it is declared in. */
  file: string;
  at: number;
  name: string;
  /**
   * The file it loads, from the project's root, read as the Rust Reference
   * reads the attribute; null for one a `cfg_attr` sets, which the build's
   * cfg decides, or one that leaves the project.
   */
  target: string | null;
}

const RUST_PATH_DECLS = new WeakMap<ResolutionContext, Map<string, readonly RustPathDecl[]>>();
const RUST_PATH_LOADS = new WeakMap<ResolutionContext, Map<string, RustPathDecl[]>>();
const RUST_PATH_LOADERS = new WeakMap<ResolutionContext, Map<string, readonly RustPathDecl[]>>();
const RUST_FILES_BY_DIR = new WeakMap<ResolutionContext, Map<string, string[]>>();
const NO_RUST_PATH_DECLS: readonly RustPathDecl[] = [];
/** An out-of-line module declaration, `pub(crate) mod name;`, from its visibility. */
const RUST_MOD_DECL = /(?:\bpub(?:\s*\([^()]*\))?\s+)?\bmod\s+(?:r#)?([A-Za-z_]\w*)\s*;/g;

/**
 * A file's own `#[path = "…"] mod name;` declarations. The attribute's path
 * is relative to the directory of the file it is written in — or, inside an
 * inline `mod`, to that module's own directory: the file's for a `mod.rs` or
 * a crate root, else the directory named after the file, then the inline
 * modules' names (the Rust Reference, "The path attribute").
 */
function rustPathDeclsIn(file: string, context: ResolutionContext): readonly RustPathDecl[] {
  let memo = RUST_PATH_DECLS.get(context);
  if (!memo) RUST_PATH_DECLS.set(context, (memo = new Map()));
  let decls = memo.get(file);
  if (!decls) memo.set(file, (decls = rustReadPathDecls(file, context)));
  return decls;
}

function rustReadPathDecls(file: string, context: ResolutionContext): readonly RustPathDecl[] {
  let decls: RustPathDecl[] | undefined;
  // Both forms write `path =`: `#[path = "…"]`, `#[cfg_attr(…, path = "…")]`.
  // The bytes are checked first, so a file without the word is never decoded.
  if (!file.endsWith('.rs') || (context.fileContains && !context.fileContains(file, 'path'))) return NO_RUST_PATH_DECLS;
  const src = context.readFile(file);
  if (!src || !/\bpath\s*=/.test(src)) return NO_RUST_PATH_DECLS;
  const code = blankRustCode(src);
  let blocks: RustModBlock[] | undefined;
  for (const m of code.matchAll(RUST_MOD_DECL)) {
    let target: string | null | undefined;
    for (const [from, to] of rustAttributesBefore(code, m.index!)) {
      const raw = src.slice(from, to);
      const plain = /^#\s*\[\s*path\s*=\s*"([^"]*)"\s*\]$/.exec(raw);
      if (plain) target = plain[1]!.replace(/\\/g, '/');
      else if (target === undefined && /^#\s*\[\s*cfg_attr\b[\s\S]*\bpath\s*=/.test(raw)) target = null;
    }
    if (target === undefined) continue;
    // The `mod` keyword's offset (`mod modules;` holds a second `mod`).
    const at = m.index! + /\bmod\s/.exec(m[0])!.index;
    // At the file's top level it is the file's own; only one inside braces
    // (an inline module's, or a macro's) needs the file's block layout.
    const block = rustBraceDepth(code, at) === 0 ? null : rustBlockAt((blocks ??= rustUsesOf(file, context).blocks), at);
    // From the file's directory; in an inline module, from that module's.
    let base = rustParentDir(file);
    if (block) {
      base = isRustTargetRoot(file, context) || /(?:^|\/)mod\.rs$/.test(file) ? base : file.replace(/\.rs$/, '');
      const names: string[] = [];
      for (let b: RustModBlock | null = block; b; b = b.parent) names.unshift(b.name);
      for (const name of names) base = rustJoin(base, name);
    }
    let loads: string | null = null;
    if (target !== null && !/^(?:\/|[A-Za-z]:)/.test(target)) {
      const joined = path.posix.normalize(rustJoin(base, target));
      loads = escapesRoot(joined) ? null : joined;
    }
    (decls ??= []).push({ file, at, name: m[1]!, target: loads });
  }
  return decls ?? NO_RUST_PATH_DECLS;
}

/** How many braces are open at `at` in blanked code. */
function rustBraceDepth(code: string, at: number): number {
  let depth = 0;
  for (let i = 0; i < at; i++) {
    const c = code.charCodeAt(i);
    if (c === 123) depth++;
    else if (c === 125 && depth > 0) depth--;
  }
  return depth;
}

/** Each file a `#[path]` of the project loads → the declarations that load it: every Rust file's, read once. */
function rustPathLoads(context: ResolutionContext): Map<string, RustPathDecl[]> {
  const hit = RUST_PATH_LOADS.get(context);
  if (hit) return hit;
  const out = new Map<string, RustPathDecl[]>();
  RUST_PATH_LOADS.set(context, out);
  for (const file of context.getAllFiles()) {
    for (const decl of rustPathDeclsIn(file, context)) {
      if (decl.target === null) continue;
      const list = out.get(decl.target);
      if (list) list.push(decl);
      else out.set(decl.target, [decl]);
    }
  }
  return out;
}

/** The project's Rust files directly in `dir`. */
function rustFilesIn(dir: string, context: ResolutionContext): readonly string[] {
  let index = RUST_FILES_BY_DIR.get(context);
  if (!index) {
    index = new Map();
    for (const file of context.getAllFiles()) {
      if (!file.endsWith('.rs')) continue;
      const parent = rustParentDir(file);
      const list = index.get(parent);
      if (list) list.push(file);
      else index.set(parent, [file]);
    }
    RUST_FILES_BY_DIR.set(context, index);
  }
  return index.get(dir) ?? [];
}

/**
 * Whether the regular rules place a Rust file: a crate root (one with a
 * `fn main` of its own too, as a trybuild case is), or `name.rs` /
 * `name/mod.rs` that a plain `mod name;` declares in the module owning its
 * directory (that directory's `mod.rs`, the file named after it, or a crate
 * root in it) — or in an inline module of the module owning a directory
 * above it, whose names make up the rest of the path (dioxus's
 * ecommerce-site: `mod components { pub mod home; }` in `src/main.rs` places
 * `src/components/home.rs`). Such a file is that module, whatever else loads it.
 */
function rustPlacedByName(file: string, context: ResolutionContext): boolean {
  if (isRustTargetRoot(file, context) || rustUsesOf(file, context).main) return true;
  const dir = rustParentDir(file);
  const isMod = file === 'mod.rs' || file.endsWith('/mod.rs');
  if (isMod && dir === '') return false;
  const name = path.posix.basename(isMod ? dir : file, '.rs');
  let parent = isMod ? rustParentDir(dir) : dir;
  // The inline modules, outermost first, between the owner's directory and the file's.
  const inline: string[] = [];
  for (let depth = 0; depth < 4; depth++) {
    const owners = [rustJoin(parent, 'mod.rs'), ...(parent === '' ? [] : [`${parent}.rs`])];
    for (const f of rustFilesIn(parent, context)) if (isRustTargetRoot(f, context)) owners.push(f);
    for (const owner of owners) {
      if (owner === file || !context.fileExists(owner)) continue;
      const uses = rustUsesOf(owner, context);
      if (uses.mods.has(name) && (inline.length === 0 || rustHasInlineModules(uses.blocks, inline))) return true;
    }
    if (parent === '') break;
    inline.unshift(path.posix.basename(parent));
    parent = rustParentDir(parent);
  }
  return false;
}

/** Whether a file declares the inline modules `names` (outermost first) nested in one another from its top level. */
function rustHasInlineModules(blocks: readonly RustModBlock[], names: readonly string[]): boolean {
  return blocks.some((block) => {
    let b: RustModBlock | null = block;
    for (let i = names.length - 1; i >= 0; i--) {
      if (!b || b.name !== names[i]) return false;
      b = b.parent;
    }
    return b === null;
  });
}

/**
 * The `#[path]` declarations that load `file`, for a file the regular rules
 * don't place (rustPlacedByName); none for one they do. Only then is every
 * Rust file of the project read for its declarations.
 */
function rustPathLoaders(file: string, context: ResolutionContext): readonly RustPathDecl[] {
  let memo = RUST_PATH_LOADERS.get(context);
  if (!memo) RUST_PATH_LOADERS.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const loaders = !file.endsWith('.rs') || rustPlacedByName(file, context)
    ? NO_RUST_PATH_DECLS
    : rustPathLoads(context).get(file) ?? NO_RUST_PATH_DECLS;
  memo.set(file, loaders);
  return loaders;
}

/** The spans of the outer attributes (`#[…]`) written right before `at` in blanked code, nearest first. */
function rustAttributesBefore(code: string, at: number): Array<[number, number]> {
  const spans: Array<[number, number]> = [];
  let p = at;
  for (;;) {
    let q = p - 1;
    while (q >= 0 && /\s/.test(code[q]!)) q--;
    if (code[q] !== ']') break;
    let depth = 0;
    let open = -1;
    for (let i = q; i >= 0; i--) {
      if (code[i] === ']') depth++;
      else if (code[i] === '[' && --depth === 0) {
        open = i;
        break;
      }
    }
    let hash = open - 1;
    while (hash >= 0 && /\s/.test(code[hash]!)) hash--;
    if (open < 0 || code[hash] !== '#') break;
    spans.push([hash, q + 1]);
    p = hash;
  }
  return spans;
}

/**
 * The one `#[path]` declaration that loads `file` as a module, or null: a file
 * the regular rules place, one no such declaration loads, or one several do
 * (tests that each load a shared helper; then which module it is depends on
 * the crate being built).
 */
function rustPathClaim(file: string, context: ResolutionContext): RustPathDecl | null {
  const loaders = rustPathLoaders(file, context);
  return loaders.length === 1 ? loaders[0]! : null;
}

/** The module a Rust file is, at its own top level. */
function rustFileModule(filePath: string, context: ResolutionContext): RustModule {
  // A file a `#[path]` loads owns its directory, as a `mod.rs` does: rustc
  // reads every `#[path]` file so.
  if (rustPathClaim(filePath, context)) return { file: filePath, dir: rustParentDir(filePath), block: null, root: false };
  const root = isRustTargetRoot(filePath, context);
  const dir = root || filePath.endsWith('/mod.rs') || filePath === 'mod.rs' ? rustParentDir(filePath) : filePath.replace(/\.rs$/, '');
  return { file: filePath, dir, block: null, root };
}

/** The module a `use` at `offset` in `filePath` is written in: the file's, or the inline one around it. */
function rustModuleAt(filePath: string, offset: number, context: ResolutionContext): RustModule {
  const own = rustFileModule(filePath, context);
  const block = rustBlockAt(rustUsesOf(filePath, context).blocks, offset);
  if (!block) return own;
  let dir = own.dir;
  const names: string[] = [];
  for (let b: RustModBlock | null = block; b; b = b.parent) names.unshift(b.name);
  for (const name of names) dir = rustJoin(dir, name);
  return { file: filePath, dir, block, root: false };
}

/**
 * The root of the crate `filePath` is in — what its `crate::` names: a test,
 * example, bench or bin target's own file, else the package's `src/lib.rs` (or
 * `src/main.rs`); in no crate the manifests name, the nearest `lib.rs` or
 * `main.rs` above it. null when no single root is the file's: a
 * `tests/support/` module serves every test that declares it.
 */
function rustCrateRootModule(filePath: string, context: ResolutionContext, depth = 0): RustModule | null {
  // A file a `#[path]` loads is in the crate of the file that declares it.
  const claim = depth < 8 ? rustPathClaim(filePath, context) : null;
  if (claim) return rustCrateRootModule(claim.file, context, depth + 1);
  const graph = rustCrateGraph(context);
  const dir = rustCrateDirOf(filePath, graph);
  if (dir === null) return rustNearestRootModule(filePath, context);
  // An example, test or bench the manifest places with a path of its own is its own crate's root.
  if (graph.crates.get(dir)?.others.includes(filePath)) return { file: filePath, dir: rustParentDir(filePath), block: null, root: true };
  const base = dir === '' ? '' : `${dir}/`;
  const rel = filePath.slice(base.length);
  const target = /^(src\/bin|tests|examples|benches)\/([^/]+?)(\.rs$|\/)/.exec(rel);
  if (target) {
    const file = target[3] === '.rs' ? filePath : `${base}${target[1]}/${target[2]}/main.rs`;
    return context.fileExists(file) ? { file, dir: rustParentDir(file), block: null, root: true } : null;
  }
  if (!rel.startsWith('src/')) {
    // A root its manifest places elsewhere (ripgrep's `[[bin]] path =
    // "crates/core/main.rs"`): the nearest one whose directory holds the file.
    const crate = graph.crates.get(dir);
    const holds = (r: string | undefined): r is string =>
      r !== undefined && (rustParentDir(r) === '' || filePath.startsWith(`${rustParentDir(r)}/`)) && context.fileExists(r);
    const own = [crate?.lib, ...(crate?.bins ?? [])].filter(holds).sort((x, y) => y.length - x.length)[0];
    return own ? { file: own, dir: rustParentDir(own), block: null, root: true } : null;
  }
  const lib = `${base}src/lib.rs`;
  const main = `${base}src/main.rs`;
  const hasLib = context.fileExists(lib);
  const hasMain = context.fileExists(main);
  if (!hasLib && !hasMain) return null;
  const file = hasMain && (filePath === main || !hasLib) ? main : lib;
  return { file, dir: `${base}src`, block: null, root: true, alt: hasLib && hasMain ? (file === lib ? main : lib) : undefined };
}

/**
 * For a file no manifest the project holds covers (sources indexed without
 * their `Cargo.toml`), the crate root nearest above it: the first `lib.rs` or
 * `main.rs` up its directories.
 */
function rustNearestRootModule(filePath: string, context: ResolutionContext): RustModule | null {
  let dir = rustParentDir(filePath);
  for (let i = 0; i < 64; i++) {
    for (const name of ['lib.rs', 'main.rs']) {
      const file = rustJoin(dir, name);
      if (context.fileExists(file)) return { file, dir, block: null, root: true };
    }
    if (dir === '') return null;
    dir = rustParentDir(dir);
  }
  return null;
}

/** The root of a project crate's library: what a path that starts with the crate's name (`tokio::sync::…`) walks from. */
function rustLibModule(crateDir: string, context: ResolutionContext): RustModule | null {
  const file = rustCrateGraph(context).crates.get(crateDir)?.lib ?? (crateDir === '' ? 'src/lib.rs' : `${crateDir}/src/lib.rs`);
  return context.fileExists(file) ? { file, dir: rustParentDir(file), block: null, root: true } : null;
}

/**
 * The module `name` that `m` declares: inline (`mod name { … }`), else
 * `<name>.rs` or `<name>/mod.rs` in its directory, else one it passes on under
 * that name — dioxus's `pub use dioxus_hooks as hooks;`. One a `#[path]`
 * puts elsewhere is the file it names when `m` declares it once, whatever
 * else loads that file too (a helper several tests load is each test's);
 * null when cfg alternatives name a file each (tokio's `process::imp` is
 * `unix/mod.rs` or `windows.rs`) or a `cfg_attr` sets the path, as for one
 * with no file.
 */
function rustSubmodule(m: RustModule, name: string, context: ResolutionContext, depth = 0): RustModule | null {
  const dir = rustJoin(m.dir, name);
  const layout = rustUsesOf(m.file, context);
  if (layout.pathMods.has(name)) {
    const decls = rustPathDeclsIn(m.file, context).filter((d) => d.name === name && rustBlockAt(layout.blocks, d.at) === m.block);
    const target = decls.length === 1 ? decls[0]!.target : null;
    return target !== null && context.fileExists(target) ? { file: target, dir: rustParentDir(target), block: null, root: false } : null;
  }
  const block = layout.blocks.find((b) => b.name === name && b.parent === m.block);
  if (block) return { file: m.file, dir, block, root: false };
  for (const file of [`${dir}.rs`, `${dir}/mod.rs`]) {
    if (context.fileExists(file)) return { file, dir, block: null, root: false };
  }
  if (depth >= 8) return null;
  for (const p of layout.paths.get(name) ?? []) {
    if (p.scope || rustBlockAt(layout.blocks, p.at) !== m.block) continue;
    const passed = rustWalkModules(p.segs, m, context, depth + 1);
    if (passed !== null && passed !== 'outside') return passed;
  }
  return null;
}

/**
 * The module `m` is declared in — what `super::` names — or null above a
 * crate's root. A file a `#[path]` loads is declared where that attribute is,
 * wherever the file lies (fast-mlsirm's `tests/unit/scaling_tests.rs` is
 * `crates/core/src/scaling.rs`'s `mod tests`).
 */
function rustSuperModule(m: RustModule, context: ResolutionContext): RustModule | null {
  if (m.block) {
    return m.block.parent ? { file: m.file, dir: rustParentDir(m.dir), block: m.block.parent, root: false } : rustFileModule(m.file, context);
  }
  const claim = rustPathClaim(m.file, context);
  if (claim) return rustModuleAt(claim.file, claim.at, context);
  if (m.root) return null;
  const dir = rustParentDir(m.dir);
  for (const file of [rustJoin(dir, 'mod.rs'), ...(dir === '' ? [] : [`${dir}.rs`]), rustJoin(dir, 'lib.rs'), rustJoin(dir, 'main.rs')]) {
    if (context.fileExists(file)) return rustFileModule(file, context);
  }
  return null;
}

/**
 * The module the segments of a `use` path walk to from `from`, the module the
 * `use` is written in: `crate::`, `self::` and `super::` as Rust reads them; a
 * module `from` declares (2018 paths start from the current module); a project
 * crate by the name its manifest gives the file's crate, or by its own.
 * 'outside' for the standard library and every other crate; null when a step
 * finds no module the project holds.
 */
function rustWalkModules(segs: readonly string[], from: RustModule, context: ResolutionContext, depth = 0): RustModule | 'outside' | null {
  const [first, ...rest] = segs;
  if (first === undefined) return from;
  let at: RustModule | null;
  if (first === 'crate') at = rustCrateRootModule(from.file, context);
  else if (first === 'self') at = from;
  else if (first === 'super') at = rustSuperModule(from, context);
  else if (RUST_STD_ROOTS.has(first)) return 'outside';
  else {
    at = rustSubmodule(from, first, context, depth);
    if (at === null) {
      const graph = rustCrateGraph(context);
      const own = rustCrateDirOf(from.file, graph);
      const crate = own === null ? undefined : graph.crates.get(own);
      const dep = crate === undefined ? undefined : first === crate.name ? own! : crate.keys.get(first);
      if (dep !== undefined) at = rustLibModule(dep, context);
      else if (rustDependencyCrates(context).has(first)) return 'outside';
    }
  }
  for (const seg of rest) {
    if (at === null) return null;
    at = seg === 'self' ? at : seg === 'super' ? rustSuperModule(at, context) : rustSubmodule(at, seg, context, depth);
  }
  return at;
}

/**
 * The items `m` declares as `name` at its own level: not in a module it
 * declares inline, nor inside a function. With `publicOnly`, only its `pub`
 * ones (a trait or const records no visibility, and counts).
 */
function rustDeclaredItems(m: RustModule, name: string, context: ResolutionContext, publicOnly = false): Node[] {
  const out: Node[] = [];
  for (const file of m.alt ? [m.file, m.alt] : [m.file]) {
    const layout = rustUsesOf(file, context);
    const block = file === m.file ? m.block : null;
    for (const n of context.getNodesInFileNamed?.(file, name) ?? context.getNodesInFile(file).filter((c) => c.name === name)) {
      // An item in a function body is qualified by it (`outer::Inner`); an inline module adds nothing.
      if (n.language !== 'rust' || n.qualifiedName !== name || !RUST_MODULE_ITEM_KINDS.has(n.kind)) continue;
      if (publicOnly && n.visibility === 'private') continue;
      const at = (layout.lineStarts[n.startLine - 1] ?? 0) + Math.max(0, n.startColumn ?? 0);
      if (rustBlockAt(layout.blocks, at) === block) out.push(n);
    }
  }
  return out;
}

/**
 * The items named `name` in module `m`, as Rust looks a name up in a module:
 * the ones it declares, else the ones its `use`s of that name bring in —
 * `pub use mutex::{Mutex, …}`, macro-wrapped as tokio's `cfg_sync! { … }`
 * are — else the ones its globs do. An outside crate's add nothing. null when
 * one of them can't be followed. `seen` holds the lookups under way, so
 * modules that glob each other (`use super::*` below a `pub use child::*`)
 * end the walk. `publicOnly` is a glob's view from outside the module: only
 * what it declares `pub` or passes on with `pub use` — dioxus-hooks' `pub use
 * use_effect::*` doesn't pass on that module's own `use dioxus_core::*`.
 */
function rustModuleItems(m: RustModule, name: string, context: ResolutionContext, seen: Set<string>, publicOnly = false): Node[] | null {
  const key = `${m.file}\0${m.block?.open ?? -1}\0${name}\0${publicOnly ? 1 : 0}`;
  if (seen.has(key)) return [];
  if (seen.size >= 32) return null;
  const uses = rustUsesOf(m.file, context);
  if (!uses.balanced) return null;
  seen.add(key);
  try {
    const declared = rustDeclaredItems(m, name, context, publicOnly);
    if (declared.length > 0) return declared;
    // (A `use` in a function's body binds its name there alone.)
    const here = (p: RustUsePath): boolean => (p.pub || !publicOnly) && !p.scope && rustBlockAt(uses.blocks, p.at) === m.block;
    const named = (uses.paths.get(name) ?? []).filter(here);
    const found: Node[] = [];
    for (const p of named) {
      const items = rustUsePathItems(p.segs, m, context, seen);
      if (items === null) return null;
      found.push(...items);
    }
    // A `use` of the name shadows the globs — in its own namespace: clap's
    // `pub use clap_derive::ValueEnum` is a derive macro, and the trait
    // `ValueEnum` still comes in through its `pub use clap_builder::*`.
    if (found.length > 0) return found;
    const globbed = rustGlobbedItems(uses.globPaths.filter(here), () => m, name, context, seen);
    return globbed === null ? null : [...found, ...globbed];
  } finally {
    seen.delete(key);
  }
}

/**
 * The items named `name` that globs bring in, each walked from the module
 * `fromOf` gives for it — what the module a glob names lets the importer see:
 * all of it from inside (`use super::*`), its public part from anywhere else.
 * A glob that brings the name in settles it — two globs bringing in two items
 * of one name don't compile — so one the walk can't follow (dioxus's
 * `elements::prelude::*`, a macro's module) matters only when none does; then
 * the answer is null.
 */
function rustGlobbedItems(
  globs: readonly RustUsePath[],
  fromOf: (glob: RustUsePath) => RustModule,
  name: string,
  context: ResolutionContext,
  seen: Set<string>,
): Node[] | null {
  const found: Node[] = [];
  let unknown = false;
  for (const g of globs) {
    const from = fromOf(g);
    const mod = rustWalkModules(g.segs, from, context);
    if (mod === 'outside') continue;
    const items = mod === null ? null : rustModuleItems(mod, name, context, seen, !rustModuleWithin(from, mod, context));
    if (items === null) unknown = true;
    else found.push(...items);
  }
  return found.length > 0 || !unknown ? found : null;
}

/** Whether module `inner` is `outer` or one declared inside it, inline or in a file below its directory. */
function rustModuleWithin(inner: RustModule, outer: RustModule, context?: ResolutionContext, depth = 0): boolean {
  if (inner.file === outer.file) {
    for (let b: RustModBlock | null = inner.block; ; b = b.parent) {
      if (b === outer.block) return true;
      if (b === null) return false;
    }
  }
  if (inner.file.startsWith(outer.dir === '' ? '' : `${outer.dir}/`) && !(outer.dir === '' && outer.block !== null)) return true;
  // A file a `#[path]` loads is inside the module that declares it.
  const claim = context && depth < 8 && inner.block === null ? rustPathClaim(inner.file, context) : null;
  return claim !== null && rustModuleWithin(rustModuleAt(claim.file, claim.at, context!), outer, context, depth + 1);
}

/**
 * The items a `use` path names from `from`: its last segment's, in the module
 * the rest walks to — or, when that segment's parent is an enum the module
 * holds, the enum's variant: `use crate::models::Mode::Fast` names `Fast` of
 * that `Mode`, never a namesake's.
 */
function rustUsePathItems(segs: readonly string[], from: RustModule, context: ResolutionContext, seen: Set<string>): Node[] | null {
  if (segs.length < 2) return null;
  const mod = rustWalkModules(segs.slice(0, -1), from, context);
  if (mod === 'outside') return [];
  if (mod !== null) return rustModuleItems(mod, segs[segs.length - 1]!, context, seen);
  const owner = segs.length > 2 ? rustWalkModules(segs.slice(0, -2), from, context) : from;
  if (owner === null || owner === 'outside') return owner === null ? null : [];
  const enums = rustModuleItems(owner, segs[segs.length - 2]!, context, seen)?.filter((n) => n.kind === 'enum') ?? [];
  return enums.length === 0 ? null : enums.flatMap((e) => rustEnumVariants(e, segs[segs.length - 1]!, context));
}

/** The variant `name` of a Rust enum: the member written inside its braces, not a namesake's in the same file. */
function rustEnumVariants(e: Node, name: string, context: ResolutionContext): Node[] {
  const qualified = `${e.qualifiedName}::${name}`;
  return (context.getNodesInFileNamed?.(e.filePath, name) ?? context.getNodesInFile(e.filePath)).filter((n) =>
    n.kind === 'enum_member' && n.qualifiedName === qualified && n.startLine >= e.startLine && n.startLine <= (e.endLine ?? e.startLine));
}

const RUST_USE_ITEMS = new WeakMap<ResolutionContext, Map<string, Set<string> | null>>();

/**
 * The ids of what the `use`s that bind `name` in `filePath` name, through the
 * project's modules: `use crate::sync::watch::Receiver` names watch.rs's
 * `Receiver`, never pipe.rs's. Empty when the module holds nothing by that
 * name the index knows (a macro's item); null when the file binds no such
 * name, or one of its paths can't be followed — a module with no file to read.
 */
function rustUseItems(name: string, filePath: string, context: ResolutionContext): Set<string> | null {
  let memo = RUST_USE_ITEMS.get(context);
  if (!memo) RUST_USE_ITEMS.set(context, (memo = new Map()));
  const key = `${filePath}\0${name}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const uses = rustUsesOf(filePath, context);
  const paths = uses.balanced ? uses.paths.get(name) : undefined;
  const ids = paths ? rustPathsItems(paths, filePath, context) : null;
  memo.set(key, ids);
  return ids;
}

/** The ids of what `use` paths of `filePath` name, each walked from the module it is written in; null if one can't be followed. */
function rustPathsItems(paths: readonly RustUsePath[], filePath: string, context: ResolutionContext): Set<string> | null {
  const ids = new Set<string>();
  for (const p of paths) {
    const items = rustUsePathItems(p.segs, rustModuleAt(filePath, p.at, context), context, new Set());
    if (items === null) return null;
    for (const n of items) ids.add(n.id);
  }
  return ids;
}

/** The `use`s that bind a name where a reference is (rustVisibleUse). */
interface RustVisibleUse {
  /** The project's paths among them (`crate::util::take`, a dependency's). */
  paths: RustUsePath[];
  /** The standard library's (`use std::fs;`). */
  std: RustUsePath[];
  /** The braces' `{` of the block they are written in, or -1 for a `use` of the module itself. */
  block: number;
}

/**
 * The `use`s that bind `name` at `offset` of `filePath`, as Rust scopes them:
 * those of the innermost block around it — a function's body, a block in one —
 * else those of the module it is written in, at the file's top level or in an
 * inline `mod`, whose `use`s neither the modules around it nor those inside it
 * see. Undefined when none binds it there, or the file's braces don't close.
 */
function rustVisibleUse(name: string, filePath: string, offset: number, context: ResolutionContext): RustVisibleUse | undefined {
  const uses = rustUsesOf(filePath, context);
  const project = uses.paths.get(name);
  const std = uses.stdPaths.get(name);
  if ((!project && !std) || !uses.balanced) return undefined;
  const module = rustBlockAt(uses.blocks, offset);
  let best: RustVisibleUse | undefined;
  const take = (p: RustUsePath, isStd: boolean): void => {
    if (p.scope ? offset <= p.scope.open || offset >= p.scope.close : false) return;
    if (rustBlockAt(uses.blocks, p.at) !== module) return;
    const block = p.scope ? p.scope.open : -1;
    if (!best || block > best.block) best = { paths: [], std: [], block };
    else if (block < best.block) return;
    (isStd ? best.std : best.paths).push(p);
  };
  for (const p of project ?? []) take(p, false);
  for (const p of std ?? []) take(p, true);
  return best;
}

const RUST_VISIBLE_ITEMS = new WeakMap<ResolutionContext, Map<string, Set<string> | null>>();

/**
 * The ids of what the `use`s binding `name` where `ref` is name (rustVisibleUse):
 * `fn first() { use crate::util::take; take() }` reaches util's `take`, the
 * next function's `use crate::a::take;` a's. Empty for a name only the
 * standard library's `use` binds there. Where no `use` binds it, those of the
 * whole file (rustUseItems), as a reference no scope reads.
 */
function rustUseItemsAt(name: string, ref: UnresolvedRef, context: ResolutionContext): Set<string> | null {
  const visible = rustVisibleUse(name, ref.filePath, rustRefOffset(ref, context), context);
  if (!visible) return rustUseItems(name, ref.filePath, context);
  if (visible.paths.length === 0) return new Set();
  let memo = RUST_VISIBLE_ITEMS.get(context);
  if (!memo) RUST_VISIBLE_ITEMS.set(context, (memo = new Map()));
  const key = `${ref.filePath}\0${name}\0${visible.block}\0${visible.paths[0]!.at}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const ids = rustPathsItems(visible.paths, ref.filePath, context);
  memo.set(key, ids);
  return ids;
}

/** The offset of a reference in its file's text (its line's start, plus its column). */
function rustRefOffset(ref: UnresolvedRef, context: ResolutionContext): number {
  return (rustUsesOf(ref.filePath, context).lineStarts[ref.line - 1] ?? 0) + Math.max(0, ref.column);
}

const RUST_GLOB_ITEMS = new WeakMap<ResolutionContext, Map<string, Set<string> | null>>();

/**
 * The ids of the items named `name` that the globs of `filePath` bring in —
 * `use dioxus::prelude::*` brings in what that module re-exports from the
 * crates it is built from. null when the file has no globs or they can't be
 * followed, and the module names they end in say what they bring instead.
 */
function rustGlobItems(name: string, filePath: string, context: ResolutionContext): Set<string> | null {
  let memo = RUST_GLOB_ITEMS.get(context);
  if (!memo) RUST_GLOB_ITEMS.set(context, (memo = new Map()));
  const key = `${filePath}\0${name}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const uses = rustUsesOf(filePath, context);
  const items = uses.balanced && uses.globPaths.length > 0
    ? rustGlobbedItems(uses.globPaths, (g) => rustModuleAt(filePath, g.at, context), name, context, new Set())
    : null;
  const ids = items === null ? null : new Set(items.map((n) => n.id));
  memo.set(key, ids);
  return ids;
}

/**
 * Whether one of the file's globs brings this candidate in: by the modules
 * they walk to, when those can be followed; else by the module names they end
 * in (rustGlobCovers).
 */
function rustGlobScope(name: string, candidate: Node, uses: RustUses, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const ids = RUST_MODULE_ITEM_KINDS.has(candidate.kind) ? rustGlobItems(name, ref.filePath, context) : null;
  return ids === null ? rustGlobCovers(uses, candidate, ref) : ids.has(candidate.id);
}

/** The module a Rust file is: `src/glob.rs` → `glob`, `src/walk/mod.rs` → `walk`. */
function rustModuleName(filePath: string): string {
  const parts = filePath.split('/');
  const base = parts[parts.length - 1]!.replace(/\.rs$/, '');
  return base === 'mod' || base === 'lib' || base === 'main' ? parts[parts.length - 2] ?? base : base;
}

/** Rust items declared in a module, whose own `pub` (or its absence) says who can name them. */
const RUST_MODULE_ITEM_KINDS = new Set(['function', 'struct', 'enum', 'union', 'type_alias', 'trait', 'constant', 'variable']);

/**
 * Whether `ref`'s file can name this Rust item. A private one — no `pub` of
 * any form — is named only in its own module and the modules inside it: a
 * `type Result` in `src/build/patch.rs` is `build::patch`'s, seen in that file
 * and under `src/build/patch/`, never through `use crate::Result` elsewhere,
 * and no glob passes it on (dioxus's `pub(crate) use patch::*` doesn't). A
 * `mod.rs`, `lib.rs` or `main.rs` is the module of its whole directory. The
 * same rule isVisibleAcrossFiles applies to the pipeline's pick, here ahead of
 * the ranking, so the crate's own `pub(crate) type Result` can win instead.
 */
function isRustItemVisibleFrom(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (candidate.language !== 'rust' || candidate.visibility !== 'private' || !RUST_MODULE_ITEM_KINDS.has(candidate.kind)) return true;
  return candidate.filePath === ref.filePath || rustFileUnder(ref.filePath, rustModuleDir(candidate.filePath), candidate.filePath, context);
}

/** What a Rust `impl` declares besides its functions: `type Err = …;`, `const MAX: usize = …;`. */
const RUST_ASSOCIATED_KINDS = new Set(['type_alias', 'variable', 'constant']);

/**
 * Whether a Rust item is an associated one: a `type` or `const` written in an
 * `impl` or a trait. It belongs to the type, not to the module, so Rust reaches
 * it only through a path — `Self::Err`, `<T as FromStr>::Err`, `T::Err` —
 * never by its name alone, and no module path (`std::error::Error`) or `use`
 * names it. The extractors qualify it by the impl's type (`ValueHint::Err`) or
 * its trait, as they do the methods; a module's own type alias or const is
 * qualified by nothing.
 */
export function isRustAssociatedItem(n: Node): boolean {
  return n.language === 'rust' && RUST_ASSOCIATED_KINDS.has(n.kind) && n.qualifiedName.includes('::');
}

/** Does one of the file's globs bring in this candidate's module (or, for `use super::*`, its parent's)? */
function rustGlobCovers(uses: RustUses, candidate: Node, ref: UnresolvedRef): boolean {
  if (uses.globs.has(rustModuleName(candidate.filePath))) return true;
  if (!uses.globs.has('super')) return false;
  const dir = (p: string): string => p.slice(0, p.lastIndexOf('/'));
  // `use super::*` in a child module: the parent's file, or a sibling in the parent's directory.
  return dir(candidate.filePath) === dir(ref.filePath) || dir(candidate.filePath) === dir(dir(ref.filePath));
}

/**
 * Whether a bare Rust name can mean this candidate. An enum's variant is in
 * scope bare only through a `use` of it or of its enum's `*`, and never
 * names a TYPE — ripgrep's every `Some(x)` bound to its `EncodingMode::Some`
 * variant, every `Ok(x)` to `ParseResult::Ok`. A prelude name (`Ok`,
 * `Result`, `Box`) is the prelude's unless the file defines it or imports a
 * project item of that name — serde's macro-hygiene tests declare `struct
 * Ok`, `struct Result`, and serde bound its own `Ok(…)` and `Result<…>` to them.
 * A private item is out of scope outside its module (isRustItemVisibleFrom),
 * and an item a `use` binds is one its path's crate can reach (rustUseCanReach)
 * and, where the project holds the modules that path walks, the item it names
 * there (rustUseItems).
 */
export function isRustNameInScope(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (RUST_SCOPED_REFS.get(context)?.has(ref)) return true;
  if (!isRustItemVisibleFrom(candidate, ref, context)) return false;
  const name = ref.referenceName;
  // Bare in the SOURCE: the index keeps `crate::error::Result` by its last
  // segment, and a path is not a prelude lookup.
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1] ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  // A trait's associated type bound in its arguments — `Iterator<Item = &str>`,
  // `Readable<Storage = S>` — is that trait's, which no node stands for: never
  // a module item or an impl's. axum's `Iterator<Item = &str>` went to a
  // same-file `enum Item`, dioxus's `Storage = UnsyncStorage` to a `Storage` trait.
  if (ref.referenceKind === 'references' && line !== undefined && isRustAssocBinding(line, ref.column, name)) return false;
  // A variant path — `Mode::A`, `mode::Mode::B`, a `Mode::C(x)` pattern, or
  // `Self::A` in an impl, where the reference names the impl's type (#2328) —
  // reads the enum that declares that variant, and nothing else: ripgrep's
  // `Match::None` is `ignore`'s enum, not the matcher's `struct Match`. An
  // associated const or function read the same way (`Limits::MAX`, `Mode::ALL`)
  // is not a variant, so it references no type.
  const at = line === undefined ? '' : line.slice(ref.column);
  const typeRead = ref.referenceKind === 'references' && /^\w+$/.test(name);
  const viaSelf = typeRead && name !== 'Self' && /^Self\s*::/.test(at);
  const variant = typeRead && (viaSelf || (at.startsWith(name) && !/^\w/.test(at.slice(name.length))))
    ? /^\w+\s*::\s*([A-Z]\w*)/.exec(at)?.[1] : undefined;
  if (variant !== undefined && !declaresRustVariant(candidate, variant, context)) return false;
  // Written through a path on its line (`jsont::SubMatch { … }`, `io::Result<…>`),
  // wherever the reference's column points. `Self::A` names the impl's type, not
  // whatever path the line writes elsewhere.
  const pathed = line === undefined || viaSelf ? null
    : (line.startsWith(name, ref.column) && /::\s*$/.test(line.slice(0, ref.column)) ? /((?:[A-Za-z_]\w*\s*::\s*)*)([A-Za-z_]\w*)?\s*::\s*$/.exec(line.slice(0, ref.column))
      : !new RegExp(`(?<![\\w$:])${escapeRegExp(name)}\\b`).test(line) ? new RegExp(`((?:[A-Za-z_]\\w*\\s*::\\s*)*)([A-Za-z_]\\w*)\\s*::\\s*${escapeRegExp(name)}\\b`).exec(line) : null);
  if (pathed) {
    // Through a path: `crate::` / `self::` / `super::` look it up relatively;
    // `io::Result` is the `io` module's — tokio's `runtime/task` alias is not —
    // and a path from std (`std::io::Error`) is std's.
    const seg = pathed[2] ?? '';
    const root = /^([A-Za-z_]\w*)/.exec(pathed[1] ?? '')?.[1] ?? seg;
    // `Self::Error` in a signature is the enclosing impl's (or trait's) own
    // associated type, and `V::Value` an associated type of a generic's bound —
    // never a struct of that name: serde's 334 `Self::Error`s went to
    // `de::value::Error`.
    if (ref.referenceKind === 'references' && (pathed[1] ?? '') === '' && line !== undefined) {
      if (seg === 'Self') return candidate.kind === 'type_alias' && isInEnclosingRustImpl(candidate, ref, context);
      if (isRustGenericParam(seg, ref, context)) return false;
    }
    // An associated item, only through its type: `Self::Err` in its impl,
    // `<T as FromStr>::Err`. No module path names one: axum-core's
    // `std::error::Error` is std's, not its file's `impl IntoResponseParts`'s `type Error`.
    if (isRustAssociatedItem(candidate)) {
      if (seg === 'Self') return isInEnclosingRustImpl(candidate, ref, context);
      if (seg !== '' || line === undefined) return false;
      // A qualified self reads as its type: `<Self as Handler>::Future` is
      // `Self::Future` — in a trait's own body, the trait's, no impl's — a
      // generic's (`<L as Listener>::Io`) no impl's, and `<Ready as
      // Listener>::Io` that type's impl of that trait.
      const qself = rustQualifiedSelf(line.slice(0, ref.column));
      if (!qself) return true;
      if (qself.self === 'Self') return isInEnclosingRustImpl(candidate, ref, context);
      if (isRustGenericParam(qself.self, ref, context) || candidate.qualifiedName !== `${qself.self}::${candidate.name}`) return false;
      return qself.trait === null || rustTraitImplHeader(candidate, context)?.trait === qself.trait;
    }
    const projectCrates = rustProjectCrates(context);
    const pathUses = rustUsesOf(ref.filePath, context);
    // A path from std or a crate the manifests depend on is that crate's, in
    // the file of a namesake too: clap's `std::ffi::OsStr` is not its own
    // `struct OsStr`, tokio's `mio::Interest` not its own `Interest`.
    if ((root === 'std' || root === 'core' || root === 'alloc' || rustDependencyCrates(context).has(root)) &&
        !projectCrates.has(root) && !pathUses.bound.has(root)) return false;
    // A project crate's name re-exports as `crate::` does: `clap::Command` is clap_builder's.
    if (seg === '' || seg === 'crate' || seg === 'self' || seg === 'super' || seg === 'Self' || projectCrates.has(seg)) return true;
    // `io::Error` under `use std::io;` is std's, whatever `io/` directory the project has.
    if (pathUses.external.has(seg) && !pathUses.bound.has(seg)) return false;
    // Through a module a `use` binds, an item of a crate that `use`'s path can
    // reach: tokio's `io::Handle` under `use crate::runtime::io` is tokio's,
    // not tokio-test's `io.rs` `Handle`.
    const from = pathUses.boundFrom.get(root);
    if (from && !rustUseCanReach(from, candidate, ref, context)) return false;
    // Otherwise the module or type the path names, wherever it is written:
    // gleam's `ast::Pattern` is `ast.rs`'s, not the `enum Pattern` beside it,
    // and `Source::Record { … }` `Source`'s variant, not another enum's. The
    // file's own items are reached so only from an inline `mod` of the file.
    return rustModuleName(candidate.filePath) === seg || candidate.filePath.includes(`/${seg}/`) ||
      candidate.qualifiedName.split('::').includes(seg) ||
      (candidate.filePath === ref.filePath && isInRustInlineModule(candidate, seg, context));
  }
  // Nor does its name alone: clap's `Err(…)` calls went to the `type Err` of
  // a `FromStr` impl in the same file, axum's routing tests' `Response`s to
  // the `type Response` of `routing/mod.rs`'s `impl Service`.
  if (isRustAssociatedItem(candidate)) return false;
  if (candidate.kind === 'enum_member') {
    if (ref.referenceKind === 'references') return false;
    const uses = rustUsesOf(ref.filePath, context);
    const cut = candidate.qualifiedName.lastIndexOf('::');
    const owner = cut >= 0 ? candidate.qualifiedName.slice(0, cut).split('::').pop()! : '';
    if (!((owner !== '' && uses.globs.has(owner)) || (uses.names.has(name) && uses.names.has(owner)))) return false;
    // A `use` of the variant itself names that enum's: `use crate::models::E::Good`
    // is `models`'s `E::Good`, not an `E::Good` another module declares.
    return !uses.paths.has(name) || rustUseItemsAt(name, ref, context)?.has(candidate.id) !== false;
  }
  if (candidate.filePath === ref.filePath) {
    // A `use` in the block around the reference shadows its module's own item
    // of the name: `fn f() { use crate::util::take; take() }` is util's `take`,
    // not the file's.
    if (candidate.qualifiedName !== name || !RUST_MODULE_ITEM_KINDS.has(candidate.kind)) return true;
    const visible = rustVisibleUse(name, ref.filePath, rustRefOffset(ref, context), context);
    return !visible || visible.block < 0 || rustUseItemsAt(name, ref, context)?.has(candidate.id) !== false;
  }
  const uses = rustUsesOf(ref.filePath, context);
  // An item a `use` binds is one its path's crate can name — and, where the
  // project holds the modules the path walks, the item of that module: the
  // `use` that binds the name where the reference is (a block's own, else its
  // module's), else those of the whole file.
  const from = RUST_MODULE_ITEM_KINDS.has(candidate.kind) ? uses.boundFrom.get(name) : undefined;
  if (from && !rustUseCanReach(from, candidate, ref, context)) return false;
  if (from && rustUseItemsAt(name, ref, context)?.has(candidate.id) === false) return false;
  // `use std::task::{Context, Poll}`: the file's `Context` is std's, not tokio's
  // `runtime::context::Context`. (A method call `.env(…)` is no imported name.)
  if (uses.external.has(name) && !uses.bound.has(name) && line !== undefined) {
    // Not on its line at all: a later link of a chain written across lines (`Arg::new(…)\n.env(…)`).
    const at = new RegExp(`(?<![\\w$])${escapeRegExp(name)}\\b`).exec(line.slice(Math.max(0, ref.column)));
    if (at && !/\.\s*$/.test(line.slice(0, Math.max(0, ref.column) + at.index))) return false;
  }
  if (!RUST_PRELUDE.has(name)) {
    // Another file's item — a type, a function — is in scope only through a
    // `use` that binds it or a glob that brings it in: tokio's `Context<'_>` is
    // not `runtime::task::trace`'s `Context` unless the file brings that one
    // in. A method is reached through a value, never a `use`.
    if (TYPE_MEMBER_KINDS.has(candidate.kind) || ref.referenceKind === 'imports' ||
        candidate.kind === 'file' || candidate.kind === 'module' || candidate.kind === 'namespace') return true;
    return uses.bound.has(name) || rustGlobScope(name, candidate, uses, ref, context);
  }
  return uses.names.has(name) || rustGlobScope(name, candidate, uses, ref, context);
}

/** What a bare Rust name a `use` renames may be, by the reference's kind. */
const RUST_RENAMED_KINDS: Record<string, ReadonlySet<string>> = {
  calls: new Set(['function', 'struct', 'union', 'enum_member', 'variable', 'constant']),
  function_ref: new Set(['function']),
  references: new Set([...RUST_MODULE_ITEM_KINDS, 'enum_member']),
};

/**
 * A bare Rust name as the scope around it binds it, which a match by its name
 * can't read:
 * - a call to a name a local binds there — a parameter, a `let`, a closure's
 *   parameter, nearer than any `use` of the name — calls that local: null;
 * - a name a `use` renames (`use crate::util::take as consume; consume()`)
 *   is the item its path names, which no declaration carries by that name,
 *   or nothing: a rename of a std item, of one the walk can't follow.
 * Undefined otherwise.
 */
export function matchRustUseBoundName(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const kinds = RUST_RENAMED_KINDS[ref.referenceKind];
  if (ref.language !== 'rust' || !kinds || !/^[A-Za-z_]\w*$/.test(ref.referenceName)) return undefined;
  const name = ref.referenceName;
  // Written bare where the reference is: no method's name, nor a path's first
  // or last segment — and a call's own name, with its arguments after it: a
  // chained call is recorded where its receiver starts, which may be a local
  // of the method's name (`deadline.as_ref().deadline()`).
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split('\n');
  const line = lines?.[ref.line - 1];
  if (line === undefined || !line.startsWith(name, ref.column) || /(?:\.|::)\s*$/.test(line.slice(0, ref.column))) return undefined;
  const after = line.slice(ref.column + name.length).trimStart();
  if (ref.referenceKind === 'calls' ? !/^(?:\(|::\s*<)/.test(after) : /^(?:\.|::)/.test(after)) return undefined;
  const offset = rustRefOffset(ref, context);
  // A type rustfmt wrapped below its path — `h: &scheduler::\n    Handle` — is
  // the path's, not the `use`'s of its last name: read back over the line
  // break, comments blanked (`// crate::scheduler::` above it is no path).
  if (ref.referenceKind === 'references' && /^\s*$/.test(line.slice(0, ref.column)) && ref.line > 1 &&
      /::\s*(?:\/\/.*|\/\*.*)?$/.test(lines![ref.line - 2] ?? '')) {
    const scopes = rustScopesOf(ref.filePath, context);
    const qualifier = scopes ? rustWrittenQualifier(scopes.code, offset) : [];
    if (qualifier.length > 0) {
      const target = rustPathTarget({ ...ref, referenceName: [...qualifier, name].join('::') }, context);
      if (!target) return undefined;
      let scoped = RUST_SCOPED_REFS.get(context);
      if (!scoped) RUST_SCOPED_REFS.set(context, (scoped = new WeakSet()));
      scoped.add(ref);
      return { original: ref, targetNodeId: target.id, confidence: 0.9, resolvedBy: 'import' };
    }
  }
  const visible = rustVisibleUse(name, ref.filePath, offset, context);
  const local = ref.referenceKind === 'references' ? null : rustShadowingLocal(name, ref, offset, visible, context);
  let target: Node | null | undefined;
  if (local) {
    // A `let` that holds a function by its path is that function: serde's `let
    // test = test::<i8>;` before its `test(…)` calls is the `test` the name
    // finds anyway; `let take = crate::other::take;` is other's.
    const held = local.kind === 'let' ? local.init?.replace(/\s*::\s*<[\s\S]*>$/, '').replace(/\s+/g, '') : undefined;
    if (held === undefined || !/^(?:[A-Za-z_]\w*::)*[A-Za-z_]\w*$/.test(held)) return null;
    if (held === name) return undefined;
    target = held.includes('::') ? rustPathTarget({ ...ref, referenceName: held }, context) : null;
  } else {
    // A rename: a path whose last segment is not the name it binds.
    const renames = (p: RustUsePath): boolean => p.segs[p.segs.length - 1] !== name;
    if (!visible || !(visible.paths.some(renames) || visible.std.some(renames))) return undefined;
    if (visible.paths.length === 0) return null;
    const ids = rustUseItemsAt(name, ref, context);
    target = ids === null ? undefined : [...ids].map((id) => context.getNodeById?.(id)).find((n) => n && kinds.has(n.kind));
  }
  if (!target || !kinds.has(target.kind)) return null;
  // What the scope says the name is needs no other look at the name (isRustNameInScope).
  let scoped = RUST_SCOPED_REFS.get(context);
  if (!scoped) RUST_SCOPED_REFS.set(context, (scoped = new WeakSet()));
  scoped.add(ref);
  return { original: ref, targetNodeId: target.id, confidence: 0.9, resolvedBy: 'import' };
}

/** References matchRustUseBoundName answered from the scope around them: a rename, a `let` that holds a function. */
const RUST_SCOPED_REFS = new WeakMap<ResolutionContext, WeakSet<UnresolvedRef>>();

/**
 * The module path written right before `offset` in a Rust file's blanked
 * code, read back over whitespace and line breaks: `scheduler::` before
 * `Handle` gives `['scheduler']`. Empty when a `::` follows no plain name
 * (a turbofish's `>::`, a qualified self).
 */
function rustWrittenQualifier(code: string, offset: number): string[] {
  const segs: string[] = [];
  let i = offset;
  for (;;) {
    let j = i - 1;
    while (j >= 0 && /\s/.test(code[j]!)) j--;
    if (j < 1 || code[j] !== ':' || code[j - 1] !== ':') break;
    j -= 2;
    while (j >= 0 && /\s/.test(code[j]!)) j--;
    let k = j;
    while (k >= 0 && /\w/.test(code[k]!)) k--;
    const seg = code.slice(k + 1, j + 1);
    if (!/^[A-Za-z_]\w*$/.test(seg)) return [];
    segs.unshift(seg);
    i = k + 1;
  }
  return segs;
}

/**
 * The local a bare name at `offset` of `ref`'s function is there (rust-scopes.ts
 * reads the bindings): a parameter, a `let`, a closure's, a pattern's — unless
 * an item of the name is nearer, as a block's own `use` (`fn f(take: fn()) {
 * { use crate::util::take; take() } }`, and one in the body itself, a scope
 * inside the parameters') or a function the block declares. A nested `fn`
 * sees no local of the function around it. Null for none.
 */
function rustShadowingLocal(name: string, ref: UnresolvedRef, offset: number, visible: RustVisibleUse | undefined, context: ResolutionContext): RustBinding | null {
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller || (caller.kind !== 'function' && caller.kind !== 'method')) return null;
  // A local is written before the reference, in the function: the name's own text first.
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split('\n') ?? [];
  const word = new RegExp(`(?<![\\w$])${escapeRegExp(name)}(?![\\w$])`);
  let written = false;
  for (let l = caller.startLine; l <= ref.line && !written; l++) {
    const text = l === ref.line ? (lines[l - 1] ?? '').slice(0, ref.column) : lines[l - 1] ?? '';
    written = word.test(text);
  }
  if (!written) return null;
  const scopes = rustScopesOf(ref.filePath, context);
  const found = scopes ? rustBindingAt(scopes, name, offset) : undefined;
  if (!scopes || !found) return null;
  const local = found.binding;
  const fn = rustFnAt(scopes, offset);
  if (fn && local.from < fn.from) return null;
  if (visible && visible.block >= local.from) return null;
  // `fn f(take: fn()) { fn take() {} take() }`: the block's own item.
  for (const n of context.getNodesInFileNamed?.(ref.filePath, name) ?? []) {
    if (n.kind !== 'function' || n.qualifiedName === name) continue;
    const block = rustInnerBlockAt(scopes, (scopes.lineStarts[n.startLine - 1] ?? 0) + Math.max(0, n.startColumn ?? 0));
    if (block && block[0] >= local.from && block[0] < offset && offset < block[1]) return null;
  }
  return local;
}

/**
 * Kinds a Rust path to a module's item names: a module-level `pub const` or
 * `static` (extracted as a variable) too, never a method — the module's own
 * items only (rustDeclaredItems), so never an impl's `const`.
 */
const RUST_PATH_ITEM_KINDS: ReadonlySet<string> = new Set(['function', 'struct', 'union', 'enum', 'trait', 'type_alias', 'constant', 'variable']);

const RUST_PATH_TARGETS = new WeakMap<ResolutionContext, Map<string, string | null>>();

/**
 * The item a Rust path written in `ref`'s file names — `crate::util::take`,
 * `super::Item` (from an inline `mod tests { }` too), `util::take` through a
 * module a `use` binds, a project crate's by its name — walking the modules as
 * Rust does from the one the path is written in (rustWalkModules), else, as a
 * 2015 path, from its crate's root, to what the last module declares, passes
 * on (`pub use`) or globs in (rustModuleItems): a function, a type, a trait —
 * and in a `use`, an enum's variant. Never a method, an `impl`'s or a trait's
 * associated item, nor a function's local item. Null when the path names no
 * module the project holds, or one that holds nothing by that name — and for
 * one whose head a `use` takes from the standard library (`fs::read` under
 * `use std::fs;`), whatever module of that name the project has.
 */
export function rustPathTarget(ref: UnresolvedRef, context: ResolutionContext): Node | null {
  const segs = ref.referenceName.replace(/^::/, '').split('::');
  if (segs.length < 2 || !segs.every((s) => /^[A-Za-z_]\w*$/.test(s))) return null;
  const variants = ref.referenceKind === 'imports';
  const offset = rustRefOffset(ref, context);
  // `sim::items::ItemPool::for_def(…)`, `ItemPool::for_def(…)` under `use
  // sim::items::ItemPool;`: a call through a type its path or a `use` names
  // (Rust names its modules in snake_case, its types in CamelCase) is to that
  // type's associated function or variant. A type the module declares itself,
  // `Self`, and a type's path in any other position are left as they were.
  const owner = segs[segs.length - 2]!;
  const typed = !variants && /^[A-Z]/.test(owner);
  const ownerUse = typed && segs.length === 2 ? rustVisibleUse(owner, ref.filePath, offset, context) : undefined;
  if (typed && (ref.referenceKind !== 'calls' || owner === 'Self' || (segs.length === 2 && !ownerUse?.paths.length))) return null;
  const from = rustModuleAt(ref.filePath, offset, context);
  const head = segs[0]!;
  const bare = head !== 'crate' && head !== 'self' && head !== 'super';
  if (bare) {
    const bound = rustVisibleUse(head, ref.filePath, offset, context);
    if (bound && bound.std.length > 0 && bound.paths.length === 0) return null;
  }
  let memo = RUST_PATH_TARGETS.get(context);
  if (!memo) RUST_PATH_TARGETS.set(context, (memo = new Map()));
  // (A type a `use` binds is that `use`'s, wherever it is written.)
  const scope = ownerUse ? `${ownerUse.block}\0${ownerUse.paths[0]!.at}` : '';
  const key = `${ref.filePath}\0${from.block?.open ?? -1}\0${variants ? 1 : 0}\0${scope}\0${segs.join('::')}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit === null ? null : context.getNodeById?.(hit) ?? null;
  // The items the path's segments name — up to its type's, for a typed one.
  const named = (path: readonly string[]): Node[] | null => {
    // A type a `use` binds, written alone: the item that `use` names.
    if (path.length === 1) {
      const ids = rustUseItemsAt(path[0]!, ref, context);
      return ids === null ? null : [...ids].map((id) => context.getNodeById?.(id)).filter((n): n is Node => !!n);
    }
    let items = rustUsePathItems(path, from, context, new Set());
    // As a 2015 path, from the crate's root — unless the module declares the
    // head itself, where a `#[path]` puts it (a cfg's choice): another module
    // of that name at the root is not it.
    if (items === null && bare && !rustUsesOf(from.file, context).pathMods.has(head)) {
      const root = rustCrateRootModule(ref.filePath, context);
      if (root) items = rustUsePathItems(path, root, context, new Set());
    }
    return items;
  };
  let target: Node | null = null;
  if (typed) {
    for (const type of named(segs.slice(0, -1)) ?? []) {
      target = rustTypeMember(type, segs[segs.length - 1]!, context);
      if (target) break;
    }
  } else {
    target = named(segs)?.find((n) => RUST_PATH_ITEM_KINDS.has(n.kind) || (variants && n.kind === 'enum_member')) ?? null;
  }
  memo.set(key, target?.id ?? null);
  return target;
}

/** Kinds a type's associated item is extracted as: an impl's functions, a `const`, a variant. */
const RUST_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'function', 'variable', 'constant', 'enum_member']);

const RUST_TYPE_MEMBERS = new WeakMap<ResolutionContext, Map<string, string | null>>();

/**
 * The associated item `member` of a Rust type, as `Type::member` reaches it:
 * an enum's variant; else the type's own (inherent) function or `const`, a
 * trait impl's only when it is the one item of that name; a trait's own
 * declared method. An impl of the type is written in the type's crate, so a
 * namesake type's impl in another crate is never it. Null when none is.
 */
function rustTypeMember(type: Node, member: string, context: ResolutionContext): Node | null {
  if (type.language !== 'rust' || !RUST_DECLARED_TYPE_KINDS.has(type.kind) || type.kind === 'type_alias') return null;
  let memo = RUST_TYPE_MEMBERS.get(context);
  if (!memo) RUST_TYPE_MEMBERS.set(context, (memo = new Map()));
  const key = `${type.id}\0${member}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit === null ? null : context.getNodeById?.(hit) ?? null;
  let found: Node | null = null;
  if (type.kind === 'enum') found = rustEnumVariants(type, member, context)[0] ?? null;
  if (!found) {
    const graph = rustCrateGraph(context);
    const crate = rustCrateDirOf(type.filePath, graph);
    const within = (n: Node): boolean => type.kind !== 'trait' ||
      (n.filePath === type.filePath && n.startLine >= type.startLine && n.startLine <= (type.endLine ?? type.startLine));
    const all = context.getNodesByName(member).filter((n) => n.language === 'rust' && RUST_MEMBER_KINDS.has(n.kind) &&
      n.qualifiedName === `${type.name}::${member}` && rustCrateDirOf(n.filePath, graph) === crate && within(n));
    const inherent = all.filter((n) => !isRustTraitImplMethod(n, context));
    const pool = inherent.length > 0 ? inherent : all.length === 1 ? all : [];
    found = pool.find((n) => n.filePath === type.filePath) ?? pool[0] ?? null;
  }
  memo.set(key, found?.id ?? null);
  return found;
}

/**
 * Whether a bare Rust name where `ref` is was brought in from the standard
 * library: by the `use` that binds it there (rustVisibleUse), or with none,
 * the file's last `use` of it — unless the crate holds a module by the root's
 * name, which a 2015 path names (`use core::Thing;` with a `mod core;`).
 */
export function isRustNameFromStd(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const name = ref.referenceName;
  const uses = rustUsesOf(ref.filePath, context);
  const visible = rustVisibleUse(name, ref.filePath, rustRefOffset(ref, context), context);
  let std: RustUsePath | undefined;
  if (visible) {
    if (visible.paths.length > 0) return false;
    std = visible.std[visible.std.length - 1];
  } else {
    const last = [...(uses.paths.get(name) ?? []), ...(uses.stdPaths.get(name) ?? [])].sort((a, b) => a.at - b.at).pop();
    if (!last || !RUST_STD_ROOTS.has(last.segs[0]!)) return false;
    std = last;
  }
  if (!std || std.segs.length < 2) return false;
  const root = std.segs[0]!;
  const crateRoot = rustCrateRootModule(ref.filePath, context);
  return rustSubmodule(rustModuleAt(ref.filePath, std.at, context), root, context) === null &&
    (crateRoot === null || rustSubmodule(crateRoot, root, context) === null);
}

/**
 * Std types a crate can implement a trait for but never declare a method on:
 * a method the index holds for one is the project's `impl SomeTrait for
 * String` (`Vec<u8>`, `Arc<T>`, `NonNull<T>`, …).
 */
const RUST_STD_TYPES = new Set([
  'String', 'str', 'Vec', 'VecDeque', 'HashMap', 'HashSet', 'BTreeMap', 'BTreeSet', 'BinaryHeap', 'LinkedList',
  'Box', 'Rc', 'Arc', 'Weak', 'Cow', 'Cell', 'RefCell', 'Mutex', 'RwLock', 'Option', 'Result', 'PathBuf', 'Path',
  'OsString', 'OsStr', 'CString', 'CStr', 'NonNull', 'Pin', 'Duration', 'Instant', 'SystemTime', 'PhantomData',
  'u8', 'u16', 'u32', 'u64', 'u128', 'usize', 'i8', 'i16', 'i32', 'i64', 'i128', 'isize', 'f32', 'f64', 'bool', 'char',
]);
const RUST_DECLARED_TYPE_KINDS = new Set(['struct', 'enum', 'union', 'type_alias', 'trait']);

const rustNameSets = (lists: Record<string, string>): ReadonlyMap<string, ReadonlySet<string>> =>
  new Map(Object.entries(lists).map(([type, names]) => [type, new Set(names.split(' '))]));

const RUST_RC_INHERENT = 'new new_cyclic new_uninit new_uninit_slice new_zeroed pin try_new try_unwrap into_inner unwrap_or_clone ' +
  'into_raw as_ptr from_raw increment_strong_count decrement_strong_count downgrade weak_count strong_count get_mut make_mut ptr_eq ' +
  'downcast assume_init';
/** `Pin`'s methods; its other functions (`Pin::new`, `Pin::into_inner`) are reached by path alone. */
const RUST_PIN_METHODS = 'as_ref as_mut as_deref_mut set get_ref get_mut get_unchecked_mut into_ref map_unchecked map_unchecked_mut';

/**
 * What std declares on its own types, which Rust picks before any trait's
 * function of the same name, on a path (`Arc::from_raw(ptr)`) as on a value
 * (`v.len()`): tokio's `Arc::from_raw(…)` is std's own, never its `impl Link
 * for Arc<ScheduledIo>`'s. Only what the type itself declares: a slice's
 * `iter`, which a `Vec` reaches by deref, comes after a trait impl on the
 * `Vec`. A name missing here leaves the trait's function in reach.
 */
const RUST_STD_INHERENT = rustNameSets({
  Arc: RUST_RC_INHERENT,
  Rc: RUST_RC_INHERENT,
  Weak: 'new upgrade strong_count weak_count as_ptr into_raw from_raw ptr_eq',
  Box: 'new new_uninit new_uninit_slice new_zeroed pin try_new from_raw into_raw from_non_null into_non_null leak into_pin ' +
    'into_boxed_slice into_inner as_ptr as_mut_ptr downcast assume_init write',
  NonNull: 'new new_unchecked dangling as_ptr as_ref as_mut cast add sub offset byte_add byte_sub byte_offset offset_from read ' +
    'read_unaligned read_volatile write write_bytes write_unaligned write_volatile replace swap copy_to copy_from ' +
    'copy_to_nonoverlapping copy_from_nonoverlapping drop_in_place from_ref from_mut slice_from_raw_parts len addr with_addr ' +
    'map_addr align_offset is_aligned',
  Pin: `new new_unchecked into_inner into_inner_unchecked static_ref static_mut ${RUST_PIN_METHODS}`,
  Cell: 'new set swap replace into_inner get update as_ptr get_mut from_mut take',
  RefCell: 'new into_inner replace replace_with swap borrow try_borrow borrow_mut try_borrow_mut as_ptr get_mut take',
  Mutex: 'new lock try_lock is_poisoned clear_poison into_inner get_mut',
  RwLock: 'new read try_read write try_write is_poisoned clear_poison into_inner get_mut',
  Vec: 'new with_capacity from_raw_parts capacity reserve reserve_exact try_reserve try_reserve_exact shrink_to_fit shrink_to ' +
    'into_boxed_slice truncate as_slice as_mut_slice as_ptr as_mut_ptr set_len swap_remove insert remove retain retain_mut ' +
    'dedup_by_key dedup_by dedup push pop pop_if append drain clear len is_empty split_off resize_with resize leak ' +
    'spare_capacity_mut extend_from_slice extend_from_within splice extract_if into_flattened',
  String: 'new with_capacity from_utf8 from_utf8_lossy from_utf8_unchecked from_utf16 from_utf16_lossy from_raw_parts into_bytes ' +
    'as_str as_mut_str push_str extend_from_within capacity reserve reserve_exact try_reserve try_reserve_exact shrink_to_fit ' +
    'shrink_to push as_bytes truncate pop remove retain insert insert_str as_mut_vec len is_empty split_off clear drain ' +
    'replace_range into_boxed_str leak',
  Option: 'is_some is_some_and is_none is_none_or as_ref as_mut as_pin_ref as_pin_mut as_slice as_mut_slice expect unwrap ' +
    'unwrap_or unwrap_or_else unwrap_or_default unwrap_unchecked map inspect map_or map_or_else ok_or ok_or_else as_deref ' +
    'as_deref_mut iter iter_mut and and_then filter or or_else xor insert get_or_insert get_or_insert_default ' +
    'get_or_insert_with take take_if replace zip unzip copied cloned transpose flatten',
  Result: 'is_ok is_ok_and is_err is_err_and ok err as_ref as_mut map map_or map_or_else map_err inspect inspect_err as_deref ' +
    'as_deref_mut iter iter_mut expect unwrap unwrap_or_default expect_err unwrap_err into_ok into_err and and_then or or_else ' +
    'unwrap_or unwrap_or_else unwrap_unchecked unwrap_err_unchecked copied cloned transpose flatten',
});

/** What the std traits a smart pointer implements answer through it: `Clone`, `AsRef`, `Deref`, `Debug`, `PartialEq`, … */
const RUST_POINTER_TRAIT_METHODS = 'clone clone_from as_ref borrow deref fmt eq ne partial_cmp lt le gt ge cmp max min clamp hash ' +
  'into try_into to_string';

/**
 * What a std wrapper a value is reached through answers itself, ahead of the
 * type it wraps — Rust tries the wrapper before dereferencing it: `Pin`'s own
 * methods, and the std traits it implements (`Rc`'s `clone`, `Deref`,
 * `Debug`). tokio's `self.get_mut()` through `self: Pin<&mut Self>` is
 * `Pin::get_mut`, not its own `BufReader::get_mut`. (`Pin<&mut T>` is no
 * `Clone`: `self.clone()` through one is the type's.) A lock guard or a
 * `RefCell`'s `Ref` answers only `Deref` and `Debug`: its `clone()` clones
 * what it guards. `downcast` is only a `Box<dyn Any>`'s or an `Rc<dyn
 * Any>`'s: dioxus's `data.downcast()` on an `Rc<FormData>` is `FormData`'s.
 */
const RUST_WRAPPER_OWN_METHODS = rustNameSets({
  Pin: `${RUST_PIN_METHODS} deref deref_mut fmt eq ne partial_cmp lt le gt ge cmp max min clamp hash into try_into to_string`,
  Box: `${RUST_POINTER_TRAIT_METHODS} as_mut borrow_mut deref_mut`,
  Rc: RUST_POINTER_TRAIT_METHODS,
  Arc: RUST_POINTER_TRAIT_METHODS,
  ManuallyDrop: `${RUST_POINTER_TRAIT_METHODS} deref_mut`,
  Cow: `${RUST_POINTER_TRAIT_METHODS} into_owned to_mut is_borrowed is_owned`,
  MutexGuard: 'deref deref_mut fmt',
  RwLockReadGuard: 'deref fmt',
  RwLockWriteGuard: 'deref deref_mut fmt',
  Ref: 'deref fmt',
  RefMut: 'deref deref_mut fmt',
});

/**
 * The std wrapper a Rust method's `self` is declared through — `self:
 * Pin<&mut Self>` → `Pin`, `self: &Arc<Self>` → `Arc` — read off its
 * signature; null for `self`, `&self`, `&mut self` or `self: &Self`.
 */
function rustSelfWrapper(method: Node): string | null {
  return /^\(\s*(?:mut\s+)?self\s*:\s*(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)?(?:(?:std|core|alloc)\s*::\s*\w+\s*::\s*)?(Pin|Box|Rc|Arc)\s*</
    .exec(method.signature ?? '')?.[1] ?? null;
}

interface RustImplHeader {
  /** The trait's name, the last segment of its path (`linked_list::Link` → `Link`). */
  trait: string;
  /** The type names its arguments write (`From<&'a Handle>` → `Handle`). */
  traitArgs: string[];
  /** The implementing type's name (`NonNull<Entry>` → `NonNull`). */
  self: string;
  /** The type names its arguments write (`Arc<Handle>` → `Handle`, `Pin<P>` → `P`). */
  selfArgs: string[];
  /** The implementing type as written, path and arguments: `pubgrub::Range<Version>`. */
  selfText: string;
  /** The impl's own type parameters (`impl<'a, P: DerefMut>` → `P`). */
  params: string[];
}

const RUST_IMPL_HEADERS = new WeakMap<ResolutionContext, Map<string, RustImplHeader | null>>();

/** `impl<'a, T> From<&'a Handle> for NonNull<Entry> where … {` → its trait and type; null for an inherent impl. */
function parseRustImplHeader(text: string): RustImplHeader | null {
  let rest = text.replace(/^\s*(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?impl\b/, '').replace(/\{[\s\S]*$/, '').replace(/\bwhere\b[\s\S]*$/, '').trim();
  // The impl's own generics, `<'a, T: Into<U>>`.
  const params: string[] = [];
  if (rest.startsWith('<')) {
    let depth = 0;
    let i = 0;
    let from = 1;
    for (; i < rest.length; i++) {
      if (rest[i] === '<') depth++;
      else if (rest[i] === '>' && --depth === 0) break;
      else if (rest[i] === ',' && depth === 1) {
        params.push(rest.slice(from, i));
        from = i + 1;
      }
    }
    params.push(rest.slice(from, i));
    rest = rest.slice(i + 1).trim();
  }
  // ` for ` outside the angle brackets parts the trait from the type.
  let depth = 0;
  let split = -1;
  for (let i = 0; i < rest.length && split < 0; i++) {
    if (rest[i] === '<') depth++;
    else if (rest[i] === '>') depth--;
    else if (depth === 0 && /\s/.test(rest[i]!) && /^for\s/.test(rest.slice(i + 1))) split = i;
  }
  if (split < 0) return null;
  const traitPart = rest.slice(0, split).trim().replace(/^!/, '');
  const head = (part: string): string =>
    /([A-Za-z_]\w*)\s*(?:<|$)/.exec(part.replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?|dyn\s+)+/, '').trim())?.[1] ?? '';
  const args = (part: string): string[] => {
    const open = part.indexOf('<');
    return open < 0 ? [] : [...part.slice(open + 1).matchAll(/(?<!['\w])([A-Za-z_]\w*)/g)]
      .map((m) => m[1]!).filter((id) => id !== 'mut' && id !== 'dyn');
  };
  const open = traitPart.indexOf('<');
  const selfPart = rest.slice(split + 5);
  return {
    trait: head(open < 0 ? traitPart : traitPart.slice(0, open)),
    traitArgs: args(traitPart),
    self: head(selfPart),
    selfArgs: args(selfPart.trim().replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?|dyn\s+)+/, '')),
    selfText: selfPart.replace(/\{[\s\S]*$/, '').replace(/\bwhere\b[\s\S]*$/, '').trim(),
    params: params.map((p) => /^\s*(?:const\s+)?([A-Za-z_]\w*)/.exec(p)?.[1]).filter((p): p is string => p !== undefined),
  };
}

/** The `impl Trait<…> for Type<…>` a Rust method is declared in: null for an inherent impl, or none. */
function rustTraitImplHeader(method: Node, context: ResolutionContext): RustImplHeader | null {
  let memo = RUST_IMPL_HEADERS.get(context);
  if (!memo) RUST_IMPL_HEADERS.set(context, (memo = new Map()));
  const hit = memo.get(method.id);
  if (hit !== undefined) return hit;
  let header: RustImplHeader | null = null;
  const lines = context.getFileLines?.(method.filePath) ?? context.readFile(method.filePath)?.split(/\r?\n/) ?? [];
  for (let i = method.startLine - 2; i >= 0; i--) {
    const line = lines[i] ?? '';
    if (/^\s*(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?impl\b/.test(line)) {
      let text = line.replace(/\/\/.*$/, '');
      for (let j = i + 1; !text.includes('{') && j < Math.min(lines.length, i + 8); j++) text += ` ${(lines[j] ?? '').replace(/\/\/.*$/, '')}`;
      header = parseRustImplHeader(text);
      break;
    }
    // A top-level item above the method means it was not inside an impl.
    if (/^(?:pub(?:\([^)]*\))?\s+)?(?:fn|struct|enum|mod|trait|const|static|type)\b/.test(line)) break;
  }
  memo.set(method.id, header);
  return header;
}

function isRustProjectNamed(name: string, kinds: ReadonlySet<string>, context: ResolutionContext): boolean {
  return context.getNodesByName(name).some((n) => n.language === 'rust' && kinds.has(n.kind));
}

const RUST_TRAIT_KIND = new Set(['trait']);

/**
 * Whether a call's first argument is evidently a `type`: a value built through
 * it (`IDI::Install`, `Str::from(…)`), `self` in an impl of it, or a name the
 * enclosing function declares with it (`fn from(name: Str)`, `let s: Str`).
 */
function rustFirstArgIs(type: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  const method = ref.referenceName.slice(Math.max(ref.referenceName.lastIndexOf(':'), ref.referenceName.lastIndexOf('.')) + 1);
  const text = [(lines[ref.line - 1] ?? '').slice(Math.max(0, ref.column)), ...lines.slice(ref.line, ref.line + 4)].join(' ');
  const open = new RegExp(`\\b${escapeRegExp(method)}\\s*\\(`).exec(text);
  // Not where the reference says: nothing to read, so nothing to veto.
  if (!open) return true;
  let depth = 0;
  let end = open.index + open[0].length;
  for (; end < text.length; end++) {
    const ch = text[end]!;
    if ('([{'.includes(ch)) depth++;
    else if (')]}'.includes(ch)) {
      if (depth === 0) break;
      depth--;
    } else if (ch === ',' && depth === 0) break;
  }
  const arg = text.slice(open.index + open[0].length, end).trim().replace(/^(?:&\s*(?:mut\s+)?|\*)+/, '').replace(/\.clone\(\)$/, '');
  if (new RegExp(`^(?:[A-Za-z_]\\w*::)*${escapeRegExp(type)}\\b`).test(arg)) return true;
  if (!/^[A-Za-z_]\w*$/.test(arg)) return false;
  const declared = new RegExp(`\\b${arg}\\s*:\\s*&?\\s*(?:'\\w+\\s+)?(?:mut\\s+)?(?:[A-Za-z_]\\w*::)*${escapeRegExp(type)}\\b`);
  const built = new RegExp(`\\blet\\s+(?:mut\\s+)?${arg}\\s*=\\s*&?\\s*(?:[A-Za-z_]\\w*::)*${escapeRegExp(type)}\\b`);
  for (let i = ref.line - 1; i >= 0; i--) {
    const line = lines[i] ?? '';
    if (arg === 'self' && /^\s*(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?impl\b/.test(line)) {
      const impl = parseRustImplHeader(`${line} {`);
      return (impl?.self ?? /impl\b(?:\s*<[^>]*>)?\s*(?:[A-Za-z_]\w*::)*([A-Za-z_]\w*)/.exec(line)?.[1]) === type;
    }
    if (arg !== 'self' && (declared.test(line) || built.test(line))) return true;
    // Above the enclosing function, nothing more declares it.
    if (arg !== 'self' && /^\s*(?:pub(?:\([^)]*\))?\s+)?(?:const\s+)?(?:async\s+)?(?:unsafe\s+)?(?:extern\s+"[^"]*"\s+)?fn\s/.test(line)) break;
  }
  return false;
}

/** Whether the file of `ref` has the project trait `trait` in scope: declared or implemented there, or brought in by a `use`. */
function isRustTraitInScope(trait: string, ref: UnresolvedRef, target: Node, context: ResolutionContext): boolean {
  if (ref.filePath === target.filePath) return true;
  const traits = context.getNodesByName(trait).filter((n) => n.kind === 'trait' && n.language === 'rust');
  if (traits.some((t) => t.filePath === ref.filePath)) return true;
  const uses = rustUsesOf(ref.filePath, context);
  if (uses.names.has(trait)) return true;
  // A glob over a prelude or a crate's root may hand it on: it can't be told apart.
  const crates = rustProjectCrates(context);
  if ([...uses.globs].some((g) => g === 'prelude' || g === 'crate' || crates.has(g))) return true;
  return traits.some((t) => rustGlobCovers(uses, t, ref));
}

/**
 * Whether a Rust call can reach this method of a project `impl` on a std type,
 * as Rust picks one. A crate implements only a trait for `String`, `Vec`,
 * `Arc` or `NonNull`, never a method of its own:
 * - a std trait, which it can implement only for one of its own types
 *   (`impl From<IDI> for String`): `String::from(x)` is that impl's only when
 *   `x` is an `IDI`. dioxus's `String::from("…")` calls all went to it,
 *   tokio's `NonNull::from(waiter)` to its `impl From<&Handle> for NonNull<Entry>`;
 * - a trait of the project's (`impl Link for Arc<ScheduledIo>`), reached only
 *   where the trait is in scope: tokio's `Arc::from_raw(ptr)` in `util/wake.rs`
 *   is std's own, its tests' `files.iter()` a `Vec`'s, not a `Storage` impl's.
 */
export function isRustForeignImplCallable(target: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (target.language !== 'rust' || target.kind !== 'method') return true;
  const cut = target.qualifiedName.lastIndexOf('::');
  const owner = cut < 0 ? '' : target.qualifiedName.slice(0, cut).split('::').pop()!;
  if (!RUST_STD_TYPES.has(owner) || isRustProjectNamed(owner, RUST_DECLARED_TYPE_KINDS, context)) return true;
  const impl = rustTraitImplHeader(target, context);
  if (!impl || impl.self !== owner || impl.trait === '') return true;
  // The type's own function of the name, std's, comes first (RUST_STD_INHERENT).
  if (RUST_STD_INHERENT.get(owner)?.has(target.name)) return false;
  if (isRustProjectNamed(impl.trait, RUST_TRAIT_KIND, context)) return isRustTraitInScope(impl.trait, ref, target, context);
  const local = impl.traitArgs.find((t) => isRustProjectNamed(t, RUST_DECLARED_TYPE_KINDS, context));
  return local === undefined || rustFirstArgIs(local, ref, context);
}

/**
 * Whether a Rust call through a type's path can mean `target` (#2614). A
 * type the path names from std or a dependency — through the file's `use`
 * (`J::from(i)` under `use serde_json::Value as J`, `Value::default()` under
 * `use serde_json::Value`) or as written (`serde_json::Value::default()`) —
 * is that crate's own: the project holds a function of it only as its own
 * impl of a trait for it (`impl Blank for serde_json::Value`, `impl From<Fail>
 * for PathBuf`), and a call through a trait's path (`W::flush(s)` under `use
 * std::io::Write as W`) reaches the project's impls of that trait. A
 * same-named function of a project type is another type's: the reporter's
 * `J::from(i)` went to a local `impl From<io::Error> for Fail`, a guess by
 * the name alone, and `Value::default()` to a project `Value` of its own.
 */
export function isRustPathCallReachable(target: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (target.language !== 'rust') return true;
  const segments = ref.referenceName.split('::');
  if (segments.length < 2 || !segments.every((s) => /^[A-Za-z_]\w*$/.test(s))) return true;
  const type = segments[segments.length - 2]!;
  if (!/^[A-Z]/.test(type) || type === 'Self') return true;
  const outside = rustOutsidePathType(type, segments.slice(0, -2), ref, context);
  if (outside === null) return true;
  const impl = target.kind === 'method' ? rustTraitImplHeader(target, context) : null;
  if (!impl) return false;
  if (impl.trait === outside) return true;
  if (impl.self !== outside) return false;
  // The type the impl is for, as its own file names it: the outside one, not a project namesake.
  const head = rustPathHead(impl.selfText.replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)+/, ''));
  const lookup = rustTypeLookup(head?.name ?? impl.self, head?.segments ?? [], target.filePath, context, rustNodeOffset(target, context));
  return lookup.outside || !lookup.nodes.some((n) => RUST_OWNER_KINDS.has(n.kind));
}

/**
 * The name of the type a Rust path `path::type` names from std or a
 * dependency, where the file's `use`s or the path itself say it is from
 * there — `J` under `use serde_json::Value as J` is `Value` — or null: one of
 * the project's, or one nothing written says is from outside it.
 */
function rustOutsidePathType(type: string, path: string[], ref: UnresolvedRef, context: ResolutionContext): string | null {
  const scopes = rustScopesOf(ref.filePath, context);
  const at = scopes ? (scopes.lineStarts[ref.line - 1] ?? 0) + Math.max(0, ref.column) : undefined;
  let root: string | undefined;
  let real = type;
  if (path.length === 0) {
    const bound = rustUsePath(type, ref.filePath, at, context);
    if (!bound || bound.length < 2) return null;
    root = bound[0];
    real = bound[bound.length - 1]!;
  } else {
    root = rustUsePath(path[0]!, ref.filePath, at, context)?.[0] ?? path[0];
  }
  return root !== undefined && isRustOutsideCrate(root, ref, context) ? real : null;
}

/** Whether a Rust path's first segment names std, or a crate the manifests depend on that the project doesn't hold. */
function isRustOutsideCrate(root: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (RUST_STD_ROOTS.has(root)) return true;
  if (root === 'crate' || root === 'self' || root === 'super' || rustProjectCrates(context).has(root)) return false;
  if (!rustDependencyCrates(context).has(root)) return false;
  // A path dependency the project holds, a workspace member or not, is the project's.
  const graph = rustCrateGraph(context);
  const own = rustCrateDirOf(ref.filePath, graph);
  if (own !== null && graph.crates.get(own)?.keys.has(root)) return false;
  for (const crate of graph.crates.values()) if (crate.name === root) return false;
  return true;
}

/** Whether `type` is a Rust enum that declares `variant` (#2328). */
function declaresRustVariant(type: Node, variant: string, context: ResolutionContext): boolean {
  if (type.kind !== 'enum') return false;
  const qualified = `${type.qualifiedName}::${variant}`;
  const named = context.getNodesInFileNamed?.(type.filePath, variant) ?? context.getNodesInFile(type.filePath);
  return named.some((n) => n.kind === 'enum_member' && n.qualifiedName === qualified);
}

/** The line of the `impl` / `trait` header above `ref` in its file (0 for none). */
function rustEnclosingImplLine(ref: UnresolvedRef, context: ResolutionContext): number {
  return rustImplLineAt(ref.filePath, ref.line, context);
}

/** The line of the `impl` / `trait` header at or above `line` of `filePath` (0 for none). */
function rustImplLineAt(filePath: string, line: number, context: ResolutionContext): number {
  const lines = context.getFileLines?.(filePath) ?? context.readFile(filePath)?.split(/\r?\n/) ?? [];
  for (let i = line - 1; i >= 0; i--) {
    if (/^\s*(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?(?:impl|trait)\b/.test(lines[i] ?? '')) return i + 1;
  }
  return 0;
}

interface RustSelfType {
  /** Its name (`TcpListener`), or the trait's in a trait's own body. */
  type: string;
  /** The first segment of the path it is written with (`tokio` of `tokio::net::TcpListener`), if any. */
  root: string | null;
  /** The trait a trait impl implements. */
  trait: string | null;
  /** Inside a trait's own body. */
  isTrait: boolean;
}

/** The type `Self` is where `ref` is written: its `impl`'s implementing type (and trait), or the trait it sits in. */
function rustSelfType(ref: UnresolvedRef, context: ResolutionContext): RustSelfType | null {
  const header = rustEnclosingImplLine(ref, context);
  if (header === 0) return null;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  let text = (lines[header - 1] ?? '').replace(/\/\/.*$/, '');
  for (let j = header; !text.includes('{') && j < Math.min(lines.length, header + 8); j++) text += ` ${(lines[j] ?? '').replace(/\/\/.*$/, '')}`;
  const trait = /^\s*(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?trait\s+([A-Za-z_]\w*)/.exec(text)?.[1];
  if (trait) return { type: trait, root: null, trait: null, isTrait: true };
  const impl = parseRustImplHeader(text);
  // The type as written: `tokio::net::TcpListener` after a trait impl's `for`,
  // or right after an inherent impl's `impl<T: Into<U>>`.
  const written = (impl
    ? /\sfor\s+(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)?((?:[A-Za-z_]\w*\s*::\s*)*[A-Za-z_]\w*)/.exec(text)
    : /\bimpl\b\s*(?:<(?:[^<>]|<[^<>]*>)*>)?\s*((?:[A-Za-z_]\w*\s*::\s*)*[A-Za-z_]\w*)/.exec(text))?.[1]?.split('::').map((s) => s.trim()) ?? [];
  const type = impl ? impl.self : written[written.length - 1];
  if (!type) return null;
  return { type, root: written.length > 1 ? written[0]! : null, trait: impl?.trait || null, isTrait: false };
}

/**
 * Whether `Self`'s type comes from outside the project: written through std's
 * or a dependency's path, brought in by an outside `use`, or a std type the
 * project doesn't declare. Its own functions are then nothing the index holds.
 */
function isRustOutsideSelf(self: RustSelfType, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (self.root !== null) return self.root === 'std' || self.root === 'core' || self.root === 'alloc' || rustDependencyCrates(context).has(self.root);
  const uses = rustUsesOf(ref.filePath, context);
  if (uses.external.has(self.type) && !uses.bound.has(self.type)) return true;
  return RUST_STD_TYPES.has(self.type) && !isRustProjectNamed(self.type, RUST_DECLARED_TYPE_KINDS, context);
}

const RUST_SELF_PATH_KINDS = new Set(['method', 'function', 'enum_member']);

/**
 * A Rust `Self::x(…)` call is `x` of the type `Self` is where it is written:
 * `Self::new(…)` in `impl Error` is `Error::new`, `Self::Text(…)` in `impl
 * Message` its variant, and in a trait impl or a trait's own body the trait's
 * method when the type has none. The receiver names no type of its own, so a
 * guess by the name alone took such a call only when nothing else shared the
 * name: clap's 118 `Self::new(…)`-style calls stayed unresolved, tokio's 56.
 * The type's own file first — where its impls are — then the nearest. Null
 * when the type has no such function the index holds — the call is then no
 * other type's — and undefined when there is no `impl` or `trait` around it.
 */
function matchRustSelfPath(name: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const self = rustSelfType(ref, context);
  if (!self) return undefined;
  // An outside type (axum's `impl Listener for tokio::net::TcpListener`) has
  // only the project's impls on it, written beside the call: another type of
  // its name elsewhere is not it.
  const outside = !self.isTrait && isRustOutsideSelf(self, ref, context);
  // A trait's method is one its own body declares: clap's `impl<T: Parser>
  // Parser for Box<T>` calls `Self::new`, which is `Box::new`, not the
  // `new` of a struct also named `Parser`.
  const inTrait = (n: Node, trait: string): boolean => (context.getNodesInFileNamed?.(n.filePath, trait) ?? context.getNodesInFile(n.filePath))
    .some((t) => t.kind === 'trait' && t.name === trait && t.startLine <= n.startLine && (t.endLine ?? 0) >= n.startLine);
  const pick = (owner: string, trait = false): Node | null => {
    const all = context.getNodesByName(name).filter((n) => n.language === 'rust' && RUST_SELF_PATH_KINDS.has(n.kind) &&
      (n.qualifiedName === `${owner}::${name}` || n.qualifiedName.endsWith(`::${owner}::${name}`)) && (!trait || inTrait(n, owner)) &&
      (trait || !outside || n.filePath === ref.filePath) &&
      // `fn local_addr(&self) { Self::local_addr(self) }` in a trait impl hands
      // the call on to the type's own function of that name, never to itself;
      // in the type's own impl it is a recursion (gleam's `resolve_type_var_id`).
      (self.trait === null || n.id !== ref.fromNodeId));
    // Rust looks up the type's own (inherent) function first, `#[cfg]` twins
    // of it standing for one another; a trait impl's only when there is none,
    // and several trait impls of one name (`From<A>`, `From<B>`) can't be told apart.
    const inherent = all.filter((n) => !isRustTraitImplMethod(n, context));
    const candidates = inherent.length > 0 ? inherent : all.length === 1 ? all : [];
    if (candidates.length === 0) return null;
    const own = candidates.find((n) => n.filePath === ref.filePath);
    if (own) return own;
    let best = candidates[0]!;
    let score = computePathProximity(ref.filePath, best.filePath);
    for (const c of candidates.slice(1)) {
      const s = computePathProximity(ref.filePath, c.filePath);
      if (s > score) {
        score = s;
        best = c;
      }
    }
    return best;
  };
  // The trait's own method only where nothing could shadow it: an outside
  // type may have an inherent one of the name, and `fn local_addr(&self) {
  // Self::local_addr(self) }` hands the call on to the type's own.
  const delegates = context.getNodeById?.(ref.fromNodeId)?.name === name;
  const target = pick(self.type, self.isTrait) ?? (self.trait && !outside && !delegates ? pick(self.trait, true) : null);
  if (!target) return null;
  return { original: ref, targetNodeId: target.id, confidence: target.filePath === ref.filePath ? 0.9 : 0.8, resolvedBy: 'qualified-name' };
}

/**
 * A Rust call through a generic type parameter of the function or `impl`
 * around it — `Key::get(…)` in protobuf's `fn map_get<Key: MapKey>`, with
 * `trait MapKey: FfiMapKey` — is to the method one of the traits its bounds
 * name declares, or one of the traits they extend: `FfiMapKey::get`. Bounds
 * only from outside the project (`T: Default`) name no project method, nor do
 * two traits that both declare it: null. Undefined when `name` is no generic
 * parameter there.
 */
function matchRustGenericPath(name: string, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const scopes = rustScopesOf(ref.filePath, context);
  if (!scopes) return undefined;
  const written: RustWrittenType = { text: name, file: ref.filePath, at: (scopes.lineStarts[ref.line - 1] ?? 0) + Math.max(0, ref.column) };
  const bounds = rustGenericBounds(name, written, context);
  if (bounds === undefined) return undefined;
  const traits = bounds.filter((b) => !/^['?]/.test(b.trim()) && !RUST_MARKER_TRAITS.has(rustPathHead(b)?.name ?? ''));
  if (traits.length === 0) return null;
  const result = rustTraitsMethodCall(traits, written, method, ref, context);
  if (result === 'unread') return null;
  // (The bound names the trait, so its method is reached as a typed call is:
  // its missing `pub` doesn't hide it from another module.)
  if (result) {
    let typed = RUST_TYPED_REFS.get(context);
    if (!typed) RUST_TYPED_REFS.set(context, (typed = new WeakSet()));
    typed.add(ref);
  }
  return result;
}

/**
 * Whether `candidate` is declared directly in an inline `mod <name> { … }` of
 * its own file — the only way a path through `name` reaches it, since an
 * inline module adds nothing to its items' qualified names. The module is the
 * innermost block rustModBlocks finds around it; a file whose braces don't
 * all close says nothing.
 */
function isInRustInlineModule(candidate: Node, name: string, context: ResolutionContext): boolean {
  const layout = rustUsesOf(candidate.filePath, context);
  if (!layout.balanced) return false;
  const at = (layout.lineStarts[candidate.startLine - 1] ?? 0) + Math.max(0, candidate.startColumn ?? 0);
  return rustBlockAt(layout.blocks, at)?.name === name;
}

/** Whether `candidate` is declared in the same `impl` / `trait` block as `ref`, above it. */
function isInEnclosingRustImpl(candidate: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const header = rustEnclosingImplLine(ref, context);
  return header > 0 && candidate.filePath === ref.filePath && candidate.startLine >= header && candidate.startLine <= ref.line;
}

/** Whether `name` is a generic type parameter of the function or impl around `ref` (`fn f<V: Visitor>`, `impl<'de, E>`). */
/**
 * Whether `name`, at `column` of `line`, is a trait's associated type bound
 * in that trait's arguments: `Iterator<Item = &str>`, `Writable<M: 'static>`.
 * An unclosed `<` before it on the line says it is inside them.
 */
function isRustAssocBinding(line: string, column: number, name: string): boolean {
  if (!line.startsWith(name, column) || !/^\s*(?:=(?![=>])|:(?!:))/.test(line.slice(column + name.length))) return false;
  let angles = 0;
  let parens = 0;
  for (let i = column - 1; i >= 0; i--) {
    const c = line[i];
    if (c === '>' && line[i - 1] !== '-') angles++;
    else if (c === '<') {
      if (angles === 0) return parens === 0;
      angles--;
    } else if (c === ')') parens++;
    else if (c === '(') {
      if (parens === 0) return false;
      parens--;
    } else if (c === '{' || c === '}' || c === ';') return false;
  }
  return false;
}

/**
 * The qualified self a path ends in, written right before `::X`: `<T as
 * Trait<A>>::X` gives `T` and `Trait`, `<T>::X` gives `T` and no trait —
 * each as the last segment of its path, without generics. Null when the text
 * is no qualified self (a turbofish, `Vec::<T>::new`, is not one).
 */
function rustQualifiedSelf(before: string): { self: string; trait: string | null } | null {
  const text = before.replace(/\s*::\s*$/, '');
  if (!text.endsWith('>')) return null;
  let depth = 0;
  let open = -1;
  for (let i = text.length - 1; i >= 0 && open < 0; i--) {
    if (text[i] === '>' && text[i - 1] !== '-') depth++;
    else if (text[i] === '<' && --depth === 0) open = i;
  }
  if (open < 0 || /::\s*$/.test(text.slice(0, open))) return null;
  const inner = text.slice(open + 1, -1).trim();
  const head = (part: string): string =>
    /((?:[A-Za-z_]\w*\s*::\s*)*)([A-Za-z_]\w*)\s*(?:<[\s\S]*)?$/.exec(part.replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?|dyn\s+)+/, '').trim())?.[2] ?? '';
  const as = /\s+as\s+/.exec(inner);
  const self = head(as ? inner.slice(0, as.index) : inner);
  return self ? { self, trait: as ? head(inner.slice(as.index + as[0].length)) || null : null } : null;
}

function isRustGenericParam(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!/^[A-Z]\w*$/.test(name)) return false;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  const from = Math.max(0, rustEnclosingImplLine(ref, context) - 1);
  const text = lines.slice(from, ref.line).join('\n');
  return new RegExp(`<[^<>]*(?:<[^<>]*>[^<>]*)*\\b${name}\\b\\s*(?:[:,>=])`).test(text);
}

/**
 * Whether `name` is a type parameter the `fn` or the `impl` around `ref`
 * declares in its own generics (`fn read<R: AsyncRead>(…)`, `impl<T> …`) —
 * not a type its arguments merely name, as `Pin<&mut File>` names `File`.
 */
function isRustTypeParam(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  const headerAt = (line: number): string => {
    let text = '';
    for (let j = line - 1; j >= 0 && j < Math.min(lines.length, line + 7) && !/[{;]/.test(text); j++) text += ` ${(lines[j] ?? '').replace(/\/\/.*$/, '')}`;
    return text;
  };
  return [enclosingScopeStartLine(ref, context), rustEnclosingImplLine(ref, context)].some((line) => {
    if (line === 0) return false;
    const header = headerAt(line);
    const open = /\b(?:fn\s+[A-Za-z_]\w*|impl)\s*</.exec(header);
    if (!open) return false;
    let depth = 0;
    let from = open.index + open[0].length;
    for (let i = from - 1; i < header.length; i++) {
      const ch = header[i];
      const param = (): boolean => new RegExp(`^\\s*(?:const\\s+)?${escapeRegExp(name)}\\b`).test(header.slice(from, i));
      if (ch === '<') depth++;
      else if (ch === '>' && header[i - 1] !== '-' && --depth === 0) return param();
      else if (ch === ',' && depth === 1) {
        if (param()) return true;
        from = i + 1;
      }
    }
    return false;
  });
}

// A Rust method call on a local or a parameter — `opts.build()` — is a call
// on the type that name is declared with where the call is (the binding
// rust-scopes.ts reads), resolved as Rust resolves it on that type.

const RUST_SCOPES = new WeakMap<ResolutionContext, Map<string, RustScopes | null>>();

/**
 * A Rust file read for its bindings (readRustScopes), for the files used
 * last: calls arrive file by file, and each looks into the files declaring
 * what it reaches.
 */
function rustScopesOf(filePath: string, context: ResolutionContext): RustScopes | null {
  let memo = RUST_SCOPES.get(context);
  if (!memo) RUST_SCOPES.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit !== undefined) {
    memo.delete(filePath);
    memo.set(filePath, hit);
    return hit;
  }
  const source = context.readFile(filePath);
  const scopes = source === null ? null : readRustScopes(source);
  if (memo.size >= 64) memo.delete(memo.keys().next().value!);
  memo.set(filePath, scopes);
  return scopes;
}

/** The 1-based line of an offset in a file read by rustScopesOf. */
function rustLineAt(scopes: RustScopes, offset: number): number {
  let lo = 0;
  let hi = scopes.lineStarts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (scopes.lineStarts[mid]! <= offset) lo = mid;
    else hi = mid - 1;
  }
  return lo + 1;
}

/**
 * A Rust type as some declaration writes it: its text, and the file and
 * offset it is written at, whose `use`s, generics and `impl` say what its
 * names are. `self` is the type `Self` names in a type's own declaration (an
 * enum's variant), `generics` that declaration's parameters; `wrappers` the
 * `Box`, `Rc`, `Arc`… the value is held in, which a call reaches through.
 */
interface RustWrittenType {
  text: string;
  file: string;
  at: number;
  self?: string;
  generics?: string;
  wrappers?: string[];
  /**
   * Generic parameters the type names that a call's value fixes, which
   * nothing here says: `W` in `build<W: WriteColor>(…) -> Standard<W>`. A
   * value that is one of them is unread, whatever its bound.
   */
  opaque?: string[];
  /**
   * What a declaration's own parameters are known by where the type is
   * reached: through `self` in `impl<S: Store> Worker<S>`, the struct's `S`
   * is the impl's, a `Store`. The traits are read where the impl is.
   */
  bounds?: ReadonlyMap<string, { traits: string[]; file: string; at: number }>;
}

/**
 * What a Rust type is, for calling a method on it, and the wrappers
 * (`MutexGuard<'_, T>`) a call goes through to reach it, outermost first.
 */
type RustTypeRead = (
  /** A type by its path: `crate::work::Worker`, `Overrides<BuildArgs>`. */
  | { kind: 'named'; name: string; path: string[]; args: string }
  /** A trait object, an `impl Trait` or a bounded generic: the traits it is known by. */
  | { kind: 'traits'; traits: string[] }
  /** A type the project doesn't declare: std's, a dependency's, a primitive, a tuple, a pointer. */
  | { kind: 'outside'; name: string }
) & { wrappers: string[]; byRef: boolean; written: RustWrittenType } | { kind: 'unread' };

/** Types that hand a method call on to what they hold (they `Deref` to it) when the method is not their own. */
const RUST_DEREF_WRAPPERS: ReadonlySet<string> = new Set([
  'Box', 'Rc', 'Arc', 'Pin', 'Cow', 'MutexGuard', 'RwLockReadGuard', 'RwLockWriteGuard', 'Ref', 'RefMut', 'ManuallyDrop',
]);
/** The std wrappers a method's `self` can be declared through (rustSelfWrapper). */
const RUST_SELF_WRAPPERS: ReadonlySet<string> = new Set(['Pin', 'Box', 'Rc', 'Arc']);
/** Traits a bound or a trait object may name that give it no methods. */
const RUST_MARKER_TRAITS: ReadonlySet<string> = new Set(['Send', 'Sync', 'Unpin', 'Sized', 'Copy', 'UnwindSafe', 'RefUnwindSafe']);
const RUST_PRIMITIVE_TYPES: ReadonlySet<string> = new Set([
  'bool', 'char', 'str', 'u8', 'u16', 'u32', 'u64', 'u128', 'usize', 'i8', 'i16', 'i32', 'i64', 'i128', 'isize', 'f32', 'f64',
]);
const RUST_OWNER_KINDS: ReadonlySet<string> = new Set(['struct', 'enum', 'union']);

/** The offset of the `>` closing the `<` at `open` in a type's text, or -1. */
function rustAngleEnd(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    const c = text[i];
    if (c === '<') depth++;
    else if (c === '>' && text[i - 1] !== '-' && --depth === 0) return i;
  }
  return -1;
}

/** A type's path: `crate::work::Worker` → segments `crate`, `work` and name `Worker`; `Overrides<BuildArgs>` its arguments too. */
function rustPathHead(text: string): { segments: string[]; name: string; args: string } | null {
  let t = text.trim().replace(/^::\s*/, '');
  let args = '';
  const open = t.indexOf('<');
  if (open >= 0) {
    if (rustAngleEnd(t, open) !== t.length - 1) return null;
    args = t.slice(open + 1, -1).trim();
    t = t.slice(0, open).trim().replace(/\s*::\s*$/, '');
  }
  const parts = t.split('::').map((s) => s.trim());
  if (!parts.every((p) => /^[A-Za-z_]\w*$/.test(p))) return null;
  const name = parts.pop()!;
  return { segments: parts, name, args };
}

/** A `{…}` or `(…)` that closes only at the text's end. */
function rustGroupIsWhole(text: string): boolean {
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') {
      if (--depth === 0) return i === text.length - 1;
    }
  }
  return false;
}

/** A value that ends in a call — `Foo::new(a)`, `x.unwrap()` — as its callee's text and arguments. */
function rustTrailingCall(value: string): { callee: string; args: string } | null {
  if (!value.endsWith(')')) return null;
  let depth = 0;
  for (let i = value.length - 1; i >= 0; i--) {
    const c = value[i];
    if (c === ')' || c === ']' || c === '}') depth++;
    else if (c === '(' || c === '[' || c === '{') {
      if (--depth === 0) {
        if (c !== '(') return null;
        // `Vec::<u8>::new()`: the turbofish is the callee's.
        return { callee: value.slice(0, i).trim(), args: value.slice(i + 1, -1) };
      }
    }
  }
  return null;
}

/** The text after a Rust function signature's `->`: `(…) -> Result<Self>` → `Result<Self>`. */
function rustReturnText(signature: string | undefined): string | null {
  if (!signature?.startsWith('(')) return null;
  let depth = 0;
  for (let i = 0; i < signature.length; i++) {
    const c = signature[i];
    if (c === '(') depth++;
    else if (c === ')' && --depth === 0) {
      const ret = /^\s*->\s*([\s\S]+)$/.exec(signature.slice(i + 1))?.[1]?.trim();
      return ret || null;
    }
  }
  return null;
}

/** What `times` `?`s / `.unwrap()`s take a value of the written type to: the `T` of `Result<T, E>` or `Option<T>`. */
function rustUnwrapped(written: RustWrittenType, times: number): RustWrittenType | null {
  let text = written.text;
  for (let i = 0; i < times; i++) {
    const head = rustPathHead(text);
    if (!head || (head.name !== 'Result' && head.name !== 'Option')) return null;
    const first = splitRustTopLevel(head.args, ',')[0];
    if (!first) return null;
    text = first;
  }
  return { ...written, text };
}

/** A path a Rust `use` binds a name to, and the block it is written in (file-level: from -1). */
interface RustUseBinding {
  path: string[];
  from: number;
  to: number;
}

const RUST_USE_PATHS = new WeakMap<ResolutionContext, Map<string, Map<string, RustUseBinding[]>>>();

/**
 * The names a Rust file's `use`s bind, each to the path it binds, the item's
 * own name last: `use crate::net::config::Config as NetConfig;` binds
 * `NetConfig` to `crate::net::config::Config`, `use std::io::{self, Read};`
 * `io` to `std::io`. A glob binds no name. A `use` in a block binds only
 * there: ripgrep's flag definitions each `use … as Separator` a type of
 * their own.
 */
function rustUseBindings(filePath: string, context: ResolutionContext): Map<string, RustUseBinding[]> {
  let memo = RUST_USE_PATHS.get(context);
  if (!memo) RUST_USE_PATHS.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit) return hit;
  const bindings = new Map<string, RustUseBinding[]>();
  const scopes = rustScopesOf(filePath, context);
  for (const m of (scopes?.code ?? '').matchAll(/(?:^|[;{}\s])use\s+([^;]{1,2000});/g)) {
    const bound = new Map<string, string[]>();
    expandRustUse(m[1]!, [], bound);
    const block = scopes ? rustInnerBlockAt(scopes, m.index!) : null;
    for (const [name, path] of bound) {
      const list = bindings.get(name) ?? [];
      list.push({ path, from: block ? block[0] : -1, to: block ? block[1] : Infinity });
      bindings.set(name, list);
    }
  }
  if (memo.size >= 256) memo.delete(memo.keys().next().value!);
  memo.set(filePath, bindings);
  return bindings;
}

/** The path a `use` in scope at `at` binds `name` to — the innermost block's first — or a file-level `use`'s without `at`. */
function rustUsePath(name: string, filePath: string, at: number | undefined, context: ResolutionContext): string[] | undefined {
  let best: RustUseBinding | undefined;
  for (const b of rustUseBindings(filePath, context).get(name) ?? []) {
    const visible = at === undefined ? b.from < 0 : at > b.from && at < b.to;
    if (visible && (!best || b.from > best.from)) best = b;
  }
  return best?.path;
}

function expandRustUse(tree: string, prefix: string[], bound: Map<string, string[]>): void {
  const t = tree.trim().replace(/^::\s*/, '');
  if (t === '') return;
  const open = t.indexOf('{');
  if (open >= 0 && t.endsWith('}')) {
    const head = t.slice(0, open).replace(/::\s*$/, '').trim();
    const within = [...prefix, ...(head === '' ? [] : head.split('::').map((s) => s.trim()))];
    let depth = 0;
    let start = open + 1;
    for (let i = open + 1; i < t.length - 1; i++) {
      const c = t[i];
      if (c === '{') depth++;
      else if (c === '}') depth--;
      else if (c === ',' && depth === 0) {
        expandRustUse(t.slice(start, i), within, bound);
        start = i + 1;
      }
    }
    expandRustUse(t.slice(start, t.length - 1), within, bound);
    return;
  }
  const m = /^((?:[A-Za-z_]\w*\s*::\s*)*)([A-Za-z_]\w*|\*)(?:\s+as\s+([A-Za-z_]\w*))?$/.exec(t);
  if (!m || m[2] === '*' || m[3] === '_') return;
  const segments = [...prefix, ...(m[1] ? m[1].split('::').map((s) => s.trim()).filter(Boolean) : [])];
  if (m[2] === 'self') {
    const name = m[3] ?? segments[segments.length - 1];
    if (name) bound.set(name, segments);
    return;
  }
  bound.set(m[3] ?? m[2]!, [...segments, m[2]!]);
}

/** The module path of a Rust file in its crate: `crates/cli/src/net/config.rs` → `net`, `config`; a `lib.rs` none. */
function rustModulePath(filePath: string): string[] {
  const parts = filePath.split('/');
  let at = -1;
  for (let i = parts.length - 2; i >= 0; i--) {
    if (parts[i] === 'src' || parts[i] === 'tests' || parts[i] === 'examples' || parts[i] === 'benches') {
      at = i;
      break;
    }
  }
  const modules = parts.slice(at + 1);
  const file = modules.pop()!.replace(/\.rs$/, '');
  if (file !== 'mod' && file !== 'lib' && file !== 'main') modules.push(file);
  return modules;
}

/**
 * Whether the modules a path walks (`net::config`) are, in order, among those
 * of the file declaring `n`: a path may name a type through a module that
 * re-exports it (`tokio::sync::Mutex` is `sync/mutex.rs`'s).
 */
function rustModulesLead(modules: string[], n: Node): boolean {
  let k = 0;
  for (const m of rustModulePath(n.filePath)) if (k < modules.length && m === modules[k]) k++;
  return k === modules.length;
}

const RUST_WALKED_ITEMS = new WeakMap<ResolutionContext, Map<string, Set<string> | null>>();

/**
 * The ids of the items a Rust path names from the module around `at` in
 * `file` (rustUsePathItems); null where the project's modules can't be
 * walked along it.
 */
function rustWalkedItems(segs: string[], file: string, at: number | undefined, context: ResolutionContext): Set<string> | null {
  const from = rustModuleAt(file, at ?? 0, context);
  let memo = RUST_WALKED_ITEMS.get(context);
  if (!memo) RUST_WALKED_ITEMS.set(context, (memo = new Map()));
  const key = `${file}\0${from.block?.open ?? -1}\0${segs.join('::')}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const items = rustUsePathItems(segs, from, context, new Set());
  const ids = items === null ? null : new Set(items.map((n) => n.id));
  memo.set(key, ids);
  return ids;
}

/** The project types a Rust type name can mean where it is written. */
interface RustTypeLookup {
  /** Its declarations the name can mean there. */
  nodes: Node[];
  /** It names a type from outside the project: std's, a dependency's, a primitive. */
  outside: boolean;
  /** No project type has the name: a dependency's, or one a macro declares, whose impls the index may hold. */
  undeclared?: boolean;
  /** The name, if a `use … as` renamed it. */
  name: string;
}

/**
 * The type a name written in `file` — bare, or through `path` — means there:
 * the one a `use` brings in by that path, the file's own, one a glob brings
 * in. std's, a dependency's or a primitive is outside the project.
 */
function rustTypeLookup(name: string, writtenPath: string[], file: string, context: ResolutionContext, at?: number): RustTypeLookup {
  let segments = writtenPath;
  let real = name;
  let viaUse = false;
  if (segments.length === 0) {
    const bound = rustUsePath(name, file, at, context);
    if (bound && bound.length > 1) {
      real = bound[bound.length - 1]!;
      segments = bound.slice(0, -1);
      viaUse = true;
    }
  } else {
    // `io::Error` under `use std::io;`: the path starts at what a `use` binds.
    const head = rustUsePath(segments[0]!, file, at, context);
    if (head && head.length > 0) segments = [...head, ...segments.slice(1)];
  }
  const outside: RustTypeLookup = { nodes: [], outside: true, name: real };
  const root = segments[0];
  const crates = rustProjectCrates(context);
  if (root === 'std' || root === 'core' || root === 'alloc') return outside;
  if (root !== undefined && !crates.has(root) && rustDependencyCrates(context).has(root)) return outside;
  if (segments.length === 0 && RUST_PRIMITIVE_TYPES.has(real)) return outside;
  const fileRef = { filePath: file } as UnresolvedRef;
  const all = context.getNodesByName(real).filter((n) => n.language === 'rust' && n.name === real && RUST_DECLARED_TYPE_KINDS.has(n.kind));
  if (all.length === 0) {
    if (segments.length === 0 && (RUST_STD_TYPES.has(real) || RUST_PRELUDE.has(real))) return outside;
    return { nodes: [], outside: false, undeclared: true, name: real };
  }
  let nodes = all.filter((n) => isRustItemVisibleFrom(n, fileRef, context));
  // A path the project's modules can be walked along, written or the one a
  // `use` binds, names the item of the module it walks to, as a `use` does in
  // isRustNameInScope: tokio's `crate::runtime::Handle` is the one
  // `runtime/mod.rs` re-exports. The modules' names decide where it can't.
  if (segments.length > 0) {
    const walked = rustWalkedItems([...segments, real], file, at, context);
    const named = walked === null ? [] : nodes.filter((n) => walked.has(n.id));
    if (named.length > 0) return { nodes: named, outside: false, name: real };
  }
  const modules = segments.filter((s) => s !== 'crate' && s !== 'self' && s !== 'super' && !crates.has(s));
  if (modules.length > 0) {
    let within = nodes.filter((n) => rustModulesLead(modules, n));
    // Through a path from a crate's root, the nearest module re-exports it:
    // `tokio::runtime::Handle` is `runtime/handle.rs`'s, not a scheduler's
    // `Handle` deeper down.
    if (within.length > 1 && root !== undefined && (root === 'crate' || crates.has(root))) {
      const depth = (n: Node): number => rustModulePath(n.filePath).length;
      const nearest = Math.min(...within.map(depth));
      within = within.filter((n) => depth(n) === nearest);
    }
    if (within.length > 0) nodes = within;
  }
  if (root !== undefined) nodes = nodes.filter((n) => rustUseCanReach(new Set([root]), n, fileRef, context));
  if (segments.length === 0 && !viaUse) {
    const same = nodes.filter((n) => n.filePath === file);
    if (same.length > 0) return { nodes: same, outside: false, name: real };
    const u = rustUsesOf(file, context);
    if (u.external.has(real) && !u.bound.has(real)) return outside;
    // What the file's globs bring in, by the modules they walk to where those
    // can be followed (rustGlobScope): dioxus's autofmt reads `AttributeValue`
    // through `use dioxus_rsx::*`.
    const globbed = nodes.filter((n) => rustGlobScope(real, n, u, fileRef, context));
    if (globbed.length > 0) return { nodes: globbed, outside: false, name: real };
    if (RUST_STD_TYPES.has(real) || RUST_PRELUDE.has(real)) return outside;
    // In scope some way the file doesn't write — a parent module's glob, a
    // macro's `use`: a type of its own module tree, or of its directory, or
    // else any (the method then tells them apart, rustTypedMethodCall).
    const dir = path.posix.dirname(file);
    const near = nodes.filter((n) => file.startsWith(`${rustModuleDir(n.filePath)}/`) || path.posix.dirname(n.filePath) === dir);
    if (near.length > 0) nodes = near;
  }
  return { nodes, outside: false, name: real };
}

/**
 * What a Rust type as written is, for a method call on it: the type it names
 * through `&`, `Box`, `Rc`, `Arc`, `Pin`… (its `wrappers`); the traits a
 * trait object, an `impl Trait` or a bounded generic is known by; `Self` the
 * type of the `impl` (or trait) it is written in.
 */
function rustReadType(written: RustWrittenType, ref: UnresolvedRef, context: ResolutionContext): RustTypeRead {
  const wrappers: string[] = [...(written.wrappers ?? [])];
  const byRef = written.text.trim().startsWith('&');
  let t = written.text.trim();
  for (let i = 0; i < 8; i++) {
    const before = t;
    t = t.replace(/^&\s*(?:'\w+\s+)?(?:mut\s+)?/, '').replace(/^mut\s+/, '').trim();
    const wrapper = /^(?:::\s*)?(?:(?:std|alloc|core)\s*::\s*(?:\w+\s*::\s*)*)?([A-Za-z_]\w*)\s*</.exec(t);
    if (wrapper && RUST_DEREF_WRAPPERS.has(wrapper[1]!)) {
      const open = wrapper[0].length - 1;
      if (rustAngleEnd(t, open) === t.length - 1) {
        t = t.slice(open + 1, -1).replace(/^\s*'\w+\s*,/, '').trim();
        wrappers.push(wrapper[1]!);
      }
    }
    if (t === before) break;
  }
  if (t === '' || t === '_' || t === '!') return { kind: 'unread' };
  const object = /^(dyn|impl)\s+([\s\S]+)$/.exec(t);
  if (object) {
    const traits = splitRustTopLevel(object[2]!, '+').filter((b) => !/^['?]/.test(b) && !RUST_MARKER_TRAITS.has(rustPathHead(b)?.name ?? ''));
    return traits.length === 0 ? { kind: 'outside', name: object[1]!, wrappers, byRef, written } : { kind: 'traits', traits, wrappers, byRef, written };
  }
  // A tuple, an array or a slice, a pointer, a function: nothing the project declares.
  if (/^[([*]/.test(t) || /^(?:unsafe\s+|extern\s+"[^"]*"\s+)*fn\s*\(/.test(t)) return { kind: 'outside', name: t[0]!, wrappers, byRef, written };
  const head = rustPathHead(t);
  if (!head) return { kind: 'unread' };
  const { segments, name, args } = head;
  // `Self::Item`, `T::Output`: an associated type.
  if (segments.length > 0 && (segments[0] === 'Self' || rustGenericBounds(segments[0]!, written, context) !== undefined)) return { kind: 'unread' };
  if (segments.length === 0 && name === 'Self') {
    if (written.self) return { kind: 'named', name: written.self, path: [], args: '', wrappers, byRef, written };
    const scopes = rustScopesOf(written.file, context);
    const self = rustSelfType({ ...ref, filePath: written.file, line: scopes ? rustLineAt(scopes, written.at) : ref.line }, context);
    if (!self) return { kind: 'unread' };
    if (self.isTrait) return { kind: 'traits', traits: [self.type], wrappers, byRef, written };
    return { kind: 'named', name: self.type, path: self.root ? [self.root] : [], args: '', wrappers, byRef, written };
  }
  if (segments.length === 0) {
    if (written.opaque?.includes(name)) return { kind: 'unread' };
    const known = written.bounds?.get(name);
    if (known) {
      const traits = known.traits.filter((b) => !/^['?]/.test(b.trim()) && !RUST_MARKER_TRAITS.has(rustPathHead(b)?.name ?? ''));
      if (traits.length === 0) return { kind: 'unread' };
      return { kind: 'traits', traits, wrappers, byRef, written: { text: written.text, file: known.file, at: known.at } };
    }
    const bounds = rustGenericBounds(name, written, context);
    if (bounds !== undefined) {
      const traits = bounds.filter((b) => !RUST_MARKER_TRAITS.has(rustPathHead(b)?.name ?? ''));
      return traits.length === 0 ? { kind: 'unread' } : { kind: 'traits', traits, wrappers, byRef, written };
    }
    if (RUST_PRIMITIVE_TYPES.has(name)) return { kind: 'outside', name, wrappers, byRef, written };
  }
  return { kind: 'named', name, path: segments, args, wrappers, byRef, written };
}

/**
 * The bounds of a generic parameter `name` where a type is written: those of
 * the function and the `impl` or trait around it. Empty for a declaration's
 * own parameter (an enum's `T`), which is whatever a use of it makes it;
 * undefined when `name` is no generic parameter there.
 */
function rustGenericBounds(name: string, written: RustWrittenType, context: ResolutionContext): string[] | undefined {
  if (written.generics !== undefined) return rustBoundsOf(name, [{ generics: written.generics, where: '' }]) === undefined ? undefined : [];
  const scopes = rustScopesOf(written.file, context);
  if (!scopes) return undefined;
  const items: Array<{ generics: string; where: string }> = [];
  const fn = rustFnAt(scopes, written.at);
  if (fn) items.push(fn);
  const block = rustImplAt(scopes, written.at);
  if (block) items.push(block);
  return items.length === 0 ? undefined : rustBoundsOf(name, items);
}

/** What the binding a Rust receiver names writes of its type, if it writes it. */
function rustBindingType(binding: RustBinding, scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number): RustWrittenType | null {
  if (binding.type !== undefined) return { text: binding.type, file: ref.filePath, at: binding.at };
  if (binding.kind === 'for') {
    // `for x in …`: an element of what the loop iterates; `for (k, v) in …` a field of that element.
    const element = binding.scrutinee === undefined ? null : rustIteratedElement(binding.scrutinee, binding.at, scopes, ref, context, depth);
    if (!element || !binding.site) return element;
    return binding.site.path === '' && binding.site.index !== undefined ? rustTupleField(element, binding.site.index) : null;
  }
  if (binding.init !== undefined) return rustValueType(binding.init, binding.at, scopes, ref, context, depth);
  if (binding.site) return rustSiteType(binding.site, binding.scrutinee, binding.at, scopes, ref, context, depth);
  return null;
}

/** The type of another local, as its binding in scope at `at` writes it. */
function rustLocalType(name: string, at: number, scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number): RustWrittenType | null {
  if (depth > 3) return null;
  const found = rustBindingAt(scopes, name, at);
  return found && !found.ambiguous ? rustBindingType(found.binding, scopes, ref, context, depth + 1) : null;
}

/**
 * The type a Rust value is, where its text says: a struct literal or a
 * tuple-struct's or variant's construction (`Opts { … }`, `Message::Text(s)`),
 * a unit struct, a function's or an associated function's return
 * (`Server::new()`, `load(…)?`), a `Box` / `Rc` / `Arc` of one, another
 * local, a literal. Null when the text says nothing of it (a method chain, a
 * block, a macro).
 */
function rustValueType(value: string, at: number, scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number): RustWrittenType | null {
  if (depth > 3) return null;
  let v = value.trim();
  let unwraps = 0;
  let awaits = 0;
  for (;;) {
    const before = v;
    if (/\.\s*await$/.test(v)) {
      v = v.replace(/\s*\.\s*await$/, '');
      awaits++;
    }
    if (v.endsWith('?')) {
      v = v.slice(0, -1).trimEnd();
      unwraps++;
    }
    const tail = rustTrailingCall(v);
    if (tail && /\.\s*(?:unwrap|expect)$/.test(tail.callee)) {
      v = tail.callee.replace(/\s*\.\s*(?:unwrap|expect)$/, '');
      unwraps++;
    }
    if (v === before) break;
  }
  v = v.replace(/^&\s*(?:mut\s+)?/, '').trim();
  const local = (text: string): RustWrittenType => ({ text, file: ref.filePath, at });
  const unwrapped = (t: RustWrittenType | null): RustWrittenType | null => (t && unwraps > 0 ? rustUnwrapped(t, unwraps) : t);
  // A literal, a closure or an array: nothing the project declares.
  if (/^(?:[bc]?r#*)?"[^"]*"#*$|^b?'[^']*'$|^-?\d[\w.]*$|^(?:true|false)$|^(?:move\s+)?\|/.test(v) ||
      (v.startsWith('[') && rustGroupIsWhole(v))) return local('()');
  if (/^(?:vec|format)\s*!\s*[[({]/.test(v) && rustGroupIsWhole(v.slice(v.search(/[[({]/)))) return local(v.startsWith('vec') ? 'Vec<_>' : 'String');
  if (v.startsWith('(')) {
    if (!rustGroupIsWhole(v)) return null;
    const inner = v.slice(1, -1);
    return splitRustTopLevel(inner, ',').length === 1 && !/,\s*$/.test(inner)
      ? unwrapped(rustValueType(inner, at, scopes, ref, context, depth + 1)) : local('()');
  }
  const call = rustTrailingCall(v);
  if (call && /^[A-Za-z_][\w:\s<>,]*$/.test(call.callee) && !call.callee.includes('.')) {
    const callee = call.callee.replace(/\s+/g, '').replace(/::<[^()]*>$/, '');
    if (!/^[A-Za-z_]\w*(?:::[A-Za-z_]\w*)*$/.test(callee)) return null;
    const segments = callee.split('::');
    const last = segments[segments.length - 1]!;
    // `Box::new(x)`, `Arc::new(x)`: what it holds, reached through it.
    const wrapper = /^(?:(?:std|alloc)::(?:boxed|rc|sync)::)?(Box|Rc|Arc)::(?:new|pin|from)$/.exec(callee)?.[1];
    if (wrapper && splitRustTopLevel(call.args, ',').length === 1) {
      const held = rustValueType(call.args, at, scopes, ref, context, depth + 1);
      return held && unwraps === 0 ? { ...held, wrappers: [wrapper, ...(held.wrappers ?? [])] } : null;
    }
    if (/^[A-Z]/.test(last)) {
      // A tuple struct (`Wrapper(x)`) or a variant (`Message::Text(s)`, `Some(x)`).
      if (segments.length === 1 && last === 'Some') return unwrapped(local('Option<_>'));
      if (segments.length === 1 && (last === 'Ok' || last === 'Err')) return unwrapped(local('Result<_, _>'));
      if (/^[A-Z][A-Z0-9_]*$/.test(last) && last.length > 1) return null;
      if (segments.length >= 2 && /^[A-Z]/.test(segments[segments.length - 2]!)) return unwrapped(local(segments.slice(0, -1).join('::')));
      return unwrapped(local(callee));
    }
    if (segments.length >= 2 && /^[A-Z]/.test(segments[segments.length - 2]!)) {
      return rustAssociatedReturn(segments.slice(0, -1), last, unwraps, at, ref, context);
    }
    return rustFunctionReturn(segments.slice(0, -1), last, unwraps, at, ref, context);
  }
  if (call) {
    // `x.clone()` is a value of `x`'s type.
    const cloned = call.args.trim() === '' ? /^([a-z_]\w*)\s*\.\s*clone$/.exec(call.callee) : null;
    if (cloned) return unwrapped(rustLocalType(cloned[1]!, at, scopes, ref, context, depth));
    // `x.m(…)`, `self.m(…)`, `x.m(…)?.n(…)`: what the method it reaches returns.
    const method = /^([\s\S]+?)\s*\.\s*([a-z_]\w*)\s*(?:::\s*<([^()]*)>)?$/.exec(call.callee);
    return method ? rustMethodReturn(method[1]!, method[2]!, method[3], unwraps, awaits, at, scopes, ref, context, depth) : null;
  }
  // `self.items`, `opts.config.port`, `pair.0`: the field's type as its struct declares it.
  const access = /^([\s\S]+?)\s*\.\s*([A-Za-z_]\w*|\d+)$/.exec(v);
  if (access && !/^\d/.test(v)) return unwrapped(rustFieldValue(access[1]!, access[2]!, at, scopes, ref, context, depth));
  const literal = /^((?:[A-Za-z_]\w*\s*::\s*)*[A-Z]\w*)\s*(?:::\s*<[^{}]*>\s*)?\{/.exec(v);
  if (literal) {
    if (!rustGroupIsWhole(v.slice(v.indexOf('{')))) return null;
    // A struct variant's literal is a value of its enum: `Outcome::Ignore { note: None }` is an `Outcome`.
    const segments = literal[1]!.replace(/\s+/g, '').split('::');
    return unwrapped(local((segments.length >= 2 && /^[A-Z]/.test(segments[segments.length - 2]!) ? segments.slice(0, -1) : segments).join('::')));
  }
  if (/^[A-Za-z_]\w*(?:\s*::\s*[A-Za-z_]\w*)*$/.test(v)) {
    const segments = v.split('::').map((s) => s.trim());
    const last = segments[segments.length - 1]!;
    if (segments.length === 1 && /^[a-z_]/.test(last)) return unwrapped(rustLocalType(last, at, scopes, ref, context, depth));
    if (!/^[A-Z]/.test(last) || (/^[A-Z][A-Z0-9_]*$/.test(last) && last.length > 1)) return null;
    if (segments.length === 1 && last === 'None') return local('Option<_>');
    // A unit variant is a value of its enum: `Mode::Fast` is a `Mode`.
    if (segments.length >= 2 && /^[A-Z]/.test(segments[segments.length - 2]!)) return local(segments.slice(0, -1).join('::'));
    return unwrapped(local(segments.join('::')));
  }
  return null;
}

/** Where a node starts in its file, as an offset into rustScopesOf's text. */
function rustNodeOffset(n: Node, context: ResolutionContext): number {
  const scopes = rustScopesOf(n.filePath, context);
  return (scopes?.lineStarts[n.startLine - 1] ?? 0) + (n.startColumn ?? 0);
}

/**
 * Where a function's return type is read from: its parameter list, inside
 * the function, so its own generic parameters are in scope there —
 * dioxus's `use_hook<State: Clone>(…) -> State` returns whatever `State` is.
 */
function rustSignatureOffset(fn: Node, context: ResolutionContext): number {
  const start = rustNodeOffset(fn, context);
  const scopes = rustScopesOf(fn.filePath, context);
  const own = scopes?.fns.find((f) => f.at >= start && f.at <= start + 512);
  return own ? own.from + 1 : start;
}

/**
 * What `Type::f(…)` returns, read from the signature of the type's `f`:
 * `Self` is the type. A type from outside the project makes, as far as a
 * call on it goes, no project value; one whose `f` the index doesn't hold
 * (a derived `Default`) is taken to make itself only through `new` and `default`.
 */
function rustAssociatedReturn(owner: string[], fn: string, unwraps: number, at: number, ref: UnresolvedRef, context: ResolutionContext): RustWrittenType | null {
  const written: RustWrittenType = { text: owner.join('::'), file: ref.filePath, at };
  const read = rustReadType(written, ref, context);
  // An outside type's function the index can't read: one that constructs
  // makes the type (`File::open(p)?`, `Vec::with_capacity(n)`); another may
  // hand out anything — `Arc::make_mut(&mut self.node)` is a `&mut Node`.
  const constructs = /^(?:new|default|from|open|create|connect|bind|empty|(?:new|with|from)_\w+)$/.test(fn);
  if (read.kind === 'outside') return constructs ? written : null;
  if (read.kind !== 'named') return null;
  const lookup = rustTypeLookup(read.name, read.path, read.written.file, context, read.written.at);
  if (lookup.outside) return constructs ? written : null;
  const fns = rustOwnedMethods(lookup.name, fn, lookup, context);
  if (fns.length === 0) return (fn === 'new' || fn === 'default') && unwraps === 0 ? written : null;
  const returns = new Set(fns.map((f) => rustReturnText(f.signature) ?? ''));
  if (returns.size !== 1) return null;
  const text = [...returns][0]!;
  if (text === '') return null;
  const made: RustWrittenType = { text, file: fns[0]!.filePath, at: rustSignatureOffset(fns[0]!, context) };
  const value = unwraps > 0 ? rustUnwrapped(made, unwraps) : made;
  // `Self`, or the type's own name, is the type the call names, where it
  // names it: `Semaphore::new(1)` under `use tokio::sync::Semaphore` is that
  // `Semaphore`, whichever of the types the name may mean has the `new` read
  // here, and so is ripgrep's `grep::regex::RegexMatcherBuilder::new()`,
  // pcre2's `new` writing the same `-> RegexMatcherBuilder`. Any other text
  // means what it does where it is written, which several types' files may
  // read differently.
  if (value && (value.text.trim() === 'Self' || rustPathHead(value.text)?.name === read.name)) return written;
  return new Set(fns.map((f) => f.filePath)).size > 1 ? null : value;
}

/** What a free function `f(…)` or `module::f(…)` returns, read from its signature, when one function of the name is in reach. */
function rustFunctionReturn(modules: string[], fn: string, unwraps: number, at: number, ref: UnresolvedRef, context: ResolutionContext): RustWrittenType | null {
  let fns = context.getNodesByName(fn).filter((n) => n.language === 'rust' && n.kind === 'function' && n.name === fn);
  const same = fns.filter((n) => n.filePath === ref.filePath);
  if (same.length > 0 && modules.length === 0) {
    fns = same;
  } else {
    // The path the call writes, its head as a `use` binds it (`oneshot::channel()`
    // under tokio's `use crate::runtime::tests::loom_oneshot as oneshot`), or
    // the one a `use` binds the bare name to.
    let path: string[];
    if (modules.length === 0) {
      const used = rustUsePath(fn, ref.filePath, at, context);
      if (!used) return null;
      path = used;
    } else {
      const head = rustUsePath(modules[0]!, ref.filePath, at, context);
      path = [...(head && head.length > 0 ? head : [modules[0]!]), ...modules.slice(1), fn];
    }
    // The function the project's modules walk to, else the one whose file's modules the path names.
    const walked = rustWalkedItems(path, ref.filePath, at, context);
    const named = walked === null ? [] : fns.filter((n) => walked.has(n.id));
    if (named.length > 0) {
      fns = named;
    } else {
      const segments = path.slice(0, -1).filter((s) => s !== 'crate' && s !== 'self' && s !== 'super' && !rustProjectCrates(context).has(s));
      if (segments.length > 0) fns = fns.filter((n) => rustModulesLead(segments, n));
    }
  }
  const returns = new Set(fns.map((f) => rustReturnText(f.signature) ?? ''));
  if (fns.length === 0 || returns.size !== 1) return null;
  const text = [...returns][0]!;
  if (text === '') return null;
  const made: RustWrittenType = { text, file: fns[0]!.filePath, at: rustSignatureOffset(fns[0]!, context) };
  return unwraps > 0 ? rustUnwrapped(made, unwraps) : made;
}

/**
 * What a method call's value is — `let b = builder.port(80)`, `let s =
 * self.state()?`, `let n = conn.next_frame().await?` — read from the
 * signature of the method the call reaches on its receiver's type
 * (rustTypedMethodCall), where `Self` is that method's impl type. A receiver
 * is a local, `self`, or another call's value. Null where any step can't be
 * told: a receiver or a method from outside the project, a return type
 * naming the impl's or the method's own generics, an `async fn` not awaited.
 */
function rustMethodReturn(
  receiver: string, method: string, turbofish: string | undefined, unwraps: number, awaits: number, at: number,
  scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number,
): RustWrittenType | null {
  let memo = RUST_METHOD_RETURNS.get(context);
  if (!memo) RUST_METHOD_RETURNS.set(context, (memo = new Map()));
  const key = `${ref.filePath}\0${at}\0${receiver}\0${method}\0${turbofish ?? ''}\0${unwraps}\0${awaits}\0${depth}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const made = readRustMethodReturn(receiver, method, turbofish, unwraps, awaits, at, scopes, ref, context, depth);
  if (memo.size >= 4096) memo.delete(memo.keys().next().value!);
  memo.set(key, made);
  return made;
}

const RUST_METHOD_RETURNS = new WeakMap<ResolutionContext, Map<string, RustWrittenType | null>>();

function readRustMethodReturn(
  receiver: string, method: string, turbofish: string | undefined, unwraps: number, awaits: number, at: number,
  scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number,
): RustWrittenType | null {
  const recv = receiver.trim();
  let written: RustWrittenType | null;
  if (recv === 'self') written = { text: 'Self', file: ref.filePath, at };
  else if (/^[a-z_]\w*$/.test(recv)) written = rustLocalType(recv, at, scopes, ref, context, depth);
  else if (/[)?]$|\.\s*(?:[A-Za-z_]\w*|\d+)$/.test(recv)) written = rustValueType(recv, at, scopes, ref, context, depth + 1);
  else return null;
  if (!written) return null;
  const read = rustReadType(written, ref, context);
  const result = rustTypedMethodCall(read, method, ref, context);
  if (!result || result === 'unread') return null;
  const target = context.getNodeById?.(result.targetNodeId);
  const text = target ? rustReturnText(target.signature) : null;
  if (!target || !text) return null;
  let made: RustWrittenType | null = { text, file: target.filePath, at: rustSignatureOffset(target, context) };
  made = rustReturnInstance(made, target, turbofish, read, at, ref, context);
  // An `async fn`'s value is a future of what it returns; `.await` hands that out.
  const isAsync = rustIsAsyncFn(target, context);
  if (awaits > 1 || (awaits === 0 && isAsync)) return null;
  if (awaits === 1 && !isAsync) made = rustFutureOutput(made);
  return made && unwraps > 0 ? rustUnwrapped(made, unwraps) : made;
}

/**
 * A method's return type as the call makes it, where it names a generic or
 * `Self`: the method's own type parameters are what the call's turbofish
 * writes (clap's `arg.get::<ArgValueCompleter>()` on `fn get<T: ArgExt>(&self)
 * -> Option<&T>`), read where the call is, when the rest of the type is std's;
 * a trait's provided method's `Self` is the receiver's own type. A parameter
 * the call doesn't write, or one of the impl's, stays opaque: the type is
 * still the one its head names (`Standard<W>` is a `Standard`), but a value
 * that is the parameter itself is unread, the bound alone not telling.
 */
function rustReturnInstance(
  made: RustWrittenType, target: Node, turbofish: string | undefined, read: RustTypeRead, at: number,
  ref: UnresolvedRef, context: ResolutionContext,
): RustWrittenType {
  const names = [...made.text.matchAll(/(?<!['\w])([A-Za-z_]\w*)/g)].map((m) => m[1]!)
    .filter((n) => !/^(?:mut|dyn|impl|const|for)$/.test(n));
  const generics = names.filter((n) => n !== 'Self' && rustGenericBounds(n, made, context) !== undefined);
  if (generics.length === 0) {
    // `fn with_x(self) -> Self` in a trait: the value is the receiver's type, not the trait.
    const bare = made.text.replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)+/, '').trim();
    if (bare === 'Self' && read.kind === 'named' && rustTraitOf(target, context) !== null) {
      const typeText = [...read.path, read.name].join('::') + (read.args ? `<${read.args}>` : '');
      return { text: made.text.replace(/Self\s*$/, typeText), file: read.written.file, at: read.written.at };
    }
    return made;
  }
  const opaque: RustWrittenType = { ...made, opaque: [...new Set(generics)] };
  if (turbofish === undefined) return opaque;
  const scopes = rustScopesOf(made.file, context);
  const own = scopes ? rustFnAt(scopes, made.at) : undefined;
  const params = own ? splitRustTopLevel(own.generics, ',').map((p) => /^\s*(?:const\s+)?([A-Za-z_]\w*)/.exec(p)?.[1]).filter((p): p is string => p !== undefined) : [];
  const args = splitRustTopLevel(turbofish, ',').map((a) => a.trim()).filter((a) => !a.startsWith("'"));
  const bound = new Map<string, string>();
  for (const g of new Set(generics)) {
    const i = params.indexOf(g);
    if (i < 0 || i >= args.length || args[i] === '_') return opaque;
    bound.set(g, args[i]!);
  }
  // The type is then read where the call writes the turbofish: anything else it names must mean the same there.
  if (names.some((n) => !bound.has(n) && (n === 'Self' || !(RUST_STD_TYPES.has(n) || RUST_PRELUDE.has(n) || RUST_PRIMITIVE_TYPES.has(n))))) return opaque;
  const text = made.text.replace(/(?<!['\w])([A-Za-z_]\w*)/g, (n) => bound.get(n) ?? n);
  return { text, file: ref.filePath, at };
}

/** Whether a Rust function is declared `async`, read off its source: the extractor's flag never says. */
function rustIsAsyncFn(fn: Node, context: ResolutionContext): boolean {
  const scopes = rustScopesOf(fn.filePath, context);
  if (!scopes) return false;
  const start = rustNodeOffset(fn, context);
  const head = scopes.code.slice(start, start + 300);
  const name = head.search(new RegExp(`\\bfn\\s+(?:r#)?${escapeRegExp(fn.name.replace(/^r#/, ''))}\\b`));
  return name >= 0 && /\basync\b/.test(head.slice(0, name));
}

/**
 * What `.await` hands out of a value of a Rust future type: the `Output` of
 * `impl Future<Output = T>` or a `Pin<Box<dyn Future<Output = T>>>`, the `T`
 * of futures' `BoxFuture<'_, T>`. Null for any other type.
 */
function rustFutureOutput(written: RustWrittenType): RustWrittenType | null {
  let t = written.text.trim();
  for (const wrapper of [/^(?:(?:std|core)\s*::\s*pin\s*::\s*)?Pin\s*</, /^(?:(?:std|alloc)\s*::\s*boxed\s*::\s*)?Box\s*</]) {
    const open = wrapper.exec(t);
    if (open && rustAngleEnd(t, open[0].length - 1) === t.length - 1) t = t.slice(open[0].length, -1).trim();
  }
  const boxed = /^(?:[A-Za-z_]\w*\s*::\s*)*(?:BoxFuture|LocalBoxFuture)\s*</.exec(t);
  if (boxed) {
    if (rustAngleEnd(t, boxed[0].length - 1) !== t.length - 1) return null;
    const args = splitRustTopLevel(t.slice(boxed[0].length, -1), ',').filter((a) => !/^'/.test(a.trim()));
    return args.length === 1 ? { ...written, text: args[0]!.trim() } : null;
  }
  const future = /^(?:impl|dyn)\s+(?:(?:std|core)\s*::\s*future\s*::\s*)?(?:Future|IntoFuture)\s*</.exec(t);
  if (!future) return null;
  const end = rustAngleEnd(t, future[0].length - 1);
  if (end < 0 || !/^\s*(?:\+[\s\S]*)?$/.test(t.slice(end + 1))) return null;
  const output = splitRustTopLevel(t.slice(future[0].length, end), ',').map((a) => /^\s*Output\s*=\s*([\s\S]+)$/.exec(a)?.[1]).find((o) => o !== undefined);
  return output ? { ...written, text: output.trim() } : null;
}

/**
 * What a Rust field access is — `self.items`, `opts.config`, `pair.0` — as
 * the receiver's struct declares the field, read where the struct is written
 * (its own generics opaque, the field's type being whatever a value of it
 * makes them). Null when the receiver isn't one struct of the project's.
 */
function rustFieldValue(
  receiver: string, field: string, at: number, scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number,
): RustWrittenType | null {
  const recv = receiver.trim();
  let written: RustWrittenType | null;
  if (recv === 'self') written = { text: 'Self', file: ref.filePath, at };
  else if (/^[a-z_]\w*$/.test(recv)) written = rustLocalType(recv, at, scopes, ref, context, depth);
  else written = rustValueType(recv, at, scopes, ref, context, depth + 1);
  if (!written) return null;
  const read = rustReadType(written, ref, context);
  // `self.pair.0` on a field declared `(Config, u8)`: the tuple's field at that place.
  if (read.kind === 'outside' && read.name === '(' && /^\d+$/.test(field)) return rustTupleField(written, Number(field));
  if (read.kind !== 'named') return null;
  const lookup = rustTypeLookup(read.name, read.path, read.written.file, context, read.written.at);
  const structs = lookup.outside ? [] : lookup.nodes.filter((n) => n.kind === 'struct' || n.kind === 'union');
  if (structs.length !== 1) return null;
  const decl = structs[0]!;
  const fields = rustDeclaredFields(decl, context);
  const text = /^\d+$/.test(field) ? fields?.tuple?.[Number(field)] : fields?.named?.get(field);
  if (!fields || !text) return null;
  const value: RustWrittenType = { text, file: decl.filePath, at: rustNodeOffset(decl, context), self: decl.name, generics: fields.generics };
  if (recv === 'self') {
    const bounds = rustSelfParamBounds(fields.generics, scopes, at, ref.filePath);
    if (bounds) value.bounds = bounds;
  }
  return value;
}

/**
 * What the struct's own type parameters are known by inside the impl around
 * `at`: the bounds of the impl's parameter each one is instantiated with,
 * by position — `struct Worker<S>` under `impl<S: Store> Worker<S>` gives
 * `S` → `Store`. Undefined where the impl's type arguments don't line up
 * with the struct's parameters, or none is a bounded parameter of the impl.
 */
function rustSelfParamBounds(structGenerics: string, scopes: RustScopes, at: number, file: string): Map<string, { traits: string[]; file: string; at: number }> | undefined {
  if (structGenerics.trim() === '') return undefined;
  const block = rustImplAt(scopes, at);
  if (!block || block.kind !== 'impl') return undefined;
  // `impl<S: Store> [Trait for] Worker<S>`: the type after the impl's generics and a top-level ` for `.
  let header = scopes.code.slice(block.at, block.from).replace(/^impl\b/, '').trim();
  if (header.startsWith('<')) {
    const end = rustAngleEnd(header, 0);
    if (end < 0) return undefined;
    header = header.slice(end + 1).trim();
  }
  let depth = 0;
  for (let i = 0; i < header.length; i++) {
    const c = header[i];
    if (c === '<') depth++;
    else if (c === '>' && header[i - 1] !== '-') depth--;
    else if (depth === 0 && /\s/.test(c!) && /^for\s/.test(header.slice(i + 1))) {
      header = header.slice(i + 4).trim();
      break;
    }
  }
  const self = rustPathHead(header.replace(/\bwhere\b[\s\S]*$/, '').trim());
  if (!self) return undefined;
  const args = splitRustTopLevel(self.args, ',').map((a) => a.trim()).filter((a) => a !== '');
  const params = splitRustTopLevel(structGenerics, ',').map((p) => /^\s*(?:const\s+)?('?[A-Za-z_]\w*)/.exec(p)?.[1] ?? '');
  if (params.length !== args.length) return undefined;
  const own = new Set(splitRustTopLevel(block.generics, ',').map((p) => /^\s*(?:const\s+)?([A-Za-z_]\w*)/.exec(p)?.[1]));
  const bounds = new Map<string, { traits: string[]; file: string; at: number }>();
  params.forEach((p, i) => {
    const arg = args[i]!;
    if (p === '' || p.startsWith("'") || !own.has(arg)) return;
    const traits = rustBoundsOf(arg, [{ generics: block.generics, where: block.where }]);
    if (traits && traits.length > 0) bounds.set(p, { traits, file, at });
  });
  return bounds.size > 0 ? bounds : undefined;
}

/** The `index`th field of a Rust tuple type as written — `(K, V)` → `V` for 1 — through `&`; null for any other type. */
function rustTupleField(written: RustWrittenType, index: number): RustWrittenType | null {
  const t = written.text.trim().replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)+/, '');
  if (!t.startsWith('(') || !rustGroupIsWhole(t)) return null;
  const fields = splitRustTopLevel(t.slice(1, -1), ',').map((f) => f.trim()).filter((f) => f !== '');
  return index < fields.length ? { ...written, text: fields[index]!, wrappers: undefined } : null;
}

/** Std adapters that hand on the items of what they are called on. */
const RUST_ITEM_ADAPTERS: ReadonlySet<string> = new Set([
  'iter', 'iter_mut', 'into_iter', 'drain', 'rev', 'copied', 'cloned', 'skip', 'take', 'step_by', 'peekable', 'by_ref', 'fuse',
]);
/** Std adapters that pick a map's keys or values, or number the items. */
const RUST_ITEM_PROJECTIONS: ReadonlyMap<string, 'key' | 'value' | 'enumerate'> = new Map([
  ['keys', 'key'], ['into_keys', 'key'], ['values', 'value'], ['values_mut', 'value'], ['into_values', 'value'], ['enumerate', 'enumerate'],
]);

/**
 * What a Rust `for` loop binds, an item of what it iterates: `for a in
 * cmd.get_arguments()` with `-> impl Iterator<Item = &Arg>` an `Arg`, `for x
 * in &self.items` with `items: Vec<Item>` an `Item`, `for (i, v) in
 * map.values().enumerate()` a `(usize, V)`. The std adapters that keep the
 * items (`.iter()`, `.rev()`, `.skip(n)`) or project them (`.values()`,
 * `.enumerate()`) are looked through only where the value they are called on
 * is read: a project method of the name is read from its own signature.
 */
function rustIteratedElement(iter: string, at: number, scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number): RustWrittenType | null {
  let v = iter.trim();
  const steps: string[] = [];
  for (let i = 0; i < 8; i++) {
    const value = rustValueType(v.replace(/^&\s*(?:mut\s+)?/, ''), at, scopes, ref, context, depth + 1);
    if (value) return rustStepItems(value, steps.reverse(), context);
    const call = rustTrailingCall(v);
    const m = call ? /^([\s\S]+?)\s*\.\s*([a-z_]\w*)$/.exec(call.callee) : null;
    if (!m || !(RUST_ITEM_ADAPTERS.has(m[2]!) || RUST_ITEM_PROJECTIONS.has(m[2]!))) return null;
    steps.push(m[2]!);
    v = m[1]!;
  }
  return null;
}

/** The items a value hands out through std adapters, innermost first. */
function rustStepItems(value: RustWrittenType, steps: string[], context: ResolutionContext): RustWrittenType | null {
  let projection: 'key' | 'value' | undefined;
  let numbered = false;
  for (const step of steps) {
    const p = RUST_ITEM_PROJECTIONS.get(step);
    if (p === 'enumerate') {
      if (numbered) return null;
      numbered = true;
    } else if (p) {
      if (numbered || projection) return null;
      projection = p;
    }
  }
  const item = rustItemOf(value, projection, context);
  return item && numbered ? { ...item, text: `(usize, ${item.text})` } : item;
}

/** Std collections whose items are their one type argument. */
const RUST_STD_SEQUENCES: ReadonlySet<string> = new Set([
  'Vec', 'VecDeque', 'HashSet', 'BTreeSet', 'BinaryHeap', 'LinkedList', 'Option', 'IndexSet', 'SmallVec',
]);
const RUST_STD_MAPS: ReadonlySet<string> = new Set(['HashMap', 'BTreeMap', 'IndexMap']);
/** Std iterator types by what they hand out: an item, a map's entry, key or value. */
const RUST_STD_ITERATORS: ReadonlyMap<string, 'item' | 'entry' | 'key' | 'value'> = new Map([
  ['Iter', 'entry'], ['IterMut', 'entry'], ['IntoIter', 'entry'], ['Drain', 'entry'],
  ['Keys', 'key'], ['IntoKeys', 'key'], ['Values', 'value'], ['ValuesMut', 'value'], ['IntoValues', 'value'],
]);
const RUST_ITERATOR_TRAITS: ReadonlySet<string> = new Set(['Iterator', 'IntoIterator', 'DoubleEndedIterator', 'ExactSizeIterator']);

/**
 * The item type a value of a Rust type hands out when iterated: a std
 * sequence's or a slice's element, a std map's `(K, V)` (its key or value
 * through `.keys()` / `.values()`), a std iterator's item, an `impl Iterator<Item
 * = T>`'s `T`, through `&` and the pointers that deref to what they hold.
 * Read where the type is written. Null for any other type.
 */
function rustItemOf(written: RustWrittenType, projection: 'key' | 'value' | undefined, context: ResolutionContext): RustWrittenType | null {
  let t = written.text.trim();
  for (let i = 0; i < 6; i++) {
    const before = t;
    t = t.replace(/^&\s*(?:'\w+\s+)?(?:mut\s+)?/, '').trim();
    const pointer = /^(?:(?:std|alloc|core)\s*::\s*(?:\w+\s*::\s*)*)?(?:Box|Rc|Arc|Cow|Ref|RefMut|MutexGuard|RwLockReadGuard|RwLockWriteGuard)\s*</.exec(t);
    if (pointer && rustAngleEnd(t, pointer[0].length - 1) === t.length - 1) t = t.slice(pointer[0].length, -1).replace(/^\s*'\w+\s*,/, '').trim();
    if (t === before) break;
  }
  const as = (text: string | undefined): RustWrittenType | null => (text ? { ...written, text: text.trim(), wrappers: undefined } : null);
  const typeArgs = (args: string): string[] => splitRustTopLevel(args, ',').map((a) => a.trim()).filter((a) => a !== '' && !a.startsWith("'"));
  const std = (name: string): boolean => !isRustProjectNamed(name, RUST_DECLARED_TYPE_KINDS, context);
  if (t.startsWith('[')) {
    if (!rustGroupIsWhole(t) || projection) return null;
    return as(splitRustTopLevel(t.slice(1, -1), ';')[0]);
  }
  const object = /^(?:impl|dyn)\s+([\s\S]+)$/.exec(t);
  if (object) {
    if (projection) return null;
    for (const bound of splitRustTopLevel(object[1]!, '+')) {
      const head = rustPathHead(bound.trim());
      if (!head || !RUST_ITERATOR_TRAITS.has(head.name)) continue;
      return as(typeArgs(head.args).map((a) => /^Item\s*=\s*([\s\S]+)$/.exec(a)?.[1]).find((a) => a !== undefined));
    }
    return null;
  }
  const head = rustPathHead(t);
  if (!head || !std(head.name)) return null;
  const args = typeArgs(head.args);
  if (RUST_STD_SEQUENCES.has(head.name)) return projection || args.length !== 1 ? null : as(args[0]);
  if (RUST_STD_MAPS.has(head.name)) {
    if (args.length < 2) return null;
    return projection === 'key' ? as(args[0]) : projection === 'value' ? as(args[1]) : as(`(${args[0]}, ${args[1]})`);
  }
  const iterator = RUST_STD_ITERATORS.get(head.name);
  if (!iterator) return null;
  if (iterator === 'key' || iterator === 'value') return projection || args.length !== 2 ? null : as(args[iterator === 'key' ? 0 : 1]);
  if (args.length === 1) return projection ? null : as(args[0]);
  if (args.length === 2) return projection === 'key' ? as(args[0]) : projection === 'value' ? as(args[1]) : as(`(${args[0]}, ${args[1]})`);
  return null;
}

/**
 * The type a name a pattern binds is: in `Some(x)` / `Ok(x)` / `Err(e)` what
 * the matched value's `Option` or `Result` holds; in a variant's or a
 * struct's pattern (`Commands::Build(opts)`, `Point { x, .. }`) the field's
 * type its declaration writes.
 */
function rustSiteType(site: RustPatternSite, scrutinee: string | undefined, at: number, scopes: RustScopes, ref: UnresolvedRef, context: ResolutionContext, depth: number): RustWrittenType | null {
  // `let (a, b) = …`, `(k, v) =>`: the matched tuple's field at the name's place.
  if (site.path === '') {
    if (site.index === undefined || !scrutinee) return null;
    const value = rustValueType(scrutinee, at, scopes, ref, context, depth + 1);
    return value ? rustTupleField(value, site.index) : null;
  }
  const segments = site.path.split('::');
  const last = segments[segments.length - 1]!;
  if (segments.length === 1 && (last === 'Some' || last === 'Ok' || last === 'Err')) {
    if (site.index !== 0 || !scrutinee) return null;
    const value = rustValueType(scrutinee, at, scopes, ref, context, depth + 1);
    const head = value && rustPathHead(value.text.replace(/^&\s*(?:'\w+\s+)?(?:mut\s+)?/, ''));
    if (!value || !head) return null;
    const args = splitRustTopLevel(head.args, ',');
    if (last === 'Some' && head.name === 'Option' && args.length === 1) return { ...value, text: args[0]! };
    if (last === 'Ok' && head.name === 'Result' && args.length >= 1) return { ...value, text: args[0]! };
    if (last === 'Err' && head.name === 'Result' && args.length === 2) return { ...value, text: args[1]! };
    return null;
  }
  const decl = rustPatternDeclaration(segments, at, ref, context);
  if (!decl) return null;
  const text = site.index !== undefined ? decl.fields.tuple?.[site.index] : site.field !== undefined ? decl.fields.named?.get(site.field) : undefined;
  return text ? { text, file: decl.file, at: decl.at, self: decl.self, generics: decl.generics } : null;
}

/** The declaration a tuple-struct, variant or struct pattern's path names, with its fields' types. */
function rustPatternDeclaration(segments: string[], at: number, ref: UnresolvedRef, context: ResolutionContext): { fields: RustFields; file: string; at: number; self: string; generics: string } | null {
  const last = segments[segments.length - 1]!;
  if (segments.length >= 2) {
    // A variant: the enum is the path before it.
    const owner = rustReadType({ text: segments.slice(0, -1).join('::'), file: ref.filePath, at }, ref, context);
    if (owner.kind !== 'named') return null;
    const enums = rustTypeLookup(owner.name, owner.path, owner.written.file, context, owner.written.at).nodes.filter((n) => n.kind === 'enum');
    if (enums.length !== 1) return null;
    const enumNode = enums[0]!;
    const variant = (context.getNodesInFileNamed?.(enumNode.filePath, last) ?? context.getNodesInFile(enumNode.filePath))
      .find((n) => n.kind === 'enum_member' && n.qualifiedName === `${enumNode.qualifiedName}::${last}`);
    if (!variant) return null;
    const fields = rustDeclaredFields(variant, context);
    const generics = rustDeclaredFields(enumNode, context, true)?.generics ?? '';
    return fields ? { fields, file: variant.filePath, at: rustNodeOffset(variant, context), self: enumNode.name, generics } : null;
  }
  const structs = rustTypeLookup(last, [], ref.filePath, context, at).nodes.filter((n) => n.kind === 'struct');
  if (structs.length !== 1) return null;
  const fields = rustDeclaredFields(structs[0]!, context);
  return fields ? { fields, file: structs[0]!.filePath, at: rustNodeOffset(structs[0]!, context), self: structs[0]!.name, generics: fields.generics } : null;
}

/** A struct's or a variant's fields: a tuple's types in order, or a named field's type by its name. */
interface RustFields {
  tuple?: string[];
  named?: Map<string, string>;
  /** The declaration's own generic parameters. */
  generics: string;
}

/** The fields a struct, an enum's variant (or, for its generics, an enum) declares, read from its file. */
const RUST_DECLARED_FIELDS = new WeakMap<ResolutionContext, Map<string, RustFields | null>>();

function rustDeclaredFields(decl: Node, context: ResolutionContext, genericsOnly = false): RustFields | null {
  let memo = RUST_DECLARED_FIELDS.get(context);
  if (!memo) RUST_DECLARED_FIELDS.set(context, (memo = new Map()));
  const key = `${decl.id}${genericsOnly ? '\u0000g' : ''}`;
  if (memo.has(key)) return memo.get(key)!;
  const fields = readRustDeclaredFields(decl, context, genericsOnly);
  memo.set(key, fields);
  return fields;
}

function readRustDeclaredFields(decl: Node, context: ResolutionContext, genericsOnly: boolean): RustFields | null {
  const scopes = rustScopesOf(decl.filePath, context);
  if (!scopes) return null;
  const code = scopes.code;
  const start = rustNodeOffset(decl, context);
  const name = new RegExp(`\\b${escapeRegExp(decl.name)}\\b`).exec(code.slice(start, start + 512));
  if (!name) return null;
  let p = start + name.index + decl.name.length;
  while (p < code.length && /\s/.test(code[p]!)) p++;
  let generics = '';
  if (code[p] === '<') {
    const end = rustAngleEnd(code.slice(p, p + 2000), 0);
    if (end < 0) return null;
    generics = code.slice(p + 1, p + end);
    p += end + 1;
  }
  if (genericsOnly) return { generics };
  // Past a `where` clause, to the fields' bracket.
  let open = p;
  while (open < code.length && code[open] !== '(' && code[open] !== '{' && code[open] !== ';' && code[open] !== ',' && code[open] !== '}') open++;
  const bracket = code[open];
  if (bracket !== '(' && bracket !== '{') return { generics };
  let depth = 0;
  let close = open;
  for (; close < code.length; close++) {
    const c = code[close];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if ((c === ')' || c === ']' || c === '}') && --depth === 0) break;
  }
  const field = (text: string): string => text.replace(/#\s*\[[^[\]]*(?:\[[^[\]]*\][^[\]]*)*\]/g, ' ').replace(/^\s*pub\s*(?:\([^)]*\))?/, '').trim();
  const parts = splitRustTopLevel(code.slice(open + 1, close), ',').map(field);
  if (bracket === '(') return { tuple: parts, generics };
  const named = new Map<string, string>();
  for (const part of parts) {
    const m = /^([A-Za-z_]\w*)\s*:\s*([\s\S]+)$/.exec(part);
    if (m) named.set(m[1]!, m[2]!.trim());
  }
  return { named, generics };
}

/** `Name::method` nodes the index holds, of any type of that name. */
function rustMethodsNamed(name: string, method: string, context: ResolutionContext): Node[] {
  if (context.getMethodMatches) return context.getMethodMatches(name, method, 'rust').filter((m) => m.language === 'rust');
  const want = `${name}::${method}`;
  return context.getNodesByName(method).filter((m) => m.kind === 'method' && m.language === 'rust' &&
    (m.qualifiedName === want || m.qualifiedName.endsWith(`::${want}`)));
}

/**
 * The `Name::method` nodes of the types a lookup found: a namesake type's
 * methods are its own. A method is the type's when it sits in the type's
 * file, or its impl's file names the type by that name.
 */
function rustOwnedMethods(name: string, method: string, lookup: RustTypeLookup, context: ResolutionContext): Node[] {
  // A trait's own declaration of the method is the trait's, whatever type
  // shares its name: gleam's `struct HttpClient` implements `trait HttpClient`.
  const matches = rustMethodsNamed(name, method, context).filter((m) => rustTraitOf(m, context) === null);
  const types = lookup.nodes.filter((n) => RUST_OWNER_KINDS.has(n.kind));
  if (types.length === 0) return matches;
  const namesakes = context.getNodesByName(name).filter((n) => n.language === 'rust' && n.name === name && RUST_OWNER_KINDS.has(n.kind));
  if (namesakes.length <= types.length) return matches;
  const ids = new Set(types.map((t) => t.id));
  const files = new Set(types.map((t) => t.filePath));
  return matches.filter((m) => files.has(m.filePath) || rustTypeLookup(name, [], m.filePath, context, rustNodeOffset(m, context)).nodes.some((n) => ids.has(n.id)));
}

/** The text an `impl` header above a Rust method gives its implementing type's arguments: `BuildArgs` of `impl Overrides<BuildArgs>`. */
function rustImplSelfArgs(method: Node, context: ResolutionContext): { args: string; generics: string; byRef: boolean } | null {
  const scopes = rustScopesOf(method.filePath, context);
  if (!scopes) return null;
  const block = rustImplAt(scopes, rustNodeOffset(method, context));
  if (!block || block.kind !== 'impl') return null;
  const header = scopes.code.slice(block.at, block.from).replace(/\bwhere\b[\s\S]*$/, '');
  const head = header.replace(/^impl\s*(?:<(?:[^<>]|<(?:[^<>]|<[^<>]*>)*>)*>)?/, '');
  const self = /\bfor\s+([\s\S]+)$/.exec(head)?.[1] ?? head;
  const type = rustPathHead(self.trim().replace(/^&\s*(?:'\w+\s+)?(?:mut\s+)?/, ''));
  return type ? { args: type.args, generics: block.generics, byRef: self.trim().startsWith('&') } : null;
}

/**
 * Among methods of one name in several impls of a type, those whose impl is
 * for the type's arguments the receiver has: `impl Overrides<BuildArgs>`'s
 * for an `Overrides<BuildArgs>`, before an `impl<T> Overrides<T>`'s.
 */
function rustSpecialized(methods: Node[], args: string, context: ResolutionContext): Node[] {
  if (methods.length < 2 || args === '') return methods;
  const norm = (text: string): string[] => splitRustTopLevel(text, ',').map((a) => a.replace(/\s+/g, '').replace(/^(?:[A-Za-z_]\w*::)+/, ''));
  const want = norm(args);
  const exact: Node[] = [];
  const generic: Node[] = [];
  for (const m of methods) {
    const impl = rustImplSelfArgs(m, context);
    if (!impl) { generic.push(m); continue; }
    const have = norm(impl.args);
    if (have.length !== want.length) continue;
    if (have.every((a, i) => a === want[i])) exact.push(m);
    else if (have.every((a, i) => a === want[i] || rustBoundsOf(a, [{ generics: impl.generics, where: '' }]) !== undefined)) generic.push(m);
  }
  return exact.length > 0 ? exact : generic.length > 0 ? generic : methods;
}

/** The method among `methods` a call reaches: its own file's, the type's file's, then the nearest. */
function rustPickMethod(methods: Node[], typeFiles: Set<string>, ref: UnresolvedRef, confidence: number): ResolvedRef {
  const chosen = methods.find((m) => m.filePath === ref.filePath) ?? methods.find((m) => typeFiles.has(m.filePath)) ??
    methods.reduce((best, m) => (computePathProximity(ref.filePath, m.filePath) > computePathProximity(ref.filePath, best.filePath) ? m : best));
  return { original: ref, targetNodeId: chosen.id, confidence, resolvedBy: 'instance-method' };
}

/** Whether a trait whose impl a Rust call may reach is callable from the call's file: a project trait in scope there; any other. */
function isRustTraitCallable(trait: string, ref: UnresolvedRef, sample: Node, context: ResolutionContext): boolean {
  return !isRustProjectNamed(trait, RUST_TRAIT_KIND, context) || isRustTraitInScope(trait, ref, sample, context);
}

const RUST_TRAIT_OF = new WeakMap<ResolutionContext, Map<string, Node | null>>();

/** The trait whose body declares a Rust method, if one does. */
function rustTraitOf(method: Node, context: ResolutionContext): Node | null {
  let memo = RUST_TRAIT_OF.get(context);
  if (!memo) RUST_TRAIT_OF.set(context, (memo = new Map()));
  const hit = memo.get(method.id);
  if (hit !== undefined) return hit;
  const cut = method.qualifiedName.lastIndexOf('::');
  const owner = cut > 0 ? method.qualifiedName.slice(0, cut).split('::').pop()! : '';
  const trait = owner === '' ? null : (context.getNodesInFileNamed?.(method.filePath, owner) ?? context.getNodesInFile(method.filePath))
    .find((n) => n.kind === 'trait' && n.name === owner && n.startLine <= method.startLine && (n.endLine ?? 0) >= method.startLine) ?? null;
  memo.set(method.id, trait);
  return trait;
}

const RUST_TRAIT_IMPLS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether the trait named `trait` (its declaration `traitFile`, when the
 * project's) is implemented for the type `name`: by an `impl` the type's
 * files or the trait's file write (`impl Render for Widget {}`), or by a
 * blanket impl over a generic (`impl<R: AsyncRead + ?Sized> AsyncReadExt for
 * R {}`) whose bounds the value meets — each one of the traits it is known by
 * (`receiverTraits`), or implemented for the type in turn. A blanket impl
 * with bounds a type from outside the project can't be checked against
 * gives it nothing.
 */
function rustTraitImplemented(trait: string, traitFile: string | null, name: string | null, typeFiles: ReadonlySet<string>,
  receiverTraits: readonly string[], context: ResolutionContext, depth = 0): boolean {
  if (!/^[A-Za-z_]\w*$/.test(trait) || (name !== null && !/^[A-Za-z_]\w*$/.test(name))) return false;
  let memo = RUST_TRAIT_IMPLS.get(context);
  if (!memo) RUST_TRAIT_IMPLS.set(context, (memo = new Map()));
  const files = [...new Set([...(traitFile ? [traitFile] : []), ...typeFiles])];
  const key = [trait, traitFile ?? '', name ?? '', receiverTraits.join(','), depth, ...files].join('\u0000');
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  memo.set(key, false);
  const traitPart = String.raw`\bimpl\b\s*(?:<((?:[^<>{;]|<(?:[^<>{;]|<[^<>{;]*>)*>)*)>)?\s*(?:[\w:]+::)?${trait}\b(?:\s*<[^{;]*?>)?\s+for\s+(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)?(?:[\w:]+::)?`;
  const blanket = new RegExp(`${traitPart}([A-Z]\\w*)\\s*(?:where\\b([^{]*))?\\{`, 'g');
  const direct = name === null ? null : new RegExp(`${traitPart}${name}\\b`);
  const meets = (bound: string): boolean => {
    const head = rustPathHead(bound)?.name ?? '';
    if (RUST_MARKER_TRAITS.has(head) || receiverTraits.some((t) => rustPathHead(t)?.name === head)) return true;
    if (name === null || depth >= 2) return false;
    const declared = context.getNodesByName(head).find((n) => n.kind === 'trait' && n.language === 'rust');
    return rustTraitImplemented(head, declared?.filePath ?? null, name, typeFiles, receiverTraits, context, depth + 1);
  };
  let found = false;
  for (const file of files) {
    const code = rustScopesOf(file, context)?.code ?? '';
    if (!code.includes(trait)) continue;
    if (direct?.test(code)) {
      found = true;
      break;
    }
    for (const m of code.matchAll(blanket)) {
      const bounds = m[1] === undefined ? undefined : rustBoundsOf(m[2]!, [{ generics: m[1], where: m[3] ?? '' }]);
      if (bounds !== undefined && bounds.every(meets)) {
        found = true;
        break;
      }
    }
    if (found) break;
  }
  memo.set(key, found);
  return found;
}

/**
 * The method a call on a value of the type `name` — or known by
 * `receiverTraits` — reaches as one a project trait provides: declared with a
 * body in the trait, which the impl for the type (or a blanket one) doesn't
 * override, the trait in scope at the call. Undefined when no such trait
 * declares the method.
 */
function rustProvidedMethod(name: string | null, typeFiles: ReadonlySet<string>, receiverTraits: readonly string[], method: string,
  ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const declared = context.getNodesByName(method).filter((m) => m.kind === 'method' && m.language === 'rust' && m.name === method &&
    rustTraitOf(m, context) !== null && rustHasBody(m, context));
  if (declared.length === 0) return undefined;
  const reached = declared.filter((m) => {
    const trait = rustTraitOf(m, context)!;
    return rustTraitImplemented(trait.name, trait.filePath, name, typeFiles, receiverTraits, context) && isRustTraitInScope(trait.name, ref, m, context);
  });
  const traits = new Set(reached.map((m) => rustTraitOf(m, context)!.id));
  if (traits.size === 1) return { original: ref, targetNodeId: reached[0]!.id, confidence: 0.85, resolvedBy: 'instance-method' };
  return traits.size > 1 ? null : undefined;
}

const RUST_ALIAS_IMPL_METHODS = new WeakMap<ResolutionContext, Map<string, Node[]>>();

/** The inherent methods named `method` that impls of aliases of the type `name` declare: `TypedConstant::type_` for `Constant`. */
function rustAliasImplMethods(name: string, method: string, context: ResolutionContext): Node[] {
  let memo = RUST_ALIAS_IMPL_METHODS.get(context);
  if (!memo) RUST_ALIAS_IMPL_METHODS.set(context, (memo = new Map()));
  const key = `${name}\u0000${method}`;
  const hit = memo.get(key);
  if (hit) return hit;
  const aliasOf = new Map<string, boolean>();
  const isAliasOfType = (owner: string): boolean => {
    let yes = aliasOf.get(owner);
    if (yes === undefined) {
      yes = owner !== name && context.getNodesByName(owner).some((n) => n.kind === 'type_alias' && n.language === 'rust' &&
        rustPathHead(rustAliasTarget(n, context)?.text ?? '')?.name === name);
      aliasOf.set(owner, yes);
    }
    return yes;
  };
  const found = context.getNodesByName(method).filter((m) => {
    if (m.kind !== 'method' || m.language !== 'rust' || m.name !== method || rustTraitOf(m, context) !== null || isRustTraitImplMethod(m, context)) return false;
    const cut = m.qualifiedName.lastIndexOf('::');
    return cut > 0 && isAliasOfType(m.qualifiedName.slice(0, cut).split('::').pop()!);
  });
  memo.set(key, found);
  return found;
}

/** Whether a trait's method declaration has a body — a provided method — rather than ending at its `;`. */
function rustHasBody(method: Node, context: ResolutionContext): boolean {
  const scopes = rustScopesOf(method.filePath, context);
  if (!scopes) return false;
  const own = scopes.fns.find((f) => f.at >= rustNodeOffset(method, context) && rustLineAt(scopes, f.at) <= (method.endLine ?? method.startLine));
  return own !== undefined;
}

/** What `impl Deref for Name { type Target = … }` makes a value of the type `name` hand calls on to. */
function rustDerefTarget(name: string, typeFiles: Iterable<string>, context: ResolutionContext): RustWrittenType | null {
  const header = new RegExp(String.raw`\bimpl\b\s*(?:<[^{;]*?>)?\s*(?:(?:std|core)\s*::\s*ops\s*::\s*|ops\s*::\s*)?Deref\s+for\s+(?:[\w:]+::)?${escapeRegExp(name)}\b[^{;]*\{`, 'g');
  for (const file of typeFiles) {
    const code = rustScopesOf(file, context)?.code ?? '';
    if (!code.includes('Deref')) continue;
    for (const m of code.matchAll(header)) {
      const body = m.index! + m[0].length;
      const target = /\btype\s+Target\s*=\s*([^;]+);/.exec(code.slice(body, body + 600));
      if (target) return { text: target[1]!.trim(), file, at: body + target.index! };
    }
  }
  return null;
}

/** What a `type Name<…> = Target;` alias names, as its declaration writes it. */
function rustAliasTarget(alias: Node, context: ResolutionContext): RustWrittenType | null {
  const scopes = rustScopesOf(alias.filePath, context);
  if (!scopes) return null;
  const start = rustNodeOffset(alias, context);
  const m = new RegExp(String.raw`\btype\s+${escapeRegExp(alias.name)}\b\s*(?:<([^=;]*?)>)?\s*=\s*([^;]+);`).exec(scopes.code.slice(Math.max(0, start - 64), start + 2000));
  return m ? { text: m[2]!.trim(), file: alias.filePath, at: start, generics: m[1] ?? '' } : null;
}

/** The methods named `method` a Rust trait declares, or the traits it extends do. */
function rustTraitMethods(traits: Node[], method: string, context: ResolutionContext, depth = 0): Node[] {
  const found: Node[] = [];
  for (const trait of traits) {
    const own = context.getNodesByName(method).filter((m) => m.kind === 'method' && m.language === 'rust' && m.filePath === trait.filePath &&
      m.startLine >= trait.startLine && m.startLine <= (trait.endLine ?? m.startLine) && rustTraitOf(m, context)?.id === trait.id);
    if (own.length > 0) {
      found.push(own[0]!);
      continue;
    }
    if (depth >= 4) continue;
    // `trait Name<…>: Super + Other where … {`
    const scopes = rustScopesOf(trait.filePath, context);
    const start = rustNodeOffset(trait, context);
    const header = scopes ? new RegExp(String.raw`\btrait\s+${escapeRegExp(trait.name)}\b\s*(?:<(?:[^<>]|<(?:[^<>]|<[^<>]*>)*>)*>)?\s*:([^{;]*?)(?:\bwhere\b[^{]*)?\{`).exec(scopes.code.slice(start, start + 2000)) : null;
    if (!header) continue;
    for (const bound of splitRustTopLevel(header[1]!, '+')) {
      const head = rustPathHead(bound);
      if (!head || bound.startsWith('\'')) continue;
      const supers = rustTypeLookup(head.name, head.segments, trait.filePath, context, rustNodeOffset(trait, context)).nodes.filter((n) => n.kind === 'trait');
      found.push(...rustTraitMethods(supers, method, context, depth + 1));
    }
  }
  return found;
}

/**
 * A call on a value known by its traits — a trait object, an `impl Trait`, a
 * bounded generic — is to the method one of the project's traits among them
 * (or a trait they extend) declares, or one a blanket impl provides in scope.
 * Known only by traits from outside the project (`Box<dyn completest::Runtime>`),
 * it is any implementation's, the project's among them: 'unread'.
 */
function rustTraitsMethodCall(traits: string[], written: RustWrittenType, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | 'unread' {
  const found: Node[] = [];
  let projectTraits = 0;
  for (const bound of traits) {
    const head = rustPathHead(bound);
    if (!head) continue;
    const nodes = rustTypeLookup(head.name, head.segments, written.file, context, written.at).nodes.filter((n) => n.kind === 'trait');
    if (nodes.length > 0) projectTraits++;
    found.push(...rustTraitMethods(nodes, method, context));
  }
  if (projectTraits === 0) return 'unread';
  const owners = new Set(found.map((m) => rustTraitOf(m, context)?.id));
  if (owners.size === 1) return { original: ref, targetNodeId: found[0]!.id, confidence: 0.9, resolvedBy: 'instance-method' };
  if (owners.size > 1) return null;
  return rustProvidedMethod(null, new Set(), traits, method, ref, context) ?? null;
}

/** Whether a method's body calls the function of its own name on its type: `Self::accept(self)`, `TcpListener::accept(self)`. */
function rustDelegatesToOwn(method: Node, typeName: string, context: ResolutionContext): boolean {
  const scopes = rustScopesOf(method.filePath, context);
  if (!scopes) return false;
  const start = scopes.lineStarts[method.startLine - 1] ?? 0;
  const end = scopes.lineStarts[method.endLine ?? method.startLine] ?? scopes.code.length;
  return new RegExp(String.raw`\b(?:Self|${escapeRegExp(typeName)})\s*::\s*${escapeRegExp(method.name)}\s*\(`).test(scopes.code.slice(start, end));
}

/**
 * A call on a value of a type from outside the project — std's, a
 * dependency's — reaches a project method only through a project trait in
 * scope: one implemented for that type (`impl Ext for String`), or one a
 * blanket impl gives every type.
 */
function rustOutsideTypeCall(name: string, args: string, byRef: boolean, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  // Among impls for the type's instantiations, the one for its arguments:
  // axum's `Result<(), E>` is `impl IntoResponse for Result<T, E>`'s, not
  // `Result<T>`'s. One that hands the call on to the type's own function of
  // its name (`fn local_addr(&self) { Self::local_addr(self) }` in axum's
  // `impl Listener for TcpListener`) shows the type has that method itself,
  // which a call reaches first.
  // An impl for a project type of the name is that type's, not the outside
  // one's: tokio's `impl Kill for Child` in process/windows.rs is for its own
  // `struct Child`, never `std::process::Child`. Its type is read as the impl
  // writes it: hexpm's `impl LowestVersion for pubgrub::Range<Version>` is
  // pubgrub's `Range`'s.
  const forOutside = (m: Node): boolean => {
    const written = rustTraitImplHeader(m, context)?.selfText.replace(/^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?)+/, '') ?? '';
    const head = rustPathHead(written);
    const lookup = rustTypeLookup(head?.name ?? name, head?.segments ?? [], m.filePath, context, rustNodeOffset(m, context));
    return lookup.outside || !lookup.nodes.some((n) => RUST_OWNER_KINDS.has(n.kind));
  };
  const impls = rustSpecialized(rustMethodsNamed(name, method, context).filter((m) => {
    const impl = rustTraitImplHeader(m, context);
    return impl !== null && impl.self === name && isRustProjectNamed(impl.trait, RUST_TRAIT_KIND, context) &&
      isRustTraitInScope(impl.trait, ref, m, context) && !rustDelegatesToOwn(m, name, context) && forOutside(m);
  }), args, context);
  if (impls.length === 1) return { original: ref, targetNodeId: impls[0]!.id, confidence: 0.85, resolvedBy: 'instance-method' };
  if (impls.length > 1) {
    // A reference's own impl for one, a value's for the value: gleam's
    // `impl Documentable for &EcoString` beside the one for `EcoString`.
    const matching = impls.filter((m) => (rustImplSelfArgs(m, context)?.byRef ?? false) === byRef);
    const pool = matching.length > 0 ? matching : impls;
    if (pool.length === 1) return { original: ref, targetNodeId: pool[0]!.id, confidence: 0.85, resolvedBy: 'instance-method' };
    // Two traits' methods: Rust asks which. One trait's, in impls `#[cfg]` twins: the nearest.
    const traits = new Set(pool.map((m) => {
      const impl = rustTraitImplHeader(m, context);
      return `${impl?.trait}<${impl?.traitArgs.join(',')}>`;
    }));
    return traits.size === 1 ? rustPickMethod(pool, new Set(), ref, 0.85) : null;
  }
  // An impl for a primitive names no type the index can address its methods
  // by — gleam's `impl Documentable for usize` — so the call is the trait's
  // method, where the trait is in scope.
  if (RUST_PRIMITIVE_TYPES.has(name)) {
    const declared = context.getNodesByName(method).filter((m) => m.kind === 'method' && m.language === 'rust' && m.name === method && rustTraitOf(m, context) !== null)
      .filter((m) => {
        const trait = rustTraitOf(m, context)!;
        return rustTraitImplemented(trait.name, trait.filePath, name, new Set(), [], context) && isRustTraitInScope(trait.name, ref, m, context);
      });
    const traits = new Set(declared.map((m) => rustTraitOf(m, context)!.id));
    if (traits.size === 1) return { original: ref, targetNodeId: declared[0]!.id, confidence: 0.8, resolvedBy: 'instance-method' };
    if (traits.size > 1) return null;
  }
  return rustProvidedMethod(/^[A-Za-z_]\w*$/.test(name) ? name : null, new Set(), [], method, ref, context) ?? null;
}

/**
 * The method a Rust call reaches on a value of a type as read: its type's
 * own (inherent) method first, then one of a trait impl for the type — the
 * trait in scope at the call when several have one — then one a trait it
 * implements provides, then what its `Deref` hands the call on to. A
 * method `Box`, `Rc` or `Arc` has itself (`clone`) is theirs. Null when the
 * type has no such method the project declares; 'unread' when what the type
 * is can't be told.
 */
function rustTypedMethodCall(read: RustTypeRead, method: string, ref: UnresolvedRef, context: ResolutionContext, depth = 0): ResolvedRef | null | 'unread' {
  if (read.kind === 'unread') return 'unread';
  if (read.wrappers.some((w) => RUST_WRAPPER_OWN_METHODS.get(w)?.has(method))) return null;
  // A wrapper the project declares itself — tokio's `MutexGuard` — has its
  // own methods, which a call reaches before what it holds.
  for (const wrapper of read.wrappers) {
    const own = rustMethodsNamed(wrapper, method, context).filter((m) => !isRustTraitImplMethod(m, context) && rustTraitOf(m, context) === null);
    if (own.length === 0) continue;
    const declared = rustTypeLookup(wrapper, [], read.written.file, context, read.written.at);
    if (!declared.outside && declared.nodes.length > 0) return rustPickMethod(own, new Set(declared.nodes.map((n) => n.filePath)), ref, 0.9);
  }
  // A project impl on the std wrapper itself — tokio's `impl<P> AsyncWrite
  // for Pin<P>`, `impl Schedule for Arc<Handle>` — answers before what the
  // wrapper holds, as Rust tries the wrapper before dereferencing it
  // (rustThroughWrapper). Only the held type's methods taking `self` through
  // that wrapper (`fn poll_flush(self: Pin<&mut Self>, …)`) come first.
  const outer = read.wrappers[0];
  if (outer !== undefined && RUST_SELF_WRAPPERS.has(outer) && !isRustProjectNamed(outer, RUST_DECLARED_TYPE_KINDS, context)) {
    const held = read.kind === 'named' ? read.name : null;
    const onWrapper = context.getNodesByName(method).filter((n) => n.language === 'rust' && n.kind === 'method' &&
      (n.qualifiedName === `${outer}::${method}` || n.qualifiedName.endsWith(`::${outer}::${method}`)) &&
      rustSelfWrapper(n) === null && rustImplFor(n, held, context));
    if (onWrapper.length > 0) {
      const inner = rustTypedMethodCall({ ...read, wrappers: read.wrappers.slice(1) }, method, ref, context, depth);
      const target = inner && inner !== 'unread' ? context.getNodeById?.(inner.targetNodeId) : undefined;
      if (inner && inner !== 'unread' && target && rustSelfWrapper(target) === outer) return inner;
      return { original: ref, targetNodeId: preferCallSiteFile(onWrapper, ref.filePath)[0]!.id, confidence: 0.9, resolvedBy: 'instance-method' };
    }
  }
  if (read.kind === 'outside') return rustOutsideTypeCall(read.name, '', read.byRef, method, ref, context);
  if (read.kind === 'traits') return rustTraitsMethodCall(read.traits, read.written, method, ref, context);
  const lookup = rustTypeLookup(read.name, read.path, read.written.file, context, read.written.at);
  if (lookup.outside) return rustOutsideTypeCall(lookup.name, read.args, read.byRef, method, ref, context);
  // No project type has the name — a dependency's, or one a macro declares:
  // only methods the index holds for that name make it the project's.
  if (lookup.undeclared && rustMethodsNamed(lookup.name, method, context).length === 0) return rustOutsideTypeCall(lookup.name, read.args, read.byRef, method, ref, context);
  if (lookup.nodes.length > 0 && lookup.nodes.every((n) => n.kind === 'trait')) {
    return rustTraitsMethodCall([read.name], read.written, method, ref, context);
  }
  const alias = lookup.nodes.length === 1 && lookup.nodes[0]!.kind === 'type_alias' ? lookup.nodes[0]! : null;
  if (alias) {
    // `impl TypedStatement { … }` on gleam's `type TypedStatement =
    // Statement<…>` keeps its methods under the alias's name; the type it
    // names has the rest.
    const own = rustMethodsNamed(alias.name, method, context);
    const inherent = own.filter((m) => !isRustTraitImplMethod(m, context) && rustTraitOf(m, context) === null);
    if (inherent.length > 0) return rustPickMethod(inherent, new Set([alias.filePath]), ref, 0.9);
    const target = depth < 4 ? rustAliasTarget(alias, context) : null;
    return target ? rustTypedMethodCall(rustReadType({ ...target, wrappers: read.wrappers }, ref, context), method, ref, context, depth + 1) : 'unread';
  }
  let types = lookup.nodes.filter((n) => RUST_OWNER_KINDS.has(n.kind));
  // Several types the name may mean: the one with the method — tokio's
  // `sync::Semaphore` has `try_acquire_owned`, its `batch_semaphore` namesake
  // doesn't. Otherwise, as the name strategies take it.
  if (types.length > 1 && new Set(types.map((t) => t.filePath)).size > 1) {
    const having = types.filter((t) => rustOwnedMethods(lookup.name, method, { ...lookup, nodes: [t] }, context).length > 0);
    if (having.length !== 1) return 'unread';
    types = having;
  }
  const typeFiles = new Set(types.map((t) => t.filePath));
  const matches = rustOwnedMethods(lookup.name, method, { ...lookup, nodes: lookup.nodes.length > 0 ? types : [] }, context);
  const inherent = matches.filter((m) => !isRustTraitImplMethod(m, context));
  if (inherent.length > 0) return rustPickMethod(rustSpecialized(inherent, read.args, context), typeFiles, ref, 0.9);
  const viaTraits = new Map<string, Node[]>();
  for (const m of matches) {
    const trait = rustTraitImplHeader(m, context)?.trait ?? '';
    viaTraits.set(trait, [...(viaTraits.get(trait) ?? []), m]);
  }
  if (viaTraits.size > 0) {
    let traits = [...viaTraits.keys()];
    if (traits.length > 1) traits = traits.filter((t) => isRustTraitCallable(t, ref, viaTraits.get(t)![0]!, context));
    // Two traits in scope with the method: Rust asks which.
    if (traits.length !== 1) return null;
    let methods = rustSpecialized(viaTraits.get(traits[0]!)!, read.args, context);
    // `impl Encoder<Bytes> for C` and `impl Encoder<&[u8]> for C`: the call's
    // argument decides, where its type is one impl's trait argument —
    // tokio's `codec.encode(Bytes::from(…), &mut buf)`, axum's
    // `router.call(request)` on a `request: Request<String>`.
    const traitArgs = (m: Node): string => rustTraitImplHeader(m, context)?.traitArgs.join(',') ?? '';
    if (new Set(methods.map(traitArgs)).size > 1) {
      const fit = methods.filter((m) => {
        const args = rustTraitImplHeader(m, context)?.traitArgs ?? [];
        const head = args.find((a) => /^[A-Z]/.test(a)) ?? args[0];
        return head !== undefined && rustFirstArgIs(head, ref, context);
      });
      if (fit.length === 0 || new Set(fit.map(traitArgs)).size > 1) return null;
      methods = fit;
    }
    return rustPickMethod(methods, typeFiles, ref, 0.9);
  }
  // An impl of an alias of the type, for the instantiation it names: gleam's
  // `impl TypedConstant { fn type_() }` on `type TypedConstant = Constant<…>`,
  // called on a `Constant<Type>` a variant of a generic enum holds.
  const viaAlias = rustAliasImplMethods(lookup.name, method, context);
  if (viaAlias.length > 0) {
    const owners = new Set(viaAlias.map((m) => m.qualifiedName.slice(0, m.qualifiedName.lastIndexOf('::'))));
    return owners.size === 1 ? rustPickMethod(viaAlias, typeFiles, ref, 0.85) : null;
  }
  const provided = rustProvidedMethod(lookup.name, typeFiles, [], method, ref, context);
  if (provided !== undefined) return provided;
  if (depth < 3) {
    const target = rustDerefTarget(lookup.name, typeFiles, context);
    if (target) return rustTypedMethodCall(rustReadType(target, ref, context), method, ref, context, depth + 1);
  }
  return null;
}

/**
 * A Rust method call on a local or a parameter — `opts.build()` — as the
 * type its binding in scope declares makes it (rustTypedMethodCall): the
 * parameter's type, the `let`'s annotation or the value it is built from,
 * the field a match arm's variant holds there. Undefined when no binding of
 * the name is in scope where the call is (a `static`, a name a macro binds);
 * `{ unread }`, with the binding's line, when the binding doesn't say what
 * its type is.
 */
function matchRustTypedReceiverCall(receiver: string, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | { unread: number } | undefined {
  const result = rustTypedReceiverCall(receiver, method, ref, context);
  if (result && 'targetNodeId' in result) {
    let typed = RUST_TYPED_REFS.get(context);
    if (!typed) RUST_TYPED_REFS.set(context, (typed = new WeakSet()));
    typed.add(ref);
  }
  return result;
}

/** The refs matchRustTypedReceiverCall resolved: through a typed receiver, a trait's own method is in reach. */
const RUST_TYPED_REFS = new WeakMap<ResolutionContext, WeakSet<UnresolvedRef>>();

/**
 * A Rust call on a field of the enclosing impl's type — `self.inner.run()`,
 * `self.0.len()` — as a call on the type the struct declares for the field:
 * through `Arc`, `Box`, `Pin` and the lock guards, by a bounded generic's
 * traits or a trait object's, with the struct's `use`s naming the type
 * (rustFieldValue, rustTypedMethodCall). Undefined where the field's type
 * can't be told: an enum's `self`, a trait's default method, a struct the
 * index doesn't hold.
 */
function matchRustTypedSelfFieldCall(field: string, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  if (!/^(?:[A-Za-z_]\w*|\d+)$/.test(field)) return undefined;
  const scopes = rustScopesOf(ref.filePath, context);
  if (!scopes) return undefined;
  const at = (scopes.lineStarts[ref.line - 1] ?? 0) + Math.max(0, ref.column);
  const written = rustFieldValue('self', field, at, scopes, ref, context, 0);
  if (!written) return undefined;
  const result = rustTypedMethodCall(rustReadType(written, ref, context), method, ref, context);
  if (result === 'unread') return undefined;
  if (result) {
    let typed = RUST_TYPED_REFS.get(context);
    if (!typed) RUST_TYPED_REFS.set(context, (typed = new WeakSet()));
    typed.add(ref);
  }
  return result;
}

function rustTypedReceiverCall(receiver: string, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | { unread: number } | undefined {
  const scopes = rustScopesOf(ref.filePath, context);
  if (!scopes) return undefined;
  const offset = (scopes.lineStarts[ref.line - 1] ?? 0) + Math.max(0, ref.column);
  const found = rustBindingAt(scopes, receiver, offset);
  if (!found) return undefined;
  const unread = { unread: rustLineAt(scopes, found.binding.at) };
  if (found.ambiguous) return unread;
  const written = rustBindingType(found.binding, scopes, ref, context, 0);
  if (!written) return unread;
  const result = rustTypedMethodCall(rustReadType(written, ref, context), method, ref, context);
  return result === 'unread' ? unread : result;
}

/** What only exists inside a type, reachable through a receiver alone. */
const TYPE_MEMBER_KINDS: ReadonlySet<string> = new Set(['method', 'property', 'field', 'enum_member']);

/** Per-context memo: `file\0name` → "the file binds this name locally". */
/** Whether `n` lies outside the function that binds the reference's name itself (see jsFunctionLocalScope). */
function isOutsideJsLocal(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  // `const indexName = this.dataSource.namingStrategy.indexName(…)`: a member, whatever the local's name.
  if (ref.referenceKind === 'calls' && bareCallReceiver(ref, context) !== null) return false;
  const scope = jsFunctionLocalScope(ref.referenceName, ref, context);
  return scope !== null && !(n.filePath === ref.filePath && n.startLine >= scope.start && n.startLine <= scope.end);
}

const JS_FN_LOCAL_MEMO = new WeakMap<ResolutionContext, Map<string, { start: number; end: number } | null>>();

/**
 * The lines of the JS/TS function a reference sits in when that function binds
 * the name itself — a parameter, or a `var`/`let`/`const` above the reference.
 * Such a name is the local, never a same-named function declared elsewhere:
 * every lodash helper lives inside `runInContext`, so `baseHas(object, key)`'s
 * `object` and `mixin`'s `object(this.__wrapped__)` reached a `function
 * object() {}` an IIFE declares there. Null when the function does not bind it.
 */
function jsFunctionLocalScope(name: string, ref: UnresolvedRef, context: ResolutionContext): { start: number; end: number } | null {
  if (!JS_FAMILY.has(ref.language) || !/^[A-Za-z_$][\w$]*$/.test(name)) return null;
  let memo = JS_FN_LOCAL_MEMO.get(context);
  if (!memo) JS_FN_LOCAL_MEMO.set(context, (memo = new Map()));
  const key = `${ref.fromNodeId}\0${name}\0${ref.line}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  let scope: { start: number; end: number } | null = null;
  const fn = context.getNodeById?.(ref.fromNodeId);
  if (fn && (fn.kind === 'function' || fn.kind === 'method') && fn.startLine <= ref.line && fn.endLine >= ref.line &&
      jsCodeBindsName(name, fn, ref.filePath, ref.line, context)) {
    scope = { start: fn.startLine, end: fn.endLine };
  }
  memo.set(key, scope);
  return scope;
}

/**
 * Per context, by `file\0first line\0reference line\0name`: whether the code
 * from a function's first line through a reference's binds the name. Every
 * function that starts on the same line has that code — all of a minified
 * script's do — so they share the answer (#2334).
 */
const JS_CODE_BINDS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether the function's code in `filePath`, from its first line through
 * `line` (a reference's, or a JSX tag's), declares `name`, or names it in a
 * parameter list.
 */
export function jsCodeBindsName(name: string, fn: Node, filePath: string, line: number, context: ResolutionContext): boolean {
  let memo = JS_CODE_BINDS.get(context);
  if (!memo) JS_CODE_BINDS.set(context, (memo = new Map()));
  const key = `${filePath}\0${fn.startLine}\0${line}\0${name}`;
  let binds = memo.get(key);
  if (binds === undefined) {
    const text = jsFunctionCodeThrough(fn, filePath, line, context);
    const n = escapeRegExp(name);
    // A plain declaration. Destructuring re-binds what a call returns under
    // the same name — `const { t } = useI18n()`, `const { getLabel } =
    // useProps(props)` — which is the same-named function more often than not.
    const declared = new RegExp(`\\b(?:const|let|var)\\s+${n}(?![\\w$])(?!\\s*[,\\]}])`).test(text);
    binds = declared || jsParameterListPattern(name, '').test(text);
    memo.set(key, binds);
  }
  return binds;
}

/**
 * A parameter list that names `name` (localBindingPatterns' `param`), never
 * a control-flow head (`if (openMarkerClose) {`). A return type stays on its
 * line, never a ternary's `: data.slice()` below `filter(canRowExpand)`, and
 * may hold an object type, so the match ends at the body's `{`, not at the
 * type's: `delta(…): { removed: T[]; added: T[] } {`.
 * The leading `(?=\()` (every match opens a list) keeps the lookbehind to
 * where one opens. Node 22's V8 stops optimizing the regexes a process
 * compiles once it has generated about a megabyte of regex code, which a
 * resolver pool worker soon has, and then tried the lookbehind at every
 * position, each time reading back through the run of blanks before it:
 * go-ethereum's graphiql.min.js, a 980 KB line whose last 962 KB the
 * stripper blanks (it reads the `//` closing `/Trident\//` as a comment),
 * never resolved.
 */
function jsParameterListPattern(name: string, flags: string): RegExp {
  const { param } = localBindingPatterns(name, flags);
  const returnType = `(?::(?:[^=;{}()\\n]|${PARAM_BRACE})*)?`;
  return new RegExp(`(?=\\()(?<!\\b(?:if|while|for|switch|with)\\s*)${param.source.replace('(?::[^=;{]*)?', () => returnType)}`, flags);
}

/**
 * Whether the JS/TS function a reference sits in binds its name in a scope
 * that holds at the reference, not just somewhere in its text: a parameter
 * list or a lone arrow parameter whose body is still open there (a
 * function's or a `catch` clause's block, an arrow's block or expression),
 * or a `var`/`let`/`const`, `function` or `class` whose block or `for`
 * statement is. A `new Promise((resolve) => …)` executor's `resolve` is the
 * calls inside it, not a `resolve(file)` after it, and a `const X =
 * require('./x')` binds the import itself. A function too long to read
 * again keeps the import.
 */
function jsBindingEnclosesReference(name: string, fn: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const through = jsFunctionCodeThrough(fn, ref.filePath, ref.line, context);
  const cut = through.slice(0, through.lastIndexOf('\n') + 1 + ref.column);
  if (cut.length > 100_000) return false;
  // Brackets in strings, template literals and regex literals open no scope.
  const regexes: number[] = [];
  const chars = blankStringContents(cut, regexes).split('');
  for (let r = 0; r + 1 < regexes.length; r += 2) chars.fill(' ', regexes[r]! + 1, regexes[r + 1]!);
  const code = chars.join('');
  const n = escapeRegExp(name);
  const declaration = new RegExp(
    `\\b(?:(?:const|let|var)\\s+${n}(?![\\w$])(?!\\s*[,\\]}])(\\s*=\\s*(?:await\\s+)?(?:require|import)\\s*\\()?|(?:function|class)\\s+${n}(?![\\w$]))`,
    'g'
  );
  for (const m of code.matchAll(declaration)) {
    if (m[1]) continue;
    const inForHead = /\bfor\s*(?:await\s*)?\(\s*$/.test(code.slice(Math.max(0, m.index! - 16), m.index));
    if (inForHead ? jsForStatementOpenAtEnd(code, m.index!) : jsBlockOpenAtEnd(code, m.index!)) return true;
  }
  for (const m of code.matchAll(jsParameterListPattern(name, 'g'))) {
    const end = m.index! + m[0].length;
    if (code[end - 1] === '{' ? jsBlockOpenAtEnd(code, end) : jsBodyOpenAtEnd(code, end)) return true;
  }
  // `new Promise<void>(resolve => { … })`: a lone parameter where an
  // expression starts, never the name a return type ends with (`(): Bounds =>`).
  const loneParameter = new RegExp(`(^|[(,=\\[{?:]|=>|\\b(?:return|async|default|yield|await))\\s*${n}\\s*=>`, 'g');
  for (const m of code.matchAll(loneParameter)) {
    if (m[1] === ':' && /\)\s*$/.test(code.slice(Math.max(0, m.index! - 200), m.index))) continue;
    if (jsBodyOpenAtEnd(code, m.index! + m[0].length)) return true;
  }
  return false;
}

/**
 * Whether the block that holds `at` (just inside a body's `{`, or where a
 * declaration starts) is still open at the end of `code`.
 */
function jsBlockOpenAtEnd(code: string, at: number): boolean {
  return jsBlockEnd(code, at) === code.length;
}

/** Where the block that holds `at` closes: its `}`, or the end of `code`. */
function jsBlockEnd(code: string, at: number): number {
  let depth = 0;
  for (let i = at; i < code.length; i++) {
    if (code[i] === '{') depth++;
    else if (code[i] === '}' && --depth < 0) return i;
  }
  return code.length;
}

const JS_OPERAND_END = /[\w$)\]}'"`]/;
const JS_OPERAND_START = /[\w$'"`]/;

/**
 * Whether the body that starts at `at` (an arrow's, after its `=>`, or a
 * `for` statement's, after its head) is still open at the end of `code`: a
 * `{…}` block, or an expression or statement, which a comma or a semicolon
 * ends, or the bracket closing around it, or a line that starts another
 * statement where no semicolon ends the last.
 */
function jsBodyOpenAtEnd(code: string, at: number): boolean {
  return jsBodyEnd(code, at) === code.length;
}

/** Where the body that starts at `at` (see jsBodyOpenAtEnd) ends, or the end of `code`. */
function jsBodyEnd(code: string, at: number): number {
  let i = at;
  while (i < code.length && WHITESPACE.test(code[i]!)) i++;
  if (code[i] === '{') return jsBlockEnd(code, i + 1);
  let depth = 0;
  for (; i < code.length; i++) {
    const c = code[i]!;
    if (c === '(' || c === '[' || c === '{') {
      depth++;
    } else if (c === ')' || c === ']' || c === '}') {
      if (--depth < 0) return i;
    } else if (depth === 0 && (c === ',' || c === ';')) {
      return i;
    } else if (depth === 0 && c === '\n') {
      // `const f = (x) => x + 1` with no semicolon, above the reference: the
      // line before ends an operand (a name, a closing bracket, a quote) and
      // the next starts one (the reference itself, when the code ends there)
      // rather than an operator or a `.` continuing the expression.
      let before = i - 1;
      while (before >= 0 && WHITESPACE.test(code[before]!)) before--;
      let after = i + 1;
      while (after < code.length && WHITESPACE.test(code[after]!)) after++;
      if (JS_OPERAND_END.test(code[before] ?? '') && (after === code.length || JS_OPERAND_START.test(code[after]!))) return i;
      i = after - 1;
    }
  }
  return code.length;
}

/**
 * Whether a declaration in a `for` head, at `at`, is still in scope at the
 * end of `code`: in the head, or in the statement after it.
 */
function jsForStatementOpenAtEnd(code: string, at: number): boolean {
  let depth = 0;
  for (let i = at; i < code.length; i++) {
    const c = code[i];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if ((c === ')' || c === ']' || c === '}') && --depth < 0) return c === ')' && jsBodyOpenAtEnd(code, i + 1);
  }
  return true;
}

/**
 * Whether an import-resolved `result` is the file's import of the reference's
 * name while the calling JS/TS function binds that name itself, in a scope
 * that holds at the reference (jsBindingEnclosesReference): bitwarden's
 * `pick(…, isAvailable: (f: string) => boolean)` calling `isAvailable(f)`
 * means its parameter, not the file's `import { isAvailable } from './sdk'`.
 * The import resolver answers before matchReference's check, which reads the
 * function's whole text — too coarse for an import, whose link is usually right.
 */
export function isImportShadowedByJsBinding(result: ResolvedRef, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!JS_FAMILY.has(ref.language) || !JS_LOCAL_REF_KINDS.has(ref.referenceKind) || !/^[A-Za-z_$][\w$]*$/.test(ref.referenceName)) return false;
  const target = context.getNodeById?.(result.targetNodeId);
  // (A parameter or local is a value: it hides no interface or type alias, `let coords: Bounds`.)
  if (!target || target.name !== ref.referenceName || target.kind === 'interface' || target.kind === 'type_alias') return false;
  const fn = context.getNodeById?.(ref.fromNodeId);
  if (!fn || (fn.kind !== 'function' && fn.kind !== 'method') || fn.startLine > ref.line || fn.endLine < ref.line) return false;
  if (target.filePath === ref.filePath && target.startLine >= fn.startLine && target.startLine <= fn.endLine) return false;
  // No function binds a name its file never does (read once per file and name).
  if (!isLocallyBoundJsName(ref.referenceName, ref.filePath, context)) return false;
  if (ref.referenceKind === 'calls' && bareCallReceiver(ref, context) !== null) return false;
  return jsBindingEnclosesReference(ref.referenceName, fn, ref, context);
}

/**
 * Per context: the comment-stripped lines of the functions jsCodeBindsName
 * read last, and where each line ends in that text, most recent last.
 */
const JS_FN_CODE = new WeakMap<ResolutionContext, Map<string, { code: string; lineEnds: number[] }>>();
const JS_FN_CODE_KEEP = 64;

/**
 * The function's lines from its first through `line`, comments blanked.
 * Stripping looks at most one character ahead — past a line's end, a
 * newline, which completes no comment marker — so this is the whole
 * function's stripped text cut at that line's end. Stripping the lines again
 * for every reference took time in the square of a large function's length;
 * in a minified script, every function's text runs to the end of its one
 * line (#2334).
 */
function jsFunctionCodeThrough(fn: Node, filePath: string, line: number, context: ResolutionContext): string {
  let fns = JS_FN_CODE.get(context);
  if (!fns) JS_FN_CODE.set(context, (fns = new Map()));
  const key = `${filePath}\0${fn.startLine}\0${fn.endLine}`;
  let own = fns.get(key);
  if (own) {
    fns.delete(key);
  } else {
    const lines = (context.getFileLines?.(filePath) ?? context.readFile(filePath)?.split(/\r?\n/) ?? [])
      .slice(fn.startLine - 1, fn.endLine);
    let end = -1;
    own = { code: stripCommentsForRegex(lines.join('\n'), 'javascript'), lineEnds: lines.map((text) => (end += text.length + 1)) };
    if (fns.size >= JS_FN_CODE_KEEP) fns.delete(fns.keys().next().value!);
  }
  fns.set(key, own);
  // Through `line`, or the file's last when it ends sooner.
  const last = Math.min(line, fn.startLine - 1 + own.lineEnds.length) - fn.startLine;
  return last < 0 ? '' : own.code.slice(0, own.lineEnds[last]);
}

const LOCAL_BINDING_MEMO = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Where a file's local bindings can start, for isLocallyBoundJsName: every
 * `const`/`let`/`var` and `function`/`class` keyword and every `=>`. Each
 * binding pattern can only match from one of these (or, for a parameter,
 * from the `(` before an occurrence of the name), so a lookup tries its
 * patterns at those offsets instead of searching the file once per pattern
 * per name. Kept for the last few files — calls arrive file by file.
 */
interface LocalBindingSites {
  varDecls: number[];
  fnDecls: number[];
  arrows: number[];
}
const LOCAL_BINDING_SITES = new WeakMap<ResolutionContext, Map<string, LocalBindingSites>>();
const LOCAL_BINDING_SITES_KEEP = 16;
const VAR_DECL_SITE = /\b(?:const|let|var)\s/g;
const FN_DECL_SITE = /\b(?:function|class)\s/g;

function localBindingSites(filePath: string, source: string, context: ResolutionContext): LocalBindingSites {
  let cache = LOCAL_BINDING_SITES.get(context);
  if (!cache) {
    cache = new Map();
    LOCAL_BINDING_SITES.set(context, cache);
  }
  let sites = cache.get(filePath);
  if (!sites) {
    const offsets = (re: RegExp): number[] => Array.from(source.matchAll(re), (m) => m.index!);
    const arrows: number[] = [];
    for (let a = source.indexOf('=>'); a !== -1; a = source.indexOf('=>', a + 2)) arrows.push(a);
    sites = { varDecls: offsets(VAR_DECL_SITE), fnDecls: offsets(FN_DECL_SITE), arrows };
    if (cache.size >= LOCAL_BINDING_SITES_KEEP) cache.delete(cache.keys().next().value!);
    cache.set(filePath, sites);
  }
  return sites;
}

type LocalBindingPatterns = { decl: RegExp; fn: RegExp; param: RegExp };
/** Sticky binding patterns by name — the same names recur file after file. */
const LOCAL_BINDING_PATTERNS = new Map<string, LocalBindingPatterns>();
const LOCAL_BINDING_PATTERNS_CAP = 4096;
const JS_BINDING_NAME = /^[\w$]+$/;
const ARROW_HEAD_CHAR = /[\w$.]/;
const IMPORT_BINDING_VALUE = /^\s*(?:await\s+)?(?:require|import)\s*\(/;

// The balanced groups a parameter's type or default can hold, two levels deep.
const PARAM_PAREN = '\\((?:[^()]|\\([^()]*\\))*\\)';
const PARAM_BRACE = '\\{(?:[^{}]|\\{[^{}]*\\})*\\}';
const PARAM_BRACKET = '\\[(?:[^\\[\\]]|\\[[^\\[\\]]*\\])*\\]';
const PARAM_ANGLE = '<(?!\\s)(?:=>|=(?!>)|[^<>=]|<(?:=>|=(?!>)|[^<>=])*>)*>';
/**
 * One piece of a parameter's type or default: a character other than a comma,
 * or a balanced group, which may hold commas (`Map<K, V>`, `{ a: A, b: B }`,
 * `(a: number, b: number) => number`). Every alternative starts with a
 * character of its own — `=>` is the arrow of a function type, and a `<` or
 * `>` spaced like an operator (`f.length > 0`) is no bracket — so a type has
 * one parse.
 */
const PARAM_PART = `(?:=>|=(?!>)|[^,(){}\\[\\]<>=]|<(?=\\s)|>(?=[\\s=])|${PARAM_PAREN}|${PARAM_BRACE}|${PARAM_BRACKET}|${PARAM_ANGLE})`;
/** A TypeScript parameter property's modifiers: `constructor(private readonly store: Store)`. */
const PARAM_MODIFIERS = '(?:(?:public|private|protected|readonly|override)\\s+)*';

function localBindingPatterns(name: string, flags: string): LocalBindingPatterns {
  const n = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return {
    // `const { name } = require('./m')` / `= await import('./m')` binds an IMPORT,
    // not a shadow: the symbol lives in the other file and the call means it.
    decl: new RegExp(
      '\\b(?:const|let|var)\\s+(?:' + n + '(?![\\w$])|[{\\[][^;=]*?\\b' + n + '(?![\\w$])[^;=]*?[}\\]])\\s*(?:=\\s*([^;\\n]*))?',
      flags
    ),
    fn: new RegExp('\\b(?:function|class)\\s+' + n + '(?![\\w$])', flags),
    // a parameter: every token before the name in the list is itself a
    // parameter (identifier or destructuring, optional type, optional
    // default) — so a string argument containing the word cannot match.
    // Each earlier parameter has exactly one parse: its first non-space
    // character after the identifier picks the type (`?`/`:`), default (`=`)
    // or bare alternative, and a type or default runs to the comma. Written
    // as `(type)?(default)?\s*`, the same strings split several ways per
    // parameter, and a failing search backtracked through every combination
    // — 30-40s per name on a vscode test file whose helper takes nine `name:
    // T = value` parameters. A type or default may hold balanced groups
    // (PARAM_PART): `isAvailable: (f: string) => boolean`, `cb: () => void`
    // before the name, `compare = (a, b) => a - b`.
    param: new RegExp(
      '\\(\\s*(?:(?:' + PARAM_MODIFIERS + '(?:\\.\\.\\.)?[\\w$]+|' + PARAM_BRACE + '|' + PARAM_BRACKET + ')' +
        '(?:\\s*(?:\\?\\s*)?:' + PARAM_PART + '+|\\s*=' + PARAM_PART + '+|\\s*),\\s*)*' +
        PARAM_MODIFIERS + n + '(?![\\w$])(?:\\s*\\??\\s*:' + PARAM_PART + '*)?(?:\\s*=' + PARAM_PART + '*)?' +
        '(?:\\s*,(?:[^()]|' + PARAM_PAREN + ')*)?\\)\\s*(?::[^=;{]*)?(?:=>|\\{)',
      flags
    ),
  };
}

/**
 * Whether a JS/TS file binds `name` itself — as a `const`/`let`/`var`/
 * `function`/`class` declaration (destructuring included) or as a parameter
 * of a function or arrow. Such a binding shadows every same-named symbol in
 * other files, so a bare call to it has no cross-file candidate: the
 * `resolve` of `new Promise((resolve, reject) => …)`, a spec's
 * `const transform = await makeTransform()`, a factory's `const now =
 * options.now || (() => new Date())`. None of these is a node the graph
 * holds (a parameter, a const bound to a call result), so without this the
 * matcher hands the call to whichever other file defines the name — and
 * once methods stop being candidates for a bare call (#1714), the function
 * that was out-ranked steps in. Read from source, memoised per file+name.
 */
function isLocallyBoundJsName(name: string, filePath: string, context: ResolutionContext): boolean {
  let memo = LOCAL_BINDING_MEMO.get(context);
  if (!memo) {
    memo = new Map();
    LOCAL_BINDING_MEMO.set(context, memo);
  }
  const key = filePath + '\0' + name;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const source = context.readFile(filePath) ?? '';
  const bound = JS_BINDING_NAME.test(name)
    ? bindsAtSites(source, name, localBindingSites(filePath, source, context))
    : bindsAnywhere(source, name);
  memo.set(key, bound);
  return bound;
}

/** isLocallyBoundJsName's patterns, searched through the whole source. */
function bindsAnywhere(source: string, name: string): boolean {
  const { decl, fn, param } = localBindingPatterns(name, 'g');
  for (const m of source.matchAll(decl)) {
    if (!IMPORT_BINDING_VALUE.test(m[1] ?? '')) return true;
  }
  const n = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return fn.test(source) || param.test(source) || new RegExp('(?:^|[^\\w$.])' + n + '\\s*=>').test(source);
}

/**
 * The `(` of the parenthesized list `source[at]` sits in, read back over the
 * balanced groups before it (an earlier parameter's `cb: () => void` or `{ a,
 * b }`), or -1 when the name sits in a block, an object or an array, after a
 * statement's end, or too far back to be in a parameter list.
 */
function enclosingOpenParen(source: string, at: number): number {
  let depth = 0;
  for (let i = at - 1; i >= 0 && at - i <= 2000; i--) {
    const c = source[i];
    if (c === ')' || c === ']' || c === '}') depth++;
    else if (c === '(' || c === '[' || c === '{') {
      if (depth === 0) return c === '(' ? i : -1;
      depth--;
    } else if (c === ';' && depth === 0) return -1;
  }
  return -1;
}

/**
 * bindsAnywhere for a plain identifier, tried only where a match can start:
 * a declaration at its keyword (in order, resuming past each match exactly as
 * the global search does), a parameter at the `(` its list opens with
 * (enclosingOpenParen, from an occurrence of the name), and `name =>` at each
 * arrow.
 */
function bindsAtSites(source: string, name: string, sites: LocalBindingSites): boolean {
  const { decl, fn, param } = stickyBindingPatterns(name);
  let from = 0;
  for (const at of sites.varDecls) {
    if (at < from) continue;
    decl.lastIndex = at;
    const m = decl.exec(source);
    if (!m) continue;
    from = at + m[0].length;
    if (!IMPORT_BINDING_VALUE.test(m[1] ?? '')) return true;
  }
  for (const at of sites.fnDecls) {
    fn.lastIndex = at;
    if (fn.test(source)) return true;
  }
  let tried = -1;
  for (let at = source.indexOf(name); at !== -1; at = source.indexOf(name, at + 1)) {
    const open = enclosingOpenParen(source, at);
    if (open < 0 || open === tried) continue;
    tried = open;
    param.lastIndex = open;
    if (param.test(source)) return true;
  }
  // `name =>`: the name ends where the whitespace before the arrow starts.
  for (const arrow of sites.arrows) {
    let end = arrow;
    while (end > 0 && WHITESPACE.test(source[end - 1]!)) end--;
    const start = end - name.length;
    if (start >= 0 && source.startsWith(name, start) && (start === 0 || !ARROW_HEAD_CHAR.test(source[start - 1]!))) {
      return true;
    }
  }
  return false;
}

/**
 * The calling file's declarations of an out-of-repo imported name that sit
 * inside a function or method — only those can shadow the import. A top-level
 * one is the import's own binding (`request = require('supertest')`), not a
 * shadow of it.
 */
function innerScopeShadows(nodes: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  const local = nodes.filter((n) => n.filePath === ref.filePath);
  if (local.length === 0) return local;
  const scopes = context.getNodesInFile(ref.filePath).filter((n) => n.kind === 'function' || n.kind === 'method');
  return local.filter((n) => scopes.some((s) =>
    s.id !== n.id &&
    s.startLine <= n.startLine &&
    (s.endLine ?? s.startLine) >= (n.endLine ?? n.startLine) &&
    (s.startLine < n.startLine || (s.endLine ?? s.startLine) > (n.endLine ?? n.startLine))));
}

/**
 * Languages where a receiver-less call inside a class body means `this.m()`,
 * and whose scoping filters in matchByExactName can still leave the caller's
 * own member and a sibling class's side by side (Scala keeps every same-file
 * member; Java keeps every type a same-named nested type extends). Kotlin,
 * C#, Swift, Dart and Ruby filter a bare call to what is in reach, and C++
 * has its own class lookup (matchCppImplicitThisCall).
 */
const IMPLICIT_THIS_LANGUAGES = new Set<string>(['java', 'scala']);
/** Languages whose extractor drops a `this.`/`self.` receiver but where a bare call never means a member. */
const EXPLICIT_THIS_LANGUAGES = new Set<string>(['python', 'typescript', 'tsx', 'javascript', 'jsx']);
const MEMBER_OWNER_KINDS = new Set<Node['kind']>(['class', 'struct', 'interface', 'trait', 'protocol', 'enum', 'union', 'module']);

/**
 * How a call names its receiver, read back from the call site's line: the
 * extractor emits `render()`, `this.render()`, `self.render()` and
 * `super.render()` all as `render`. `null` when the line can't be read or the
 * receiver is something else.
 */
function callReceiverKind(ref: UnresolvedRef, context: ResolutionContext): 'bare' | 'self' | 'super' | null {
  const line = context.getFileLines?.(ref.filePath)?.[ref.line - 1]
    ?? context.readFile(ref.filePath)?.split('\n')[ref.line - 1];
  if (line === undefined) return null;
  const nameEsc = ref.referenceName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // The ref's column is the call expression's start, except in Dart, where it
  // is the argument list right after the name: take the first occurrence at
  // or after the column, else the last one before it.
  let at = -1;
  for (const m of line.matchAll(new RegExp('(?<![\\w$])' + nameEsc + '(?![\\w$])', 'g'))) {
    at = m.index;
    if (at >= ref.column) break;
  }
  if (at < 0) return null;
  const before = line.slice(0, at);
  // Only the languages' own words: Java's extractor drops a `parent.` or
  // `cls.` receiver too, and there it is a variable (protobuf's
  // `parent.getFullName()` on the EnumDescriptor an enum value belongs to).
  if (/(?:^|[^\w$.])super(?:\s*\([^()]*\)|<[^<>]*>)?\s*\.\s*$/.test(before)) return 'super';
  if (/(?:^|[^\w$.])this\s*\??\.\s*$/.test(before)) return 'self';
  // A JS `self` the file doesn't bind is the global object, not the instance.
  if (/(?:^|[^\w$.])self\s*\??\.\s*$/.test(before)) return isBrowserHostGlobal('self', ref, context) ? null : 'self';
  if (ref.language === 'python' && /(?:^|[^\w$.])cls\s*\.\s*$/.test(before)) return 'self';
  if (/(?:\.|->|::)\s*$/.test(before)) return null;
  return 'bare';
}

/**
 * A call that means a member of the class it is written in — a receiver-less
 * `render()` in Java / Scala, or `this.render()` / `self.render()` in
 * TypeScript / JavaScript / Python — binds by
 * the language's scoping, not by which same-named method sits nearest: the
 * caller's own class first, then what it inherits, then (for a bare call) the
 * classes it is nested in. Without this the same-file line-distance term
 * handed `RegName.toString()`'s `render()` to a longer sibling class's
 * `render` declared closer to the call. Walks the caller's qualified-name
 * scopes innermost-out and returns the first candidate declared directly in
 * one (a local function of an enclosing method counts, same file only); a
 * `super.` call skips its own class. Returns null — existing ranking — when
 * nothing in scope declares the name.
 */
function matchEnclosingScopeMember(
  ref: UnresolvedRef,
  candidates: Node[],
  context: ResolutionContext
): Node | null {
  if (ref.referenceKind !== 'calls' || /[.:]/.test(ref.referenceName)) return null;
  const implicit = IMPLICIT_THIS_LANGUAGES.has(ref.language);
  if (!implicit && !EXPLICIT_THIS_LANGUAGES.has(ref.language)) return null;
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller?.qualifiedName) return null;
  const receiver = callReceiverKind(ref, context);
  if (!receiver || (receiver === 'bare' && !implicit)) return null;

  const name = ref.referenceName;
  // One pass over the candidates, keyed by the type that declares each: a
  // ubiquitous name (`get`, `init`) can bring thousands, and the walk below
  // asks about several scopes and supertypes.
  const byOwner = new Map<string, Node[]>();
  const byOwnerName = new Map<string, Node[]>();
  for (const c of candidates) {
    const sep = c.qualifiedName.lastIndexOf('::');
    if (sep <= 0 || c.qualifiedName.slice(sep + 2) !== name) continue;
    const owner = c.qualifiedName.slice(0, sep);
    const simple = owner.includes('::') ? owner.slice(owner.lastIndexOf('::') + 2) : owner;
    byOwner.set(owner, [...(byOwner.get(owner) ?? []), c]);
    byOwnerName.set(simple, [...(byOwnerName.get(simple) ?? []), c]);
  }
  // Whatever a scope declares under the name shadows the scopes outside it —
  // a Scala `val` applied like a function, a nested class constructed by a
  // bare call — but a method is the likelier target when both exist.
  const callableFirst = (found: Node[]): Node[] =>
    [...found].sort((a, b) => Number(b.kind === 'method' || b.kind === 'function') - Number(a.kind === 'method' || a.kind === 'function'));
  // `Owner::Owner` is a constructor: a bare `Owner(...)` builds a new
  // instance, it does not call an inherited or enclosing member.
  const members = (owner: string): Node[] =>
    owner === name || owner.endsWith(`::${name}`)
      ? []
      : callableFirst(byOwner.get(owner) ?? []);
  const typesNamed = (qn: string): Node[] =>
    context.getNodesByQualifiedName(qn).filter((n) => MEMBER_OWNER_KINDS.has(n.kind) && sameLanguageFamily(n.language, ref.language));
  // One member of `owner`: the caller's file first; another file only when a
  // single type in the index carries that qualified name.
  const pick = (owner: string, isType: boolean): Node | null => {
    const found = members(owner);
    if (found.length === 0) return null;
    const local = found.find((c) => c.filePath === ref.filePath);
    if (local) return local;
    return isType && typesNamed(owner).length === 1 ? found[0]! : null;
  };
  // The declaration of `scope` the call sits in, else the only one.
  const declOf = (scope: string): Node | null => {
    const decls = typesNamed(scope);
    const enclosing = decls.filter((n) => n.filePath === ref.filePath && n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line);
    if (enclosing.length > 0) return enclosing[enclosing.length - 1]!;
    return decls.length === 1 ? decls[0]! : null;
  };
  // A declaration's supertypes through its own resolved extends/implements
  // edges, in the order its header names them.
  const supertypesOf = (type: Node): Node[] => {
    const supers = context.getSupertypeNodes?.(type.id) ?? [];
    if (supers.length < 2) return supers;
    const header = headerOf(type);
    const at = (s: Node): number => {
      const i = header.search(new RegExp('(?<![\\w$])' + escapeRegExp(s.name) + '(?![\\w$])'));
      return i < 0 ? Number.MAX_SAFE_INTEGER : i;
    };
    return [...supers].sort((a, b) => at(a) - at(b));
  };
  // Inherited members through those edges, breadth-first: the members of the
  // very types the declaration extends, where a walk by name reaches every
  // type of that name (Django's per-backend `DatabaseSchemaEditor`s differ in
  // what they override).
  const inheritedThrough = (type: Node): Node | null => {
    const seen = new Set<string>([type.id]);
    let frontier = [type];
    // An interface's or an abstract declaration answers only when no class
    // further up implements the member: SystemUI's `RotationContextButton
    // extends ContextualButton implements RotationButton` runs
    // ButtonDispatcher's `getCurrentView`, not RotationButton's.
    let declared: Node | null = null;
    for (let depth = 0; depth < 4 && frontier.length > 0; depth++) {
      const next: Node[] = [];
      for (const t of frontier) {
        for (const s of supertypesOf(t)) {
          if (seen.has(s.id)) continue;
          seen.add(s.id);
          next.push(s);
          if (s.name === name) continue;
          const abstractOnly = s.kind === 'interface' || s.kind === 'protocol';
          const found = callableFirst((byOwner.get(s.qualifiedName) ?? []).filter((c) =>
            c.filePath === s.filePath &&
            !(receiver === 'super' && (c.isAbstract || abstractOnly))));
          if (found.length === 0) continue;
          if (!abstractOnly && !found[0]!.isAbstract) return found[0]!;
          declared ??= found[0]!;
        }
      }
      frontier = next;
    }
    return declared;
  };
  // Inherited members, breadth-first over the resolved extends/implements
  // edges, starting from the caller's own type's supertypes.
  const inherited = (firstSupers: string[], typeName: string): Node | null => {
    if (!context.getSupertypes) return null;
    let frontier = [typeName];
    const seen = new Set(frontier);
    for (let depth = 0; depth < 4 && frontier.length > 0; depth++) {
      const next: string[] = [];
      for (const t of frontier) {
        for (const s of depth === 0 ? firstSupers : context.getSupertypes(t, ref.language)) {
          if (seen.has(s)) continue;
          seen.add(s);
          next.push(s);
          if (s === name) continue;
          // Supertypes come back as bare names: when the caller's language
          // declares a type of that name, a same-named type of another
          // language (Scala `Results` vs Java `play.mvc.Results`) is not it.
          if (!byOwnerName.has(s)) continue;
          const ownLanguage = context.getNodesByName(s).some((n) => MEMBER_OWNER_KINDS.has(n.kind) && n.language === ref.language);
          const found = callableFirst((byOwnerName.get(s) ?? []).filter((c) =>
            (!ownLanguage || c.language === ref.language) &&
            // `super.m()` runs a superclass body, never an interface's
            // abstract declaration.
            !(receiver === 'super' && (c.isAbstract || isInterfaceMember(c)))));
          // Overloads share a file; copies of a same-named type in several
          // files are a guess unless one is the caller's.
          if (found.length > 0 && found.every((c) => c.filePath === found[0]!.filePath)) return found[0]!;
          if (found.length > 0) return found.find((c) => c.filePath === ref.filePath) ?? null;
        }
      }
      frontier = next;
    }
    return null;
  };

  const segments = caller.qualifiedName.split('::');
  // A method's scopes start at its owner; a class caller (a field initializer)
  // is its own scope.
  const start = MEMBER_OWNER_KINDS.has(caller.kind) ? segments.length : segments.length - 1;
  for (let i = start; i > 0; i--) {
    const scope = segments.slice(0, i).join('::');
    const isType = typesNamed(scope).length > 0;
    if (!isType) {
      // `this.`/`super.` name a class member; only a bare call sees locals.
      if (receiver !== 'bare') continue;
      const localFn = members(scope).find((c) => c.filePath === ref.filePath && (c.kind === 'method' || c.kind === 'function'));
      if (localFn) return localFn;
      continue;
    }
    if (receiver !== 'super') {
      const own = pick(scope, true);
      if (own) return own;
    }
    // The type's own supertypes first; by name when they reach nothing, as
    // when the index resolved an `extends` to a namesake (Minestom's
    // `Player extends LivingEntity` to a nested `EntityStatuses.LivingEntity`).
    const decl = declOf(scope);
    const supers = directSupertypes(scope, segments[i - 1]!);
    const viaSuper = (decl && inheritedThrough(decl)) || inherited(supers, segments[i - 1]!);
    if (viaSuper) return viaSuper;
    // `this`/`self`/`super` is the innermost instance; outer classes are
    // reachable only by a bare call.
    if (receiver !== 'bare') return null;
    // A supertype outside the index (an Android `View`, the listener an
    // anonymous class implements) may declare the name, and it would win
    // over the outer class: stop rather than guess past it.
    if (supers.length === 0 && declaresSupertype(scope, segments[i - 1]!)) return null;
  }
  return null;

  /**
   * The declaration's header — its text up to the body's `{`. The declaration
   * that encloses the call when there is one (a Scala `object Cookies` beside
   * a `trait Cookies`), else every declaration of that name (a C++ class whose
   * member is defined out of line).
   */
  function typeHeader(scope: string): string | null {
    const decls = typesNamed(scope);
    const enclosing = decls.filter((n) => n.filePath === ref.filePath && n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line);
    let header = '';
    for (const decl of enclosing.length > 0 ? enclosing.slice(-1) : decls) {
      const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split('\n');
      if (!lines) return null;
      for (let l = decl.startLine - 1; l < Math.min(lines.length, decl.startLine + 30); l++) {
        const brace = lines[l]!.indexOf('{');
        header += ' ' + (brace >= 0 ? lines[l]!.slice(0, brace) : lines[l]);
        if (brace >= 0) break;
      }
    }
    return decls.length > 0 ? header : null;
  }

  /** A type declaration's header: its text up to the body's `{`. */
  function headerOf(decl: Node): string {
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split('\n');
    let header = '';
    for (let l = decl.startLine - 1; lines && l < Math.min(lines.length, decl.startLine + 30); l++) {
      const brace = lines[l]!.indexOf('{');
      header += ' ' + (brace >= 0 ? lines[l]!.slice(0, brace) : lines[l]);
      if (brace >= 0) break;
    }
    return header;
  }

  // getSupertypes answers for every type of that simple name (all of a
  // protobuf file's `Builder`s at once), so keep the ones this declaration's
  // header actually names, in the order it names them: the first base that
  // has the member is the one a call reaches (`class A(B, C)`).
  function directSupertypes(scope: string, simple: string): string[] {
    const all = context.getSupertypes?.(simple, ref.language) ?? [];
    if (all.length === 0) return all;
    const header = typeHeader(scope);
    if (header === null) return all;
    const at = (t: string): number => header.search(new RegExp('(?<![\\w$])' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![\\w$])'));
    return all.filter((t) => at(t) >= 0).sort((a, b) => at(a) - at(b));
  }

  function isInterfaceMember(member: Node): boolean {
    const sep = member.qualifiedName.lastIndexOf('::');
    return sep > 0 && context.getNodesByQualifiedName(member.qualifiedName.slice(0, sep)).some((n) => n.kind === 'interface' || n.kind === 'protocol');
  }

  function declaresSupertype(scope: string, simple: string): boolean {
    if (simple.startsWith('<')) return true; // an anonymous class always has one
    const header = typeHeader(scope);
    if (header === null) return true;
    // `extends` / `implements` / `with`, a C++ `:` base list.
    return /\b(?:extends|implements|with)\b|[\w>)\]]\s*:(?!:)/.test(header);
  }
}

/**
 * Try to resolve a reference by exact name match
 */
export function matchByExactName(
  ref: UnresolvedRef,
  context: ResolutionContext
): ResolvedRef | null {
  // `import`-kind nodes are import STATEMENTS, not definitions, so a reference
  // resolving to a sibling file's `import` is a meaningless edge — the real
  // import→definition resolution is the import resolver's job (resolveViaImport),
  // never name-matching here. Excluding them also removes a quadratic blow-up:
  // a ubiquitous package (`react`, `@superset-ui/core`, Python `logging`/`typing`)
  // is re-declared as an `import` node in every file that imports it, so K
  // unresolved import refs each scored K same-named import candidates through
  // findBestMatch — O(K²) per package, the dominant cost of "Resolving refs" on
  // large import-heavy (front-end + back-end) repos (#915).
  const bareJs = isBareJsCall(ref, context);
  const bareNoMembers = isBareGoCall(ref, context) || isBareRCall(ref, context);
  const solidityBare = isReceiverLessSolidityCall(ref, context);
  const barePhp = isBarePhpCall(ref, context);
  const luaBareCall = (ref.language === 'lua' || ref.language === 'luau') && ref.referenceKind === 'calls' && /^[A-Za-z_]\w*$/.test(ref.referenceName);
  // A type, a value or an import the file binds from a package outside the
  // repository names nothing in it, whatever kind of reference it is.
  if (!bareJs && JS_FAMILY.has(ref.language) && ref.referenceKind !== 'calls' &&
      /^[A-Za-z_$][\w$]*$/.test(ref.referenceName) && isOutOfRepoBinding(ref.referenceName, ref, context)) {
    return null;
  }
  // `import { useQuery } from '@tanstack/react-query'`: the call means the
  // package's, and no other file's same-named symbol. A declaration of the
  // name in this file's inner scope still shadows the import.
  let outOfRepoCall = false;
  if (bareJs) {
    const storeAction = matchJsStoreBindingCall(ref, context);
    if (storeAction) return storeAction;
    const returned = matchDestructuredCallResult(ref, context);
    if (returned) return returned;
    outOfRepoCall = isOutOfRepoBinding(ref.referenceName, ref, context);
  }
  // Every rule below judges one candidate on its own, so they run as ONE pass,
  // the kind/language checks before the ones that read source: a common name
  // has thousands of same-named nodes, and a chain of filters copied that
  // list once per rule for every reference.
  const valueRef = ref.referenceKind === 'references' || ref.referenceKind === 'function_ref';
  const importRef = ref.referenceKind === 'imports';
  const inheritanceRef = isInheritanceRef(ref);
  // Read once, and only for a candidate in another file: it scans the file.
  let bareTypeName: boolean | undefined;
  // Every candidate uses the same binding key. Keep this check lazy.
  let locallyBoundJsName: boolean | undefined;
  const tsBareTypeName = (): boolean => (bareTypeName ??= isTsBareTypeName(ref, context));
  const sameName = outOfRepoCall
    ? innerScopeShadows(context.getNodesByName(ref.referenceName), ref, context)
    : context.getNodesByName(ref.referenceName);
  // `NAME(...)` where NAME is a function-like macro somewhere in the project is
  // an expansion or a call to a same-named function — never the macro itself
  // (#1839), and never a type that happens to share the name (#2070: expat's
  // `PREFIX(scanRef)(…)` bound to an unrelated `struct PREFIX`). Keep
  // upstream's language gate on the chosen result.
  const cMacroCall = ref.referenceKind === 'calls' && (ref.language === 'c' || ref.language === 'cpp') &&
    sameName.some((n) => n.kind === 'constant' && CPP_DEFINE_SIGNATURE.test(n.signature ?? ''));
  const typeRef = isDotNetTypeRef(ref, context);
  const rustBare = ref.language === 'rust' && /^[A-Za-z_]\w*$/.test(ref.referenceName);
  const pythonShape = pythonCallShape(ref, context);
  const javaBare = ref.language === 'java' && ref.referenceKind === 'calls' && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName);
  const dartBare = ref.language === 'dart' && ref.referenceKind === 'calls' && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName) && isReceiverLessDartCall(ref, context);
  // A Dart type name — a declared type, a supertype, the `Color` of `Color.red` — is in scope as a call is, or through its import prefix.
  const dartTypeRef = ref.language === 'dart' && (ref.referenceKind === 'references' || isInheritanceRef(ref)) && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName);
  const dartPrefix = dartTypeRef ? dartImportPrefixOf(ref, context) : null;
  const kotlinCall = ref.language === 'kotlin' && ref.referenceKind === 'calls' && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName);
  const kotlinBare = kotlinCall && isReceiverLessKotlinCall(ref, context);
  const rubyBare = ref.language === 'ruby' && ref.referenceKind === 'calls' && /^[A-Za-z_]\w*[?!]?$/.test(ref.referenceName);
  const cfmlBare = (ref.language === 'cfml' || ref.language === 'cfscript') && ref.referenceKind === 'calls' && /^[A-Za-z_]\w*$/.test(ref.referenceName);
  const vbReceiver = ref.language === 'vbnet' && (ref.referenceKind === 'calls' || ref.referenceKind === 'instantiates') && /^\w+$/.test(ref.referenceName)
    ? vbReceiverOf(ref, context) : null;
  const vbScoped = isVbScopedCall(ref, vbReceiver, context);
  const vbUnqualified = isVbUnqualifiedName(ref, vbReceiver, context);
  const objcShape = ref.language === 'objc' && ref.referenceKind === 'calls' && /^[A-Za-z_]\w*:*(?:\w+:)*$/.test(ref.referenceName)
    ? objcCallShape(ref, context) : null;
  const csharpBare = ref.language === 'csharp' && (ref.referenceKind === 'calls' || ref.referenceKind === 'references') && /^[A-Za-z_]\w*$/.test(ref.referenceName);
  const scalaBare = ref.language === 'scala' && ref.referenceKind === 'calls' && /^[A-Za-z_$][\w$]*$/.test(ref.referenceName);
  const rustGoShape = (ref.language === 'rust' || ref.language === 'go') && ref.referenceKind === 'calls' && /^[A-Za-z_]\w*$/.test(ref.referenceName)
    ? rustGoCallShape(ref, context) : null;
  const kotlinStdChain = ref.language === 'kotlin' && ref.referenceKind === 'calls' && KOTLIN_STD_METHODS.has(ref.referenceName)
    ? kotlinChainReceiver(ref, context) : null;
  const swiftShape = ref.language === 'swift' && ref.referenceKind === 'calls' && /^[A-Za-z_]\w*$/.test(ref.referenceName)
    ? swiftCallShape(ref, context) : null;
  const phpSelf = phpSelfReceiver(ref, context);
  const filtered = sameName.filter((n) =>
    !(kotlinStdChain !== null && !isKotlinStdChainTarget(n, kotlinStdChain)) &&
    !(swiftShape && !isSwiftCallTarget(n, swiftShape, ref, context)) &&
    !(rustGoShape && !isRustGoCallTarget(n, rustGoShape)) &&
    !(scalaBare && !isScalaMemberInScope(n, ref, context)) &&
    !(csharpBare && !isCsharpMemberInScope(n, ref, context)) &&
    !(objcShape === 'c-call' && OBJC_MEMBER_KINDS.has(n.kind)) &&
    !(objcShape === 'self-send' && !isObjcSelfSendTarget(n, ref, context)) &&
    !(objcShape === 'super-send' && !isObjcSelfSendTarget(n, ref, context, true)) &&
    !isObjcFileLocalElsewhere(n, ref) &&
    !(vbReceiver !== null && !isVbMemberReachable(n, vbReceiver)) &&
    !(vbReceiver && !/^(?:me|mybase|myclass)$/i.test(vbReceiver) && !isVbTypeQualifiedBy(n, vbReceiver, ref.filePath, context)) &&
    !(vbScoped && !isVbMemberInScope(n, ref, context)) &&
    !(vbUnqualified && !isVbNestedTypeInScope(n, ref, context)) &&
    !(rubyBare && n.kind === 'method' && !isRubyMethodInScope(n, ref, context)) &&
    !(cfmlBare && n.kind === 'method' && !isCfmlMethodInScope(n, ref, context)) &&
    !(javaBare && n.kind === 'method' && !isJavaMethodInScope(n, ref, context)) &&
    !(kotlinCall && !isKotlinTopLevelVisible(n, ref, context)) &&
    !(kotlinBare && !isKotlinMemberReachable(n, ref, context)) &&
    !isKotlinNumberBitwise(n, ref) &&
    !(solidityBare && !isSolidityMemberInScope(n, ref, context)) &&
    !(dartBare && isDartMember(n) && !isDartMethodInScope(n, ref, context)) &&
    // A Dart constructor is reached through its class (`Foo.named(…)`,
    // `@Foo.named(…)`), never by its name alone: not a bare call, not the
    // last link of a chain, not an annotation (riverpod's 210 `@internal`
    // annotations went to its providers' `internal` constructors).
    !(ref.language === 'dart' && isDartConstructor(n, context)) &&
    !(dartBare && isDartTypeValue(n) && !isDartMethodInScope(n, ref, context)) &&
    !((dartBare || dartTypeRef) && !isDartTopLevelVisible(n, ref, context, dartPrefix)) &&
    !(ref.language === 'dart' && isDartPrivateOfAnotherLibrary(n, ref, context)) &&
    !(phpSelf && (n.kind !== 'method' || !isPhpMethodInScope(n, ref, phpSelf, context))) &&
    !(pythonShape && !fitsPythonCallShape(n, pythonShape, ref, context)) &&
    !(rustBare && !isRustNameInScope(n, ref, context)) &&
    !(cMacroCall && n.kind !== 'function' && n.kind !== 'method') &&
    !(typeRef && !canNameInTypePosition(n)) &&
    // A Scala type position (`Arbitrary[B]`) never names a method: an
    // `implicit def A: Order[A]` shares its name with half of cats' type
    // parameters. Scala's value references only read a file's own vals.
    // Nor does a kind-projector placeholder (`F[*]`, `G[?]`): cats' 567 `*`
    // type arguments went to an algebra `Sign`'s `*` method.
    !(ref.language === 'scala' && ref.referenceKind === 'references' && /^(?:[A-Z]|[^\w\s]+$)/.test(ref.referenceName) &&
      (n.kind === 'method' || n.kind === 'function')) &&
    // Type/value references retain same-family eligibility: a native namesake
    // must not hide the actual web type. Calls still gate only the winner.
    (!valueRef || sameLanguageFamily(n.language, ref.language)) &&
    n.kind !== 'import' &&
    // A receiver-less JS/TS or Go call cannot reach a member of a type — a
    // method (#1714, #1857), nor a property, field or case: mocha's global
    // `it(…)` bound to an interface's `it` property, `describe(…)` to a
    // command class's `describe` string.
    !((bareJs || bareNoMembers) && TYPE_MEMBER_KINDS.has(n.kind)) &&
    // A bare PHP call is a function call: nothing else is callable without a receiver.
    !(barePhp && n.kind !== 'function') &&
    // Nor is a table's method (`function M.x`, `function M:x`) in Lua, without its table.
    !(luaBareCall && n.kind === 'method') &&
    // A Vue component's own method is `this.m()` inside that component — not
    // `this.$refs['input'].click()` on an element another component renders.
    !(ref.referenceKind === 'calls' && JS_FAMILY.has(ref.language) && isVueComponentMethod(n) && !isThisCallInOwnFile(n, ref, context)) &&
    // An `extends`/`implements` ref names a supertype, so anything that can't
    // BE one is not a candidate at all. This is eligibility, not
    // ranking: kind is only a scoring bonus below (and none is awarded for
    // inheritance refs), so without this a same-named `enum_member` outranked
    // the real `trait`, and as the sole candidate was adopted outright by the
    // single-match shortcut. Restricting the pool BEFORE ranking lets the
    // legitimate supertype win instead of merely dropping the false edge.
    // So does a Kotlin object expression's `instantiates` (Kotlin's only):
    // okhttp's `object : CookieJar { … }` is no `OverrideParam.CookieJar` entry.
    (!(inheritanceRef || (ref.language === 'kotlin' && ref.referenceKind === 'instantiates')) || isSupertypeTarget(n)) &&
    // And a supertype or type a TS/JS module names without importing it is
    // its own or a global, never another module's — ahead of the ranking, so
    // a global `interface Window` in a `declare global` still wins.
    !(n.filePath !== ref.filePath && tsBareTypeName() && !isTsTypeInScope(n, ref, context)) &&
    // Likewise for `imports`: a member that only exists inside a type is not
    // importable, so it is not a candidate. Without this a `path`/`id`/`url`
    // import resolved to some interface's same-named property.
    (!importRef || isImportableKind(n.kind)) &&
    // Nested locals are only reachable from inside their container (#1230).
    isLexicallyReachable(n, ref, context) &&
    // A C# type name is a type its namespaces can see — ahead of the ranking,
    // so a visible namesake wins where the veto after it would drop the
    // ref: eShop's `WebhookType.OrderPaid` under `using Webhooks.API.Model;`.
    // A bare PHP class name, only its namespace's or the imported one — ahead of
    // the ranking, so koel's `extends Request` under `use App\Http\Requests\API\Request;`
    // is that class, not the first `Request` indexed.
    isPhpClassVisible(n, ref, context) &&
    // Likewise a bare Java type name: retrofit's tests' `new Builder()` is not
    // a wire converter test's nested `CrashingPhone.Builder`.
    isJavaTypeVisible(n, ref, context) &&
    // And a Go name that isn't exported, only its own package's: prometheus
    // tsdb's `[]*memSeries` is head.go's, not `tsdb/agent`'s, which scored the
    // same (a child package's directory shares as much of the path) and won.
    (n.language !== 'go' || isGoNameVisible(n, ref, context)) &&
    dartExtensionDecl(n, context)?.named !== false &&
    // A Scala package object's member, only where it is in scope — ahead of
    // the ranking, so cats.laws' `Eq` can be the `cats` package object's.
    !(ref.language === 'scala' && n.language === 'scala' && n.filePath !== ref.filePath &&
      !isScalaPackageObjectMemberVisible(n, ref, context)) &&
    // A nested type, only from inside its owner: AutoMapper's same-file `new
    // Source()` in one test class is not the previous test class's `Source`.
    !(ref.language === 'csharp' && n.language === 'csharp' && CSHARP_TYPE_KINDS.has(n.kind) && /^[A-Za-z_]\w*$/.test(ref.referenceName) &&
      (!isCsharpNestedTypeInScope(n, ref, context) || (n.filePath !== ref.filePath && !isCsharpTypeVisible(n, ref, context)))) &&
    // Preserve import ranking; calls reject the winner without promoting another.
    (!importRef || n.filePath === ref.filePath ||
      !ESM_FAMILY.has(n.language) || !isSealedModule(n.filePath, context)) &&
    // A name the file binds itself (a parameter, a const) shadows every other
    // file's symbol of that name, so a bare call has no cross-file candidate.
    !(bareJs && n.filePath !== ref.filePath && (locallyBoundJsName ??= isLocallyBoundJsName(ref.referenceName, ref.filePath, context)))
  );
  const ranked = dartBare ? nearestDartMembers(preferOwnDartLibrary(filtered, ref, context), ref, context)
    : dartTypeRef && dartPrefix === null ? preferOwnDartLibrary(filtered, ref, context)
    : swiftShape && swiftShape.shape !== 'chained' ? nearestSwiftMembers(filtered, ref, context)
    : kotlinBare ? lexicalKotlinMembers(filtered, ref, context)
    : rubyBare ? rubyMethodsOfCallerKind(filtered, ref, context) : cppSpecializationPool(filtered, ref, context);
  // (Above the ceiling below nothing is picked, so no translation unit is read.)
  const candidates = ranked.length <= AMBIGUOUS_NAME_CEILING ? withinCppTranslationUnit(ranked, ref, context, true) : ranked;

  if (candidates.length === 0) {
    return null;
  }

  // If only one match, use it — but penalize a match in another language
  // family (a `.tsx` component calling a `.ts` helper is not one, #1662)
  if (candidates.length === 1) {
    if (!isCrossFileReachable(candidates[0]!, ref, context)) return null;
    const isCrossLanguage = !sameLanguageFamily(candidates[0]!.language, ref.language);
    return {
      original: ref,
      targetNodeId: candidates[0]!.id,
      confidence: isCrossLanguage ? 0.5 : 0.9,
      resolvedBy: 'exact-match',
    };
  }

  // A member of the caller's own class (or what it inherits / is nested in)
  // is what the name means there, however far away it is declared. Not for a
  // call written on `super`: the one in a class expression's method gets here
  // (js-super-calls declines to place it), and its `super` is that
  // expression's parent, never the enclosing class's (#2497).
  const member = isJsSuperCallSite(ref, context) ? null : matchEnclosingScopeMember(ref, candidates, context);
  // The scope names the member, not the overload: when the class declares
  // the name more than once, the one the arguments fit, else the nearest, is
  // chosen below — among those overloads only, so a sibling class's namesake
  // stays out of it.
  let pool = candidates;
  if (member) {
    const overloads = candidates.filter((c) => c.qualifiedName === member.qualifiedName && c.filePath === member.filePath);
    if (overloads.length <= 1) {
      return { original: ref, targetNodeId: member.id, confidence: 0.9, resolvedBy: 'exact-match' };
    }
    pool = overloads;
  }

  // Ubiquitous-name ceiling (#999): above it, picking one target among K
  // same-named defs by directory proximity is unreliable AND O(K) per ref — the
  // quadratic behind the "Resolving refs" wedge on theme/SDK-vendoring repos.
  // Decline; the precise strategies (qualified-name, import, class-name) already
  // ran. Falls through to fuzzy, which itself only resolves a UNIQUE candidate.
  if (pool.length > AMBIGUOUS_NAME_CEILING) {
    return null;
  }

  // Multiple matches - try to narrow down
  const nearest = findBestMatch(ref, pool, context);
  const bestMatch = nearest && cppFunctionOverload(nearest, pool, ref, context);
  if (bestMatch && isCrossFileReachable(bestMatch, ref, context)) {
    // Lower confidence when the match is from a distant/unrelated module
    const proximity = computePathProximity(ref.filePath, bestMatch.filePath);
    // Every candidate is a copy of one symbol and this is the caller's own
    // copy: the name itself is not ambiguous, only which copy — so rank it
    // above a proximity guess, but below a unique name or the file's own
    // definition (0.9). The candidates are those findBestMatch weighed: a
    // namesake in another language never wins while one in the reference's
    // own language (sameRankingLanguage) exists. The caller's own copy being
    // the caller itself is no evidence, as for a same-file match
    // (isDecisiveSameFileMatch).
    const weighed = candidates.some((c) => sameRankingLanguage(c.language, ref.language))
      ? candidates.filter((c) => sameRankingLanguage(c.language, ref.language))
      : candidates;
    const confidence = isDecisiveSameFileMatch(bestMatch, ref, candidates, context)
      ? 0.9
      : bestMatch.id !== ref.fromNodeId && closestCopy(ref, weighed) === bestMatch ? 0.8
      : proximity >= 30 ? 0.7 : 0.4;
    return {
      original: ref,
      targetNodeId: bestMatch.id,
      confidence,
      resolvedBy: 'exact-match',
    };
  }

  return null;
}

/** Languages whose supertypes are written through their enclosing type with a dot: `Outer.Inner`. */
const DOTTED_SUPERTYPE_LANGUAGES: ReadonlySet<string> = new Set(['java', 'kotlin', 'csharp']);
const DOTTED_SUPERTYPE_KINDS: ReadonlySet<string> = new Set(['class', 'interface', 'struct', 'trait', 'enum']);

/**
 * A supertype written through its enclosing type — Java's `class Named extends
 * Outer.Inner`, `implements Api.Listener` or `new Api.Listener() {…}`, Kotlin's
 * `class K : Outer.Inner()` or `object : Api.Listener`, C#'s `class N :
 * Outer.IListener` — or in full (`com.x.Outer.Inner`). The index names a nested
 * type `p::Outer::Inner`, so the written path is the tail of its qualified
 * name. A path that is not written in full must start at a type the file can
 * name: in its own file, package or namespace, or one it imports (C#: one its
 * usings reach). Of several, the one closest to the file in the tree, or none
 * when two are as close. Undefined when no project type has the path (a
 * library supertype), for the other strategies to look at.
 */
function matchDottedSupertype(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  // A Kotlin object expression's `instantiates` names its supertype as written too.
  if (!DOTTED_SUPERTYPE_LANGUAGES.has(ref.language) ||
      !(isInheritanceRef(ref) || (ref.language === 'kotlin' && ref.referenceKind === 'instantiates'))) return undefined;
  const written = ref.referenceName.replace(/<[^<>]*(?:<[^<>]*>[^<>]*)*>/g, '').replace(/\s+/g, '');
  if (!/^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+$/.test(written)) return undefined;
  const parts = written.split('.');
  const candidates = context.getNodesByName(parts[parts.length - 1]!).filter((n) => {
    if (!DOTTED_SUPERTYPE_KINDS.has(n.kind) || !sameLanguageFamily(n.language, ref.language) || n.id === ref.fromNodeId) return false;
    const dotted = n.qualifiedName.replace(/::/g, '.');
    return dotted === written || dotted.endsWith(`.${written}`);
  });
  if (candidates.length === 0) return undefined;
  const visible = candidates.filter((n) => {
    if (n.qualifiedName.replace(/::/g, '.') === written || n.filePath === ref.filePath) return true;
    // The type the written path starts at: `p::Outer` for `p::Outer::Inner`.
    const segments = n.qualifiedName.split('::');
    const rootQn = segments.slice(0, segments.length - (parts.length - 1)).join('::');
    const cut = rootQn.indexOf('::');
    const pkg = cut < 0 ? '' : rootQn.slice(0, cut);
    const rootFqn = rootQn.replace(/::/g, '.');
    if (ref.language === 'java') {
      const scope = javaFileScope(ref.filePath, context);
      return scope.pkg === pkg || scope.single.has(rootFqn) || scope.demand.has(pkg);
    }
    if (ref.language === 'kotlin') {
      const scope = kotlinFileScope(ref.filePath, context);
      return scope.pkg === pkg || scope.imports.has(rootFqn) || scope.stars.has(pkg);
    }
    const root = context.getNodesByQualifiedName(rootQn).find((r) => DOTTED_SUPERTYPE_KINDS.has(r.kind));
    return root !== undefined && isCsharpTypeVisible(root, { ...ref, referenceName: parts[0]! }, context);
  });
  if (visible.length === 0) return null;
  let chosen = visible[0]!;
  if (visible.length > 1) {
    const fromDirs = ref.filePath.split('/').slice(0, -1);
    const closeness = (n: Node): number => {
      const dirs = n.filePath.split('/').slice(0, -1);
      let shared = 0;
      while (shared < Math.min(dirs.length, fromDirs.length) && dirs[shared] === fromDirs[shared]) shared++;
      return shared;
    };
    const ranked = visible.map((n) => ({ n, c: closeness(n) })).sort((a, b) => b.c - a.c);
    if (ranked[0]!.c === ranked[1]!.c) return null;
    chosen = ranked[0]!.n;
  }
  return { original: ref, targetNodeId: chosen.id, confidence: 0.9, resolvedBy: 'qualified-name' };
}

/**
 * Try to resolve by qualified name
 */
export function matchByQualifiedName(
  ref: UnresolvedRef,
  context: ResolutionContext
): ResolvedRef | null {
  // Check if the reference name looks qualified (contains :: or .)
  if (!ref.referenceName.includes('::') && !ref.referenceName.includes('.')) {
    return null;
  }

  // A method call `receiver.method()` can share an exact qualified name with a
  // config-file key: `service.process()` (a `calls` ref named `service.process`)
  // vs the yaml key `service.process`. Config keys are bound to their code refs
  // upstream by the framework resolvers (`@Value` → `references`); a `calls` ref
  // must never resolve to a yaml/properties config node — that's a wrong edge
  // AND it hides the real callee. Drop those from both the exact and the partial
  // candidate sets so resolution falls through to method resolution below (#1180).
  const keepForRef = (nodes: Node[]): Node[] =>
    ref.referenceKind === 'calls'
      ? nodes.filter(
          (n) => !(n.kind === 'constant' && (n.language === 'yaml' || n.language === 'properties')),
        )
      : nodes;

  // A C or C++ name written from the global scope (`::hpb::CreateMessage`,
  // `::operator delete`) is the declaration of exactly that name. The suffix
  // match below would take one nested in another namespace or class: for
  // fmt's mock `test::open`, the `::open(…)` it wraps. Nor is it a declaration
  // inside a namespace a macro opens, which only looks global in the index
  // (fmt's `struct pipe`); step 5 of matchReference reads those.
  if ((ref.language === 'cpp' || ref.language === 'c') && ref.referenceName.startsWith('::')) {
    const global = cppSpecializationPool(keepForRef(context.getNodesByQualifiedName(ref.referenceName.slice(2))).filter((n) =>
      (n.language === 'cpp' || n.language === 'c') &&
      !cppMacroNamespaceFrames(n.filePath, context).some((f) => f.start <= n.startLine && f.end >= n.startLine)), ref, context);
    const chosen = preferCallSiteFile(global, ref.filePath)[0];
    if (!chosen) return null;
    return {
      original: ref,
      targetNodeId: cppFunctionOverload(chosen, global, ref, context).id,
      confidence: global.length === 1 || chosen.filePath === ref.filePath ? 0.95 : 0.85,
      resolvedBy: 'qualified-name',
    };
  }

  let candidates = cppQualifierSpecializationPool(cppSpecializationPool(keepForRef(context.getNodesByQualifiedName(ref.referenceName)), ref, context), ref, context);
  // A C# `using X.Y;` names a namespace: one the project declares, else it is
  // the file's own (external) using — never another file's using of that name.
  // That own using ends the lookup here, and resolveOne drops it (an import
  // never names its own statement), so the ref parks as failed.
  if (ref.language === 'csharp' && ref.referenceKind === 'imports') {
    const namespaces = candidates.filter((n) => n.kind === 'namespace');
    candidates = namespaces.length > 0 ? preferCallSiteFile(namespaces, ref.filePath).slice(0, 1)
      : candidates.filter((n) => n.kind !== 'import' || n.filePath === ref.filePath);
  }

  if (candidates.length === 1) {
    return {
      original: ref,
      targetNodeId: candidates[0]!.id,
      confidence: 0.95,
      resolvedBy: 'qualified-name',
    };
  }

  // Several symbols share this exact qualified name (e.g. `Logger::log` declared
  // in two files — an ODR clash or separate translation units): prefer the one
  // in the call site's own file before the partial-match fallback below, else
  // the first-indexed def wins and a call in `b/svc` targets `a/svc` (#1079).
  if (candidates.length > 1) {
    const ordered = preferCallSiteFile(candidates, ref.filePath);
    if (ordered[0]!.filePath === ref.filePath) {
      return {
        original: ref,
        targetNodeId: cppFunctionOverload(ordered[0]!, ordered, ref, context).id,
        confidence: 0.95,
        resolvedBy: 'qualified-name',
      };
    }
  }

  // Erlang qualified refs (#1610): every erlang function's qualifiedName
  // carries its arity (`mod::f/2`), and refs carry the call-site arity when it
  // is statically known.
  if (ref.language === 'erlang' && ref.referenceName.includes('::')) {
    // A ref WITH arity that missed the exact lookup names an arity that isn't
    // defined (or a module out of repo). Never fall through to the partial
    // match — its "last segment" would be the arity digits — and never settle
    // for a sibling arity: silent beats wrong.
    if (/\/\d{1,3}$/.test(ref.referenceName)) return null;
    // An arity-LESS qualified ref (dynamic MFA whose args list wasn't a
    // static literal): resolve only when the module defines exactly ONE arity
    // of that function; several arities with no signal is a guess.
    const base = ref.referenceName.slice(ref.referenceName.lastIndexOf('::') + 2);
    const prefix = `${ref.referenceName}/`;
    const arityCands = keepForRef(context.getNodesByName(base)).filter(
      (n) =>
        n.qualifiedName.startsWith(prefix) && /^\d{1,3}$/.test(n.qualifiedName.slice(prefix.length)),
    );
    if (arityCands.length === 1) {
      return {
        original: ref,
        targetNodeId: arityCands[0]!.id,
        confidence: 0.85,
        resolvedBy: 'qualified-name',
      };
    }
    return null;
  }

  // Try partial qualified name match — again preferring the call site's own
  // file when more than one symbol's qualifiedName ends with the reference.
  // The written name must start a scope of the candidate's: rocksdb's
  // `CacheShard::ComputeHash` (a template parameter's) is no
  // `clock_cache::ClockCacheShard::ComputeHash`. A namesake in the call's own
  // language comes first: protobuf's C++ `DescriptorPool::generated_pool()`
  // is never its Ruby `Google::Protobuf::DescriptorPool`'s.
  const parts = ref.referenceName.split(/[:.]/);
  const lastName = parts[parts.length - 1];
  if (lastName) {
    const partialCandidates = cppQualifierSpecializationPool(cppSpecializationPool(keepForRef(context.getNodesByName(lastName))
      .filter((candidate) => endsAtScopeBoundary(candidate.qualifiedName, ref.referenceName)), ref, context), ref, context);
    const ownLanguage = partialCandidates.filter((candidate) => sameLanguageFamily(candidate.language, ref.language));
    const pool = ownLanguage.length > 0 ? ownLanguage : partialCandidates;
    const chosen = preferCallSiteFile(pool, ref.filePath)[0];
    if (chosen) {
      return {
        original: ref,
        targetNodeId: cppFunctionOverload(chosen, pool, ref, context).id,
        confidence: 0.85,
        resolvedBy: 'qualified-name',
      };
    }
  }

  return null;
}

/**
 * Whether qualified name `qn` is `name`, or ends with it right after a scope
 * separator: `::`, or the `.` of a dotted package, namespace, object path or
 * config key. A name written from the global scope (`::Foo::bar`) is never
 * the tail of a nested one.
 */
function endsAtScopeBoundary(qn: string, name: string): boolean {
  if (qn === name) return true;
  if (!qn.endsWith(name)) return false;
  const before = qn.slice(0, qn.length - name.length);
  return before.endsWith('::') || before.endsWith('.');
}

/** A node a `Receiver.method()` call can name as the method's owning type. */
function isMethodOwnerKind(n: Node): boolean {
  return n.kind === 'class' || n.kind === 'struct' || n.kind === 'union' || n.kind === 'interface' ||
    (n.language === 'scala' && n.kind === 'module');
}

/**
 * When a symbol name is ambiguous across files, prefer the candidate(s) declared
 * in the call site's own file, keeping the rest in their original order (#1079).
 * A same-file definition is the strongest language-agnostic signal for which of
 * several same-named symbols a call means; without it, resolution collapses onto
 * whichever was indexed first, so a call in `b/svc` wrongly targets `a/svc`.
 * No-op when there are <2 candidates or none share the call site's file.
 */
export function preferCallSiteFile(nodes: Node[], callSiteFile: string): Node[] {
  if (nodes.length < 2) return nodes;
  const same: Node[] = [];
  const other: Node[] = [];
  for (const n of nodes) {
    if (n.filePath === callSiteFile) same.push(n);
    else other.push(n);
  }
  return same.length ? [...same, ...other] : nodes;
}

/**
 * Languages whose object literals declare callable members — `export const
 * api = { call() {…}, get: () => {…} }` used as a namespace (#1573) — including
 * the script blocks of single-file components (#2300).
 */
const OBJECT_LITERAL_LANGUAGES = new Set<string>(['typescript', 'tsx', 'javascript', 'jsx', 'arkts', 'vue', 'svelte', 'astro']);

/** True when `inner`'s source range lies within `outer`'s (lines, then columns on a shared line). */
function rangeWithin(inner: Node, outer: Node): boolean {
  const innerEnd = inner.endLine ?? inner.startLine;
  const outerEnd = outer.endLine ?? outer.startLine;
  if (inner.startLine < outer.startLine || innerEnd > outerEnd) return false;
  if (inner.startLine === outer.startLine && inner.startColumn < outer.startColumn) return false;
  if (innerEnd === outerEnd && inner.endColumn > outer.endColumn) return false;
  return true;
}

function sameRange(a: Node, b: Node): boolean {
  return (
    a.startLine === b.startLine &&
    a.startColumn === b.startColumn &&
    (a.endLine ?? a.startLine) === (b.endLine ?? b.startLine) &&
    a.endColumn === b.endColumn
  );
}

/**
 * Resolve `container.member` where `container` is a VALUE holding an object
 * literal — `export const api = { call() {…}, get: () => {…} }` used as the
 * module's namespace (#1573). The members are extracted as plain functions
 * with BARE qualified names inside the constant's source extent (there is no
 * `api::call`), so neither the `Container::member` lookup the class-shaped
 * kinds use (#825) nor the declared-type inference for singleton instances
 * (#1292) can reach them, and every such call resolved to nothing — or, via
 * an import, to the constant itself. This looks the member up by CONTAINMENT:
 * a node named `member` whose range lies inside the container's, in the
 * container's own file. A helper declared inside a member's body is not a
 * member and is skipped; nothing else in the file can donate a match. Calls
 * take callable kinds only; other references accept value members too.
 */
export function resolveObjectLiteralMember(
  container: Node,
  member: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  confidence: number,
  resolvedBy: ResolvedRef['resolvedBy'],
): ResolvedRef | null {
  if (container.kind !== 'constant' && container.kind !== 'variable') return null;
  if (!OBJECT_LITERAL_LANGUAGES.has(container.language)) return null;
  if (!sameLanguageFamily(container.language, ref.language)) return null;

  const inFile = context.getNodesInFile(container.filePath);
  const callable = (n: Node) => n.kind === 'function' || n.kind === 'method';
  const valueMember = (n: Node) =>
    callable(n) || n.kind === 'property' || n.kind === 'variable' || n.kind === 'constant';
  const accepts = ref.referenceKind === 'calls' ? callable : valueMember;

  const inside = inFile.filter((n) => n.id !== container.id && rangeWithin(n, container));
  const property = objectLiteralProperty(container, member, context);
  if (property === null || property?.binding) return null;
  let candidates = inside.filter((n) => n.name === member && accepts(n) && (!property || property.contains(n)));
  if (candidates.length === 0) return null;

  // Drop a candidate nested inside ANOTHER callable's body within the literal
  // (`{ run() { const call = () => {}; } }` — `call` is `run`'s local, not a
  // member). Strict containment: an identically-ranged sibling node for the
  // same member (a property node over an arrow function) is not a body.
  const bodies = inside.filter(callable);
  candidates = candidates.filter(
    (c) => !bodies.some((b) => b.id !== c.id && !sameRange(b, c) && rangeWithin(c, b))
  );
  if (candidates.length === 0) return null;

  // Several survivors (a property AND a function for one arrow member, say):
  // a callable first, then the earliest in source order.
  candidates.sort((a, b) => {
    const ca = callable(a) ? 0 : 1;
    const cb = callable(b) ? 0 : 1;
    if (ca !== cb) return ca - cb;
    return a.startLine - b.startLine || a.startColumn - b.startColumn;
  });
  return {
    original: ref,
    targetNodeId: candidates[0]!.id,
    confidence,
    resolvedBy,
  };
}

/**
 * The binding an object-literal member names when it is a shorthand property
 * (`{ getUser }`) or a pair whose value is a bare identifier (`{ getUser:
 * fetchUser }`) — the usual way an API module assembles its namespace from
 * standalone functions (#1932). Only the literal's own members count: a member
 * of a nested object, a word inside a member's body, a comment or a string
 * never donates one. Null when the member is absent, or when its value is not
 * a bare identifier (`{ fn: 1 }` names nothing).
 */
export function objectLiteralMemberBinding(
  container: Node,
  member: string,
  context: ResolutionContext,
): string | null {
  return objectLiteralProperty(container, member, context)?.binding ?? null;
}

/** The last own property wins; an unknown spread/computed key invalidates earlier evidence. */
function objectLiteralProperty(
  container: Node,
  member: string,
  context: ResolutionContext,
): { binding: string | null; contains: (node: Node) => boolean } | null | undefined {
  const lines = context.getFileLines?.(container.filePath) ?? context.readFile(container.filePath)?.split('\n');
  if (!lines) return undefined;
  const extentLines = lines.slice(container.startLine - 1, container.endLine);
  if (!extentLines.length) return undefined;
  extentLines[extentLines.length - 1] = extentLines[extentLines.length - 1]!.slice(0, container.endColumn);
  extentLines[0] = extentLines[0]!.slice(container.startColumn);
  const extent = stripCommentsForRegex(extentLines.join('\n'), 'typescript');
  const code = blankStringContents(extent);
  // Start at THIS declarator, including its columns, never a sibling on the same line.
  const open = /^[^=]*=\s*(?:(?:Object\.(?:freeze|seal)\s*)?\(\s*)*\{/.exec(code);
  if (!open) return undefined;

  const members: Array<{ start: number; end: number }> = [];
  let depth = 0;
  let start = open[0].length;
  for (let i = start; i < code.length; i++) {
    const ch = code[i];
    if (ch === '{' || ch === '(' || ch === '[') depth++;
    else if (ch === ')' || ch === ']') depth--;
    else if (ch === '}') {
      if (depth === 0) {
        members.push({ start, end: i });
        break;
      }
      depth--;
    } else if (ch === ',' && depth === 0) {
      members.push({ start, end: i });
      start = i + 1;
    }
  }

  let selected: { start: number; end: number; binding: string | null } | null = null;
  for (const part of members) {
    const text = extent.slice(part.start, part.end).trim();
    if (/^(?:\.\.\.|\[)/.test(text)) { selected = null; continue; }
    const key = /^(?:(?:async|get|set)\s+)?\*?\s*(?:([A-Za-z_$][\w$]*)|['"]([^'"\\]*)['"])(?=\s*(?:[:(<,=]|$))/.exec(text);
    if ((key?.[1] ?? key?.[2]) !== member) continue;
    const value = text.slice(key![0].length).trim();
    const binding = value === '' ? member : /^:\s*([A-Za-z_$][\w$]*)$/.exec(value)?.[1] ?? null;
    selected = { ...part, binding };
  }
  if (!selected) return null;
  const offset = (node: Node): number => {
    let result = node.startColumn - container.startColumn;
    for (let line = container.startLine; line < node.startLine; line++) result += lines[line - 1]!.length + 1;
    return result;
  };
  const property = selected;
  return { binding: property.binding, contains: (node) => offset(node) >= property.start && offset(node) < property.end };
}

/**
 * Shared lexical lookup for namespace-object aliases (#1932): `api.getUser()` where
 * `api` is `const api = { getUser }` (or `{ getUser: fetchUser }`) in the
 * object's own file. The member's function is declared OUTSIDE the literal, so
 * containment (`resolveObjectLiteralMember`) finds nothing. Follow the binding
 * the member names — a symbol of this file, else one of its imports — unless a
 * parameter or nearer declaration shadows that name where the literal is
 * written (the edge would then name the wrong function).
 */
export function resolveObjectLiteralBinding(
  container: Node,
  member: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null {
  const binding = objectLiteralMemberBinding(container, member, context);
  if (!binding) return null;
  const at: UnresolvedRef = { ...ref, filePath: container.filePath, language: container.language,
    fromNodeId: container.id, line: container.startLine, column: container.startColumn };
  const inFile = context.getNodesInFile(container.filePath);
  if (inFile.some((n) => (n.kind === 'function' || n.kind === 'method') &&
      rangeWithin(container, n) && n.signature &&
      hasParameterBinding(`${n.signature} {`, binding.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')))) return null;

  const lines = context.getFileLines?.(container.filePath) ?? context.readFile(container.filePath)?.split('\n');
  if (!lines) return null;
  const code = blankStringContents(stripCommentsForRegex(lines.join('\n'), 'typescript'));
  const offsets = [0];
  for (let i = 0; i < code.length; i++) if (code[i] === '\n') offsets.push(i + 1);
  const scopeAt = (node: Node): number[] => {
    const end = (offsets[node.startLine - 1] ?? code.length) + node.startColumn;
    const scope: number[] = [];
    for (let i = 0; i < end; i++) {
      if (code[i] === '{') scope.push(i);
      else if (code[i] === '}') scope.pop();
    }
    return scope;
  };
  const scope = scopeAt(container);

  const callable = (n: Node) => n.kind === 'function' || n.kind === 'method' || n.kind === 'class';
  const accepts =
    ref.referenceKind === 'calls'
      ? callable
      : (n: Node) => callable(n) || n.kind === 'constant' || n.kind === 'variable' || n.kind === 'component';

  const locals = inFile
    .filter((n) => n.name === binding && n.id !== container.id &&
      ['function', 'class', 'constant', 'variable', 'component'].includes(n.kind))
    .map((node) => ({ node, scope: scopeAt(node) }))
    .filter((entry) => entry.scope.every((position, i) => scope[i] === position))
    .sort((a, b) => b.scope.length - a.scope.length);
  // Select the lexical binding BEFORE checking callability: a nearer value
  // shadows an outer function even if that value cannot be called.
  const local = locals[0]?.node;
  if (local) return accepts(local)
    ? { original: ref, targetNodeId: local.id, confidence: 0.85, resolvedBy: 'instance-method' }
    : null;

  const imported = context.resolveImport?.({ ...at, referenceName: binding });
  const target = imported ? context.getNodeById?.(imported.targetNodeId) : null;
  if (target && accepts(target)) {
    return { original: ref, targetNodeId: target.id, confidence: 0.85, resolvedBy: 'instance-method' };
  }
  return null;
}

// ── Object literals that own their members (#2300) ──────────────────────────────
//
// A named object literal — `const App = {…}`, the same inside an IIFE or a
// function, `App = {…}`, or one hung on a path (`window.App = {…}`, `App.utils
// = {…}`) — makes each function member a node qualified under its owner
// (`App::init`, `window.App::init`). An owner is a constant or variable whose
// initializer is an object literal. A member is reached THROUGH its object:
// `App.init()`, `window.App.init()`, `App.utils.fmt()`, a sibling's
// `this.init()`, a `const { init } = App` binding — never by its name alone.

/**
 * A path on the global object — `window.`, `globalThis.`. (`self` is the
 * global only in a worker; in page code it is far more often `var self = this`.)
 */
const HOST_GLOBAL_PREFIX = /^(?:window|globalThis)\./;

/** The last `::` segment of a qualified name. */
function lastQualifiedSegment(qualifiedName: string): string {
  const cut = qualifiedName.lastIndexOf('::');
  return cut < 0 ? qualifiedName : qualifiedName.slice(cut + 2);
}

/**
 * The path a constant or variable is reached by: its name, or — for an object
 * hung on a path by assignment — that path, any global-object root dropped
 * (`window.App = {…}` defines the global `App`; `App.utils = {…}` is `App.utils`).
 */
function holderPath(n: Node): string {
  const last = lastQualifiedSegment(n.qualifiedName);
  return last.includes('.') ? last.replace(HOST_GLOBAL_PREFIX, '') : n.name;
}

/** Whether a constant or variable was hung on a dotted path by assignment rather than declared. */
function isPathHolder(n: Node): boolean {
  return lastQualifiedSegment(n.qualifiedName).includes('.');
}

/** Whether `n` holds an object literal: an owner its members can belong to. */
function isObjectLiteralOwner(n: Node): boolean {
  return (n.kind === 'constant' || n.kind === 'variable') && JS_FAMILY.has(n.language) && /^=\s*\{/.test(n.signature ?? '');
}

const OBJECT_OWNER_OF = new WeakMap<ResolutionContext, Map<string, Node | null>>();

/**
 * The object literal a function node is a member of — its qualified parent,
 * an owner in its file whose extent holds it — or null for every other
 * function: a declaration, a helper nested in a function, a function inside
 * an initializer that is not an object literal (a module IIFE's own helpers).
 */
function objectLiteralOwnerOf(n: Node, context: ResolutionContext): Node | null {
  if (n.kind !== 'function' || !JS_FAMILY.has(n.language)) return null;
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut <= 0) return null;
  let memo = OBJECT_OWNER_OF.get(context);
  if (!memo) OBJECT_OWNER_OF.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  const parent = n.qualifiedName.slice(0, cut);
  const owner = context.getNodesByQualifiedName(parent).find((o) =>
    o.filePath === n.filePath && o.id !== n.id && isObjectLiteralOwner(o) && rangeWithin(n, o)) ?? null;
  memo.set(n.id, owner);
  return owner;
}

/** The node a qualified name's parent names, in `n`'s file and holding it. */
function qualifiedParentOf(n: Node, context: ResolutionContext): Node | null {
  const cut = n.qualifiedName.lastIndexOf('::');
  if (cut <= 0) return null;
  return context.getNodesByQualifiedName(n.qualifiedName.slice(0, cut))
    .find((p) => p.filePath === n.filePath && p.id !== n.id && rangeWithin(n, p)) ?? null;
}

/** An arrow function's text: `(a) =>`, `async (a) =>`, `a =>`, `<T>(a: T) =>` — not `name(…) {`, `function …`. */
const ARROW_HEAD = /^(?:async\s*)?(?:[(<]|[A-Za-z_$][\w$]*\s*=>)/;

/** Whether an object literal's member is an arrow function — one that has no `this` of its own. */
function isArrowMember(n: Node, context: ResolutionContext): boolean {
  const line = (context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split('\n'))?.[n.startLine - 1] ?? '';
  return ARROW_HEAD.test(line.slice(n.startColumn));
}

const THIS_CALLERS = new WeakMap<ResolutionContext, Map<string, Node>>();

/**
 * The caller whose scope `this` belongs to, for code written in `caller`
 * (#2300). An object literal's own method — `load() {…}`, `load: function () {…}`
 * — has the object: it is returned as is, so its qualified parent is the
 * owner. An arrow member has no `this` of its own, and a value written in the
 * literal runs where the literal is: both take the `this` of the code around
 * the literal, a class method's in `class App { api() { return { load: () =>
 * this.x() } } }`. Any other caller is its own scope.
 */
export function thisScopeCaller(caller: Node, context: ResolutionContext): Node {
  if (!JS_FAMILY.has(caller.language)) return caller;
  let memo = THIS_CALLERS.get(context);
  if (!memo) THIS_CALLERS.set(context, (memo = new Map()));
  const hit = memo.get(caller.id);
  if (hit) return hit;
  let cur = caller;
  for (let depth = 0; depth < 8; depth++) {
    const owner = isObjectLiteralOwner(cur) ? cur
      : objectLiteralOwnerOf(cur, context) !== null && isArrowMember(cur, context) ? objectLiteralOwnerOf(cur, context) : null;
    if (!owner) break;
    const up = qualifiedParentOf(owner, context);
    if (!up) break;
    cur = up;
  }
  memo.set(caller.id, cur);
  return cur;
}

/** The object literal `this` is inside `caller`, when it is one: the owner of an object's own method. */
function thisObjectOf(caller: Node, context: ResolutionContext): Node | null {
  const scope = thisScopeCaller(caller, context);
  const owner = objectLiteralOwnerOf(scope, context);
  return owner && !isArrowMember(scope, context) ? owner : null;
}

/** Whether (line, column) falls inside `n`'s source range. */
function positionWithin(line: number, column: number, n: Node): boolean {
  const end = n.endLine ?? n.startLine;
  if (line < n.startLine || line > end) return false;
  if (line === n.startLine && column < n.startColumn) return false;
  return !(line === end && column >= n.endColumn);
}

/**
 * What the object-literal lookups read from a JS/TS file (#2300), each part
 * built on first use: its source with comments and string contents blanked
 * (offsets kept), its `{…}` blocks, the scopes it binds a name in and the
 * names it destructures off a path. References arrive file by file, so only
 * the last few files' are kept: no file is read twice in a row, and a large
 * project's files are never all held at once (#2334).
 */
interface JsFileScan {
  source: string | null;
  code?: string | null;
  blocks?: JsBlockIndex | null;
  bindings?: Map<string, Array<[number, number]>>;
  destructured?: Map<string, Set<string>>;
}

const JS_FILE_SCANS = new WeakMap<ResolutionContext, Map<string, JsFileScan>>();
const JS_FILE_SCANS_KEEP = 32;

function jsFileScan(filePath: string, context: ResolutionContext): JsFileScan {
  let files = JS_FILE_SCANS.get(context);
  if (!files) JS_FILE_SCANS.set(context, (files = new Map()));
  let scan = files.get(filePath);
  if (scan) {
    files.delete(filePath); // re-added below: the most recently read goes last
  } else {
    const source = context.readFile(filePath);
    scan = { source: typeof source === 'string' ? source : null };
    if (files.size >= JS_FILE_SCANS_KEEP) files.delete(files.keys().next().value!);
  }
  files.set(filePath, scan);
  return scan;
}

function scannedCode(scan: JsFileScan): string | null {
  if (scan.code === undefined) {
    scan.code = scan.source === null ? null : blankStringContents(stripCommentsForRegex(scan.source, 'typescript'));
  }
  return scan.code;
}

/** A JS/TS file's source with comments and string contents blanked, offsets kept. */
function maskedJsSource(filePath: string, context: ResolutionContext): string | null {
  return scannedCode(jsFileScan(filePath, context));
}

/**
 * Whether a reference by NAME alone can mean an object literal's member. Only
 * three ways write one: the owner's own `this.load()` (a sibling member), a
 * named function expression calling itself (`load: function load() { load() }`),
 * and a binding destructured off the owner (`const { load } = App`). A bare
 * `load()`, a callback `setTimeout(load)`, `window.Other.load()` mean a
 * function of that name — or nothing.
 */
function isObjectMemberReachableByName(n: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const owner = objectLiteralOwnerOf(n, context);
  if (!owner) return true;
  if (ref.filePath === n.filePath) {
    if (ref.referenceKind === 'calls' && positionWithin(ref.line, ref.column, owner) &&
        bareCallReceiver(ref, context)?.receiver === 'self') {
      // `this` must be that object: written in one of its own methods, not in an arrow member.
      const caller = context.getNodeById?.(ref.fromNodeId);
      if (caller && thisObjectOf(caller, context)?.id === owner.id) return true;
    }
    if (positionWithin(ref.line, ref.column, n)) {
      const line = (context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split('\n'))?.[n.startLine - 1] ?? '';
      const self = new RegExp(`^(?:async\\s+)?function\\s*\\*?\\s*${n.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w$])`);
      if (self.test(line.slice(n.startColumn))) return true;
    }
  }
  return destructuresMember(ref.filePath, holderPath(owner), n.name, context);
}

/** `{ … } = App` / `= window.App.utils`: a pattern destructured off a plain path (the whole right-hand side). */
const DESTRUCTURED_OFF_PATH = /\{([^{}]*)\}\s*=\s*(?:(?:window|globalThis)\s*\.\s*)?([A-Za-z_$][\w$]*(?:\s*\.\s*[A-Za-z_$][\w$]*)*)(?![\w$])(?!\s*[.(\[])/g;
/**
 * A `}` then `=` with only space and comments between — what any such pattern
 * holds, read off the raw text. Each comment form matches one way only (a
 * line comment through its newline, a block comment to its first `*\/`), so
 * a `////////` banner can't make the match backtrack without end.
 */
const CLOSE_THEN_ASSIGN = /\}(?:\s|\/\*(?:[^*]|\*(?!\/))*\*\/|\/\/[^\n]*\n)*=(?!=)/;

/**
 * Whether a file binds `member` by destructuring it off the object at `path`:
 * `{ load }` or `{ a, load = fallback }` off `App` — not `{ x: load }`, which
 * binds `load` to `App.x`. The file's patterns are read once, on first use.
 */
function destructuresMember(filePath: string, path: string, member: string, context: ResolutionContext): boolean {
  const scan = jsFileScan(filePath, context);
  if (!scan.destructured) {
    const paths = new Map<string, Set<string>>();
    const code = scan.source !== null && CLOSE_THEN_ASSIGN.test(scan.source) ? scannedCode(scan) : null;
    for (const m of code?.matchAll(DESTRUCTURED_OFF_PATH) ?? []) {
      const own = [...destructuredKeys(m[1]!)].filter(([name, key]) => name === key).map(([name]) => name);
      if (own.length === 0) continue;
      const at = m[2]!.replace(/\s+/g, '');
      const names = paths.get(at);
      if (names) for (const name of own) names.add(name);
      else paths.set(at, new Set(own));
    }
    scan.destructured = paths;
  }
  return scan.destructured.get(path)?.has(member) ?? false;
}

/** A file's `{…}` blocks: for any offset, the innermost one open there (see jsBlockAt). */
interface JsBlockIndex {
  lineStarts: number[];
  /** Offsets of every `{` and `}`, in order. */
  events: number[];
  /** The innermost block still open just after each event (its `{` offset), -1 at the top level. */
  open: number[];
  close: Map<number, number>;
  length: number;
}

function jsBlockIndex(filePath: string, context: ResolutionContext): JsBlockIndex | null {
  const scan = jsFileScan(filePath, context);
  if (scan.blocks === undefined) {
    const code = scannedCode(scan);
    scan.blocks = code === null ? null : readJsBlocks(code);
  }
  return scan.blocks;
}

function readJsBlocks(code: string): JsBlockIndex {
  const lineStarts = [0];
  const events: number[] = [];
  const open: number[] = [];
  const close = new Map<number, number>();
  const stack: number[] = [];
  for (let i = 0; i < code.length; i++) {
    const ch = code.charCodeAt(i);
    if (ch === 10) { lineStarts.push(i + 1); continue; }
    if (ch === 123) stack.push(i);
    else if (ch === 125) {
      const at = stack.pop();
      if (at !== undefined) close.set(at, i);
    } else continue;
    events.push(i);
    open.push(stack.length > 0 ? stack[stack.length - 1]! : -1);
  }
  return { lineStarts, events, open, close, length: code.length };
}

/** The offset of (line, column) in a file. */
function jsOffset(index: JsBlockIndex, line: number, column: number): number {
  return (index.lineStarts[line - 1] ?? index.length) + column;
}

/** The innermost `{…}` holding an offset, as [open, close] — null at the file's top level. */
function jsBlockAt(index: JsBlockIndex, offset: number): [number, number] | null {
  let lo = 0;
  let hi = index.events.length - 1;
  let at = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (index.events[mid]! < offset) { at = mid; lo = mid + 1; } else hi = mid - 1;
  }
  const open = at < 0 ? -1 : index.open[at]!;
  return open < 0 ? null : [open, index.close.get(open) ?? index.length];
}

/**
 * The offset ranges a JS/TS file binds `name` in: a declaration's or a
 * function/class name's enclosing block (the whole file at the top level), a
 * parameter's function body (an expression-bodied arrow's, to the end of its
 * enclosing block). The patterns are isLocallyBoundJsName's; only the scope is
 * added, so one function's parameter does not shadow a global in another.
 */
function bindingScopes(name: string, filePath: string, context: ResolutionContext): Array<[number, number]> {
  const scan = jsFileScan(filePath, context);
  const memo = (scan.bindings ??= new Map());
  const hit = memo.get(name);
  if (hit) return hit;
  const scopes: Array<[number, number]> = [];
  const code = scannedCode(scan);
  const index = jsBlockIndex(filePath, context);
  if (code && index && code.includes(name)) {
    const blockOf = (at: number): [number, number] => jsBlockAt(index, at) ?? [-1, code.length];
    // The body a parameter list (ending in `{` or `=>`) opens.
    const bodyAfter = (start: number, end: number): [number, number] => {
      if (code[end - 1] === '{') return [end - 1, index.close.get(end - 1) ?? code.length];
      let i = end;
      while (i < code.length && /\s/.test(code[i]!)) i++;
      if (code[i] === '{') return [i, index.close.get(i) ?? code.length];
      return [start, blockOf(start)[1]];
    };
    const { decl, fn, param } = localBindingPatterns(name, 'g');
    for (const m of code.matchAll(decl)) scopes.push(blockOf(m.index!));
    for (const m of code.matchAll(fn)) scopes.push(blockOf(m.index!));
    for (const m of code.matchAll(param)) scopes.push(bodyAfter(m.index!, m.index! + m[0].length));
    const arrow = new RegExp(`(?<![\\w$.])${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*=>`, 'g');
    for (const m of code.matchAll(arrow)) scopes.push(bodyAfter(m.index!, m.index! + m[0].length));
  }
  memo.set(name, scopes);
  return scopes;
}

/** Whether a binding of `name` in the reference's own file encloses the reference. */
function bindsNameAt(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const index = jsBlockIndex(ref.filePath, context);
  if (!index) return false;
  const at = jsOffset(index, ref.line, ref.column);
  return bindingScopes(name, ref.filePath, context).some(([start, end]) => at > start && at < end);
}

/**
 * Where a same-file holder of an object can be seen from: the block it is
 * declared in (an IIFE's, a function's), or the whole file for one at the top
 * level — and for a path hung by assignment, which is a property of its root
 * object wherever that is. Returns the depth to rank by (the block's `{`
 * offset; -1 for the whole file), or null when the reference cannot see it —
 * outside its block, or where the calling function binds the root name itself.
 */
function holderScopeAt(holder: Node, ref: UnresolvedRef, viaGlobal: boolean, context: ResolutionContext): number | null {
  let depth = -1;
  // A single-file component's source holds its template and styles too, whose
  // braces are not blocks: a holder there is read as the script's top level.
  if (!isPathHolder(holder) && JS_TS.has(holder.language)) {
    const index = jsBlockIndex(holder.filePath, context);
    const block = index ? jsBlockAt(index, jsOffset(index, holder.startLine, holder.startColumn)) : null;
    if (index && block) {
      const at = jsOffset(index, ref.line, ref.column);
      if (at <= block[0] || at >= block[1]) return null;
      depth = block[0];
    }
  }
  const root = viaGlobal ? null : holderPath(holder).split('.')[0]!;
  const local = root ? jsFunctionLocalScope(root, ref, context) : null;
  if (local && !(holder.filePath === ref.filePath && holder.startLine >= local.start && holder.startLine <= local.end)) return null;
  return depth;
}

const CLASSIC_SCRIPTS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether a JS/TS file is a classic script — no `import`, `export`, CommonJS
 * export or `require(…)` — whose top-level names are globals every other
 * script on the page shares (#2300).
 */
function isClassicScript(filePath: string, context: ResolutionContext): boolean {
  let memo = CLASSIC_SCRIPTS.get(context);
  if (!memo) CLASSIC_SCRIPTS.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit !== undefined) return hit;
  const source = context.readFile(filePath);
  let classic = false;
  if (typeof source === 'string' && !/\.mjs$|\.cjs$/i.test(filePath) && !HAS_CJS_EXPORT.test(source)) {
    const code = maskedJsSource(filePath, context) ?? '';
    classic = !HAS_IMPORT_STATEMENT.test(code) && !HAS_ESM_EXPORT.test(code) && !/(?:^|[^\w$.])require\s*\(/.test(code);
  }
  memo.set(filePath, classic);
  return classic;
}

const GLOBAL_HOLDERS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/** Whether a holder in another file is a global: on the global object, or at the top level of a classic script. */
function isGlobalHolder(n: Node, context: ResolutionContext): boolean {
  let memo = GLOBAL_HOLDERS.get(context);
  if (!memo) GLOBAL_HOLDERS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  let global: boolean;
  if (HOST_GLOBAL_PREFIX.test(lastQualifiedSegment(n.qualifiedName))) global = true;
  else if (!JS_TS.has(n.language) || !isClassicScript(n.filePath, context)) global = false;
  else if (!isPathHolder(n)) {
    const index = jsBlockIndex(n.filePath, context);
    global = !!index && jsBlockAt(index, jsOffset(index, n.startLine, n.startColumn)) === null;
  } else {
    // `App.utils = {…}` is global when `App` is: declared at a classic script's top level, or on the global object.
    const root = holderPath(n).split('.')[0]!;
    global = context.getNodesByName(root).some((r) => (r.kind === 'constant' || r.kind === 'variable') &&
      JS_FAMILY.has(r.language) && holderPath(r) === root && r.id !== n.id && isGlobalHolder(r, context));
  }
  memo.set(n.id, global);
  return global;
}

/**
 * Resolve `member` on the object a dotted `path` names, at `ref` (#2300):
 * `App` for `App.init()` / `window.App.init()`, `App.utils` for
 * `App.utils.fmt()`. A same-file holder the reference can see comes first, the
 * innermost; then — when the file neither imports nor binds the path's root —
 * a global one: `window.App = {…}` anywhere, or a classic script's top-level
 * `App`. Several equally near holders that all have the member are no answer.
 * `host` is the global object the call was written on (`window.App.init()`),
 * null for a bare `App.init()`. Undefined when no holder of the path exists at
 * all (so a caller can try its other strategies), null when one exists but
 * none has the member.
 */
function resolveObjectPathMember(
  path: string,
  member: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  host: string | null,
): ResolvedRef | null | undefined {
  const viaGlobal = host !== null;
  const tail = path.slice(path.lastIndexOf('.') + 1);
  const named = context.getNodesByName(tail).filter((n) =>
    (n.kind === 'constant' || n.kind === 'variable') && OBJECT_LITERAL_LANGUAGES.has(n.language) &&
    sameLanguageFamily(n.language, ref.language) && holderPath(n) === path);
  if (named.length === 0) return undefined;
  const hitOn = (holder: Node): ResolvedRef | null =>
    resolveObjectLiteralMember(holder, member, ref, context, 0.85, 'instance-method') ??
    resolveObjectLiteralBinding(holder, member, ref, context);

  const local = named
    .filter((n) => n.filePath === ref.filePath)
    .map((n) => ({ n, depth: holderScopeAt(n, ref, viaGlobal, context) }))
    .filter((e): e is { n: Node; depth: number } => e.depth !== null)
    .sort((a, b) => b.depth - a.depth);
  if (local.length > 0) {
    // The nearest holders only: an outer one is shadowed where an inner one exists.
    const nearest = local.filter((e) => e.depth === local[0]!.depth);
    for (const { n } of nearest) {
      const hit = hitOn(n);
      if (hit) return hit;
    }
    return null;
  }

  const hits = named
    .filter((n) => n.filePath !== ref.filePath && isObjectLiteralOwner(n) && isGlobalHolder(n, context))
    .map((n) => ({ n, hit: hitOn(n) }))
    .filter((e): e is { n: Node; hit: ResolvedRef } => e.hit !== null);
  if (hits.length === 0) return null;
  // A global is what the call names only where nothing nearer binds the name:
  // the file's own import of it, a parameter or local around the call — or,
  // for `window.App`, a `window` of its own. (Checked once a global holder has
  // the member: it reads the calling file.)
  const root = path.split('.')[0]!;
  if (host !== null ? bindsNameAt(host, ref, context)
    : isImportBinding(root, ref, context) || bindsNameAt(root, ref, context)) return null;
  const targets = new Set(hits.map((e) => e.hit.targetNodeId));
  if (targets.size === 1) return { ...hits[0]!.hit, confidence: 0.8 };
  // The same namespace defined twice (a page's copy and a build's): the caller's own directory decides, or nothing does.
  const dir = ref.filePath.slice(0, ref.filePath.lastIndexOf('/') + 1);
  const near = hits.filter((e) => e.n.filePath.startsWith(dir) && !e.n.filePath.slice(dir.length).includes('/'));
  return new Set(near.map((e) => e.hit.targetNodeId)).size === 1 ? { ...near[0]!.hit, confidence: 0.75 } : null;
}

/**
 * `a.b.m()` through a namespace an object literal was hung on (`App.utils =
 * {…}` then `App.utils.fmt()`, #2300). Identifier-rooted chains carry no type
 * (#1566), so nothing else may resolve them: this answers only when a holder
 * of exactly that path exists, and is null otherwise.
 */
export function matchObjectPathCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null {
  if (ref.referenceKind !== 'calls' || !JS_FAMILY.has(ref.language)) return null;
  const dot = ref.referenceName.lastIndexOf('.');
  if (dot <= 0) return null;
  let path = ref.referenceName.slice(0, dot);
  const host = HOST_GLOBAL_PREFIX.test(path) ? path.slice(0, path.indexOf('.')) : null;
  if (host !== null) path = path.slice(host.length + 1);
  if (!path.includes('.') && host === null) return null;
  return resolveObjectPathMember(path, ref.referenceName.slice(dot + 1), ref, context, host) ?? null;
}

/** `(` after optional space, at `lastIndex`. */
const OPEN_PAREN_AT = /\s*\(/y;

/** `window.App.utils` at the end of a receiver's text → host `window`, path `App.utils`. */
const HOST_GLOBAL_RECEIVER =/(?:^|[^\w$.])(window|globalThis)\s*\??\.\s*([A-Za-z_$][\w$]*(?:\s*\??\.\s*[A-Za-z_$][\w$]*)*)$/;

/**
 * A call the extractor recorded by its bare name although it was written on
 * an object (#2300): `window.App.init()` — the `window` chain keeps its bare
 * name as the project-global escape (#1707) — and `this.render()` inside an
 * object literal's member. Both name the owner of the member they call, which
 * is tried first. Undefined when the call is neither, or no such owner has the
 * member (the bare-name strategies then run as before). Null when the object
 * is one of the browser's own: a global `self.close()`, or a `window` chain
 * that starts at `localStorage`, `history` or another host object, like
 * `window.localStorage.getItem()` — no project code is that object (#2907).
 */
export function matchCollapsedObjectCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  if (ref.referenceKind !== 'calls' || !JS_FAMILY.has(ref.language) || !/^[A-Za-z_$][\w$]*$/.test(ref.referenceName)) return undefined;
  // A call written bare starts with its own name and `(`: no receiver to read.
  const line = (context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/))?.[ref.line - 1];
  if (line?.startsWith(ref.referenceName, ref.column)) {
    OPEN_PAREN_AT.lastIndex = ref.column + ref.referenceName.length;
    if (OPEN_PAREN_AT.test(line)) return undefined;
  }
  const written = bareCallReceiver(ref, context);
  if (!written) return undefined;
  if (written.receiver === 'self') {
    // The object literal `this` is — the owner of the method the call is
    // written in (an arrow member's `this` is the code around the literal's) —
    // when it has the member.
    const caller = context.getNodeById?.(ref.fromNodeId);
    const owner = caller ? thisObjectOf(caller, context) : null;
    const hit = owner ? resolveObjectLiteralMember(owner, ref.referenceName, ref, context, 0.85, 'instance-method') : null;
    return hit ?? undefined;
  }
  // A global `self` arrives as `globalThis.self` (bareCallReceiver).
  const host = HOST_GLOBAL_RECEIVER.exec(written.receiver);
  if (!host) return undefined;
  const path = host[2]!.replace(/[\s?]/g, '');
  const hit = resolveObjectPathMember(path, ref.referenceName, ref, context, host[1]!);
  if (hit) return hit;
  return JS_BROWSER_HOST_GLOBALS.has(path.split('.')[0]!) ? null : undefined;
}

/**
 * The method `methodName` a TS/JS class or interface declared in `file` gets
 * from its supertypes, found through that declaration's own extends and
 * implements edges: the member a supertype's own declaration has, each
 * supertype and then its own supertypes in the order they are written, as
 * the walk by name goes. That walk (getSupertypes) unions the supertypes of
 * every type sharing the name and looks the method up by its name again, so a
 * supertype declared in many files — vscode's `IDisposable`, in eleven — gave
 * whichever one came first, another app's included. Undefined when `file`
 * declares no such type, or none of its supertypes has the member.
 */
function esInheritedMethod(typeName: string, methodName: string, file: string, ref: UnresolvedRef, context: ResolutionContext): Node | undefined {
  const supertypeNodes = context.getSupertypeNodes;
  if (!supertypeNodes) return undefined;
  const decls = context.getNodesByName(typeName).filter((n) => n.filePath === file && (n.kind === 'class' || n.kind === 'interface'));
  const seen = new Set(decls.map((n) => n.id));
  const inherited = (decl: Node, depth: number): Node | undefined => {
    for (const base of supertypeNodes(decl.id)) {
      if (seen.has(base.id)) continue;
      seen.add(base.id);
      const members = context.getMethodMatches?.(base.name, methodName, ref.language) ??
        context.getNodesByName(methodName).filter((m) => m.kind === 'method' && m.qualifiedName.endsWith(`${base.name}::${methodName}`));
      const own = members.find((m) => m.filePath === base.filePath && m.startLine >= base.startLine && m.endLine <= base.endLine);
      if (own) return own;
      const above = depth < 3 ? inherited(base, depth + 1) : undefined;
      if (above) return above;
    }
    return undefined;
  };
  for (const decl of decls) {
    const found = inherited(decl, 0);
    if (found) return found;
  }
  return undefined;
}

/**
 * The supertypes, by name, of the TS/JS classes named `typeName`: the walk by
 * name without an interface's supertypes, which only esInheritedMethod reads,
 * from the interface's own declaration. Through any interface of the name, a
 * type from a package or a global namespace (vscode's `NodeJS.ReadableStream`)
 * reached the supertypes of the project's own `ReadableStream`, and a type
 * whose import doesn't resolve those of whichever app declares one.
 */
function esClassSupertypes(typeName: string, language: Language, context: ResolutionContext): string[] {
  if (!context.getSupertypeNodes) return context.getSupertypes?.(typeName, language) ?? [];
  const names = new Set<string>();
  for (const n of context.getNodesByName(typeName)) {
    if (n.language !== language || n.kind !== 'class') continue;
    for (const s of context.getSupertypeNodes(n.id)) {
      if (s.name && s.name !== typeName) names.add(s.name);
    }
  }
  return [...names];
}

/**
 * The supertypes of the Java / Kotlin types named `typeName` (`LegacyBuilder`,
 * or a chain, `AssistantMessage::Builder`), in the order the walk by name
 * reads them, each with the chain of types that names it, its package
 * dropped: a nested supertype (`extends AssistantMessage.Builder<T>`) is
 * looked up as `AssistantMessage::Builder` before every `Builder` in the
 * project is. Null without the edge reader.
 */
function jvmSupertypeChains(
  typeName: string,
  language: Language,
  context: ResolutionContext,
): Array<{ chain: string; name: string }> | null {
  if (!context.getSupertypeNodes) return null;
  const simple = typeName.split('::').pop()!;
  const out: Array<{ chain: string; name: string }> = [];
  const seen = new Set<string>();
  for (const n of context.getNodesByName(simple)) {
    if (n.language !== language || !JVM_DECLARED_TYPE_KINDS.has(n.kind)) continue;
    if (typeName !== simple && n.qualifiedName !== typeName && !n.qualifiedName.endsWith(`::${typeName}`)) continue;
    for (const s of context.getSupertypeNodes(n.id)) {
      if (!s.name || s.name === simple) continue;
      const segments = s.qualifiedName.split('::');
      let first = 0;
      while (first < segments.length - 1 && !/^[A-Z]/.test(segments[first]!)) first++;
      const chain = segments.slice(first).join('::');
      if (seen.has(chain)) continue;
      seen.add(chain);
      out.push({ chain, name: s.name });
    }
  }
  return out;
}

// Exported for the precedence unit tests (#1079): they assert the
// preferredFqn → same-file → matches[0] ordering directly.
export function resolveMethodOnType(
  typeName: string,
  methodName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  confidence: number,
  resolvedBy: ResolvedRef['resolvedBy'],
  /**
   * Optional FQN that identifies WHICH class declaration `typeName`
   * refers to in the caller's file. When multiple candidates share
   * the same qualifiedName (`FooConverter::convert` in both
   * `dao/converter/` and `service/converter/`), the FQN's
   * file-path-suffix picks the right one — the disambiguation
   * signal Java imports carry but the call site doesn't (#314).
   * For Go it is the project-relative directory of the package that
   * declares `typeName`, when that is known (resolveGoMethodInPackage).
   * For TS/JS it is the file declaring the class the caller's file
   * imports under that name (tsImportedTypeFile), or, for a type written
   * in another file (an imported value's), the class that file imports or
   * declares.
   */
  preferredFqn?: string,
  /** Recursion guard for the supertype/conformance walk. */
  depth = 0,
): ResolvedRef | null {
  // Look up methods by name and match by qualifiedName ending in
  // `<typeName>::<methodName>`. This works whether the method is defined
  // in-class (`class Foo { int bar() { ... } }`) or out-of-line in a separate
  // file (`int Foo::bar() { ... }` in foo.cpp while class Foo is in foo.hpp).
  // The previous same-file approach missed the latter — the typical C++ layout.
  // Prefer the context's per-(type, method) memo: the raw name lookup fetches
  // EVERY node sharing the method name — tens of thousands of rows for a
  // collision-heavy Java name like `execute` — and re-filtering that per ref
  // was a dominant term in the #1122 watchdog kill on large repos. Only the
  // ref-independent filter is memoized; per-ref disambiguation stays below.
  let matches: Node[];
  if (context.getMethodMatches) {
    matches = context.getMethodMatches(typeName, methodName, ref.language);
  } else {
    const methodCandidates = context.getNodesByName(methodName);
    const want = `${typeName}::${methodName}`;
    matches = [];
    for (const m of methodCandidates) {
      if (m.kind !== 'method') continue;
      if (!sameLanguageFamily(m.language, ref.language)) continue;
      const qn = m.qualifiedName;
      if (qn === want || qn.endsWith(`::${want}`)) {
        matches.push(m);
      }
    }
  }
  if (ref.language === 'go' && preferredFqn !== undefined) {
    const scoped = resolveGoMethodInPackage(typeName, methodName, preferredFqn, matches, ref, context, confidence, resolvedBy, depth);
    if (scoped !== undefined) return scoped;
  }
  // A Kotlin extension, `fun Modes.hidden()` (indexed as `Modes::hidden`), is
  // a top-level declaration: from another package, only an import of it or of
  // its package puts it in scope. A member of the type is always reachable.
  if (ref.language === 'kotlin' && matches.some((m) => !isKotlinExtensionInScope(m, ref, context))) {
    matches = matches.filter((m) => isKotlinExtensionInScope(m, ref, context));
  }
  if (matches.length === 0) {
    // Conformance fallback: the method may be defined on a supertype `typeName`
    // extends, or on a protocol / trait it conforms to (e.g. a Swift protocol-
    // extension method, a C# default-interface or extension method, a Kotlin
    // extension on a supertype). Walk supertypes transitively (depth-capped) via
    // the resolved implements/extends edges — empty in the first resolution pass,
    // populated in the conformance pass. Still VALIDATED (the method must exist on
    // a supertype), so a wrong inference produces no edge.
    if (depth < 4 && context.getSupertypes) {
      const viaSupers = nmTimedT('rmot-supers', ref, (): ResolvedRef | null => {
        // A TS/JS type whose declaration is known — the file it is imported
        // from, or else the call's own — takes the member its own supertypes
        // declare before any type of the same name elsewhere is asked.
        const es = ES_IMPORT_LANGUAGES.has(ref.language);
        if (depth === 0 && es) {
          const inherited = esInheritedMethod(typeName, methodName, preferredFqn ?? ref.filePath, ref, context);
          if (inherited) return { original: ref, targetNodeId: inherited.id, confidence, resolvedBy };
        }
        // A Java / Kotlin supertype is asked by the chain that names it first
        // (`AssistantMessage::Builder`, not every `Builder`), then — when the
        // edge reached a namesake, Minestom's `Player extends LivingEntity` to a
        // nested `EntityStatuses.LivingEntity` — by its name, as before.
        const jvm = !es && (ref.language === 'java' || ref.language === 'kotlin')
          ? jvmSupertypeChains(typeName, ref.language, context) : null;
        if (jvm) {
          const tried = new Set<string>();
          for (const { chain, name } of jvm) {
            for (const t of chain === name ? [chain] : [chain, name]) {
              if (tried.has(t)) continue;
              tried.add(t);
              const via = resolveMethodOnType(t, methodName, ref, context, confidence, resolvedBy, preferredFqn, depth + 1);
              if (via) return via;
            }
          }
          return null;
        }
        const supertypes = es ? esClassSupertypes(typeName, ref.language, context) : context.getSupertypes!(typeName, ref.language);
        for (const supertype of supertypes) {
          const via = resolveMethodOnType(
            supertype, methodName, ref, context, confidence, resolvedBy, preferredFqn, depth + 1,
          );
          if (via) return via;
        }
        return null;
      });
      if (viaSupers) return viaSupers;
    }
    // A Dart extension's member: no declaration of the type has it, so an
    // extension `on` the type (or a supertype) supplies it — `s.shout()` on an
    // enum through `extension ShapeInfo on Shape` (#2338).
    if (ref.language === 'dart' && depth === 0) {
      const viaExtension = dartExtensionMemberOf(typeName, methodName, ref, context);
      if (viaExtension) return { original: ref, targetNodeId: viaExtension.id, confidence, resolvedBy };
    }
    return null;
  }

  // Rust picks a type's inherent method before a trait's of the same name —
  // where one type has the name: two types of it each keep their own.
  if (ref.language === 'rust' && matches.length > 1) {
    const inherent = matches.filter((m) => !isRustTraitImplMethod(m, context));
    if (inherent.length > 0 && inherent.length < matches.length &&
        context.getNodesByName(typeName).filter((n) => n.language === 'rust' && RUST_DECLARED_TYPE_KINDS.has(n.kind)).length <= 1) {
      matches = inherent;
    }
  }

  if (matches.length > 1 && preferredFqn && ES_IMPORT_LANGUAGES.has(ref.language)) {
    const chosen = matches.find((m) => m.filePath === preferredFqn);
    if (chosen) return { original: ref, targetNodeId: chosen.id, confidence, resolvedBy };
  }
  if (matches.length > 1 && preferredFqn && ref.language !== 'go' && !ES_IMPORT_LANGUAGES.has(ref.language)) {
    // Prefer the candidate whose namespace-qualified name matches the imported
    // FQN. #412 indexes JVM declarations as `<pkg>::<Class>` from the file's
    // `package` directive — independent of the file name — so this disambiguates
    // Kotlin (where `FooConverter` can live in `Converters.kt`) that the
    // file-path-suffix heuristic below can't. `com.example.b.FooConverter`
    // → expected method qn `com.example.b::FooConverter::convert`.
    const lastDot = preferredFqn.lastIndexOf('.');
    if (lastDot > 0) {
      const expectedQn = `${preferredFqn.slice(0, lastDot)}::${preferredFqn.slice(lastDot + 1)}::${methodName}`;
      const byQn = matches.find((m) => m.qualifiedName === expectedQn);
      if (byQn) {
        return { original: ref, targetNodeId: byQn.id, confidence, resolvedBy };
      }
    }
    // Fall back to file-path-suffix match for Java's class-name = file-name
    // layout (covers files indexed before the namespace wrapper, or any case
    // the qn match misses).
    const ext = ref.language === 'kotlin' ? '.kt' : '.java';
    const fqnPath = preferredFqn.replace(/\./g, '/') + ext;
    const chosen = matches.find((m) => {
      const fp = m.filePath.replace(/\\/g, '/');
      return fp.endsWith(fqnPath) || fp.endsWith('/' + fqnPath);
    });
    if (chosen) {
      return {
        original: ref,
        targetNodeId: chosen.id,
        confidence,
        resolvedBy,
      };
    }
  }

  // Language-agnostic disambiguation: when several same-named methods survive
  // (e.g. two files each declaring `class Logger { void log(); }` — an ODR
  // clash, an anonymous-namespace type, or separate translation units), prefer
  // the definition in the CALL SITE's own file. Without this, every ambiguous
  // call collapses onto the first-indexed definition, so a call in `b/svc.cpp`
  // wrongly points at `a/svc.cpp` (#1079). This runs AFTER the `preferredFqn`
  // blocks, so Java/Kotlin and TS/JS import disambiguation — whose target is
  // intentionally in ANOTHER file (#314) — is unaffected: those blocks return
  // early whenever an import pins the class.
  if (ref.referenceKind === 'function_ref' && matches.length !== 1) return null;
  // Java: a same-named type in another JVM language (Scala's `play.api.data.Form`
  // beside Java's `play.data.Form`) is the weaker candidate when no import
  // pins one — a wildcard `import play.data.*` or the same package names none.
  const sameLanguage = ref.language === 'java' ? matches.filter((m) => m.language === 'java') : [];
  const ordered = rubyMethodsOfKindFirst(
    preferCallSiteFile(withinCppTranslationUnit(cppVisibleFirst(sameLanguage.length > 0 ? sameLanguage : matches, ref, context), ref, context), ref.filePath),
    ref.language === 'ruby' ? 'instance' : undefined);
  return {
    original: ref,
    targetNodeId: ordered[0]!.id,
    confidence,
    resolvedBy,
  };
}

// C++ keywords/control-flow tokens that can appear right before a receiver
// (e.g. `return ptr->m()`) and must NOT be treated as a type.
const CPP_NON_TYPE_TOKENS = new Set([
  'return', 'if', 'else', 'for', 'while', 'do', 'switch', 'case', 'default',
  'break', 'continue', 'goto', 'throw', 'new', 'delete', 'co_await', 'co_yield',
  'co_return', 'static_cast', 'const_cast', 'dynamic_cast', 'reinterpret_cast',
  'sizeof', 'alignof', 'typeid', 'and', 'or', 'not', 'xor',
]);

/**
 * Does a `>` in a declared C++ type close no `<`? Then the type began on an
 * earlier line — rocksdb's `std::unique_ptr<BlobContents>>>& blob_reqs` under
 * `autovector<std::pair<BlobRangeReadRequest*,` — or the text is an
 * expression (`i < a->b->c`).
 */
function cppTypeBeganAbove(typeName: string): boolean {
  let depth = 0;
  for (const c of typeName) {
    if (c === '<') depth++;
    else if (c === '>' && --depth < 0) return true;
  }
  return false;
}

/**
 * Does `line` end a declaration of the receiver begun on an earlier line, a
 * templated type whose `>`s outnumber its `<`s before the name: rocksdb's
 * `std::unique_ptr<BlobContents>>>& blob_reqs` under `autovector<std::pair<
 * BlobReadRequest*,`? The declarator reads no type there, since its template
 * arguments pair their brackets. (`this->blob_reqs` and `in >> blob_reqs`
 * declare nothing.)
 */
function cppEndsDeclarationBegunAbove(line: string, escapedReceiver: string): boolean {
  const end = new RegExp(String.raw`(?:^|[^\w:])([A-Za-z_][\w:]*\s*<[^;=(){}]+>)(?:\s*(?:const\b|volatile\b|[*&]+))*\s*${escapedReceiver}\b`).exec(line);
  return end !== null && cppTypeBeganAbove(end[1]!);
}

/**
 * The type a declaration of the receiver on the code `line` (lines[index])
 * declares when its type is written on lines above, read with them:
 * - the end of a type begun above, its text before the name closing a `<`
 *   an earlier line opened — protobuf's `const
 *   google::protobuf::internal::ExtensionIdentifier<` above `FeatureSet,
 *   TypeTraitsT, field_type, is_packed>& extension) const {`. Lines are
 *   joined, up to six, until the brackets pair;
 * - a type alone on the line above, the name starting this one — rocksdb's
 *   `std::unordered_map<std::string, std::shared_ptr<const TableProperties>>`
 *   above `props;`, as cppDataMemberIn reads a member.
 * Null when the line needs no line above, or the lines read together declare
 * no type there.
 */
function cppDeclarationBegunAbove(
  lines: readonly string[],
  index: number,
  line: string,
  receiverPattern: RegExp,
  declaratorRegex: RegExp,
  rawLines: ReturnType<typeof cppNonCodeLines>,
): string | null {
  const at = line.search(receiverPattern);
  if (at < 0 || index === 0) return null;
  const codeAt = (j: number): string => cppCodeOf(cppLiteralsBlanked(lines[j]!, j + 1, rawLines)) ?? '';
  const head = line.slice(0, at);
  if (/^\s*[*&]*\s*$/.test(head)) {
    const above = codeAt(index - 1);
    return CPP_TYPE_LINE.test(above) ? matchCppDeclarator(`${above} ${line}`, declaratorRegex)?.[1] ?? null : null;
  }
  // (Only such a line can need the lines above: every other line naming the
  // receiver is spared joining them.)
  if (!cppTypeBeganAbove(head)) return null;
  let text = line;
  let before = head;
  for (let j = index - 1; j >= Math.max(0, index - 6); j--) {
    const above = codeAt(j);
    text = `${above} ${text}`;
    before = `${above} ${before}`;
    if (!cppTypeBeganAbove(before)) return matchCppDeclarator(text, declaratorRegex)?.[1] ?? null;
  }
  return null;
}

/**
 * The last name of a declared C++ type: `const std::vector<std::pair<int,
 * Foo>>&` → `vector`, `ns::Table<int, Box<int>>` → `Table`. Null when the text
 * names no type.
 */
function normalizeCppTypeName(typeName: string): string | null {
  // Without its head, what is left of a type begun above names a template
  // argument's type, not the declared one.
  if (cppTypeBeganAbove(typeName)) return null;
  // Template arguments go with the ones nested in them. Cut at their first
  // `>`, `Table<int, Box<int>>` was `Table >`, which names no type: a call
  // on it never reached Table's method, and a capitalized name no class has
  // ruled out any guess as well.
  const normalized = stripCppTemplateArguments(
    typeName
      .replace(/\b(const|volatile|mutable|typename|class|struct)\b/g, ' ')
      .replace(/[&*]+/g, ' '),
  )
    .replace(/\s+/g, ' ')
    .trim();

  if (!normalized) return null;
  const parts = normalized.split(/::/).filter(Boolean);
  const last = parts[parts.length - 1];
  if (!last) return null;
  if (CPP_NON_TYPE_TOKENS.has(last)) return null;
  return last;
}

/** cv-qualifiers and `__restrict`, before or after a declarator's `*` or `&`: `Iterator* const iter`, `Slice const& key`. */
const CPP_DECLARATOR_CV = String.raw`\b(?:const|volatile|__restrict__|__restrict)\b`;
/**
 * What a pointer or reference declarator may carry after its `*` or `&`:
 * clang's and abseil's nullability annotations (CPP_NULLABILITY), and the
 * ALL-CAPS macros c-cpp.ts blanks for the parser — protobuf's `Arena*
 * PROTOBUF_NULLABLE arena`, xxhash's `XXH_RESTRICT`.
 */
const CPP_DECLARATOR_ANNOTATION = String.raw`\b(?:absl_nonnull|absl_nullable|absl_nullability_unknown|_Nonnull|_Nullable|_Null_unspecified|[A-Z][A-Z0-9]*_[A-Z0-9_]*)\b`;
/**
 * A function wrapper's type, whose template argument is a function type:
 * rocksdb's `std::function<Iterator*()> create_iterator`.
 */
const CPP_FUNCTION_WRAPPER_TYPE = String.raw`(?:::\s*)?(?:std\s*::\s*(?:function|move_only_function|copyable_function)|absl\s*::\s*(?:FunctionRef|AnyInvocable))\s*<[^;={}]*>`;
/**
 * A template argument list, nested up to three deep: `<std::string,
 * std::vector<std::pair<int, int>>>`. Its `<`s and `>`s pair up, so on a line
 * declaring `const std::vector<A*>& a, const std::vector<B>& b` the list
 * read for `b` is `<B>`: matching any run up to a `>` read `a`'s parameter
 * into `b`'s type.
 */
const CPP_TEMPLATE_ARGUMENTS = String.raw`<(?:[^<>;=(){}]|<(?:[^<>;=(){}]|<[^<>;=(){}]*>)*>)*>`;
/**
 * A declared type as the declarator regex reads it, what it carries included:
 * `const FieldDescriptor* PROTOBUF_NULLABLE*`, a leading `::` that names the
 * global scope (`::upb::Arena arena`), which C++ lookup starts from, and the
 * class template a member type is written in: `SkipList<Key,
 * Comparator>::Iterator iter` is SkipList's `Iterator`, which read from its
 * `Iterator` alone was the namespace's own. (A `::` after a name, a
 * template's arguments or a `)` is no leading `::`.)
 */
const CPP_DECLARATOR_TYPE = String.raw`(?:${CPP_FUNCTION_WRAPPER_TYPE}|(?:(?<![\w>):])::\s*)?[A-Za-z_][\w:]*(?:\s*${CPP_TEMPLATE_ARGUMENTS}(?:\s*::\s*[A-Za-z_][\w:]*)?)?)(?:\s*(?:${CPP_DECLARATOR_CV}|[*&]+(?:\s*${CPP_DECLARATOR_ANNOTATION})*))*`;
/** A line that is a declared type and nothing else, what may come before a type included: `const std::map<int, Foo*>&`. */
const CPP_TYPE_LINE = new RegExp(String.raw`^\s*(?:(?:const|volatile|static|mutable|constexpr|inline)\s+)*${CPP_DECLARATOR_TYPE}\s*$`);
/** An annotation macro's call after a declared name: leveldb's `VersionSet* const versions_ GUARDED_BY(mutex_);`. */
const CPP_TRAILING_ANNOTATION = String.raw`\b[A-Z][A-Z0-9]*_[A-Z0-9_]*\s*\([^()]*\)`;

// Declarator regex: matches `Type receiver`, `Type* receiver`, `Type *receiver`,
// `Type*receiver`, `Type<X> receiver`, etc., REQUIRING a declarator terminator
// (`;`, `=`, `,`, `)`, `[`, `{`, `(`, or end-of-line) after the receiver. The
// terminator rules out uses like `return receiver->m()` where the preceding
// token is a keyword, not a type. A range-based for's `Type receiver :` is read
// by cppRangeForDeclaration instead. Qualifiers and annotations around the
// name are read past, and matchCppDeclarator drops the annotations from the
// type.
function buildDeclaratorRegex(escapedReceiver: string): RegExp {
  return new RegExp(
    `(${CPP_DECLARATOR_TYPE})\\s*\\b${escapedReceiver}\\b(?:\\s*${CPP_TRAILING_ANNOTATION})*\\s*(?=[;=,)\\[{(]|$)`,
  );
}

/** buildDeclaratorRegex's `regex` run on the code `line`, with its type as cppDeclaratorType gives it. */
function matchCppDeclarator(line: string, regex: RegExp): RegExpExecArray | null {
  const m = regex.exec(line);
  if (m?.[1] !== undefined) m[1] = cppDeclaratorType(m[1]);
  return m;
}

/** matchCppDeclarator's first match in `line` from `from` on. */
function matchCppDeclaratorFrom(line: string, regex: RegExp, from: number): RegExpExecArray | null {
  const global = new RegExp(regex.source, 'g');
  global.lastIndex = from;
  const m = global.exec(line);
  if (m?.[1] !== undefined) m[1] = cppDeclaratorType(m[1]);
  return m;
}

const CPP_DECLARATOR_ANNOTATION_WORD = new RegExp(`^${CPP_DECLARATOR_ANNOTATION}$`);
const CPP_WORD_AT = /[A-Za-z_]\w*/y;

/**
 * A type the declarator regex read, without the annotations it reads past
 * after a `*` or `&`, outside template arguments: `Arena*
 * PROTOBUF_NULLABLE` → `Arena*`. Taken as part of the type, one read as its
 * name, of a class no project has. An ALL-CAPS word stands for an annotation
 * only there, so a type's own name stays (`OS_HANDLE* const h`), and so do
 * its cv-qualifiers, which what reads a type reads past. A type with nothing
 * to drop comes back as it is.
 */
function cppDeclaratorType(text: string): string {
  let out = '';
  let depth = 0;
  let afterPointer = false;
  let dropped = false;
  for (let i = 0; i < text.length; ) {
    CPP_WORD_AT.lastIndex = i;
    const word = depth === 0 && !/[\w:]/.test(text[i - 1] ?? ' ') ? CPP_WORD_AT.exec(text)?.[0] : undefined;
    if (word) {
      if (afterPointer && CPP_DECLARATOR_ANNOTATION_WORD.test(word)) {
        dropped = true;
      } else {
        out += word;
        afterPointer = false;
      }
      i += word.length;
      continue;
    }
    const c = text[i]!;
    if (c === '<') depth++;
    else if (c === '>') depth--;
    else if (depth === 0 && (c === '*' || c === '&')) afterPointer = true;
    else if (depth === 0 && !/\s/.test(c)) afterPointer = false;
    out += c;
    i++;
  }
  return dropped ? out.replace(/\s+/g, ' ').trim() : text;
}

// The receiver after a comma, as a name later in a declaration's list is:
// `ByteBuffer symbols_found, strings_found;`, `Foo *a, *const b;`. The
// declarator regex wants the type right before the name, and a list writes
// it once, before the first name; matchCppListedDeclarator reads the others.
function buildListedDeclaratorRegex(escapedReceiver: string): RegExp {
  return new RegExp(String.raw`,(?:\s|[*&]|${CPP_DECLARATOR_CV}|${CPP_DECLARATOR_ANNOTATION})*\b${escapedReceiver}\b`);
}

// Words a C++ declaration may open with before its type.
const CPP_DECL_SPECIFIERS: ReadonlySet<string> = new Set([
  'static', 'extern', 'inline', 'constexpr', 'constinit', 'thread_local', 'register', 'mutable',
  'const', 'volatile', 'typename', 'struct', 'class', 'union', 'enum',
]);

// Words that never are the type a declaration of variables opens with.
const CPP_NOT_A_DECLARED_TYPE: ReadonlySet<string> = new Set([
  ...CPP_NON_TYPE_TOKENS, 'typedef', 'using', 'namespace', 'template', 'friend', 'operator',
  'public', 'private', 'protected', 'virtual', 'explicit', 'static_assert', 'asm', 'try', 'catch',
  'this', 'true', 'false', 'nullptr',
]);

// Nor a declared variable's name: those, the specifiers and the built-in
// types. `const Message& message, int, int)` ends a parameter list.
const CPP_NOT_A_DECLARED_NAME: ReadonlySet<string> = new Set([
  ...CPP_NOT_A_DECLARED_TYPE, ...CPP_DECL_SPECIFIERS, 'auto', 'void', 'bool', 'char', 'wchar_t',
  'char8_t', 'char16_t', 'char32_t', 'short', 'int', 'long', 'signed', 'unsigned', 'float', 'double',
]);

const CPP_DECLARATOR_CV_WORD = new RegExp(`^${CPP_DECLARATOR_CV}$`);
const CPP_TRAILING_ANNOTATION_AT = new RegExp(CPP_TRAILING_ANNOTATION, 'y');

/** The identifier at `code[i]`, or null. */
function cppWordAt(code: string, i: number): string | null {
  CPP_WORD_AT.lastIndex = i;
  return CPP_WORD_AT.exec(code)?.[0] ?? null;
}

/** Past the whitespace at `code[i]`. */
function cppSkipSpace(code: string, i: number): number {
  while (i < code.length && /\s/.test(code[i]!)) i++;
  return i;
}

/** The word that ends where the spaces before `code[i]` begin (`for` before `for (`). */
function cppWordBefore(code: string, i: number): string {
  let end = i;
  while (end > 0 && /\s/.test(code[end - 1]!)) end--;
  let start = end;
  while (start > 0 && /\w/.test(code[start - 1]!)) start--;
  return code.slice(start, end);
}

/** Does a string or character literal open at `code[i]`? (A `'` after a digit separates digits: `1'000'000`.) */
function cppOpensLiteral(code: string, i: number): boolean {
  return code[i] === '"' || (code[i] === '\'' && !/\d/.test(code[i - 1] ?? ''));
}

/**
 * Past the bracket that closes the `(`, `[` or `{` at `code[i]`, over what
 * is nested or quoted inside: the line's length when the line ends first,
 * -1 when a bracket closes out of turn.
 */
function cppPastBrackets(code: string, i: number): number {
  const closers: string[] = [];
  for (; i < code.length; i++) {
    const c = code[i]!;
    if (c === '(') closers.push(')');
    else if (c === '[') closers.push(']');
    else if (c === '{') closers.push('}');
    else if (c === ')' || c === ']' || c === '}') {
      if (closers.pop() !== c) return -1;
      if (closers.length === 0) return i + 1;
    } else if (cppOpensLiteral(code, i)) i = cppLiteralEnd(code, i);
  }
  return code.length;
}

/**
 * Where the initializer starting at `code[i]` ends: at the first `,`, `;`
 * or closing bracket outside its own brackets, or the line's end; -1 when
 * its brackets don't match. A `<` is not taken for a bracket — it may be
 * `a < b` — so a comma in template arguments (`f<A, B>(x)`) ends it, and
 * what follows then reads as no declarator.
 */
function cppPastInitializer(code: string, i: number): number {
  while (i < code.length) {
    const c = code[i]!;
    if (c === ',' || c === ';' || c === ')' || c === ']' || c === '}') return i;
    if (c === '(' || c === '[' || c === '{') {
      i = cppPastBrackets(code, i);
      if (i < 0) return -1;
    } else if (cppOpensLiteral(code, i)) i = cppLiteralEnd(code, i) + 1;
    else i++;
  }
  return i;
}

/** Past the template argument list opening at `code[i]` (`<`), or -1 when it doesn't close on the line. */
function cppPastTemplateArguments(code: string, i: number): number {
  let angles = 0;
  let parens = 0;
  for (; i < code.length; i++) {
    const c = code[i]!;
    if (c === '(') parens++;
    else if (c === ')') {
      if (--parens < 0) return -1;
    } else if (parens > 0) continue;
    else if (c === '<') angles++;
    else if (c === '>') {
      if (--angles === 0) return i + 1;
    } else if (c === ';' || c === '{' || c === '}') return -1;
  }
  return -1;
}

/** Past the type a C++ declaration opens with at `code[i]` — `ns::Table<int, Box<int>>`, `::Foo` — or -1. */
function cppPastDeclaredType(code: string, i: number): number {
  if (code.startsWith('::', i)) i = cppSkipSpace(code, i + 2);
  for (let segment = 0; ; segment++) {
    let word = cppWordAt(code, i);
    // `typename Traits<T>::template Rebind<U>`
    if (word === 'template' && segment > 0) {
      i = cppSkipSpace(code, i + word.length);
      word = cppWordAt(code, i);
    }
    if (word === null || CPP_NOT_A_DECLARED_TYPE.has(word)) return -1;
    i += word.length;
    let next = cppSkipSpace(code, i);
    if (code[next] === '<') {
      i = cppPastTemplateArguments(code, next);
      if (i < 0) return -1;
      next = cppSkipSpace(code, i);
    }
    if (!code.startsWith('::', next)) return i;
    i = cppSkipSpace(code, next + 2);
  }
}

/** A name a C++ declaration lists after its first, as cppDeclaratorsAfterFirst reads it. */
interface CppListedName {
  name: string;
  /** The type the declaration opens with plus this name's own `*`s and `&`s. */
  type: string;
  /** Where the declaration's type starts. */
  typeAt: number;
  /** Where the name ends, an annotation after it (`GUARDED_BY(mu_)`) included. */
  end: number;
}

/**
 * The names after the first that the C++ declaration starting at
 * `code[start]` lists, or null when no declaration starts there. In a `for`,
 * `if` or `switch` header a `)` may end it; one that runs on past the line
 * ends with it. A declarator's `*`s and `&`s are its own, and so are the
 * cv-qualifiers and annotations the declarator regex reads past: `Arena*
 * PROTOBUF_NULLABLE a, * PROTOBUF_NULLABLE b`.
 */
function cppDeclaratorsAfterFirst(code: string, start: number, inHeader: boolean): CppListedName[] | null {
  let i = cppSkipSpace(code, start);
  for (let word = cppWordAt(code, i); word !== null && CPP_DECL_SPECIFIERS.has(word); word = cppWordAt(code, i)) {
    i = cppSkipSpace(code, i + word.length);
  }
  const typeAt = i;
  i = cppPastDeclaredType(code, i);
  if (i < 0) return null;
  const type = code.slice(typeAt, i);
  const listed: CppListedName[] = [];
  for (let first = true; ; first = false) {
    let pointer = '';
    for (i = cppSkipSpace(code, i); ; i = cppSkipSpace(code, i)) {
      const c = code[i];
      if (c === '*' || c === '&') {
        pointer += c;
        i++;
        continue;
      }
      const word = cppWordAt(code, i);
      if (word === null) break;
      // An annotation word after a `*` or `&` is one only when the name still follows it.
      const after = cppSkipSpace(code, i + word.length);
      if (!CPP_DECLARATOR_CV_WORD.test(word) &&
          !(pointer && CPP_DECLARATOR_ANNOTATION_WORD.test(word) && (/[*&]/.test(code[after] ?? '') || cppWordAt(code, after) !== null))) break;
      i += word.length;
    }
    // `Foo a,` with the rest of the list on the next line.
    if (i >= code.length && !first && !pointer) return listed;
    const name = cppWordAt(code, i);
    if (name === null || CPP_NOT_A_DECLARED_NAME.has(name)) return null;
    i = cppSkipSpace(code, i + name.length);
    // `Foo Bar::baz` defines a member of Bar.
    if (code.startsWith('::', i)) return null;
    for (CPP_TRAILING_ANNOTATION_AT.lastIndex = i; CPP_TRAILING_ANNOTATION_AT.exec(code); CPP_TRAILING_ANNOTATION_AT.lastIndex = i) {
      i = cppSkipSpace(code, CPP_TRAILING_ANNOTATION_AT.lastIndex);
    }
    if (!first) listed.push({ name, type: type + pointer, typeAt, end: i });
    while (code[i] === '[') {
      i = cppPastBrackets(code, i);
      if (i < 0) return null;
      i = cppSkipSpace(code, i);
    }
    if (code[i] === '(' || code[i] === '{') i = cppPastBrackets(code, i);
    else if (code[i] === '=' && code[i + 1] !== '=') i = cppPastInitializer(code, i + 1);
    if (i < 0) return null;
    i = cppSkipSpace(code, i);
    if (i >= code.length || code[i] === ';' || (inHeader && code[i] === ')')) return listed;
    if (code[i] !== ',') return null;
    i++;
  }
}

/**
 * The declaration of `receiverName` on the code `line` when the name follows
 * another in the declaration's list — `ByteBuffer symbols_found,
 * strings_found;`, `Foo* a = nullptr, *b;`, `Bar a{1}, b(2);` — shaped like
 * matchCppDeclarator's match: the declaration's type from `index`, through
 * the name at [0], and at [1] the type as the declarator regex reads one,
 * this name's own `*`s and `&`s on the type the declaration opens with, since
 * `Foo *a, b;` declares one pointer. A comma in template arguments
 * (`std::map<K, V> m;`), in a call's or a constructor's arguments (`Writer
 * w(log, table, 3);`, `: a_(x), b_(y)`) or in an expression (`x = f(a, b);`)
 * lists no name. A declaration opens the line, follows a statement or a
 * brace, or opens a `for`, `if` or `switch` header.
 */
function matchCppListedDeclarator(line: string, receiverName: string, listedRegex: RegExp): RegExpExecArray | null {
  return listedRegex.test(line) ? cppListedDeclaratorOn(line, receiverName) : null;
}

/** matchCppListedDeclarator without its prefilter, for a line already known to name the receiver after a comma. */
function cppListedDeclaratorOn(line: string, receiverName: string): RegExpExecArray | null {
  for (let i = -1; i < line.length; i++) {
    const c = line[i];
    const header = c === '(' && /^(?:for|if|switch)$/.test(cppWordBefore(line, i));
    if (i >= 0 && c !== ';' && c !== '{' && c !== '}' && !header) continue;
    const named = cppDeclaratorsAfterFirst(line, i + 1, header)?.find((d) => d.name === receiverName);
    if (named) {
      return Object.assign([line.slice(named.typeAt, named.end), named.type], { index: named.typeAt, input: line }) as RegExpExecArray;
    }
  }
  return null;
}

// A range-based for's declaration, `for (const Foo& name :`, up to the single
// colon (not `::`) that ends it. What may precede the type — `const`, a
// global-scope `::` — is never an initializer, a call or a member access.
const CPP_RANGE_FOR_DECLARATION = /\bfor\s*\(([^;=(){}?."']*?)\b([A-Za-z_]\w*)\s*:(?!:)/g;
// The type a declaration ends with, read as the declarator regex reads it.
const CPP_DECLARED_TYPE_TAIL = new RegExp(String.raw`(${CPP_DECLARATOR_TYPE})\s*$`);

/**
 * The type the range-based for on `line` (comments blanked) declares
 * `receiverName` with — `for (ConformanceTestSuite *suite : suites)` — and
 * the column of the header's `(`. The declarator regex never reads one: a
 * loop's name is followed by its `:`. (Neither is a bit-field, `unsigned car
 * : 1;`, which no method is called on.)
 */
function cppRangeForDeclaration(line: string, receiverName: string): { type: string; paren: number; colon: number } | null {
  if (!line.includes('for')) return null;
  for (const m of line.matchAll(CPP_RANGE_FOR_DECLARATION)) {
    if (m[2] !== receiverName) continue;
    const tail = m[1]!.match(CPP_DECLARED_TYPE_TAIL);
    return tail ? { type: cppDeclaratorType(tail[1]!), paren: m.index! + m[0].indexOf('('), colon: m.index! + m[0].length } : null;
  }
  return null;
}

/**
 * The range a range-based for iterates, as written — `*versions_->
 * GetColumnFamilySet()` — from the declaration's `:` at `lines[line][column]`
 * to the header's closing `)`, comments dropped. Null when the header runs
 * on past a few lines or holds a literal.
 */
function cppRangeExpression(lines: readonly string[], line: number, column: number): string | null {
  let depth = 1;
  let text = '';
  for (let l = line; l < Math.min(lines.length, line + 4); l++) {
    const code = lines[l]!.replace(/\/\*.*?\*\//g, ' ').replace(/\/\/.*$/, '');
    for (let c = l === line ? column : 0; c < code.length; c++) {
      const ch = code[c]!;
      if (ch === '"' || ch === '\'') return null;
      if (ch === '(') depth++;
      else if (ch === ')' && --depth === 0) return text.trim() || null;
      text += ch;
    }
    text += ' ';
  }
  return null;
}

/**
 * A C++ type as written (`const autovector<ColumnFamilyData*>&`), with where
 * it is written, which is where the names in it are looked up from (see
 * cppClassWritten): the scope, the file and line, and the template
 * parameters in scope there.
 */
interface CppWrittenType {
  text: string;
  scope: string;
  file: string;
  line: number;
  parameters: ReadonlySet<string>;
  /**
   * The array dimensions a declarator gives a variable of `text`, which the
   * type doesn't show: `Status statuses[3]` is a `Status` with one.
   */
  array?: number;
}

/**
 * The standard library's and abseil's containers whose elements are their
 * first template argument. A map's elements are key and value pairs, whose
 * `first` and `second` are no receiver of a call this resolves.
 */
const CPP_LIBRARY_SEQUENCES: ReadonlySet<string> = new Set([
  'vector', 'list', 'forward_list', 'deque', 'set', 'multiset', 'unordered_set', 'unordered_multiset', 'array', 'span',
  'initializer_list', 'Span', 'InlinedVector', 'FixedArray', 'flat_hash_set', 'node_hash_set', 'btree_set',
  'btree_multiset',
]);
/** Widely used project containers of the same kind: protobuf's repeated fields, rocksdb's `autovector`. */
const CPP_PROJECT_SEQUENCES: ReadonlySet<string> = new Set(['RepeatedField', 'RepeatedPtrField', 'autovector']);
/** The standard library's and abseil's maps, whose elements are `std::pair`s of a key and a value. */
const CPP_LIBRARY_MAPS: ReadonlySet<string> = new Set([
  'map', 'multimap', 'unordered_map', 'unordered_multimap', 'flat_hash_map', 'node_hash_map', 'btree_map', 'btree_multimap',
]);

/** Clang's and abseil's nullability annotations: `const FieldDescriptor* absl_nonnull`. */
const CPP_NULLABILITY = /\b(?:absl_nonnull|absl_nullable|absl_nullability_unknown|_Nonnull|_Nullable|_Null_unspecified)\b/g;

/** A written type without its nullability annotations, which are no part of its name. */
function cppWithoutNullability(text: string): string {
  return text.replace(CPP_NULLABILITY, ' ').replace(/\s+/g, ' ').trim();
}

/** Is `n` a C or C++ function or method? */
function isCppFunctionNode(n: Node): boolean {
  return (n.kind === 'method' || n.kind === 'function') && (n.language === 'cpp' || n.language === 'c');
}

/** Where the `(` that the `)` at `text[close]` closes opens, or -1. */
function cppOpeningParen(text: string, close: number): number {
  let depth = 0;
  for (let i = close; i >= 0; i--) {
    if (text[i] === ')') depth++;
    else if (text[i] === '(' && --depth === 0) return i;
  }
  return -1;
}

/** Where the `[` that the `]` at `text[close]` closes opens, or -1. */
function cppOpeningBracket(text: string, close: number): number {
  let depth = 0;
  for (let i = close; i >= 0; i--) {
    if (text[i] === ']') depth++;
    else if (text[i] === '[' && --depth === 0) return i;
  }
  return -1;
}

/** Where the `]` that closes the `[` at `text[open]` is, or -1. */
function cppClosingBracket(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '[') depth++;
    else if (text[i] === ']' && --depth === 0) return i;
  }
  return -1;
}

/**
 * How many array dimensions the C++ declarator that the code `rest` follows
 * declares: one for the `[kNumShards];` after `LRUCache shard_`. (Not an
 * attribute's `[[…]]`.)
 */
function cppArrayDimensions(rest: string): number {
  let dimensions = 0;
  for (let open = /^\s*\[(?!\[)/.exec(rest); open; open = /^\s*\[(?!\[)/.exec(rest)) {
    dimensions++;
    const close = cppClosingBracket(rest, open[0].length - 1);
    if (close < 0) break;
    rest = rest.slice(close + 1);
  }
  return dimensions;
}

/** An element of the array `type`: the type it is declared with, one dimension less. */
function cppArrayElement(type: CppWrittenType): CppWrittenType {
  const { array, ...element } = type;
  return array !== undefined && array > 1 ? { ...element, array: array - 1 } : element;
}

/**
 * The element a subscript of a value of the type `type` reads: an array's,
 * what a pointer points at, a library map's mapped value, a sequence's
 * element (a library container's, or one of CPP_PROJECT_SEQUENCES'), or what
 * a class's `operator[]` returns. Null for anything else: a `std::string`'s
 * `char`, or a class whose `operator[]` the index doesn't hold.
 */
function cppSubscriptElement(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  if (type.array) return cppArrayElement(type);
  if (isCppPointerType(type.text)) return cppPointee(type);
  const segments = cppTypeSegments(type.text);
  const last = segments?.[segments.length - 1];
  if (!segments || !last) return null;
  const library = segments[0] === 'std' || segments[0] === 'absl';
  if (library && CPP_LIBRARY_MAPS.has(last)) {
    const value = cppTemplateArguments(type.text)?.[1];
    return value ? { ...type, text: cppWithoutNullability(value) } : null;
  }
  if ((library && CPP_LIBRARY_SEQUENCES.has(last)) || CPP_PROJECT_SEQUENCES.has(last)) return cppRangeElementOf(type, at, context);
  if (library) return null;
  const cls = cppWrittenClass(type, at, context);
  if (!cls) return null;
  const element = cppReturnTypeOf(cppMethodsOf(cls, 'operator[]', at, context), context);
  return element ? { ...element, text: element.text.replace(/&+\s*$/, '').trim() } : null;
}

/**
 * The expanded definition a C++ method that a macro defines carries as its
 * signature (cpp-macro-methods.ts), `inline const FileDescriptor*
 * Descriptor::file() const` for protobuf's `PROTOBUF_DEFINE_ACCESSOR(Descriptor,
 * file, const FileDescriptor*)`: its source is the invocation, which spells
 * neither its return type nor its parameters. Null for any other node.
 */
function cppMacroMethodHead(fn: Node): string | null {
  if (fn.kind !== 'method' || !fn.signature) return null;
  const name = fn.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`::\\s*${name}\\s*\\(`).test(fn.signature) ? fn.signature : null;
}

/**
 * The return type of a C or C++ function, as its declaration writes it:
 * `std::vector<const FieldDescriptor*>` for `std::vector<const
 * FieldDescriptor*> FieldNumberOrder(…)`. (The index keeps only `vector`.)
 * Null for none that can be read: a constructor, `void`, `auto` or
 * `decltype(…)`. A method a macro defines is read from its expansion.
 */
function cppWrittenReturnType(fn: Node, context: ResolutionContext): string | null {
  const macro = cppMacroMethodHead(fn);
  const lines = macro === null ? context.getFileLines?.(fn.filePath) ?? context.readFile(fn.filePath)?.split(/\r?\n/) : null;
  if (macro === null && !lines) return null;
  const head = macro ?? lines!.slice(fn.startLine - 1, fn.startLine + 2).join(' ').slice(fn.startColumn);
  const name = fn.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/^operator/, 'operator\\s*');
  const declared = new RegExp(String.raw`^(.*?)(?:\b[A-Za-z_]\w*\s*(?:<[^<>;{}]*>)?\s*::\s*)*\b${name}\s*\(`).exec(head);
  let written = declared?.[1];
  if (written === undefined) return null;
  if (/^\s*template\b/.test(written)) {
    const open = written.indexOf('<');
    let depth = 0;
    let end = -1;
    for (let i = open; open >= 0 && i < written.length; i++) {
      if (written[i] === '<') depth++;
      else if (written[i] === '>' && --depth === 0) {
        end = i;
        break;
      }
    }
    if (end < 0) return null;
    written = written.slice(end + 1);
  }
  written = cppWithoutNullability(written
    .replace(/\[\[[^\]]*\]\]/g, ' ')
    .replace(/\b(?:inline|static|virtual|constexpr|consteval|explicit|friend|extern)\b/g, ' ')
    // A leading macro: `PROTOBUF_EXPORT`, `ABSL_MUST_USE_RESULT`.
    .replace(/^\s*(?:[A-Z][A-Z0-9]*_[A-Z0-9_]*(?:\([^()]*\))?\s+)+/, '')
    // A trailing one: `T* PROTOBUF_NONNULL`.
    .replace(/(?:\s+[A-Z][A-Z0-9]*_[A-Z0-9_]*(?:\([^()]*\))?)+\s*$/, ''));
  if (!written || /^(?:void|auto)$/.test(written) || /\bdecltype\b/.test(written)) return null;
  return written;
}

/**
 * The names of the template parameters a C++ function template's own
 * `template <…>` header declares, in order, without their defaults:
 * `['Type']` for protobuf's `template <typename Type> const Type& GetRaw(…)`.
 * A template's node starts at its declaration, so the header is the code
 * right before it. Empty for a function that is no template.
 */
function cppOwnTemplateParameters(fn: Node, context: ResolutionContext): string[] {
  const lines = context.getFileLines?.(fn.filePath) ?? context.readFile(fn.filePath)?.split(/\r?\n/);
  if (!lines) return [];
  const at = lines[fn.startLine - 1] ?? '';
  const before = [...lines.slice(Math.max(0, fn.startLine - 9), fn.startLine - 1), at.slice(0, fn.startColumn)]
    .map((line) => cppCodeOf(line) ?? '').join(' ').trimEnd();
  let depth = 0;
  for (let i = before.endsWith('>') ? before.length - 1 : -1; i >= 0; i--) {
    if (before[i] === '>') depth++;
    else if (before[i] === '<' && --depth === 0) {
      if (!/\btemplate\s*$/.test(before.slice(0, i))) return [];
      return splitCppTopLevel(before.slice(i + 1, -1)).map((p) => /([A-Za-z_]\w*)$/.exec(p.split('=')[0]!.trim())?.[1] ?? '');
    }
  }
  return [];
}

/**
 * What a call of the C++ member template whose overloads are `methods`, with
 * the explicit template arguments `args` (`<…>` as written), returns when
 * every overload is declared to return the same one of its own template
 * parameters, perhaps const, a pointer or a reference: that argument, so
 * qualified, as written at the call (`site`). protobuf's `template <typename
 * Type> const Type& GetRaw(…)` called as `reflection->GetRaw<RepeatedPtrField<
 * std::string>>(…)` returns a `const RepeatedPtrField<std::string>&`, and
 * rocksdb's `T* GetOptions()` called as `GetOptions<BlockBasedTableOptions>()`
 * a `BlockBasedTableOptions*`. Undefined otherwise: then the return type is
 * read as written.
 */
function cppMemberTemplateReturn(
  methods: readonly Node[],
  args: string,
  site: Omit<CppWrittenType, 'text'>,
  context: ResolutionContext,
): CppWrittenType | undefined {
  let slot: { index: number; written: string; param: string } | undefined;
  for (const fn of methods) {
    const written = cppWrittenReturnType(fn, context);
    if (!written) continue;
    const param = written.replace(/\b(?:const|volatile)\b|[*&]/g, ' ').trim();
    const index = param ? cppOwnTemplateParameters(fn, context).indexOf(param) : -1;
    if (index < 0 || (slot && slot.index !== index)) return undefined;
    slot ??= { index, written, param };
  }
  const arg = slot && splitCppTopLevel(args.slice(1, -1))[slot.index];
  return slot && arg ? { ...site, text: slot.written.replace(new RegExp(`\\b${slot.param}\\b`), arg) } : undefined;
}

/** What one of `fns` (overloads, a declaration and its definition) returns, as written where it is declared. */
function cppReturnTypeOf(fns: readonly Node[], context: ResolutionContext): CppWrittenType | null {
  for (const fn of fns) {
    const text = cppWrittenReturnType(fn, context);
    if (text) {
      return { text, scope: cppParentScope(fn.qualifiedName), file: fn.filePath, line: fn.startLine, parameters: cppTemplateParameters(fn, context) };
    }
  }
  return null;
}

/**
 * The C++ class `cls`'s methods named `name`: its own declarations and
 * definitions, else the nearest one a class it derives from has (cppMethodOf).
 */
function cppMethodsOf(cls: Node, name: string, at: UnresolvedRef, context: ResolutionContext): Node[] {
  const own = context.getNodesByQualifiedName(`${cls.qualifiedName}::${name}`).filter(isCppFunctionNode);
  if (own.length > 0) return own;
  const inherited = cppMethodOf(cls, name, at, context);
  return inherited ? [inherited] : [];
}

/**
 * `type` once the aliases it is written with are followed, each in its own
 * scope, with what they name as written: rocksdb's `const BlobFiles&` is
 * `std::vector<std::shared_ptr<BlobFileMetaData>>`. Null when an alias on
 * the way can't be read.
 */
function cppFollowWrittenAliases(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  let current = type;
  for (let hop = 0; hop < 4; hop++) {
    const aliased = cppAliasedTypeWritten(current.text, cppScopesWithin(current.scope), at, context);
    if (aliased === undefined) return current;
    if (aliased === null) return null;
    const { alias } = aliased;
    current = {
      text: isCppPointerType(current.text) ? `${aliased.text}*` : aliased.text,
      scope: cppParentScope(alias.qualifiedName),
      file: alias.filePath,
      line: alias.startLine,
      parameters: cppTemplateParameters(alias, context),
      ...(current.array ? { array: current.array } : {}),
    };
  }
  return null;
}

/** Is the type `type` names a template parameter's, which a template argument decides? */
function isCppTemplateParameterType(type: CppWrittenType): boolean {
  const head = cppTypeSegments(type.text)?.[0];
  return !!head && type.parameters.has(head);
}

/** The project class `type` names, looked up as C++ looks it up where it is written. */
function cppWrittenClass(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): Node | null {
  const found = cppClassWritten(type.text, type, at, context);
  return found && CPP_CLASS_KINDS.has(found.node.kind) ? found.node : null;
}

const CPP_DATA_MEMBERS = new WeakMap<ResolutionContext, Map<string, CppWrittenType | null>>();
const CPP_NESTED_SPANS = new WeakMap<ResolutionContext, Map<string, Array<[number, number]>>>();
const CPP_CLASS_PAREN_DEPTHS = new WeakMap<ResolutionContext, Map<string, number[]>>();

/**
 * The type the C++ class `decl` declares its data member `name` with, as
 * written, in the class's scope: `std::vector<SubcompactionState>` for
 * rocksdb's `CompactionState::sub_compact_states`. Data members are not
 * indexed, so the class's own lines are read — one inside none of the
 * functions or classes nested in it. Null when none of them declares it
 * (a base class may). Only `decl`'s own: a class of the same qualified name
 * another file declares for itself is another class — rocksdb's
 * `db_bench_tool.cc` and `db_stress_shared_state.h` each declare a
 * `ThreadState`, whose `rand` is a `Random64` in one and a `Random` in the
 * other. A declarator inside parentheses is a parameter of a method the
 * class declares — which has no node of its own, so its lines are the
 * class's — not a member: rocksdb's `DB` declares `CreateColumnFamilies(const
 * std::vector<ColumnFamilyDescriptor>& column_families, …)`. Nor is a name
 * an argument list follows, a method.
 */
function cppDataMemberIn(decl: Node, name: string, context: ResolutionContext): CppWrittenType | null {
  if ((decl.language !== 'cpp' && decl.language !== 'c') || !CPP_CLASS_KINDS.has(decl.kind)) return null;
  let memo = CPP_DATA_MEMBERS.get(context);
  if (!memo) CPP_DATA_MEMBERS.set(context, (memo = new Map()));
  const key = `${decl.id}\u0000${name}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  let member: CppWrittenType | null = null;
  const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/);
  if (lines) {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const word = new RegExp(`\\b${escaped}\\b`);
    const declarator = buildDeclaratorRegex(escaped);
    const listed = buildListedDeclaratorRegex(escaped);
    // `Table *index_, *data_;` declares both members.
    const declared = (text: string): RegExpExecArray | null =>
      matchCppDeclarator(text, declarator) ?? matchCppListedDeclarator(text, name, listed);
    const end = Math.min(decl.endLine ?? decl.startLine, lines.length);
    const nested = cppNestedSpans(decl, end, context);
    const rawLines = cppNonCodeLines(decl.filePath, context);
    const depths = cppClassParenDepths(decl, lines, end, rawLines, context);
    for (let l = decl.startLine; l <= end; l++) {
      if (!word.test(lines[l - 1]!) || nested.some(([start, stop]) => l >= start && l <= stop)) continue;
      let code = cppCodeOf(cppLiteralsBlanked(lines[l - 1]!, l, rawLines));
      // The line the declaration's code starts on: the one above, for a type
      // written there and nothing else (rocksdb's
      // `std::vector<std::pair<ColumnFamilyHandle*, std::unique_ptr<Iterator>>>`
      // above `cfh_iter_pairs_;`), so a default member initializer continued
      // on the next line (`bool ready_ = flag_ &&` above `it_;`) isn't one.
      let from = l;
      let m = code ? declared(code) : null;
      if (!m && code && l > decl.startLine) {
        const above = cppCodeOf(cppLiteralsBlanked(lines[l - 2]!, l - 1, rawLines));
        if (above && CPP_TYPE_LINE.test(above)) {
          code = `${above} ${code}`;
          from = l - 1;
          m = declared(code);
        }
      }
      const rest = m ? code!.slice(m.index + m[0].length) : '';
      if (!m || rest.startsWith('(')) continue;
      let depth = depths[from - decl.startLine]!;
      for (const c of code!.slice(from === decl.startLine ? decl.startColumn : 0, m.index)) {
        if (c === '(') depth++;
        else if (c === ')') depth--;
      }
      const type = depth <= 0 ? normalizeCppTypeName(m[1]!) : null;
      if (type && type !== 'auto') {
        const array = cppArrayDimensions(rest);
        member = {
          text: m[1]!,
          scope: decl.qualifiedName,
          file: decl.filePath,
          line: from,
          parameters: cppTemplateParameters(decl, context),
          ...(array > 0 ? { array } : {}),
        };
        break;
      }
    }
  }
  memo.set(key, member);
  return member;
}

/**
 * How many parentheses are open where each line of the C++ class
 * declaration `decl`, which ends on line `end`, begins. Its block comments
 * and literals are blanked first (cppNonCodeLines): a parenthesis in one
 * opens nothing.
 */
function cppClassParenDepths(
  decl: Node,
  lines: readonly string[],
  end: number,
  rawLines: ReturnType<typeof cppNonCodeLines>,
  context: ResolutionContext,
): number[] {
  let memo = CPP_CLASS_PAREN_DEPTHS.get(context);
  if (!memo) CPP_CLASS_PAREN_DEPTHS.set(context, (memo = new Map()));
  let depths = memo.get(decl.id);
  if (!depths) {
    depths = [];
    let depth = 0;
    for (let l = decl.startLine; l <= end; l++) {
      depths.push(depth);
      const text = cppLiteralsBlanked(lines[l - 1] ?? '', l, rawLines);
      for (let i = l === decl.startLine ? decl.startColumn : 0; i < text.length; i++) {
        const c = text[i]!;
        if (c === '/' && text[i + 1] === '/') break;
        else if (c === '(') depth++;
        else if (c === ')' && depth > 0) depth--;
      }
    }
    memo.set(decl.id, depths);
  }
  return depths;
}

/**
 * Is the C or C++ declaration `n` an anonymous union or struct, with no name
 * and no declarator, whose members are those of the class it is declared in?
 * C++ looks them up as that class's own: protobuf's generated messages hold
 * their fields in `union { Impl_ _impl_; };`, and fmt's `value` its argument
 * in a union of `string`, `custom` and the rest. Not one with a declarator,
 * `union { … } u;`, whose members are `u`'s, nor a specialization the index
 * keeps as `<anonymous>`, whose head names its template.
 */
function isCppAnonymousMembers(n: Node, context: ResolutionContext): boolean {
  if (n.name !== '<anonymous>' || (n.kind !== 'union' && n.kind !== 'struct')) return false;
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/);
  const head = lines?.[n.startLine - 1]?.slice(n.startColumn ?? 0);
  const foot = lines?.[(n.endLine ?? n.startLine) - 1];
  return !!head && !!foot && /^\s*(?:union|struct)\s*\{/.test(head) && /\}\s*;\s*(?:\/\/.*)?$/.test(foot);
}

/**
 * The lines of the functions and classes nested in the C++ class declaration
 * `decl`, which ends on line `end` — not an anonymous union's or struct's,
 * whose members are the class's own (isCppAnonymousMembers).
 */
function cppNestedSpans(decl: Node, end: number, context: ResolutionContext): Array<[number, number]> {
  let memo = CPP_NESTED_SPANS.get(context);
  if (!memo) CPP_NESTED_SPANS.set(context, (memo = new Map()));
  let spans = memo.get(decl.id);
  if (!spans) {
    spans = context.getNodesInFile(decl.filePath)
      .filter((n) => n.id !== decl.id && n.startLine >= decl.startLine && (n.endLine ?? n.startLine) <= end &&
        (isCppFunctionNode(n) || (CPP_CLASS_KINDS.has(n.kind) && !isCppAnonymousMembers(n, context))))
      .map((n): [number, number] => [n.startLine, n.endLine ?? n.startLine]);
    memo.set(decl.id, spans);
  }
  return spans;
}

const CPP_CALLERS_MEMBERS = new WeakMap<ResolutionContext, Map<string, CppWrittenType | null>>();

/**
 * The type a data member `name` of the C++ class the calling function
 * `caller` belongs to has, as written in the class: its own, else one of a
 * class it derives from, through its base edges (not a base that depends on
 * the class's template parameters, where a bare name isn't looked up). The
 * class is read wherever it is declared: rocksdb's `DBImpl` is declared in
 * db_impl.h, while its methods are defined in db_impl_write.cc,
 * db_impl_compaction_flush.cc, db_impl_open.cc and more. A gtest
 * `TEST_F(Fixture, Name)` or `TEST_P` body is a method of a class derived
 * from `Fixture`. Null when none of them declares it.
 */
function cppCallersMember(name: string, caller: Node, ref: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  let memo = CPP_CALLERS_MEMBERS.get(context);
  if (!memo) CPP_CALLERS_MEMBERS.set(context, (memo = new Map()));
  const key = `${caller.id}\u0000${name}`;
  const hit = memo.get(key);
  if (hit !== undefined) return hit;
  const owner = cppMemberOwner(caller, context) ?? cppTestFixture(caller, ref, context);
  const decls = owner ? cppScopeDeclarations(owner, cppClassDecls(owner, context), caller, context).decls : [];
  const member = owner ? cppInheritedDataMember(decls, name, context, 0, new Set([owner])) : null;
  memo.set(key, member);
  return member;
}

/** The data member `name` of a class, in one of its declarations `decls` or else in a class it derives from. */
function cppInheritedDataMember(decls: readonly Node[], name: string, context: ResolutionContext, depth: number, seen: Set<string>): CppWrittenType | null {
  for (const decl of decls) {
    const own = cppDataMemberIn(decl, name, context);
    if (own) return own;
  }
  if (depth >= 4 || !context.getSupertypeNodes) return null;
  for (const decl of decls) {
    for (const base of context.getSupertypeNodes(decl.id)) {
      if (!CPP_CLASS_KINDS.has(base.kind) || seen.has(base.qualifiedName)) continue;
      if (isCppDependentBase(decl, base, context) && !cppUsingDeclares(decl, base, name, context)) continue;
      seen.add(base.qualifiedName);
      const inherited = cppInheritedDataMember([base], name, context, depth + 1, seen);
      if (inherited) return inherited;
    }
  }
  return null;
}

/**
 * The fixture class of a gtest `TEST_F(Fixture, Name)` or `TEST_P(Fixture,
 * Name)` body, which the index holds as a function named `TEST_F`: the body
 * is a method of a class gtest derives from `Fixture`. Null for any other
 * function, and for a fixture C++ lookup doesn't find.
 */
function cppTestFixture(caller: Node, ref: UnresolvedRef, context: ResolutionContext): string | null {
  if (caller.kind !== 'function' || (caller.name !== 'TEST_F' && caller.name !== 'TEST_P')) return null;
  const lines = context.getFileLines?.(caller.filePath) ?? context.readFile(caller.filePath)?.split(/\r?\n/);
  const head = lines?.slice(caller.startLine - 1, caller.startLine + 1).join(' ') ?? '';
  const fixture = /\bTEST_[FP]\s*\(\s*((?:::\s*)?[A-Za-z_]\w*(?:\s*::\s*[A-Za-z_]\w*)*)\s*,/.exec(head)?.[1];
  if (!fixture) return null;
  const site = { scope: cppParentScope(caller.qualifiedName), file: caller.filePath, line: caller.startLine, parameters: new Set<string>() };
  const found = cppClassWritten(fixture.replace(/\s+/g, ''), site, ref, context);
  return found?.exact && CPP_CLASS_KINDS.has(found.node.kind) ? found.node.qualifiedName : null;
}

/**
 * The type `*x` has when `x` has the type `type`: what a pointer points at,
 * or what a smart pointer, an optional or an `absl::StatusOr` holds (cppHeldType). Null for any other type.
 */
function cppPointee(type: CppWrittenType): CppWrittenType | null {
  const text = type.text.replace(/&+\s*$/, '').trim();
  let depth = 0;
  for (let i = text.length - 1; i >= 0; i--) {
    const ch = text[i]!;
    if (ch === '>') depth++;
    else if (ch === '<') depth--;
    else if (ch === '*' && depth === 0) return { ...type, text: text.slice(0, i).trim() };
  }
  const held = cppHeldType(text);
  return held ? { ...type, text: held } : null;
}

/**
 * The element type of a range of the type `type`, as written: an array's
 * (cppArrayElement), a container's first template argument
 * (`autovector<ColumnFamilyData*>`), or, for one of the project's classes,
 * what its `begin()` returns dereferenced — rocksdb's `ColumnFamilySet`,
 * whose iterator's `operator*` returns a `ColumnFamilyData*`. Null when that
 * can't be read.
 */
function cppRangeElementOf(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext, hops = 0): CppWrittenType | null {
  if (type.array) return cppArrayElement(type);
  const range = cppFollowWrittenAliases(type, at, context);
  if (!range || isCppPointerType(range.text) || hops > 2) return null;
  const segments = cppTypeSegments(range.text);
  const last = segments?.[segments.length - 1];
  if (!segments || !last) return null;
  if (CPP_LIBRARY_SEQUENCES.has(last) || CPP_PROJECT_SEQUENCES.has(last)) {
    // A project type of a standard container's name, written without
    // `std::` or `absl::`, is that type, not the container.
    if (CPP_LIBRARY_SEQUENCES.has(last) && segments[0] !== 'std' && segments[0] !== 'absl' && cppTypesNamed(last, context).length > 0) return null;
    const element = cppTemplateArguments(range.text)?.[0];
    return element ? { ...range, text: cppWithoutNullability(element) } : null;
  }
  // A map's elements pair its key with its value.
  if (CPP_LIBRARY_MAPS.has(last) && (segments[0] === 'std' || segments[0] === 'absl')) {
    const [key, value] = cppTemplateArguments(range.text) ?? [];
    return key && value ? { ...range, text: `std::pair<const ${cppWithoutNullability(key)}, ${cppWithoutNullability(value)}>` } : null;
  }
  const cls = cppWrittenClass(range, at, context);
  const begin = cls ? cppReturnTypeOf(cppMethodsOf(cls, 'begin', at, context), context) : null;
  return begin ? cppIteratorElement(begin, at, context, hops) : null;
}

/** A container's iterator type, `std::vector<Foo*>::const_iterator`, with the container. */
const CPP_ITERATOR_OF = /^(.*>)\s*::\s*(?:const_)?(?:reverse_)?iterator\s*$/;

/** A written type without `typename`, `const` and `&`, which name no part of it. */
function cppWithoutTypeKeywords(text: string): string {
  return text.replace(/\b(?:typename|const)\b|&/g, ' ').trim();
}

/** The members of a library container that return an iterator into it, with the iterator's kind. */
const CPP_ITERATOR_MEMBERS: ReadonlyMap<string, string> = new Map([
  ['begin', 'iterator'], ['end', 'iterator'], ['find', 'iterator'], ['lower_bound', 'iterator'], ['upper_bound', 'iterator'],
  ['cbegin', 'const_iterator'], ['cend', 'const_iterator'], ['rbegin', 'reverse_iterator'], ['rend', 'reverse_iterator'],
  ['crbegin', 'const_reverse_iterator'], ['crend', 'const_reverse_iterator'],
]);

/** The standard library's searches that return an iterator of the type of the one they are given first. */
const CPP_ITERATOR_ALGORITHMS = /^(?:::\s*)?std\s*::\s*(?:find|find_if|find_if_not|lower_bound|upper_bound|min_element|max_element|partition_point|adjacent_find|next|prev)$/;

/**
 * The iterator the member `member` of a standard library or abseil container
 * of the type `object` returns, where the container's type is written:
 * `std::deque<LogWriterNumber>::iterator` for rocksdb's `logs_.begin()`,
 * whose `->` reaches the container's element (cppArrowTarget). Null for any
 * other member or type.
 */
function cppLibraryIteratorOf(object: CppWrittenType, member: string): CppWrittenType | null {
  const kind = CPP_ITERATOR_MEMBERS.get(member);
  if (!kind || isCppPointerType(object.text)) return null;
  const container = cppWithoutTypeKeywords(object.text);
  const segments = cppTypeSegments(container);
  const last = segments?.[segments.length - 1];
  if (!last || (segments![0] !== 'std' && segments![0] !== 'absl')) return null;
  return CPP_LIBRARY_SEQUENCES.has(last) || CPP_LIBRARY_MAPS.has(last) ? { ...object, text: `${container}::${kind}` } : null;
}

/** The standard library's container adaptors, whose element is their first template argument. */
const CPP_LIBRARY_ADAPTORS: ReadonlySet<string> = new Set(['stack', 'queue', 'priority_queue']);

/**
 * What the member `member` of a library container or holder of the type
 * `object` hands out, where the container's type is written: an element of
 * a sequence for `front()`, `back()` and `at(i)` — of one of
 * CPP_PROJECT_SEQUENCES' too — the value a map's `at(key)` maps to, the
 * element of a `std::stack`'s `top()` or a `std::queue`'s `front()` and
 * `back()`, the pointer a smart pointer's `get()` returns and the value an
 * optional's or an `absl::StatusOr`'s `value()` returns (cppHeldType).
 * rocksdb's `cfds.front()->GetName()` over an `autovector<ColumnFamilyData*>`
 * calls ColumnFamilyData's. Null for any other member or type.
 */
function cppLibraryElementOf(object: CppWrittenType, member: string, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  if (isCppPointerType(object.text)) return null;
  const segments = cppTypeSegments(cppWithoutTypeKeywords(object.text));
  const last = segments?.[segments.length - 1];
  if (!segments || !last) return null;
  // (Its own `const` and `&` aside: a `const` in a template argument, `std::shared_ptr<const Message>`, stays.)
  const text = object.text.replace(/^\s*(?:typename\s+)?const\s+/, '').replace(/(?:\s*\bconst\b)?\s*&+\s*$/, '').trim();
  const library = segments[0] === 'std' || segments[0] === 'absl';
  if (member === 'front' || member === 'back' || member === 'at') {
    if ((library && CPP_LIBRARY_SEQUENCES.has(last)) || CPP_PROJECT_SEQUENCES.has(last)) return cppRangeElementOf(object, at, context);
    if (member === 'at' && library && CPP_LIBRARY_MAPS.has(last)) {
      const value = cppTemplateArguments(text)?.[1];
      return value ? { ...object, text: cppWithoutNullability(value) } : null;
    }
  }
  if (segments[0] === 'std' && CPP_LIBRARY_ADAPTORS.has(last) && (member === 'top' || ((member === 'front' || member === 'back') && last === 'queue'))) {
    const element = cppTemplateArguments(text)?.[0];
    return element ? { ...object, text: cppWithoutNullability(element) } : null;
  }
  const held = cppHeldType(text);
  if (!held || held.includes('[')) return null;
  const holder = segments.join('::');
  if (member === 'get' && (holder === 'std::unique_ptr' || holder === 'std::shared_ptr' || holder === 'absl::NoDestructor')) return { ...object, text: `${held}*` };
  if ((member === 'value' || member === 'value_or') && (holder === 'std::optional' || holder === 'absl::optional' || holder === 'absl::StatusOr')) return { ...object, text: held };
  return null;
}

/** What dereferencing an iterator of the type `type` gives, as written. */
function cppIteratorElement(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext, hops: number): CppWrittenType | null {
  const iterator = cppFollowWrittenAliases(type, at, context);
  if (!iterator) return null;
  if (isCppPointerType(iterator.text)) return cppPointee(iterator);
  // `std::vector<Foo*>::const_iterator`: the container's element.
  const nested = CPP_ITERATOR_OF.exec(cppWithoutTypeKeywords(iterator.text));
  if (nested) return cppRangeElementOf({ ...iterator, text: nested[1]! }, at, context, hops + 1);
  const cls = cppWrittenClass(iterator, at, context);
  const star = cls ? cppReturnTypeOf(cppMethodsOf(cls, 'operator*', at, context), context) : null;
  return star ? { ...star, text: star.text.replace(/&+\s*$/, '').trim() } : null;
}

/**
 * The type of the object `x.m` or `x->m` (`op`) names a member of, given
 * `x`'s text: `x`'s own type for `.`, what it points at, holds or iterates
 * over for `->` (cppDereferenced).
 */
function cppMemberObject(object: string, op: string, at: UnresolvedRef, context: ResolutionContext, depth: number): CppWrittenType | null {
  const type = cppExpressionType(object, at, context, depth + 1);
  const followed = type && cppFollowWrittenAliases(type, at, context);
  if (!followed) return null;
  if (op === '->') return cppDereferenced(followed, at, context);
  return isCppPointerType(followed.text) || followed.array ? null : followed;
}

/**
 * The type of a C++ expression as written where it is declared, for the
 * ranges of `auto` loops and the initializers of `auto` locals: a variable,
 * parameter or member the calling function or its class declares; `*x`;
 * `this`; a call to a function or method whose declaration writes its return
 * type — `FieldNumberOrder(desc)`, `vstorage->GetBlobFiles()`, a bare
 * `NewIterator()` of the caller's class; and what a construction (`new
 * Foo(…)`, `Foo(…)`, `std::make_unique<Foo>(…)`) or a cast
 * (`static_cast<Foo*>(…)`, `std::unique_ptr<Foo>(…)`) makes. Null for
 * anything else, or a name declared only outside the caller.
 */
function cppExpressionType(expr: string, at: UnresolvedRef, context: ResolutionContext, depth: number): CppWrittenType | null {
  if (depth > 4) return null;
  let text = expr.trim();
  while (text.startsWith('(') && text.endsWith(')') && cppOpeningParen(text, text.length - 1) === 0) text = text.slice(1, -1).trim();
  if (text.startsWith('*')) {
    const pointer = cppExpressionType(text.slice(1), at, context, depth + 1);
    const followed = pointer && cppFollowWrittenAliases(pointer, at, context);
    return followed && cppDereferenced(followed, at, context);
  }
  const caller = context.getNodeById?.(at.fromNodeId);
  if (!caller) return null;
  // What the calling function writes is looked up from inside it.
  const callers = { scope: caller.qualifiedName, file: at.filePath, line: at.line, parameters: cppTemplateParameters(caller, context) };
  if (text === 'this') {
    // (A gtest `TEST_F` body's object is of a class derived from its fixture.)
    const owner = cppMemberOwner(caller, context) ?? cppTestFixture(caller, at, context);
    return owner ? { ...callers, text: `${owner}*` } : null;
  }
  const name = /^(?:this\s*->\s*)?([A-Za-z_]\w*)$/.exec(text);
  if (name) {
    const decl: CppReceiverDeclaration = {};
    inferCppReceiverType(name[1]!, at, context, depth + 1, decl);
    if (decl.declared) return decl.declared;
    // `const auto& blob_files = vstorage->GetBlobFiles();`: what its initializer is.
    if (decl.initializer && isCppCallersDeclaration(at.filePath, decl.initializer.line, at, context)) {
      return cppExpressionType(decl.initializer.text, { ...at, line: decl.initializer.line, column: 0 }, context, depth + 1);
    }
    // (A data member of the caller's class has its type as `declared`.)
    if (decl.raw === undefined || !decl.callers || decl.shadowed) return null;
    return { ...callers, text: decl.raw, ...(decl.array ? { array: decl.array } : {}) };
  }
  // `new Foo(…)`: a pointer to what it constructs.
  const created = /^new\s+((?:::\s*)?[A-Za-z_][\w:]*(?:\s*<[^;{}()]*>)?)\s*(?:[({[][\s\S]*)?$/.exec(text);
  if (created) return { ...callers, text: `${created[1]!.trim()}*` };
  // `statuses[i]`, `(*m)[key]`: the element a subscript reads.
  if (text.endsWith(']')) {
    const open = cppOpeningBracket(text, text.length - 1);
    const container = open > 0 ? cppExpressionType(text.slice(0, open), at, context, depth + 1) : null;
    const followed = container && cppFollowWrittenAliases(container, at, context);
    return followed && cppSubscriptElement(followed, at, context);
  }
  if (!text.endsWith(')')) {
    // `compact_->sub_compact_states`: a data member of the object's class, or
    // of a class it derives from — rocksdb's `Options` declares none of its
    // own, and inherits `table_factory`, `statistics` and the rest from
    // `DBOptions` and `ColumnFamilyOptions`; `it->second` through a map's
    // iterator: the member of the `std::pair`.
    const field = /^(.+?)\s*(\.|->)\s*([A-Za-z_]\w*)$/.exec(text);
    const object = field && cppMemberObject(field[1]!, field[2]!, at, context, depth);
    const element = object && cppPairMember(object, field![3]!, at, context);
    if (element) return element;
    const cls = object && cppWrittenClass(object, at, context);
    return cls ? cppInheritedDataMember([cls], field![3]!, context, 0, new Set([cls.qualifiedName])) : null;
  }
  const open = cppOpeningParen(text, text.length - 1);
  const callee = open > 0 ? text.slice(0, open).trim() : '';
  // `static_cast<Foo*>(…)`: the type it casts to.
  const cast = /^(?:static|dynamic|const|reinterpret)_cast\s*<([\s\S]+)>$/.exec(callee);
  if (cast) return { ...callers, text: cast[1]!.trim() };
  // `std::make_unique<Foo>(…)`: the smart pointer it makes.
  const made = /^(?:::\s*)?(?:std|absl)\s*::\s*make_(unique|shared)\s*<([\s\S]+)>$/.exec(callee);
  if (made) return { ...callers, text: `std::${made[1]}_ptr<${made[2]!.trim()}>` };
  // `std::unique_ptr<Iterator>(…)`: the holder it makes (cppHeldType).
  if (cppHeldType(callee)) return { ...callers, text: callee };
  // `std::lower_bound(v.begin(), v.end(), key)`: the iterator it is given.
  if (CPP_ITERATOR_ALGORITHMS.test(callee)) {
    const first = splitCppTopLevel(text.slice(open + 1, -1))[0];
    return first ? cppExpressionType(first, at, context, depth + 1) : null;
  }
  // `create_iterator()` on a `std::function<Iterator*()> create_iterator`: what its function type returns.
  if (/^[A-Za-z_]\w*$/.test(callee)) {
    const wrapper = cppExpressionType(callee, at, context, depth + 1);
    const returned = wrapper && cppWrapperReturnType(wrapper);
    if (returned) return returned;
  }
  // `recv.method(…)`, `recv->method(…)`, `recv->method<T>(…)`: the method of the receiver's class.
  const member = /^(.+?)\s*(\.|->)\s*([A-Za-z_]\w*)\s*(<[\s\S]*>)?$/.exec(callee);
  if (member) {
    const object = cppMemberObject(member[1]!, member[2]!, at, context, depth);
    // `logs_.begin()`, `map.find(key)`: the iterator a library container hands out.
    const iterator = object && !member[4] ? cppLibraryIteratorOf(object, member[3]!) : null;
    if (iterator) return iterator;
    // `ws.front()`, `m.at(key)`, `p.get()`, `s.value()`: what it holds.
    const element = object && !member[4] ? cppLibraryElementOf(object, member[3]!, at, context) : null;
    if (element) return element;
    const cls = object && cppWrittenClass(object, at, context);
    if (!cls) return null;
    const methods = cppMethodsOf(cls, member[3]!, at, context);
    if (!member[4]) return cppReturnTypeOf(methods, context);
    // Explicit template arguments call a template, never an overload that is none.
    const templates = methods.filter((fn) => cppOwnTemplateParameters(fn, context).length > 0);
    return cppMemberTemplateReturn(templates, member[4], callers, context) ?? cppReturnTypeOf(templates, context);
  }
  if (!/^(?:[A-Za-z_]\w*\s*::\s*)*[A-Za-z_]\w*(?:\s*<[\s\S]*>)?$/.test(callee)) return null;
  const spelled = stripCppTemplateArguments(callee).replace(/\s+/g, '');
  // `NewIterator(…)` in a method, or in a gtest body: what the method of its
  // class, or of a class it derives from, returns (cppImplicitThisMethod),
  // before anything outside. It is looked up as on `this`: in a template, a
  // bare call into a base that depends on its parameters compiles only
  // through a using-declaration, like protobuf's `using
  // RepeatedFieldWrapper<T>::MutableRepeatedField;`.
  const own = spelled.includes('::') ? undefined : cppImplicitThisMethod(spelled, 'this', caller, at, context);
  if (own) return cppReturnTypeOf([own], context);
  // `f(…)`, `ns::f(…)`, `Class::f(…)`: looked up from the caller outwards.
  for (const scope of cppScopesWithin(cppParentScope(caller.qualifiedName))) {
    const fns = context.getNodesByQualifiedName(scope ? `${scope}::${spelled}` : spelled).filter(isCppFunctionNode);
    if (fns.length > 0) return cppReturnTypeOf(fns, context);
  }
  // `Foo(…)`, `Foo<int>(…)`: what it constructs, when C++ lookup finds the class.
  const constructed = cppClassWritten(callee, callers, at, context);
  return constructed?.exact && CPP_CLASS_KINDS.has(constructed.node.kind) ? { ...callers, text: callee } : null;
}

const CPP_LOOP_ELEMENTS = new WeakMap<ResolutionContext, Map<string, CppWrittenType | null>>();

/**
 * The element type of the range the `auto` range-for on line `line`
 * iterates, as written where the range's type is declared — what the loop's
 * variable is. `for (auto cfd : cfds)` over a parameter `const
 * autovector<ColumnFamilyData*>& cfds` gives `ColumnFamilyData*`. Null when
 * it can't be read reliably: then the loop's variable is as unknown as an
 * `auto` local whose initializer can't be read. (It is worked out once per
 * loop, so with its own depth budget, whatever lookup first asks for it.)
 */
function cppAutoLoopElement(
  lines: readonly string[],
  line: number,
  loop: { colon: number },
  ref: UnresolvedRef,
  context: ResolutionContext,
): CppWrittenType | null {
  let memo = CPP_LOOP_ELEMENTS.get(context);
  if (!memo) CPP_LOOP_ELEMENTS.set(context, (memo = new Map()));
  const key = `${ref.fromNodeId}\u0000${ref.filePath}\u0000${line}:${loop.colon}`;
  if (memo.has(key)) return memo.get(key)!;
  // (Unknown while it is worked out, so a range naming its own loop's variable ends.)
  memo.set(key, null);
  const range = cppRangeExpression(lines, line, loop.colon);
  const at = { ...ref, line: line + 1, column: loop.colon };
  const type = range ? cppExpressionType(range, at, context, 0) : null;
  const element = type && cppRangeElementOf(type, at, context);
  const followed = element && cppFollowWrittenAliases(element, at, context);
  const result = followed && !isCppTemplateParameterType(followed) ? followed : null;
  memo.set(key, result);
  return result;
}

const CPP_AUTO_LOCALS = new WeakMap<ResolutionContext, Map<string, CppWrittenType | null>>();

/**
 * The type of the initializer `init` of the `auto` local `name` declared on
 * line `line`, as written where it is declared — what the local is: `auto
 * iter = std::unique_ptr<Iterator>(…)` is a `std::unique_ptr<Iterator>`, and
 * `auto it = txn->GetIterator(…)` the `Iterator*` that
 * `Transaction::GetIterator` is declared to return. The index keeps only a
 * return type's last name, which a namesake shares: by it, rocksdb's `auto
 * iter = …; iter->SeekToFirst()` reached `MemTableRep::Iterator`. Null when
 * the type can't be read reliably. (As for a loop, it is worked out once,
 * with its own depth budget.)
 */
function cppAutoLocalType(
  init: string,
  line: number,
  name: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): CppWrittenType | null {
  let memo = CPP_AUTO_LOCALS.get(context);
  if (!memo) CPP_AUTO_LOCALS.set(context, (memo = new Map()));
  const key = `${ref.fromNodeId}\u0000${ref.filePath}\u0000${line}\u0000${name}`;
  if (memo.has(key)) return memo.get(key)!;
  // (Unknown while it is worked out, so an initializer naming its own local ends.)
  memo.set(key, null);
  const at = { ...ref, line, column: 0 };
  const type = cppExpressionType(init, at, context, 0);
  const followed = type && cppFollowWrittenAliases(type, at, context);
  // What a template returns may be what its arguments make it, which are not
  // substituted, and its overloads may return different types: protobuf's
  // `DownCastMessage<T>` returns a `const T&`, a `T*` or a
  // `std::shared_ptr<T>`, by its argument.
  const result = followed && !isCppTemplateDependentType(followed, context) ? followed : null;
  memo.set(key, result);
  return result;
}

/**
 * Is the C++ type `type` a template parameter's where it is written (`T*`,
 * `const T&`), or a library template of one (`std::shared_ptr<T>`,
 * `std::vector<T>`), whose members are the parameter's? A class template of
 * the project's is that class whatever its arguments: `ProtectionInfoKVOS<T>`,
 * or the one a smart pointer holds (`std::unique_ptr<ExternalTableReaderBase<Mode>>`).
 */
function isCppTemplateDependentType(type: CppWrittenType, context: ResolutionContext): boolean {
  if (type.parameters.size === 0) return false;
  if (isCppTemplateParameterType(type)) return true;
  const held = cppHeldType(type.text);
  if (held) return isCppTemplateDependentType({ ...type, text: held }, context);
  // (A trait of one, `std::conditional_t<kIsMutable, …>`, too: it names another type.)
  return (isCppLibraryType(type.text, context) || cppTypeSegments(type.text)?.[0] === 'std') &&
    (type.text.match(/[A-Za-z_]\w*/g) ?? []).some((word) => type.parameters.has(word));
}

/** Where the C or C++ string or character literal opening at `text[start]` closes (the line's end if it doesn't). */
function cppLiteralEnd(text: string, start: number): number {
  for (let i = start + 1; i < text.length; i++) {
    if (text[i] === '\\') i++;
    else if (text[i] === text[start]) return i;
  }
  return text.length;
}

/**
 * Is column `useColumn` of line `useLine` inside the body of the `for` whose
 * header opens at `lines[line][paren]`? A range-based for's variable is in
 * scope there and nowhere else: after the loop, or in a later function, the
 * same name is some other variable. The body runs to the `}` closing a braced
 * body, or to the end of its one statement — taken to be the first `;` or
 * closing `}` at its own depth, so an `else` after it is not counted.
 * Comments and literals are skipped, and a `for` inside one (commented-out
 * code, a code generator's template) has no body.
 */
function cppForBodyEncloses(lines: readonly string[], line: number, paren: number, useLine: number, useColumn: number): boolean {
  let phase: 'before' | 'header' | 'gap' | 'block' | 'statement' = 'before';
  let depth = 0;
  let comment = false;
  for (let l = line; l <= useLine && l < lines.length; l++) {
    const text = lines[l]!;
    const end = l === useLine ? Math.min(useColumn, text.length) : text.length;
    for (let c = 0; c < end; c++) {
      const ch = text[c]!;
      if (comment) {
        if (ch === '*' && text[c + 1] === '/') {
          comment = false;
          c++;
        }
        continue;
      }
      if (ch === '/' && text[c + 1] === '/') break;
      if (ch === '/' && text[c + 1] === '*') {
        comment = true;
        c++;
        continue;
      }
      // (A `'` after a digit separates digits: `1'000'000`.)
      if (ch === '"' || (ch === '\'' && !/\d/.test(text[c - 1] ?? ''))) {
        c = cppLiteralEnd(text, c);
        continue;
      }
      if (phase === 'before') {
        if (l === line && c === paren) {
          phase = 'header';
          depth = 1;
        }
        continue;
      }
      if (phase === 'header') {
        if (ch === '(') depth++;
        else if (ch === ')' && --depth === 0) phase = 'gap';
        continue;
      }
      if (phase === 'gap') {
        if (/\s/.test(ch)) continue;
        phase = ch === '{' ? 'block' : 'statement';
      }
      if (ch === '(' || ch === '[' || ch === '{') depth++;
      else if (ch === ')' || ch === ']') depth--;
      else if (ch === '}' && --depth <= 0) return false;
      else if (ch === ';' && depth <= 0 && phase === 'statement') return false;
    }
  }
  return phase !== 'before' && phase !== 'header';
}

/** What C++ receiver inference made of a receiver's declared type. */
interface CppReceiverDeclaration {
  /**
   * The declared type is an alias: `followed` to the type it names, or
   * `unreadable` when that type is a template parameter's (`using Type =
   * GenericType;`, `typename Traits::Field`) or a `decltype(…)` — no
   * particular class.
   */
  aliased?: 'followed' | 'unreadable';
  /** The type a `followed` alias names, looked up from the calling function (its own typedefs included). */
  alias?: CppAliasedType;
  /** The type as written in the declaration, without following an alias (`Table`). */
  written?: string;
  /** The type is reached through a pointer (`Table* t`, `using Field = const FieldDescriptor*;`). */
  pointer?: boolean;
  /** The type is one of the project's class templates, whose specializations may add members. */
  classTemplate?: boolean;
  /** The declared type as written (`std::vector<Slice>*`). */
  raw?: string;
  /** A `const` the declaration writes before its type (`const Buffer* b`), which `raw` leaves out. */
  constant?: boolean;
  /** The array dimensions the declarator gives the receiver (`Status statuses[3]`), which `raw` doesn't show. */
  array?: number;
  /** The declaration is the calling function's own, or a member of its class (isCppCallersDeclaration). */
  callers?: boolean;
  /**
   * On its way back to the declaration the scan passed one of the receiver
   * it could not read a type from — `auto x = Make();`, `for (Foo& x : xs)`,
   * `auto [x, y] = …` — so the declaration it found is an earlier variable's.
   */
  shadowed?: boolean;
  /**
   * The receiver's type as written where it is declared, when that is not
   * in the calling function's own text or says `auto` there (`raw` is its
   * text): the element type of the range an `auto` range-for iterates, the
   * type of an `auto` local's initializer — the `Iterator*` that
   * `txn->GetIterator(…)` returns — or a data member's, in its class.
   */
  declared?: CppWrittenType;
  /**
   * The first declaration the scan met is an `auto` local's, on this line,
   * with this initializer: `vstorage->GetBlobFiles()` in `const auto&
   * blob_files = vstorage->GetBlobFiles();`.
   */
  initializer?: { line: number; text: string };
}

/**
 * A declared C++ type as receiver inference reads it: its own last segment,
 * or, when it is an alias the caller's own declaration uses, the type the
 * alias names (cpp-type-aliases.ts) — null when that type can't be known. An
 * alias is never a class, so its own name is never looked up as one: that is
 * how protobuf's `Field f; f->number()` (`using Field = const
 * FieldDescriptor*;`) reached the generated `Field` message's `number`.
 */
function cppDeclaredType(
  raw: string,
  normalized: string,
  inCallerScope: boolean,
  ref: UnresolvedRef,
  context: ResolutionContext,
  found?: CppReceiverDeclaration,
): string | null {
  // A declaration read from elsewhere (an earlier function, another class)
  // may not be this receiver's, so it is taken as it was before aliases
  // were followed.
  if (!inCallerScope) return normalized;
  const aliased = resolveCppAliasedType(raw, ref, context);
  if (aliased === undefined) return normalized;
  if (found) {
    found.aliased = aliased ? 'followed' : 'unreadable';
    if (aliased) found.alias = aliased;
    found.written = normalized;
    found.pointer = aliased ? aliased.pointer : isCppPointerType(raw);
    found.classTemplate = aliased?.classTemplate ?? false;
  }
  return aliased ? cppAliasedTypeName(aliased) : null;
}

const CPP_CLASSES_IN_FILE = new WeakMap<ResolutionContext, Map<string, Node[]>>();

/** The classes, structs and unions a C or C++ file declares. */
function cppClassesIn(file: string, context: ResolutionContext): Node[] {
  let memo = CPP_CLASSES_IN_FILE.get(context);
  if (!memo) CPP_CLASSES_IN_FILE.set(context, (memo = new Map()));
  let classes = memo.get(file);
  if (!classes) {
    classes = context.getNodesInFile(file).filter((n) => n.kind === 'class' || n.kind === 'struct' || n.kind === 'union');
    memo.set(file, classes);
  }
  return classes;
}

/**
 * Is line `line` of `file`, which declares a C++ receiver, the calling
 * function's own code, or a member declaration of the caller's class?
 * Receiver inference reads back to the top of the file and through the
 * header, so a declaration it finds elsewhere — an earlier function, another
 * class in the header, a class nested in the caller's (rocksdb's
 * `MultiScan::MultiScanIterator` has a `scan_opts_` of its own) — may be
 * another variable of the same name. (The scan has blanked comments.)
 */
function isCppCallersDeclaration(file: string, line: number, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller || (caller.kind !== 'method' && caller.kind !== 'function')) return false;
  if (file === ref.filePath && line >= caller.startLine && line <= ref.line) return true;
  const cut = caller.qualifiedName.lastIndexOf('::');
  if (cut < 0) return false;
  let innermost: Node | undefined;
  for (const cls of cppClassesIn(file, context)) {
    if (line < cls.startLine || line > (cls.endLine ?? cls.startLine)) continue;
    if (!innermost || cls.startLine >= innermost.startLine) innermost = cls;
  }
  return innermost?.qualifiedName === caller.qualifiedName.slice(0, cut);
}

/**
 * The operator the C++ member call at `ref` is written with: `.` for
 * `receiver.method(…)`, `->` through a pointer, iterator or smart pointer, or
 * null when the source doesn't show it.
 */
function cppMemberOperator(receiver: string, ref: UnresolvedRef, context: ResolutionContext): '.' | '->' | null {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  const at = lines?.[ref.line - 1]?.slice(ref.column);
  if (!lines || !at?.startsWith(receiver)) return null;
  let rest = at.slice(receiver.length);
  // `symbols_by_parent_` ending its line, `.insert(…)` starting the next.
  for (let next = ref.line; !rest.trim() && next < Math.min(lines.length, ref.line + 3); next++) rest = lines[next]!;
  const op = /^\s*(\.|->)/.exec(rest)?.[1];
  return op === '.' || op === '->' ? op : null;
}

/** Is the C++ member call at `ref` written `receiver.method(…)`, not through `->`? */
function isCppDotCall(receiver: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return cppMemberOperator(receiver, ref, context) === '.';
}

/** Kinds that declare a C or C++ type name. */
const CPP_TYPE_KINDS: ReadonlySet<string> = new Set(['class', 'struct', 'union', 'enum', 'interface', 'type_alias']);

/** The C and C++ types the project declares under `name`. */
function cppTypesNamed(name: string, context: ResolutionContext): Node[] {
  return context.getNodesByName(name).filter((n) => (n.language === 'cpp' || n.language === 'c') && CPP_TYPE_KINDS.has(n.kind));
}

/**
 * Is a C++ declared type, as written (`std::vector<Slice>*`, `const
 * absl::flat_hash_set<int>&`), one from outside the project with a lowercase
 * name, as the standard library's and abseil's are? (isUndeclaredTypeName
 * takes the capitalized ones.) The name is qualified, by namespaces that are
 * no project type's (`Foo::kMask & key` reads like a declaration of `key`),
 * and the project declares no type of that name: in `std` itself for a
 * `std::` name (googletest's `testing::internal::string` is no
 * `std::string`); for any other, none the written name can be
 * (cppFindsOnlyNamesakes), so `absl::flat_hash_set` is abseil's beside a
 * project's own `util::flat_hash_set`. An unqualified name
 * is not known to be std's: fmt's `using namespace std;` is inside `namespace
 * adl { … }`, and its `basic_string_view` is fmt's own. Nor is a type whose
 * `>`s outnumber its `<`s: the end of a declaration begun on an earlier line
 * (`autovector<std::pair<Req*,` above `std::unique_ptr<Blob>>>& reqs`). A
 * `_t` name has no members of its own: it is a scalar (`std::size_t`, so
 * the declaration is another variable's), a tag, or a trait that names
 * another type (rocksdb's `std::conditional_t<kIsDigested, void*, Slice>
 * dict`). So is a member of a template's specialization other than an
 * iterator: `std::vector<Slice>::value_type` is a `Slice`, and googletest's
 * `typename std::tuple_element<N - 1, MatcherTuple>::type matcher` one of its
 * matcher classes.
 */
function isCppLibraryType(raw: string, context: ResolutionContext): boolean {
  if ((raw.match(/</g)?.length ?? 0) !== (raw.match(/>/g)?.length ?? 0)) return false;
  const segments = cppTypeSegments(raw);
  if (!segments || segments.length < 2) return false;
  const name = segments[segments.length - 1]!;
  if (!/^[a-z]/.test(name) || /_t$/.test(name)) return false;
  if (!CPP_ITERATOR_NAME.test(name) && isCppSpecializationMember(raw)) return false;
  if (segments.slice(0, -1).some((s) => cppTypesNamed(s, context).length > 0)) return false;
  const declared = cppTypesNamed(name, context);
  if (segments[0] !== 'std') return declared.length === 0 || cppFindsOnlyNamesakes(raw, context);
  const spelled = segments.join('::');
  return !declared.some((n) => n.qualifiedName === spelled || n.qualifiedName.endsWith(`::${spelled}`));
}

/** A container's iterator type: `iterator`, `const_reverse_iterator`, `local_iterator`. */
const CPP_ITERATOR_NAME = /^(?:const_)?(?:reverse_|local_)?iterator$/;

/**
 * Is a C++ type written as a member of a template's specialization:
 * `std::vector<int>::iterator`, `SkipList<Key, Comparator>::Iterator`?
 */
function isCppSpecializationMember(raw: string): boolean {
  let depth = 0;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] === '<') depth++;
    else if (raw[i] === '>' && --depth === 0 && /^\s*::/.test(raw.slice(i + 1))) return true;
  }
  return false;
}

/** Library types whose `->` reaches the value they hold. */
const CPP_HOLDERS: ReadonlySet<string> = new Set(['std::unique_ptr', 'std::shared_ptr', 'std::optional', 'absl::optional', 'absl::StatusOr', 'absl::NoDestructor']);

/**
 * The type a standard smart pointer, an optional, an `absl::StatusOr` or an
 * `absl::NoDestructor` written as `raw` holds (`Iterator` for
 * `std::unique_ptr<Iterator>`), or null.
 */
function cppHeldType(raw: string): string | null {
  const holder = cppTypeSegments(raw);
  if (holder?.length !== 2 || !CPP_HOLDERS.has(holder.join('::'))) return null;
  return cppTemplateArguments(raw)?.[0] ?? null;
}

/**
 * What `->` on a C++ value of the type `raw` reaches, as written: the type a
 * library holder holds (cppHeldType), at the call (`site`), or the element of
 * the container whose iterator it is — `Slice` for
 * `std::deque<Slice>::const_iterator`, protobuf's `SourceCodeInfo_Location`
 * for `RepeatedPtrField<SourceCodeInfo_Location>::iterator`, read from the
 * container's template arguments before the `iterator` alias would lose them
 * (cppRangeElementOf) — where the container's type is written (`declared`,
 * where an `auto` local's initializer or a data member's class writes it,
 * else `site`). (A holder's type is looked up from the call: a pimpl's
 * `Rep`, which a header only declares, is complete in the file that calls
 * it, while from the header the lookup finds a namesake, as it did for
 * protobuf's `DescriptorIndex`.) Null for any other type, and for an
 * element a class template's own `begin()` or `operator*` writes with its
 * template parameter (googletest's `ParamGenerator<T>::iterator`), which
 * the specialization decides.
 */
function cppArrowTarget(
  raw: string,
  site: CppNameSite,
  declared: CppWrittenType | undefined,
  ref: UnresolvedRef,
  context: ResolutionContext,
): CppWrittenType | null {
  const held = cppHeldType(raw);
  if (held) return isCppLibraryHolder(raw, context) ? { ...site, text: held } : null;
  return cppIteratorTarget({ ...(declared ?? site), text: raw }, ref, context);
}

/**
 * The element a container's iterator of the type `iterator` points at, read
 * from the container's template arguments (cppArrowTarget), or what `->` on
 * a value of one of the project's classes reaches (cppOperatorTarget). Null
 * for any other type, and for an element a class template's own `begin()` or
 * `operator*` writes with its template parameter.
 */
function cppIteratorTarget(iterator: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  const container = CPP_ITERATOR_OF.exec(cppWithoutTypeKeywords(iterator.text))?.[1];
  const element = container ? cppRangeElementOf({ ...iterator, text: container }, at, context, 1) : cppOperatorTarget(iterator, at, context);
  return element && (element.scope === iterator.scope || !isCppTemplateParameterType(element)) ? element : null;
}

/**
 * What `->` on a value of one of the project's classes of the type `type`
 * reaches, as C++ reads `x->m`: what the class's `operator->` returns,
 * through the pointer it is, or with `->` applied again to a class it is (a
 * library holder's held type, or another of these); else what its
 * `operator*` returns. The return type is read where the class declares it,
 * with the class's own template parameters bound to the arguments `type` is
 * written with (cppTemplateBound). rocksdb's `MultiGetContext::Range::Iterator`
 * declares `KeyContext* operator->()`, its `UnownedPtr<DB>` a `T*
 * operator->()`, a `DB*`, and its `FileSystemPtr` returns a
 * `std::shared_ptr<FileSystem>`. Null when the class declares neither, or
 * what it returns can't be read.
 */
function cppOperatorTarget(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext, hops = 0): CppWrittenType | null {
  const written = cppWithoutTypeKeywords(type.text);
  if (hops > 2 || !written || isCppPointerType(written) || isCppLibraryType(written, context)) return null;
  const found = cppClassWritten(written, type, at, context);
  if (!found?.exact || !CPP_CLASS_KINDS.has(found.node.kind)) return null;
  const arrow = cppMethodsOf(found.node, 'operator->', at, context);
  const returned = cppReturnTypeOf(arrow.length > 0 ? arrow : cppMethodsOf(found.node, 'operator*', at, context), context);
  const bound = returned && cppTemplateBound(returned, found.node, { ...type, text: written }, at, context);
  if (!bound) return null;
  if (arrow.length === 0) return { ...bound, text: bound.text.replace(/&+\s*$/, '').trim() };
  return cppPointee(bound) ?? cppOperatorTarget(bound, at, context, hops + 1);
}

/**
 * The type `returned`, which the class template `cls` writes, with `cls`'s
 * own template parameters bound to the arguments of `type`, a specialization
 * of it: the `T*` of `UnownedPtr<T>` is a `DB*` for an `UnownedPtr<DB>`. An
 * alias the class declares (`pointer`) is followed first, and an argument is
 * looked up where `type` is written. A type of a class that is no template
 * comes back as written; null for a parameter `type` doesn't bind.
 */
function cppTemplateBound(returned: CppWrittenType, cls: Node, type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  const params = cppOwnTemplateParameters(cls, context);
  if (params.length === 0) return returned;
  const args = cppTemplateArguments(type.text) ?? [];
  const followed = cppFollowWrittenAliases(returned, at, context) ?? returned;
  const core = followed.text.replace(/\b(?:const|volatile|typename)\b|[*&]/g, ' ').trim();
  const index = params.indexOf(core);
  if (index >= 0) {
    const arg = args[index]?.trim();
    return arg ? { ...type, text: followed.text.replace(new RegExp(`\\b${core}\\b`), arg) } : null;
  }
  let text = followed.text;
  params.forEach((param, i) => {
    const arg = args[i]?.trim();
    if (param && arg) text = text.replace(new RegExp(`\\b${param}\\b`, 'g'), arg);
  });
  return { ...followed, text };
}

/**
 * What dereferencing a value of the type `type` gives, for `*x` and `x->`:
 * an array's first element, what a pointer points at or a holder holds
 * (cppPointee), or the element a container's iterator points at
 * (cppIteratorTarget) — the `Node*` of `*nodes.begin()` over a
 * `std::vector<Node*>`.
 */
function cppDereferenced(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  if (type.array) return cppArrayElement(type);
  return cppPointee(type) ?? cppIteratorTarget(type, at, context);
}

/** Whether the holder `raw` names (cppHeldType) is the library's: no type of the project's has its name. */
function isCppLibraryHolder(raw: string, context: ResolutionContext): boolean {
  const spelled = cppTypeSegments(raw)!.join('::');
  return !cppTypesNamed(cppLastSegment(spelled), context).some((n) => n.qualifiedName === spelled || n.qualifiedName.endsWith(`::${spelled}`));
}

/**
 * A `->` call on a C++ receiver declared as a standard smart pointer, an
 * optional or an `absl::StatusOr` (`std::unique_ptr<Iterator> iter;
 * iter->Valid()`, protobuf's `absl::StatusOr<FeatureResolver> resolver;
 * resolver->MergeFeatures(…)`), or as a container's iterator
 * (`std::deque<Slice>::const_iterator it; it->data()`), calls a member of
 * the type it holds or points at (cppArrowTarget, which says where that is
 * read: an iterator rocksdb's `auto it = logs_.begin()` gets has the element
 * the class's `logs_` is written with). That type is looked up as C++ looks
 * it up there (cpp-supertypes.ts): the scopes around it, the file's
 * `using`s, and aliases followed. Looking it up by its last name instead
 * finds namesakes: 21 other classes in rocksdb are named `Iterator`, nested
 * ones like `MemTableRep::Iterator`, while the `Iterator` the call means
 * inherits `Valid` from `IteratorBase`.
 *  - The member of the class it names, or of a class that class derives from.
 *  - null when no project method is called: the type is a template
 *    parameter's, a library type (`std::unique_ptr<std::deque<…>>`) or an
 *    alias of one, or a class that surely lacks the method (cppLacksMethod:
 *    not when a class template's specialization or a base the index doesn't
 *    link may declare it).
 *  - undefined when `raw` declares no such holder or iterator, or the type
 *    it holds is none the project declares (a generated message, a class the
 *    index doesn't name): the call goes on as before.
 */
function matchCppHeldTypeCall(
  raw: string,
  methodName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  declared?: CppWrittenType,
): ResolvedRef | null | undefined {
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller) return undefined;
  const target = cppArrowTarget(raw, cppCallSite(caller, ref, context), declared, ref, context);
  if (!target || isCppPointerType(target.text)) return undefined;
  const held = target.text;
  if (isCppLibraryType(held, context)) return null;
  // A template parameter's type (`std::unique_ptr<T>`, `typename T::Iter`) names no particular class: null.
  const found = cppClassWritten(held, target, ref, context);
  if (found === undefined) return undefined;
  if (found === null) return null;
  if (!CPP_CLASS_KINDS.has(found.node.kind)) {
    // An alias that leads to none of the project's classes. When it names a
    // library type (`using VectorWalPtr = std::vector<…>;`) or a template
    // parameter's, nothing of the project's is called. Otherwise it may be one
    // each `#if` arm declares differently (rocksdb's `port::Thread`, a
    // `std::thread` or a `WindowsThread`) or name a class the index keeps
    // under another namespace (protobuf's `MapField`): no telling.
    const aliased = resolveCppAliasedType(held, ref, context);
    return aliased === null || (aliased && isCppLibraryType(aliased.target.join('::'), context)) ? null : undefined;
  }
  const method = cppMethodOf(found.node, methodName, ref, context);
  if (method) return { original: ref, targetNodeId: method.id, confidence: found.exact ? 0.9 : 0.85, resolvedBy: 'instance-method' };
  return cppLacksMethod(found.node, context) ? null : undefined;
}

const CPP_CLASS_KINDS: ReadonlySet<string> = new Set(['class', 'struct', 'union']);

/**
 * Where a type the calling function writes is looked up from: the function
 * itself, so a class local to it is found first, then — in a gtest `TEST_F`
 * or `TEST_P` body — the test's fixture (cppTestFixture) and its bases, as
 * for the member function of a class derived from it that the body is:
 * rocksdb's `new TestUserDefinedIndexFactory()` is the fixture base's own.
 */
function cppCallSite(caller: Node, ref: UnresolvedRef, context: ResolutionContext): CppNameSite {
  const fixture = cppTestFixture(caller, ref, context);
  return {
    scope: caller.kind === 'file' ? '' : caller.qualifiedName,
    file: ref.filePath,
    line: ref.line,
    parameters: cppTemplateParameters(caller, context),
    ...(fixture ? { classScope: fixture } : {}),
  };
}

/**
 * A C++ member call on a receiver the calling function or its class declares
 * — `Iterator* iter; iter->Valid()`, `const Slice& key; key.size()` — with the
 * operator that declaration takes (`->` on a pointer, `.` on a value or
 * reference) calls a member of the class the declared type names, looked up as
 * for a smart pointer's held type (matchCppHeldTypeCall); a type named through
 * an alias is the class the alias names. The type's last name alone finds
 * namesakes: rocksdb's `Iterator* iter; iter->Valid()` reached
 * `MemTableRep::Iterator::Valid`, one of 22 classes named `Iterator`, while the
 * `Iterator` the code means inherits `Valid` from `IteratorBase`.
 *  - The member of that class, or of a class it derives from.
 *  - null when that class surely has no such method (cppLacksMethod):
 *    protobuf's descriptor accessors aren't indexed, and `field->full_name()`
 *    reached unrelated classes' by the method's name.
 *  - null when the type is from outside the project, whatever class of the
 *    project shares its name: a standard or abseil one with a lowercase name
 *    (isCppLibraryType) — leveldb's `std::string data_; data_.data()` reached
 *    `Slice::data`, and fmt declares an `ostream` of its own with a `flush` —
 *    or one under a namespace the project declares nothing in: protobuf's
 *    `absl::Status status; status.ok()` reached `upb::Status::ok`.
 *  - undefined when the declaration may be another variable's (read from
 *    elsewhere, past one of the receiver the scan couldn't read, or not taking
 *    that operator), or the lookup doesn't place the type: a template
 *    parameter's, an alias of a type outside the project, a name nothing the
 *    file sees declares, or one only the class of that name the file can see
 *    shares (rocksdb's out-of-line `InlineSkipList<C>::Node` is indexed
 *    unnamed, so its `Node` matched `FlushScheduler::Node`). The call goes on
 *    as before.
 */
function matchCppDeclaredTypeCall(
  receiver: string,
  methodName: string,
  decl: CppReceiverDeclaration,
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null | undefined {
  if (!decl.callers || decl.shadowed || !decl.raw) return undefined;
  if (cppMemberOperator(receiver, ref, context) !== (decl.pointer ? '->' : '.')) return undefined;
  // (Not so for `->` on a value — a smart pointer, optional or iterator hands
  // the call to its element type — which the operator check above leaves be.)
  if (!decl.aliased && isCppLibraryType(decl.raw, context)) return null;
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller) return undefined;
  // An alias was followed from the calling function, through typedefs of its
  // own the index doesn't hold: the class it names, by its qualified name.
  const aliasedClass = decl.alias && cppAliasedClass(decl.alias, context);
  if (decl.aliased && !aliasedClass) return undefined;
  // A type the calling function doesn't write is looked up where it is
  // written: where an `auto` variable's range or initializer gets it, or in
  // a data member's class.
  const site = decl.declared ?? cppCallSite(caller, ref, context);
  const found = cppClassWritten(aliasedClass ? `::${aliasedClass}` : decl.raw, site, ref, context);
  if (found === undefined && !aliasedClass && isCppOutsideQualifiedType(decl.raw, site, context)) return null;
  if (!found?.exact || !CPP_CLASS_KINDS.has(found.node.kind)) return undefined;
  const method = cppMethodOf(found.node, methodName, ref, context);
  if (method) return { original: ref, targetNodeId: method.id, confidence: 0.9, resolvedBy: 'instance-method' };
  return cppLacksMethod(found.node, context) ? null : undefined;
}

/**
 * Is a C++ `->` call on `receiver` made on a value — not a pointer — of a
 * type from outside the project that nothing the file sees declares
 * (isCppOutsideQualifiedType)? Its `operator->` hands the call to a type the
 * declared one only wraps (`absl::StatusOr<Any>`'s `Any`), so the declared
 * type's last name names no class the method is in. (A smart pointer, an
 * optional or an `absl::StatusOr` holding one of the project's classes is
 * matchCppHeldTypeCall's.)
 */
function isCppArrowThroughOutsideType(receiver: string, decl: CppReceiverDeclaration, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!decl.callers || decl.shadowed || !decl.raw || decl.pointer || decl.aliased) return false;
  if (cppMemberOperator(receiver, ref, context) !== '->' || isCppLibraryType(decl.raw, context)) return false;
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller) return false;
  const site = decl.declared ?? cppCallSite(caller, ref, context);
  return cppClassWritten(decl.raw, site, ref, context) === undefined && isCppOutsideQualifiedType(decl.raw, site, context);
}

/**
 * Is the C++ type `raw`, which nothing the file sees declares, written under
 * a namespace the project declares no type in — `absl::Status`,
 * `grpc::ServerContext` — so that it is from outside the project? Not when
 * that first name is a template parameter or a namespace alias. A lowercase
 * name, and anything of `std`, is isCppLibraryType's to tell: a trait or a
 * member type may name one of the project's (`std::conditional_t<kFlag,
 * void*, Slice>`, `std::vector<Slice>::value_type`).
 */
function isCppOutsideQualifiedType(raw: string, site: CppNameSite, context: ResolutionContext): boolean {
  const segments = cppTypeSegments(raw);
  if (!segments || segments.length < 2) return false;
  const head = segments[0]!;
  if (head === 'std' || !/^[A-Z]/.test(segments[segments.length - 1]!)) return false;
  if (site.parameters.has(head) || cppNamespaceAliases(context).has(head)) return false;
  if (cppMacroNamespaceFrames(site.file, context).some((frame) => frame.path.includes(head))) return false;
  return !cppProjectScopeNames(context).has(head);
}

/**
 * Is every class the last name of a C++ type written with a namespace
 * qualifier finds — `absl::Status`, protobuf's generated
 * `DescriptorProto::ExtensionRange` — a namesake, none of them a class that
 * qualified name can be? That is so when the project has C or C++ types of
 * that last name, or owners of a `method` of that name (the index can hold a
 * class's methods without the class), and each one's qualified name ends
 * unlike the written one, neither the other's tail. C++ name lookup only adds
 * scopes in front of what is written, and the index leaves some out of a name
 * (one a macro opens, one a parse error lost). A namespace alias stands for
 * what it names, and a macro that names a namespace (`ROCKSDB_NAMESPACE`) for
 * that namespace. A `std::` name is the very name or none of the project's:
 * a global `string` class is no `std::string`. Never so for a name one of the
 * project's types qualifies, for an unqualified name, or for the end of a
 * declaration begun on an earlier line.
 */
function cppFindsOnlyNamesakes(raw: string, context: ResolutionContext, method?: string): boolean {
  if ((raw.match(/</g)?.length ?? 0) !== (raw.match(/>/g)?.length ?? 0)) return false;
  const segments = cppTypeSegments(raw);
  if (!segments || segments.length < 2) return false;
  if (segments.slice(0, -1).some((s) => cppTypesNamed(s, context).length > 0)) return false;
  const name = segments[segments.length - 1]!;
  const alias = cppNamespaceAliases(context).get(segments[0]!);
  const written = [segments, ...(alias ? [[...alias.split('::'), ...segments.slice(1)]] : [])]
    .flatMap((s) => cppNamespaceSpellings(s.join('::'), context));
  const std = segments[0] === 'std';
  const fits = (owner: string): boolean => written.some((w) =>
    owner === w || owner.endsWith(`::${w}`) || (!std && w.endsWith(`::${owner}`)));
  const owners = cppTypesNamed(name, context).map((n) => n.qualifiedName);
  if (method) {
    const methods = context.getMethodMatches?.(name, method, 'cpp') ?? context.getNodesByName(method).filter((m) =>
      m.kind === 'method' && sameLanguageFamily(m.language, 'cpp') && `::${m.qualifiedName}`.endsWith(`::${name}::${method}`));
    for (const m of methods) owners.push(m.qualifiedName.slice(0, m.qualifiedName.length - method.length - 2));
  }
  return owners.length > 0 && !owners.some((owner) => cppNamespaceSpellings(owner, context).some(fits));
}

/**
 * A C++ qualified name as it is spelled, and with a macro that names a
 * namespace read as that namespace: `ROCKSDB_NAMESPACE::DB` is `rocksdb::DB`.
 */
function cppNamespaceSpellings(qualified: string, context: ResolutionContext): string[] {
  const macros = cppNameMacros(context);
  if (macros.size === 0) return [qualified];
  const named = qualified.split('::').map((s) => macros.get(s) ?? s).join('::');
  return named === qualified ? [qualified] : [qualified, named];
}

/** Is a C++ type written as a member of a template parameter where `ref` is made (`typename PolicyT::Payload`)? */
function isCppTemplateMember(raw: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const head = cppTypeSegments(raw)?.[0];
  const caller = context.getNodeById?.(ref.fromNodeId);
  return head !== undefined && !!caller && cppTemplateParameters(caller, context).has(head);
}

const CPP_SCOPE_NAMES = new WeakMap<ResolutionContext, Set<string>>();

/**
 * Every name in the qualified names of the types the project's C and C++
 * code declares — a namespace (`google`, `ROCKSDB_NAMESPACE`), a class,
 * whatever a qualifier may start with from some scope — and in the
 * namespaces its macros open (`fmt` for `FMT_BEGIN_NAMESPACE`), which no
 * qualified name shows. A macro that stands for a name (`#define
 * ROCKSDB_NAMESPACE rocksdb`) brings the other: rocksdb's types are
 * `ROCKSDB_NAMESPACE::DB` in the index and `rocksdb::DB` to code that names
 * them. (Not those of functions: protobuf's conversion operators read as
 * methods named `google::protobuf::absl::Cord`.)
 */
function cppProjectScopeNames(context: ResolutionContext): Set<string> {
  const hit = CPP_SCOPE_NAMES.get(context);
  if (hit) return hit;
  const names = new Set(cppMacroNamespaceHeads(context));
  for (const kind of ['class', 'struct', 'union', 'enum', 'type_alias'] as const) {
    for (const n of context.iterateNodesByKind?.(kind) ?? context.getNodesByKind(kind)) {
      if (n.language !== 'cpp' && n.language !== 'c') continue;
      for (const segment of n.qualifiedName.split('::')) if (segment) names.add(segment);
    }
  }
  for (const [macro, name] of cppNameMacros(context)) {
    if (names.has(macro)) names.add(name);
    else if (names.has(name)) names.add(macro);
  }
  CPP_SCOPE_NAMES.set(context, names);
  return names;
}

/**
 * Whether a C++ class with no method of a name, its own or one it inherits
 * through its base edges, surely has none: it is no class template, whose
 * specializations may declare members the template doesn't, and every base on
 * the way is one the walk follows (cppBasesKnown).
 */
function cppLacksMethod(cls: Node, context: ResolutionContext): boolean {
  return cppTemplateParameters(cls, context).size === 0 && cppBasesKnown(cls, context);
}

/**
 * Whether every base C++ class `cls` writes, and every base of those, is one
 * cppMethodOf walks — a base edge to a class — or a library type such as
 * `std::runtime_error`, which declares no project method. A base the index
 * doesn't link may declare any method: protobuf's `FlatAllocator` derives
 * from a `decltype(…)` that names `FlatAllocatorImpl`, and rocksdb's
 * `WritePreparedTxnDB` from an alias each `#if` arm declares differently.
 */
function cppBasesKnown(cls: Node, context: ResolutionContext, depth = 0, seen = new Set<string>()): boolean {
  if (seen.has(cls.qualifiedName)) return true;
  seen.add(cls.qualifiedName);
  if (!context.getSupertypeNodes) return false;
  for (const decl of context.getNodesByQualifiedName(cls.qualifiedName)) {
    if ((decl.language !== 'cpp' && decl.language !== 'c') || !CPP_CLASS_KINDS.has(decl.kind)) continue;
    const bases = context.getSupertypeNodes(decl.id);
    const written = cppBaseSpecifiers(decl, context).filter((s) => !isCppLibraryType(s, context));
    // (cppMethodOf looks no deeper than this.)
    if (depth >= 4 ? bases.length + written.length > 0 : written.length > bases.length) return false;
    for (const base of bases) {
      if (!CPP_CLASS_KINDS.has(base.kind) || !cppBasesKnown(base, context, depth + 1, seen)) return false;
    }
  }
  return true;
}

/**
 * C++ class `cls`'s method `name`: its own — of its overloads, the one the
 * call's arguments fit (cppOverloadFor), and of a member template's explicit
 * specializations, the one its template arguments name (cppSpecializationPool;
 * null when it names none of them and they are all `cls` has) — else the
 * nearest one of a class it derives from, through the base edges every
 * declaration of `cls` has.
 * When other classes share `cls`'s qualified name, its own are the ones
 * defined in its body, else where it is: the local classes of gtest bodies
 * in one namespace are each `ns::TEST_F::Listener`, and leveldb's
 * db_bench.cc and db_bench_sqlite3.cc each declare a `RandomGenerator`, with
 * a `Generate` that takes a `size_t` and an `int`. (A chained call
 * `inner(…).name(…)` keeps the first: the arguments at its position are the
 * inner call's.)
 */
function cppMethodOf(cls: Node, name: string, ref: UnresolvedRef, context: ResolutionContext, depth = 0, seen = new Set<string>()): Node | null {
  const want = `${cls.qualifiedName}::${name}`;
  const named = context.getMethodMatches?.(cls.name, name, ref.language) ??
    context.getNodesByName(name).filter((n) => n.kind === 'method' && sameLanguageFamily(n.language, ref.language));
  const family = named.filter((n) => n.qualifiedName === want);
  const own = cppQualifierSpecializationPool(cppSpecializationPool(family, ref, context), ref, context);
  // Specializations of the class's own member template, none the call's:
  // what C++ finds is the template, which has no body here.
  if (own.length === 0 && family.length > 0) return null;
  if (own.length > 0) {
    const ordered = preferCallSiteFile(cppVisibleFirst(own, ref, context), ref.filePath);
    if (ref.referenceName.includes('().')) return ordered[0]!;
    const namesakes = cppClassDecls(cls.qualifiedName, context).length > 1;
    const inBody = namesakes
      ? ordered.filter((n) => n.filePath === cls.filePath && n.startLine >= cls.startLine && n.endLine <= cls.endLine)
      : [];
    const defined = inBody.length > 0 ? inBody : namesakes
      ? ordered.filter((n) => n.filePath === cls.filePath || cppIncluders(cls.filePath, context).has(n.filePath))
      : ordered;
    return cppOverloadFor(defined.length > 0 ? defined : ordered, name, ref, context);
  }
  seen.add(cls.qualifiedName);
  if (depth >= 4 || !context.getSupertypeNodes) return null;
  for (const decl of context.getNodesByQualifiedName(cls.qualifiedName)) {
    if ((decl.language !== 'cpp' && decl.language !== 'c') || !CPP_CLASS_KINDS.has(decl.kind)) continue;
    for (const base of context.getSupertypeNodes(decl.id)) {
      if (!CPP_CLASS_KINDS.has(base.kind) || seen.has(base.qualifiedName)) continue;
      const inherited = cppMethodOf(base, name, ref, context, depth + 1, seen);
      if (inherited) return inherited;
    }
  }
  return null;
}

/**
 * A C++ call written with no receiver, or on `this` (`this->Clear()`,
 * `(*this).Clear()`), in a member function — or in a lambda in one, whose
 * calls the extractor gives to the function — calls what C++ name lookup
 * finds there: a member of the function's class, else of a class it derives
 * from, else of a class it is nested in, before anything at namespace scope.
 * By its name alone, protobuf's generated `Api::operator=` calling
 * `InternalSwap(&from)` reached `Any::InternalSwap`, and `Any::InternalSwap`
 * calling the `GetArena()` it inherits from `MessageLite` reached
 * `Arena::InternalHelper::GetArena`.
 *  - Bases are the class's own base edges, so a namesake class elsewhere
 *    lends it nothing. A bare call skips a base that depends on the class's
 *    template parameters, which C++ doesn't look in (`this->` is how such a
 *    member is called).
 *  - `this` is an object of the innermost class: never an enclosing class's.
 *  - A parameter or local the function declares before a bare call is what
 *    it calls: `void Set(Callback callback) { callback(); }`.
 *  - A class that may declare the name through a macro (`Get##name`), which
 *    no node shows, ends the walk.
 * Undefined when the call is not of that shape or no class on the way has a
 * method of that name in the index — a free function, `static` or not, has
 * no class; a base outside the project lends no node: the name strategies
 * decide, as before.
 */
function matchCppImplicitThisCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | undefined {
  const name = ref.referenceName;
  if (ref.referenceKind !== 'calls' || !/^[A-Za-z_]\w*$/.test(name)) return undefined;
  const receiver = cppImplicitReceiver(ref, context);
  if (receiver === null) return undefined;
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller) return undefined;
  const found = cppImplicitThisMethod(name, receiver, caller, ref, context);
  // (A recursive call names the function itself, which no local shadows.)
  if (!found || (receiver === 'bare' && name !== caller.name && isCppLocalName(name, caller, ref, context))) return undefined;
  return { original: ref, targetNodeId: found.id, confidence: 0.9, resolvedBy: 'instance-method' };
}

/**
 * The method a C++ call of `name` written with no receiver, or on `this`,
 * reaches from `caller` by C++ lookup (matchCppImplicitThisCall): of the
 * caller's class, a class it derives from, or one it is nested in. A gtest
 * `TEST_F(Fixture, …)` or `TEST_P` body is a method of a class gtest derives
 * from `Fixture`, so the fixture's methods are its own: rocksdb's tests call
 * `DBTestBase`'s `Put(…)` and `NewIterator(…)` bare. Undefined when the
 * caller is no member function, or no class on the way has a method of that
 * name in the index. (Whether a local of the caller's shadows it is the
 * caller's to ask.)
 */
function cppImplicitThisMethod(name: string, receiver: 'bare' | 'this', caller: Node, ref: UnresolvedRef, context: ResolutionContext): Node | undefined {
  const owner = cppMemberOwner(caller, context) ?? cppTestFixture(caller, ref, context);
  if (owner === null) return undefined;
  let found: Node | null | undefined = null;
  for (const scope of cppEnclosingClasses(owner, caller, context)) {
    found = cppScopeMethod(scope, name, receiver, ref, context);
    if (found !== null || receiver === 'this') break;
  }
  return found ?? undefined;
}

/** `this->` / `(*this).` before a member's name, with a `template` keyword after it. */
const CPP_THIS_RECEIVER = /^(?:this\s*->|\(\s*\*\s*this\s*\)\s*\.)\s*(?:template\s+)?/;

/**
 * How a C++ call the extractor recorded by its bare name is written, read at
 * its column: `'bare'` with no receiver, `'this'` on `this->` / `(*this).`,
 * null for anything else. The extractor also drops receivers it can't spell
 * (`arr_[0].Foo()`, `(p_)->Foo()`, `this->p_->Foo()`), whose calls are no
 * member of the caller's class; and a name its argument list doesn't follow
 * is no call of it.
 */
function cppImplicitReceiver(ref: UnresolvedRef, context: ResolutionContext): 'bare' | 'this' | null {
  const line = (context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/))?.[ref.line - 1];
  if (line === undefined) return null;
  const at = (column: number): 'bare' | 'this' | null => {
    const text = line.slice(column);
    const self = CPP_THIS_RECEIVER.exec(text)?.[0] ?? '';
    const before = line.slice(0, column).replace(/\s+$/, '');
    // A column past the receiver: on `this`, or some other object's call.
    const onThis = self !== '' || /(?:^|[^\w$])(?:this\s*->|\(\s*\*\s*this\s*\)\s*\.)$/.test(before);
    if (!onThis && /(?:\.|->|::)$/.test(before)) return null;
    const rest = text.slice(self.length);
    if (!rest.startsWith(ref.referenceName) || /[\w$]/.test(rest.charAt(ref.referenceName.length))) return null;
    return cppArgumentListFollows(rest, ref.referenceName.length) ? (onThis ? 'this' : 'bare') : null;
  };
  const verdict = at(Math.max(0, ref.column));
  if (verdict !== null || !/[^\x00-\x7f]/.test(line)) return verdict;
  const index = cppUtf8Column(line, ref.column);
  return index === null ? null : at(index);
}

/**
 * Where in `line` a call's `column` is when it counts UTF-8 bytes, which
 * wider characters before the call outnumber. Null when no character starts
 * there, or the two agree.
 */
function cppUtf8Column(line: string, column: number): number | null {
  let bytes = 0;
  let index = 0;
  while (index < line.length && bytes < column) {
    const point = line.codePointAt(index)!;
    bytes += point < 0x80 ? 1 : point < 0x800 ? 2 : point < 0x10000 ? 3 : 4;
    index += point > 0xffff ? 2 : 1;
  }
  return bytes === column && index !== column ? index : null;
}

/**
 * A call's receiver the extractor drops, at the start of `text` (its literals
 * blanked) up to the member's name: a variable or a dereferenced one
 * (`(*it)`), then what the extractor can't spell — subscripts
 * (`statuses[i]`, `(*m)[key]`) and the member of a pair (`it->second`,
 * `cfs[i].first`) — and the operator. Null when the variable has none of it
 * (the extractor spells `it.Flush()`), it is `(*this)` alone
 * (cppImplicitReceiver's), or a subscript doesn't close.
 */
function cppUnspelledReceiverText(text: string): { expression: string; op: string; length: number } | null {
  const head = /^(?:\(\s*\*\s*([A-Za-z_]\w*)\s*\)|[A-Za-z_]\w*)/.exec(text);
  if (!head) return null;
  let end = head[0].length;
  let unspelled = head[1] !== undefined && head[1] !== 'this';
  for (let open = /^\s*\[/.exec(text.slice(end)); open; open = /^\s*\[/.exec(text.slice(end))) {
    const close = cppClosingBracket(text, end + open[0].length - 1);
    if (close < 0) return null;
    end = close + 1;
    unspelled = true;
  }
  const member = /^\s*(?:->|\.)\s*(?:first|second)\b/.exec(text.slice(end));
  if (member) {
    end += member[0].length;
    unspelled = true;
  }
  const op = unspelled ? /^\s*(->|\.)\s*(?:template\s+)?/.exec(text.slice(end)) : null;
  return op ? { expression: text.slice(0, end).trim(), op: op[1]!, length: end + op[0].length } : null;
}

/**
 * The receiver a C++ call the extractor recorded by its bare name is made
 * on, when cppUnspelledReceiverText reads one, with the operator — `(*it)`
 * and `->` for `(*it)->Visit()`, `it->second` and `.` for
 * `it->second.Flush()`, `statuses[i]` and `.` for `statuses[i].ok()` — read
 * at the call's column, where the receiver starts. Null for any other call.
 */
function cppUnspelledReceiver(ref: UnresolvedRef, context: ResolutionContext): { expression: string; op: string } | null {
  const raw = (context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/))?.[ref.line - 1];
  const line = raw === undefined ? null : cppCodeOf(cppLiteralsBlanked(raw, ref.line, cppNonCodeLines(ref.filePath, context)));
  if (!line) return null;
  const at = (column: number): { expression: string; op: string } | null => {
    const text = line.slice(column);
    const receiver = cppUnspelledReceiverText(text);
    if (!receiver) return null;
    const rest = text.slice(receiver.length);
    if (!rest.startsWith(ref.referenceName) || /[\w$]/.test(rest.charAt(ref.referenceName.length))) return null;
    return cppArgumentListFollows(rest, ref.referenceName.length) ? { expression: receiver.expression, op: receiver.op } : null;
  };
  const found = at(Math.max(0, ref.column));
  if (found || !/[^\x00-\x7f]/.test(line)) return found;
  const index = cppUtf8Column(line, ref.column);
  return index === null ? null : at(index);
}

/** A member chain and the operator after it: `props->rep.db_id` and `.`, `this->mu_` and `->`. */
const CPP_MEMBER_CHAIN = /^([A-Za-z_]\w*(?:\s*(?:\.|->)\s*[A-Za-z_]\w*)*)\s*(\.|->)\s*(?:template\s+)?/;

/**
 * The member chain a C++ call the extractor recorded by its bare name is made
 * on, with the operator after it — `options.cf_paths` and `.` for
 * `options.cf_paths.emplace_back(…)`, `props->rep.db_id` and `.` for
 * `props->rep.db_id.size()` — read at the call's column, where the chain
 * starts. Null for any other call, a receiver of one name among them (the
 * extractor spells those).
 */
function cppMemberChainReceiver(ref: UnresolvedRef, context: ResolutionContext): { expression: string; op: string } | null {
  const raw = (context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/))?.[ref.line - 1];
  const line = raw === undefined ? null : cppCodeOf(cppLiteralsBlanked(raw, ref.line, cppNonCodeLines(ref.filePath, context)));
  if (!line) return null;
  const at = (column: number): { expression: string; op: string } | null => {
    const chain = CPP_MEMBER_CHAIN.exec(line.slice(column));
    if (!chain || !/\.|->/.test(chain[1]!)) return null;
    const rest = line.slice(column + chain[0].length);
    if (!rest.startsWith(ref.referenceName) || /[\w$]/.test(rest.charAt(ref.referenceName.length))) return null;
    return cppArgumentListFollows(rest, ref.referenceName.length) ? { expression: chain[1]!, op: chain[2]! } : null;
  };
  const found = at(Math.max(0, ref.column));
  if (found || !/[^\x00-\x7f]/.test(line)) return found;
  const index = cppUtf8Column(line, ref.column);
  return index === null ? null : at(index);
}

/**
 * A C++ call on a data member reached through a member chain, which the
 * extractor records by its bare name, calls a member of the class that
 * member's type names, looked up as C++ looks it up where the type is
 * written (cppMemberObject reads each member's declared type in its class).
 * By its bare name the call went to whichever class had a method of that
 * name, or, in a method, to the method's own class: rocksdb's
 * `thread->rnd.Next()` on a `Random rnd` reached `ArenaWrappedDBIter::Next`,
 * `meta.smallest.user_key()` on an `InternalKey` `ClippingIterator::user_key`,
 * and `options.cf_paths.emplace_back(…)` on a `std::vector<DbPath>`
 * `autovector::emplace_back`. Unlike a call chain's, a member chain's
 * operator is read where it is written, so a library template of a template
 * parameter is no matter: `.` calls a member of `std::vector<T>` itself, and
 * `->` on a `std::unique_ptr<T>` one of `T`.
 *  - The member of that class, or of a class it derives from.
 *  - null when no project method is called: a type from outside the project,
 *    a library type (isCppLibraryType) or one under a namespace the project
 *    declares nothing in (isCppOutsideQualifiedType); a template parameter's
 *    type the calling function writes; or a class that surely lacks the
 *    method (cppLacksMethod).
 *  - undefined for any other call, or a member whose type can't be read or
 *    placed: the name strategies decide, as before.
 */
function matchCppMemberChainCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const receiver = cppMemberChainReceiver(ref, context);
  if (!receiver) return undefined;
  const object = cppMemberObject(receiver.expression, receiver.op, ref, context, 0);
  if (!object || isCppPointerType(object.text)) return undefined;
  if (isCppLibraryType(object.text, context)) return null;
  const found = cppClassWritten(object.text, object, ref, context);
  if (found === undefined) return isCppOutsideQualifiedType(object.text, object, context) ? null : undefined;
  // (As for an unspelled receiver: a template parameter another template
  // writes is what the call's specialization makes it.)
  if (found === null) return isCppTemplateParameterType(object) && object.scope !== context.getNodeById?.(ref.fromNodeId)?.qualifiedName ? undefined : null;
  if (!found.exact || !CPP_CLASS_KINDS.has(found.node.kind)) return undefined;
  const method = cppMethodOf(found.node, ref.referenceName, ref, context);
  if (method) return { original: ref, targetNodeId: method.id, confidence: 0.9, resolvedBy: 'instance-method' };
  return cppLacksMethod(found.node, context) ? null : undefined;
}

/**
 * A C++ call the extractor recorded by its bare name on a receiver it drops
 * (cppUnspelledReceiver) — `(*it)->Visit()` over a `std::vector<Node*>`,
 * `(*node).Weight()` on a `Node*`, `it->second.Flush()` through a map's
 * iterator — calls a member of the class that receiver has
 * (cppMemberObject), looked up as C++ looks it up where that type is
 * written. By its bare name the call went to whichever class had a method of
 * that name.
 *  - The member of that class, or of a class it derives from.
 *  - null when no project method is called: a library type (`(*it).size()`
 *    over a `std::vector<std::string>`, `it->second.size()` on a map of
 *    strings), a template parameter's, or a class that surely lacks the
 *    method (cppLacksMethod).
 *  - undefined when the call is on no such receiver, or its type can't be
 *    read or placed: the name strategies decide, as before.
 */
function matchCppUnspelledReceiverCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const receiver = cppUnspelledReceiver(ref, context);
  if (!receiver) return undefined;
  const object = cppMemberObject(receiver.expression, receiver.op, ref, context, 0);
  if (!object || isCppPointerType(object.text)) return undefined;
  if (isCppLibraryType(object.text, context)) return null;
  const found = cppClassWritten(object.text, object, ref, context);
  if (found === undefined) return undefined;
  // A template parameter's type names no particular class when the calling
  // function writes it; one another template writes is what the call's
  // specialization makes it — rocksdb's `CoreLocalArray<T>` returns a
  // `std::pair<T*, size_t>` from `AccessElementAndIndex()` — so the call
  // goes on as before.
  if (found === null) return isCppTemplateParameterType(object) && object.scope !== context.getNodeById?.(ref.fromNodeId)?.qualifiedName ? undefined : null;
  if (!found.exact || !CPP_CLASS_KINDS.has(found.node.kind)) return undefined;
  const method = cppMethodOf(found.node, ref.referenceName, ref, context);
  if (method) return { original: ref, targetNodeId: method.id, confidence: 0.9, resolvedBy: 'instance-method' };
  return cppLacksMethod(found.node, context) ? null : undefined;
}

/** Whether `text` from `from` on is an argument list, after any template arguments (`<Foo, 3>(`). */
function cppArgumentListFollows(text: string, from: number): boolean {
  let i = from;
  while (i < text.length && /\s/.test(text[i]!)) i++;
  if (text[i] === '<') {
    let depth = 0;
    for (; i < text.length; i++) {
      const c = text[i]!;
      if (c === '<') depth++;
      else if (c === '>' && --depth === 0) break;
      else if (c === ';' || c === '{' || c === '}') return false;
    }
    if (depth !== 0) return false;
    i++;
    while (i < text.length && /\s/.test(text[i]!)) i++;
  }
  return text[i] === '(';
}

/** The C and C++ class, struct and union declarations of a qualified name. */
function cppClassDecls(qualifiedName: string, context: ResolutionContext): Node[] {
  return context.getNodesByQualifiedName(qualifiedName).filter((n) =>
    CPP_CLASS_KINDS.has(n.kind) && (n.language === 'cpp' || n.language === 'c'));
}

/**
 * The qualified name of the class whose scope a C++ caller's body is in: a
 * member function's, defined in the class or out of line (`void
 * Api::InternalSwap(…) {…}`), static or not — or a class's own, for code in
 * its body. A function node counts only when its definition is written
 * `Class::name(…)`. Null for a free function, and for one defined through a
 * namespace (`void detail::helper() {}` is a method node of no class).
 */
function cppMemberOwner(caller: Node, context: ResolutionContext): string | null {
  if (CPP_CLASS_KINDS.has(caller.kind)) return caller.qualifiedName;
  if (caller.kind !== 'method' && caller.kind !== 'function') return null;
  const cut = caller.qualifiedName.lastIndexOf('::');
  if (cut <= 0) return null;
  const owner = caller.qualifiedName.slice(0, cut);
  if (caller.kind === 'function') {
    const lines = context.getFileLines?.(caller.filePath) ?? context.readFile(caller.filePath)?.split(/\r?\n/);
    const head = lines?.slice(caller.startLine - 1, caller.startLine + 2).join(' ') ?? '';
    const cls = cppLastSegment(owner).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const fn = caller.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (!new RegExp(`\\b${cls}\\s*(?:<[^<>;{}]*>\\s*)?::\\s*~?${fn}\\s*\\(`).test(head)) return null;
  }
  if (cppClassDecls(owner, context).length > 0) return owner;
  // A class declared in another and defined elsewhere, which the index has
  // no node for: protobuf's `Any::_Internal`, declared in `Any`.
  const outer = owner.lastIndexOf('::');
  return outer > 0 && cppClassDecls(owner.slice(0, outer), context).length > 0 ? owner : null;
}

/** One class C++ lookup passes through, with the declarations that are the class there. */
interface CppClassScope {
  qualifiedName: string;
  decls: Node[];
  /** `decls[0]` holds the code the lookup starts from. */
  holds: boolean;
  /** Other classes of that qualified name were left out: another translation unit's. */
  narrowed: boolean;
}

/**
 * The classes a C++ caller's name lookup passes through, innermost first:
 * the caller's class, then each class it is nested in. After a class
 * declared in a function body comes that function's class. Several classes
 * can share a qualified name — another translation unit's local fixture or
 * helper — so each scope keeps only the declaration holding the code, else
 * those in its file, else those its file includes, else all of them.
 */
function cppEnclosingClasses(owner: string, caller: Node, context: ResolutionContext): CppClassScope[] {
  const scopes: CppClassScope[] = [];
  let qualifiedName = owner;
  let inner = caller;
  for (let hops = 0; hops < 8 && qualifiedName !== ''; hops++) {
    const decls = cppClassDecls(qualifiedName, context);
    if (decls.length === 0 && hops > 0) {
      // A namespace: lookup leaves the classes. Unless it is the function a
      // local class is declared in (`Clear::Local`), whose class comes next.
      const fn = (context.getNodesInFileNamed?.(inner.filePath, cppLastSegment(qualifiedName)) ?? [])
        .find((n) => (n.kind === 'method' || n.kind === 'function') && rangeWithin(inner, n) && !sameRange(inner, n));
      const fnOwner = fn ? cppMemberOwner(fn, context) : null;
      if (!fn || fnOwner === null) break;
      qualifiedName = fnOwner;
      inner = fn;
      continue;
    }
    const scope = cppScopeDeclarations(qualifiedName, decls, inner, context);
    scopes.push(scope);
    if (scope.decls.length > 0) inner = scope.decls[0]!;
    const cut = qualifiedName.lastIndexOf('::');
    qualifiedName = cut > 0 ? qualifiedName.slice(0, cut) : '';
  }
  return scopes;
}

/** A class scope's declarations as cppEnclosingClasses keeps them. */
function cppScopeDeclarations(qualifiedName: string, decls: Node[], inner: Node, context: ResolutionContext): CppClassScope {
  const scope = (kept: Node[], holds: boolean): CppClassScope => ({ qualifiedName, decls: kept, holds, narrowed: kept.length < decls.length });
  // (Code in a class's own body, a member's initializer, has that class as `inner`.)
  const holding = decls.filter((d) => d.filePath === inner.filePath && rangeWithin(inner, d));
  if (holding.length > 0) return scope(holding, true);
  const local = decls.filter((d) => d.filePath === inner.filePath);
  if (local.length > 0 || decls.length < 2) return scope(local.length > 0 ? local : decls, false);
  const included = decls.filter((d) => cppIncluders(d.filePath, context).has(inner.filePath));
  return scope(included.length > 0 ? included : decls, false);
}

/**
 * The method `name` a class scope gives C++ lookup: the class's own — first
 * one written in the very declaration holding the code, as an inline member
 * — else the nearest one of a class it derives from, through the kept
 * declarations' base edges. Undefined when the class may declare `name`
 * through a macro, which no node shows: lookup would stop there.
 */
function cppScopeMethod(scope: CppClassScope, name: string, receiver: 'bare' | 'this', ref: UnresolvedRef, context: ResolutionContext): Node | null | undefined {
  const own = cppSpecializationPool(context.getNodesByQualifiedName(`${scope.qualifiedName}::${name}`).filter((n) =>
    n.kind === 'method' && (n.language === 'cpp' || n.language === 'c') &&
    // A namesake class's members are defined where it is: leveldb's
    // fault-injection test declares a `FileState` of its own, with no
    // `Truncate`, beside memenv.cc's.
    (!scope.narrowed || scope.decls.some((d) => d.filePath === n.filePath || cppIncluders(d.filePath, context).has(n.filePath)))), ref, context);
  const holder = scope.holds ? scope.decls[0]! : null;
  const inline = holder ? own.filter((n) => n.filePath === holder.filePath && rangeWithin(n, holder)) : [];
  // A class with no name (a partial specialization, an unnamed struct)
  // shares its qualified name with every other: only its inline members are its own.
  const outOfLine = cppLastSegment(scope.qualifiedName) === '<anonymous>' ? [] : own.filter((n) => !inline.includes(n));
  if (inline.length + outOfLine.length > 0) {
    return cppOverloadFor([...inline, ...preferCallSiteFile(outOfLine, ref.filePath)], name, ref, context);
  }
  if (scope.decls.some((d) => cppMemberMacroArguments(d, context).some((a) => name.startsWith(a) || name.endsWith(a)))) return undefined;
  if (!context.getSupertypeNodes) return null;
  for (const decl of scope.decls) {
    for (const base of context.getSupertypeNodes(decl.id)) {
      if (!CPP_CLASS_KINDS.has(base.kind)) continue;
      if (receiver === 'bare' && isCppDependentBase(decl, base, context) && !cppUsingDeclares(decl, base, name, context)) continue;
      const inherited = cppMethodOf(base, name, ref, context, 1, new Set([scope.qualifiedName]));
      if (!inherited) continue;
      // Its class's other overloads, which the arguments may fit better
      // (rocksdb's `RegisterOptions(name, &opts, &info)` is not the
      // two-parameter template beside it).
      const siblings = context.getNodesByQualifiedName(inherited.qualifiedName).filter((n) =>
        n.id !== inherited.id && n.kind === 'method' && (n.language === 'cpp' || n.language === 'c'));
      return cppOverloadFor(cppSpecializationPool([inherited, ...preferCallSiteFile(siblings, ref.filePath)], ref, context), name, ref, context);
    }
  }
  return null;
}

/**
 * Of one class's overloads of `name` (in preference order), the one the
 * call's arguments fit best: by their count and string literals
 * (cppOverloadFit), then, among overloads those fit alike, by the types the
 * arguments have where the call reads them (cppArgumentTypeFit). rocksdb's
 * `Insert(ch)` on a `char ch` is `Insert(char key, …)`, not `Insert(const
 * std::string& key, …)`. A deleted overload (`void reset(T*) = delete;`) is
 * none a call that compiles reaches, so it is only taken when every one is.
 */
function cppOverloadFor(candidates: Node[], name: string, ref: UnresolvedRef, context: ResolutionContext): Node {
  if (candidates.length === 1) return candidates[0]!;
  const callable = candidates.filter((n) => !isCppDeletedFunction(n, name, context));
  const overloads = callable.length > 0 ? callable : candidates;
  if (overloads.length === 1) return overloads[0]!;
  const args = cppCallArguments(ref, name, context);
  if (!args) return overloads[0]!;
  const fits = overloads.map((n) => cppOverloadFit(n, name, args, context));
  const top = Math.max(...fits);
  return cppArgumentTypeChoice(overloads.filter((_, i) => fits[i] === top), name, args, ref, context);
}

/**
 * Of overloads the call's arguments `args` fit alike by count (in
 * preference order), the one the types the arguments have where the call
 * reads them fit best (cppArgumentTypeFit); the first on a tie, unless a
 * const twin of it fits the arguments' constness better (cppConstTwinChoice).
 */
function cppArgumentTypeChoice(tied: Node[], name: string, args: string[], ref: UnresolvedRef, context: ResolutionContext): Node {
  if (tied.length === 1 || args.length === 0) return tied[0]!;
  const types = args.map((arg) => cppArgumentType(arg, ref, context));
  if (types.every((t) => t === null)) return tied[0]!;
  const fits = tied.map((n) => cppArgumentTypeFit(n, name, types, context));
  const top = Math.max(...fits);
  const best = tied[fits.indexOf(top)]!;
  return cppConstTwinChoice(best, tied.filter((n, i) => fits[i] === top && n !== best), name, types, context);
}

/**
 * `best`, or of its twins among `others` — overloads alike but for the
 * `const` of a pointer or reference parameter — the one that adds `const` to
 * the fewest of the arguments `types`, as C++ ranks them: protobuf's
 * `DynamicCastMessage<T>(ptr.get())` on a `std::shared_ptr<Message> ptr` is
 * `T* DynamicCastMessage(MessageLite* from)`, not the `const T*
 * DynamicCastMessage(const MessageLite* from)` declared before it. (A const
 * object fits only the const twin: cppWrittenTypeFit.)
 */
function cppConstTwinChoice(best: Node, others: Node[], name: string, types: Array<CppArgumentType | null>, context: ResolutionContext): Node {
  if (others.length === 0) return best;
  const shape = cppConstlessParameters(best, name, context)?.join(',');
  if (shape === undefined) return best;
  let choice = best;
  let added = cppConstAdded(best, name, types, context);
  for (const n of others) {
    if (cppConstlessParameters(n, name, context)?.join(',') !== shape) continue;
    const count = cppConstAdded(n, name, types, context);
    if (count < added) {
      choice = n;
      added = count;
    }
  }
  return choice;
}

/** An overload's parameter types without their `const`s: what its const twins share. */
function cppConstlessParameters(n: Node, name: string, context: ResolutionContext): string[] | null {
  const list = cppOverloadParameters(n, name, context);
  if (list === null) return null;
  return splitCppTopLevel(cppWithoutComments(list)).filter((p) => p !== 'void')
    .map((p) => cppParameterType(p).replace(/\bconst\b/g, ' ').replace(/\s+/g, ''));
}

/** How many of the arguments `types` an overload's pointer or reference parameters add `const` to. */
function cppConstAdded(n: Node, name: string, types: Array<CppArgumentType | null>, context: ResolutionContext): number {
  const list = cppOverloadParameters(n, name, context);
  if (list === null) return 0;
  const params = splitCppTopLevel(cppWithoutComments(list)).filter((p) => p !== 'void');
  let count = 0;
  for (let i = 0; i < types.length && i < params.length; i++) {
    const arg = types[i];
    const param = cppParameterType(params[i]!);
    if (arg?.kind === 'type' && cppRefersToConst(param) === true && cppArgumentConst(arg.text, param) === false) count++;
  }
  return count;
}

/**
 * The C++ function a call of `chosen`'s name reaches among `candidates`:
 * of its overloads — the functions of its qualified name the call's file
 * can see (isVisibleAcrossFiles), `chosen` first — the one the call's
 * arguments fit (cppOverloadFor). The name strategies pick a function by
 * where it is; protobuf's `ParseWithLimit(limit, data, result)` on an
 * `int32_t result` is the overload taking an `int32_t&`, not the
 * `int64_t&` one nearer the call. A function hides a class of its name, so
 * a call is to the function when `chosen` is that class. C has no
 * overloads: a C call reaches the function of the name its file sees — its
 * own or one a header it includes defines, else one with external linkage —
 * the best placed of them (findBestMatch). jemalloc's tests call the
 * `static inline do_arena_create` of the arena_util.h they include, not a
 * neighbouring test's own `static do_arena_create`. What the file sees only
 * when the build sets a flag nothing in the project sets
 * (isCFeatureVariant) yields to a definition with external linkage that the
 * build without it calls: lua-cjson's fpconv.h defines `fpconv_init` under
 * `#ifdef USE_INTERNAL_FPCONV`, and redis's build calls fpconv.c's. A call
 * compiled only with such a flag itself is left to the file's own: redis's
 * quicklist.c tests call its `static mstime` inside `#ifdef REDIS_TEST`.
 * `chosen` itself for anything but a C or C++ call, or when no function is
 * in sight.
 */
function cppFunctionOverload(chosen: Node, candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node {
  if ((ref.language !== 'cpp' && ref.language !== 'c') || ref.referenceKind !== 'calls') return chosen;
  const overloads = candidates.filter((n) => n.kind === 'function' && n.qualifiedName === chosen.qualifiedName &&
    isVisibleAcrossFiles(n, ref, context));
  if (overloads.length === 0) return chosen;
  if (ref.language === 'c') {
    const own = overloads.filter((n) => n.filePath === ref.filePath || cppIncluders(n.filePath, context).has(ref.filePath));
    const external = own.length > 0 ? overloads.filter((n) => !own.includes(n) && !isStaticCFunction(n, context)) : [];
    const outside = external.length > 0 && own.every((n) => isCFeatureVariant(n, ref, context)) &&
      !isOffByDefault(ref.filePath, ref.line, context)
      ? external.filter((n) => !isCFeatureVariant(n, ref, context))
      : [];
    return findBestMatch(ref, outside.length > 0 ? outside : own.length > 0 ? own : overloads, context) ?? chosen;
  }
  return cppOverloadFor(overloads.includes(chosen) ? [chosen, ...overloads.filter((n) => n !== chosen)] : overloads, chosen.name, ref, context);
}

/**
 * Of the C++ functions `candidates` a call may reach, the ones the template
 * arguments it writes allow. An explicit specialization is named like the
 * template it specializes, so a call meets both among that name's candidates:
 *  - a call that writes template arguments is to the specialization written
 *    with the same ones — rocksdb's `Deserialize<int64_t>(src, offset)` is
 *    `template <> int64_t Deserialize<int64_t>(…)` — else to the template
 *    itself or an ordinary overload: fmt's `num_bits<unsigned short>()` is
 *    `num_bits<T>()`, not the `num_bits<uint128>()` beside the call. None is
 *    left when specializations are all there is: protobuf's template
 *    `ReadPrimitive<CType, DeclaredType>(…)` calls whichever one its
 *    arguments become.
 *  - a call that writes none, or another reference, reaches a
 *    specialization only when there is nothing else.
 * The candidates as they are when none is a specialization.
 */
function cppSpecializationPool(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  if (ref.language !== 'cpp') return candidates;
  const written = candidates.map((n) => cppSpecializationArguments(n, context));
  if (written.every((w) => w === null)) return candidates;
  const others = candidates.filter((_, i) => written[i] === null);
  const args = cppCallTemplateArguments(ref, context);
  if (args === null) return others.length > 0 ? others : candidates;
  const named = candidates.filter((_, i) => written[i] !== null && cppTemplateArgumentsMatch(written[i]!, args));
  return named.length > 0 ? named : others;
}

/**
 * The `candidates` a C++ call through a qualifier written with template
 * arguments can mean: fmt's `formatter<int>::format(…)` is never the
 * `format` a test defines for `formatter<incomplete_type>`, which the index
 * names `fmt::formatter::format` like every other specialization's. A member
 * defined out of line for a full specialization of its class stays only when
 * that specialization's arguments are the call's; a template's own members,
 * a partial specialization's and those defined in their class all stay. The
 * candidates as they are when the qualifier is written without arguments.
 */
function cppQualifierSpecializationPool(candidates: Node[], ref: UnresolvedRef, context: ResolutionContext): Node[] {
  if (ref.language !== 'cpp' || candidates.length === 0) return candidates;
  const args = cppQualifierArguments(ref, context);
  if (args === null) return candidates;
  return candidates.filter((n) => {
    const owner = cppSpecializationOwnerArguments(n, context);
    return owner === null || cppTemplateArgumentsMatch(owner, args);
  });
}

/** The template arguments a C++ call writes on the qualifier before its name: `int` for `formatter<int>::format(…)`, null for none. */
function cppQualifierArguments(ref: UnresolvedRef, context: ResolutionContext): string[] | null {
  const segments = ref.referenceName.split('::');
  if (segments.length < 2) return null;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  return cppTemplateArgumentsAfter(lines.slice(ref.line - 1, ref.line + 3).join('\n'), segments[segments.length - 2]!, Math.max(0, ref.column));
}

/** Per context: a C++ member's id → the arguments of the full specialization it is defined out of line for (null: none). */
const CPP_SPECIALIZATION_OWNER_ARGUMENTS = new WeakMap<ResolutionContext, Map<string, string[] | null>>();

/**
 * The arguments of the full specialization of its class a C++ member is
 * defined out of line for: `incomplete_type` for fmt's `auto
 * fmt::formatter<incomplete_type>::format(…)`. Null for a member defined in
 * its class, and for one whose arguments name the template parameters around
 * it, a template's own (`Foo<T>::bar`) or a partial specialization's
 * (`Foo<T*>::bar`).
 */
function cppSpecializationOwnerArguments(n: Node, context: ResolutionContext): string[] | null {
  if (n.language !== 'cpp' || (n.kind !== 'method' && n.kind !== 'function')) return null;
  const segments = n.qualifiedName.split('::');
  if (segments.length < 2) return null;
  let memo = CPP_SPECIALIZATION_OWNER_ARGUMENTS.get(context);
  if (!memo) CPP_SPECIALIZATION_OWNER_ARGUMENTS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  const owner = segments[segments.length - 2]!.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const name = n.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  const head = lines.slice(n.startLine - 1, n.startLine + 11).join('\n').slice(n.startColumn);
  let found: string[] | null = null;
  // `Owner<args>::name`, the declarator's own qualifier.
  for (const m of head.matchAll(new RegExp(`(?<![\\w$])${owner}<`, 'g'))) {
    const open = m.index! + m[0].length - 1;
    const end = cppTemplateArgumentsEnd(head, open);
    if (end < 0 || !new RegExp(`^\\s*::\\s*~?${name}(?![\\w$])`).test(head.slice(end + 1))) continue;
    const args = splitCppTopLevel(head.slice(open + 1, end)).map(cppTemplateArgumentKey);
    // A `template <…>` with parameters on the definition makes it a template's
    // own member or a partial specialization's, whatever the arguments say:
    // abseil's `template <int max_words> … BigUnsigned<max_words>::FiveToTheNth(`.
    const before = `${lines.slice(Math.max(0, n.startLine - 3), n.startLine - 1).join('\n')}\n${head.slice(0, m.index)}`;
    const header = /\btemplate\s*<\s*(>)?(?![\s\S]*\btemplate\s*<)/.exec(before);
    const parameters = [...cppTemplateParameters(n, context)];
    const dependent = (header !== null && header[1] === undefined) ||
      args.some((a) => parameters.some((p) => new RegExp(`(?<![\\w$])${p}(?![\\w$])`).test(a)));
    found = dependent || args.length === 0 ? null : args;
    break;
  }
  memo.set(n.id, found);
  return found;
}

/** Per context: a C++ function's id → the template arguments it is an explicit specialization for (null: none). */
const CPP_SPECIALIZATION_ARGUMENTS = new WeakMap<ResolutionContext, Map<string, string[] | null>>();

/**
 * The template arguments the C++ function or method `n` is an explicit
 * specialization for, as its definition writes them after its name:
 * `int32_t` and `WireFormatLite::TYPE_INT32` for protobuf's `template <>
 * inline bool WireFormatLite::ReadPrimitive<int32_t, WireFormatLite::TYPE_INT32>(…)`.
 * A method a macro defines is read from its expansion. Null for a template's
 * own definition, any other function, and a specialization that leaves its
 * arguments to be deduced.
 */
export function cppSpecializationArguments(n: Node, context: ResolutionContext): string[] | null {
  // A constructor, whose signature is its parameter list, is never specialized
  // by name: gmock's `template <typename Func> Action(const Action<Func>& action)`
  // writes `Action<Func>` for a parameter.
  if (n.language !== 'cpp' || (n.kind !== 'function' && n.kind !== 'method') || n.signature?.startsWith('(')) return null;
  let memo = CPP_SPECIALIZATION_ARGUMENTS.get(context);
  if (!memo) CPP_SPECIALIZATION_ARGUMENTS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  // (A method a macro defines carries its expansion as its signature.)
  const lines = n.signature ? [] : context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  const head = n.signature || lines.slice(n.startLine - 1, n.startLine + 11).join('\n').slice(n.startColumn);
  const args = cppTemplateArgumentsAfter(head, n.name, 0);
  memo.set(n.id, args);
  return args;
}

/**
 * The template arguments the C++ call at `ref` writes after the name it
 * calls — `unsigned short` for fmt's `num_bits<unsigned short>()` — or null
 * when it writes none, leaving them to be deduced.
 */
function cppCallTemplateArguments(ref: UnresolvedRef, context: ResolutionContext): string[] | null {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/) ?? [];
  const text = lines.slice(ref.line - 1, ref.line + 3).join('\n');
  return cppTemplateArgumentsAfter(text, ref.referenceName.split(/::|\.|->/).pop()!, Math.max(0, ref.column));
}

/**
 * The template arguments `text` writes right after `name`, the first time
 * from `from` on it is written as a word of its own, as they compare
 * (cppTemplateArgumentKey). Null when it writes none there, or `<>`.
 */
function cppTemplateArgumentsAfter(text: string, name: string, from: number): string[] | null {
  for (let at = text.indexOf(name, from); at >= 0; at = text.indexOf(name, at + 1)) {
    const open = at + name.length;
    if (/[\w$]/.test(text[at - 1] ?? '') || /[\w$]/.test(text[open] ?? '')) continue;
    const end = text[open] === '<' ? cppTemplateArgumentsEnd(text, open) : -1;
    const args = end < 0 ? [] : splitCppTopLevel(text.slice(open + 1, end)).map(cppTemplateArgumentKey);
    return args.length > 0 ? args : null;
  }
  return null;
}

/** A C++ template argument as it compares: spaced only between words. */
function cppTemplateArgumentKey(arg: string): string {
  return arg.replace(/\s*([^\w\s])\s*/g, '$1').replace(/\s+/g, ' ');
}

/**
 * Whether a call's template arguments `call` are the ones a specialization
 * writes, `written`: each the same, or the same name qualified further on
 * one side (`TYPE_INT64` inside the class, `WireFormatLite::TYPE_INT64`
 * outside it).
 */
function cppTemplateArgumentsMatch(written: string[], call: string[]): boolean {
  return written.length === call.length && written.every((w, i) => {
    const c = call[i]!;
    return w === c || w.endsWith(`::${c}`) || c.endsWith(`::${w}`);
  });
}

const CPP_DELETED_FUNCTIONS = new WeakMap<ResolutionContext, Map<string, boolean>>();

/**
 * Whether the C++ function or method `n`, named `name`, is declared deleted:
 * from its name to the declaration's `;` or body, it says `= delete`
 * (protobuf's `void reset(T* PROTOBUF_NULLABLE) = delete;`). A method a macro
 * defines has a body.
 */
function isCppDeletedFunction(n: Node, name: string, context: ResolutionContext): boolean {
  if (cppMacroMethodHead(n) !== null) return false;
  let memo = CPP_DELETED_FUNCTIONS.get(context);
  if (!memo) CPP_DELETED_FUNCTIONS.set(context, (memo = new Map()));
  const hit = memo.get(n.id);
  if (hit !== undefined) return hit;
  const lines = context.getFileLines?.(n.filePath) ?? context.readFile(n.filePath)?.split(/\r?\n/) ?? [];
  const text = lines.slice(n.startLine - 1, Math.min(lines.length, n.startLine + 11)).join('\n');
  const at = text.search(new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\(`));
  const declaration = at < 0 ? '' : text.slice(at).split(/[;{]/)[0]!;
  const deleted = /=\s*delete\b/.test(declaration);
  memo.set(n.id, deleted);
  return deleted;
}

/** What a C++ call's argument is: a literal's kind, or the type a name or expression has as written. */
type CppArgumentType =
  | { kind: 'char' | 'number' | 'zero' | 'bool' | 'null' }
  | { kind: 'type'; text: string; lvalue?: boolean; dependent?: boolean };

/**
 * What the argument `arg` of the call at `ref` is, where that can be read: a
 * character, number, `true`/`false` or `nullptr` literal, or the written
 * type of a name the calling function declares, of `&name`, or of an
 * expression (cppExpressionType) — the element `keys[i]` reads in rocksdb's
 * `TryLock(column_family[i], keys[i], …)` on a `std::vector<Slice>`. Null
 * otherwise. (String literals are cppOverloadFit's.)
 */
function cppArgumentType(arg: string, ref: UnresolvedRef, context: ResolutionContext): CppArgumentType | null {
  const text = arg.trim();
  if (/^(?:u8|u|U|L)?'(?:[^'\\]|\\.)+'$/.test(text)) return { kind: 'char' };
  if (text === 'true' || text === 'false') return { kind: 'bool' };
  if (text === 'nullptr' || text === 'NULL') return { kind: 'null' };
  if (/^0+[uUlL]*$/.test(text)) return { kind: 'zero' };
  if (/^[-+]?(?:0[xX][\da-fA-F']+|\d[\d']*(?:\.\d*)?(?:[eE][-+]?\d+)?|\.\d+(?:[eE][-+]?\d+)?)[uUlLfFzZ]*$/.test(text)) return { kind: 'number' };
  const address = /^&\s*([A-Za-z_]\w*)$/.exec(text);
  const name = address?.[1] ?? (/^[A-Za-z_]\w*$/.test(text) ? text : null);
  if (name) {
    const decl: CppReceiverDeclaration = {};
    inferCppReceiverType(name, ref, context, 0, decl);
    const declared = decl.declared?.text ?? decl.raw;
    if (!declared || !decl.callers || decl.shadowed) return null;
    const written = decl.constant && !/^\s*const\b/.test(declared) ? `const ${declared}` : declared;
    // (An array is a pointer to its element: fmt's `format_base2e(4, buf, …)` on a `Char buf[8]` is the `Char* out` overload.)
    const typed = address || decl.array ? `${written.replace(/\s*&+\s*$/, '')}*` : written;
    return { kind: 'type', text: typed, lvalue: !address, dependent: isCppDependentArgument(typed, ref, context) };
  }
  const typed = /^(?:u8|u|U|L)?R?["']/.test(text) ? null : cppExpressionType(text, ref, context, 0);
  return typed
    ? { kind: 'type', text: typed.text, lvalue: cppNamesObject(text, typed.text), dependent: isCppDependentArgument(typed.text, ref, context) }
    : null;
}

/**
 * Whether an argument of the written type `type` has the type of a template
 * parameter of the calling function or its class (fmt's `const S& fmt`),
 * which could be a pointer as well as an object.
 */
function isCppDependentArgument(type: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const name = normalizeCppTypeName(type);
  const caller = name ? context.getNodeById?.(ref.fromNodeId) : null;
  return !!caller && cppTemplateParameters(caller, context).has(name!);
}

/**
 * Whether the C++ argument `expr`, of the written type `type`, names an
 * object, which a reference to a non-const type can bind: a dereference, a
 * subscript, a member, or a call that returns an lvalue reference. False for
 * a call that returns a value; undefined when that can't be told.
 */
function cppNamesObject(expr: string, type: string): boolean | undefined {
  let text = expr.trim();
  while (text.startsWith('(') && text.endsWith(')') && cppOpeningParen(text, text.length - 1) === 0) text = text.slice(1, -1).trim();
  if (text.startsWith('*') || text.endsWith(']')) return true;
  if (!text.endsWith(')')) return /^[A-Za-z_][\w\s.:>-]*$/.test(text) ? true : undefined;
  if (/&&\s*$/.test(type)) return undefined;
  return /&\s*$/.test(type);
}

/** What a C++ type is, for an argument to fit a parameter of it. */
type CppTypeCategory = 'string' | 'cstring' | 'char' | 'number' | 'bool' | 'pointer' | 'null' | 'class';

const CPP_CHAR_TYPES: ReadonlySet<string> = new Set(['char', 'wchar_t', 'char8_t', 'char16_t', 'char32_t']);
const CPP_NUMBER_TYPES: ReadonlySet<string> = new Set([
  'int', 'unsigned', 'signed', 'short', 'long', 'float', 'double', 'size_t', 'ssize_t', 'ptrdiff_t',
  'int8_t', 'int16_t', 'int32_t', 'int64_t', 'uint8_t', 'uint16_t', 'uint32_t', 'uint64_t', 'intptr_t', 'uintptr_t',
  // A container's own integer aliases, by convention: nlohmann/json's `operator[](size_type idx)`.
  'size_type', 'difference_type',
]);
const CPP_STRING_TYPES: ReadonlySet<string> = new Set(['string', 'wstring', 'string_view', 'wstring_view', 'basic_string', 'basic_string_view']);

/**
 * The category of the written C++ type `type`: a pointer's, a string's, a
 * character's, a number's, `std::nullptr_t`'s, a class's.
 */
function cppTypeCategory(type: string): CppTypeCategory {
  const flat = stripCppTemplateArguments(type).replace(/\b(?:const|volatile|struct|class|typename|enum)\b/g, ' ').replace(/&+/g, ' ').trim();
  const words = flat.replace(/\*/g, ' ').trim().split(/\s+/);
  const last = cppLastSegment(words[words.length - 1] ?? '');
  if (flat.includes('*')) return CPP_CHAR_TYPES.has(last) && (flat.match(/\*/g) ?? []).length === 1 ? 'cstring' : 'pointer';
  if (last === 'nullptr_t') return 'null';
  if (last === 'bool') return 'bool';
  if (CPP_CHAR_TYPES.has(last) && words.every((w) => CPP_CHAR_TYPES.has(w) || w === 'signed' || w === 'unsigned')) return 'char';
  if (CPP_NUMBER_TYPES.has(last) || words.every((w) => CPP_NUMBER_TYPES.has(w))) return 'number';
  return CPP_STRING_TYPES.has(last) ? 'string' : 'class';
}

/**
 * How well the read argument types `types` fit the parameters of the
 * overload `n`: the same type, or a character to a character, scores; a
 * character, number or pointer to a string, or a string or pointer to a
 * number, counts against. Classes of other names score nothing: a conversion
 * may join them.
 */
function cppArgumentTypeFit(n: Node, name: string, types: Array<CppArgumentType | null>, context: ResolutionContext): number {
  const list = cppOverloadParameters(n, name, context);
  if (list === null) return 0;
  const params = splitCppTopLevel(cppWithoutComments(list)).filter((p) => p !== 'void');
  const own = types.some((t) => t?.kind === 'type') ? cppOwnTemplateParameters(n, context) : [];
  let score = 0;
  for (let i = 0; i < types.length && i < params.length; i++) {
    const arg = types[i];
    const param = cppParameterType(params[i]!);
    if (!arg || param.includes('...')) continue;
    const category = cppTypeCategory(param);
    // (A parameter of the function's own template parameter's type, `T* x`, takes the argument's `const` into `T`.)
    const deduced = own.length > 0 && own.includes(normalizeCppTypeName(param) ?? '');
    score += arg.kind === 'type'
      ? cppWrittenTypeFit(arg.text, param, category, { lvalue: arg.lvalue, dependent: arg.dependent, deduced })
      : CPP_LITERAL_FIT[arg.kind][category];
  }
  return score;
}

/**
 * How a literal fits a parameter of each category. `nullptr` is a
 * `std::nullptr_t` exactly, and a pointer only by conversion: protobuf's
 * `ptr.reset(nullptr)` is `reset(std::nullptr_t)`, not `reset(T*)`.
 */
const CPP_LITERAL_FIT: Record<'char' | 'number' | 'zero' | 'bool' | 'null', Record<CppTypeCategory, number>> = {
  char: { char: 3, number: 1, bool: 0, string: -3, cstring: -3, pointer: -3, null: -3, class: 0 },
  number: { number: 2, char: 1, bool: 0, string: -3, cstring: -3, pointer: -3, null: -3, class: 0 },
  zero: { number: 2, char: 1, bool: 0, pointer: 1, cstring: 1, null: 1, string: -3, class: 0 },
  bool: { bool: 3, number: 1, char: 0, string: -3, cstring: -3, pointer: -3, null: -3, class: 0 },
  null: { null: 4, pointer: 3, cstring: 3, class: 1, string: -3, char: -3, number: -3, bool: -1 },
};

/**
 * How an argument written as type `arg` fits a parameter of type `param` (of
 * category `category`). An object is no pointer, nor a pointer to characters
 * a pointer to anything but characters or `void`, or the other way round:
 * protobuf's `DynamicCastMessage<T>(*msg)` takes a reference, and rocksdb's
 * `db_->Put(opts, key, ts, value)` on a `char key[]` no `ColumnFamilyHandle*`.
 * A pointer or reference to a non-const type never takes a const object,
 * nor a reference a value a call returns (`lvalue` false). None of that
 * holds for an argument of a template parameter's type (`dependent`), and
 * the pointer and `const` rules not for a parameter whose type the function's
 * own template parameter is (`deduced`). (Of two overloads alike but for a
 * `const`, which one a non-const object takes is cppConstTwinChoice's.)
 */
function cppWrittenTypeFit(
  arg: string,
  param: string,
  category: CppTypeCategory,
  how: { lvalue?: boolean; dependent?: boolean; deduced?: boolean } = {},
): number {
  const fit = cppUnqualifiedTypeFit(arg, param, category);
  if (fit < 0 || how.dependent) return fit;
  const argCategory = cppTypeCategory(arg);
  if (category === 'pointer' && argCategory === 'class') return -3;
  if (!how.deduced && category === 'pointer' && argCategory === 'cstring' && !/\bvoid\b/.test(param)) return -3;
  if (category === 'cstring' && argCategory === 'pointer') return -3;
  if (cppRefersToConst(param) !== false) return fit;
  if (!how.deduced && cppArgumentConst(arg, param) === true) return -3;
  return how.lvalue === false && !/\*/.test(stripCppTemplateArguments(param)) ? -3 : fit;
}

/**
 * Whether the object an argument of the written type `arg` gives a pointer
 * or reference parameter `param` is const: what the pointer points at, or
 * the object itself. Undefined when the argument is no such thing.
 */
function cppArgumentConst(arg: string, param: string): boolean | undefined {
  const argPointer = /\*/.test(stripCppTemplateArguments(arg));
  if (/\*/.test(stripCppTemplateArguments(param))) return argPointer ? cppRefersToConst(arg) : undefined;
  return argPointer ? undefined : cppIsConstObject(arg);
}

/**
 * Whether the C++ type `type`, a pointer or an lvalue reference of one
 * level, refers to a const object: `const T*`, `T const&`. (A pointer's own
 * `const`, `T* const`, is not the object's.) Undefined for any other type.
 */
function cppRefersToConst(type: string): boolean | undefined {
  const text = stripCppTemplateArguments(type).trim();
  const stars = (text.match(/\*/g) ?? []).length;
  if (stars > 1 || (stars === 0 && !/[^&]&\s*$/.test(text))) return undefined;
  return /\bconst\b/.test(stars === 1 ? text.slice(0, text.indexOf('*')) : text);
}

/** Whether a C++ object of the written type `type`, a value or a reference, is const. */
function cppIsConstObject(type: string): boolean {
  return /\bconst\b/.test(stripCppTemplateArguments(type));
}

/** How an argument written as type `arg` fits a parameter of type `param`, `const` aside. */
function cppUnqualifiedTypeFit(arg: string, param: string, category: CppTypeCategory): number {
  const argCategory = cppTypeCategory(arg);
  const pointer = (c: CppTypeCategory): boolean => c === 'pointer' || c === 'cstring';
  if (normalizeCppTypeName(arg) === normalizeCppTypeName(param) && pointer(argCategory) === pointer(category)) return 3;
  if (argCategory === category && argCategory !== 'class') return 2;
  const textual = (c: CppTypeCategory): boolean => c === 'string' || c === 'cstring';
  if ((argCategory === 'char' || argCategory === 'number' || argCategory === 'pointer') && category === 'string') return -3;
  if ((textual(argCategory) || argCategory === 'pointer') && (category === 'char' || category === 'number')) return -3;
  if ((argCategory === 'char' || argCategory === 'number') && (category === 'pointer' || category === 'cstring')) return -3;
  return 0;
}

/** A C++ parameter declaration's type: without its default argument and its name. */
function cppParameterType(param: string): string {
  let text = param;
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i]!;
    if (c === '<' || c === '(' || c === '[') depth++;
    else if (c === '>' || c === ')' || c === ']') depth--;
    else if (c === '=' && depth === 0) {
      text = text.slice(0, i);
      break;
    }
  }
  text = text.trim();
  // The name, when a type comes before it.
  const named = /^(.*[\w>*&\s])\b[A-Za-z_]\w*\s*(?:\[[^\]]*\])?$/.exec(text);
  return named && /[A-Za-z_]/.test(named[1]!) && !/^(?:const|volatile|unsigned|signed|struct|class|enum)\s*$/.test(named[1]!.trim()) ? named[1]!.trim() : text;
}

const CPP_MEMBER_MACRO_ARGS = new WeakMap<ResolutionContext, Map<string, string[]>>();

/**
 * The words in the arguments of the macros a C++ class declaration calls
 * among its members, like `Message` in protobuf's
 * `LOCAL_VAR_ACCESSOR(Message*, Message);`: such a macro can declare a member
 * the index has no node for (`Get##name` makes `GetMessage`).
 */
function cppMemberMacroArguments(decl: Node, context: ResolutionContext): string[] {
  let memo = CPP_MEMBER_MACRO_ARGS.get(context);
  if (!memo) CPP_MEMBER_MACRO_ARGS.set(context, (memo = new Map()));
  const hit = memo.get(decl.id);
  if (hit) return hit;
  const words: string[] = [];
  const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
  const nonCode = cppNonCodeLines(decl.filePath, context);
  let depth = 0;
  for (let i = decl.startLine - 1; i < Math.min(lines.length, decl.endLine); i++) {
    const blanked = cppLiteralsBlanked(lines[i]!, i + 1, nonCode);
    const code = cppCodeOf(i === decl.startLine - 1 ? blanked.slice(decl.startColumn) : blanked) ?? '';
    const call = depth === 1 ? /^\s*[A-Z][A-Z0-9_]*\s*\(([^;{}]*)\)\s*;?\s*$/.exec(code) : null;
    if (call) words.push(...call[1]!.split(/\W+/).filter((w) => w.length >= 3));
    for (const c of code) {
      if (c === '{') depth++;
      else if (c === '}') depth--;
    }
  }
  memo.set(decl.id, words);
  return words;
}

const CPP_BASE_SPECS = new WeakMap<ResolutionContext, Map<string, string[]>>();

/**
 * The base specifiers a C or C++ class declaration writes (`public
 * Base<T>`, `private Mixin`), read from its own head; none for a forward
 * declaration.
 */
function cppBaseSpecifiers(decl: Node, context: ResolutionContext): string[] {
  let memo = CPP_BASE_SPECS.get(context);
  if (!memo) CPP_BASE_SPECS.set(context, (memo = new Map()));
  const hit = memo.get(decl.id);
  if (hit) return hit;
  const specs: string[] = [];
  const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/);
  const nonCode = cppNonCodeLines(decl.filePath, context);
  const head = (lines?.slice(decl.startLine - 1, decl.startLine + 11) ?? []).map((l, k) => cppLiteralsBlanked(l, decl.startLine + k, nonCode));
  if (head.length > 0) {
    head[0] = head[0]!.slice(decl.startColumn);
    const text = head.map((l) => cppCodeOf(l) ?? '').join('\n');
    const brace = text.indexOf('{');
    const colon = brace < 0 ? -1 : text.slice(0, brace).search(/(?<!:):(?!:)/);
    if (colon >= 0 && !text.slice(0, brace).includes(';')) {
      specs.push(...splitCppTopLevel(text.slice(colon + 1, brace)).map((s) => s.replace(/\b(?:public|protected|private|virtual)\b/g, ' ').trim()));
    }
  }
  memo.set(decl.id, specs);
  return specs;
}

/** Per context: a C++ class declaration's id → the `using Base::name;` declarations its body writes, as [base, name]. */
const CPP_USING_MEMBERS = new WeakMap<ResolutionContext, Map<string, Array<[string, string]>>>();

/**
 * Whether the C++ class declaration `decl` brings `name` in from its base
 * `base` with a using-declaration: rocksdb's `FullTypedCacheHelperFns`
 * writes `using BasicTypedCacheHelperFns<TValue>::DownCastValue;`, and a bare
 * `DownCastValue(v)` in it then finds the base's, though the base depends on
 * the class's template parameters (isCppDependentBase).
 */
function cppUsingDeclares(decl: Node, base: Node, name: string, context: ResolutionContext): boolean {
  let memo = CPP_USING_MEMBERS.get(context);
  if (!memo) CPP_USING_MEMBERS.set(context, (memo = new Map()));
  let usings = memo.get(decl.id);
  if (!usings) {
    usings = [];
    const lines = context.getFileLines?.(decl.filePath) ?? context.readFile(decl.filePath)?.split(/\r?\n/) ?? [];
    const nonCode = cppNonCodeLines(decl.filePath, context);
    const body = lines.slice(decl.startLine - 1, decl.endLine ?? decl.startLine)
      .map((l, k) => cppCodeOf(cppLiteralsBlanked(l, decl.startLine + k, nonCode)) ?? '').join('\n');
    for (const m of body.matchAll(/\busing\s+(?!namespace\b)((?:::\s*)?[A-Za-z_][\w:]*(?:\s*<[^;{}]*>)?)\s*::\s*([A-Za-z_]\w*)\s*;/g)) {
      usings.push([cppLastSegment(stripCppTemplateArguments(m[1]!).trim()), m[2]!]);
    }
    memo.set(decl.id, usings);
  }
  return usings.some(([of, member]) => of === base.name && member === name);
}

/**
 * Whether `base`, a base of the C++ class declaration `decl`, depends on the
 * template parameters of `decl` or a class around it: `template <class T>
 * class Foo : public Base<T>`. A bare name is not looked up in such a base,
 * unless the class brings it in with a using-declaration (cppUsingDeclares).
 */
function isCppDependentBase(decl: Node, base: Node, context: ResolutionContext): boolean {
  const parameters = cppTemplateParameters(decl, context);
  if (parameters.size === 0) return false;
  const spec = cppBaseSpecifiers(decl, context).find((s) => cppLastSegment(stripCppTemplateArguments(s).trim()) === base.name);
  return spec !== undefined && [...parameters].some((p) => new RegExp(`(?<![\\w$])${p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w$])`).test(spec));
}

/**
 * Whether the C++ function `caller` declares `name` before the call at
 * `ref` — a parameter, a local, a lambda's parameter, a range-`for` variable,
 * a structured binding — which a bare call then calls, not a member. A
 * declaration in an earlier block the call is outside of counts too: the
 * name strategies decide, as before.
 */
function isCppLocalName(name: string, caller: Node, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (caller.filePath !== ref.filePath || CPP_CLASS_KINDS.has(caller.kind)) return false;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  if (!lines) return false;
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const word = new RegExp(`\\b${escaped}\\b`);
  const declarator = buildDeclaratorRegex(escaped);
  const listed = buildListedDeclaratorRegex(escaped);
  const nonCode = cppNonCodeLines(caller.filePath, context);
  for (let i = Math.max(0, caller.startLine - 1); i < Math.min(lines.length, ref.line); i++) {
    if (!word.test(lines[i]!)) continue;
    const code = cppCodeOf(cppLiteralsBlanked(lines[i]!, i + 1, nonCode));
    if (!code || !word.test(code)) continue;
    if (cppRebindsReceiver(code, escaped)) return true;
    // `std::function<void()> done;` reads as a declaration once its template arguments are gone.
    for (const variant of [code, stripCppTemplateArguments(code)]) {
      const type = declarator.exec(variant)?.[1];
      // `Owner::name(` is a definition's own declarator; `return name(` no declaration.
      if (type !== undefined && !/::\s*$/.test(type) && normalizeCppTypeName(type) !== null) return true;
    }
    // `std::function<void()> done, failed;` declares `failed` too.
    const listedType = matchCppListedDeclarator(code, name, listed)?.[1];
    if (listedType !== undefined && normalizeCppTypeName(listedType) !== null) return true;
  }
  return false;
}

// What may open a local declaration before its type or `auto`.
const CPP_LOCAL_SPECIFIERS = String.raw`(?:(?:const|constexpr|static|volatile|thread_local|register)\s+)*`;
// A type a local is declared with, as written: `ns::Formatter`, `std::function<void(int)>`, `::Foo`. Its
// template arguments may hold a function type's parentheses, which CPP_TEMPLATE_ARGUMENTS leaves out.
const CPP_LOCAL_TEMPLATE_ARGUMENTS = String.raw`<(?:[^<>;={}]|<(?:[^<>;={}]|<[^<>;={}]*>)*>)*>`;
const CPP_LOCAL_TYPE = String.raw`(?:::\s*)?[A-Za-z_]\w*(?:\s*::\s*[A-Za-z_]\w*)*(?:\s*${CPP_LOCAL_TEMPLATE_ARGUMENTS}(?:\s*::\s*[A-Za-z_]\w*)*)?`;
// Where a statement starts on a line of code: the line's start, or after `;`, `{`, `}`, or a `for`/`if` header's `(`.
const CPP_STATEMENT_START = String.raw`(?:^|[;{}]|\b(?:for|if)\s*\()\s*`;
// Declarations that start a statement, the declared name captured: `auto key = …`, `Formatter format(p);`,
// `const Formatter& format = …`, and the local types `using V = …;`, `typedef … V;`, `struct Getter {`.
const CPP_AUTO_LOCAL = new RegExp(String.raw`${CPP_STATEMENT_START}${CPP_LOCAL_SPECIFIERS}auto(?:\s+|\s*[*&]+\s*)([A-Za-z_]\w*)\s*(?:=|\{|\()`, 'g');
const CPP_TYPED_LOCAL = new RegExp(String.raw`${CPP_STATEMENT_START}${CPP_LOCAL_SPECIFIERS}(${CPP_LOCAL_TYPE})(\s+|\s*[*&]+\s*)(?:const\s+)?([A-Za-z_]\w*)\s*([=({;[,])`, 'g');
const CPP_LOCAL_TYPE_DECLARATION = new RegExp(String.raw`${CPP_STATEMENT_START}(?:using\s+([A-Za-z_]\w*)\s*=|typedef\b[^;]*?\b([A-Za-z_]\w*)\s*;|(?:struct|class|union|enum)(?:\s+class)?\s+([A-Za-z_]\w*)\b)`, 'g');
// A lambda's head, its parameters captured: `[&](const Foo& f) mutable -> bool {`.
const CPP_LAMBDA_HEAD = /\]\s*\(([^()]*)\)\s*(?:mutable\s*)?(?:->[^{;]*)?\{/g;

/** Does `text` hold `name` as a whole word? */
function cppHasWord(text: string, name: string): boolean {
  for (let at = text.indexOf(name); at >= 0; at = text.indexOf(name, at + 1)) {
    if (!/\w/.test(text[at - 1] ?? '') && !/\w/.test(text[at + name.length] ?? '')) return true;
  }
  return false;
}

/** A declaration of a name in a C++ function's own code, at a 0-based line. */
interface CppLocalBinding {
  line: number;
  /**
   * What the name is from there: a parameter (in scope in the whole body), a
   * variable, or a type or a function the body declares, which a call
   * constructs or calls instead.
   */
  kind: 'parameter' | 'variable' | 'type' | 'function';
  /** Where its scope starts: the statement's column, or just inside the `{` of a lambda whose parameter it is. */
  column: number;
  /** For a range-`for` variable: the column of the loop header's `(`, whose body is its scope. */
  loopParen?: number;
}

const CPP_LOCAL_BINDINGS = new WeakMap<ResolutionContext, Map<string, CppLocalBinding[]>>();
const CPP_CALLER_HEADS = new WeakMap<ResolutionContext, Map<string, { parameters: Set<string>; body: number }>>();

/**
 * The names a C++ parameter list declares: `const Formatter& format, int n
 * = 0` → `format`, `n`. A parameter without a name (`const Foo&`, `int`,
 * `const Foo`) declares none.
 */
function cppParameterNames(list: string): string[] {
  const names: string[] = [];
  for (const parameter of splitCppTopLevel(list)) {
    const declarator = parameter.replace(/=[^]*$/, '').trim();
    const m = /([A-Za-z_]\w*)\s*(?:\[[^\]]*\])*$/.exec(declarator);
    if (!m) continue;
    const before = declarator.slice(0, m.index).replace(/\b(?:const|volatile|struct|class|enum|union|typename|signed|unsigned)\b/g, '').trim();
    if (before !== '' && !/::\s*$/.test(before)) names.push(m[1]!);
  }
  return names;
}

/** The text inside the balanced `(…)` opening at line `line`, column `column`, of `codeLine`'s lines, within a dozen lines; null when it doesn't close. */
function cppParenTextFrom(codeLine: (line: number) => string, line: number, column: number): string | null {
  let depth = 0;
  let text = '';
  for (let l = line; l < line + 12; l++) {
    const code = codeLine(l);
    for (let c = l === line ? column : 0; c < code.length; c++) {
      const ch = code[c]!;
      if (ch === '(') depth++;
      else if (ch === ')' && --depth === 0) return text.slice(1);
      text += ch;
    }
    text += ' ';
  }
  return null;
}

/** Does a `T name(args)` local's argument list declare parameters — `void helper(int);`, `Foo make();`, `Foo bar(Baz qux);` — so it declares a function? */
function cppDeclaresLocalFunction(type: string, args: string): boolean {
  if (type === 'void' || args.trim() === '') return true;
  return splitCppTopLevel(args).some((a) =>
    /^(?:int|char|bool|float|double|long|short|unsigned|signed|void|size_t)$/.test(a) ||
    (/^(?:(?:const|volatile|unsigned|signed)\s+)*[A-Za-z_][\w:]*(?:\s*<[^>]*>)?\s*[*&]*\s*(?:[A-Za-z_]\w*)?$/.test(a) && /\s|[*&]/.test(a)));
}

/**
 * The C++ function `caller`'s parameter names, read from the list after its
 * own name on its head, and the line (0-based) its head's name is on, where
 * its body's code begins to be read.
 */
function cppCallerHead(caller: Node, codeLine: (line: number) => string, lineCount: number, context: ResolutionContext): { parameters: Set<string>; body: number } {
  let memo = CPP_CALLER_HEADS.get(context);
  if (!memo) CPP_CALLER_HEADS.set(context, (memo = new Map()));
  const hit = memo.get(caller.id);
  if (hit) return hit;
  const first = caller.startLine - 1;
  let head = { parameters: new Set<string>(), body: first };
  const named = new RegExp(`\\b${caller.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\(`);
  for (let l = first; l < Math.min(lineCount, first + 13); l++) {
    const at = named.exec(codeLine(l));
    if (!at) continue;
    const list = cppParenTextFrom(codeLine, l, at.index + at[0].length - 1);
    head = { parameters: new Set(list === null ? [] : cppParameterNames(list)), body: l };
    break;
  }
  memo.set(caller.id, head);
  return head;
}

/**
 * The declarations of `name` in the C++ function `caller`'s own code, read
 * through `codeLine` (a 0-based line as code): a parameter, then each
 * statement that declares the name — `auto key = [](int i) {…};`,
 * `Formatter format(p);`, `const Formatter& format = …`, a later name in a
 * list, a range-`for` variable, a lambda's parameter. A local type (`using V
 * = …;`, `struct Getter {`) or a function declared in the body (`void
 * helper(int);`) is recorded as what the name is there. An expression that
 * reads like a declaration — `a && f(x)`, `a * f(x)` — declares nothing, and
 * neither does a line that continues one from the line above.
 */
function cppLocalBindings(
  name: string,
  caller: Node,
  head: { parameters: Set<string>; body: number },
  codeLine: (line: number) => string,
  rawLines: readonly string[],
): CppLocalBinding[] {
  const first = caller.startLine - 1;
  const last = Math.min(rawLines.length - 1, (caller.endLine ?? caller.startLine) - 1);
  const bindings: CppLocalBinding[] = head.parameters.has(name) ? [{ line: head.body, column: 0, kind: 'parameter' }] : [];
  // Whether the code above line `l` ends a statement, so a declaration may start the line.
  const startsStatement = (l: number): boolean => {
    for (let k = l - 1; k >= first; k--) {
      const above = codeLine(k);
      if (above.trim() !== '') return /[;{}:]\s*$/.test(above) || /^\s*#/.test(above) || k < head.body;
    }
    return true;
  };
  for (let l = head.body; l <= last; l++) {
    // (Blanking literals and comments only takes text away: a line without the name raw has none as code.)
    if (!cppHasWord(rawLines[l] ?? '', name)) continue;
    const text = codeLine(l);
    if (!cppHasWord(text, name)) continue;
    const starts = (index: number): boolean => index > 0 || l === head.body || startsStatement(l);
    for (const m of text.matchAll(CPP_LOCAL_TYPE_DECLARATION)) {
      if ((m[1] ?? m[2] ?? m[3]) === name && starts(m.index)) bindings.push({ line: l, column: m.index, kind: 'type' });
    }
    for (const m of text.matchAll(CPP_AUTO_LOCAL)) {
      if (m[1] === name && starts(m.index)) bindings.push({ line: l, column: m.index, kind: 'variable' });
    }
    for (const m of text.matchAll(CPP_TYPED_LOCAL)) {
      const type = m[1]!;
      if (m[3] !== name || !starts(m.index) || CPP_NOT_A_DECLARED_TYPE.has(type.split(/[\s<:]/)[0]!) ||
          /^(?:using|typedef|struct|class|union|enum|auto)$/.test(type)) continue;
      let kind: CppLocalBinding['kind'] = 'variable';
      if (m[4] === '(') {
        // `a && f(x)` and `a * f(x)` are expressions.
        if (/[*&]/.test(m[2]!)) continue;
        if (cppDeclaresLocalFunction(type, cppParenTextFrom(codeLine, l, m.index + m[0].length - 1) ?? '')) kind = 'function';
      }
      bindings.push({ line: l, column: m.index, kind });
    }
    if (text.includes(',')) {
      const m = cppListedDeclaratorOn(text, name);
      if (m && starts(m.index)) bindings.push({ line: l, column: m.index, kind: 'variable' });
    }
    const loop = cppRangeForDeclaration(text, name);
    if (loop) bindings.push({ line: l, column: loop.paren, kind: 'variable', loopParen: loop.paren });
    for (const m of text.matchAll(CPP_LAMBDA_HEAD)) {
      if (cppParameterNames(m[1]!).includes(name)) bindings.push({ line: l, column: m.index + m[0].length, kind: 'variable' });
    }
  }
  return bindings;
}

/** Is the code at (`toLine`, `toColumn`) inside the brace block open at (`line`, `column`) — no `}` between them closes it? */
function cppBlockReaches(codeLine: (line: number) => string, line: number, column: number, toLine: number, toColumn: number): boolean {
  let depth = 0;
  for (let l = line; l <= toLine; l++) {
    const text = codeLine(l);
    const end = l === toLine ? Math.min(toColumn, text.length) : text.length;
    for (let c = l === line ? column : 0; c < end; c++) {
      if (text[c] === '{') depth++;
      else if (text[c] === '}' && --depth < 0) return false;
    }
  }
  return true;
}

/**
 * Whether a C++ call written by its bare name calls a local of the calling
 * function — a parameter, a lambda's parameter, a range-`for` variable, or a
 * variable declared above the call in a block still open there — which C++
 * lookup finds before any function or method of that name. protobuf's code
 * generators call `format(…)` on a `const Formatter& format` parameter,
 * which linked to the conformance suite's `TestResult::format`, and rocksdb's
 * tests call local lambdas (`auto key = [](int i) {…};`) that linked to
 * `ArenaWrappedDBIter::key`. A name the function declares as a type (`using
 * V = std::vector<int>;`) or a function (`void helper(int);`) is not one:
 * that call constructs the type or calls the function.
 */
function isCppLocalCallableCall(ref: UnresolvedRef, context: ResolutionContext): boolean {
  const name = ref.referenceName;
  if (!/^[A-Za-z_]\w*$/.test(name) || cppImplicitReceiver(ref, context) !== 'bare') return false;
  const caller = context.getNodeById?.(ref.fromNodeId);
  if (!caller || (caller.kind !== 'function' && caller.kind !== 'method') || caller.filePath !== ref.filePath ||
      caller.name === name || ref.line < caller.startLine || ref.line > (caller.endLine ?? caller.startLine)) return false;
  const rawLines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  if (!rawLines) return false;
  const nonCode = cppNonCodeLines(ref.filePath, context);
  const codeLines = new Map<number, string>();
  const codeLine = (l: number): string => {
    let code = codeLines.get(l);
    if (code === undefined) codeLines.set(l, (code = cppCodeOf(cppLiteralsBlanked(rawLines[l] ?? '', l + 1, nonCode)) ?? ''));
    return code;
  };
  let memo = CPP_LOCAL_BINDINGS.get(context);
  if (!memo) CPP_LOCAL_BINDINGS.set(context, (memo = new Map()));
  const key = `${caller.id}\u0000${name}`;
  let bindings = memo.get(key);
  if (!bindings) {
    const head = cppCallerHead(caller, codeLine, rawLines.length, context);
    memo.set(key, (bindings = cppLocalBindings(name, caller, head, codeLine, rawLines)));
  }
  const callLine = ref.line - 1;
  // The nearest declaration above the call whose scope holds it decides.
  let decided: CppLocalBinding | null = null;
  for (const b of bindings) {
    if (b.line > callLine || (b.line === callLine && b.column >= ref.column)) continue;
    const inScope = b.kind === 'parameter' ||
      (b.loopParen !== undefined
        ? cppForBodyEncloses(rawLines, b.line, b.loopParen, callLine, ref.column)
        : cppBlockReaches(codeLine, b.line, b.column, callLine, ref.column));
    if (inScope && (!decided || b.line > decided.line || (b.line === decided.line && b.column > decided.column))) decided = b;
  }
  return decided?.kind === 'parameter' || decided?.kind === 'variable';
}

/**
 * A C++ source line as code, for reading declarations: null for a `// …`
 * line, else the line with its comments blanked, columns kept. Receiver
 * inference read leveldb's `// … non-null imm_` as a declaration of `imm_`
 * with the type `null`. A line inside a block comment is blank by the time
 * it gets here (cppLiteralsBlanked, from cppNonCodeLines): a line starting
 * with `*` is not one by that alone, as `*widget_;` continuing a declaration
 * is not.
 */
function cppCodeOf(line: string): string | null {
  if (/^\s*\/\//.test(line)) return null;
  let code = line.replace(/\/\*.*?\*\//g, (c) => ' '.repeat(c.length));
  // A block comment opening here runs past the line.
  const open = code.indexOf('/*');
  if (open >= 0) code = code.slice(0, open);
  const comment = code.indexOf('//');
  return comment >= 0 ? code.slice(0, comment) : code;
}

/**
 * Does `line` declare the receiver in a form the declarator pattern doesn't
 * read: a range-`for` variable (`for (const Foo& x : xs)`) or a structured
 * binding (`auto [x, y] = …`)?
 */
function cppRebindsReceiver(line: string, escapedReceiver: string): boolean {
  return new RegExp(String.raw`\bfor\s*\(.*\b${escapedReceiver}\s*:(?!:)`).test(line) ||
    new RegExp(String.raw`\bauto\s*&{0,2}\s*\[[^\]]*\b${escapedReceiver}\b[^\]]*\]`).test(line);
}

/** Record the C++ declaration receiver inference settles on, with the array dimensions its declarator gives it. */
/** A `const` (or `constexpr`) right before a declarator's type: `(Writer& w, const ` of `const Buffer* b`. */
const CPP_LEADING_CONST = /\b(?:const|constexpr)\s+$/;

function noteCppDeclaration(found: CppReceiverDeclaration | undefined, raw: string, callers: boolean, array = 0, constant = false): void {
  if (!found) return;
  found.raw = raw;
  found.callers = callers;
  found.pointer = isCppPointerType(raw);
  found.array = array > 0 ? array : undefined;
  found.constant = constant || undefined;
}

/**
 * A type name that reads as a type (capitalized) yet names no class, struct
 * or interface the project declares: one from outside the project.
 */
function isUndeclaredTypeName(typeName: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return /^[A-Z]/.test(typeName) &&
    !context.getNodesByName(typeName).some((n) => isMethodOwnerKind(n) && sameLanguageFamily(n.language, ref.language));
}

/**
 * Is the qualifier of a C++ `X::m()` call a class the index doesn't hold, as
 * protobuf's `FeatureSet` is (declared in `descriptor.pb.h`, which is over the
 * indexer's size cap)? A capitalized name that no C or C++ type, alias or
 * namespace node has, and that the calling file makes nothing of itself
 * (cppNamesBroughtIn).
 */
function isCppUndeclaredQualifier(qualifier: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  if (!isUndeclaredTypeName(qualifier, ref, context) || cppTypesNamed(qualifier, context).length > 0 ||
      context.getNodesByName(qualifier).some((n) => (n.language === 'cpp' || n.language === 'c') && (n.kind === 'namespace' || n.kind === 'module'))) return false;
  const names = cppNamesBroughtIn(ref.filePath, context);
  return !names.types.has(qualifier) && !names.namespaces.has(qualifier);
}

/**
 * Is the qualifier of a C++ `x::m()` call a namespace, `absl` in
 * `absl::StripPrefix(…)` or `fmt` in `fmt::ptr(p)`, and not a type? A
 * lowercase name that no C or C++ type or alias node has, and that the
 * calling file doesn't declare as a template parameter or an alias
 * (cppNamesBroughtIn). A namespace holds functions and types, never a
 * class's method.
 */
function isCppNamespaceQualifier(qualifier: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return /^[a-z_]/.test(qualifier) && cppTypesNamed(qualifier, context).length === 0 &&
    !cppNamesBroughtIn(ref.filePath, context).types.has(qualifier);
}

/**
 * Is `method` the constructor of the class a C++ call `ns::m(…)` names
 * through its namespace? Its owner, right inside `ns`, is `m` itself or a
 * specialization of the class template `m`, which the index holds without
 * a name: protobuf's `internal::SourceWrapper<absl::Cord>(&data)` constructs
 * the `struct SourceWrapper<absl::Cord>` in message_lite.cc, whose template
 * is only declared. fmt's `template <> struct scanner<num>` is no `scan`.
 */
function isCppConstructorThrough(namespace: string, method: Node, context: ResolutionContext): boolean {
  const parts = method.qualifiedName.split('::');
  if (parts.length < 3 || parts[parts.length - 3] !== namespace) return false;
  const owner = parts[parts.length - 2]!;
  if (owner === method.name) return true;
  if (owner !== '<anonymous>') return false;
  const holder = context.getNodesByQualifiedName(parts.slice(0, -1).join('::')).find((n) =>
    n.filePath === method.filePath && n.startLine <= method.startLine && (n.endLine ?? n.startLine) >= method.startLine);
  const lines = holder ? context.getFileLines?.(holder.filePath) ?? context.readFile(holder.filePath)?.split(/\r?\n/) : undefined;
  const head = holder && lines ? lines.slice(holder.startLine - 1, holder.startLine + 1).join(' ') : '';
  return new RegExp(String.raw`\b(?:class|struct|union)\s+(?:[A-Za-z_]\w*\s+)*${escapeRegExp(method.name)}\s*<`).test(head);
}

/** The names a C++ file makes something of itself, which the index holds no node for (see cppNamesBroughtIn). */
interface CppFileNames {
  /** Template parameters and aliases. */
  types: ReadonlySet<string>;
  /** The namespaces it opens, aliases or uses. */
  namespaces: ReadonlySet<string>;
}

const CPP_FILE_TYPE_NAMES = new WeakMap<ResolutionContext, Map<string, CppFileNames>>();
const CPP_MACRO_TYPE_NAMES = new WeakMap<ResolutionContext, Map<string, ReadonlySet<string>>>();

/**
 * The names a C++ file makes types or namespaces of itself, which the index
 * holds no node for: its template parameters (fmt's `Traits` of `typename
 * Traits = buffer_traits`), the aliases it declares — in a function body
 * too, or by expanding a macro that declares them — and the namespaces it
 * names: opened, aliased or used (`using namespace …;`). googletest's typed
 * tests declare `TypeParam` and `TestFixture`.
 */
function cppNamesBroughtIn(file: string, context: ResolutionContext): CppFileNames {
  let memo = CPP_FILE_TYPE_NAMES.get(context);
  if (!memo) CPP_FILE_TYPE_NAMES.set(context, (memo = new Map()));
  const hit = memo.get(file);
  if (hit) return hit;
  const text = stripCommentsForRegex((context.readFile(file) ?? '').replace(/\\\r?\n/g, ' '), 'cpp');
  const types = cppTypeNamesDeclared(text);
  const namespaces = new Set<string>();
  for (const m of text.matchAll(/\bnamespace\s+([^;{}()]{1,200}?)\s*[;{]/g)) {
    for (const name of m[1]!.match(/[A-Za-z_]\w*/g) ?? []) namespaces.add(name);
  }
  for (const [macro, declared] of cppMacroTypeNames(context)) {
    if (hasCppWord(text, macro)) for (const name of declared) types.add(name);
  }
  if (/\bTYPED_TEST(?:_P)?\s*\(/.test(text)) types.add('TypeParam').add('TestFixture');
  const names = { types, namespaces };
  memo.set(file, names);
  return names;
}

/**
 * The type names each of the project's macros declares where it is
 * expanded: rocksdb's `IMPORT_RIBBON_IMPL_TYPES(T)` declares `using
 * SimpleSoln = …;`, a vendored googletest's `TYPED_TEST` its `TestFixture`.
 */
function cppMacroTypeNames(context: ResolutionContext): Map<string, ReadonlySet<string>> {
  const hit = CPP_MACRO_TYPE_NAMES.get(context);
  if (hit) return hit;
  const macros = new Map<string, ReadonlySet<string>>();
  for (const file of context.getAllFiles()) {
    if (!/\.(?:h|hh|hpp|hxx|h\+\+|inl|inc|ipp|tcc)$/i.test(file)) continue;
    const raw = context.readFile(file);
    if (!raw || !raw.includes('define')) continue;
    // Each `#define` with the lines it continues; only its body is stripped of comments.
    for (const m of raw.matchAll(/^[ \t]*#[ \t]*define[ \t]+([A-Za-z_]\w*)(?:\([^)\n]*\))?((?:[^\n\\]|\\\r?\n|\\(?!\r?\n))*)/gm)) {
      if (macros.has(m[1]!) || !/\b(?:using|typedef|template)\b/.test(m[2]!)) continue;
      const names = cppTypeNamesDeclared(stripCommentsForRegex(m[2]!.replace(/\\\r?\n/g, ' '), 'cpp'));
      if (names.size > 0) macros.set(m[1]!, names);
    }
  }
  CPP_MACRO_TYPE_NAMES.set(context, macros);
  return macros;
}

/** Does `text` hold `word` as a whole identifier? */
function hasCppWord(text: string, word: string): boolean {
  for (let at = text.indexOf(word); at >= 0; at = text.indexOf(word, at + 1)) {
    if (!/\w/.test(text[at - 1] ?? '') && !/\w/.test(text[at + word.length] ?? '')) return true;
  }
  return false;
}

function inferCppReceiverType(
  receiverName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  depth = 0,
  found: CppReceiverDeclaration = {},
): string | null {
  // Per-file lines cache when available — this runs per `receiver->method()`
  // ref and re-splitting the file each time is the same quadratic as the
  // shared inferrer's (#1122).
  const lines = context.getFileLines
    ? context.getFileLines(ref.filePath)
    : (context.readFile(ref.filePath)?.split(/\r?\n/) ?? null);
  if (!lines || lines.length === 0) return null;

  const callLineIndex = Math.max(0, Math.min(lines.length - 1, ref.line - 1));
  const escapedReceiver = receiverName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const receiverPattern = new RegExp(`\\b${escapedReceiver}\\b`);
  const declaratorRegex = buildDeclaratorRegex(escapedReceiver);
  const listedRegex = buildListedDeclaratorRegex(escapedReceiver);
  // A declaration in a string literal is text: protobuf's upb generator
  // writes `upb_MiniTableField field = $field_init$;` in the raw string it
  // emits, above calls on its own `upb::FieldDefPtr field` parameter.
  const rawLines = cppNonCodeLines(ref.filePath, context);
  // Past the calling function's first line, C++ looks the name up among the
  // members of the function's class before anything outside it.
  const caller = context.getNodeById?.(ref.fromNodeId);
  const memberCaller = caller && caller.filePath === ref.filePath && (caller.kind === 'method' || caller.kind === 'function') ? caller : null;
  let memberLooked = memberCaller === null;

  for (let i = callLineIndex; i >= 0; i--) {
    if (!memberLooked && memberCaller && i < memberCaller.startLine - 1) {
      memberLooked = true;
      const member = cppMemberReceiverType(receiverName, memberCaller, ref, context, found);
      if (member !== undefined) return member;
    }
    const text = lines[i];
    if (!text || !receiverPattern.test(text)) continue;
    const line = cppCodeOf(cppLiteralsBlanked(text, i + 1, rawLines));
    if (!line || !receiverPattern.test(line)) continue;

    let declaratorMatch = matchCppDeclarator(line, declaratorRegex) ?? matchCppListedDeclarator(line, receiverName, listedRegex);
    // A parameter named like the function it belongs to is declared after
    // the function's own name on its head: protobuf's `std::string
    // u64(uint64_t u64) {` gives `u64` a `uint64_t`, not a `std::string`.
    if (declaratorMatch && memberCaller?.name === receiverName && line[declaratorMatch.index + declaratorMatch[0].length] === '(') {
      declaratorMatch = matchCppDeclaratorFrom(line, declaratorRegex, declaratorMatch.index + declaratorMatch[0].length) ?? declaratorMatch;
    }
    if (declaratorMatch) {
      const normalized = normalizeCppTypeName(declaratorMatch[1] ?? '');
      if (normalized === 'auto') {
        // `auto x = Foo::instance();` — the declared type is deduced; recover it
        // from the initializer (call return type / construction) (#645).
        const init = cppAutoInitializer(line, receiverName);
        const statement = cppAutoInitializerStatement(line, lines, i, receiverName, rawLines);
        if (init && !found.shadowed && !found.initializer) found.initializer = { line: i + 1, text: statement ?? init };
        // The calling function's own local has the type its initializer has
        // where that is written: `auto iter = std::unique_ptr<Iterator>(…)`,
        // or the `Iterator*` that `txn->GetIterator(…)` is declared to return.
        const local = statement && !found.shadowed && isCppCallersDeclaration(ref.filePath, i + 1, ref, context)
          ? cppAutoLocalType(statement, i + 1, receiverName, ref, context)
          : null;
        const localType = local && normalizeCppTypeName(local.text);
        if (local && localType && localType !== 'auto') {
          noteCppDeclaration(found, local.text, true);
          found.declared = local;
          return cppDeclaredType(local.text, localType, true, ref, context, found);
        }
        const initType = init ? inferCppAutoInitializerType(init, ref, context, depth) : null;
        if (initType) return initType;
        // No usable initializer on this line — keep scanning earlier ones,
        // where what is declared is an earlier variable.
        found.shadowed = true;
      } else if (normalized) {
        const inCallerScope = isCppCallersDeclaration(ref.filePath, i + 1, ref, context);
        const array = cppArrayDimensions(line.slice(declaratorMatch.index + declaratorMatch[0].length));
        noteCppDeclaration(found, declaratorMatch[1]!, inCallerScope, array, CPP_LEADING_CONST.test(line.slice(0, declaratorMatch.index)));
        return cppDeclaredType(declaratorMatch[1]!, normalized, inCallerScope, ref, context, found);
      } else if (cppTypeBeganAbove(declaratorMatch[1] ?? '')) {
        // The end of a declaration begun on an earlier line, maybe the
        // receiver's: one found further up may be another variable.
        found.shadowed = true;
      }
    } else {
      // `for (ConformanceTestSuite *suite : suites)`, when the call is in the
      // loop's body. A loop over `auto` elements has the element type of its
      // range, when that can be read; when it can't, the scan goes on as for
      // an `auto` local whose initializer is unreadable.
      const loopVar = cppRangeForDeclaration(line, receiverName);
      if (loopVar && cppForBodyEncloses(lines, i, loopVar.paren, callLineIndex, ref.column)) {
        const normalized = normalizeCppTypeName(loopVar.type);
        if (normalized && normalized !== 'auto') {
          const inCallerScope = isCppCallersDeclaration(ref.filePath, i + 1, ref, context);
          noteCppDeclaration(found, loopVar.type, inCallerScope);
          return cppDeclaredType(loopVar.type, normalized, inCallerScope, ref, context, found);
        }
        const element = normalized === 'auto' ? cppAutoLoopElement(lines, i, loopVar, ref, context) : null;
        const elementType = element && normalizeCppTypeName(element.text);
        if (element && elementType && elementType !== 'auto') {
          noteCppDeclaration(found, element.text, true);
          found.declared = element;
          return cppDeclaredType(element.text, elementType, true, ref, context, found);
        }
      }
      // A declaration begun on an earlier line, read with the lines it began on.
      const begun = cppDeclarationBegunAbove(lines, i, line, receiverPattern, declaratorRegex, rawLines);
      const begunType = begun && normalizeCppTypeName(begun);
      if (begun && begunType && begunType !== 'auto') {
        const inCallerScope = isCppCallersDeclaration(ref.filePath, i + 1, ref, context);
        noteCppDeclaration(found, begun, inCallerScope);
        return cppDeclaredType(begun, begunType, inCallerScope, ref, context, found);
      }
      // One those lines don't make readable is still maybe the receiver's:
      // one found further up may be another variable.
      if (cppEndsDeclarationBegunAbove(line, escapedReceiver)) found.shadowed = true;
      // `for (auto& [cfh, iter] : cfh_iter_pairs_)`, `auto [status, iter] = Open();`.
      const bound = !found.shadowed ? cppStructuredBindingType(line, lines, i, receiverName, callLineIndex, ref, context, rawLines) : null;
      const boundType = bound && normalizeCppTypeName(bound.text);
      if (bound && boundType && boundType !== 'auto') {
        noteCppDeclaration(found, bound.text, true);
        found.declared = bound;
        return cppDeclaredType(bound.text, boundType, true, ref, context, found);
      }
      if (cppRebindsReceiver(line, escapedReceiver)) found.shadowed = true;
    }
  }
  // (A function that starts on the file's first line.)
  if (!memberLooked && memberCaller) {
    const member = cppMemberReceiverType(receiverName, memberCaller, ref, context, found);
    if (member !== undefined) return member;
  }

  const headerCandidates = [
    ref.filePath.replace(/\.(?:c|cc|cpp|cxx)$/i, '.h'),
    ref.filePath.replace(/\.(?:c|cc|cpp|cxx)$/i, '.hpp'),
    ref.filePath.replace(/\.(?:c|cc|cpp|cxx)$/i, '.hxx'),
  ].filter((candidate, index, arr) => arr.indexOf(candidate) === index && candidate !== ref.filePath);

  for (const headerPath of headerCandidates) {
    if (!context.fileExists(headerPath)) continue;
    const headerLines = context.getFileLines
      ? context.getFileLines(headerPath)
      : (context.readFile(headerPath)?.split(/\r?\n/) ?? null);
    if (!headerLines) continue;
    const headerRawLines = cppNonCodeLines(headerPath, context);

    for (let i = 0; i < headerLines.length; i++) {
      const text = headerLines[i]!;
      if (!receiverPattern.test(text)) continue;
      const line = cppCodeOf(cppLiteralsBlanked(text, i + 1, headerRawLines));
      if (!line) continue;
      const declaratorMatch = matchCppDeclarator(line, declaratorRegex) ?? matchCppListedDeclarator(line, receiverName, listedRegex);
      if (!declaratorMatch) continue;
      const normalized = normalizeCppTypeName(declaratorMatch[1] ?? '');
      if (normalized && normalized !== 'auto') {
        const inCallerScope = isCppCallersDeclaration(headerPath, i + 1, ref, context);
        const array = cppArrayDimensions(line.slice(declaratorMatch.index + declaratorMatch[0].length));
        noteCppDeclaration(found, declaratorMatch[1]!, inCallerScope, array, CPP_LEADING_CONST.test(line.slice(0, declaratorMatch.index)));
        return cppDeclaredType(declaratorMatch[1]!, normalized, inCallerScope, ref, context, found);
      }
    }
  }

  return null;
}

/**
 * The type of a C++ receiver the calling function doesn't declare, as a data
 * member of the function's class (cppCallersMember), recorded in `found` as
 * a declaration of the caller's, where the class writes it. Undefined when
 * it is no member, or the scan passed a declaration of the name it couldn't
 * read (`auto mutex_ = Make();`), which is what the name means there.
 */
function cppMemberReceiverType(
  receiverName: string,
  caller: Node,
  ref: UnresolvedRef,
  context: ResolutionContext,
  found: CppReceiverDeclaration,
): string | null | undefined {
  if (found.shadowed) return undefined;
  const member = cppCallersMember(receiverName, caller, ref, context);
  const normalized = member && normalizeCppTypeName(member.text);
  if (!member || !normalized) return undefined;
  // A member of a template parameter's type (`TComparator cmp_;`), or of an
  // alias of one (`using Shard = typename Cache::Shard;`, protobuf's
  // `using MapFieldBase = std::conditional_t<kIsMutable, …>;`), names no
  // particular class: the call goes on as before.
  const followed = cppFollowWrittenAliases(member, ref, context);
  if (isCppTemplateDependentType(followed ?? member, context) || resolveCppAliasedType(member.text, ref, context) === null) return undefined;
  noteCppDeclaration(found, member.text, true);
  found.declared = member;
  return cppDeclaredType(member.text, normalized, true, ref, context, found);
}

/**
 * Last `::`-separated segment of a (possibly namespace-qualified) C++ name.
 */
function cppLastSegment(name: string): string {
  const parts = name.split('::').filter(Boolean);
  return parts[parts.length - 1] ?? name;
}

/**
 * Return type captured at extraction for `Class::method` (or a free function),
 * read off the indexed node's `returnType` — used by the C++ (#645) and PHP
 * (#608) chained-call resolvers. Language-filtered. Null when not indexed or no
 * return type was recorded (a `void`/primitive return).
 */
function lookupCalleeReturnType(
  callee: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null {
  let method = callee;
  let cls: string | null = null;
  if (callee.includes('::')) {
    const parts = callee.split('::').filter(Boolean);
    method = parts[parts.length - 1] ?? callee;
    cls = parts.slice(0, -1).join('::');
  }
  const candidates = context.getNodesByName(method).filter(
    (n) =>
      (n.kind === 'method' || n.kind === 'function') &&
      n.language === ref.language &&
      !!n.returnType,
  );
  if (cls) {
    const want = `${cls}::${method}`;
    // The call site may name the class with MORE namespace qualification than
    // the stored node (`details::registry::instance` at the call vs
    // `registry::instance` on the node — the receiver type only carries the
    // immediate class), or LESS. Accept an exact match or either being a
    // namespace-suffix of the other; the shared `::<class>::<method>` tail keeps
    // it specific.
    const m = candidates.find(
      (n) =>
        n.qualifiedName === want ||
        n.qualifiedName.endsWith(`::${want}`) ||
        want.endsWith(`::${n.qualifiedName}`),
    );
    return m?.returnType ?? null;
  }
  return candidates.find((n) => n.kind === 'function')?.returnType ?? null;
}

/** Does the graph contain an aggregate type named `name`'s last segment? */
function cppClassExists(name: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const last = cppLastSegment(name);
  return context
    .getNodesByName(last)
    .some((n) => (n.kind === 'class' || n.kind === 'struct' || n.kind === 'union') && n.language === ref.language);
}

/**
 * Infer the class produced by a C++ call/construction expression, using return
 * types captured at extraction (#645). Handles, in order:
 *   - `make_unique<T>()` / `make_shared<T>()`        → T
 *   - single-level member call `recv.method()`       → recv's type, then method's return
 *   - `Class::method()` / free `func()`              → the callee's recorded return type
 *   - direct construction `Type()` / `ns::Type()`    → Type
 * Returns null when undeterminable. Callers MUST still validate the outer method
 * exists on the result before creating an edge, so a wrong guess stays silent.
 */
function resolveCppCallResultType(
  inner: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  depth = 0,
): string | null {
  if (depth > 3) return null; // guard against pathological mutual recursion
  const expr = inner.trim();

  const make = expr.match(/(?:^|::)(?:make_unique|make_shared)\s*<\s*([A-Za-z_]\w*)/);
  if (make) return make[1] ?? null;

  // Single-level member call `recv.method` (the `manager.view().render()` shape).
  const dotIdx = expr.lastIndexOf('.');
  if (dotIdx > 0) {
    const recv = expr.slice(0, dotIdx);
    const method = expr.slice(dotIdx + 1);
    if (recv.includes('.') || recv.includes('(') || recv.includes('::')) return null; // single level only
    const recvType = inferCppReceiverType(recv, ref, context, depth + 1);
    if (!recvType) return null;
    return lookupCalleeReturnType(`${recvType}::${method}`, ref, context);
  }

  const ret = lookupCalleeReturnType(expr, ref, context);
  if (ret) return ret;

  // Direct construction — the callee itself names a class/struct.
  if (cppClassExists(expr, ref, context)) return cppLastSegment(expr);

  return null;
}

/** The initializer of `auto receiverName = …;` on `line`, when the line holds it. */
function cppAutoInitializer(line: string, receiverName: string): string | null {
  const escaped = receiverName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const m = line.match(new RegExp(`\\b${escaped}\\b\\s*=\\s*([^;]+)`));
  return m?.[1]?.trim() || null;
}

/**
 * The whole initializer of `auto receiverName = …;`, which the code `line`
 * (`lines[index]`, comments and literals blanked) begins: read on to the `;`
 * that ends it, since `auto* op = opts->merge_operator` may go on with
 * `->CheckedCast<Foo>();` on the next line. Null when no `;` ends it
 * within a few lines.
 */
function cppAutoInitializerStatement(
  line: string,
  lines: readonly string[],
  index: number,
  receiverName: string,
  rawLines: ReturnType<typeof cppNonCodeLines>,
): string | null {
  const escaped = receiverName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const start = new RegExp(`\\b${escaped}\\b\\s*=(?!=)`).exec(line);
  return start ? cppStatementFrom(line.slice(start.index + start[0].length), lines, index, rawLines) : null;
}

/**
 * The C++ statement that `text`, the rest of `lines[index]`, begins, read on
 * to the `;` that ends it. Null when no `;` ends it within a few lines. A
 * macro body's lines end in `\`, which splices them: protobuf's `const auto&
 * rep = \` goes on with `reflection->GetRaw<…>(message, field); \`.
 */
function cppStatementFrom(
  text: string,
  lines: readonly string[],
  index: number,
  rawLines: ReturnType<typeof cppNonCodeLines>,
): string | null {
  const spliced = (code: string): string => code.replace(/\\\s*$/, ' ');
  text = spliced(text);
  for (let next = index + 1; ; next++) {
    const end = cppStatementEnd(text);
    if (end >= 0) return text.slice(0, end).trim() || null;
    if (next >= lines.length || next > index + 4) return null;
    text += ` ${spliced(cppCodeOf(cppLiteralsBlanked(lines[next]!, next + 1, rawLines)) ?? '')}`;
  }
}

/** A structured binding's names: `[cfh, iter]` in `for (auto& [cfh, iter] : …)` or `const auto [status, iter] = …;`. */
const CPP_STRUCTURED_BINDING = /\bauto\s*&{0,2}\s*\[([^\]]*)\]/g;

/**
 * The type the structured binding on line `index` (`line`, its code) gives
 * `receiverName`, as written: the element at the name's place of the pair
 * or tuple bound. That is an element of the range a range-for over the
 * binding iterates, when the call is in the loop's body — rocksdb's `for
 * (auto& [cfh, iter] : cfh_iter_pairs_)` over a
 * `std::vector<std::pair<ColumnFamilyHandle*, std::unique_ptr<Iterator>>>`,
 * or a map's key and value — or the initializer of a declaration the
 * calling function makes (`auto [status, iter] = Open();`). Null when that
 * can't be read.
 */
function cppStructuredBindingType(
  line: string,
  lines: readonly string[],
  index: number,
  receiverName: string,
  callLineIndex: number,
  ref: UnresolvedRef,
  context: ResolutionContext,
  rawLines: ReturnType<typeof cppNonCodeLines>,
): CppWrittenType | null {
  if (!line.includes('[')) return null;
  for (const m of line.matchAll(CPP_STRUCTURED_BINDING)) {
    const place = m[1]!.split(',').map((name) => name.trim()).indexOf(receiverName);
    if (place < 0) continue;
    const end = m.index! + m[0].length;
    const loop = /\bfor\s*\(\s*(?:(?:const|volatile)\s+)*$/.exec(line.slice(0, m.index!));
    const colon = /^\s*:(?!:)/.exec(line.slice(end));
    let value: CppWrittenType | null = null;
    if (loop && colon) {
      if (!cppForBodyEncloses(lines, index, line.indexOf('(', loop.index), callLineIndex, ref.column)) return null;
      value = cppAutoLoopElement(lines, index, { colon: end + colon[0].length }, ref, context);
    } else {
      const assign = /^\s*=(?!=)/.exec(line.slice(end));
      if (!assign || !isCppCallersDeclaration(ref.filePath, index + 1, ref, context)) return null;
      const init = cppStatementFrom(line.slice(end + assign[0].length), lines, index, rawLines);
      value = init ? cppAutoLocalType(init, index + 1, m[0], ref, context) : null;
    }
    return (value && cppBindingElements(value, ref, context)?.[place]) ?? null;
  }
  return null;
}

/**
 * What calling a function wrapper of the written type `type` returns, as
 * written: what the function type that is its template argument returns
 * (`Iterator*` for `std::function<Iterator*()>`). Only a wrapper's
 * declaration is read with one (CPP_FUNCTION_WRAPPER_TYPE). Null when its
 * template argument is no function type.
 */
function cppWrapperReturnType(type: CppWrittenType): CppWrittenType | null {
  const signature = cppTemplateArguments(type.text)?.[0] ?? '';
  let depth = 0;
  for (let i = 0; i < signature.length; i++) {
    const c = signature[i]!;
    if (c === '<') depth++;
    else if (c === '>') depth--;
    else if (c === '(' && depth === 0) {
      const returned = signature.slice(0, i).trim();
      return returned ? { ...type, text: returned } : null;
    }
  }
  return null;
}

/** What a structured binding of a value of the type `type` names, in order: a `std::pair`'s or `std::tuple`'s elements. */
function cppBindingElements(type: CppWrittenType, at: UnresolvedRef, context: ResolutionContext): CppWrittenType[] | null {
  const followed = cppFollowWrittenAliases(type, at, context);
  const segments = followed && cppTypeSegments(followed.text);
  if (!followed || segments?.length !== 2 || segments[0] !== 'std' || (segments[1] !== 'pair' && segments[1] !== 'tuple')) return null;
  return cppTemplateArguments(followed.text)?.map((text) => ({ ...followed, text: cppWithoutNullability(text) })) ?? null;
}

/**
 * The member `first` or `second` of a `std::pair` of the type `pair`, as a
 * map's iterator points at one: its first or second element. Null for any
 * other member or type.
 */
function cppPairMember(pair: CppWrittenType, member: string, at: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  const index = member === 'first' ? 0 : member === 'second' ? 1 : -1;
  const followed = index >= 0 ? cppFollowWrittenAliases(pair, at, context) : null;
  if (!followed || cppTypeSegments(followed.text)?.join('::') !== 'std::pair') return null;
  const element = cppTemplateArguments(followed.text)?.[index];
  return element ? { ...followed, text: cppWithoutNullability(element) } : null;
}

/** Where the statement that `text` begins ends: its first `;` outside brackets, or -1. */
function cppStatementEnd(text: string): number {
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i]!;
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth--;
    else if (c === ';' && depth <= 0) return i;
  }
  return -1;
}

/**
 * Recover the type of an `auto`-declared local from its initializer `init` on
 * the declaration line — `auto x = Foo::instance();`, `auto w = make_unique<W>();`,
 * `auto p = new W();`, `auto w = Widget();` (#645).
 */
function inferCppAutoInitializerType(
  init: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  depth: number,
): string | null {
  const neu = init.match(/^new\s+([A-Za-z_][\w:]*)/);
  if (neu && neu[1]) return cppLastSegment(neu[1]);

  // A call or construction: `Foo(...)`, `A::b(...)`, `make_unique<T>(...)`.
  const call = init.match(/^([A-Za-z_][\w:]*(?:\s*<[^>;]*>)?)\s*\(/);
  if (call && call[1]) return resolveCppCallResultType(call[1].replace(/\s+/g, ''), ref, context, depth + 1);

  return null;
}

/**
 * A C++ construction — `new log::Writer(…)`, `Writer w(…)`, which the
 * extractor records by the type's last name — makes the class C++ lookup
 * finds for the type as written at the ref (cppClassWritten), as a base
 * class names one (matchCppSupertype): from the scopes around the call
 * outward, its qualifier followed, an alias to the class it names. leveldb's
 * db_impl.cc writes `new log::Writer(…)` in `DBImpl` methods, which also
 * construct `DBImpl::Writer`s, the struct it defines out of line, as `Writer
 * w(…)`; by its last name alone the two were one.
 *  - At 0.7 when lookup doesn't place the type and the class is only the one
 *    of that name the file can see.
 *  - The enum lookup finds instead of a class: rocksdb's `const ValueType
 *    types[] = {kTypeValue, …}`.
 *  - Through an alias the calling function declares itself, which isn't
 *    indexed, the class it names, if one of the project's.
 *  - null (no edge) when the type names no particular class: a template
 *    parameter, a member of a type from outside the project (rocksdb's
 *    `stl_wrappers::KVMap::value_type`), a function's own alias of one —
 *    protobuf's `using Map = std::map<…>; … new Map{}` is no
 *    `google::protobuf::Map`.
 *  - undefined, for the name strategies to decide as before, when nothing
 *    the file sees is named so.
 * The type is read with its template arguments, so `new Outer<int>::Inner(…)`,
 * which the extractor records by the name before the first `<`, makes an
 * `Outer::Inner`. Where the file declares several classes or aliases of the
 * qualified name lookup found, which C++ tells apart and qualified names
 * don't, the type is the one declared around the construction
 * (cppNamesakeAround).
 */
function matchCppConstruction(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const caller = context.getNodeById?.(ref.fromNodeId);
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  const text = lines?.[ref.line - 1]?.slice(Math.max(0, ref.column));
  if (!caller || !text) return undefined;
  // (A declaration's column is where its specifiers start: `const Slice key(…)`.)
  const specifiers = /^(?:(?:new|const|volatile|static|thread_local|constexpr|constinit|mutable|struct|class|union|typename)\s+)*/.exec(text)![0];
  const written = cppTypeWrittenAt(text.slice(specifiers.length));
  if (!written) return undefined;
  const made = (node: Node, exact = true): ResolvedRef => exact
    ? { original: ref, targetNodeId: node.id, confidence: 0.9, resolvedBy: 'qualified-name' }
    : { original: ref, targetNodeId: node.id, confidence: 0.7, resolvedBy: 'exact-match' };
  if (cppDeclaresLocalAlias(written, ref, context)) {
    const aliased = resolveCppAliasedType(written, ref, context);
    const named = aliased && !aliased.pointer ? cppAliasedClass(aliased, context, ref) : undefined;
    const cls = named ? context.getNodesByQualifiedName(named).find((n) => CPP_CLASS_KINDS.has(n.kind)) : undefined;
    return cls ? made(cls) : null;
  }
  const site = cppCallSite(caller, ref, context);
  const found = cppClassWritten(written, site, ref, context);
  if (found === null) {
    const named = cppEnumWritten(written, site, context);
    return named ? made(named) : null;
  }
  if (!found) return undefined;
  const namesakes = context.getNodesByQualifiedName(found.node.qualifiedName)
    .filter((n) => n.filePath === ref.filePath && (CPP_CLASS_KINDS.has(n.kind) || n.kind === 'type_alias'));
  const type = namesakes.length > 1 ? cppNamesakeAround(namesakes, ref, context) : found.node;
  return type ? made(type, found.exact) : undefined;
}

/**
 * The enum a C++ type written at `site` names, which C++ lookup for a class
 * passes by: the first scope around the site, innermost first, that declares
 * one of that name the file can see. (A template parameter of that name is
 * the parameter, which the resolver's type-parameter gate sees to.)
 */
function cppEnumWritten(written: string, site: CppNameSite, context: ResolutionContext): Node | undefined {
  const global = written.trimStart().startsWith('::');
  const path = stripCppTemplateArguments(written).replace(/\s+/g, '').replace(/^::/, '');
  for (const scope of global ? [''] : cppScopesWithin(site.scope)) {
    const enums = context.getNodesByQualifiedName(scope ? `${scope}::${path}` : path)
      .filter((n) => n.kind === 'enum' && (n.filePath === site.file || !C_SOURCE_EXT.test(n.filePath)));
    if (enums.length > 0) return enums.find((n) => n.filePath === site.file) ?? enums[0];
  }
  return undefined;
}

const CPP_HOLDER_KINDS: ReadonlySet<string> = new Set(['function', 'method', 'class', 'struct', 'union']);

/**
 * Of several classes or aliases the ref's file declares under one qualified
 * name — the local classes of rocksdb's gtest `TEST_F` bodies, each a
 * `FakeWF`, or the `Impl`s and `ArgumentTuple`s of googlemock's unnamed
 * specializations — the one whose holder (the function or class it is
 * declared in, else the file) holds the ref. Undefined unless exactly one is.
 */
function cppNamesakeAround(namesakes: Node[], ref: UnresolvedRef, context: ResolutionContext): Node | undefined {
  const holders = context.getNodesInFile(ref.filePath).filter((n) => CPP_HOLDER_KINDS.has(n.kind));
  const around = namesakes.filter((cls) => {
    let holder: Node | undefined;
    for (const n of holders) {
      if (n.id === cls.id || n.startLine > cls.startLine || n.endLine < cls.endLine) continue;
      if (!holder || n.endLine - n.startLine < holder.endLine - holder.startLine) holder = n;
    }
    return !holder || (holder.startLine <= ref.line && ref.line <= holder.endLine);
  });
  return around.length === 1 ? around[0] : undefined;
}

/**
 * The type name `text` starts with, template arguments and all: `log::Writer`
 * of `log::Writer(…)`, `Outer<int>::Inner` of `Outer<int>::Inner x(…)`.
 * Undefined when it starts with none, or a template argument list goes on to
 * the next line.
 */
function cppTypeWrittenAt(text: string): string | undefined {
  let end = 0;
  for (let segment = /^(?:::\s*)?[A-Za-z_]\w*/; ; segment = /^\s*::\s*[A-Za-z_]\w*/) {
    const name = segment.exec(text.slice(end));
    if (!name) return end > 0 ? text.slice(0, end) : undefined;
    end += name[0].length;
    const open = /^\s*</.exec(text.slice(end));
    if (!open) continue;
    end += open[0].length;
    // (`>` inside parentheses compares: `Bits<(N > 8)>`.)
    for (let angles = 1, parens = 0; angles > 0; end++) {
      const c = text[end];
      if (c === undefined) return undefined;
      if (c === '(') parens++;
      else if (c === ')') parens--;
      else if (parens > 0) continue;
      else if (c === '<') angles++;
      else if (c === '>') angles--;
    }
  }
}

/**
 * Resolve a C++ chained call whose receiver is itself a call — encoded by the
 * extractor as `<innerCallee>().<method>` (#645). The receiver's type is what
 * the inner call returns; the outer method is then resolved and VALIDATED on it
 * (resolveMethodOnType requires `cls::method` to exist), so a wrong inference
 * produces no edge rather than a wrong one.
 */
export function matchCppCallChain(
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null {
  const m = ref.referenceName.match(/^(.+)\(\)\.(\w+)$/);
  if (!m || !m[1] || !m[2]) return null;
  const looked = matchCppChainOnWrittenType(m[1], m[2], ref, context);
  if (looked !== undefined) return looked;
  const cls = resolveCppCallResultType(m[1], ref, context);
  if (!cls) return null;
  return resolveMethodOnType(cls, m[2], ref, context, 0.85, 'instance-method');
}

/**
 * A C++ chained call `inner().method` whose inner call's return type is read
 * as its declaration writes it: `method` is that class's, looked up as C++
 * looks the type up there, or no project method's. By the type's last name,
 * protobuf's `generator_factory_->NewEnumGenerator(…)->Generate(…)` in the
 * Java generator reached `csharp::EnumGenerator`, and a call on an
 * `absl::Status` reached `upb::Status`.
 *  - The method of that class or of a class it derives from, 0.85 as before.
 *  - null when the type is from outside the project, or a class that surely
 *    lacks the method (cppLacksMethod).
 *  - undefined when the type can't be read or placed: the last-name path
 *    decides, as before.
 */
function matchCppChainOnWrittenType(inner: string, method: string, ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const type = cppChainInnerType(inner, ref, context);
  const followed = type && cppFollowWrittenAliases(type, ref, context);
  if (!followed || isCppTemplateDependentType(followed, context)) return undefined;
  // (The chain is spelled with `.` for `->` too; `->` on a pointer or a
  // smart pointer reaches what it points at, and `.` on one isn't a call of
  // the project's.)
  const object = cppPointee(followed) ?? followed;
  if (isCppLibraryType(object.text, context)) return null;
  const found = cppClassWritten(object.text, object, ref, context);
  if (found === undefined && isCppOutsideQualifiedType(object.text, object, context)) return null;
  if (!found?.exact || !CPP_CLASS_KINDS.has(found.node.kind)) return undefined;
  const target = cppMethodOf(found.node, method, ref, context);
  if (target) return { original: ref, targetNodeId: target.id, confidence: 0.85, resolvedBy: 'instance-method' };
  return cppLacksMethod(found.node, context) ? null : undefined;
}

/**
 * What the inner call of a C++ chain returns, as written where it is
 * declared: `recv.method` (the extractor spells `->` as `.`), `Class::method`,
 * `func`. Null when that can't be read.
 */
function cppChainInnerType(inner: string, ref: UnresolvedRef, context: ResolutionContext): CppWrittenType | null {
  const dot = inner.lastIndexOf('.');
  if (dot < 0) return cppExpressionType(`${inner}()`, ref, context, 1);
  const recv = inner.slice(0, dot);
  if (!/^[A-Za-z_]\w*$/.test(recv)) return null;
  const op = cppMemberOperator(recv, ref, context);
  const recvType = op ? cppExpressionType(recv, ref, context, 1) : null;
  const followed = recvType && cppFollowWrittenAliases(recvType, ref, context);
  if (!followed) return null;
  const object = op === '->' ? cppDereferenced(followed, ref, context) : isCppPointerType(followed.text) ? null : followed;
  const element = object && cppLibraryElementOf(object, inner.slice(dot + 1), ref, context);
  if (element) return element;
  const cls = object && cppWrittenClass(object, ref, context);
  return cls ? cppReturnTypeOf(cppMethodsOf(cls, inner.slice(dot + 1), ref, context), context) : null;
}

/**
 * Resolve a `::`-scoped factory chain whose receiver is a scoped/static call —
 * PHP `Cls::for($x)->method()` (#608, the per-credential Laravel client idiom) or
 * Rust `Foo::new().bar()` (an associated-function call) — both encoded by the
 * extractor as `Cls::factory().method`. The receiver's type is what `Cls::factory`
 * returns: a `self` marker (PHP `: self`/`: static`, Rust `-> Self`) resolves to
 * the factory's own type, a concrete return type to that type. The outer method is
 * then resolved and VALIDATED on it (resolveMethodOnType requires the method to
 * exist on the type or a supertype it conforms to), so a wrong inference yields no
 * edge rather than a wrong one. Shared by the `::`-receiver languages (PHP, Rust).
 */
export function matchScopedCallChain(
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null {
  const m = ref.referenceName.match(/^(.+)\(\)\.(\w+)$/);
  if (!m || !m[1] || !m[2]) return null;
  const inner = m[1];
  const method = m[2];
  if (!inner.includes('::')) return null; // only static-factory (`Cls::method`) chains
  const factoryClass = inner.slice(0, inner.lastIndexOf('::'));
  const ret = lookupCalleeReturnType(inner, ref, context);
  if (!ret) return null;
  // `self` (the extractor's marker for self/static/$this) → the factory's class.
  const resolvedClass = ret === 'self' ? factoryClass : ret;
  return resolveMethodOnType(resolvedClass, method, ref, context, 0.85, 'instance-method');
}

/**
 * Languages where an unprefixed capitalized call `Foo(args)` constructs the
 * class (so a `Foo(args).method()` receiver's type is `Foo`). Java/C# need `new`,
 * so a bare `Foo()` there is a method call, not construction — excluded. Scala's
 * `Foo(args)` is a case-class / companion `apply`, which conventionally returns
 * `Foo` — and resolveMethodOnType validates, so a non-conventional `apply` that
 * returns another type simply yields no edge rather than a wrong one. Pascal/Delphi:
 * a `TFoo(x)` is a TYPECAST whose result is a `TFoo`, so `TFoo(x).method()` resolves
 * the method on `TFoo` — same shape, same validation.
 */
const CONSTRUCTS_VIA_BARE_CALL = new Set(['kotlin', 'swift', 'scala', 'dart', 'pascal']);

/**
 * Resolve a dotted chained call whose receiver is a static factory / fluent call —
 * `Foo.getInstance().bar()`, encoded by the extractor as `Foo.getInstance().bar`
 * (#645/#608 mechanism). The receiver's type is what `Foo.getInstance` returns
 * (its declared return type); the outer method is then resolved and VALIDATED on
 * it (resolveMethodOnType requires `Type::method` to exist), so a wrong inference
 * yields no edge rather than a wrong one (e.g. a same-named `bar()` on an
 * unrelated class is never matched). Shared by the dot-notation languages
 * (Java, Kotlin, C#, Swift) — same receiver shape, same `Class::method` qualified names.
 */
export function matchDottedCallChain(
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null {
  const m = ref.referenceName.match(/^(.+)\(\)\.(\w+)$/);
  if (!m || !m[1] || !m[2]) return null;
  const inner = m[1]; // `Foo.getInstance`
  const method = m[2]; // `bar`
  const lastDot = inner.lastIndexOf('.');

  if (lastDot <= 0) {
    // Go: bare package-level factory FUNCTION `New().method()` — the receiver's
    // type is what `New` returns; resolve the method on that.
    if (ref.language === 'go') {
      const ret = lookupCalleeReturnType(inner, ref, context);
      if (ret) {
        return resolveMethodOnType(ret, method, ref, context, 0.85, 'instance-method', importedFqnOf(ret, ref, context));
      }
      // `inner` isn't a function with a captured return type — typically a
      // package-level VARIABLE holding a function value (e.g. gin's `engine()`),
      // whose type we can't recover. Fall back to bare-name resolution of the
      // method so we don't DROP an edge the un-re-encoded bare path would have
      // found. (When `inner` IS a real factory function but the method doesn't
      // exist on its return type, `ret` is truthy and we returned no edge above —
      // the absent-method safety guarantee is preserved.)
      //
      // CRITICAL: resolve the TARGET via a synthetic bare-name ref, but return the
      // match tied to the ORIGINAL `ref` (referenceName `inner().method`). The
      // batched resolver (resolveAndPersistBatched) reads unresolved rows from
      // offset 0 every pass and relies on the post-batch cleanup (row-id delete
      // for DB-loaded refs, referenceName-keyed delete otherwise, #1269) to
      // clear each resolved row so the batch empties. If we propagated the
      // synthetic ref's bare `method` as `.original`, a key-based delete
      // would never match the stored `inner().method` row, the batch would
      // never drain, and the loop would re-resolve + re-insert forever (a runaway
      // that grew gin's graph to 5M edges / 1.4 GB before this fix).
      const bareRef = { ...ref, referenceName: method };
      const bareMatch = matchByExactName(bareRef, context) ?? matchFuzzy(bareRef, context);
      return bareMatch ? { ...bareMatch, original: ref } : null;
    }
    // Constructor receiver `Foo(args).method()` (encoded `Foo().method`): a bare,
    // capitalized inner is a class construction, so the receiver's type is the
    // class itself — resolve the method on it. Only in languages where an
    // unprefixed capitalized call constructs the class (Kotlin, Swift); in Java/C#
    // a bare `Foo()` is a method call (constructors need `new`), so we must not
    // assume construction. A lowercase bare inner is a top-level `factory().method()`
    // whose type we can't recover — bail.
    if (!CONSTRUCTS_VIA_BARE_CALL.has(ref.language) || !/^[A-Z]/.test(inner)) return null;
    return resolveMethodOnType(inner, method, ref, context, 0.85, 'instance-method', importedFqnOf(inner, ref, context));
  }

  // Factory/fluent receiver `Receiver.factory(args).method()`: the receiver's
  // type is what `Receiver.factory` returns (its declared return type).
  const factoryClass = inner.slice(0, lastDot).split('.').pop(); // simple class name
  const factoryMethod = inner.slice(lastDot + 1);
  if (!factoryClass || !factoryMethod) return null;
  const ret = lookupCalleeReturnType(`${factoryClass}::${factoryMethod}`, ref, context);
  if (ref.language === 'dart') {
    const declared = ret
      ? resolveMethodOnType(ret, method, ref, context, 0.85, 'instance-method', importedFqnOf(ret, ref, context))
      : null;
    if (declared) return declared;
    // A generic factory returns its type parameter — `static T of<T>(…)` in
    // flutter_bloc's BlocProvider — and one outside the project declares
    // nothing here, so `BlocProvider.of<CounterCubit>(context).increment()`
    // had no type to look `increment` up on. The call site has it: read the
    // chain there as a later link of a chain is read (#750), where `of<T>`'s
    // T is the type argument the call gives. The edge belongs to this ref, not
    // to the bare name it was looked up by (see the gin runaway above).
    const link = matchDartChainLink({ ...ref, referenceName: method }, context);
    return link ? { ...link, original: ref } : null;
  }
  if (!ret) {
    // Objective-C: a class-message factory — `[X alloc]`, `[X new]`,
    // `[X sharedFoo]` — returns an instance of the RECEIVER class `X` by
    // convention (`instancetype`). So when the factory's own return type isn't
    // recoverable (its selector returns `instancetype`, or `alloc`/`new` aren't
    // user-defined nodes at all), the receiver's type is the class `X` itself.
    // This resolves the ubiquitous `[[X alloc] init]` and singleton chains.
    // resolveMethodOnType validates against X (and its supertypes), so a class
    // whose method actually lives elsewhere yields NO edge, not a wrong one — and
    // crucially this does NOT fire when a concrete return type WAS captured but
    // simply lacks the method (that already returned null above: absent-method
    // safety, so a same-named decoy is still never matched).
    if (ref.language === 'objc' && /^[A-Z]/.test(factoryClass)) {
      return resolveMethodOnType(factoryClass, method, ref, context, 0.8, 'instance-method', importedFqnOf(factoryClass, ref, context));
    }
    // Pascal/Delphi: the extractor only re-encodes a `TFoo`/`IFoo`-prefixed chain
    // (the type-naming convention), so `factoryClass` is always a real class here.
    // A factory whose return type wasn't captured is a CONSTRUCTOR
    // (`TFileMem.Create().SetCachePerformance` — `constructor Create` has no `:
    // TBar` annotation but returns its own class) or an unannotated function. In
    // both cases the receiver's type is the class itself, so resolve the method on
    // `factoryClass`. resolveMethodOnType validates against it (and its
    // supertypes), so a wrong inference yields no edge — and this never fires when
    // a return type WAS captured but lacks the method (absent-method safety above).
    if (ref.language === 'pascal' && /^[TI]/.test(factoryClass)) {
      return resolveMethodOnType(factoryClass, method, ref, context, 0.8, 'instance-method', importedFqnOf(factoryClass, ref, context));
    }
    return null;
  }
  return resolveMethodOnType(ret, method, ref, context, 0.85, 'instance-method', importedFqnOf(ret, ref, context));
}

/**
 * When several classes share a simple type name, the caller file's import of
 * that type is the only signal that names WHICH one (#314). Returns the imported
 * FQN for `typeName` in the ref's file, or undefined.
 */
function importedFqnOf(
  typeName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | undefined {
  const imports = context.getImportMappings(ref.filePath, ref.language);
  return imports.find((i) => i.localName === typeName)?.source;
}

/** How many lines past its first a Kotlin call is read for its arguments. */
const KOTLIN_CALL_LINES = 8;

/** An unqualified Kotlin call's head, up to its `(`: `repository(`, `this.repository(`, `make<Foo>(`. */
const KOTLIN_UNQUALIFIED_CALL = /^(?:this\s*\.\s*)?([a-z_]\w*)\s*(?:<[^<>()]*>)?\s*\(/;

/** The index of the `)` closing the `(` at `open` in Kotlin source, string literals skipped; -1 when it doesn't close. */
function kotlinClosingParen(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    const c = text[i]!;
    if (c === '"' || c === "'") {
      for (i++; i < text.length && text[i] !== c; i++) if (text[i] === '\\') i++;
    } else if (c === '(') depth++;
    else if (c === ')' && --depth === 0) return i;
  }
  return -1;
}

/**
 * A Kotlin call written on what an unqualified call returns —
 * `repository().pending(1)`, `this.repository().pending(1)`,
 * `nullable()?.pending(1)` — which the extractor records by the outer
 * method's bare name at the inner call's column (a capitalized inner is a
 * constructor, kept as `Foo().pending`). The inner function's name, or null
 * for any other shape: anything but `!!` between the inner call and the
 * method makes another one (`repository().other().pending()`).
 */
function kotlinCallResultCallee(ref: UnresolvedRef, context: ResolutionContext): string | null {
  if (ref.language !== 'kotlin' || ref.referenceKind !== 'calls' || !/^[A-Za-z_]\w*$/.test(ref.referenceName)) return null;
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  const first = lines?.[ref.line - 1];
  if (!lines || first === undefined) return null;
  const text = [first.slice(Math.max(0, ref.column)), ...lines.slice(ref.line, ref.line + KOTLIN_CALL_LINES)].join('\n');
  const head = KOTLIN_UNQUALIFIED_CALL.exec(text);
  if (!head) return null;
  const close = kotlinClosingParen(text, head[0].length - 1);
  if (close < 0) return null;
  const outer = new RegExp(`^\\s*(?:!!\\s*)?\\??\\.\\s*${escapeRegExp(ref.referenceName)}\\s*[({<]`);
  return outer.test(text.slice(close + 1)) ? head[1]! : null;
}

/**
 * The type an unqualified Kotlin call to `name` returns, as the function it
 * calls declares it (#2805): a method of the calling class, else of a type
 * around the call or one those inherit (kotlinHierarchyAt, read from their
 * declarations), else a top-level function the calling file can name.
 * Undefined when no such function is found, or those found don't declare one
 * type: `fun repository() = RealRepo()` declares none.
 */
function kotlinCallResultType(name: string, ref: UnresolvedRef, context: ResolutionContext): string | undefined {
  const fns = context.getNodesByName(name).filter((n) => n.language === 'kotlin' && (n.kind === 'method' || n.kind === 'function'));
  if (fns.length === 0) return undefined;
  const ownerOf = (qualifiedName: string): string => qualifiedName.slice(0, Math.max(0, qualifiedName.lastIndexOf('::')));
  const caller = context.getNodeById?.(ref.fromNodeId);
  // Inside an extension function on a type from outside the project (`fun
  // URI.toHttpUrlOrNull() = toString()…`), that type's own members are the
  // first a bare call reaches, and they aren't known here.
  if (caller?.kind === 'method') {
    const owner = ownerOf(caller.qualifiedName);
    const member = context.getNodesByQualifiedName(owner).some((n) => MEMBER_CLASS_KINDS.has(n.kind) || n.kind === 'module');
    if (!member && !isKotlinProjectType(owner.split(/::|\./).pop() ?? '', context)) return undefined;
  }
  let pool = caller ? fns.filter((n) => n.kind === 'method' && ownerOf(n.qualifiedName) === ownerOf(caller.qualifiedName)) : [];
  if (pool.length === 0) {
    const hierarchy = kotlinHierarchyAt(ref, context);
    pool = fns.filter((n) => {
      if (n.kind !== 'method') return false;
      const owner = ownerOf(n.qualifiedName).split(/::|\./);
      const type = owner.pop();
      // A companion object's members are called bare inside its class.
      return hierarchy.has(type === 'Companion' ? owner.pop() ?? '' : type ?? '');
    });
  }
  if (pool.length === 0) {
    pool = fns.filter((n) => {
      if (n.kind !== 'function') return false;
      const pkg = kotlinFileScope(n.filePath, context).pkg;
      return n.qualifiedName === (pkg ? `${pkg}::${n.name}` : n.name) && isKotlinTopLevelVisible(n, ref, context);
    });
  }
  const types = new Set(pool.map((n) => kotlinScopedReturnType(n, context) ?? ''));
  return pool.length > 0 && types.size === 1 && !types.has('') ? [...types][0] : undefined;
}

/**
 * The type a Kotlin function declares it returns (kotlinDeclaredReturnType),
 * a name written alone taken as the nested type of the class it is declared
 * in, or of a class around that, that has the name: `fun newBuilder():
 * Builder` in `Request` returns `Request.Builder`, not `Headers.Builder`.
 */
function kotlinScopedReturnType(fn: Node, context: ResolutionContext): string | undefined {
  const written = kotlinDeclaredReturnType(fn);
  if (!written || written.includes('.')) return written;
  const isType = (qualifiedName: string): boolean =>
    context.getNodesByQualifiedName(qualifiedName).some((n) => MEMBER_CLASS_KINDS.has(n.kind) || n.kind === 'module');
  const scopes = fn.qualifiedName.split('::').slice(0, -1);
  for (let i = scopes.length; i > 0; i--) {
    const scope = scopes.slice(0, i).join('::');
    if (isType(scope) && isType(`${scope}::${written}`)) return `${scopes[i - 1]!}.${written}`;
  }
  return written;
}

/**
 * The type a Kotlin function's signature declares it returns, as its type
 * names from the outermost type on, without nullability, type arguments or a
 * package: `(source: Buffer): Hpack.Reader` → `Hpack.Reader`, `(): RealRepo?`
 * → `RealRepo`, `(): List<Foo>` → `List`. Undefined for none, or a function type.
 */
function kotlinDeclaredReturnType(fn: Node): string | undefined {
  const sig = fn.signature?.trim();
  if (!sig?.startsWith('(')) return undefined;
  const close = kotlinClosingParen(sig, 0);
  const written = close < 0 ? undefined : /^\s*:\s*([\s\S]+)$/.exec(sig.slice(close + 1))?.[1];
  const path = written?.trim().replace(/\?+$/, '').replace(/<[\s\S]*>$/, '').trim().split('.').map((p) => p.trim());
  if (!path || !path.every((p) => /^[A-Za-z_]\w*$/.test(p))) return undefined;
  const types = path.slice(path.findIndex((p) => /^[A-Z]/.test(p)));
  return types.length > 0 && types.every((p) => /^[A-Z]/.test(p)) ? types.join('.') : undefined;
}

/** Whether a Kotlin or Java type of the project — a class, interface, enum or object — has the name `name`. */
function isKotlinProjectType(name: string, context: ResolutionContext): boolean {
  return kotlinProjectTypes(name, context).length > 0;
}

/** The project's Kotlin and Java types — classes, interfaces, enums, objects — named `name`. */
function kotlinProjectTypes(name: string, context: ResolutionContext): Node[] {
  return context.getNodesByName(name).filter((n) =>
    (n.language === 'kotlin' || n.language === 'java') && (MEMBER_CLASS_KINDS.has(n.kind) || n.kind === 'module'));
}

/**
 * A Kotlin call on what an unqualified call returns (kotlinCallResultCallee):
 * the method of the type that function declares (#2805), as a
 * `Foo.factory().bar()` chain takes it (matchDottedCallChain), or nothing —
 * never a namesake found by the method's name alone. A nested type the
 * function names through its outer one, `Request.Builder`, is that one, not
 * another type's `Builder`. Undefined when the shape or the declared type
 * can't be read, for the strategies after it.
 */
function matchKotlinCallResultCall(ref: UnresolvedRef, context: ResolutionContext): ResolvedRef | null | undefined {
  const callee = kotlinCallResultCallee(ref, context);
  if (!callee) return undefined;
  const written = kotlinCallResultType(callee, ref, context);
  const path = written?.split('.') ?? [];
  const type = path[path.length - 1];
  // A type from outside the project is no help: its methods, and which of the
  // project's extensions its supertypes take, aren't known here.
  if (!type || !isKotlinProjectType(type, context)) return undefined;
  const name = ref.referenceName;
  const found = resolveMethodOnType(type, name, ref, context, 0.85, 'instance-method', importedFqnOf(type, ref, context));
  // Whole names: `MockResponse::Builder::body` is no `Response::Builder::body`.
  const member = `${path.join('::')}::${name}`;
  const isPathMember = (n: Node): boolean => n.qualifiedName === member || n.qualifiedName.endsWith(`::${member}`);
  if (found) {
    const target = context.getNodeById?.(found.targetNodeId);
    // An extension function, kept under its receiver type's bare name, is
    // the one the calling file can name: Exposed declares `Expression<T>.year()`
    // in three modules, and a test of one calls its own.
    if (target && target.kind === 'method' && !target.qualifiedName.slice(0, target.qualifiedName.lastIndexOf('::')).includes('::')) {
      const visible = context.getNodesByName(name).filter((n) =>
        n.kind === 'method' && n.qualifiedName === target.qualifiedName && isKotlinTopLevelVisible(n, ref, context));
      if (visible.some((n) => n.id === target.id)) return found;
      return visible.length === 1 ? { ...found, targetNodeId: visible[0]!.id } : undefined;
    }
    if (path.length === 1 || (target && isPathMember(target))) return found;
    // Another type's `Builder`: the method of the one the path names, or the strategies after this one.
    const own = context.getNodesByName(name).filter((n) => n.kind === 'method' && isPathMember(n));
    return own.length === 1 ? { original: ref, targetNodeId: own[0]!.id, confidence: 0.85, resolvedBy: 'instance-method' } : undefined;
  }
  // An extension the index doesn't keep under the type may be it: one on a
  // nullable receiver (`fun MediaType?.charsetOrUtf8()`) is a top-level
  // function, one on a nested type (`fun Dns.Call.toEventsQueue()`) is kept
  // under its outer type's bare name (`Dns::toEventsQueue`), where a member's
  // owner carries its package.
  const extension = context.getNodesByName(name).some((n) => n.language === 'kotlin' &&
    (n.kind === 'function' || (n.kind === 'method' && !n.qualifiedName.slice(0, n.qualifiedName.lastIndexOf('::')).includes('::'))));
  return extension ? undefined : null;
}

/**
 * The type a Kotlin local holds when its nearest declaration in the calling
 * function sets it from an unqualified call alone — `val repo =
 * repository()`, `var repo = this.repository()!!` — as that function declares
 * (kotlinCallResultType, #2805). Undefined for any other declaration, or none.
 */
function kotlinLocalCallResultType(receiver: string, ref: UnresolvedRef, context: ResolutionContext): string | undefined {
  const lines = context.getFileLines?.(ref.filePath) ?? context.readFile(ref.filePath)?.split(/\r?\n/);
  if (!lines) return undefined;
  const r = escapeRegExp(receiver);
  const declares = new RegExp(`\\b(?:val|var)\\s+${r}\\b`);
  const initializer = new RegExp(`^(?:val|var)\\s+${r}\\s*=\\s*(?:this\\s*\\.\\s*)?([a-z_]\\w*)\\s*(?:<[^<>()]*>)?\\s*\\(`);
  const start = Math.max(0, enclosingScopeStartLine(ref, context) - 1);
  for (let i = Math.min(lines.length, ref.line) - 1; i >= start; i--) {
    const line = lines[i]!;
    const at = declares.exec(i === ref.line - 1 ? line.slice(0, Math.max(0, ref.column)) : line);
    if (!at) continue;
    const text = [line.slice(at.index), ...lines.slice(i + 1, i + 1 + KOTLIN_CALL_LINES)].join('\n');
    const call = initializer.exec(text);
    if (!call) return undefined;
    const close = kotlinClosingParen(text, call[0].length - 1);
    if (close < 0 || !/^[ \t]*(?:!![ \t]*)?(?:;|\/\/|\r?\n|$)/.test(text.slice(close + 1))) return undefined;
    // Only a type of the project's (see matchKotlinCallResultCall), and a
    // nested one only when no other type shares its name: the type is looked
    // up by its last name from here on.
    const path = kotlinCallResultType(call[1]!, ref, context)?.split('.') ?? [];
    const types = path.length > 0 ? kotlinProjectTypes(path[path.length - 1]!, context) : [];
    return types.length === 1 || (types.length > 1 && path.length === 1) ? path[path.length - 1] : undefined;
  }
  return undefined;
}

/** Per-context memo: `<file>\0<type name as written>` → tsImportedTypeFile's answer. */
const TS_IMPORTED_TYPE_FILES = new WeakMap<ResolutionContext, Map<string, string | null>>();

/**
 * The file declaring the type a TS/JS file imports under the name a
 * declaration in it writes (`store: DisposableStore`, `new async.Delayer()`),
 * or undefined when the file doesn't import that name. Several classes may
 * share it, a vendored copy, a test fixture or another app's, and the import
 * is what says which one the file means: on vscode, calls on a
 * `DisposableStore` imported from `vs/base/common/lifecycle` reached
 * copilot's vendored copy of that file, the first declaration indexed, and
 * a call whose first declaration was a test fixture's linked to nothing.
 */
export function tsImportedTypeFile(written: string, ref: UnresolvedRef, context: ResolutionContext): string | undefined {
  const name = /^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*/.exec(written.trim())?.[0];
  if (!name) return undefined;
  let memo = TS_IMPORTED_TYPE_FILES.get(context);
  if (!memo) {
    memo = new Map();
    TS_IMPORTED_TYPE_FILES.set(context, memo);
  }
  const key = ref.filePath + '\0' + name;
  let file = memo.get(key);
  if (file === undefined) {
    file = null;
    const binding = name.split('.')[0]!;
    if (context.getImportMappings?.(ref.filePath, ref.language)?.some((i) => i.localName === binding)) {
      const imported = context.resolveImport?.({ ...ref, referenceName: name, referenceKind: 'references' });
      const node = imported ? context.getNodeById?.(imported.targetNodeId) : undefined;
      // A type the blocks declaring one module merge (vscode's proposed API files add
      // members to `vscode.d.ts`'s interfaces) has no one file that holds every member.
      if (node && node.kind !== 'file' && node.filePath !== ref.filePath && !isMergedAmbientDeclaration(node, context)) file = node.filePath;
    }
    memo.set(key, file);
  }
  return file ?? undefined;
}

/**
 * Java/Kotlin: infer a receiver's declared type by walking field declarations
 * in the class enclosing the call site. The field's `signature` is already in
 * the form "<TypeName> <fieldName>" (set by tree-sitter.ts extractField), so we
 * pull the type from there. Handles Spring `@Resource UserBO userbo;` /
 * `@Autowired private UserService userService;` where the receiver field name
 * doesn't match the class name by Java naming convention.
 *
 * Returns the bare type name (generics stripped, dotted package stripped) or
 * null when no matching field is in the enclosing class.
 */
function inferJavaFieldReceiverType(
  receiverName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null {
  const inFile = context.getNodesInFile(ref.filePath);
  if (inFile.length === 0) return null;
  if (ref.language === 'java') return javaEnclosingFieldType(receiverName, ref, inFile);

  // Find the class enclosing the call line (tightest match by latest start).
  let enclosing: Node | null = null;
  for (const n of inFile) {
    if (n.kind !== 'class' && n.kind !== 'interface') continue;
    if (n.language !== ref.language) continue;
    const end = n.endLine ?? n.startLine;
    if (n.startLine <= ref.line && end >= ref.line) {
      if (!enclosing || n.startLine >= enclosing.startLine) enclosing = n;
    }
  }
  if (!enclosing) return null;

  // A Kotlin object expression (`object : Callback { … }`) sees the scope it
  // is written in: a property it does not declare itself is one of the class
  // around it — okhttp's `server.url(…)` in an `object : Callback`'s
  // `onResponse` is the test class's `MockWebServer`.
  while (ref.language === 'kotlin' && isAnonymousClass(enclosing)) {
    const anon: Node = enclosing;
    const own = inFile.find((n) => (n.kind === 'field' || n.kind === 'constant' || n.kind === 'variable') &&
      n.qualifiedName === `${anon.qualifiedName}::${receiverName}`);
    if (own) return inferKotlinPropertyType(receiverName, own, anon, inFile, ref, context);
    let outer: Node | null = null;
    for (const n of inFile) {
      if ((n.kind !== 'class' && n.kind !== 'interface') || n.language !== ref.language) continue;
      if (n.startLine < anon.startLine && (n.endLine ?? n.startLine) >= ref.line &&
          (!outer || n.startLine >= outer.startLine)) outer = n;
    }
    if (!outer) return null;
    enclosing = outer;
  }

  const enclosingEnd = enclosing.endLine ?? enclosing.startLine;
  const enclosingAnon = anonymousDepth(enclosing.qualifiedName);
  // Kotlin indexes a `val` property as a `constant`, a `var` as a `field`, and
  // a companion-object property as a `variable`. One of an object expression
  // in the class's code is that object's.
  const field = inFile.find(
    (n) =>
      (n.kind === 'field' || (ref.language === 'kotlin' && (n.kind === 'constant' || n.kind === 'variable'))) &&
      n.name === receiverName &&
      n.language === ref.language &&
      n.startLine >= enclosing.startLine &&
      (n.endLine ?? n.startLine) <= enclosingEnd &&
      !(ref.language === 'kotlin' && anonymousDepth(n.qualifiedName) > enclosingAnon),
  );
  // Kotlin keeps no signature on a property, and a primary-constructor
  // property (`class A(private val repo: Repo)`) is no node at all, so the
  // declared type has to be read from the declaration itself.
  if (ref.language === 'kotlin') {
    return inferKotlinPropertyType(receiverName, field ?? null, enclosing, inFile, ref, context);
  }
  return field ? fieldSignatureType(field) : null;
}

/**
 * The declared type of a Java/Kotlin field node, read from its signature
 * ("<TypeName> <fieldName>", set by tree-sitter.ts extractField): generics,
 * a dotted package and array/varargs markers stripped — for Java, in
 * javaTypeName's form, which keeps a written package and outer class. Null
 * for a primitive or a field without a signature.
 */
function fieldSignatureType(field: Node): string | null {
  if (!field.signature) return null;
  const typeRaw = field.signature.slice(0, field.signature.lastIndexOf(field.name)).trim();
  if (!typeRaw) return null;
  if (field.language === 'java') return javaTypeName(typeRaw);

  const typeNoGenerics = typeRaw.replace(/<[^>]*>/g, '').trim();
  const typeNoArray = typeNoGenerics.replace(/\[\s*\]/g, '').replace(/\.\.\.$/, '').trim();
  const parts = typeNoArray.split(/[.\s]+/).filter(Boolean);
  const lastPart = parts[parts.length - 1];
  if (!lastPart) return null;
  if (!/^[A-Z]/.test(lastPart)) return null; // primitives / lowercase → skip
  return lastPart;
}

/**
 * A Java type as written (`Foo`, `java.util.List<Foo>`, `Map.Entry<K, V>`,
 * `play.api.mvc.BodyParser<B>`, `Foo[]`), type arguments and array markers
 * dropped. The class chain is joined with `::` (`Map::Entry`), so a nested
 * type is never taken for a same-named type nested elsewhere, and a package
 * written in source stays in front of it, dotted (`play.api.mvc.BodyParser`),
 * for javaTypeRef to pin the declaration with. Null for a primitive.
 */
function javaTypeName(raw: string): string | null {
  let type = raw;
  for (let prev = ''; prev !== type; ) {
    prev = type;
    type = type.replace(/<[^<>]*>/g, '');
  }
  type = type.replace(/\[\s*\]/g, '').replace(/\.\.\.$/, '').replace(/\s+/g, '');
  const segments = type.split('.').filter(Boolean);
  let first = segments.length;
  while (first > 0 && /^[A-Z][\w$]*$/.test(segments[first - 1]!)) first--;
  const chain = segments.slice(first).join('::');
  if (!chain || NON_TYPE_RECEIVER_TOKENS.has(chain)) return null;
  const pkg = segments.slice(0, first).join('.');
  return pkg ? `${pkg}.${chain}` : chain;
}

/**
 * Java: the declared type of the field a receiver names — `mHandler`,
 * `this.mHandler`, or `Outer.this.mHandler`. The field is looked up in the
 * class enclosing the call and then in each class around it, tightest first,
 * because an inner or anonymous class reads its outer classes' fields
 * (`mHandler.post(...)` inside a `new Runnable() {…}`); `Outer.this.f` names
 * the class to read. A `static final` field is indexed as a `constant`.
 */
function javaEnclosingFieldType(receiverName: string, ref: UnresolvedRef, inFile: Node[]): string | null {
  const m = receiverName.match(/^(?:(?:(\w+)\.)?this\.)?(\w+)$/);
  if (!m) return null;
  const [, outer, fieldName] = m;
  const enclosing = inFile
    .filter(
      (n) =>
        (n.kind === 'class' || n.kind === 'interface' || n.kind === 'enum') &&
        n.language === 'java' &&
        n.startLine <= ref.line &&
        (n.endLine ?? n.startLine) >= ref.line,
    )
    .sort((a, b) => b.startLine - a.startLine);
  for (const cls of enclosing) {
    if (outer && cls.name !== outer) continue;
    const field = inFile.find(
      (n) =>
        (n.kind === 'field' || n.kind === 'constant') &&
        n.name === fieldName &&
        n.qualifiedName === `${cls.qualifiedName}::${fieldName}`,
    );
    if (field) return fieldSignatureType(field);
    if (outer) return null;
  }
  return null;
}

/**
 * Stands for "a type the project does not declare" — a library class, or a
 * field reached through one — so the caller can refuse a name-only guess.
 */
const JAVA_EXTERNAL_TYPE = '\u0000external';

const JVM_DECLARED_TYPE_KINDS = new Set<Node['kind']>(['class', 'interface', 'enum', 'struct', 'trait']);

/** JVM type declarations named `name`. */
function jvmTypeDecls(name: string, context: ResolutionContext): Node[] {
  return context
    .getNodesByName(name)
    .filter((n) => JVM_DECLARED_TYPE_KINDS.has(n.kind) && sameLanguageFamily(n.language, 'java'));
}

/**
 * Whether `decl` is the type one of `fqns` (an import, or a package written
 * in source) names: the Java declaration of that qualified name or file, or
 * a Scala / Kotlin one in that package's directory (their qualified names
 * carry no package, and their files need not be named after the type).
 */
function declaresJvmFqn(decl: Node, fqns: string[]): boolean {
  const dotted = decl.qualifiedName.replace(/::/g, '.');
  const declPath = decl.filePath.replace(/\\/g, '/');
  const declFile = declPath.replace(/\.\w+$/, '');
  const declDir = declPath.slice(0, declPath.lastIndexOf('/') + 1);
  return fqns.some((fqn) => {
    const fqnPath = fqn.replace(/\./g, '/');
    if (dotted === fqn || declFile === fqnPath || declFile.endsWith('/' + fqnPath)) return true;
    const pkgPath = fqnPath.slice(0, fqnPath.lastIndexOf('/') + 1);
    return decl.language !== 'java' && pkgPath !== '' && (declDir === pkgPath || declDir.endsWith('/' + pkgPath));
  });
}

/**
 * Whether Java file `filePath` can name `decl` by its simple name without
 * importing it — for a type read from a declaration (a field's, a local's),
 * where isJavaTypeVisible judges a name written at a reference. A Java
 * qualified name reads `package::Outer::Inner`; a nested type is named that
 * way only in its own file, in its own package (as `Outer.Inner`), or where
 * its top-level class is imported. A top-level type of another package is
 * also reachable through a wildcard import, which the import mappings do not
 * list, so it counts as visible, and so does a Scala or Kotlin declaration,
 * whose qualified name carries no package to check. A class also names the
 * nested types of the classes it extends or implements (SystemUI's
 * `AlertEntry` in a subclass of `AlertingNotificationManager`).
 */
function isJavaTypeNameable(decl: Node, filePath: string, context: ResolutionContext): boolean {
  if (decl.language !== 'java' || decl.filePath === filePath) return true;
  const segments = decl.qualifiedName.split('::');
  const hasPackage = segments.length > 1 && /^[a-z]/.test(segments[0]!);
  const classChain = hasPackage ? segments.slice(1) : segments;
  if (classChain.length <= 1) return true;
  const pkg = hasPackage ? segments[0]! : '';
  if (pkg === javaFileScope(filePath, context).pkg) return true;
  const outer = pkg ? `${pkg}.${classChain[0]}` : classChain[0]!;
  if (context.getImportMappings(filePath, 'java').some((i) => i.source === outer || i.source.startsWith(outer + '.'))) return true;
  // `import play.mvc.Http.*;` names Http's nested types.
  if (javaFileScope(filePath, context).demand.has(segments.slice(0, -1).join('.'))) return true;
  const ancestors = javaFileAncestors(filePath, context);
  return context.getNodesByQualifiedName(segments.slice(0, -1).join('::')).some((o) => ancestors.has(o.id));
}

/** Per-context memo: Java file → ids of the classes its classes extend or implement. */
const JAVA_FILE_ANCESTORS = new WeakMap<ResolutionContext, Map<string, Set<string>>>();

/** The Java classes and interfaces the classes of `filePath` extend or implement, up to five levels up. */
function javaFileAncestors(filePath: string, context: ResolutionContext): Set<string> {
  let memo = JAVA_FILE_ANCESTORS.get(context);
  if (!memo) JAVA_FILE_ANCESTORS.set(context, (memo = new Map()));
  const hit = memo.get(filePath);
  if (hit) return hit;
  const classes = context.getNodesInFile(filePath).filter((n) => n.language === 'java' && isMethodOwnerKind(n));
  const seen = new Set<string>(classes.map((c) => c.id));
  const ancestors = new Set<string>();
  let frontier = classes;
  for (let depth = 0; depth < 5 && frontier.length > 0; depth++) {
    const next: Node[] = [];
    for (const cls of frontier) {
      for (const sup of declaredSupertypes(cls, context)) {
        for (const decl of context.getNodesByName(sup)) {
          if (decl.language !== 'java' || !isMethodOwnerKind(decl) || seen.has(decl.id)) continue;
          seen.add(decl.id);
          ancestors.add(decl.id);
          next.push(decl);
        }
      }
    }
    frontier = next;
  }
  memo.set(filePath, ancestors);
  return ancestors;
}

/** A Java receiver type the project declares. */
type JavaTypeRef = {
  /** The class chain resolveMethodOnType matches (`Http::Cookie`). */
  name: string;
  /** The declaration an import or a written package pins, when one does. */
  decl?: Node;
};

/**
 * What a Java type written in `filePath` (javaTypeName's form) is: a project
 * type, or null for a library one (`Parcel`, `Context`, `List`), which none
 * of the project's methods belongs to. It is a library type when the project
 * declares no JVM type of its outer name; when an import, or a package
 * written in source, names a type the project does not declare (`import
 * java.util.Iterator` beside a project `UByteArray.Iterator`); when every
 * project type of that name is one the file cannot name that way (a nested
 * type of another package); or when a project class declares no nested type
 * of the written name (`MyLayout.LayoutParams`, inherited from a library
 * class). A short all-caps name (`T`, `VH`) is taken for a type parameter,
 * whose bound may be a project type, and left alone.
 */
function javaTypeRef(written: string, filePath: string, context: ResolutionContext): JavaTypeRef | null {
  const chainStart = written.indexOf('::');
  const head = chainStart < 0 ? written : written.slice(0, chainStart);
  const lastDot = head.lastIndexOf('.');
  const pkg = lastDot < 0 ? '' : head.slice(0, lastDot);
  const chain = written.slice(lastDot + 1).split('::');
  const outer = chain[0]!;
  if (!pkg && chain.length === 1 && /^[A-Z][A-Z0-9]{0,2}$/.test(outer)) return { name: outer };
  const decls = jvmTypeDecls(outer, context);
  if (decls.length === 0) return null;
  const pins = pkg
    ? [`${pkg}.${outer}`]
    : context.getImportMappings(filePath, 'java').filter((i) => i.localName === outer).map((i) => i.source);
  if (pins.length === 0) {
    if (!decls.some((d) => isJavaTypeNameable(d, filePath, context))) return null;
    if (chain.length === 1) return { name: outer };
    const name = chain.join('::');
    const nested = jvmTypeDecls(chain[chain.length - 1]!, context).some(
      (n) => n.qualifiedName === name || n.qualifiedName.endsWith(`::${name}`),
    );
    return nested ? { name } : null;
  }
  let decl = decls.find((d) => declaresJvmFqn(d, pins));
  for (const segment of chain.slice(1)) {
    if (!decl) break;
    const owner: Node = decl;
    decl = jvmTypeDecls(segment, context).find((n) => n.qualifiedName === `${owner.qualifiedName}::${segment}`);
  }
  if (!decl) return null;
  const segments = decl.qualifiedName.split('::');
  const hasPackage = decl.language === 'java' && segments.length > 1 && /^[a-z]/.test(segments[0]!);
  return { name: (hasPackage ? segments.slice(1) : segments).join('::'), decl };
}

/**
 * Resolve a method on a Java receiver type: the pinned declaration's own
 * method first, then resolveMethodOnType on the class chain, then — for a
 * nested chain, which the supertype walk there cannot look up — the
 * supertypes of its simple name. A Scala or Kotlin declaration pinned by an
 * import is not followed further than its own methods: the class chain alone
 * matches a same-named Java type as well.
 */
function resolveOnJavaType(
  type: JavaTypeRef,
  methodName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null {
  if (type.decl) {
    const decl = type.decl;
    const own = context
      .getNodesByName(methodName)
      .find((n) => n.kind === 'method' && n.qualifiedName === `${decl.qualifiedName}::${methodName}`);
    if (own) return { original: ref, targetNodeId: own.id, confidence: 0.9, resolvedBy: 'instance-method' };
    if (decl.language !== 'java') return null;
  }
  const fqn = type.decl ? type.decl.qualifiedName.replace(/::/g, '.') : undefined;
  const direct = resolveMethodOnType(type.name, methodName, ref, context, 0.9, 'instance-method', fqn);
  if (direct || !type.name.includes('::') || !context.getSupertypes) return direct;
  for (const supertype of context.getSupertypes(type.name.split('::').pop()!, 'java')) {
    const via = resolveMethodOnType(supertype, methodName, ref, context, 0.9, 'instance-method', undefined, 1);
    if (via) return via;
  }
  return null;
}

/** `Type.FIELD`, `Outer.Inner.FIELD`, `pkg.Type.FIELD`: a value a type holds, as a call's receiver. */
const JAVA_STATIC_FIELD_RECEIVER = /^((?:[a-z_$][\w$]*\.)*(?:[A-Z][\w$]*\.)*[A-Z][\w$]*)\.([A-Za-z_$][\w$]*)$/;

/**
 * The static field `name` of Java type `owner`, its own or one it inherits
 * from the types it extends or implements (an interface's constant), a few
 * levels up. An enum's constant counts.
 */
function javaStaticField(owner: Node, name: string, context: ResolutionContext): Node | undefined {
  const seen = new Set<string>([owner.id]);
  let frontier = [owner];
  for (let depth = 0; depth < 5 && frontier.length > 0; depth++) {
    const next: Node[] = [];
    for (const type of frontier) {
      const own = context
        .getNodesByQualifiedName(`${type.qualifiedName}::${name}`)
        .find((n) => n.filePath === type.filePath && (n.kind === 'field' || n.kind === 'constant' || n.kind === 'enum_member'));
      if (own) return own;
      for (const sup of declaredSupertypes(type, context)) {
        const written = javaTypeName(sup);
        const ref = written ? javaTypeRef(written, type.filePath, context) : null;
        const tail = written?.split('.').pop() ?? '';
        const decls = ref?.decl ? [ref.decl]
          : ref ? jvmTypeDecls(tail.split('::').pop()!, context).filter((d) => d.qualifiedName === ref.name || d.qualifiedName.endsWith(`::${ref.name}`))
          : [];
        for (const decl of decls) {
          if (seen.has(decl.id)) continue;
          seen.add(decl.id);
          next.push(decl);
        }
      }
    }
    frontier = next;
  }
  return undefined;
}

/**
 * Java's `Type.FIELD.m()` — `Consts.HELPER.go()`, `Outer.Inner.SHARED.run()`,
 * `ProjectInterpolators.LOCAL.getInterpolation(t)`, `Color.RED.hex()`: a call
 * on a value a type holds in a static field, an interface's constant or an
 * enum's constant. The field is the type's own or one it inherits, and its
 * value is typed by its own declaration, read with its own file's imports: the
 * method an anonymous class it is initialized with declares (a `CREATOR`'s
 * `createFromParcel`), else the class a `new X(…)` initializer builds, else
 * the declared type's. A Kotlin object's `INSTANCE` and a class's
 * `Companion`, as Java writes them, are the type itself. Null — no edge — for
 * a field of a type from outside the project (`Intent.ACTION_VIEW.equals(…)`)
 * or a value of one; undefined when the receiver is no type's field (a local,
 * a nested type), for the strategies below.
 */
function matchJavaStaticFieldCall(
  receiver: string,
  methodName: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null | undefined {
  const m = JAVA_STATIC_FIELD_RECEIVER.exec(receiver);
  if (!m) return undefined;
  const [, ownerWritten, fieldName] = m;
  const head = ownerWritten!.split('.')[0]!;
  // A local or a field of that name holds a value, not a type.
  if (/^[A-Z]/.test(head) && (inferLocalReceiverType(head, ref, context) || inferJavaFieldReceiverType(head, ref, context))) return undefined;
  const written = javaTypeName(ownerWritten!);
  if (!written) return undefined;
  const ownerType = javaTypeRef(written, ref.filePath, context);
  if (!ownerType) return null;
  const owners = ownerType.decl ? [ownerType.decl]
    : jvmTypeDecls(ownerType.name.split('::').pop()!, context).filter((d) =>
      (d.qualifiedName === ownerType.name || d.qualifiedName.endsWith(`::${ownerType.name}`)) && isJavaTypeNameable(d, ref.filePath, context));
  const owner = owners.length === 1 ? owners[0]! : owners.find((d) => d.filePath === ref.filePath);
  if (!owner) return undefined;
  const found = (n: Node | undefined): ResolvedRef | null =>
    n ? { original: ref, targetNodeId: n.id, confidence: 0.9, resolvedBy: 'instance-method' } : null;
  const methodOf = (typeQn: string, file: string): Node | undefined =>
    context.getNodesByQualifiedName(`${typeQn}::${methodName}`).find((n) => n.kind === 'method' && n.filePath === file);
  if (owner.language === 'kotlin' && (fieldName === 'INSTANCE' || fieldName === 'Companion')) {
    return found(methodOf(owner.qualifiedName, owner.filePath));
  }
  // `Outer.Inner.m()` is a static call on a nested type, not on a field.
  if (context.getNodesByQualifiedName(`${owner.qualifiedName}::${fieldName}`).some((n) => JVM_DECLARED_TYPE_KINDS.has(n.kind))) return undefined;
  const field = javaStaticField(owner, fieldName!, context);
  if (!field || field.language !== 'java') return undefined;
  if (field.kind === 'enum_member') {
    // A constant's own body overrides first (`PLUS { int apply(…) }`), then the enum's method.
    const enumQn = field.qualifiedName.slice(0, field.qualifiedName.lastIndexOf('::'));
    const enumDecl = context.getNodesByQualifiedName(enumQn).find((n) => n.filePath === field.filePath && JVM_DECLARED_TYPE_KINDS.has(n.kind));
    const segments = enumQn.split('::');
    const chain = segments.length > 1 && /^[a-z]/.test(segments[0]!) ? segments.slice(1).join('::') : enumQn;
    return found(methodOf(field.qualifiedName, field.filePath) ?? methodOf(enumQn, field.filePath)) ??
      (enumDecl ? resolveOnJavaType({ name: chain, decl: enumDecl }, methodName, ref, context) : null);
  }
  // An anonymous class the field is initialized with: its own method.
  const anonMethod = context
    .getNodesInFile(field.filePath)
    .filter((n) => n.kind === 'class' && n.qualifiedName.startsWith(`${field.qualifiedName}::<`) && n.name.includes('$anon@'))
    .map((anon) => methodOf(anon.qualifiedName, field.filePath))
    .find((n) => n !== undefined);
  if (anonMethod) return found(anonMethod);
  // A `new X(…)` initializer builds X, the declared type's subtype at most.
  const lines = context.getFileLines?.(field.filePath) ?? context.readFile(field.filePath)?.split(/\r?\n/) ?? [];
  const declText = lines.slice(field.startLine - 1, Math.min(lines.length, (field.endLine ?? field.startLine))).join('\n');
  const built = new RegExp(`\\b${field.name.replace(/\$/g, '\\$')}\\s*=\\s*new\\s+((?:[\\w$]+\\s*\\.\\s*)*[\\w$]+)\\s*(?:<[^()]*>)?\\s*\\(`).exec(declText)?.[1]?.replace(/\s+/g, '');
  if (built) {
    const builtName = javaTypeName(built);
    const builtType = builtName ? javaTypeRef(builtName, field.filePath, context) : null;
    if (builtType) {
      const viaBuilt = resolveOnJavaType(builtType, methodName, ref, context);
      if (viaBuilt) return viaBuilt;
    }
  }
  const declared = fieldSignatureType(field);
  if (!declared) return null;
  const declaredType = javaTypeRef(declared, field.filePath, context);
  return declaredType ? resolveOnJavaType(declaredType, methodName, ref, context) : null;
}

/**
 * Java: the declared type of a receiver the field lookup reaches — a field
 * (`mRepo`, `this.mRepo`, `Outer.this.mRepo`) or a chain of up to three
 * fields after it (`mState.menu`, `this.mOwner.mRepo`), whose head may also
 * be a local. Each hop reads the field declared on the previous hop's type,
 * and reads that field's type with its own file's imports.
 * JAVA_EXTERNAL_TYPE as soon as a hop's type is a library one; null when a
 * hop cannot be typed (an inherited field, an untyped local).
 */
function javaReceiverDeclaredType(
  receiver: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): JavaTypeRef | typeof JAVA_EXTERNAL_TYPE | null {
  const m = receiver.match(/^((?:\w+\.)?this\.\w+|[A-Za-z_$][\w$]*)((?:\.[a-zA-Z_$][\w$]*){0,3})$/);
  if (!m) return null;
  const [, head, rest] = m;
  const segments = rest ? rest.slice(1).split('.').filter(Boolean) : [];
  const headType =
    // A plain receiver's local declaration was already read by the caller.
    (segments.length > 0 && !head!.includes('.')
      ? inferLocalReceiverType(head!, ref, context)
      : null) ?? inferJavaFieldReceiverType(head!, ref, context);
  if (!headType) return null;
  // A type parameter of the class or method around the call (`TState
  // mTmpState` in `QSTileImpl<TState extends State>`) is no library type: its
  // bound decides, which matchMethodCall reads when this answers null. As
  // there, only a name no project class has: typeParameterBound also reads a
  // type argument (`Comparable<ApplicationModule>`) as a parameter.
  if (/^[A-Z][\w$]*$/.test(headType) && !context.getNodesByName(headType).some(isMethodOwnerKind) &&
      typeParameterBound(headType, ref, context) !== undefined) return null;
  let written = headType;
  let filePath = ref.filePath;
  for (const segment of segments) {
    const type = javaTypeRef(written, filePath, context);
    if (!type) return JAVA_EXTERNAL_TYPE;
    const owner = type.decl?.qualifiedName;
    const field = context
      .getNodesByName(segment)
      .find(
        (n) =>
          (n.kind === 'field' || n.kind === 'constant') &&
          n.language === 'java' &&
          (owner
            ? n.qualifiedName === `${owner}::${segment}`
            : n.qualifiedName.endsWith(`::${type.name}::${segment}`) || n.qualifiedName === `${type.name}::${segment}`),
      );
    const fieldType = field ? fieldSignatureType(field) : null;
    if (!fieldType) return null;
    written = fieldType;
    filePath = field!.filePath;
  }
  return javaTypeRef(written, filePath, context) ?? JAVA_EXTERNAL_TYPE;
}

/**
 * The declared type of a Kotlin property named `name` in class `owner`: from
 * the property's own declaration lines when it is a node (`lateinit var repo:
 * Repo`, `val repo = Repo(…)`), otherwise from the class header, where a
 * primary-constructor property (`class A(private val repo: Repo)`) lives. The
 * header is the class's lines before its first member, so a same-named local
 * inside a method body is never read as the property. Returns null when no
 * declaration names a type; resolveMethodOnType still validates the method.
 */
function inferKotlinPropertyType(
  name: string,
  property: Node | null,
  owner: Node,
  inFile: Node[],
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null {
  const lines = kotlinFileLines(ref.filePath, context);
  if (!lines) return null;

  if (property) {
    const text = lines.slice(Math.max(0, property.startLine - 1), Math.min(lines.length, property.endLine ?? property.startLine));
    return kotlinDeclaredTypeIn(text.join('\n'), name, ref, context);
  }
  return kotlinDeclaredTypeIn(kotlinClassHeader(owner, inFile, lines), name, ref, context);
}

/** A file's lines through the context's per-file cache; null when unreadable. */
function kotlinFileLines(filePath: string, context: ResolutionContext): string[] | null {
  const lines = context.getFileLines
    ? context.getFileLines(filePath)
    : (context.readFile(filePath)?.split(/\r?\n/) ?? null);
  return lines && lines.length > 0 ? lines : null;
}

/**
 * A Kotlin class's lines before its first member: its annotations, name,
 * primary constructor and supertype list.
 */
function kotlinClassHeader(owner: Node, inFile: Node[], lines: string[]): string {
  const ownerEnd = owner.endLine ?? owner.startLine;
  let firstMember = ownerEnd + 1;
  for (const n of inFile) {
    if (n.id === owner.id || n.kind === 'file') continue;
    if (n.startLine > owner.startLine && n.startLine <= ownerEnd && n.startLine < firstMember) {
      firstMember = n.startLine;
    }
  }
  return lines.slice(Math.max(0, owner.startLine - 1), Math.min(lines.length, firstMember - 1)).join('\n');
}

/**
 * The supertype names a Kotlin class header lists after its primary
 * constructor (`class A(…) : Base(…), Iface<T>, Api by impl {`), as
 * kotlinTypeName gives them. Colons and commas inside the constructor or
 * type arguments are skipped; a `where` clause or the body ends the list.
 */
function kotlinSupertypeNames(header: string, className: string): string[] {
  const r = className.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const decl = new RegExp(`\\b(?:class|object|interface)\\s+${r}\\b`).exec(header);
  if (!decl) return [];
  const entries: string[] = [];
  let paren = 0;
  let angle = 0;
  let start = -1;
  let i = decl.index + decl[0].length;
  for (; i < header.length; i++) {
    const c = header[i]!;
    if (c === '(') paren++;
    else if (c === ')') paren--;
    else if (paren > 0) continue;
    else if (c === '<') angle++;
    else if (c === '>') angle--;
    else if (angle > 0) continue;
    else if (c === '{') break;
    else if (start >= 0 && c === 'w' && /^where\b/.test(header.slice(i, i + 6)) && !/\w/.test(header[i - 1] ?? '')) break;
    else if (c === ':' && start < 0) start = i + 1;
    else if (c === ',' && start >= 0) {
      entries.push(header.slice(start, i));
      start = i + 1;
    }
  }
  if (start >= 0) entries.push(header.slice(start, i));
  const names: string[] = [];
  for (const entry of entries) {
    const m = entry.match(/^\s*(?:@\w+\s+)*([A-Za-z_][\w.]*)/);
    const type = m && m[1] ? kotlinTypeName(m[1]) : null;
    if (type) names.push(type);
  }
  return names;
}

/**
 * The declared type of Kotlin property `name` if class `owner` declares it —
 * as a member node or a primary-constructor `val`/`var` — read in the
 * owner's own file. Undefined when the owner does not declare it; null when
 * it does without a type the declaration names.
 */
function kotlinOwnPropertyType(
  name: string,
  owner: Node,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null | undefined {
  const inFile = context.getNodesInFile(owner.filePath);
  const qualified = `${owner.qualifiedName}::${name}`;
  const property = inFile.find(
    (n) => (n.kind === 'field' || n.kind === 'constant' || n.kind === 'variable') && n.qualifiedName === qualified,
  ) ?? null;
  if (!property) {
    const lines = kotlinFileLines(owner.filePath, context);
    const r = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (!lines || !new RegExp(`\\b(?:val|var)\\s+${r}\\b`).test(kotlinClassHeader(owner, inFile, lines))) {
      return undefined;
    }
  }
  // Read the declaration in the owner's file, as if the ref sat there.
  const at: UnresolvedRef = { ...ref, filePath: owner.filePath, line: property?.startLine ?? owner.startLine };
  return inferKotlinPropertyType(name, property, owner, inFile, at, context);
}

/**
 * The declared type of Kotlin property `name` that class `owner` inherits: the
 * nearest project supertype (breadth-first, at most four levels) declaring it,
 * with supertypes read from each class header. A supertype the project does
 * not declare, or whose name is ambiguous, is not walked — the property may
 * come from it — so the result is then null (unknown), never external.
 */
function kotlinInheritedPropertyType(
  name: string,
  owner: Node,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null {
  const seen = new Set<string>([owner.id]);
  let level: Node[] = [owner];
  for (let depth = 0; depth < 4 && level.length > 0; depth++) {
    const next: Node[] = [];
    for (const cls of level) {
      const lines = kotlinFileLines(cls.filePath, context);
      if (!lines) continue;
      const header = kotlinClassHeader(cls, context.getNodesInFile(cls.filePath), lines);
      for (const superName of kotlinSupertypeNames(header, cls.name)) {
        const simple = superName.split('::').pop()!;
        const supers = context.getNodesByName(simple).filter(
          (n) => (n.kind === 'class' || n.kind === 'interface') && n.language === 'kotlin' &&
            (n.qualifiedName === superName || n.qualifiedName.endsWith(`::${superName}`)),
        );
        if (supers.length !== 1 || seen.has(supers[0]!.id)) continue;
        const sup = supers[0]!;
        seen.add(sup.id);
        const type = kotlinOwnPropertyType(name, sup, ref, context);
        if (type !== undefined) return type;
        next.push(sup);
      }
    }
    level = next;
  }
  return null;
}


/** Node kinds that declare a type a receiver can have. */
const DECLARED_TYPE_KINDS = new Set<Node['kind']>([
  'class', 'interface', 'struct', 'enum', 'type_alias', 'trait', 'protocol', 'union',
]);

/**
 * Whether the project declares `typeName` (simple, or `Outer::Inner`) in the
 * ref's language family. False for library types (`Regex`, `Properties`).
 */
function isProjectType(typeName: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  const simple = typeName.split('::').pop()!;
  return context.getNodesByName(simple).some(
    (n) =>
      DECLARED_TYPE_KINDS.has(n.kind) &&
      sameLanguageFamily(n.language, ref.language) &&
      (!typeName.includes('::') || n.qualifiedName === typeName || n.qualifiedName.endsWith(`::${typeName}`)),
  );
}

/**
 * A Kotlin type written in source (`Lease?`, `HardwareLock.Lease`,
 * `List<Foo>`) as a name resolveMethodOnType matches: nullability and type
 * arguments dropped, a nested type joined with `::`, a package prefix
 * (lowercase segments) dropped. Null when it is not a type name.
 */
function kotlinTypeName(raw: string): string | null {
  const cleaned = raw.replace(/<[^>]*>/g, '').replace(/\?/g, '').trim();
  const segments = cleaned.split('.').filter(Boolean);
  let first = segments.length;
  while (first > 0 && /^[A-Z]\w*$/.test(segments[first - 1]!)) first--;
  const typeSegments = segments.slice(first);
  return typeSegments.length > 0 ? typeSegments.join('::') : null;
}

/**
 * Stands for "a type the project does not declare" — a library class, or the
 * result of a call on one — so the caller can refuse a name-only guess.
 */
export const KOTLIN_EXTERNAL_TYPE = '\u0000external';

/**
 * The type a Kotlin declaration of `name` in `text` gives it: `name: Type`, a
 * constructor call `name = Type(…)`, or a call `name = Owner.fn(…)` /
 * `name = fn(…)`, typed by `fn`'s declared return type. KOTLIN_EXTERNAL_TYPE
 * when the owner is not a project type; null when nothing names a type.
 */
function kotlinDeclaredTypeIn(
  text: string,
  name: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  depth = 0,
): string | null {
  const r = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const typed = text.match(new RegExp(`\\b(?:val|var)\\s+${r}\\s*:\\s*([A-Z][\\w.]*)`));
  if (typed && typed[1]) return kotlinTypeName(typed[1]);
  // An alias of another value: `val old = ws`, `val s = current ?: return`,
  // `val s = current!!` — typed as that value.
  const alias = text.match(new RegExp(`\\b(?:val|var)\\s+${r}\\s*=\\s*([a-z_]\\w*)\\s*(?:!!|\\?:\\s*(?:return|continue|break|throw)\\b[^\\n]*)?\\s*$`, 'm'));
  if (alias && alias[1] && alias[1] !== name && depth < 3) {
    return kotlinReceiverDeclaredType(alias[1], ref, context, depth + 1);
  }
  // `(` or a trailing lambda `{`: `Thread { … }`, `thread { … }`.
  // Type arguments are skipped: `WebRtcPlaneSession<IceCandidate>(plane)`.
  const assigned = text.match(new RegExp(`\\b(?:val|var)\\s+${r}\\s*=\\s*([A-Za-z_][\\w.]*)\\s*(?:<[\\w\\s.,?*<>]*>\\s*)?[({]`));
  if (!assigned || !assigned[1]) {
    // An enum entry or other constant of a type: `var mode = GpsMode.ON`.
    const entry = text.match(new RegExp(`\\b(?:val|var)\\s+${r}\\s*=\\s*([A-Z]\\w*(?:\\.[A-Z]\\w*)*)\\.[A-Z][A-Z0-9_]*\\b(?!\\s*[.(])`));
    if (!entry || !entry[1]) return null;
    // Only an entry of a project enum names its type; `Limits.MAX` is an Int.
    const type = kotlinTypeName(entry[1]);
    const simple = type?.split('::').pop();
    return simple && context.getNodesByName(simple).some(
      (n) => n.kind === 'enum' && sameLanguageFamily(n.language, ref.language),
    ) ? type : null;
  }
  const segments = assigned[1].split('.');
  const last = segments.pop()!;
  if (/^[A-Z]/.test(last)) return kotlinTypeName(assigned[1]);
  // A call. Only an owner written as a type chain (`Lock.tryBegin`) or none at
  // all (`beginOp()`) can be typed; `a.b.fn()` goes through values.
  if (segments.length > 0 && !segments.every((seg) => /^[A-Z]/.test(seg))) return null;
  if (segments.length === 0 && KOTLIN_ARGUMENT_PASSTHROUGH.has(last)) {
    const arg = text.match(new RegExp(`\\b${last}\\s*\\(\\s*([A-Za-z_]\\w*)\\s*[,)]`));
    if (!arg || !arg[1] || arg[1] === name) return null;
    // The argument is a parameter or local of the same scope.
    const argType = inferLocalReceiverType(arg[1], ref, context);
    return argType && /^[A-Z]/.test(argType) ? argType : null;
  }
  return kotlinQualifiedCallResultType(segments.length > 0 ? segments.join('::') : undefined, last, ref, context);
}

/** Kotlin stdlib functions whose result is always a library type. */
const KOTLIN_LIBRARY_FACTORIES = new Set([
  'listOf', 'mutableListOf', 'arrayListOf', 'emptyList', 'listOfNotNull',
  'setOf', 'mutableSetOf', 'hashSetOf', 'linkedSetOf', 'sortedSetOf', 'emptySet',
  'mapOf', 'mutableMapOf', 'hashMapOf', 'linkedMapOf', 'sortedMapOf', 'emptyMap',
  'arrayOf', 'arrayOfNulls', 'emptyArray', 'intArrayOf', 'longArrayOf', 'byteArrayOf',
  'sequenceOf', 'emptySequence', 'buildList', 'buildSet', 'buildMap', 'buildString',
  'lazy', 'thread', 'mutableStateOf', 'Channel', 'MutableStateFlow', 'MutableSharedFlow',
]);

/** Stdlib functions that return their (non-null) argument: `requireNotNull(x)`. */
const KOTLIN_ARGUMENT_PASSTHROUGH = new Set(['requireNotNull', 'checkNotNull']);

/**
 * The declared return type of Kotlin `owner.fn` (or of an unqualified `fn`, a
 * method of the ref's own class first, then one in the same file). Every
 * candidate must declare the same return type. A return type nested in the
 * callee's owner keeps that owner (`Lease` in `HardwareLock` →
 * `HardwareLock::Lease`). KOTLIN_EXTERNAL_TYPE for a call on a type the
 * project does not declare (`Executors.newSingleThreadScheduledExecutor()`).
 */
function kotlinQualifiedCallResultType(
  owner: string | undefined,
  fn: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null {
  if (owner && !isProjectType(owner, ref, context)) return KOTLIN_EXTERNAL_TYPE;
  let candidates = context.getNodesByName(fn).filter(
    (n) => (n.kind === 'method' || n.kind === 'function') && n.language === 'kotlin' && !!n.signature,
  );
  if (owner) {
    candidates = candidates.filter((n) => n.qualifiedName.endsWith(`${owner}::${fn}`));
  } else {
    const ownClass = context.getNodesInFile(ref.filePath)
      .filter((n) => (n.kind === 'class' || n.kind === 'interface') && n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line)
      .sort((a, b) => b.startLine - a.startLine)[0];
    const inOwnClass = ownClass
      ? candidates.filter((n) => n.qualifiedName === `${ownClass.qualifiedName}::${fn}`)
      : [];
    const inFile = candidates.filter((n) => n.filePath === ref.filePath);
    candidates = inOwnClass.length > 0 ? inOwnClass : inFile.length > 0 ? inFile : candidates;
  }
  // No project function of that name. A known stdlib factory returns a
  // library type; any other library function (`requireNotNull`, `let`) may
  // return a project value, so its result stays unknown.
  if (candidates.length === 0) return !owner && KOTLIN_LIBRARY_FACTORIES.has(fn) ? KOTLIN_EXTERNAL_TYPE : null;

  let result: string | null = null;
  for (const c of candidates) {
    const sig = c.signature!;
    const at = sig.lastIndexOf('):');
    if (at < 0) return null;
    let type = kotlinTypeName(sig.slice(at + 2));
    if (!type) return null;
    if (!type.includes('::')) {
      const container = c.qualifiedName.slice(0, c.qualifiedName.lastIndexOf('::'));
      const containerName = container.split('::').pop();
      if (containerName && context.getNodesByQualifiedName(`${container}::${type}`).some((n) => DECLARED_TYPE_KINDS.has(n.kind))) {
        type = `${containerName}::${type}`;
      }
    }
    if (result !== null && result !== type) return null;
    result = type;
  }
  return result;
}

/**
 * The declared type of Kotlin receiver `name` at `ref`: the nearest local
 * declaration in the enclosing scope (typed, constructed, or bound to a call),
 * else a property of the enclosing class, else a parameter, else a property
 * the enclosing class inherits. Null when none names a type.
 */
function kotlinReceiverDeclaredType(
  name: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
  depth = 0,
): string | null {
  const lines = kotlinFileLines(ref.filePath, context);
  let localDeclared = false;
  if (lines) {
    const r = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const declares = new RegExp(`\\b(?:val|var)\\s+${r}\\b`);
    for (const i of kotlinLocalScanLines(ref, context, lines.length)) {
      const line = lines[i];
      if (!line || line.length > 10_000 || !declares.test(line)) continue;
      const local = kotlinDeclaredTypeIn(line, name, ref, context, depth);
      if (local) return local;
      localDeclared = true;
      break;
    }
  }
  const property = inferJavaFieldReceiverType(name, ref, context);
  if (property) return property;
  // A typed parameter of the enclosing function or lambda (`webSocket:
  // WebSocket` in an overridden callback).
  const param = inferLocalReceiverType(name, ref, context);
  if (param) return /^[A-Z]/.test(param) ? param : null;
  if (localDeclared) return null;
  // A property of a superclass: `viewModel` declared in `BaseActivity`. In an
  // object expression, of the class it is written in, unless the object
  // declares the name itself.
  const around = kotlinEnclosingClasses(ref, context);
  const owner = around[around.length - 1];
  if (!owner || around.some((c) => kotlinOwnPropertyType(name, c, ref, context) !== undefined)) return null;
  return kotlinInheritedPropertyType(name, owner, ref, context);
}

/** The tightest Kotlin class or interface enclosing `ref`'s line. */
function kotlinEnclosingClass(ref: UnresolvedRef, context: ResolutionContext): Node | undefined {
  return context.getNodesInFile(ref.filePath)
    .filter((n) => (n.kind === 'class' || n.kind === 'interface') && n.language === 'kotlin' &&
      n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line)
    .sort((a, b) => b.startLine - a.startLine)[0];
}

/**
 * The Kotlin classes enclosing `ref`'s line, tightest first: each object
 * expression (`object : Callback { … }`) the line is in, whose code sees the
 * scope it is written in, through the first named class.
 */
function kotlinEnclosingClasses(ref: UnresolvedRef, context: ResolutionContext): Node[] {
  const around = context.getNodesInFile(ref.filePath)
    .filter((n) => (n.kind === 'class' || n.kind === 'interface') && n.language === 'kotlin' &&
      n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line)
    .sort((a, b) => b.startLine - a.startLine);
  const out: Node[] = [];
  for (const c of around) {
    out.push(c);
    if (!isAnonymousClass(c)) break;
  }
  return out;
}

/**
 * The 0-based lines a Kotlin local visible at `ref` may be declared on,
 * nearest first: the enclosing function above the call, then — when that
 * function is nested in another (a member of an anonymous object, a local
 * function) — each outer function above the nested one, whose locals it
 * captures. Lines of a function nested in a scanned one that does not
 * enclose `ref` are skipped: its locals are not visible. Outside any
 * function, every line above the call.
 */
function kotlinLocalScanLines(ref: UnresolvedRef, context: ResolutionContext, lineCount: number): number[] {
  const callIdx = Math.max(0, Math.min(lineCount - 1, ref.line - 1));
  const fns = context.getNodesInFile(ref.filePath).filter(
    (n) => (n.kind === 'function' || n.kind === 'method') && n.language === 'kotlin',
  );
  const enclosing = fns
    .filter((n) => n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line)
    .sort((a, b) => b.startLine - a.startLine);
  const out: number[] = [];
  if (enclosing.length === 0) {
    for (let i = callIdx; i >= 0; i--) out.push(i);
    return out;
  }
  let hi = callIdx;
  for (const fn of enclosing) {
    const fnEnd = fn.endLine ?? fn.startLine;
    const hidden = fns.filter(
      (n) => n.startLine > fn.startLine && (n.endLine ?? n.startLine) <= fnEnd &&
        !(n.startLine <= ref.line && (n.endLine ?? n.startLine) >= ref.line),
    );
    for (let i = hi; i >= fn.startLine - 1; i--) {
      if (!hidden.some((n) => i + 1 >= n.startLine && i + 1 <= (n.endLine ?? n.startLine))) out.push(i);
    }
    hi = Math.min(hi, fn.startLine - 2);
  }
  return out;
}

/**
 * The declared type of a Kotlin receiver chain `a.b.c` / `this.a.b`: the first
 * value typed as a single receiver (`this` is the enclosing class, a type name
 * its object or companion), each next segment as a property or enum entry
 * declared in the class of the type before it, read from that class's own
 * file. KOTLIN_EXTERNAL_TYPE as soon as a segment has a
 * type the project does not declare; null when any segment's type is unknown
 * (an inherited property, an ambiguous class name).
 */
function kotlinChainDeclaredType(
  receiver: string,
  ref: UnresolvedRef,
  context: ResolutionContext,
): string | null {
  const segments = receiver.split('.');
  if (segments.length < 2 || segments.length > 4) return null;

  let owner: Node | undefined;
  if (segments[0] === 'this') {
    owner = kotlinEnclosingClass(ref, context);
    if (!owner) return null;
  }
  let type: string | null = owner ? null : kotlinReceiverDeclaredType(segments[0]!, ref, context);
  if (!owner && !type && /^[A-Z]/.test(segments[0]!)) {
    // An object or a class's companion: `Registry.current.load()`,
    // `Mode.ON.next()`.
    const classes = context.getNodesByName(segments[0]!).filter(
      (n) => DECLARED_TYPE_KINDS.has(n.kind) && n.language === 'kotlin',
    );
    if (classes.length !== 1) return null;
    owner = classes[0]!;
  }
  for (const segment of segments.slice(1)) {
    if (!owner) {
      if (!type) return null;
      if (type === KOTLIN_EXTERNAL_TYPE || !isProjectType(type, ref, context)) return KOTLIN_EXTERNAL_TYPE;
      const t = type;
      const classes = context.getNodesByName(t.split('::').pop()!).filter(
        (n) => DECLARED_TYPE_KINDS.has(n.kind) && n.language === 'kotlin' &&
          (n.qualifiedName === t || n.qualifiedName.endsWith(`::${t}`)),
      );
      if (classes.length !== 1) return null;
      owner = classes[0]!;
    }
    const inFile = context.getNodesInFile(owner.filePath);
    const qualified = `${owner.qualifiedName}::${segment}`;
    if (inFile.some((n) => n.kind === 'enum_member' && n.qualifiedName === qualified)) {
      // An enum entry has its enum's type (`Outer::Mode`, package dropped).
      type = kotlinTypeName(owner.qualifiedName.split('::').join('.'));
      owner = undefined;
      continue;
    }
    const own = kotlinOwnPropertyType(segment, owner, ref, context);
    type = own !== undefined ? own : kotlinInheritedPropertyType(segment, owner, ref, context);
    owner = undefined;
  }
  return type;
}

/** A Kotlin call through a receiver chain: `a.b.m`, `this.a.m`, `a.b.c.d.m`. */
const KOTLIN_CHAIN_REF = /^((?:this|[A-Za-z_]\w*)(?:\.[A-Za-z_]\w*){1,3})\.(\w+)$/;

/**
 * A Kotlin call through a receiver chain (`engine.pump.drain()`), resolved on
 * the chain's declared type. Null — no edge — when the chain ends in a type
 * the project does not declare (or passes through one) and the project has
 * no extension of that name on a library type. When the type is
 * unknown, `{ method }` names the bare method for the caller to resolve, the
 * ref the extractor emitted before it kept the chain. Undefined for a ref
 * that is not a receiver chain.
 */
export function matchKotlinReceiverChain(
  ref: UnresolvedRef,
  context: ResolutionContext,
): ResolvedRef | null | { method: string } | undefined {
  const m = ref.referenceName.match(KOTLIN_CHAIN_REF);
  if (!m) return undefined;
  const method = m[2]!;
  const declared = kotlinChainDeclaredType(m[1]!, ref, context);
  if (!declared) return { method };
  if (declared !== KOTLIN_EXTERNAL_TYPE) {
    const typed = resolveMethodOnType(declared, method, ref, context, 0.9, 'instance-method');
    if (typed) return typed;
    if (isProjectType(declared, ref, context)) return { method };
  }
  // A library type still reaches the project's own extensions of library
  // types (`view.context.dp(8)` → `fun Context.dp()`).
  return kotlinDeclaresLibraryExtension(method, ref, context) ? { method } : null;
}

/**
 * Whether the project declares a Kotlin extension `method` on a type it does
 * not declare itself (`fun Context.dp(…)`, indexed as `Context::dp`).
 */
function kotlinDeclaresLibraryExtension(method: string, ref: UnresolvedRef, context: ResolutionContext): boolean {
  return context.getNodesByName(method).some((n) => {
    if ((n.kind !== 'method' && n.kind !== 'function') || n.language !== 'kotlin') return false;
    const owner = n.qualifiedName.split('::').slice(-2, -1)[0];
    return !!owner && /^[A-Z]/.test(owner) && !isProjectType(owner, ref, context);
  });
}

// ── Local-variable receiver-type inference (#1108) ──────────────────────────
//
// Instance calls through a local variable (`const lg = new Logger(); lg.log()`)
// only resolved in C++ before this — no other language could learn the
// receiver's type. Local variables are not indexed as nodes (node-explosion),
// so, like the C++ inferrer above, we read the enclosing function's source and
// match the receiver's declaration/initializer to recover its type. The type is
// then handed to resolveMethodOnType, which VALIDATES that the type actually
// declares the method, so a mis-inference produces NO edge — the safety net
// that lets the patterns below stay simple. C++ keeps its dedicated inferrer
// (header scan + `auto`); this covers every other language.

// Tokens a loose pattern might capture that are never a user-defined type.
const NON_TYPE_RECEIVER_TOKENS = new Set([
  'this', 'self', 'super', 'new', 'return', 'await', 'yield', 'typeof',
  'null', 'nil', 'None', 'true', 'false', 'True', 'False', 'undefined',
]);

/**
 * Normalize a captured type expression to a simple type name: drop generic
 * args and pointer/ref markers, take the last `.`/`::`-qualified segment, and
 * reject obvious non-types.
 */
export function normalizeInferredTypeName(raw: string): string | null {
  const cleaned = raw.replace(/<[^>]*>/g, '').replace(/[&*]/g, '').trim();
  const seg = cleaned.split(/[.:]+/).filter(Boolean).pop();
  if (!seg) return null;
  if (NON_TYPE_RECEIVER_TOKENS.has(seg)) return null;
  return seg;
}

/** The element type of an array type a TS annotation gave (`Item[]`, `Item []` → `Item`), or undefined. */
export function arrayElementType(type: string): string | undefined {
  return /^(.+?)\s*\[\s*\]$/.exec(type)?.[1];
}

/**
 * A Java / C# type's optional type arguments (one level of nesting) and array
 * ranks, as a regex source: `<L, R>`, `<string, List<int>>`, `[]`, `[,]`.
 */
const TYPE_ARGS = '(?:<[^;=(){}<>]*(?:<[^;=(){}<>]*>[^;=(){}<>]*)*>)?\\s*(?:\\[[\\s,]*\\]\\s*)*';

/**
 * A Swift constructor call's argument list that no member follows: closed on
 * the line (two levels of nested parentheses) with no `.`/`?.` after it, or
 * left open at the line's end — its arguments go on below.
 */
const SWIFT_UNCHAINED_CALL = '(?:\\((?:[^()]|\\((?:[^()]|\\([^()]*\\))*\\))*\\)(?!\\s*\\??\\.)|\\([^)]*$)';

/**
 * Per-language patterns that recover a local variable's (or typed parameter's)
 * type from its declaration/initializer. Each regex captures the type in group
 * 1; `r` is the already-escaped receiver name. Ordered most-specific first.
 * PascalCase is required in the capture where the language convention allows,
 * as a cheap false-positive guard on top of resolveMethodOnType's validation.
 */
/**
 * Compiled-pattern memo for the receiver-type pattern builders below. They
 * run for EVERY `receiver.method()` ref the matcher attempts, compiling 2–4
 * fresh RegExp objects per call — and receivers repeat massively (`self`
 * alone accounts for tens of thousands of refs on a Lua repo, measured 41µs
 * per methodCall miss on kong with compilation a large slice). The patterns
 * are a pure function of (language, receiver) and non-global (`.match()`
 * never touches lastIndex), so shared instances are behavior-identical.
 * FIFO-capped with no per-get mutation (the §7a.6 LRU-churn lesson): a hit
 * costs one Map lookup, overflow evicts oldest, and an evicted entry simply
 * recompiles exactly as every call did before this memo.
 */
const PATTERN_MEMO = new Map<string, RegExp[]>();
const PATTERN_MEMO_CAP = 8192;

/**
 * Per-context incremental receiver-scan states for inferLocalReceiverType
 * (see the memo comment there). Keyed (file, scopeStart, language, receiver);
 * entries are a few dozen bytes, count is bounded by distinct receiver uses
 * (same order as the context's other per-file caches). MUST drop whenever the
 * context's file caches drop — the states are derived from file lines — so
 * ReferenceResolver.clearCaches calls clearNameMatcherMemos alongside
 * clearImportResolverMemos.
 */
type InferScanState = { hi: number; ansIdx: number; ansType: string | null; ansRaw?: string };
const INFER_SCAN_STATES = new WeakMap<ResolutionContext, Map<string, InferScanState>>();

/** Awaited inference caches are scoped to the resolver's stable-source window.
 * Negative file eligibility avoids scanning ordinary receiver misses; call-site
 * keys distinguish shadowed bindings and sibling blocks. Both caches are bounded
 * and are invalidated with file/import caches on sync. */
type AwaitedType = { name: string | null; filePath: string };
type AwaitedFile = {
  code: string; ready: boolean; offsets: number[]; names: Set<string>;
  scopes: { start: number; end: number; parent: number }[];
  declarations: Map<string, { index: number; length: number }[]>;
};
const AWAITED_TYPE_MEMO = new WeakMap<ResolutionContext, Map<string, AwaitedType | null>>();
const AWAITED_FILES = new WeakMap<ResolutionContext, Map<string, AwaitedFile | null>>();

function getInferScanStates(context: ResolutionContext): Map<string, InferScanState> {
  let m = INFER_SCAN_STATES.get(context);
  if (!m) {
    m = new Map();
    INFER_SCAN_STATES.set(context, m);
  }
  return m;
}

